window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["中国人民银行"] = {"gerenzhufangdaikuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为支持城镇居民购买自用普通住房，规范个人住房贷款管理，维护借贷双方的合法权益，根据《中华人民共和国商业银行法》、《中华人民共和国担保法》和《贷款通则》，制订本办法。"},{"i":2,"n":"第二条","txt":"个人住房贷款(以下简称贷款)是指贷款人向借款人发放的用于购买自用普通住房的贷款。贷款人发放个人住房贷款时，借款人必须提供担保。借款人到期不能偿还贷款本息的，贷款人有权依法处理其抵押物或质物，或由保证人承担偿还本息的连带责任。"},{"i":3,"n":"第三条","txt":"本办法适用于经中国人民银行批准设立的商业银行和住房储蓄银行。"},{"i":4,"n":"第四条","txt":"贷款对象应是具有完全民事行为能力的自然人。"},{"i":5,"n":"第五条","txt":"借款人须同时具备以下条件： 一、具有城镇常住户口或有效居留身份； 二、有稳定的职业和收入，信用良好，有偿还贷款本息的能力； 三、具有购买住房的合同或协议； 四、不享受购房补贴的以不低于所购住房全部价款的30%作为购房的首期付款；享受购房补贴的以个人承担部分的30%作为购房的首期付款； 五、有贷款人认可的资产作为抵押或质押，或有足够代偿能力的单位或个人作为保证人； 六、贷款人规定的其他条件。"},{"i":6,"n":"第六条","txt":"借款人应向贷款人提供下列资料： 一、身份证件(指居民身份证、户口本和其他有效居留证件)； 二、有关借款人家庭稳定的经济收入的证明； 三、符合规定的购买住房合同意向书、协议或其他批准文件； 四、抵押物或质物清单、权属证明以及有处分权人同意抵押或质押的证明；有权部门出具的抵押物估价证明；保证人同意提供担保的书面文件和保证人资信证明； 五、申请住房公积金贷款的，需持有住房公积金管理部门出具的证明； 六、贷款人要求提供的其他文件或资料。"},{"i":7,"n":"第七条","txt":"借款人应直接向贷款人提出借款申请。贷款人自收到贷款申请及符合要求的资料之日起，应在三周内向借款人正式答复。贷款人审查同意后，按照《贷款通则》的有关规定，向借款人发放住房贷款。"},{"i":8,"n":"第八条","txt":"贷款人发放贷款的数额，不得大于房地产评估机构评估的拟购买住房的价值。"},{"i":9,"n":"第九条","txt":"申请使用住房公积金贷款购买住房的，在借款申请批准后，按借款合同约定的时间，由贷款人以转账方式将资金划转到售房单位在银行开立的账户。住房公积金贷款额度最高不得超过借款家庭成员退休年龄内所交纳住房公积金数额的2倍。"},{"i":10,"n":"第十条","txt":"贷款人应根据实际情况，合理确定贷款期限，但最长不得超过20年。"},{"i":11,"n":"第十一条","txt":"借款人应与贷款银行制定还本付息计划，贷款期限在1年以内(含1年)的，实行到期一次还本付息，利随本清；贷款期限在1年以上的，按月归还贷款本息。"},{"i":12,"n":"第十二条","txt":"用信贷资金发放的个人住房贷款利率按法定贷款利率(不含浮动)减档执行。即，贷款期限为1年期以下(含1年)的，执行半年以下(含半年)法定贷款利率；期限为1至3年(含3年)的，执行6个月至1年期(含1年)法定贷款利率；期限为3至5年(含5年)的，执行1至3年期(含3年)法定贷款利率；期限为5至10年(含10年)的，执行3至5年(含5年)法定贷款利率；期限为10年以上的，在3至5年(含5年)法定贷款利率基础上适当上浮，上浮幅度最高不得超过5%。"},{"i":13,"n":"第十三条","txt":"用住房公积金发放的个人住房贷款利率在3个月整存整取存款利率基础上加点执行。贷款期限为1年至3年(含3年)的，加1.8个百分点；期限为3至5年(含5年)的，加2.16个百分点；期限为5至10年(含10年)的，加2.34个百分点；期限为10至15年(含15年)的，加2.88个百分点；期限为15年至20年(含20年)的，加3.42个百分点。"},{"i":14,"n":"第十四条","txt":"个人住房贷款期限在1年以内(含1年)的，实行合同利率，遇法定利率调整，不分段计息；贷款期限在1年以上的，遇法定利率调整，于下年初开始，按相应利率档次执行新的利率规定。"},{"i":15,"n":"第十五条","txt":"贷款抵押物应当符合《中华人民共和国担保法》第三十四条的规定。《中华人民共和国担保法》第三十七条规定不得抵押的财产，不得用于贷款抵押。"},{"i":16,"n":"第十六条","txt":"借款人以所购自用住房作为贷款抵押物的，必须将住房价值全额用于贷款抵押。"},{"i":17,"n":"第十七条","txt":"以房地产作抵押的，抵押人和抵押权人应当签订书面抵押合同，并于放款前向县级以上地方人民政府规定的部门办理抵押登记手续。抵押合同的有关内容按照《中华人民共和国担保法》第三十九条的规定确定。"},{"i":18,"n":"第十八条","txt":"借款人对设定抵押的财产在抵押期内必须妥善保管，负有维修、保养、保证完好无损的责任，并随时接受贷款人的监督检查。对设定的抵押物，在抵押期届满之前，贷款人不得擅自处分。"},{"i":19,"n":"第十九条","txt":"抵押期间，未经贷款人同意，抵押人不得将抵押物再次抵押或出租、转让、变卖、馈赠。"},{"i":20,"n":"第二十条","txt":"抵押合同自抵押物登记之日起生效，至借款人还清全部贷款本息时终止。抵押合同终止后，当事人应按合同的约定，解除设定的抵押权。以房地产作为抵押物的，解除抵押权时，应到原登记部门办理抵押注销登记手续。"},{"i":21,"n":"第二十一条","txt":"采取质押方式的，出质人和质权人必须签订书面质押合同，《中华人民共和国担保法》规定需要办理登记的，应当办理登记手续。质押合同的有关内容，按照《中华人民共和国担保法》第六十五条的规定执行。生效日期按第七十六条至第七十九条的规定执行。质押合同至借款人还清全部贷款本息时终止。"},{"i":22,"n":"第二十二条","txt":"对设定的质物，在质押期届满之前，贷款人不得擅自处分。质押期间，质物如有损坏、遗失，贷款人应承担责任并负责赔偿。"},{"i":23,"n":"第二十三条","txt":"借款人不能足额提供抵押(质押)时，应有贷款人认可的第三方提供承担连带责任的保证。保证人是法人的，必须具有代为偿还全部贷款本息的能力，且在银行开立有存款账户。保证人为自然人的，必须有固定经济来源，具有足够代偿能力，并且在贷款银行存有一定数额的保证金。"},{"i":24,"n":"第二十四条","txt":"保证人与债权人应当以书面形式订立保证合同。保证人发生变更的，必须按照规定办理变更担保手续，未经贷款人认可，原保证合同不得撤销。"},{"i":25,"n":"第二十五条","txt":"以房产作为抵押的，借款人需在合同签订前办理房屋保险或委托贷款人代办有关保险手续。抵押期内，保险单由贷款人保管。"},{"i":26,"n":"第二十六条","txt":"抵押期内，借款人不得以任何理由中断或撤销保险；在保险期内，如发生保险责任范围以外的因借款人过错的毁损，由借款人负全部责任。"},{"i":27,"n":"第二十七条","txt":"借款合同需要变更的，必须经借贷双方协商同意，并依法签订变更协议。"},{"i":28,"n":"第二十八条","txt":"借款人死亡、宣告失踪或丧失民事行为能力，其财产合法继承人继续履行借款人所签订的借款合同。"},{"i":29,"n":"第二十九条","txt":"保证人失去担保资格和能力，或发生合并、分立或破产时，借款人应变更保证人并重新办理担保手续。"},{"i":30,"n":"第三十条","txt":"抵押人或出质人按合同规定偿还全部贷款本息后，抵押物或质物返还抵押人或出质人，借款合同终止。"},{"i":31,"n":"第三十一条","txt":"借款人在还款期限内死亡、失踪或丧失民事行为能力后无继承人或受遗赠人，或其法定继承人、受遗赠人拒绝履行借款合同的，贷款人有权依照《中华人民共和国担保法》的规定处分抵押物或质物。"},{"i":32,"n":"第三十二条","txt":"处分抵押物或质物，其价款不足以偿还贷款本息的，贷款人有权向债务人追偿；其价款超过应偿还部分，贷款人应退还抵押人或出质人。"},{"i":33,"n":"第三十三条","txt":"拍卖划拨的国有土地使用权所得的价款，在依法缴纳相当于应缴纳的土地使用权出让金的款项后，抵押权人有优先受偿权。"},{"i":34,"n":"第三十四条","txt":"借款合同发生纠纷时，借贷双方应及时协商解决，协商不成的，任何一方均可依法申请仲裁或向人民法院提起诉讼。"},{"i":35,"n":"第三十五条","txt":"借款人有下列情形之一的，贷款人按中国人民银行《贷款通则》的有关规定，对借款人追究违约责任： 一、借款人不按期归还贷款本息的； 二、借款人提供虚假文件或资料，已经或可能造成贷款损失的； 三、未经贷款人同意，借款人将设定抵押权或质押权财产或权益拆迁、出售、转让、赠与或重复抵押的； 四、借款人擅自改变贷款用途，挪用贷款的； 五、借款人拒绝或阻挠贷款人对贷款使用情况进行监督检查的； 六、借款人与其他法人或经济组织签订有损贷款人权益的合同或协议的； 七、保证人违反保证合同或丧失承担连带责任能力，抵押物因意外损毁不足以清偿贷款本息，质物明显减少影响贷款人实现质权，而借款人未按要求落实新保证或新抵押(质押)的。"},{"i":36,"n":"第三十六条","txt":"个人住房贷款不得用于购买豪华住房。城镇居民修房、自建住房贷款，参照本办法执行。"},{"i":37,"n":"第三十七条","txt":"贷款人可根据本办法制定实施细则，并报中国人民银行备案。"},{"i":38,"n":"第三十八条","txt":"本办法由中国人民银行负责解释和修改。"},{"i":39,"n":"第三十九条","txt":"本办法自公布之日起施行。与本办法相抵触的有关规定同时废止。"}],"gerenxinyongxinxijichushujukuguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为维护金融稳定，防范和降低商业银行的信用风险，促进个人信贷业务的发展，保障个人信用信息的安全和合法使用，根据《中华人民共和国中国人民银行法》等有关法律规定，制定本办法。"},{"i":2,"n":"第二条","txt":"中国人民银行负责组织商业银行建立个人信用信息基础数据库（以下简称个人信用数据库），并负责设立征信服务中心，承担个人信用数据库的日常运行和管理。"},{"i":3,"n":"第三条","txt":"个人信用数据库采集、整理、保存个人信用信息，为商业银行和个人提供信用报告查询服务，为货币政策制定、金融监管和法律、法规规定的其他用途提供有关信息服务。"},{"i":4,"n":"第四条","txt":"本办法所称个人信用信息包括个人基本信息、个人信贷交易信息以及反映个人信用状况的其他信息。 前款所称个人基本信息是指自然人身份识别信息、职业和居住地址等信息；个人信贷交易信息是指商业银行提供的自然人在个人贷款、贷记卡、准贷记卡、担保等信用活动中形成的交易记录；反映个人信用状况的其他信息是指除信贷交易信息之外的反映个人信用状况的相关信息。"},{"i":5,"n":"第五条","txt":"中国人民银行、商业银行及其工作人员应当为在工作中知悉的个人信用信息保密。"},{"i":6,"n":"第六条","txt":"商业银行应当遵守中国人民银行发布的个人信用数据库标准及其有关要求，准确、完整、及时地向个人信用数据库报送个人信用信息。"},{"i":7,"n":"第七条","txt":"商业银行不得向未经信贷征信主管部门批准建立或变相建立的个人信用信息基础数据库提供个人信用信息。"},{"i":8,"n":"第八条","txt":"征信服务中心应当建立完善的规章制度和采取先进的技术手段确保个人信用信息安全。"},{"i":9,"n":"第九条","txt":"征信服务中心根据生成信用报告的需要，对商业银行报送的个人信用信息进行客观整理、保存，不得擅自更改原始数据。"},{"i":10,"n":"第十条","txt":"征信服务中心认为有关商业银行报送的信息可疑时，应当按有关规定的程序及时向该商业银行发出复核通知。 商业银行应当在收到复核通知之日起5个工作日内给予答复。"},{"i":11,"n":"第十一条","txt":"商业银行发现其所报送的个人信用信息不准确时，应当及时报告征信服务中心，征信服务中心收到纠错报告应当立即进行更正。"},{"i":12,"n":"第十二条","txt":"商业银行办理下列业务，可以向个人信用数据库查询个人信用报告： （一）审核个人贷款申请的； （二）审核个人贷记卡、准贷记卡申请的； （三）审核个人作为担保人的； （四）对已发放的个人信贷进行贷后风险管理的； （五）受理法人或其他组织的贷款申请或其作为担保人，需要查询其法定代表人及出资人信用状况的。"},{"i":13,"n":"第十三条","txt":"除本办法第十二条第(四)项规定之外，商业银行查询个人信用报告时应当取得被查询人的书面授权。书面授权可以通过在贷款、贷记卡、准贷记卡以及担保申请书中增加相应条款取得。"},{"i":14,"n":"第十四条","txt":"商业银行应当制定贷后风险管理查询个人信用报告的内部授权制度和查询管理程序。"},{"i":15,"n":"第十五条","txt":"征信服务中心可以根据个人申请有偿提供其本人信用报告。 征信服务中心应当制定相应的处理程序，核实申请人身份。"},{"i":16,"n":"第十六条","txt":"个人认为本人信用报告中的信用信息存在错误(以下简称异议信息)时，可以通过所在地中国人民银行征信管理部门或直接向征信服务中心提出书面异议申请。 中国人民银行征信管理部门应当在收到异议申请的2个工作日内将异议申请转交征信服务中心。"},{"i":17,"n":"第十七条","txt":"征信服务中心应当在接到异议申请的2个工作日内进行内部核查。 征信服务中心发现异议信息是由于个人信用数据库信息处理过程造成的，应当立即进行更正，并检查个人信用数据库处理程序和操作规程存在的问题。"},{"i":18,"n":"第十八条","txt":"征信服务中心内部核查未发现个人信用数据库处理过程存在问题的，应当立即书面通知提供相关信息的商业银行进行核查。"},{"i":19,"n":"第十九条","txt":"商业银行应当在接到核查通知的10个工作日内向征信服务中心作出核查情况的书面答复。异议信息确实有误的，商业银行应当采取以下措施： （一）应当向征信服务中心报送更正信息； （二）检查个人信用信息报送的程序； （三）对后续报送的其他个人信用信息进行检查，发现错误的，应当重新报送。"},{"i":20,"n":"第二十条","txt":"征信服务中心收到商业银行重新报送的更正信息后，应当在2个工作日内对异议信息进行更正。 异议信息确实有误，但因技术原因暂时无法更正的，征信服务中心应当对该异议信息作特殊标注，以有别于其他异议信息。"},{"i":21,"n":"第二十一条","txt":"经过核查，无法确认异议信息存在错误的，征信服务中心不得按照异议申请人要求更改相关个人信用信息。"},{"i":22,"n":"第二十二条","txt":"征信服务中心应当在接受异议申请后15个工作日内，向异议申请人或转交异议申请的中国人民银行征信管理部门提供书面答复；异议信息得到更正的，征信服务中心同时提供更正后的信用报告。 异议信息确实有误，但因技术原因暂时无法更正异议信息的，征信服务中心应当在书面答复中予以说明，待异议信息更正后，提供更正后的信用报告。"},{"i":23,"n":"第二十三条","txt":"转交异议申请的中国人民银行征信管理部门应当自接到征信服务中心书面答复和更正后的信用报告之日起2个工作日内，向异议申请人转交。"},{"i":24,"n":"第二十四条","txt":"对于无法核实的异议信息，征信服务中心应当允许异议申请人对有关异议信息附注100字以内的个人声明。个人声明不得包含与异议信息无关的内容，异议申请人应当对个人声明的真实性负责。 征信服务中心应当妥善保存个人声明原始档案，并将个人声明载入异议人信用报告。"},{"i":25,"n":"第二十五条","txt":"征信服务中心应当对处于异议处理期的信息予以标注。"},{"i":26,"n":"第二十六条","txt":"商业银行应当根据中国人民银行的有关规定，制定相关信用信息报送、查询、使用、异议处理、安全管理等方面的内部管理制度和操作规程，并报中国人民银行备案。"},{"i":27,"n":"第二十七条","txt":"商业银行应当建立用户管理制度，明确管理员用户、数据上报用户和信息查询用户的职责及操作规程。 商业银行管理员用户、数据上报用户和查询用户不得互相兼职。"},{"i":28,"n":"第二十八条","txt":"商业银行管理员用户应当根据操作规程，为得到相关授权的人员创建相应用户。管理员用户不得直接查询个人信用信息。 管理员用户应当加强对同级查询用户、数据上报用户与下一级管理员用户的日常管理。查询用户工作人员调离，该用户应当立即予以停用。"},{"i":29,"n":"第二十九条","txt":"商业银行管理员用户、数据上报用户和查询用户须报中国人民银行征信管理部门和征信服务中心备案。 前款用户工作人员发生变动，商业银行应当在2个工作日内向中国人民银行征信管理部门和征信服务中心变更备案。"},{"i":30,"n":"第三十条","txt":"商业银行应当制定管理员用户和查询用户的口令控制制度，并定期检查口令控制执行情况。"},{"i":31,"n":"第三十一条","txt":"商业银行应当建立保证个人信用信息安全的管理制度，确保只有得到内部授权的人员才能接触个人信用报告，不得将个人信用报告用于本办法第十二条规定以外的其它用。"},{"i":32,"n":"第三十二条","txt":"征信服务中心应当制定信用信息采集、整理、保存、查询、异议处理、用户管理、安全管理等方面的管理制度和操作规程，明确岗位职责，完善内控制度，保障个人信用数据库的正常运行和个人信用信息的安全。"},{"i":33,"n":"第三十三条","txt":"征信服务中心及其工作人员不得违反法律、法规及本办法的规定，篡改、毁损、泄露或非法使用个人信用信息，不得与自然人、法人、其它组织恶意串通，提供虚假信用报告。"},{"i":34,"n":"第三十四条","txt":"征信服务中心应当建立个人信用数据库内部运行和外部访问的监控制度，监督个人信用数据库用户和商业银行用户的操作，防范对个人信用数据库的非法入侵。"},{"i":35,"n":"第三十五条","txt":"征信服务中心应当建立灾难备份系统，采取必要的安全保障措施，防止系统数据丢失。"},{"i":36,"n":"第三十六条","txt":"征信服务中心应当对商业银行的所有查询进行记录，并及时向商业银行反馈。"},{"i":37,"n":"第三十七条","txt":"商业银行应当经常对个人信用数据库的查询情况进行检查，确保所有查询符合本办法的规定，并定期向中国人民银行及征信服务中心报告查询检查结果。 征信服务中心应当定期核查商业银行对个人信用数据库的查询情况。"},{"i":38,"n":"第三十八条","txt":"商业银行未按照本办法规定建立相应管理制度及操作规程的，由中国人民银行责令改正，逾期不改正的，给予警告，并处以三万元罚款。"},{"i":39,"n":"第三十九条","txt":"商业银行有下列情形之一的，由中国人民银行责令改正，并处一万元以上三万元以下罚款；涉嫌犯罪的，依法移交司法机关处理： （一）违反本办法规定，未准确、完整、及时报送个人信用信息的； （二）违反本办法第七条规定的； （三）越权查询个人信用数据库的； （四）将查询结果用于本办法规定之外的其他目的的； （五）违反异议处理规定的； （六）违反本办法安全管理要求的。"},{"i":40,"n":"第四十条","txt":"商业银行有本办法第三十八条至第三十九条规定情形的，中国人民银行可以建议商业银行对直接负责的董事、高级管理人员和其他直接责任人员给予纪律处分；涉嫌犯罪的，依法移交司法机关处理。"},{"i":41,"n":"第四十一条","txt":"征信服务中心工作人员有下列情形之一的，由中国人民银行依法给予行政处分；涉嫌犯罪的，依法移交司法机关处理： （一）违反本办法规定，篡改、毁损、泄露或非法使用个人信用信息的； （二）与自然人、法人、其它组织恶意串通，提供虚假信用报告的。"},{"i":42,"n":"第四十二条","txt":"中国人民银行其他工作人员有违反本办法规定的行为，造成个人信用信息被泄露的，依法给予行政处分；涉嫌犯罪的，依法移交司法机关处理。"},{"i":43,"n":"第四十三条","txt":"本办法所称商业银行，是指在中华人民共和国境内设立的商业银行、城市信用合作社、农村信用合作社以及经国务院银行业监督管理机构批准的专门从事信贷业务的其他金融机构。"},{"i":44,"n":"第四十四条","txt":"本办法由中国人民银行负责解释。"},{"i":45,"n":"第四十五条","txt":"本办法自2005年10月1日起施行。"}],"gerenwaihuiguanlibanfa":[{"i":1,"n":"第一条","txt":"为便利个人外汇收支，简化业务手续，规范外汇管理，根据《中华人民共和国外汇管理条例》和《结汇、售汇及付汇管理规定》等相关法规，制定本办法。"},{"i":2,"n":"第二条","txt":"个人外汇业务按照交易主体区分境内与境外个人外汇业务，按照交易性质区分经常项目和资本项目个人外汇业务。按上述分类对个人外汇业务进行管理。"},{"i":3,"n":"第三条","txt":"经常项目项下的个人外汇业务按照可兑换原则管理，资本项目项下的个人外汇业务按照可兑换进程管理。"},{"i":4,"n":"第四条","txt":"国家外汇管理局及其分支机构（以下简称外汇局）按照本办法规定，对个人在境内及跨境外汇业务进行监督和管理。"},{"i":5,"n":"第五条","txt":"个人应当按照本办法规定办理有关外汇业务。银行应当按照本办法规定为个人办理外汇收付、结售汇及开立外汇账户等业务，对个人提交的有效身份证件及相关证明材料的真实性进行审核。汇款机构及外币兑换机构（含代兑点）按照本办法规定为个人办理个人外汇业务。"},{"i":6,"n":"第六条","txt":"银行应通过外汇局指定的管理信息系统办理个人购汇和结汇业务，真实、准确录入相关信息，并将办理个人业务的相关材料至少保存5年备查。"},{"i":7,"n":"第七条","txt":"银行和个人在办理个人外汇业务时，应当遵守本办法的相关规定，不得以分拆等方式逃避限额监管，也不得使用虚假商业单据或者凭证逃避真实性管理。"},{"i":8,"n":"第八条","txt":"个人跨境收支，应当按照国际收支统计申报的有关规定办理国际收支统计申报手续。"},{"i":9,"n":"第九条","txt":"对个人结汇和境内个人购汇实行年度总额管理。年度总额内的，凭本人有效身份证件在银行办理；超过年度总额的，经常项目项下凭本人有效身份证件和有交易额的相关证明等材料在银行办理，资本项目项下按照第三章有关规定办理。"},{"i":10,"n":"第十条","txt":"从事货物进出口的个人对外贸易经营者，在商务部门办理对外贸易经营权登记备案后，其贸易外汇资金的收支按照机构的外汇收支进行管理。"},{"i":11,"n":"第十一条","txt":"个人进行工商登记或者办理其他执业手续后，可以凭有关单证办理委托具有对外贸易经营权的企业代理进出口项下及旅游购物、边境小额贸易等项下外汇资金收付、划转及结汇。"},{"i":12,"n":"第十二条","txt":"境内个人外汇汇出境外用于经常项目支出，单笔或当日累计汇出在规定金额以下的，凭本人有效身份证件在银行办理；单笔或当日累计汇出在规定金额以上的，凭本人有效身份证件和有交易额的相关证明等材料在银行办理。"},{"i":13,"n":"第十三条","txt":"境外个人在境内取得的经常项目项下合法人民币收入，可以凭本人有效身份证件及相关证明材料在银行办理购汇及汇出。"},{"i":14,"n":"第十四条","txt":"境外个人未使用的境外汇入外汇，可以凭本人有效身份证件在银行办理原路汇回。"},{"i":15,"n":"第十五条","txt":"境外个人将原兑换未使用完的人民币兑回外币现钞时，小额兑换凭本人有效身份证件在银行或外币兑换机构办理;超过规定金额的，可以凭原兑换水单在银行办理。"},{"i":16,"n":"第十六条","txt":"境内个人对外直接投资符合有关规定的，经外汇局核准可以购汇或以自有外汇汇出，并应当办理境外投资外汇登记。"},{"i":17,"n":"第十七条","txt":"境内个人购买B股，进行境外权益类、固定收益类以及国家批准的其他金融投资，应当按相关规定通过具有相应业务资格的境内金融机构办理。"},{"i":18,"n":"第十八条","txt":"境内个人向境内保险经营机构支付外汇人寿保险项下保险费，可以购汇或以自有外汇支付。"},{"i":19,"n":"第十九条","txt":"境内个人在境外获得的合法资本项目收入经外汇局核准后可以结汇。"},{"i":20,"n":"第二十条","txt":"境内个人对外捐赠和财产转移需购付汇的，应当符合有关规定并经外汇局核准。"},{"i":21,"n":"第二十一条","txt":"境内个人向境外提供贷款、借用外债、提供对外担保和直接参与境外商品期货和金融衍生产品交易，应当符合有关规定并到外汇局办理相应登记手续。"},{"i":22,"n":"第二十二条","txt":"境外个人购买境内商品房，应当符合自用原则，其外汇资金的收支和汇兑应当符合相关外汇管理规定。境外个人出售境内商品房所得人民币，经外汇局核准可以购汇汇出。"},{"i":23,"n":"第二十三条","txt":"除国家另有规定外，境外个人不得购买境内权益类和固定收益类等金融产品。境外个人购买B股，应当按照国家有关规定办理。"},{"i":24,"n":"第二十四条","txt":"境外个人在境内的外汇存款应纳入存款金融机构短期外债余额管理。"},{"i":25,"n":"第二十五条","txt":"境外个人对境内机构提供贷款或担保，应当符合外债管理的有关规定。"},{"i":26,"n":"第二十六条","txt":"境外个人在境内的合法财产对外转移，应当按照个人财产对外转移的有关外汇管理规定办理。"},{"i":27,"n":"第二十七条","txt":"个人外汇账户按主体类别区分为境内个人外汇账户和境外个人外汇账户；按账户性质区分为外汇结算账户、资本项目账户及外汇储蓄账户。"},{"i":28,"n":"第二十八条","txt":"银行按照个人开户时提供的身份证件等证明材料确定账户主体类别，所开立的外汇账户应使用与本人有效身份证件记载一致的姓名。境内个人和境外个人外汇账户境内划转按跨境交易进行管理。"},{"i":29,"n":"第二十九条","txt":"个人进行工商登记或者办理其他执业手续后可以开立外汇结算账户。"},{"i":30,"n":"第三十条","txt":"境内个人从事外汇买卖等交易，应当通过依法取得相应业务资格的境内金融机构办理。"},{"i":31,"n":"第三十一条","txt":"境外个人在境内直接投资，经外汇局核准，可以开立外国投资者专用外汇账户。账户内资金经外汇局核准可以结汇。直接投资项目获得国家主管部门批准后，境外个人可以将外国投资者专用外汇账户内的外汇资金划入外商投资企业资本金账户。"},{"i":32,"n":"第三十二条","txt":"个人可以凭本人有效身份证件在银行开立外汇储蓄账户。外汇储蓄账户的收支范围为非经营性外汇收付、本人或与其直系亲属之间同一主体类别的外汇储蓄账户间的资金划转。境内个人和境外个人开立的外汇储蓄联名账户按境内个人外汇储蓄账户进行管理。"},{"i":33,"n":"第三十三条","txt":"个人携带外币现钞出入境，应当遵守国家有关管理规定。"},{"i":34,"n":"第三十四条","txt":"个人购汇提钞或从外汇储蓄账户中提钞，单笔或当日累计在有关规定允许携带外币现钞出境金额之下的，可以在银行直接办理；单笔或当日累计提钞超过上述金额的，凭本人有效身份证件、提钞用途证明等材料向当地外汇局事前报备。"},{"i":35,"n":"第三十五条","txt":"个人外币现钞存入外汇储蓄账户，单笔或当日累计在有关规定允许携带外币现钞入境免申报金额之下的，可以在银行直接办理；单笔或当日累计存钞超过上述金额的，凭本人有效身份证件、携带外币现钞入境申报单或本人原存款金融机构外币现钞提取单据在银行办理。"},{"i":36,"n":"第三十六条","txt":"银行应根据有关反洗钱规定对大额、可疑外汇交易进行记录、分析和报告。"},{"i":37,"n":"第三十七条","txt":"本办法下列用语的含义： （一）境内个人是指持有中华人民共和国居民身份证、军人身份证件、武装警察身份证件的中国公民。 （二）境外个人是指持护照、港澳居民来往内地通行证、台湾居民来往大陆通行证的外国公民（包括无国籍人）以及港澳台同胞。 （三）经常项目项下非经营性外汇是指除贸易外汇之外的其他经常项目外汇。"},{"i":38,"n":"第三十八条","txt":"个人旅行支票按照外币现钞有关规定办理；个人外币卡业务，按照外币卡管理的有关规定办理。"},{"i":39,"n":"第三十九条","txt":"对违反本办法规定的，由外汇局依据《中华人民共和国外汇管理条例》及其他相关规定予以处罚；构成犯罪的，依法移送司法机关追究刑事责任。"},{"i":40,"n":"第四十条","txt":"国家外汇管理局负责制定本办法相应的实施细则，确定年度总额、规定金额等。"},{"i":41,"n":"第四十一条","txt":"本办法由国家外汇管理局负责解释。"},{"i":42,"n":"第四十二条","txt":"本办法自2007年2月1日起施行。以前规定与本办法不一致的，按本办法执行。附件所列外汇管理规定自本办法施行之日起废止。 附：废止规定目录 废止规定目录 1.《关于居民、非居民个人大额外币现钞存取款有关问题的通知》（〔97〕汇管函字第123号） 2.《境内居民个人外汇管理暂行办法》（汇发〔1998〕11号） 3.《关于修改〈境内居民个人外汇管理暂行办法〉的通知》（汇发〔1999〕133号） 4.《关于修改〈关于境内居民个人因私用汇有关问题的通知〉和《关于印发〈境内居民个人外汇管理暂行办法〉的通知》（汇发〔1999〕305号） 5.《关于自费出境留学人员预交人民币保证金购付汇的通知》（汇发〔2000〕82号） 6.《关于境内居民个人外汇存款汇出和外汇存款账户更名有关问题的批复》（汇发〔2000〕291号） 7.《国家外汇管理局关于调整对境内居民个人自费出国（境）留学购付汇政策有关问题的通知"}],"zhongguorenminyinhangyewulingyushujuanquanguanlibaf54f80":[{"i":1,"n":"第一条","txt":"为规范中国人民银行业务领域数据的安全管理并促进开发利用，根据《中华人民共和国网络安全法》《中华人民共和国数据安全法》《中华人民共和国个人信息保护法》《中华人民共和国中国人民银行法》《网络数据安全管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内开展与中国人民银行业务领域数据相关的处理活动及其安全监督管理，适用本办法。其他有关主管部门有规定的，还应当依法遵守其规定。 本办法所称中国人民银行业务领域，指依据法律、行政法规，党中央、国务院决定，由中国人民银行承担监督和管理职责的业务领域。 本办法所称中国人民银行业务领域数据，指中国人民银行业务领域内产生和收集的不涉及国家秘密的网络数据（以下简称业务数据）。 本办法所称数据处理者，指金融机构以及经中国人民银行批准设立或者认定的其他机构。"},{"i":3,"n":"第三条","txt":"业务数据安全工作遵循“谁管业务，谁管业务数据，谁管数据安全”原则。中国人民银行对业务数据安全负指导监管责任。数据处理者应当履行数据安全保护义务，防范业务数据被篡改、破坏、泄露或者非法获取、非法利用等风险，保障国家安全、公共利益、个人及组织合法权益，尊重社会公德伦理，遵守商业道德和职业道德，保障业务数据依法有序自由流动。"},{"i":4,"n":"第四条","txt":"在国家数据安全工作协调机制统筹协调下，中国人民银行及其分支机构按照本办法开展业务数据安全监督管理工作，加强与其他有关主管部门间的数据安全监督管理协作配合、信息沟通。 相关金融行业协会应当加强自律管理，依法制定业务数据安全行为规范和团体标准，指导会员加强业务数据安全保护。"},{"i":5,"n":"第五条","txt":"鼓励数据处理者积极开展业务数据安全创新应用，在保障安全合规前提下促进业务数据的高效流通和开发利用，鼓励在行业内推广优秀创新成果。"},{"i":6,"n":"第六条","txt":"中国人民银行负责制定业务数据分类分级保护相关规范标准，指导业务数据分类分级保护工作，组织编制中国人民银行业务领域重要数据目录并实施动态管理。"},{"i":7,"n":"第七条","txt":"数据处理者应当建立健全业务数据分类分级制度和操作规程。业务数据分类分级实施应当遵循制度规程，分类分级结果应当履行内部审批程序。"},{"i":8,"n":"第八条","txt":"数据处理者应当建立业务数据资源目录，并从业务关联性、敏感性和可用性方面分别做好业务数据分类： （一）标识各数据项是否为个人信息、是否为外部收集产生、存储该数据项的信息系统清单和关联的业务类别。 （二）根据业务数据遭到泄露或者被非法获取、非法利用时，对个人、组织合法权益或者公共利益等造成的危害程度开展敏感性分类。业务数据的结构化数据项应当逐一标识敏感性，业务数据的非结构化数据项应当优先按照可拆分的各结构化数据项所标识的最高敏感性，标识其敏感性。中国人民银行业务领域内的敏感个人信息、可能涉及商业秘密的客户经营信息、应当严格控制知悉范围的业务信息等，应当标识为高敏感性数据项。 （三）根据业务数据遭到篡改、破坏后对业务正常运行造成的影响程度，明确信息系统差异化的数据恢复点目标，视为对业务数据的可用性分类。"},{"i":9,"n":"第九条","txt":"按照国家有关规定，将业务数据分为一般数据、重要数据、核心数据三级。重要数据是指特定领域、特定群体、特定区域或者达到一定精度和规模，一旦遭到篡改、破坏、泄露或者非法获取、非法利用，可能直接危害国家安全、经济运行、社会稳定、公共健康和安全的数据。核心数据是指对领域、群体、区域具有较高覆盖度或者达到较高精度、较大规模、一定深度，一旦被非法使用或者共享，可能直接影响政治安全的重要数据。 中国人民银行按照国家有关规定组织确定重要数据具体目录，数据处理者应当准确识别、申报本机构存储的全量业务数据是否属于重要数据、核心数据，并填报重要数据具体目录内容。 中国人民银行汇总形成重要数据具体目录，经国家数据安全工作协调机制审定后，确定重要数据的处理者并告知其对应的重要数据。 除单独说明的情形外，本办法所列重要数据的保护义务，均适用于核心数据。"},{"i":10,"n":"第十条","txt":"数据处理者应当每年至少更新一次业务数据资源目录，完整准确记录信息系统所存储数据项和对应标识内容。"},{"i":11,"n":"第十一条","txt":"数据处理者应当切实履行业务数据安全保护责任，明确业务数据安全保护相关内设部门职责，配备与业务范围和服务规模相适应的数据安全专业人员，细化业务数据安全保护奖惩规程。 面向社会提供产品、服务的数据处理者应当建立便捷的投诉、举报渠道，及时受理并处理业务数据安全有关投诉、举报。 重要数据的处理者应当明确业务数据的安全负责人和管理机构。管理机构应当切实履行法律、行政法规已明确的各项责任。业务数据的安全负责人应当符合法律、行政法规已明确需具备的条件，并确保其能够有效履行数据安全保护义务，有权直接向中国人民银行报告业务数据安全情况。"},{"i":12,"n":"第十二条","txt":"数据处理者应当建立健全全流程业务数据安全管理制度，结合业务数据分类分级明确差异化的安全保护措施，制定业务数据处理活动操作规程和业务数据安全相关内部审批授权规程，明确操作实施和审批授权记录的留存要求。 不同敏感性数据项在同一个业务数据处理活动中被处理，且难以采取差异化安全保护措施的，应当采取高敏感性数据项对应的安全保护措施。"},{"i":13,"n":"第十三条","txt":"数据处理者应当根据岗位分工，制定业务数据安全年度培训计划，每年组织业务数据处理活动参与人员开展相关教育培训。培训内容应当包括与业务数据安全相关的制度标准、风险防范常识、岗位责任、保护措施和事件应急处置要求。"},{"i":14,"n":"第十四条","txt":"数据处理者应当严格管理处理业务数据相关信息系统数据库管理员账号等特权账号和各类业务处理账号的权限，人员变动时应当立即调整权限。数据处理者应当与可使用高敏感性数据项账号的人员签订保密协议。 数据处理者存储核心数据的，应当对业务数据的安全负责人和可使用核心数据的关键岗位人员进行安全背景审查。"},{"i":15,"n":"第十五条","txt":"数据处理者收集业务数据应当采取下列安全保护管理措施： （一）除收集自行公开或者其他已经合法公开的业务数据的情形外，收集业务数据时应当依照法律、行政法规和中国人民银行相关规定取得个人同意或者组织授权，并落实相应告知义务。 （二）非直接面向个人、组织收集其尚未公开的业务数据的，应当在合同或者协议中明确数据提供方保障业务数据来源合法性、真实性的义务。数据提供方未取得个人书面同意或者组织书面授权的，还应当要求其出具业务数据来源依法合规和数据真实性的必要佐证材料。 （三）采用人工录入方式收集业务数据的，应当采取必要校验措施保障业务数据录入的准确性，按照相关管理要求留存业务数据收集原始凭证。 （四）原则上不收集图像等原始个人生物识别信息。确需收集的，应当统一规范管理相关需求场景。 （五）按照与数据提供方合同或者协议中约定的处理目的、方式、范围以及安全保护义务等开展收集和后续的业务数据处理活动。"},{"i":16,"n":"第十六条","txt":"数据处理者应当根据业务需要，明确业务数据保存期限。除履行法定职责或者法定义务外，高敏感性数据项原则上不在终端设备和移动介质中存储，确需存储的，数据处理者应当统一规范管理相关需求场景。"},{"i":17,"n":"第十七条","txt":"业务数据使用活动中，数据处理者使用高敏感性数据项，原则上不采取导出方式，使用用于身份鉴别的数据项原则上仅采取核验方式。确需采取导出方式使用高敏感性数据项或者采取其他方式使用用于身份鉴别的数据项的，数据处理者应当统一规范管理相关需求场景。 除根据个人请求向其展示与其相关业务数据，以及履行法定职责或者法定义务所需外，数据处理者原则上须实施脱敏处理后再展示高敏感性数据项。确需不脱敏展示的，数据处理者应当统一规范管理相关需求场景。"},{"i":18,"n":"第十八条","txt":"数据处理者应当审查业务数据加工目的与业务数据收集约定是否一致；需要训练业务数据的，应当审查训练业务数据的真实性、准确性、客观性、多样性；需要标注业务数据的，应当抽样审查标注的合理性与准确性；需要建立模型评价激励规则的，应当审查评价激励规则是否尊重社会公德伦理、遵守商业道德和职业道德。 业务数据加工活动中，数据处理者加工高敏感性数据项的，应当进一步明确应当采取的安全保护措施，并履行内部审批程序；基于加工生成的数据项面向个人提供自动化决策服务的，应当以适当方式向个人解释说明处理目的、用于加工的个人信息种类和加工规则。"},{"i":19,"n":"第十九条","txt":"对于业务数据加工活动产生新数据项，经评估其敏感性明显低于加工所使用数据项的，数据处理者可遵循规程降低其敏感性标识，促进依法合规开发利用。 对于业务数据加工活动产生新数据项，经评估其敏感性明显高于加工所使用数据项的，数据处理者应当提高其敏感性标识，并加强业务数据安全保护。"},{"i":20,"n":"第二十条","txt":"除根据个人请求向其传输与其相关业务数据外，数据处理者原则上不使用邮件、即时通讯、在线文件存储等互联网信息服务或者移动介质传输高敏感性数据项。确有需要的，数据处理者应当统一规范管理相关需求场景。"},{"i":21,"n":"第二十一条","txt":"从事业务所需的业务数据提供活动，数据处理者应当核验数据接收方身份，并采取下列安全保护管理措施： （一）对于涉及个人信息的业务数据提供活动，应当评估是否遵守法律、行政法规要求。对于其他业务数据提供活动，应当评估是否符合保守商业秘密的约定。 （二）向其他数据处理者提供业务数据涉及个人信息和重要数据的，应当在合同或者协议中明确各自的数据安全保护义务，需要采取的安全保护措施，数据提供的目的、方式、范围，数据允许存储时限，数据提供至第三方的限制和数据安全事件告知义务，并对数据接收方履行约定义务的情况进行监督。 （三）按照约定做好业务数据清洗转换，对提供数据的真实性作必要审查，不得误导数据接收方。 （四）除委托处理情形外，原则上不采取导出方式向其他数据处理者提供高敏感性数据项，用于身份鉴别的数据项原则上须采取核验方式提供。确需采取导出方式提供高敏感性数据项或者采取其他方式使用用于身份鉴别的数据项的"},{"i":22,"n":"第二十二条","txt":"数据处理者向其他数据处理者提供、委托处理、共同处理重要数据前，应当依照法律、行政法规和中国人民银行相关规定进行风险评估，并重点评估数据接收方数据处理目的和方式的合法正当性、数据项列表的需求合理性、数据活动的潜在安全风险、数据接收方诚信守法情况、合同或者协议内容的完备性、拟采取的安全保护措施等。 除履行法定职责或者法定义务外，数据处理者向其他数据处理者提供核心数据达到国家规定情形的，在提供业务数据之前应当经中国人民银行报国家数据安全工作协调机制开展风险评估。数据处理者不得通过拆分、转换等手段规避上述义务。 重要数据的处理者因合并、分立、解散、破产等可能影响重要数据安全的，应当依照法律、行政法规要求，事前向中国人民银行或者住所地中国人民银行省级分支机构报告重要数据处置方案，在方案中说明重要数据目录内容更新情况、数据接收方的名称或者姓名和联系方式等。"},{"i":23,"n":"第二十三条","txt":"数据处理者采用隐私计算等技术促进业务数据融合创新应用的，应当落实本办法第二十一条第一项至第三项要求，并确认除本机构外其他数据处理者无法使用未加密原始数据、与其他数据融合创新应用活动作关联分析无法泄露约定范围外的信息。"},{"i":24,"n":"第二十四条","txt":"数据处理者因业务等需要向中华人民共和国境外提供数据，存在国家网信部门规定情形的，应当严格遵守其有关规定；法律、行政法规和中国人民银行相关规定有境内存储要求的，业务数据还应当同时在中华人民共和国境内存储。 符合国家网信部门规定应当申报数据出境安全评估或者开展保护认证等情形的，数据处理者不得对业务数据采取拆分、转换等手段规避相关义务。"},{"i":25,"n":"第二十五条","txt":"中国人民银行根据有关法律和中华人民共和国缔结或者参加的国际条约、协定，或者按照平等互惠原则，处理外国金融执法机构关于提供业务数据的请求。"},{"i":26,"n":"第二十六条","txt":"数据处理者应当审核业务数据公开活动的目的、数据项列表、渠道、时限和脱敏处理情况，分析研判可能产生的不利影响，审查业务数据的合法性、真实性，并通过本机构明确的官方渠道公开业务数据。确需通过其他渠道公开的，应当明确采用的安全保护措施并履行内部审批程序。 业务数据处理活动中，数据处理者不得公开用于身份鉴别的数据项，公开其他高敏感性数据项原则上须作脱敏处理。确需不作脱敏处理的，数据处理者应当统一规范管理相关需求场景。"},{"i":27,"n":"第二十七条","txt":"数据处理者应当依照法律、行政法规和中国人民银行相关规定，主动删除处理目的已实现、处理目的无法实现、为实现处理目的不再必要或者约定保存期限已届满等情形的业务数据。 删除业务数据从技术上难以实现的，数据处理者应当停止除存储和采取必要的安全保护措施之外的业务数据处理活动，并每年至少实施一次审查，确认相关业务数据不可被使用。"},{"i":28,"n":"第二十八条","txt":"数据处理者委托处理业务数据，除落实本办法第二十一条第二项要求外，还应当在合同或者协议中明确受托人需报告的重要事项、委托处理事项完成后传输和删除业务数据的实施方式与时限要求、配合本机构监督其委托处理活动等义务，并采取定期评估等方式监督受托人履约情况。涉及核心数据的委托处理活动，数据处理者应当事前对受托人开展尽职调查，进一步加强对其的监督。 数据处理者应当将业务数据委托处理活动纳入业务或者信息科技外包管理体系，加强风险管理。 中国人民银行已明确要求不得以外包形式开展业务的，相关业务数据不得委托处理。"},{"i":29,"n":"第二十九条","txt":"数据处理者应当加强访问控制，采取有效技术措施管控业务数据处理账号的数据使用权限，明确特权账号的使用场景并加强使用时的内部审批授权。使用特权账号实施业务数据新增、删除、修改等人工操作时应当逐一开展事前审批和事后审查。使用特权账号开展自动化操作前应当对操作正确性和安全性进行必要检查。 数据处理者应当加强安全认证，保障业务数据处理账号和特权账号认证口令的强度，限制验证失败重试次数，可使用高敏感性数据项的账号应当支持多因素认证或者二次授权确认，并建立超时退出、访问通信地址变化等情形的重新验证机制。"},{"i":30,"n":"第三十条","txt":"数据处理者应当规范日志记录，明确业务数据处理活动日志记录信息，满足数据安全风险溯源和事件处置需要。 业务数据处理活动日志记录高敏感性数据项原则上须经脱敏处理。确需不脱敏处理的，数据处理者应当统一规范管理相关需求场景。 数据处理者应当将业务数据处理活动日志纳入业务数据分类分级管理，落实安全保护要求。 数据处理者应当留存业务数据处理活动日志至少六个月；对于与存储重要数据信息系统相关的业务数据处理活动日志，应当留存至少一年；对于与存储核心数据信息系统相关的业务数据处理活动日志，应当留存至少三年。 数据处理者向其他数据处理者提供、委托处理个人信息、重要数据的业务数据处理活动日志等记录，应当留存至少三年。"},{"i":31,"n":"第三十一条","txt":"数据处理者应当优先采用直接录入或者信息系统间交互的方式收集业务数据。采用直接录入方式收集业务数据的，应当验证录入人身份；采用信息系统间交互方式收集高敏感性数据项的，应当验证数据提供方身份。 数据处理者应当采取关联信息交叉核验等技术措施，尽可能保障收集业务数据的准确性。 数据处理者采用自动化工具方式从其他数据处理者收集业务数据的，应当遵守其数据收集的控制规则，不得干扰网络服务正常运行，不得侵害其他机构网络服务合法运营权益。"},{"i":32,"n":"第三十二条","txt":"数据处理者应当针对业务数据存储活动采取下列安全保护措施： （一）有效隔离信息系统开发测试环境与生产环境。 （二）存储重要数据的信息系统应当满足三级网络安全等级保护要求，存储核心数据的信息系统应当满足四级网络安全等级保护要求或者关键信息基础设施保护要求，并优先采购安全可信的网络产品和服务。 （三）原则上高敏感性数据项须加密存储，确需不加密存储的，数据处理者应当统一规范管理相关需求场景。中国人民银行对业务数据存储有使用商用密码保护特别规定的，按照其规定执行。 （四）及时评估并调整业务数据存储承载容量。对照信息系统数据恢复点目标，做好生产环境业务数据冗余备份，按照中国人民银行要求定期验证冗余备份业务数据的可用性。评估备份技术措施是否具备防范生产环境业务数据和冗余备份业务数据同时遭到篡改、破坏等风险的能力，并针对性加强安全保护措施。"},{"i":33,"n":"第三十三条","txt":"数据处理者应当明确高敏感性数据项的脱敏处理策略，切实降低脱敏业务数据仍可识别至特定个人、组织的风险。 数据处理者应当建立终端设备安全管控策略，明确安全防护措施要求。业务数据展示、打印时应当采取技术措施标识当前使用业务数据的业务处理账号和使用时间。 除开发测试环境与生产环境业务数据安全保护措施完全一致的情形外，生产环境数据项用于开发测试环境的，应当履行内部审批程序并实施脱敏处理。"},{"i":34,"n":"第三十四条","txt":"数据处理者应当建立业务数据加工算法风险评估和控制策略，明确可解释性、脆弱性等风险对应的防范或者缓释措施和停止使用加工算法开展自动化决策时的替代方案。"},{"i":35,"n":"第三十五条","txt":"数据处理者应当针对业务数据传输活动采取下列安全保护措施： （一）优先采取专用线路、虚拟专用网等技术加强业务数据传输安全保护。 （二）健全访问控制和安全隔离策略，加强相关终端设备准入控制。 （三）原则上高敏感性数据项须加密传输至其他数据处理者、其他数据中心或者互联网。确需不加密传输的，数据处理者应当统一规范管理相关需求场景。中国人民银行对业务数据传输有使用商用密码保护特别规定的，按照其规定执行。 （四）及时评估并调整通信线路的传输承载容量，加强通信线路和相关软硬件设备的冗余备份。"},{"i":36,"n":"第三十六条","txt":"数据处理者应当动态维护本机构提供业务数据的前置网关和应用程序接口清单，并在前置网关和应用程序接口变更投产前开展安全测试，发现风险隐患立即采取补救措施。 数据处理者采用隐私计算等技术提供业务数据的，应当建立技术风险评估和控制策略，明确安全不可验证、性能不可接受等风险的应对措施。"},{"i":37,"n":"第三十七条","txt":"数据处理者应当制定本机构公开的业务数据是否允许自动化工具收集的控制规则，并采取必要技术措施保障公开的业务数据不被篡改。"},{"i":38,"n":"第三十八条","txt":"数据处理者应当明确业务数据存储介质销毁策略，规范销毁实施方式和过程监督程序。"},{"i":39,"n":"第三十九条","txt":"数据处理者应当加强业务数据处理活动风险监测，有效识别下列风险并立即采取补救措施： （一）存在法律、行政法规禁止发布传输的信息。 （二）存在计算机病毒、木马、勒索等恶意程序，数据安全漏洞、认证口令强度偏低等缺陷。 （三）高敏感性数据项安全保护措施失效。 （四）异常的业务数据处理活动。 （五）业务数据传输或者存储承载能力不足。"},{"i":40,"n":"第四十条","txt":"数据处理者应当加强对业务数据泄露、业务数据被非法兜售、仿冒本机构身份处理业务数据，以及其他与本机构有关的业务数据安全负面舆情的风险监测，发现相关风险时应当立即核实处置。"},{"i":41,"n":"第四十一条","txt":"中国人民银行及其分支机构通报与业务数据相关的数据安全缺陷、漏洞等风险时，数据处理者应当立即核实处置，并根据通报要求按时准确反馈情况。 鼓励数据处理者向中国人民银行及其分支机构提供具有行业共享价值的业务数据安全风险情报。"},{"i":42,"n":"第四十二条","txt":"重要数据的处理者应当自行或者委托第三方评估机构，每年对业务数据开展一次风险评估，并于每年1月15日前向中国人民银行或者住所地中国人民银行省级分支机构报送上一年度风险评估报告。除法律、行政法规已明确应当评估的内容外，风险评估报告还应当包含与存储重要数据信息系统相关的人员培训与日常管理情况，与业务数据相关的岗位职责落实情况、网络安全等级保护测评和整改情况、保护措施执行情况、本年度风险监测和事件处置情况，以及中国人民银行要求的其他评估内容。"},{"i":43,"n":"第四十三条","txt":"数据处理者应当按照国家网络安全事件应急预案有关事件分级要求，综合考虑影响范围和程度，明确业务数据安全事件对应的分级标准： （一）业务数据被篡改、破坏事件分级的标准应当考虑信息系统数据恢复点目标、无法正常提供服务时长、受影响业务笔数和金额、受影响个人或者组织数量、损失的不同敏感性数据项和对应规模等因素。 （二）业务数据泄露事件分级的标准应当考虑受影响个人或者组织数量、泄露的不同敏感性数据项和对应规模等因素。 （三）涉及核心数据、重要数据泄露或者被篡改、破坏的安全事件，应当分别分级为特别重大事件、重大事件。"},{"i":44,"n":"第四十四条","txt":"数据处理者应当做好业务数据安全事件分级，发生业务数据安全事件时，应当立即采取处置措施，按照规定及时告知用户并按照中国人民银行要求及时、准确、完整报告事件情况。 数据接收方、委托处理受托人发生与数据处理者所提供业务数据相关的数据安全事件的，数据处理者应当开展调查评估，督促相关机构立即采取补救措施并向有关主管部门报告。 重要数据的处理者应当每年至少开展一次针对业务数据安全事件的应急演练，其他数据处理者应当每三年至少开展一次针对业务数据安全事件的应急演练。"},{"i":45,"n":"第四十五条","txt":"数据处理者应当对照法律、行政法规和本办法所列安全保护措施要求，以及本机构业务数据安全相关管理制度和操作规程的执行情况，每三年至少开展一次业务数据安全合规审计，重要数据的处理者应当每年至少开展一次与重要数据安全相关的合规审计。发生重大或者特别重大事件后，应当开展专项审计。审计应当重点关注业务数据资源目录是否及时更新、相关信息系统账号权限管理是否严密、业务数据处理活动相关合同或者协议是否完备、高敏感性数据项安全保护措施是否有效、数据委托处理受托人管理职责是否落实、前置网关和应用程序接口是否持续安全维护、数据安全风险监测是否有效、数据安全风险与事件处置是否及时、数据出境是否合规、数据安全投诉处理是否及时等情况。"},{"i":46,"n":"第四十六条","txt":"数据处理者应当加强风险评估人员和审计人员使用业务数据权限的管理，采取必要措施确保实施过程的业务数据安全。 与业务数据相关的风险评估报告和审计报告记录高敏感性数据项时应当进行脱敏处理。 数据处理者委托第三方评估机构、审计机构开展与业务数据相关的风险评估或者审计工作的，应当在合同或者协议中明确其数据安全保护义务和对应责任，指定本机构人员全程参与。涉及会计审计服务的，还应当按照国家网信部门和财政部门要求，进一步加强相关业务数据安全保护。"},{"i":47,"n":"第四十七条","txt":"中国人民银行及其分支机构发现数据处理者的业务数据处理活动存在较大安全风险时，可以对其进行约谈和要求其采取措施进行整改；发现影响或者可能影响国家安全的业务数据处理活动线索时，可以要求数据处理者按照国家有关规定进行国家安全审查。 中国人民银行及其分支机构按照职责可以对数据处理者与业务数据相关的数据安全保护义务落实情况开展执法检查，必要时可以与其他有关主管部门联合实施执法检查。"},{"i":48,"n":"第四十八条","txt":"中国人民银行及其分支机构发现数据处理者在业务数据处理活动中未履行数据出境安全评估或者保护认证等义务的，应当将相关案件信息移送同级网信部门，并配合其予以处理。"},{"i":49,"n":"第四十九条","txt":"数据处理者未履行本办法规定的数据安全保护义务，有下列情形之一的，中国人民银行及其分支机构依照《中华人民共和国数据安全法》第四十五条予以处罚： （一）未依照法律、行政法规对应规定，建立健全全流程业务数据安全管理制度的。 （二）未依照法律、行政法规对应规定，组织开展业务数据安全教育培训的。 （三）未依照法律、行政法规对应规定，采取相应的技术措施和其他必要措施，保障业务数据安全的。 （四）重要数据的处理者未明确业务数据安全负责人和管理机构的。 （五）未有效监测业务数据安全风险的。 （六）发现业务数据安全风险未立即采取补救措施的。 （七）发生业务数据安全事件未立即采取处置措施，未及时告知用户，或者未按照要求报告事件情况的。 （八）重要数据的处理者未每年对业务数据开展一次风险评估，或者未按照要求报送风险评估报告的。"},{"i":50,"n":"第五十条","txt":"中国人民银行及其分支机构发现数据处理者开展业务数据处理活动排除、限制竞争，或者损害个人、组织合法权益的，依照相关法律、行政法规予以处理，属于其他有关主管部门管理职责的，移送相关案件信息并配合其予以处理。"},{"i":51,"n":"第五十一条","txt":"中国人民银行及其分支机构发现数据处理者开展业务数据处理活动，涉嫌构成违反治安管理行为或者构成犯罪的，将相关案件信息移送同级公安机关、国家安全机关等有关主管部门，并配合其予以处理。"},{"i":52,"n":"第五十二条","txt":"数据处理者发生业务数据安全事件造成危害后果，如能证明本机构已按照规定采取数据安全保护措施，并立即采取补救措施的，应当对其从轻或者减轻行政处罚。 数据处理者积极提供数据安全风险情报，协助及时发现重大业务数据安全风险的，应当对其未履行数据安全保护义务但尚未造成危害后果的行为，从轻或者减轻行政处罚。"},{"i":53,"n":"第五十三条","txt":"中国人民银行及其分支机构工作人员在业务数据处理活动的安全监督管理过程中存在玩忽职守、滥用职权、徇私舞弊情形的，依法给予处分。"},{"i":54,"n":"第五十四条","txt":"术语定义： （一）数据项，是指描述网络数据结构最基本的、不可分割的单位。 （二）结构化数据项，是指具有预定义的抽象描述数据类型，通常为使用数据库二维逻辑表单一字段指代的数据项。 （三）非结构化数据项，是指不适宜用数据库二维逻辑表展现的数据项，如图像、视频、音频、文档文件等。 （四）终端设备，是指数据处理者在业务数据处理活动中所用的计算机终端、移动智能终端、音视频和多媒体设备、其他专用终端设备。 （五）导出方式，是指数据使用或者提供活动中，将原本具有严格访问权限控制和访问日志记录的业务数据，转换成未实施严格访问控制或者无访问日志记录的文档文件的操作方式。 （六）核验方式，是指业务数据使用或者提供活动中，经核实验证后，仅反馈与存储业务数据是否匹配的操作方式。 （七）统一规范管理，是指数据处理者在本机构制度或者操作规程中对不执行本办法所提原则性合规要求的情形予以集中列举，并说明保留此类情形的"},{"i":55,"n":"第五十五条","txt":"本办法由中国人民银行负责解释。"},{"i":56,"n":"第五十六条","txt":"本办法自2025年6月30日起施行。"}],"zhongguorenminyinhangyewulingyuwangluoanquanshijia7f70f3":[{"i":1,"n":"第一条","txt":"为规范中国人民银行业务领域网络安全事件报告管理，根据《中华人民共和国网络安全法》《中华人民共和国数据安全法》《中华人民共和国个人信息保护法》《中华人民共和国中国人民银行法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"金融从业机构在中华人民共和国境内发生中国人民银行业务领域网络安全事件时，应当按照本办法规定向中国人民银行或者住所地中国人民银行分支机构报告。非中国人民银行业务领域网络安全事件无须按照本办法规定报告。涉及国家秘密的，按照有关规定执行。"},{"i":3,"n":"第三条","txt":"本办法所称中国人民银行业务领域，指依据法律、行政法规，党中央、国务院决定，由中国人民银行承担监督和管理职责的业务领域。 本办法所称中国人民银行业务领域网络安全事件（以下简称网络安全事件），指由于人为原因、遭受网络攻击、存在漏洞隐患、软硬件缺陷或故障、不可抗力等因素，对本机构建设、运营、维护、管理的中国人民银行业务领域网络或者处理的中国人民银行业务领域数据造成危害的事件。"},{"i":4,"n":"第四条","txt":"国家有关部门和其他金融管理部门等对网络安全事件报告有规定的，金融从业机构还应当从其规定报告。涉及危害计算机信息系统等违法犯罪的网络安全事件，金融从业机构还应当及时向公安机关报案。 中国人民银行加强与国家有关部门和其他金融管理部门间的网络安全事件报告内容共享，按照国家有关部门规定向其通报网络安全事件，并根据其他金融管理部门需要向其通报网络安全事件。"},{"i":5,"n":"第五条","txt":"任何个人和组织有权向中国人民银行或其分支机构举报金融从业机构未按照本办法规定报告网络安全事件的行为。中国人民银行或其分支机构对举报人的相关信息予以保密。"},{"i":6,"n":"第六条","txt":"金融从业机构应当在本机构网络安全管理制度或者操作规程中明确网络安全事件分级标准（以下简称分级标准），将网络安全事件分为特别重大、重大、较大和一般四个等级。金融从业机构应当每年组织评估并视情更新分级标准。分级标准如有更新，应当报本机构主管网络安全的领导班子成员批准。 金融从业机构制定分级标准时，应当综合考虑网络安全事件对业务、用户等的影响程度。金融从业机构针对与货币存取款、支付交易、税款缴库、银行间市场交易密切相关的中国人民银行业务领域网络制定分级标准时，应当差异化考虑业务高峰时段和非业务高峰时段网络安全事件对业务处理的影响程度。 金融从业机构还应当结合中国人民银行业务领域数据安全管理相关规定，制定与中国人民银行业务领域数据遭到篡改、破坏、泄露相关的分级标准。 金融从业机构可以针对网络安全等级保护三级以上的中国人民银行业务领域网络，逐一细化制定专门适用的分级标准。"},{"i":7,"n":"第七条","txt":"符合下列情形之一的，应当分级为特别重大网络安全事件： （一）属于金融基础设施、直接服务5000万个以上自然人或者与货币存取款、支付交易、税款缴库、银行间市场交易密切相关的中国人民银行业务领域网络，主要功能在业务高峰时段出现两个以上省级行政区范围整体中断运行3小时以上或者单个省级行政区范围整体中断运行6小时以上的； （二）提供金融服务的中国人民银行业务领域网络，主要功能出现中断、超时报错等情形，导致业务无法正常开展，经合理测算或者估算，已实际影响1000万个以上自然人或者100万个以上法人和其他组织的； （三）中国人民银行业务领域核心数据遭到篡改、破坏、泄露的； （四）致使泄露1000万条以上敏感个人信息或者1亿条以上个人信息的； （五）网信部门、公安机关已明确应当分级为特别重大网络安全事件的； （六）中国人民银行或其上海总部、省级分行、计划单列市分行研判并书面告知金融从业机构，应当分级"},{"i":8,"n":"第八条","txt":"符合下列情形之一的，应当至少分级为重大网络安全事件： （一）属于金融基础设施、直接服务5000万个以上自然人或者与货币存取款、支付交易、税款缴库、银行间市场交易密切相关的中国人民银行业务领域网络，主要功能在业务高峰时段出现两个以上省级行政区范围整体中断运行1.5小时以上或者单个省级行政区范围整体中断运行3小时以上的； （二）提供金融服务的中国人民银行业务领域网络，主要功能出现中断、超时报错等情形，导致业务无法正常开展，经合理测算或者估算，已实际影响100万个以上自然人或者10万个以上法人和其他组织的； （三）中国人民银行业务领域重要数据遭到篡改、破坏、泄露的； （四）致使泄露100万条以上敏感个人信息或者1000万条以上个人信息的； （五）网信部门、公安机关已明确应当分级为重大网络安全事件的； （六）中国人民银行或其上海总部、省级分行、计划单列市分行研判并书面告知金融从业机构，应当分级"},{"i":9,"n":"第九条","txt":"符合下列情形之一的，应当至少分级为较大网络安全事件： （一）属于金融基础设施、直接服务5000万个以上自然人或者与货币存取款、支付交易、税款缴库、银行间市场交易密切相关的中国人民银行业务领域网络，主要功能在业务高峰时段出现两个以上省级行政区范围整体中断运行15分钟以上或者单个省级行政区范围整体中断运行30分钟以上的； （二）提供金融服务的中国人民银行业务领域网络，主要功能出现中断、超时报错等情形，导致业务无法正常开展，经合理测算或者估算，已实际影响10万个以上自然人或者5000个以上法人和其他组织的； （三）致使泄露500条以上征信信息、财产信息，或者致使泄露5万条以上个人信息的； （四）遭受勒索恶意程序攻击，已对中国人民银行业务领域网络或者中国人民银行业务领域数据造成危害后果的； （五）网信部门、公安机关已明确应当分级为较大网络安全事件的。"},{"i":10,"n":"第十条","txt":"符合下列情形之一的，应当至少分级为一般网络安全事件： （一）提供金融服务的中国人民银行业务领域网络，主要功能出现单个省级行政区范围整体中断运行30分钟以上的； （二）提供金融服务的中国人民银行业务领域网络，主要功能出现中断、超时报错等情形，导致业务无法正常开展，经合理测算或者估算，已实际影响1万个以上自然人或者1000个以上法人和其他组织的； （三）中国人民银行业务领域网络主要功能出现中断、超时报错等情形，导致业务无法正常开展，已持续1小时以上的； （四）中国人民银行业务领域数据遭到篡改、破坏、泄露，导致社会危害的； （五）发生或者可能发生个人信息泄露、篡改、丢失的； （六）网信部门、公安机关已明确应当分级为一般网络安全事件的。"},{"i":11,"n":"第十一条","txt":"金融从业机构制定与中国人民银行管理的金融基础设施业务交互功能异常相关的分级标准时，应当征求金融基础设施运营机构意见并协商一致。"},{"i":12,"n":"第十二条","txt":"金融从业机构发生网络安全事件时，应当对照分级标准，综合确定网络安全事件等级。同时符合多个分级标准的，应当按照最高级别确定网络安全事件等级。对照分级标准无法准确确定网络安全事件等级的，应当至少分级为较大网络安全事件。 因灾害或者信息基础设施故障，导致金融从业机构多个中国人民银行业务领域网络同时发生网络安全事件时，应当先分别确定网络安全事件等级，再按照各网络安全事件等级中的最高级别，确定整体的网络安全事件等级。 网络安全事件事态发展情况已达到更高级别分级标准时，金融从业机构应当立即调整网络安全事件等级。"},{"i":13,"n":"第十三条","txt":"金融从业机构应当明确应急处置与报告的职责分工，确保网络安全事件报告及时、准确、完整，不得迟报、漏报或者瞒报。 金融从业机构应当健全网络安全风险监测预警体系，提升第一时间发现和报告网络安全事件的技术能力。 金融从业机构发生网络安全事件时，应当立即启动应急预案，采取相应的补救措施。按照本办法规定报告网络安全事件时，不应迟滞业务恢复、存证溯源、用户解释、舆情应对等处置工作。"},{"i":14,"n":"第十四条","txt":"国家开发银行、政策性银行、国有商业银行、中国邮政储蓄银行、股份制商业银行、属于系统重要性金融机构的城市商业银行、系统重要性非银行支付机构、经营个人征信业务的征信机构发生网络安全事件时，应当向中国人民银行报告；其分支机构发生网络安全事件时，应当向住所地中国人民银行分支机构报告。中国人民银行所属单位及其管理的金融基础设施运营机构发生网络安全事件时，应当向中国人民银行报告。其他金融从业机构或其分支机构发生网络安全事件时，应当向住所地中国人民银行分支机构报告；在保障报告时效性前提下，证券、期货、基金机构发生网络安全事件时，经中国证监会派出机构转通报同级中国人民银行分支机构。 中国人民银行计划单列市分行（不含深圳市分行）、地市分行接报辖区发生较大等级以上网络安全事件时，应当及时上报至中国人民银行省级分行。中国人民银行省级分行、深圳市分行接报辖区发生重大等级以上网络安全事件时，应当及时上报至中国人"},{"i":15,"n":"第十五条","txt":"金融从业机构发生较大等级以上网络安全事件后，应当于1小时内报送网络安全事件事发简要报告，并在24小时内报送网络安全事件事发报告。 金融从业机构发生网络安全事件，尚未达到较大等级，但出现相关舆情信息进入社交媒体、搜索引擎或者新闻网站热点榜等情形，引发较大舆情的，应当按照前款规定报告。"},{"i":16,"n":"第十六条","txt":"对于重大等级以上网络安全事件，金融从业机构应当至少每隔2小时进行事中进展报告，直至处置结束。处置过程中如出现调高网络安全事件等级、处置取得阶段性进展、发现新的问题等重要情况时，应当立即报告。"},{"i":17,"n":"第十七条","txt":"网络安全事件处置结束后，金融从业机构应当于10个工作日内报送事后调查总结报告。无法按时报送事后调查总结报告的，金融从业机构应当先按时报送初步报告，说明承诺报送事后调查总结报告的日期并按时报送。承诺日期原则上应当在处置结束之日起40个工作日内。"},{"i":18,"n":"第十八条","txt":"金融从业机构可以通过电话、即时通信工具、电子邮件、传真或者中国人民银行指定的信息系统报送网络安全事件事发简要报告、事发报告和事中进展报告；采用电子邮件、传真方式报告的，应当通过电话或者即时通信工具确认中国人民银行或其分支机构已收悉。涉及工作秘密的，不得通过互联网渠道报告。 金融从业机构应当书面报送网络安全事件事后调查总结报告，并加盖本机构或者承担报告职责内设部门公章。中国人民银行对网络安全事件事后调查总结报告另有电子化报送规定的，金融从业机构还应当按照规定电子化报送。"},{"i":19,"n":"第十九条","txt":"网络安全事件事发简要报告内容包括初次确定的网络安全事件等级、事发时间、依据网络安全事件分类分级相关国家标准确定的网络安全事件分类、影响的中国人民银行业务领域网络及其对应的网络安全保护等级、涉及的数据中心、报告机构和报告时间、报告人和联系方式。网络安全事件事发报告应当在事发简要报告内容基础上，增补影响范围和程度、已采取的措施和效果，网络攻击事件还应当增补分析研判情况。 网络安全事件事中进展报告应当在事发简要报告基础上，增补说明最新确定的网络安全事件等级、影响的变化、处置进展和下一步拟采取的措施。如存在需中国人民银行或其分支机构协调支持处置的事项，应当一并说明。 网络安全事件事后调查总结报告内容应当包括最终确定的网络安全事件等级、处置历程回顾、影响损失评估、技术或者管理问题根源分析、处置经验教训、后续改进措施、报告机构和报告时间、报告人和联系方式、签发人。"},{"i":20,"n":"第二十条","txt":"金融从业机构发生网络安全事件涉及个人信息泄露、篡改、丢失的，事后调查总结报告还应当说明本机构为有效避免网络安全事件危害所采取的补救措施、依法通知个人的情况和告知个人可以采取减轻危害措施的情况。 对于重大等级以上网络安全事件，前款所列内容应当在事中进展报告中提前予以说明。"},{"i":21,"n":"第二十一条","txt":"较大等级以上网络安全事件事后调查总结报告内容，还应当包括直接负责的主管人员和其他直接责任人员的责任认定和对应责任处理情况。 金融从业机构应当综合考虑动机态度、客观条件、程序方法、后果影响、挽回损失等因素，在本机构网络安全管理制度中明确责任处理的差异化适用情形。事后调查总结报告中对直接负责的主管人员和其他直接责任人员的处理措施，应当符合本机构网络安全管理制度规定。"},{"i":22,"n":"第二十二条","txt":"满足下列条件之一并且能提供相关证明材料的，金融从业机构可以根据直接负责的主管人员和其他直接责任人员具体承担职责，视情针对性减轻或者免除责任处理，但应当在网络安全事件事后调查总结报告中予以说明： （一）已按本办法规定主动报告，同时按照本机构网络安全事件应急预案有关程序立即进行处置，尽最大努力降低影响的； （二）网络技术创新和应用过程中因缺乏经验、先行先试造成网络安全事件，且没有主观过错的； （三）已切实落实中国人民银行和本机构网络安全、数据安全相关管理制度要求，并严格执行本机构相关操作规程的。"},{"i":23,"n":"第二十三条","txt":"中国人民银行或其分支机构认为金融从业机构网络安全事件事后调查总结报告存在内容缺失、原因分析不清、影响损失评估失实、责任认定或者处理不当等情形，退回事后调查总结报告并正式反馈修改意见的，金融从业机构应当在收到反馈之日起10个工作日内完善事后调查总结报告并重新报送。"},{"i":24,"n":"第二十四条","txt":"金融从业机构收到中国人民银行或其分支机构通报的其网络产品、服务存在运行异常、疑似数据泄露、安全缺陷、漏洞等风险提示时，应当立即组织核查，采取必要补救措施。经核查风险属实并构成网络安全事件的，金融从业机构应当按照本办法规定进行报告；风险不属实或者尚不构成网络安全事件的，应当根据通报要求按时反馈风险核查处置情况。"},{"i":25,"n":"第二十五条","txt":"金融从业机构应当建立网络安全事件台账，完整准确记录网络安全事件事发时间、事发报告时间、中国人民银行或其分支机构接报联系人和对应的网络安全事件报告内容。中国人民银行分支机构应当相应建立辖区网络安全事件台账。台账应当至少留存三年。"},{"i":26,"n":"第二十六条","txt":"中国人民银行或其分支机构根据金融从业机构报告处置网络安全事件的情况，可以按照中国人民银行执法检查有关规定明确的程序，对金融从业机构依法实施检查，金融从业机构应当予以配合。 金融从业机构拒绝、阻碍中国人民银行或其分支机构实施检查的，中国人民银行或其分支机构依照《中华人民共和国网络安全法》第六十九条予以处罚。"},{"i":27,"n":"第二十七条","txt":"金融从业机构未按照本办法规定报告网络安全事件的，中国人民银行或其分支机构依照《中华人民共和国网络安全法》第五十九条予以处罚。 前款行为涉及中国人民银行业务领域数据遭到篡改、破坏、泄露或者非法获取、非法利用的，中国人民银行或其分支机构依照《中华人民共和国数据安全法》第四十五条予以处罚；前款行为涉及个人信息泄露、篡改、丢失的，中国人民银行或其分支机构可以依照《中华人民共和国个人信息保护法》第六十六条予以处罚。"},{"i":28,"n":"第二十八条","txt":"金融从业机构收到中国人民银行或其分支机构通报的风险，如果风险属实，但未立即采取补救措施或者未按照本办法规定按时反馈核查处置情况的，中国人民银行或其分支机构依照《中华人民共和国网络安全法》第六十条予以处罚。 有前款行为并且通报的风险为数据安全缺陷、漏洞的，中国人民银行或其分支机构依照《中华人民共和国数据安全法》第四十五条予以处罚。"},{"i":29,"n":"第二十九条","txt":"金融从业机构在接受中国人民银行或其分支机构检查时，主动供述检查人员尚未掌握的未按照本办法规定报告网络安全事件行为的，应当从轻或者减轻处罚。"},{"i":30,"n":"第三十条","txt":"中国人民银行分支机构未按照本办法规定报告网络安全事件，存在失职失责行为，造成重大损失、严重后果或者恶劣影响的，对直接负责的主管人员和其他直接责任人员依规依纪依法予以严肃追责问责。"},{"i":31,"n":"第三十一条","txt":"本办法下列用语的含义： （一）金融从业机构，是指金融机构以及经中国人民银行批准设立或者认定的其他机构。 （二）网络，是指由计算机或者其他信息终端及相关设备组成的按照一定的规则和程序对信息进行收集、存储、传输、交换、处理的系统。 （三）业务高峰时段，是指按年度统计的分时平均业务量超过日平均业务量百分之三的时段，或者依据本机构制度列明的其他合理计算方式确定的时段。 （四）整体中断运行，是指因网络安全事件，某一时段内未处理和处理失败业务量与正常情况全部业务量的比例，经合理测算或者估算，已经超过百分之七十。 （五）主要功能，是指与用户身份认证或者业务交互相关的功能。 （六）本办法所称“以上”均含本数。"},{"i":32,"n":"第三十二条","txt":"本办法由中国人民银行负责解释。 中国人民银行分支机构自身发生的网络安全事件应当向其上级行报告，报告时效、途径和内容等要求按照本办法对金融从业机构的规定执行。"},{"i":33,"n":"第三十三条","txt":"本办法自2025年8月1日起施行。《银行计算机安全事件报告管理制度》（银发〔2002〕280号文印发）、《中国人民银行计算机系统信息安全报告制度》（银发〔2010〕366号文印发）同时废止。"}],"zhongguorenminyinhangling":[],"zhongguorenminyinhangguanyuquxiaoqiyeyinhangzhangh3f3423":[],"zhongguorenminyinhangzhifajianchachengxuguiding":[{"i":1,"n":"第一条","txt":"为促进中国人民银行及其分支机构依法履行职责，严格规范公正文明执法，保护被检查人合法权益，根据《中华人民共和国中国人民银行法》《中华人民共和国商业银行法》《中华人民共和国行政处罚法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"中国人民银行及其分支机构依法履行职责，对被检查人进行执法检查的，适用本规定。 本规定所称被检查人，是指根据法律、行政法规、国务院决定和中国人民银行规章规定，中国人民银行及其分支机构有监督管理权限的法人、非法人组织和自然人。"},{"i":3,"n":"第三条","txt":"本规定所称执法检查，是指中国人民银行及其分支机构根据履行职责需要，通过进入被检查人现场、查阅相关材料、询问相关人员、访问计算机信息系统等方式，监督被检查人执行有关金融管理规定情况的行政执法活动。"},{"i":4,"n":"第四条","txt":"中国人民银行及其分支机构开展执法检查，应当遵循合法、公开、公平、公正、合理、效率的原则，加大关系群众切身利益的重点领域执法力度，不断提升执法效能。"},{"i":5,"n":"第五条","txt":"中国人民银行及其分支机构开展执法检查，可以采取非现场检查、现场检查或者两者相结合的方式。"},{"i":6,"n":"第六条","txt":"中国人民银行及其分支机构根据“分级负责”原则，按照法律、行政法规、国务院决定、中国人民银行规章和有关规定，对本单位负责监管的被检查人和发生在本辖区的违法违规行为开展执法检查。 中国人民银行统筹、指导、协调全系统执法检查工作，根据需要，可以对分支机构负责监管的被检查人开展执法检查，或者委托特定分支机构以中国人民银行的名义开展执法检查。"},{"i":7,"n":"第七条","txt":"中国人民银行可以授权特定分支机构对部分业务类型或者部分被检查人开展执法检查。"},{"i":8,"n":"第八条","txt":"中国人民银行及其分支机构应当配备与执法检查需求相适应的检查力量，建立完善检查人员库。 本规定所称检查人员，是指承担行政执法工作职责、掌握相关法律和业务知识、具备执法检查工作能力，按照规定取得《中国人民银行执法证》的中国人民银行及其分支机构正式工作人员。"},{"i":9,"n":"第九条","txt":"中国人民银行及其分支机构根据执法检查工作需要，可以聘请注册会计师、资产评估人员、律师等专业人员，以及数据分析、信息技术等领域技术人员作为辅助人员协助执法检查，或者邀请上述人员出具专业意见。"},{"i":10,"n":"第十条","txt":"中国人民银行及其分支机构的工作人员、参与执法检查的辅助人员对执法检查中知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息应当依法予以保密，不得违反规定对外提供；中国人民银行及其分支机构可以要求上述人员签署保密协议。 执法检查结果公布之前，被检查人及其工作人员对执法检查情况负有保密义务，不得泄露与执法检查有关的信息。 除法律、行政法规或者中国人民银行规章另有规定外，中国人民银行及其分支机构在执法检查过程中形成的案卷信息不予公开。被检查人及其代理人可以按照规定申请查阅证据材料等相关案卷信息。"},{"i":11,"n":"第十一条","txt":"中国人民银行及其分支机构应当加强与其他监管部门的沟通协调，依法共享检查信息，必要时可以与其他监管部门联合组织现场检查。"},{"i":12,"n":"第十二条","txt":"中国人民银行及其分支机构按照相关财务管理规定对执法检查工作给予经费保障。"},{"i":13,"n":"第十三条","txt":"中国人民银行及其分支机构可以对被检查人的相关活动以及其风险状况进行非现场检查，充分运用互联网、大数据等技术手段，依托国家统一建立的在线监管系统，建立完善监管信息系统，加强监管信息归集共享和关联整合，分析、评价被检查人的风险状况，及时发现被检查人的违法违规行为。"},{"i":14,"n":"第十四条","txt":"中国人民银行及其分支机构可以要求被检查人通过业务管理系统、监管信息系统等信息化系统提供监管所需的信息，并通过对相关信息的汇总、分析了解被检查人的业务开展情况、风险状况等。"},{"i":15,"n":"第十五条","txt":"中国人民银行及其分支机构在日常监管中，或者通过业务管理系统、监管信息系统等信息化系统发现被检查人可能存在违法违规行为的，可以采取线上检查的方式直接通过信息化系统对相关情况进行进一步核实。 线上检查应当由两名以上检查人员实施。检查人员应当全面、客观、完整地记录检查工作情况，并制作执法检查工作底稿。"},{"i":16,"n":"第十六条","txt":"中国人民银行或其分支机构发现被检查人存在违法违规行为问题线索的，可以向被检查人发出函询通知书，要求其限期说明情况，提供相关信息、电子数据、文件和资料等。 被检查人应当书面答复中国人民银行或其分支机构的函询，并按照中国人民银行或其分支机构指定的方式、规定的时间，如实、完整提供相关信息、电子数据、文件和资料等。"},{"i":17,"n":"第十七条","txt":"中国人民银行及其分支机构开展线上检查、函询等非现场检查的，应当立项。"},{"i":18,"n":"第十八条","txt":"中国人民银行及其分支机构根据执法检查计划、日常监管中发现的问题、非现场检查情况以及其他履行职责的需要，组织实施现场检查。"},{"i":19,"n":"第十九条","txt":"中国人民银行于每年年初统筹制定中国人民银行系统年度执法检查计划，确定本年度拟开展的执法检查项目。"},{"i":20,"n":"第二十条","txt":"中国人民银行副省级城市中心支行以上分支机构根据中国人民银行制定的执法检查计划和本辖区履行职责的需要，对本辖区的执法检查工作作出统一部署。"},{"i":21,"n":"第二十一条","txt":"中国人民银行及其分支机构制定执法检查计划时，应当将防范金融风险与随机抽查相结合，充分利用非现场检查结果和日常监管信息，确定被检查人。"},{"i":22,"n":"第二十二条","txt":"中国人民银行及其分支机构根据日常监管工作的需要、突发风险事件等拟对被检查人开展现场检查的，应当立项、制定检查方案，经法制审核后，报本单位行长或者副行长（主任或者副主任）批准后实施。 已经列入执法检查计划的现场检查项目可以不再立项，在制定检查方案，经法制审核后，报本单位行长或者副行长（主任或者副主任）批准后实施。"},{"i":23,"n":"第二十三条","txt":"中国人民银行及其分支机构应当根据检查方案组成检查组，检查组的组成人员不得少于两人，原则上从本单位检查人员库中随机抽取。 检查组的组成人员与被检查人存在利害关系或者有其他关系可能影响公正执法的，应当回避。"},{"i":24,"n":"第二十四条","txt":"根据现场检查的需要，检查组可以组织检查人员进行法律、业务知识培训和纪律教育。"},{"i":25,"n":"第二十五条","txt":"检查组应当在实施现场检查前，向被检查人送达执法检查通知书，告知现场检查的依据、内容、检查期限范围、检查开展时间、要求、检查组成员名单等事项；因特殊情况需要立即实施现场检查的，检查组应当在进入被检查人现场时送达执法检查通知书。"},{"i":26,"n":"第二十六条","txt":"检查组在实施现场检查前，可以书面通知被检查人提供与现场检查相关的信息、电子数据、文件和资料等，被检查人应当配合，并按照检查组指定的方式、规定的时间，如实、完整提供。"},{"i":27,"n":"第二十七条","txt":"中国人民银行分支机构对管辖权存在争议的案件，应当逐级报请共同上级行指定管辖，或者由共同上级行直接指定管辖。 对重大、特殊案件，中国人民银行可以指定中国人民银行分支机构开展现场检查，或者自行开展现场检查。 作出指定管辖决定的中国人民银行或其分支机构应当出具指定管辖通知书。"},{"i":28,"n":"第二十八条","txt":"检查组实施现场检查时，检查人员应当向被检查人出示《中国人民银行执法证》，自觉接受监督。"},{"i":29,"n":"第二十九条","txt":"检查组实施现场检查的，应当与被检查人进行进场会谈，说明检查的目的、内容、工作安排和要求；充分听取被检查人的业务情况报告和其他有关情况报告。 检查组实施现场检查前，应当告知被检查人享有的权利和配合检查的义务，并由被检查人签字、盖章确认。"},{"i":30,"n":"第三十条","txt":"检查组在现场检查中需要查阅被检查人的工作制度、业务凭证、会计账目、财务报表等资料的，应当填写执法检查调阅资料清单，并由专人负责接收和退还调阅资料。"},{"i":31,"n":"第三十一条","txt":"检查组可以采取抽样检查的方式核实有关情况。 检查组在实施抽样检查前，应当书面告知被检查人拟采取抽样检查方式的检查项目、抽样方式、拟抽取的最低样本数量或者比例等信息；被检查人有异议的，应当在抽样检查实施前向检查组书面提出。"},{"i":32,"n":"第三十二条","txt":"检查组应当全面、客观、完整地记录检查工作的情况，并制作执法检查工作底稿。"},{"i":33,"n":"第三十三条","txt":"检查组可以根据检查工作的实际需要，变更下列事项，并书面告知被检查人： （一）执法检查通知书载明检查期限范围可以追溯或者顺延的，调整检查期限范围； （二）执法检查通知书载明可以对被检查人的分支机构、营业网点开展检查的，增加、变更被检查人的分支机构、营业网点； （三）增加、变更检查人员； （四）变更检查开展时间。"},{"i":34,"n":"第三十四条","txt":"现场检查过程中，为进一步查明相关事实，检查组可以向被检查人以外的其他法人、非法人组织和自然人调查情况。 相关法人、非法人组织和自然人不在本地的，检查组经本单位行长或者副行长（主任或者副主任）批准，可以请求其所在地中国人民银行分支机构协助调查。"},{"i":35,"n":"第三十五条","txt":"中国人民银行及其分支机构为核实较为明确的特定违法违规线索、了解特定情况，可以适用简易现场检查程序对被检查人开展执法检查。 中国人民银行及其分支机构适用简易现场检查程序的，应当立项、制作执法检查通知书，经法制审核后，报本单位行长或者副行长（主任或者副主任）批准后实施。"},{"i":36,"n":"第三十六条","txt":"中国人民银行及其分支机构应当指派两名以上检查人员，参照本规定第二十五条、第三章第二节、第四章规定的具体程序和证据收集规范开展执法检查。 适用简易现场检查程序进行执法检查的，根据实际需要，可以不再拟定检查方案、进行进场会谈和退场会谈等，但应当以适当形式告知被检查人享有的权利和配合检查的义务。"},{"i":37,"n":"第三十七条","txt":"检查组应当严格遵守法定程序，根据违法违规行为的不同类别、阶段、环节，合理使用音视频记录和文字记录等多种方式，全面、客观、及时、准确地收集符合法定形式的证据，实现执法全过程留痕和可回溯管理。"},{"i":38,"n":"第三十八条","txt":"检查组在现场检查中可以要求被检查人对相关检查事实进行确认，制作执法检查事实认定书，由被检查人签字、盖章确认。 执法检查事实认定书应当载明被检查人的名称或者姓名、检查开展时间、检查内容、确认的事实等内容。 被检查人对执法检查事实认定书无异议的，视为被检查人认可执法检查事实认定书载明的内容。"},{"i":39,"n":"第三十九条","txt":"检查组在现场检查中收集有关书证、物证、视听资料等证据的，应当尽可能取得原件；无法取得原件的，可以制作复印件、影印件、节录本等复制件。 能够证明合法来源，与原件一致的复制件可以作为认定相关事实的证据使用。"},{"i":40,"n":"第四十条","txt":"检查组可以直接提取被检查人电子计算机数据库及其他信息化系统中的电子数据作为证据，也可以采用抽样、汇总、分解、转换、计算、统计、比对等方式形成新的电子数据。 检查组形成新的电子数据的，应当通过取证说明、音视频记录等方式，记录电子数据的形成方式或者过程。"},{"i":41,"n":"第四十一条","txt":"检查组向被检查人或者其工作人员、其他知悉相关情况的人员询问有关情况的，应当制作执法检查询问笔录，由被询问人进行核对并签字确认；执法检查询问笔录有错误或者有遗漏的，应当允许被询问人提出更正意见或者补充意见。"},{"i":42,"n":"第四十二条","txt":"对可能灭失或者以后难以取得的证据，检查组经本单位行长或者副行长（主任或者副主任）批准，可以根据具体情况依法采取先行登记保存、聘请公证人员进行公证、申请有权机关冻结或者查封等保全措施。 采取保全措施的，检查组应当通知被检查人。先行登记保存证据期间，被检查人或者其他有关人员不得毁损、销毁或者转移证据。"},{"i":43,"n":"第四十三条","txt":"中国人民银行及其分支机构通过函询，或者在线上检查中通过信息化系统获取的信息、电子数据、文件和资料等可以作为认定被检查人是否存在违法违规行为的证据使用。"},{"i":44,"n":"第四十四条","txt":"现场检查结束时，检查组应当与被检查人进行退场会谈，通报现场检查中认定的事实，并制作执法检查退场会谈纪要。被检查人存在异议的，可以在会谈中提出，或者自收到执法检查退场会谈纪要之日起五个工作日内向检查组书面提出。 确因特殊原因难以在现场检查结束时举行退场会谈，或者通过非现场检查方式、适用简易现场检查程序拟认定被检查人存在违法违规行为的，应当及时书面告知被检查人拟认定的事实、理由和依据。被检查人存在异议的，可以自收到书面告知之日起五个工作日内向作出该书面告知的中国人民银行或其分支机构书面提出。 检查组应当听取被检查人的意见，并以适当形式向被检查人反馈。"},{"i":45,"n":"第四十五条","txt":"中国人民银行及其分支机构在现场检查，或者函询、线上检查等非现场检查中发现被检查人存在违反法律、行政法规、国务院决定，以及中国人民银行规章、规范性文件规定的行为的，应当向被检查人出具责令整改通知书，要求被检查人整改；必要时，可以将责令整改通知书抄送被检查人的上级机构。 责令整改通知书应当载明被检查人的名称或者姓名、被检查人违法违规行为情况及认定依据、被检查人应当采取的整改措施、整改期限等。 中国人民银行及其分支机构应当参照《中国人民银行行政处罚程序规定》第四十五条、第四十六条规定的时限和方式送达责令整改通知书。"},{"i":46,"n":"第四十六条","txt":"被检查人应当在责令整改通知书规定的整改期限内完成整改，并向发出责令整改通知书的中国人民银行或其分支机构提交整改报告。 中国人民银行或其分支机构可以采取适当方式对被检查人的整改情况进行核实。"},{"i":47,"n":"第四十七条","txt":"中国人民银行及其分支机构根据非现场检查和现场检查认定的事实，可以约谈被检查人的实际控制人、法定代表人或者主要负责人、董事、监事、高级管理人员以及相关责任人员。 被检查人拒绝、阻碍中国人民银行及其分支机构的非现场检查和现场检查工作，或者未按要求进行整改的，中国人民银行及其分支机构可以采取前款规定的约谈措施。"},{"i":48,"n":"第四十八条","txt":"中国人民银行及其分支机构根据非现场检查和现场检查认定的事实，可以对被检查人采取出具警示函、监管意见书等监管措施。"},{"i":49,"n":"第四十九条","txt":"被检查人有违反法律、行政法规或者中国人民银行规章规定的行为，并且中国人民银行或其分支机构对相关违法违规行为有管辖权的，应当及时依照《中华人民共和国行政处罚法》和《中国人民银行行政处罚程序规定》处理。"},{"i":50,"n":"第五十条","txt":"中国人民银行分支机构在日常监管、执法检查中发现被检查人存在违法违规行为，但不属于本单位管辖的，应当移送有管辖权的中国人民银行分支机构处理；发现属于中国人民银行管辖的，应当逐级报请中国人民银行处理。 中国人民银行及其分支机构在日常监管、执法检查中发现被检查人涉嫌存在应当由其他部门查处的违法违规行为的，应当依法移送有关部门处理。"},{"i":51,"n":"第五十一条","txt":"中国人民银行及其分支机构在执法检查过程中发现被检查人及其工作人员涉嫌犯罪，依法需要追究刑事责任的，应当按照《行政执法机关移送涉嫌犯罪案件的规定》，及时向公安机关移送。 中国人民银行及其分支机构在执法检查过程中发现被检查人的工作人员中存在被监察对象涉嫌违反党纪、职务违法或者职务犯罪等问题线索的，应当及时向纪检监察机关移送。"},{"i":52,"n":"第五十二条","txt":"中国人民银行及其分支机构应当依照有关规定，将执法检查材料整理归档，妥善保存。"},{"i":53,"n":"第五十三条","txt":"中国人民银行及其分支机构的工作人员违反本规定，按照法律、行政法规规定应当给予处分的，依法给予处分；涉嫌犯罪的，依法移送监察机关或者司法机关处理。"},{"i":54,"n":"第五十四条","txt":"被检查人或其工作人员违反本规定，拒绝、阻碍中国人民银行或其分支机构的非现场检查和现场检查工作，拒绝提供信息、电子数据、文件和资料等或者提供虚假信息、电子数据、文件和资料等，拒绝参加或者配合中国人民银行或其分支机构约谈的，有关法律、行政法规和中国人民银行规章有处罚规定的，依据其规定给予处罚；有关法律、行政法规和中国人民银行规章未作处罚规定的，中国人民银行或其分支机构给予警告，并处十万元以下罚款，视情况给予通报批评。"},{"i":55,"n":"第五十五条","txt":"被检查人未按照中国人民银行或其分支机构的要求整改，或者提交的整改报告内容不实，有关法律、行政法规和中国人民银行规章有处罚规定的，依据其规定给予处罚；有关法律、行政法规和中国人民银行规章未作处罚规定，情节严重的，中国人民银行或其分支机构给予警告，并处十万元以下罚款，视情况给予通报批评。"},{"i":56,"n":"第五十六条","txt":"本规定所称中国人民银行分支机构包括中国人民银行上海总部，各分行、营业管理部、中心支行和支行。"},{"i":57,"n":"第五十七条","txt":"本规定所称被检查人享有的权利，是指被检查人对检查组工作进行监督、申请检查人员回避、对检查情况提出异议、举报检查人员违法违纪行为等权利。 本规定所称被检查人配合检查的义务，包括： （一）不得阻碍、拒绝监督检查，不得提出不合理的要求； （二）如实回复函询或者回答检查人员的询问，及时就相关事项进行说明； （三）按照要求及时提供执法检查所需的信息、电子数据、文件和资料等，并对所提供的信息、电子数据、文件和资料等的真实性、准确性、完整性负责。"},{"i":58,"n":"第五十八条","txt":"国家外汇管理局及其分支机构实施执法检查的程序规定，由国家外汇管理局另行制定。"},{"i":59,"n":"第五十九条","txt":"中国人民银行及其分支机构与其他行政执法部门联合实施执法检查的，可以参照本规定执行。 中国人民银行可以依法与其他监管部门建立执法合作机制，相关办法由中国人民银行会同相关监管部门另行制定。"},{"i":60,"n":"第六十条","txt":"本规定由中国人民银行负责解释。"},{"i":61,"n":"第六十一条","txt":"本规定自2022年6月1日起施行。《中国人民银行执法检查程序规定》（中国人民银行令〔2010〕第1号发布）同时废止。"}],"zhongguorenminyinhangcanquewusunrenminbiduihuanbanb47fb2-2":[{"i":1,"n":"第一条","txt":"为维护人民币信誉，保护国家财产安全和人民币持有人的合法权益，确保人民币正常流通，根据《中华人民共和国中国人民银行法》和《中华人民共和国人民币管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称残缺、污损人民币是指票面撕裂、损缺，或因自然磨损、侵蚀，外观、质地受损，颜色变化，图案不清晰，防伪特征受损，不宜再继续流通使用的人民币。"},{"i":3,"n":"第三条","txt":"凡办理人民币存取款业务的金融机构（以下简称金融机构）应无偿为公众兑换残缺、污损人民币，不得拒绝兑换。"},{"i":4,"n":"第四条","txt":"残缺、污损人民币兑换分“全额”、“半额”两种情况。 （一）能辨别面额，票面剩余四分之三（含四分之三）以上，其图案、文字能按原样连接的残缺、污损人民币，金融机构应向持有人按原面额全额兑换。 （二）能辨别面额，票面剩余二分之一（含二分之一）至四分之三以下，其图案、文字能按原样连接的残缺、污损人民币，金融机构应向持有人按原面额的一半兑换。 纸币呈正十字形缺少四分之一的，按原面额的一半兑换。"},{"i":5,"n":"第五条","txt":"兑付额不足一分的，不予兑换；五分按半额兑换的，兑付二分。"},{"i":6,"n":"第六条","txt":"金融机构在办理残缺、污损人民币兑换业务时，应向残缺、污损人民币持有人说明认定的兑换结果。不予兑换的残缺、污损人民币，应退回原持有人。"},{"i":7,"n":"第七条","txt":"残缺、污损人民币持有人同意金融机构认定结果的，对兑换的残缺、污损人民币纸币，金融机构应当面将带有本行行名的“全额”或“半额”戳记加盖在票面上；对兑换的残缺、污损人民币硬币，金融机构应当面使用专用袋密封保管，并在袋外封签上加盖“兑换”戳记。"},{"i":8,"n":"第八条","txt":"残缺、污损人民币持有人对金融机构认定的兑换结果有异议的，经持有人要求，金融机构应出具认定证明并退回该残缺、污损人民币。 持有人可凭认定证明到中国人民银行分支机构申请鉴定，中国人民银行应自申请日起5个工作日内做出鉴定并出具鉴定书。持有人可持中国人民银行的鉴定书及可兑换的残缺、污损人民币到金融机构进行兑换。"},{"i":9,"n":"第九条","txt":"金融机构应按照中国人民银行的有关规定，将兑换的残缺、污损人民币交存当地中国人民银行分支机构。"},{"i":10,"n":"第十条","txt":"中国人民银行依照本办法对残缺、污损人民币的兑换工作实施监督管理。"},{"i":11,"n":"第十一条","txt":"违反本办法第三条规定的金融机构，由中国人民银行根据《中华人民共和国人民币管理条例》第四十二条规定，依法进行处罚。"},{"i":12,"n":"第十二条","txt":"本办法自2004年2月1日起施行。1955年5月8日中国人民银行发布的《残缺人民币兑换办法》同时废止。"}],"zhongguorenminyinhangcanquewusunrenminbiduihuanbanb47fb2":[{"i":1,"n":"第一条","txt":"为了维护人民币信誉，保护国家财产安全和人民币持有人的合法权益，确保人民币正常流通，根据《中华人民共和国中国人民银行法》和《中华人民共和国人民币管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，办理人民币现金存取业务的银行业金融机构（以下简称金融机构）为公众办理残缺、污损人民币兑换业务，中国人民银行分支机构鉴定残缺、污损人民币兑换结果，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称残缺、污损人民币，是指票面撕裂、损缺，或外观、质地受损，颜色变化，图案不清晰，防伪特征受损，不宜再继续流通使用的人民币。 本办法所称兑换，是指金融机构根据残缺、污损人民币持有人（以下简称持有人）请求，将其持有的残缺、污损人民币兑换为适宜流通人民币的行为。 本办法所称鉴定，是指持有人对金融机构认定的兑换结果有异议，中国人民银行分支机构依据持有人申请，对兑换结果进行裁定的行为。"},{"i":4,"n":"第四条","txt":"金融机构应当无偿为公众办理残缺、污损人民币兑换业务，不得拒绝办理。 因火烧、侵蚀、霉烂等特殊原因形成的残缺、污损人民币（以下简称特殊残缺、污损人民币）的兑换业务，由中国人民银行分支机构指定的金融机构办理。被指定的金融机构应当无偿为公众办理特殊残缺、污损人民币兑换业务，不得拒绝办理。"},{"i":5,"n":"第五条","txt":"残缺、污损人民币的剩余面积（以下简称剩余面积），是指票面图案、文字、材质能按原样连接的实物面积。特殊残缺、污损人民币能原样连接的炭化、变形部分，计入剩余面积。 剩余面积比例是指剩余面积占原票面面积的比例。"},{"i":6,"n":"第六条","txt":"有下列情形之一的残缺、污损人民币，不予兑换： （一）重要防伪特征缺失，无法辨别为真币的； （二）无法辨别面额的； （三）剩余面积比例不满二分之一的。"},{"i":7,"n":"第七条","txt":"残缺、污损人民币不具有本办法第六条规定的不予兑换情形，按照以下标准兑换： （一）剩余面积比例在四分之三（含）以上，按照原面额全额兑换； （二）剩余面积比例在二分之一（含）以上不满四分之三的，或者纸币呈正十字形缺少四分之一的，按照原面额的一半兑换。"},{"i":8,"n":"第八条","txt":"兑付金额不足1分的，不予兑换；5分按原面额的一半兑换的，兑付2分。"},{"i":9,"n":"第九条","txt":"金融机构在办理残缺、污损人民币兑换业务时，应当向持有人说明认定的兑换结果。 不予兑换的残缺、污损人民币，应当退回原持有人。"},{"i":10,"n":"第十条","txt":"持有人同意金融机构认定的兑换结果的，对半额兑换的残缺、污损人民币（特殊残缺、污损人民币除外）纸币，金融机构应当当面在票面上加盖符合中国人民银行规定的“半额”戳记；对兑换的残缺、污损人民币硬币以及特殊残缺、污损人民币，金融机构应当当面使用专用袋密封保管，并在袋外封签上加盖符合中国人民银行规定的兑换戳记。"},{"i":11,"n":"第十一条","txt":"持有人对金融机构认定的兑换结果有异议的，金融机构应当出具符合中国人民银行规定的残缺、污损人民币兑换认定书，并退回该残缺、污损人民币。 持有人可自兑换认定书出具之日起10个工作日内，持兑换认定书和对应的残缺、污损人民币，向属地中国人民银行分支机构申请鉴定。"},{"i":12,"n":"第十二条","txt":"中国人民银行分支机构应当自接到申请之日起20个工作日内做出鉴定并出具鉴定书。情况复杂的，经本单位负责人批准，可以延长，但是延长期限最多不超过20个工作日。 持有人可持鉴定书到金融机构办理兑换。"},{"i":13,"n":"第十三条","txt":"金融机构应当按照中国人民银行的有关规定，将兑换的残缺、污损人民币交存中国人民银行分支机构。"},{"i":14,"n":"第十四条","txt":"中国人民银行及其分支机构依法对残缺、污损人民币兑换工作实施监督管理。"},{"i":15,"n":"第十五条","txt":"金融机构违反本办法第四条规定，未无偿为公众兑换残缺、污损人民币的，由中国人民银行及其分支机构按照《中华人民共和国人民币管理条例》进行处罚。"},{"i":16,"n":"第十六条","txt":"本办法自2026年3月31日起施行。《中国人民银行残缺污损人民币兑换办法》（中国人民银行令〔2003〕第7号发布）、《中国人民银行关于做好特殊残缺污损人民币兑换工作有关事项的通知》（银发〔2007〕280号）同时废止。"}],"zhongguorenminyinhangjinjidaikuanguanlizanxingbanfb36c76":[{"i":1,"n":"第一条","txt":"为了维护金融体系的安全与稳定，防范和化解金融风险，依据《中华人民共和国中国人民银行法》、《中华人民共和国商业银行法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于经中国人民银行批准设立、具有法人资格的城市商业银行、城市信用合作社和农村信用合作社（含农村信用合作社县联社，下同）。地方政府兑付被撤销地方金融机构的债务向中央借款，不适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称紧急贷款，系指中国人民银行为帮助发生支付危机的上述金融机构缓解支付压力、恢复信誉，防止出现系统性或区域性金融风险而发放的人民币贷款。"},{"i":4,"n":"第四条","txt":"紧急贷款的审批权属中国人民银行总行（以下简称总行）。经总行授权，中国人民银行分行、营业管理部（以下简称分行）可依据本办法规定审批、发放紧急贷款。"},{"i":5,"n":"第五条","txt":"城市商业银行、城市信用合作社和农村信用合作社（以下统称借款人）申请紧急贷款，应符合下列条件： （一）在中国人民银行开户行设立“准备金存款”账户，且经批准已全额或部分动用法定存款准备金； （二）当地政府及有关部门对处置借款人的支付风险高度重视，并已采取增加其资金来源以及其它切实有效的救助措施； （三）借款人已采取了清收债权、组织存款、系统内调度资金、同业拆借、资产变现等自救措施，自救态度积极、措施得力； （四）当地政府和组建单位或股东制定的救助方案已经中国人民银行总行或分行批准，并承诺在规定时限内实行增资扩股，逐步减少经营亏损，改善其资信情况，查处违规、违纪行为和违法案件，追究有关当事人的经济、行政或刑事责任； （五）依据《中华人民共和国担保法》提供担保； （六）中国人民银行分行已派驻工作组或专人实施现场监管； （七）中国人民银行认为必要的其它条件。"},{"i":6,"n":"第六条","txt":"城市商业银行申请紧急贷款时，其原股东欠缴的股本已补足；资本充足率低于规定比例的，已开始实施增资扩股。"},{"i":7,"n":"第七条","txt":"紧急贷款仅限用于兑付自然人存款的本金和合法利息，并优先用于兑付小额储蓄存款。"},{"i":8,"n":"第八条","txt":"紧急贷款的最长期限2年。贷款到期归还确有困难的，经借款人申请，可批准展期一次，展期期限不得超过原贷款期限。紧急贷款展期，应按本办法规定的审批权限报批，并由担保人出具同意的书面证明。"},{"i":9,"n":"第九条","txt":"紧急贷款应执行总行制定的中国人民银行对金融机构贷款利率；发生逾期的紧急贷款，应执行再贷款罚息利率。"},{"i":10,"n":"第十条","txt":"分行申请增加紧急贷款限额，应以分行名义书面申请。总行受理分行申请后，由货币政策司会同有关监管部门提出审查意见，报行长或主管副行长审批。"},{"i":11,"n":"第十一条","txt":"对分行发放的紧急贷款实行单独管理和限额控制。分行应在总行下达的紧急贷款额度内，依据本办法规定，审批、发放和管理紧急贷款，确定对单个借款人的贷款方式、数额和期限，并对辖内紧急贷款的合理使用和安全负责。"},{"i":12,"n":"第十二条","txt":"分行应与借款人签定《借款合同》，并与借款人或其出资人、第三人签定《担保合同》，依法建立完备的贷款担保手续。"},{"i":13,"n":"第十三条","txt":"分行应对紧急贷款实行专户管理，在再贷款科目下单独设立“紧急贷款”账户；在借款人准备金存款科目下单独设立“紧急贷款专户”，并按月向总行列报辖内紧急贷款的限额执行、发放进度、周转使用和到期收回情况。"},{"i":14,"n":"第十四条","txt":"分行货币信贷部门应配合监管部门做好借款人支付风险的防范和化解工作；监管部门应按照发放紧急贷款时规定条件，督促借款人及其组建单位或股东和地方政府逐项落实承诺采取的救助措施。"},{"i":15,"n":"第十五条","txt":"中国人民银行内审部门应根据实际情况，适时采取适当形式，对紧急贷款业务的管理情况进行内审。"},{"i":16,"n":"第十六条","txt":"借款人应以法人名义（农村信用合作社以县联社为单位）向中国人民银行开户行申请紧急贷款，并提交足以证明其符合紧急贷款条件的书面文件和资料。"},{"i":17,"n":"第十七条","txt":"借款人在借用紧急贷款期间，所筹资金除用于兑付储蓄存款外，应优先用于归还紧急贷款，不得增加新的资产运用，不得向股东分红派息，并向中国人民银行开户行报告每笔资产、负债的变动情况和每日的资金头寸表。"},{"i":18,"n":"第十八条","txt":"借款人应当按照《借款合同》约定，按时足额归还紧急贷款本息。对逾期的紧急贷款，中国人民银行可依据《借款合同》和《担保合同》约定，从借款人准备金存款账户中扣收贷款本息；依法处置抵押物、质物，用于归还贷款本息；依法要求保证人履行还款保证责任。"},{"i":19,"n":"第十九条","txt":"借款人有下列情形之一，中国人民银行可提前收回部分或全部紧急贷款；情节严重的，取消其高级管理人员的任职资格： （一）虚报材料，隐瞒事实，骗取紧急贷款的； （二）违反本办法规定，挪用紧急贷款的； （三）未按人民银行批准救助方案采取自救措施的。"},{"i":20,"n":"第二十条","txt":"中国人民银行分支行有下列情形之一，上级行给予通报批评；情节严重的，对直接负责的主管行领导和其他直接责任人员给予行政处分： （一）超过上级行下达限额发放紧急贷款的； （二）不按照本办法规定对象、条件、期限和用途审批、发放紧急贷款的； （三）对辖内紧急贷款管理不力、严重失职的。"},{"i":21,"n":"第二十一条","txt":"经总行批准，对城市商业银行、城市信用合作社、农村信用合作社以外的商业银行及其他非银行金融机构发放紧急贷款，适用本办法。"},{"i":22,"n":"第二十二条","txt":"本办法由总行负责解释。"},{"i":23,"n":"第二十三条","txt":"本办法自下发之日起实行。"}],"zhongguorenminyinhangxingzhengchufachengxuguiding":[{"i":1,"n":"第一条","txt":"为规范中国人民银行及其分支机构的行政处罚行为，维护当事人合法权益，根据《中华人民共和国中国人民银行法》《中华人民共和国商业银行法》《中华人民共和国行政处罚法》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"中国人民银行及其分支机构依法对管辖的法人、非法人组织和自然人违反相关法律、行政法规、中国人民银行规章的行为给予行政处罚的，依照本规定实施。"},{"i":3,"n":"第三条","txt":"中国人民银行及其分支机构应当依照法律、行政法规、中国人民银行规章的规定，公正、公开、合理地实施行政处罚，坚持处罚与教育相结合，与违法行为的事实、性质、情节以及社会危害程度相当。"},{"i":4,"n":"第四条","txt":"中国人民银行及其分支机构实施行政处罚，实行分级管理、分工负责，执法检查、案件调查与案件审理、案件决定相分离。"},{"i":5,"n":"第五条","txt":"中国人民银行及其分支机构依法公开行政处罚决定信息。 除法律、行政法规或者中国人民银行规章另有规定外，中国人民银行及其分支机构在行政处罚案件立案、调查、审理、决定过程中形成的案卷信息不予公开。当事人及其代理人可以按照规定申请查阅相关案卷信息。"},{"i":6,"n":"第六条","txt":"中国人民银行及其分支机构的工作人员对实施行政处罚过程中知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息应当依法予以保密，不得违反规定对外提供。 行政处罚决定信息公布之前，当事人、中国人民银行及其分支机构的工作人员、参与案件调查的辅助人员、提供意见的外部专家等对行政处罚情况负有保密义务，不得泄露与行政处罚有关的信息。"},{"i":7,"n":"第七条","txt":"中国人民银行负责对下列违法违规行为实施行政处罚： （一）法律、行政法规、中国人民银行规章规定由中国人民银行实施行政处罚的违法违规行为； （二）以中国人民银行名义开展执法检查发现的违法违规行为； （三）全国范围内有重大影响的违法违规行为； （四）中国人民银行认为应当由其直接实施行政处罚的其他违法违规行为。"},{"i":8,"n":"第八条","txt":"中国人民银行分支机构负责对下列违法违规行为实施行政处罚： （一）所监管的法人、非法人组织和自然人的违法违规行为； （二）发生在辖区内的违法违规行为； （三）以本单位名义开展执法检查发现的违法违规行为； （四）中国人民银行授权其开展执法检查发现的违法违规行为； （五）中国人民银行指定其管辖的其他违法违规行为。 当事人的违法违规行为涉及信息网络等因素，无法确定发生地的，原则上由当事人所在地的中国人民银行分支机构管辖。"},{"i":9,"n":"第九条","txt":"中国人民银行或其分支机构根据需要可以直接对下级行辖区内有重大影响、案情复杂的违法违规行为实施行政处罚。 中国人民银行分支机构认为应当由其实施行政处罚的违法违规行为情节严重、有重大影响的，可以请求上级行实施行政处罚。"},{"i":10,"n":"第十条","txt":"中国人民银行根据实际情况，认为案件不适宜由相关中国人民银行分支机构负责实施行政处罚的，可以自行实施行政处罚，或者指定其上级行、其他同级中国人民银行分支机构负责实施行政处罚。"},{"i":11,"n":"第十一条","txt":"中国人民银行根据履行法定职责的需要，可以决定由特定中国人民银行分支机构集中行使其他中国人民银行分支机构的部分或者全部管辖权，具体方式和集中管辖的案件范围由中国人民银行另行规定。"},{"i":12,"n":"第十二条","txt":"除法律、行政法规另有规定外，《中华人民共和国行政处罚法》第九条第三项、第四项所规定的行政处罚，以及其他涉及许可证件、资质等级、生产经营等行政处罚，由颁发该许可证件、授予该资质等级、准许生产经营的中国人民银行或其分支机构实施。"},{"i":13,"n":"第十三条","txt":"两个以上中国人民银行分支机构对同一违法违规行为均有管辖权的，由最先立案的中国人民银行分支机构管辖。 中国人民银行分支机构对管辖权发生争议的，应当协商解决，协商不成的，逐级报请共同的上级行指定管辖；也可以由共同的上级行直接指定管辖。 作出指定管辖决定的中国人民银行或其分支机构应当出具指定管辖通知书。"},{"i":14,"n":"第十四条","txt":"中国人民银行及其分支机构设立行政处罚委员会，负责案件审理和审议决定行政处罚、决定涉及行政处罚的其他重大事项。 行政处罚委员会集体行使行政处罚权，接受上级行行政处罚委员会的指导和监督，其他部门和个人不得干涉行政处罚委员会依法独立行使职权。 行政处罚委员会的组成人员、设立方式等事项由中国人民银行另行规定。"},{"i":15,"n":"第十五条","txt":"行政处罚委员会的主任由中国人民银行或其分支机构的行长（主任），或者其授权的副行长（副主任）担任，实行主任负责制；主任因故不能履行职责时，可以委托副主任代行主任职责。"},{"i":16,"n":"第十六条","txt":"行政处罚委员会履行下列职责： （一）审议行政处罚案件，作出行政处罚决定； （二）审议案件审理指导意见、本单位涉及行政处罚工作的重要管理制度等； （三）对下级行行政处罚委员会进行指导和监督； （四）审议本单位与行政处罚工作相关的其他重大事项。"},{"i":17,"n":"第十七条","txt":"行政处罚委员会下设办公室，行政处罚委员会办公室设在中国人民银行及其分支机构的法律事务部门；暂未设立法律事务部门的中国人民银行分支机构，由具体承担法律事务工作的部门履行其职责。 行政处罚委员会办公室承担行政处罚委员会的日常工作，履行下列职责： （一）立案审查； （二）进行法制审核，提出案件处理意见； （三）组织召开行政处罚委员会会议和组织书面审议； （四）听取当事人陈述、申辩，组织听证； （五）制作相关法律文书； （六）督促行政处罚的执行或者申请人民法院强制执行； （七）中国人民银行规定的其他职责。"},{"i":18,"n":"第十八条","txt":"行政处罚委员会采取集体审议的方式作出行政处罚决定，可以根据案件具体情况采取会议审议和书面审议两种方式。具体审议程序由中国人民银行另行规定。"},{"i":19,"n":"第十九条","txt":"除符合《中华人民共和国行政处罚法》第五十一条规定，依法适用简易程序作出行政处罚外，中国人民银行及其分支机构执法职能部门根据下列情形，认为符合立案标准的，依法向本单位行政处罚委员会办公室申请立案： （一）在现场检查、非现场检查及日常监管中发现当事人存在违法违规行为，或者有违法违规行为确切线索的； （二）对于公安机关、其他监管部门、行业自律组织等移送的违法违规线索，经初步核实认为当事人存在违法违规行为的； （三）中国人民银行及其他分支机构发现违法违规行为，移送本单位管辖的； （四）上级行指定本单位管辖的； （五）本单位对相关违法违规行为有管辖权的其他情形。"},{"i":20,"n":"第二十条","txt":"中国人民银行及其分支机构立案后，认为需要对违法违规行为进一步调查，了解相关情况、补充证据材料的，可以对当事人开展案件调查。 中国人民银行及其分支机构开展案件调查的，应当向当事人送达案件调查通知书，告知案件调查的依据、内容、调查期限范围、调查开展时间、要求、调查人员名单等事项。"},{"i":21,"n":"第二十一条","txt":"案件调查程序参照《中国人民银行执法检查程序规定》简易现场检查程序进行；案件情况较为复杂、影响较大的，可以参照现场检查程序进行。 调查人员应当按照《中华人民共和国行政处罚法》《中国人民银行执法检查程序规定》等规定全面、客观、公正地调查，充分收集证据材料。"},{"i":22,"n":"第二十二条","txt":"中国人民银行及其分支机构根据案件调查工作需要，可以聘请注册会计师、资产评估人员、律师等专业人员，以及数据分析、信息技术等领域技术人员作为辅助人员协助案件调查，或者邀请上述人员出具专业意见。"},{"i":23,"n":"第二十三条","txt":"当事人应当配合中国人民银行及其分支机构的案件调查，履行下列义务： （一）不得阻碍、拒绝案件调查，不得提出不合理的要求； （二）如实回答调查人员的询问，及时就相关事项进行说明； （三）按照要求及时提供案件调查所需的信息、电子数据、文件和资料等，并对所提供的信息、电子数据、文件和资料等的真实性、准确性、完整性负责。"},{"i":24,"n":"第二十四条","txt":"行政处罚委员会办公室根据相关证据材料，依法提出案件处理意见。"},{"i":25,"n":"第二十五条","txt":"行政处罚委员会办公室提出案件处理意见后，经行政处罚委员会主任批准，组织召开行政处罚委员会会议或者组织书面审议。 行政处罚委员会审议下列事项： （一）本单位是否具有管辖权，是否超越法定权限； （二）违法违规事实是否清楚，证据是否合法、充分，定性是否准确； （三）执法检查、案件调查程序是否合法； （四）适用法律、行政法规、中国人民银行规章是否正确，裁量基准运用是否适当； （五）拟作出行政处罚的种类、金额是否适当，拟不予行政处罚或者减轻处罚的理由和依据是否充分。"},{"i":26,"n":"第二十六条","txt":"行政处罚委员会审议案件时，可以听取与案件不存在利害关系的法官、律师、学者等外部专家的意见。 听取意见可以采取当面听取的方式，也可以邀请外部专家提供书面意见。"},{"i":27,"n":"第二十七条","txt":"行政处罚委员会审议通过，拟作出行政处罚决定的，行政处罚委员会办公室制作行政处罚意见告知书，经行政处罚委员会主任或者其授权的副主任批准后，送达当事人。"},{"i":28,"n":"第二十八条","txt":"行政处罚意见告知书应当载明违法违规行为的事实和证据，拟作出行政处罚的种类、金额、理由和依据，以及当事人依法享有提出陈述和申辩的权利；拟作出的行政处罚决定符合《中华人民共和国行政处罚法》第六十三条规定的听证情形的，应当告知当事人依法享有提出听证的权利。其中，“较大数额罚款”“没收较大数额违法所得、没收较大价值非法财物”，是指： （一）中国人民银行对法人、非法人组织拟作出罚款、没收违法所得、没收非法财物合计五百万元及以上的，对单一自然人合计二十万元以上的； （二）中国人民银行副省级城市中心支行以上分支机构对法人、非法人组织拟作出罚款、没收违法所得、没收非法财物合计三百万元及以上的，对单一自然人合计十万元以上的； （三）中国人民银行地市中心支行对法人、非法人组织拟作出罚款、没收违法所得、没收非法财物合计一百万元及以上的，对单一自然人合计五万元以上的。"},{"i":29,"n":"第二十九条","txt":"案件调查人员、行政处罚委员会委员、行政处罚委员会办公室从事案件处理工作的人员与当事人存在利害关系，或者有其他可能影响案件公平审理的情形的，应当主动申请回避；应当回避而未主动申请回避，当事人申请回避且理由充分的，行政处罚委员会主任应当要求相关人员回避。"},{"i":30,"n":"第三十条","txt":"当事人可以在中国人民银行及其分支机构立案后、送达行政处罚决定书前书面提出先行整改承诺申请，载明清晰、可查证的整改目标、整改措施和完成时间，或者消除损害、不良影响的措施等。中国人民银行认为当事人通过先行整改能够更好符合金融监管要求且不立即实施行政处罚不会损害社会公共利益、他人合法权益的，可以决定中止审理、暂缓作出行政处罚决定，督促当事人进行整改。当事人按承诺期限完成整改的，中国人民银行或其分支机构可以依法从轻、减轻处罚；到期未实质完成整改工作，或者没有合理理由拖延整改的，恢复审理，并依法从重处罚。 先行整改承诺主要适用于拟作出较大数额罚款、吊销相关许可证、责令停业整顿等重大行政处罚案件，且当事人不存在违法违规行为情节严重、社会影响恶劣等情形。"},{"i":31,"n":"第三十一条","txt":"当事人在中国人民银行及其分支机构作出行政处罚决定前发生金融风险事件，金融管理部门或者存款保险机构依法完成处置的，对当事人在金融风险事件处置完成前实施的违法违规行为，可以按照经批准的金融风险处置方案处理。"},{"i":32,"n":"第三十二条","txt":"中国人民银行及其分支机构对于不适用《中华人民共和国行政处罚法》第五章第二节规定的简易程序，但事实清楚，当事人书面申请、自愿认错认罚，且相关违法违规行为有证据佐证的案件，可以适当简化案件审理程序，及时作出行政处罚决定。"},{"i":33,"n":"第三十三条","txt":"当事人要求陈述和申辩的，应当自收到行政处罚意见告知书之日起五日内将陈述和申辩的书面材料提交至制作行政处罚意见告知书的中国人民银行或其分支机构。 当事人收到行政处罚意见告知书后，可以书面提出放弃陈述和申辩权利；当事人逾期未提交陈述和申辩的书面材料，且没有合理理由的，视为放弃陈述和申辩权利。"},{"i":34,"n":"第三十四条","txt":"当事人根据《中华人民共和国行政处罚法》第六十三条规定要求听证的，应当自收到行政处罚意见告知书之日起五日内，向制作行政处罚意见告知书的中国人民银行或其分支机构提交听证申请书，说明听证的要求和理由；当事人对违法违规事实有异议，或者主张应当从轻、减轻、免除行政处罚的，应当同时提交相关证据材料。 当事人收到行政处罚意见告知书后，可以书面提出放弃听证权利；当事人逾期不提出听证申请，且没有合理理由的，视为放弃听证权利。"},{"i":35,"n":"第三十五条","txt":"当事人申请听证的，中国人民银行或其分支机构应当自收到听证申请之日起三十日内组织听证，并在召开听证会七日前，通知当事人及有关人员举行听证的时间、地点。 除涉及国家秘密、商业秘密或者个人隐私等依法予以保密的情形外，听证应当公开进行。"},{"i":36,"n":"第三十六条","txt":"听证由行政处罚委员会办公室未参与本案案件处理、案件调查的人员担任听证主持人，两名正式工作人员担任听证员，也可以由行政处罚委员会主任指定未参与本案案件处理、案件调查的正式工作人员担任听证主持人。 当事人认为听证主持人、听证员与本案有直接利害关系的，有权申请回避。听证主持人、听证员是否回避，由行政处罚委员会主任决定。"},{"i":37,"n":"第三十七条","txt":"举行听证时，由负责执法检查或者案件调查的执法职能部门说明拟作出行政处罚的事实、证据和行政处罚建议；当事人及其代理人可以进行申辩和质证，并可以出示无违法违规事实、违法违规事实较轻或者应当从轻、减轻、免除行政处罚的证据材料。 听证应当由听证主持人指定专人记录并制作听证笔录，听证笔录的内容包括：举行听证的时间、地点、参加听证的人员、听证事项、听证参与人的意见。 听证笔录应当交当事人或其代理人确认并签字或者盖章。当事人或其代理人拒绝签字或者盖章的，由听证主持人在听证笔录中注明。"},{"i":38,"n":"第三十八条","txt":"听证结束后，听证主持人和听证员应当制作听证报告，提出处理意见，并将听证报告、听证笔录及听证取得的证据，一并报行政处罚委员会办公室。"},{"i":39,"n":"第三十九条","txt":"听证申请人提出延期申请且有合理理由，或者因不可抗力，导致听证无法如期举行的，中国人民银行或其分支机构行政处罚委员会办公室可以决定延期举行听证，并告知听证申请人。"},{"i":40,"n":"第四十条","txt":"听证开始前或者在听证过程中，听证申请人有下列情形的，视为放弃听证权利，不得再次就同一行政处罚事项提出听证申请： （一）撤回听证申请； （二）无正当理由拒不参加听证； （三）听证过程中严重扰乱听证秩序，或者未经听证主持人允许中途退场。 听证申请人可以在听证前书面提出撤回听证申请，也可以在听证过程中书面或者口头提出撤回听证申请。"},{"i":41,"n":"第四十一条","txt":"中国人民银行及其分支机构应当充分听取当事人的意见，不得因当事人进行陈述、申辩或者提出听证而加重处罚。"},{"i":42,"n":"第四十二条","txt":"行政处罚委员会办公室应当根据案件审议情况，结合当事人的陈述和申辩意见、听证情况制作行政处罚决定书，经行政处罚委员会主任批准后，送达当事人。"},{"i":43,"n":"第四十三条","txt":"行政处罚决定书应当载明下列事项： （一）当事人的姓名或者名称、地址； （二）违法违规事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）不服行政处罚决定，申请行政复议或者提起行政诉讼的途径和期限； （六）作出行政处罚决定的中国人民银行或其分支机构的名称、印章和作出决定的日期。 当事人提出陈述和申辩意见或者进行听证的，行政处罚决定书中还应当说明是否采纳当事人的意见及理由。"},{"i":44,"n":"第四十四条","txt":"当事人的违法违规行为涉嫌犯罪，依法需要追究刑事责任的，中国人民银行及其分支机构应当按照《行政执法机关移送涉嫌犯罪案件的规定》，及时向公安机关移送。 中国人民银行及其分支机构在行政处罚过程中发现当事人或其工作人员存在被监察对象涉嫌违反党纪、职务违法或者职务犯罪等问题线索的，应当及时向纪检监察机关移送。"},{"i":45,"n":"第四十五条","txt":"中国人民银行及其分支机构应当在行政处罚决定书制作完成后七日内送达当事人。"},{"i":46,"n":"第四十六条","txt":"中国人民银行及其分支机构可以采取下列方式送达行政处罚意见告知书、行政处罚决定书等文书： （一）在中国人民银行及其分支机构办公场所当面送达当事人； （二）派两名以上正式工作人员赴当事人身份证件载明的住址，或者当事人确认的其他地址送达当事人； （三）根据当事人确认的通讯地址、联系方式等信息邮寄送达，采取邮寄送达的，邮件签收视为送达，邮件因地址错误、拒收等原因被退回的，邮件退回之日视为送达； （四）经当事人同意，使用电子邮件、信息化系统等电子送达方式送达当事人； （五）采取前述方式向当事人委托的代收人送达； （六）无法通过前述方式送达的，中国人民银行及其分支机构可以公告送达，公告期为三十日，公告期满，视为送达。 中国人民银行及其分支机构可以委托其他中国人民银行分支机构采取前款第一项、第二项、第五项规定的方式代为送达。"},{"i":47,"n":"第四十七条","txt":"中国人民银行及其分支机构作出罚款、没收违法所得行政处罚决定的，当事人应当自收到行政处罚决定书之日起十五日内按照行政处罚决定书载明的方式缴纳罚款、违法所得。 当事人根据《中华人民共和国行政处罚法》第六十六条的规定，申请延期或者分期缴纳罚款的，应当自收到行政处罚决定书之日起十五日内向作出行政处罚决定的中国人民银行或其分支机构提出书面申请，并提交相关证明材料。"},{"i":48,"n":"第四十八条","txt":"中国人民银行及其分支机构应当自行政处罚决定作出之日起七日内依据中国人民银行的相关规定公开行政处罚决定信息。"},{"i":49,"n":"第四十九条","txt":"当事人逾期不履行行政处罚决定的，中国人民银行及其分支机构可以根据《中华人民共和国行政处罚法》第七十二条的规定，采取相关措施。"},{"i":50,"n":"第五十条","txt":"当事人对行政处罚决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":51,"n":"第五十一条","txt":"中国人民银行及其分支机构应当自行政处罚案件立案之日起九十日内作出行政处罚决定，下列程序所需必要时间不计入行政处罚办理期限： （一）行政处罚立案后，根据本规定对当事人开展案件调查的； （二）根据当事人申请组织听证，或者相关证据需要进行检验、鉴定的； （三）通过公告方式送达行政处罚意见告知书的； （四）中国人民银行及其分支机构决定中止审理的。 中国人民银行及其分支机构在九十日内确实无法作出行政处罚决定的，经行政处罚委员会主任或者其授权的副主任批准，可以延长九十日。"},{"i":52,"n":"第五十二条","txt":"中国人民银行及其分支机构在作出行政处罚决定前，有下列情形之一的，经行政处罚委员会主任或者其授权的副主任批准，可以作出中止审理的决定： （一）当事人因涉嫌违法违规被其他行政机关调查，或者被司法机关侦查，尚未结案，对该行政处罚案件影响重大的； （二）当事人被依法接管或者采取其他金融风险处置措施，接管期限尚未届满或者金融风险处置尚未完成的； （三）行政处罚决定必须以相关诉讼的审理结果为依据，而相关诉讼未审结的； （四）对有关法律、行政法规、国务院决定、规章的规定，需要进一步明确具体含义，中国人民银行或其分支机构请求有关机关作出解释的； （五）当事人按照本规定第三十条的规定，向中国人民银行或其分支机构提出先行整改承诺申请，中国人民银行经审核同意的。 相关情形消失后，中国人民银行及其分支机构应当及时恢复审理，作出行政处罚决定。"},{"i":53,"n":"第五十三条","txt":"当事人违反本规定，拒绝、阻碍中国人民银行或其分支机构的案件调查，拒绝提供信息、电子数据、文件和资料等或者提供虚假信息、电子数据、文件和资料等的，有关法律、行政法规和中国人民银行规章有处罚规定的，依照其规定给予处罚；有关法律、行政法规和中国人民银行规章未作处罚规定的，由中国人民银行或其分支机构给予警告，并处十万元以下罚款，视情况给予通报批评。"},{"i":54,"n":"第五十四条","txt":"中国人民银行分支机构包括中国人民银行上海总部，各分行、营业管理部、中心支行和支行。"},{"i":55,"n":"第五十五条","txt":"中国人民银行可以依法与其他监管部门建立执法合作机制，相关办法由中国人民银行会同相关监管部门另行制定。"},{"i":56,"n":"第五十六条","txt":"国家外汇管理局及其分支机构实施行政处罚的程序规定，由国家外汇管理局另行制定。 国家外汇管理局可以参照实施本规定第五十一条、第五十二条的相关规定。"},{"i":57,"n":"第五十七条","txt":"本规定中“五日”“七日”均以工作日计算，不含法定节假日。"},{"i":58,"n":"第五十八条","txt":"本规定由中国人民银行负责解释。"},{"i":59,"n":"第五十九条","txt":"本规定自2022年6月1日起施行。《中国人民银行行政处罚程序规定》（中国人民银行令〔2001〕第3号发布）同时废止。"}],"zhongguorenminyinhangxingzhengchufacailiangjizhuns263d00":[{"i":1,"n":"第一条","txt":"为规范中国人民银行及其分支机构的行政处罚行为，保护当事人合法权益，根据《中华人民共和国行政处罚法》《中华人民共和国中国人民银行法》等法律，制定本规定。"},{"i":2,"n":"第二条","txt":"中国人民银行及其分支机构依法对监管的法人、非法人组织和自然人（以下统称当事人）违反相关法律、行政法规、规章的行为（以下统称违法行为）实施行政处罚的，应当遵守本规定明确的行政处罚裁量基准。"},{"i":3,"n":"第三条","txt":"本规定所称行政处罚裁量基准，是指按照当事人违法行为涉及的不同事实和情节，对法律、行政法规、规章中的原则性规定或者具有一定弹性的执法权限、裁量幅度等内容进行细化量化，形成的具体执法尺度和标准。"},{"i":4,"n":"第四条","txt":"中国人民银行及其分支机构适用行政处罚裁量基准，应当遵循公平公正、过罚相当、宽严相济、程序正当、处罚与教育相结合的原则，保障行政处罚的种类、幅度与违法行为事实、性质、情节及社会危害程度相匹配。"},{"i":5,"n":"第五条","txt":"行政处罚裁量基准划分为不予处罚、减轻处罚、从轻处罚、一般处罚、从重处罚等裁量阶次。 不予处罚是指依照法律、行政法规的规定，根据特定法定事由，对本应给予行政处罚的当事人不再给予行政处罚。 减轻处罚是指以少于法律、行政法规、规章规定的行政处罚种类或者低于处罚幅度的最低限，对当事人实施行政处罚。 从轻处罚是指在法律、行政法规、规章规定的行政处罚种类范围和处罚幅度内，选择较轻、较少的种类或者较低的幅度，对当事人实施行政处罚。 一般处罚是指在法律、行政法规、规章规定的行政处罚种类范围和处罚幅度内，选择适中的种类或者幅度，对当事人实施行政处罚。 从重处罚是指在法律、行政法规、规章规定的行政处罚种类范围和处罚幅度内，选择较重、较多的种类或者较高的幅度，对当事人实施行政处罚。"},{"i":6,"n":"第六条","txt":"法定罚款金额为一定幅度的，原则上在相应的幅度范围内，按照以下标准划分从轻处罚、一般处罚、从重处罚： （一）法定罚款幅度为20万元以上50万元以下的，从轻处罚、一般处罚、从重处罚的幅度分别为20万元至30万元（不含本数）、30万元至40万元（不含本数）、40万元至50万元； （二）法定罚款幅度为50万元以上200万元以下的，从轻处罚、一般处罚、从重处罚的幅度分别为50万元至100万元（不含本数）、100万元至150万元（不含本数）、150万元至200万元； （三）法定罚款幅度为200万元以上500万元以下的，从轻处罚、一般处罚、从重处罚的幅度分别为200万元至300万元（不含本数）、300万元至400万元（不含本数）、400万元至500万元； （四）法定罚款幅度为违法所得、营业收入等的1倍至5倍的，从轻处罚、一般处罚、从重处罚的幅度分别为违法所得的1倍至2倍（不含本数）、2倍至3.5倍（"},{"i":7,"n":"第七条","txt":"法律、行政法规、规章规定的行政处罚为特定种类或者特定数值的，原则上仅适用不予处罚、减轻处罚、一般处罚。 依法单独适用警告、通报批评，或者适用没收违法所得的，原则上仅适用不予处罚、一般处罚。"},{"i":8,"n":"第八条","txt":"当事人有下列情形之一的，依法不予处罚： （一）违法行为轻微并及时改正，没有造成危害后果的； （二）当事人有证据足以证明没有主观过错的，法律、行政法规另有规定的，从其规定； （三）符合《中华人民共和国行政处罚法》第三十条、第三十一条规定的不予处罚情形的； （四）符合法律、行政法规规定的其他不予处罚情形的。 当事人初次违法且危害后果轻微并及时改正的，中国人民银行及其分支机构可以不予处罚。 依法不予处罚的，中国人民银行或其分支机构应当对当事人进行教育。"},{"i":9,"n":"第九条","txt":"当事人有下列情形之一的，依法减轻处罚： （一）在中国人民银行或其分支机构开展执法检查或者案件调查前主动消除或者减轻违法行为危害后果，且违法行为轻微的； （二）受他人胁迫实施违法行为的； （三）在中国人民银行或其分支机构开展执法检查或者案件调查前主动供述执法检查或者案件调查实施单位尚未掌握的违法行为的，情节严重的除外； （四）配合中国人民银行或其分支机构查处违法行为有重大立功表现的； （五）在违法行为轻微的共同违法行为中起次要或者辅助作用的； （六）通过赔礼道歉、退赔损失等方式取得违法行为受害人谅解的； （七）违法行为显著轻微，且危害后果较小的； （八）符合《中华人民共和国行政处罚法》第三十条、第三十一条规定的减轻处罚情形的； （九）法律、行政法规、规章规定的其他减轻处罚情形的。"},{"i":10,"n":"第十条","txt":"当事人有下列情形之一的，依法从轻处罚： （一）在中国人民银行或其分支机构执法检查或者案件调查结束前主动消除或者减轻违法行为危害后果的； （二）受他人诱骗实施违法行为的； （三）在中国人民银行或其分支机构执法检查或者案件调查结束前主动供述执法检查或者案件调查实施单位尚未掌握的违法行为的； （四）配合中国人民银行或其分支机构查处违法行为有立功表现的； （五）在共同违法行为中起次要或者辅助作用的； （六）违法行为较轻，且危害后果不大的； （七）符合《中华人民共和国行政处罚法》第三十条、第三十一条规定的从轻处罚情形的； （八）法律、行政法规、规章规定的其他从轻处罚情形的。"},{"i":11,"n":"第十一条","txt":"当事人有下列情形之一的，依法从重处罚： （一）违法行为造成严重后果或者社会影响恶劣的； （二）违法行为持续时间长、发生次数多，违法交易规模大，违法业务占比大，受害人数量大，或者具有其他恶劣情节的； （三）不配合中国人民银行或其分支机构的执法活动，或者隐匿、销毁违法行为证据的； （四）受到中国人民银行或其分支机构行政处罚后五年内，再次实施相同违法行为的； （五）对举报人、证人、中国人民银行或其分支机构的工作人员进行打击报复的； （六）符合《中华人民共和国行政处罚法》第四十九条规定的从重处罚情形的； （七）其他性质恶劣或者造成严重影响的。"},{"i":12,"n":"第十二条","txt":"当事人不存在前述不予处罚、减轻处罚、从轻处罚、从重处罚情形的，原则上依法给予一般处罚，法律、行政法规、规章另有规定的除外。"},{"i":13,"n":"第十三条","txt":"法律、行政法规、规章规定违法行为情节严重才给予行政处罚，或者对情节严重情形另行设定罚款幅度的，裁量阶次划分为情节严重一档、情节严重二档、情节严重三档，每个裁量阶次对应的裁量幅度、具体情形等参照前述从轻处罚、一般处罚和从重处罚规定执行。"},{"i":14,"n":"第十四条","txt":"中国人民银行及其分支机构适用行政处罚裁量基准，判断违法行为情节、危害后果严重程度等，应当综合考虑以下因素： （一）违法行为的具体方法或者手段，以及当事人实施违法行为的主观过错程度； （二）违法行为的持续时间、发生次数，违法交易规模，违法业务占比，以及违法行为造成的社会影响、危害后果； （三）违法行为的危害对象及其数量； （四）当事人获取的违法所得； （五）当事人的生产经营规模、经营情况； （六）当事人改正违法行为的主观态度、所采取的整改措施及效果； （七）法律、行政法规、规章规定的其他因素。"},{"i":15,"n":"第十五条","txt":"当事人存在下列情况的，中国人民银行及其分支机构不再立案实施行政处罚： （一）违法事实不能成立，或者违法行为没有法定的行政处罚依据的； （二）违法行为在二年内未被发现的，涉及金融安全且有危害后果的，上述期限延长至五年，法律另有规定的除外； （三）法律、行政法规、规章规定违法行为情节严重才给予行政处罚，当事人的违法行为情节不严重的； （四）法律、行政法规、规章规定违法行为逾期不改正才给予行政处罚，当事人及时改正的。"},{"i":16,"n":"第十六条","txt":"中国人民银行及其分支机构在立案实施行政处罚时，针对当事人每一个独立违法行为，依据法律、行政法规、规章等的具体规定，在综合考虑本规定第十四条规定的因素的基础上，对照行政处罚裁量基准，依法确定对每一个违法行为给予的行政处罚，而后合并计算对当事人的整体行政处罚。 独立违法行为的认定标准，由中国人民银行根据违法行为的具体情况、严重程度、社会危害性以及当事人的主观过错等另行确定。"},{"i":17,"n":"第十七条","txt":"当事人的同一个违法行为同时具有两个或者两个以上从轻处罚情形，且不具有从重处罚情形的，可以减轻处罚。"},{"i":18,"n":"第十八条","txt":"对当事人的同一违法行为，不得给予两次以上罚款的行政处罚。 当事人同一个违法行为违反多个法律规范应当给予罚款处罚的，按照罚款数额较高的规定处罚。"},{"i":19,"n":"第十九条","txt":"当事人违法行为有违法所得的，应当按照法律、行政法规等的规定予以没收。 违法所得是指实施违法行为所取得的款项，原则上该款项的获得应当与当事人实施相关违法行为具有直接因果关系。计算违法所得时，以下款项可以予以扣除： （一）在行政处罚决定作出前已经依法退赔的； （二）当事人有证据证明已经缴纳的税款、已经支付的行政事业性收费和政府性基金等； （三）当事人有证据证明相关款项是按照相关规定为其他主体代收的； （四）法律、行政法规、规章规定的其他款项。"},{"i":20,"n":"第二十条","txt":"法律、行政法规、规章规定对法人、非法人组织给予行政处罚的同时，对相关责任人员给予行政处罚的，原则上应当参照对法人、非法人组织违法行为给予行政处罚的裁量阶次，确定应当对该违法行为承担责任的责任人员的行政处罚裁量阶次。 中国人民银行及其分支机构应当综合考虑相关责任人员的岗位职责、任职时间、履职行为与违法行为的关联性、主观过错程度、主次责任，以及是否对违法行为采取整改措施等因素，在行政处罚裁量阶次内，确定适当的行政处罚。 相关责任人员确有应当不予处罚、减轻处罚或者从轻处罚情形的，依法不予处罚、减轻处罚或者从轻处罚。"},{"i":21,"n":"第二十一条","txt":"当事人的生产经营规模较小，对行政处罚的承受能力较低的，可以结合违法行为的严重程度、社会危害性以及当事人的主观过错程度等因素减轻处罚、从轻处罚。 中国人民银行分支机构拟适用前款规定减轻处罚的，应当按照相关规定经中国人民银行批准。"},{"i":22,"n":"第二十二条","txt":"中国人民银行及其分支机构根据本规定确定拟给予的行政处罚后，应当按照《中华人民共和国行政处罚法》《中国人民银行行政处罚程序规定》等规定的具体程序，依法作出行政处罚决定。 中国人民银行及其分支机构实施行政处罚时或者实施行政处罚前，应当责令当事人改正或者限期改正违法行为。 除法律、行政法规、规章另有规定外，不得仅以当事人完成整改，或者对相关责任人员进行内部追责、问责等作为不予处罚的理由。"},{"i":23,"n":"第二十三条","txt":"适用本规定可能出现明显不当、显失公平，或者行政处罚裁量基准适用的客观情况发生变化的，经中国人民银行行长批准或者中国人民银行行政处罚委员会集体审议通过，可以依法调整适用。批准材料或者集体审议记录应当作为行政处罚案卷的一部分归档保存。 中国人民银行分支机构因前述情况拟调整适用本规定的，应当经中国人民银行批准。"},{"i":24,"n":"第二十四条","txt":"中国人民银行结合工作实际，通过适当形式指导各分支机构规范适用行政处罚裁量基准，并通过行政执法情况检查、行政执法案卷评查等方式，加强对行政处罚裁量基准执行情况的监督。"},{"i":25,"n":"第二十五条","txt":"本规定由中国人民银行负责解释。"},{"i":26,"n":"第二十六条","txt":"本规定自2025年1月1日起施行。"}],"zhongguorenminyinhangxingzhengfuyibanfa":[{"i":1,"n":"第一条","txt":"为了规范中国人民银行及其分支机构行政复议工作，保护公民、法人和其他组织的合法权益，监督和保障依法行使职权，发挥行政复议化解行政争议的主渠道作用，推进法治政府建设，根据《中华人民共和国行政复议法》（以下简称《行政复议法》）及其实施条例、《中华人民共和国中国人民银行法》等法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织认为中国人民银行及其分支机构的行政行为侵犯其合法权益，依法提出行政复议申请，中国人民银行及其分支机构办理行政复议案件，适用本办法。 前款所称行政行为，包括中国人民银行及其分支机构管理的法律、法规和规章授权的组织作出的行政行为。"},{"i":3,"n":"第三条","txt":"行政复议工作坚持中国共产党的领导。 中国人民银行及其分支机构履行行政复议职责，应当遵循合法、公正、公开、高效、便民、为民的原则，坚持有错必纠，保障法律、法规的正确实施。"},{"i":4,"n":"第四条","txt":"本办法所称行政复议机关是履行行政复议职责的中国人民银行及其分支机构。 本办法所称行政复议机构，是中国人民银行及其分支机构中负责法治工作的部门，负责办理行政复议事项，同时组织办理行政复议机关的行政应诉事项。 中国人民银行及其分支机构相关业务部门参与办理涉及本部门业务的行政复议案件。"},{"i":5,"n":"第五条","txt":"中国人民银行统一领导中国人民银行各分支机构的行政复议工作。上级行政复议机构对下级行政复议机构的行政复议工作进行指导、监督。"},{"i":6,"n":"第六条","txt":"中国人民银行及其分支机构应当依法配备与履行行政复议职责相适应的行政复议人员。 中国人民银行及其分支机构应当加强对行政复议人员的培训，提高行政复议人员专业素质。 中国人民银行及其分支机构应当根据工作需要，提供办案场所、装备等设施和其他必要的工作条件。行政复议工作所需经费列入本级预算。"},{"i":7,"n":"第七条","txt":"公民、法人或者其他组织可以依照《行政复议法》及其实施条例规定的行政复议范围，向中国人民银行及其分支机构申请行政复议。"},{"i":8,"n":"第八条","txt":"申请人委托代理人参加行政复议，应当提交授权委托书、委托人及被委托人的身份证明文件。授权委托书应当载明委托事项、权限和期限，并由申请人签名、盖章或者按指印确认。"},{"i":9,"n":"第九条","txt":"申请人以外的同被申请行政复议的行政行为或者行政复议案件处理结果有利害关系的公民、法人或者其他组织，可以自行申请或者经行政复议机构通知作为第三人参加行政复议。 第三人不参加行政复议，不影响行政复议案件的审理。"},{"i":10,"n":"第十条","txt":"公民、法人或者其他组织对行政行为不服申请行政复议的，作出行政行为的中国人民银行及其分支机构或者法律、法规和规章授权的组织是被申请人。 作出行政行为的中国人民银行分支机构被撤销或者职权变更的，继续行使其职权的机构是被申请人。"},{"i":11,"n":"第十一条","txt":"公民、法人或者其他组织向中国人民银行及其分支机构提出行政复议申请，应当遵守法律规定的申请期限。因不可抗力或者其他正当理由耽误法定申请期限的，申请期限自障碍消除之日起继续计算。申请人提出行政复议申请时应当同时提供法定申请期限被耽误的相关证明材料。"},{"i":12,"n":"第十二条","txt":"申请人申请行政复议，可以书面申请。书面申请应当附相关材料及申请人的身份证明文件；申请人为法人或者其他组织的，应当提供法定代表人（主要负责人）身份证明文件。 书面申请有困难的，可以口头申请。申请人口头申请行政复议的，中国人民银行及其分支机构应当当场记录申请人的基本情况、行政复议请求、申请行政复议的主要事实、理由和时间。 申请人对两个以上行政行为不服的，应当分别申请行政复议。"},{"i":13,"n":"第十三条","txt":"行政复议申请书应当载明下列事项： （一）申请人的基本情况，包括公民的姓名、性别、身份证号码、住所、送达地址、联系方式；法人或者其他组织的名称、统一社会信用代码、住所、送达地址、联系方式和法定代表人或者主要负责人的姓名、职务； （二）被申请人的名称； （三）行政复议请求、申请行政复议的主要事实和理由； （四）申请人签名、盖章或者按指印； （五）申请行政复议的日期。"},{"i":14,"n":"第十四条","txt":"申请人撤回行政复议申请的，行政复议机构可以同意。"},{"i":15,"n":"第十五条","txt":"对中国人民银行作出的行政行为不服的，向中国人民银行申请行政复议。 对中国人民银行分支机构作出的行政行为不服的，向其上一级行申请行政复议。对中国人民银行深圳市分行作出的行政行为不服的，向中国人民银行申请行政复议；对中国人民银行大连市、宁波市、青岛市、厦门市分行作出的行政行为不服的，向该分行所在地省级分行申请行政复议。 对法律、法规、规章授权的组织作出的行政行为不服的，向管理该组织的中国人民银行及其分支机构申请行政复议。"},{"i":16,"n":"第十六条","txt":"公民、法人或者其他组织向中国人民银行及其分支机构申请行政复议，中国人民银行及其分支机构已经依法受理的，在行政复议期间不得向人民法院提起行政诉讼。公民、法人或者其他组织向人民法院提起行政诉讼，人民法院已经依法受理的，不得申请行政复议。"},{"i":17,"n":"第十七条","txt":"行政复议机关收到行政复议申请后，应当在五个工作日内依法进行审查，符合法定受理条件的，应当予以受理。 对不符合法定受理条件的行政复议申请，行政复议机关应当在审查期限届满前作出不予受理决定，并说明理由。不属于本机关管辖的，还应当在不予受理决定书中告知申请人有管辖权的行政复议机关。 行政复议申请的审查期限届满，行政复议机关未作出不予受理决定的，审查期限届满之日起视为受理。"},{"i":18,"n":"第十八条","txt":"行政复议机关收到行政复议申请后，经审查认为依法需要申请人补正的，应当自收到申请之日起五个工作日内书面通知申请人补正。补正通知应当一次性载明需要补正的事项、补正期限以及无正当理由逾期未补正的法律后果等内容。 申请人应当自收到补正通知之日起十个工作日内提交补正材料。有正当理由不能按期补正的，行政复议机关可以延长合理的补正期限。无正当理由逾期不补正的，视为申请人放弃行政复议申请，并记录在案。 行政复议机关自收到补正材料之日起，重新计算行政复议受理审查期限。"},{"i":19,"n":"第十九条","txt":"行政复议机关受理行政复议申请后，依法适用普通程序或者简易程序进行审理。 行政复议机关认为行政复议案件事实清楚、权利义务关系明确、争议不大，或者当事人各方同意的，可以依法适用简易程序。 行政复议机构应当指定行政复议人员负责办理行政复议案件。 行政复议人员对办理行政复议案件过程中知悉的国家秘密、商业秘密和个人隐私，应当予以保密。"},{"i":20,"n":"第二十条","txt":"行政复议机关依照法律、法规和规章审理行政复议案件。"},{"i":21,"n":"第二十一条","txt":"上级行政复议机关根据需要，可以审理下级行政复议机关管辖的行政复议案件。 下级行政复议机关对其管辖的行政复议案件，认为需要由上级行政复议机关审理的，可以报请上级行政复议机关决定。"},{"i":22,"n":"第二十二条","txt":"适用普通程序审理的行政复议案件，行政复议机构应当自行政复议申请受理之日起七个工作日内，制作答复通知，连同行政复议申请材料副本发送被申请人。 被申请人应当自收到行政复议答复通知之日起十个工作日内提交书面行政复议答复，并提交作出行政行为的证据、依据和其他有关材料。"},{"i":23,"n":"第二十三条","txt":"适用简易程序审理的行政复议案件，行政复议机构应当自受理行政复议申请之日起三个工作日内，制作答复通知，连同行政复议申请材料副本发送被申请人。答复通知应当载明案件适用简易程序等内容。 被申请人应当自收到行政复议答复通知之日起五个工作日内提交书面行政复议答复，并提交作出行政行为的证据、依据和其他有关材料。"},{"i":24,"n":"第二十四条","txt":"申请人依法对被复议的行政行为所依据的规范性文件提出附带审查申请，有权处理的，行政复议机构应当转送中国人民银行及其分支机构相关业务部门办理；无权处理的，行政复议机构应当转送有权处理的行政机关处理。"},{"i":25,"n":"第二十五条","txt":"行政复议机关有权依法向有关单位和个人调查取证。调查取证时，行政复议人员不得少于两人，并应当向有关单位和个人出示行政复议工作证件。调查取证的过程可以根据需要记录，需被调查人员（单位）签字（盖章）确认的，被调查人员（单位）应当予以配合。"},{"i":26,"n":"第二十六条","txt":"适用普通程序审理的行政复议案件，行政复议机构应当当面或者通过互联网、电话等方式听取当事人的意见，并将听取的意见记录在案。当面听取当事人意见的，应当制作记录，由当事人签字确认。因当事人原因不能听取意见的，行政复议机构可以书面审理。 适用简易程序审理的行政复议案件，行政复议机构可以书面审理。"},{"i":27,"n":"第二十七条","txt":"行政复议机构审理重大、疑难、复杂的案件，依法组织听证的，应当于举行听证的五个工作日前制发书面通知，将听证的时间、地点和拟听证事项等通知当事人。 听证可以通过陈述、申辩、举证、质证等形式进行。听证应当制作相关记录，由参加听证人员核对无误后签字确认。参加听证人员拒绝签字确认的，听证员在笔录中记录相关情况。"},{"i":28,"n":"第二十八条","txt":"行政复议期间有法定中止或者终止情形的，行政复议机关应当书面告知当事人。 行政复议中止的原因消除后，行政复议机关应当及时恢复行政复议案件的审理，并书面告知当事人。 行政复议期间，行政复议机关无正当理由中止行政复议的，上级行政机关应当责令其恢复审理。"},{"i":29,"n":"第二十九条","txt":"行政复议期间，申请人、第三人及被委托人需要查阅、复制被申请人书面答复等相关材料的，可以向行政复议机构提出申请。 行政复议机构安排现场查阅、复制的，应当依法告知申请人、第三人及被委托人查阅、复制的时间和地点。行政复议人员应当在场。申请人、第三人及被委托人应当向行政复议人员出示身份证明文件，被委托人还应当提交授权委托材料。 申请人、第三人及被委托人在查阅、复制过程中不得有涂改、毁损、隐匿、调换等行为。"},{"i":30,"n":"第三十条","txt":"行政复议机关办理行政复议案件可以依法进行调解。当事人在行政复议决定作出前可以自愿达成和解。 调解与和解不得损害国家利益、社会公共利益和他人合法权益，不得违反法律、法规的强制性规定。"},{"i":31,"n":"第三十一条","txt":"行政复议机关依法审理行政复议案件，由行政复议机构对行政行为进行审查，提出意见，经行政复议机关负责人同意或者集体讨论通过后，以行政复议机关的名义作出行政复议决定。"},{"i":32,"n":"第三十二条","txt":"公民、法人或者其他组织对中国人民银行及其分支机构作出的行政复议决定不服的，可以依法向人民法院提起行政诉讼。对中国人民银行就本单位行政行为作出的行政复议决定不服的，也可以依法向国务院申请裁决。"},{"i":33,"n":"第三十三条","txt":"行政复议机关在办理行政复议案件过程中，发现被申请人或者其他下级行的有关行政行为违法或者不当的，可以向其制发行政复议意见书。有关机关应当自收到行政复议意见书之日起六十日内，将纠正相关违法或者不当行政行为的情况报送行政复议机关。"},{"i":34,"n":"第三十四条","txt":"中国人民银行及其分支机构可以根据工作需要建立由有关部门、专家、学者等参与的行政复议委员会，为办理行政复议案件提供咨询意见，并就行政复议工作中的重大事项和共性问题研究提出意见。"},{"i":35,"n":"第三十五条","txt":"中国人民银行及其分支机构工作人员在行政复议活动中，徇私舞弊或者有其他渎职、失职行为的，依法给予处分；涉嫌构成犯罪的，移送司法机关依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"被申请人违反法律规定，不提出书面答复或者不提交作出行政行为的证据、依据和其他有关材料，或者阻挠、变相阻挠公民、法人或者其他组织依法申请行政复议的，对负有责任的领导人员和直接责任人员依法给予处分；涉嫌构成犯罪的，移送司法机关依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"被申请人不履行或者无正当理由拖延履行行政复议决定书、调解书、意见书的，对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":38,"n":"第三十八条","txt":"拒绝、阻挠中国人民银行及其分支机构行政复议人员调查取证，故意扰乱行政复议工作秩序的，依法给予处分、治安管理处罚；涉嫌构成犯罪的，移送司法机关依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"中国人民银行及其分支机构办理行政复议案件可以使用行政复议专用章。"},{"i":40,"n":"第四十条","txt":"外国人、无国籍人、外国组织在中华人民共和国境内向中国人民银行及其分支机构申请行政复议，适用本办法。"},{"i":41,"n":"第四十一条","txt":"本办法由中国人民银行负责解释。"},{"i":42,"n":"第四十二条","txt":"本办法自2026年3月1日起施行。《中国人民银行行政复议办法》（中国人民银行令〔2001〕第4号发布）同时废止。"}],"zhongguorenminyinhangxingzhengxukeshishibanfa":[{"i":1,"n":"第一条","txt":"为了规范中国人民银行及其分支机构实施行政许可的行为，保护公民、法人和其他组织的合法权益，根据《中华人民共和国行政许可法》和《中华人民共和国中国人民银行法》，制定本办法。"},{"i":2,"n":"第二条","txt":"中国人民银行及其分支机构实施行政许可适用本办法。 中国人民银行对其直接管理的事业单位的人事、财务、外事等事项的审批，不适用本办法。 中国人民银行及其分支机构根据相关规定对公民、法人或者其他组织申请接入中国人民银行及其直接管理的事业单位等建设、运营的信息化系统进行审核的，不适用本办法。"},{"i":3,"n":"第三条","txt":"中国人民银行应当在法定职权范围内依法实施行政许可；中国人民银行分支机构应当在中国人民银行授权范围内依法实施行政许可。"},{"i":4,"n":"第四条","txt":"中国人民银行及其分支机构实施行政许可，应当依照法定的权限、范围、条件和程序，遵循公开、公平、公正、便民、高效、非歧视的原则。"},{"i":5,"n":"第五条","txt":"中国人民银行及其分支机构实施行政许可的依据为法律、行政法规、国务院决定、规章。 规章和规范性文件中不得增设行政许可，不得增设违反法律、行政法规和国务院决定的行政许可条件。"},{"i":6,"n":"第六条","txt":"中国人民银行及其分支机构依法保护申请人的商业秘密和个人隐私。 行政许可的实施和结果，除涉及国家秘密、工作秘密、商业秘密或者个人隐私的外，应当公开。"},{"i":7,"n":"第七条","txt":"中国人民银行及其分支机构推进行政许可电子办理，提高办事效率，提供优质服务。 申请人通过电子政务系统提出申请的，符合相关要求的电子申请材料、电子证照、电子印章、电子签名、电子档案与纸质申请材料、纸质证照、实物印章、手写签名或者盖章、纸质档案具有同等法律效力。 中国人民银行及其分支机构通过电子政务系统向申请人发送的相关文书、颁布的各种决定书和行政许可证，与纸质文件具有同等法律效力。"},{"i":8,"n":"第八条","txt":"中国人民银行及其分支机构依法制作行政许可事项服务指南，按规定在办公场所、互联网站公示行政许可事项及其适用范围、审查类型、审批依据、受理机构和相关职能部门、决定机构、申请条件、申请接受方式和接受地址、办理基本流程和办理方式、办理时限、审批结果和送达方式、收费依据、监督投诉渠道等信息，以及需要提交的全部材料的目录和申请书示范文本。 申请人要求对公示内容予以说明、解释的，中国人民银行及其分支机构应当说明、解释，并提供准确、可靠的信息。"},{"i":9,"n":"第九条","txt":"公民、法人或者其他组织从事特定活动，依法需要取得中国人民银行或其分支机构行政许可的，应当向中国人民银行或其分支机构提出申请。 申请书需要采用格式文本的，该格式文本由中国人民银行统一公布，并通过电子政务系统提供下载，或者由承办行政许可事项的职能部门提供。申请书格式文本中不得包含与申请行政许可事项没有直接关系的内容；不得要求申请人提交与其申请的行政许可事项无关的技术资料和其他材料。 申请人可以当面提交行政许可申请，也可以通过电子政务系统提出，并按照行政许可事项服务指南在指定地点提交或者通过电子政务系统在线提交申请材料。"},{"i":10,"n":"第十条","txt":"申请人提出的行政许可申请，由中国人民银行及其分支机构承办行政许可事项的职能部门负责审查受理。 依法应当由中国人民银行下级行先行审查后报上级行决定的行政许可事项的申请，由下级行承办行政许可事项的职能部门受理；需要多个职能部门办理的申请，由中国人民银行确定一个职能部门统一受理、牵头办理。"},{"i":11,"n":"第十一条","txt":"申请人提交行政许可申请时，应当出示身份证明文件；单位申请的，应当出示单位统一社会信用代码证或者营业执照，以及法定代表人身份证明文件或者主要负责人身份证明文件、授权委托书、被委托人身份证件等身份证明文件。 申请人可以委托代理人提出行政许可申请。申请人委托代理人提出行政许可申请的，还应当提供申请人、代理人的身份证明文件和授权委托书；办理开户许可等事项，由商业银行等机构批量代理提交的除外。 中国人民银行及其分支机构应当核对上述身份证明文件，必要时可以利用技术手段核实申请人身份。"},{"i":12,"n":"第十二条","txt":"申请人向中国人民银行或其分支机构申请行政许可，应当如实提交有关材料和反映真实情况，并对其申请材料实质内容的真实性负责。 中国人民银行及其分支机构有权要求申请人提供申请材料真实性声明。"},{"i":13,"n":"第十三条","txt":"申请人提交申请材料，中国人民银行及其分支机构应当及时办理登记手续，并向申请人出具申请材料接收凭证，载明申请材料接收日期；当场出具行政许可受理通知书、不予受理决定书、补正告知书等的，可以不再出具申请材料接收凭证。 申请人现场办理的，申请材料接收凭证应当由申请人或者其代理人签字确认。"},{"i":14,"n":"第十四条","txt":"中国人民银行及其分支机构收到申请人提出的行政许可申请，发现申请事项依法不需要取得行政许可的，应当即时告知申请人不受理；发现申请事项属于中国人民银行职权范围，但不属于本级机构受理的，应当即时向申请人说明情况，并告知其向有权受理的机构提出申请。"},{"i":15,"n":"第十五条","txt":"中国人民银行及其分支机构收到申请人提出的行政许可申请，发现申请材料存在错误可以当场更正的，应当允许申请人当场更正。"},{"i":16,"n":"第十六条","txt":"申请材料不齐全、不符合法定形式或者存在错误不能当场更正的，中国人民银行及其分支机构应当当场或者在收到申请材料之日起五日内一次告知申请人需要补正的全部内容，出具加盖本行行政许可专用章并载明日期的补正告知书。逾期不告知的，自收到申请材料之日起即为受理。 申请人拒不补正，或者自补正告知书送达之日起十日内无正当理由未补正的，视为放弃行政许可申请，中国人民银行及其分支机构应当退回已经收到的全部申请材料。"},{"i":17,"n":"第十七条","txt":"申请人提出的行政许可申请存在下列情形之一的，中国人民银行及其分支机构可以不予受理，并出具加盖本行行政许可专用章的不予受理决定书，说明不予受理的理由和依据，退回已经收到的全部申请材料： （一）申请事项不属于中国人民银行职权范围的； （二）申请人提供的补正材料不齐全、不符合法定形式的； （三）申请人补正后仍存在不符合受理条件的其他情形的。 中国人民银行及其分支机构依据前款第一项不予受理的，应当即时作出不予受理的决定，并告知申请人向有关行政机关申请。 依法由中国人民银行下级行先行审查后报上级行决定的行政许可事项的申请，由下级行出具不予受理决定书。"},{"i":18,"n":"第十八条","txt":"申请事项属于中国人民银行职权范围，申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正申请材料的，中国人民银行及其分支机构应当受理行政许可申请。 依前款规定受理行政许可的，中国人民银行及其分支机构应当于收到申请材料或者全部补正申请材料之日起五日内，出具加盖本行行政许可专用章并注明受理日期的行政许可受理通知书。 依法由中国人民银行下级行先行审查后报上级行决定的行政许可事项的申请，由下级行出具行政许可受理通知书。"},{"i":19,"n":"第十九条","txt":"中国人民银行及其分支机构依法对申请人提交的申请材料进行审查。需要对申请材料的实质内容进行核实的，中国人民银行及其分支机构应当指派两名以上工作人员，根据法定条件和程序进行。"},{"i":20,"n":"第二十条","txt":"行政许可事项依法由中国人民银行下级行先行审查后报上级行决定的，下级行应当将初步审查意见和全部申请材料直接报送上级行。 上级行在审查该行政许可事项时，不得要求申请人重复提供申请材料。"},{"i":21,"n":"第二十一条","txt":"中国人民银行及其分支机构审查行政许可申请时，发现行政许可事项直接关系他人重大利益的，应当告知该利害关系人。 申请人、利害关系人有权进行陈述和申辩，并自被告知之日起三日内提交陈述、申辩意见；对于口头陈述、申辩的，中国人民银行及其分支机构应当做好记录，并交陈述人、申辩人签字确认。 中国人民银行及其分支机构应当听取申请人、利害关系人的意见。"},{"i":22,"n":"第二十二条","txt":"中国人民银行及其分支机构在审查过程中发现申请人提交的申请材料存在实质性问题，可能影响作出行政许可决定的，可以要求申请人限期对申请材料进一步修改、完善，或者解释说明。 申请人在合理期限内拒不修改、完善、解释说明，或者修改、完善、解释说明后仍存在实质性问题的，中国人民银行及其分支机构应当继续审查，不利后果由申请人承担。"},{"i":23,"n":"第二十三条","txt":"中国人民银行及其分支机构可以通过实地调查、面谈等方式对申请材料进行核实。申请人或者有关人员应当配合；拒不配合的，应当自行承担相关不利后果。 通过实地调查、面谈等现场方式进行核实的，中国人民银行及其分支机构的工作人员应当出示证件，并制作核实记录。"},{"i":24,"n":"第二十四条","txt":"中国人民银行及其分支机构在审查过程中，有下列情形之一的，可以作出中止审查的决定，并书面通知申请人，法律、行政法规、国务院决定、规章另有规定的除外： （一）申请人因涉嫌违法违规被中国人民银行或者其他行政机关调查，或者被司法机关侦查，尚未结案，对行政许可事项影响重大的； （二）申请人被中国人民银行或者其他行政机关依法采取限制业务活动、责令停业整顿等监管措施，尚未解除的； （三）申请人被中国人民银行或者其他行政机关接管，接管期限尚未届满的； （四）对有关法律、行政法规、国务院决定、规章的规定，需要进一步明确具体含义，中国人民银行及其分支机构请求有关机关作出解释的； （五）申请人主动要求中止审查，且有正当理由的。 因前款第一项至第四项规定情形中止审查的，相关情形消失后，中国人民银行及其分支机构恢复审查，并书面通知申请人。 申请人主动要求中止审查或者申请恢复审查的，应当向受理行政许可申请的中国人"},{"i":25,"n":"第二十五条","txt":"中国人民银行及其分支机构对行政许可申请进行审查后，应当根据下列情况分别作出处理： （一）申请符合法定条件、标准，拟准予行政许可的，应当拟定准予行政许可决定书； （二）申请不符合法定条件、标准，拟不予行政许可的，应当拟定不予行政许可决定书。"},{"i":26,"n":"第二十六条","txt":"中国人民银行及其分支机构按照相关规定对行政许可决定实施法制审核，确保行政许可主体合法、程序合规、证据充分、法律适用准确。"},{"i":27,"n":"第二十七条","txt":"准予行政许可或者不予行政许可决定书由作出行政许可的中国人民银行或其分支机构行长（主任）或者分管副行长（副主任）审查批准。"},{"i":28,"n":"第二十八条","txt":"准予行政许可或者不予行政许可决定书应当统一编号、加盖本行行章，并注明日期。 准予行政许可决定书应当明确行政许可的效力范围、有效期限、变更及延续方式等事项。 不予行政许可决定书应当说明不予行政许可的理由，并告知申请人享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":29,"n":"第二十九条","txt":"中国人民银行及其分支机构作出准予行政许可决定，依照法律、行政法规、国务院决定、规章的规定需要颁发行政许可证的，依法向申请人颁发加盖本行行章的行政许可证，可以不再制作行政许可决定书。"},{"i":30,"n":"第三十条","txt":"中国人民银行及其分支机构作出行政许可决定前，申请人撤回申请的，应当提交正式书面请求，并说明理由。 申请人撤回申请的，中国人民银行及其分支机构应当退回已经收到的全部申请材料。"},{"i":31,"n":"第三十一条","txt":"除根据本办法适用简易程序作出行政许可决定的外，中国人民银行及其分支机构应当自受理行政许可申请之日起二十日内，作出行政许可决定。二十日内不能作出决定的，经本行行长（主任）批准，可以延长十日，并应当将延长期限的理由告知申请人。但法律、行政法规、国务院决定另有规定的，依照其规定。"},{"i":32,"n":"第三十二条","txt":"依法由中国人民银行下级行审查后报上级行决定的行政许可事项申请，下级行应当自受理申请之日起二十日内审查完毕，并将初步审查意见和申请材料移交上级行。 上级行应当自收到申请材料和下级行初步审查意见之日起二十日内，作出是否准予行政许可的决定。 但法律、行政法规、国务院决定另有规定的，依照其规定。"},{"i":33,"n":"第三十三条","txt":"中国人民银行及其分支机构作出行政许可决定，下列时间不计入本节规定的期限内： （一）依照法律、行政法规、国务院决定、规章的规定需要检验、检测、鉴定和专家评审，或者需要听证的； （二）依照法律、行政法规、国务院决定、规章的规定需要公示相关信息的； （三）依照相关规定需要进行国家安全审查的； （四）申请材料存在实质性问题，需要进一步修改、完善的，或者需要申请人进一步解释说明的； （五）需要对行政许可申请进行实地核查，以及听取申请人、利害关系人陈述、申辩的； （六）在行政许可过程中收到对申请人相关违法违规行为的举报，需要进行核查的； （七）依据本办法第二十四条规定中止审查的。 发生前款第一项、第二项所列情形的，中国人民银行及其分支机构应当将所需时间书面告知申请人。"},{"i":34,"n":"第三十四条","txt":"对于受理、不予受理或者要求补正申请材料的通知书，除即时告知的外，应当自相关文书作出之日起五日内送达当事人。"},{"i":35,"n":"第三十五条","txt":"中国人民银行及其分支机构作出准予行政许可决定的，应当自作出决定之日起十日内向申请人送达准予行政许可的书面决定或者行政许可证。 中国人民银行及其分支机构作出不予行政许可决定的，应当自作出决定之日起十日内向申请人送达不予行政许可的书面决定。"},{"i":36,"n":"第三十六条","txt":"申请人应当在申请行政许可时，选择相关文书、许可证的送达方式，并如实告知通讯地址、联系方式等信息。 申请人选择邮寄送达的，邮件签收，视为送达；邮件因地址错误、拒收等原因被退回的，到达上述地址，视为送达。 申请人选择自行领取或者代理人领取的，应当按照中国人民银行及其分支机构通知的时间及时领取相关文书、许可证，并应当在领取时参照本办法第十一条的要求出示身份证明文件和授权委托书等，予以签收。 办理开户许可等事项，由商业银行等机构批量代理提交的行政许可申请，中国人民银行及其分支机构一般采取由提交行政许可申请的商业银行等机构代为送达的方式，相关文书、许可证送交提交行政许可申请的商业银行等机构的，视为送达。申请人明确提出通过邮寄、自行领取等方式送达的除外。 申请人或者代理人在接到领取通知十日内不领取相关文书、许可证且无法通过邮寄等方式送达的，可以公告送达，公告期为两个月。公告期满，视为送达。"},{"i":37,"n":"第三十七条","txt":"申请人通过电子政务系统提出行政许可申请的，中国人民银行及其分支机构可以通过电子政务系统，以电子形式出具本办法规定的申请材料接收凭证、补正告知书、行政许可受理通知书、不予受理决定书、准予行政许可决定书、不予行政许可决定书等。 申请人在电子政务系统完成申请书填写，并完成申请材料提交的日期为该行政许可的申请日期；中国人民银行及其分支机构通过电子政务系统以电子形式出具文书并能够被申请人查阅，视为送达。"},{"i":38,"n":"第三十八条","txt":"法律、行政法规、国务院决定、规章规定实施行政许可应当听证的事项，或者中国人民银行及其分支机构认为需要听证的其他涉及公共利益的重大行政许可事项，应当向社会公告，并举行听证。"},{"i":39,"n":"第三十九条","txt":"行政许可直接涉及申请人与他人之间重大利益关系的，中国人民银行及其分支机构在作出行政许可决定前，应当告知申请人、利害关系人享有要求听证的权利；申请人、利害关系人在被告知听证权利之日起五日内提出听证申请的，中国人民银行或其分支机构应当在收到听证申请之日起二十日内组织听证。 申请人、利害关系人不承担中国人民银行及其分支机构组织听证的费用。"},{"i":40,"n":"第四十条","txt":"听证由中国人民银行及其分支机构法律事务部门组织，按照下列程序公开举行： （一）中国人民银行及其分支机构应当于举行听证的七日前将听证的时间、地点通知申请人、利害关系人，必要时予以公告； （二）听证由中国人民银行及其分支机构法律事务部门工作人员担任主持人，或者由本行行长（主任）或者分管副行长（副主任）指定该行政许可事项承办部门以外的其他部门的工作人员担任主持人；申请人、利害关系人认为主持人与该行政许可事项有直接利害关系的，有权申请回避；听证主持人是否回避，由本行行长（主任）或者分管副行长（副主任）决定； （三）举行听证时，承办行政许可事项的职能部门应当提供作出审查意见的证据、理由；申请人、利害关系人可以提出证据，并进行申辩和质证； （四）听证应当由听证主持人指定专人记录并制作听证笔录，笔录的内容包括：举行听证的时间、地点、参加听证的人员、听证事项、听证当事人的意见。 听证笔录应当交听证当事"},{"i":41,"n":"第四十一条","txt":"申请人、利害关系人根据本办法第三十九条提出的听证申请，中国人民银行及其分支机构开始听证前，听证申请人可以书面提出撤回听证申请，并说明理由。 听证申请人撤回听证申请的，视为放弃听证权利，不得再次就同一行政许可事项提出听证申请。"},{"i":42,"n":"第四十二条","txt":"行政许可事项简单、审查标准明确，申请人以格式文书提出申请，材料齐全、符合法定形式，且申请事项依据有关规定能够于当场或者五日内确认准予行政许可的，中国人民银行及其分支机构可以适用简易程序作出行政许可。 适用简易程序的行政许可事项，在行政许可事项服务指南中载明，并由中国人民银行公布。"},{"i":43,"n":"第四十三条","txt":"适用简易程序的，由承办行政许可事项的职能部门根据本行行长（主任）或者分管副行长（副主任）的授权，在受理行政许可后及时制作准予行政许可决定书或者依据有关规定制发行政许可证。 适用简易程序作出行政许可决定的，可以不再出具申请材料接收凭证、行政许可受理通知书等过程性文书，并适当简化内部审批流程。"},{"i":44,"n":"第四十四条","txt":"中国人民银行及其分支机构在按照简易程序审查的过程中，发现申请人提交的申请材料存在实质性问题，不能在五日内准予行政许可的，应当告知申请人，并按照本办法第二章的相关规定处理相关行政许可申请。"},{"i":45,"n":"第四十五条","txt":"被许可人拟变更下列事项的，应当向作出行政许可决定的中国人民银行或其分支机构提出申请，法律、行政法规、国务院决定、规章另有规定的除外；符合法定条件、标准的，中国人民银行及其分支机构应当依法办理变更手续： （一）变更准予行政许可决定书或者行政许可证记载事项的； （二）变更根据法律、行政法规、国务院决定、规章规定应当经中国人民银行或其分支机构批准变更的事项的。"},{"i":46,"n":"第四十六条","txt":"被许可人需要延续行政许可有效期的，应当在该行政许可有效期届满六个月前向作出行政许可决定的中国人民银行或其分支机构提出申请。但法律、行政法规、国务院决定、规章另有规定的，依照其规定。"},{"i":47,"n":"第四十七条","txt":"中国人民银行及其分支机构应当根据被许可人的申请，按照法律、行政法规、国务院决定、规章规定的行政许可条件，综合被许可人在该行政许可有效期内的合规经营情况，在行政许可有效期届满前作出是否准予延续的决定。 被许可人不符合法律、行政法规、国务院决定、规章规定的行政许可条件，或者在该行政许可有效期内存在重大违法违规行为的，中国人民银行及其分支机构应当不再准予延续。"},{"i":48,"n":"第四十八条","txt":"中国人民银行及其分支机构受理、审查、决定被许可人变更和延续申请的程序，以及适用简易程序的，本章有规定的，适用本章规定；本章没有规定的，适用本办法第二章的有关规定。法律、行政法规、国务院决定、规章另有规定的，依照其规定。"},{"i":49,"n":"第四十九条","txt":"中国人民银行及其分支机构依法对行政许可办理过程进行记录，完善行政许可案卷管理制度。"},{"i":50,"n":"第五十条","txt":"中国人民银行及其分支机构上级行依法对下级行实施行政许可的情况进行监督，及时纠正下级行实施行政许可中的违法违规行为。"},{"i":51,"n":"第五十一条","txt":"中国人民银行及其分支机构可以要求被许可人提供从事行政许可事项活动情况的有关材料，有权对被许可人从事行政许可事项的活动进行现场检查。 中国人民银行及其分支机构有权对涉嫌非法从事应当得到中国人民银行及其分支机构批准的行政许可事项活动的当事人进行现场检查。"},{"i":52,"n":"第五十二条","txt":"申请人隐瞒有关情况或者提供虚假材料申请行政许可的，中国人民银行及其分支机构不予受理或者不予行政许可，并给予警告。"},{"i":53,"n":"第五十三条","txt":"被许可人以欺骗、贿赂等不正当手段取得行政许可的，中国人民银行及其分支机构依据《中华人民共和国行政许可法》第六十九条撤销行政许可，有关法律、行政法规、规章有处罚规定的，依照其规定给予处罚；有关法律、行政法规、规章未作处罚规定的，中国人民银行及其分支机构给予警告，并处三万元以下罚款。"},{"i":54,"n":"第五十四条","txt":"被许可人有下列行为之一，有关法律、行政法规有处罚规定的，中国人民银行及其分支机构依照其规定给予处罚；有关法律、行政法规未作处罚规定的，中国人民银行及其分支机构依据《中华人民共和国中国人民银行法》第四十六条进行处罚： （一）涂改、倒卖、出租、出借行政许可证，或者以其他形式非法转让行政许可的； （二）超越许可范围从事经营活动； （三）向负责监督检查的行政机关隐瞒有关情况、提供虚假材料或者拒绝提供反映其活动情况的真实材料的； （四）法律、行政法规、国务院决定、规章规定的其他违法违规行为。"},{"i":55,"n":"第五十五条","txt":"其他单位和个人非法从事应当得到中国人民银行及其分支机构批准的行政许可事项活动的，由中国人民银行及其分支机构责令改正，并可以根据经营活动的实际情况，依据《中华人民共和国中国人民银行法》第四十六条进行处罚。拒不改正的，由中国人民银行及其分支机构会同有关行政机关予以取缔；涉嫌构成犯罪的，移送司法机关依法追究刑事责任。法律、行政法规、国务院决定、规章另有规定的除外。"},{"i":56,"n":"第五十六条","txt":"中国人民银行及其分支机构作出准予行政许可、变更、延续决定，依法撤销、注销行政许可的，应当于决定作出之日起七日内依据行政许可事项服务指南和中国人民银行的相关规定予以公开。"},{"i":57,"n":"第五十七条","txt":"中国人民银行及其分支机构实施行政许可和对行政许可事项进行监督检查，不得收取任何费用。但法律、行政法规另有规定的，依照其规定。"},{"i":58,"n":"第五十八条","txt":"本办法规定的期限以“日”为单位的，均以工作日计算，不含法定节假日。"},{"i":59,"n":"第五十九条","txt":"国家外汇管理局及其分支机构实施行政许可不适用本办法。"},{"i":60,"n":"第六十条","txt":"本办法由中国人民银行负责解释。"},{"i":61,"n":"第六十一条","txt":"本办法自2020年6月1日起施行。《中国人民银行行政许可实施办法》（中国人民银行令〔2004〕第3号发布）同时废止。"}],"zhongguorenminyinhangguizhangzhidingchengxuyuguanl2ca8a2":[{"i":1,"n":"第一条","txt":"为加强对中国人民银行规章的管理，规范规章的制定、备案、解释和清理等工作，保障规章质量，根据《中华人民共和国立法法》、《规章制定程序条例》和《法规规章备案条例》等法律法规，结合工作实际，制定本规定。"},{"i":2,"n":"第二条","txt":"中国人民银行规章的立项、起草、审查、决定、公布、解释、修改、清理、备案等事项，适用本规定。"},{"i":3,"n":"第三条","txt":"制定规章，应当贯彻落实党的路线方针政策和决策部署，体现全面深化改革精神，科学规范行政行为，切实保障公民、法人和其他组织的合法权益，遵循《中华人民共和国立法法》确定的立法原则，符合宪法、法律、行政法规和其他上位法的规定。 没有法律或者国务院的行政法规、决定、命令的依据，规章不得设定减损公民、法人和其他组织权利或者增加其义务的规范，不得增加中国人民银行的权力或者减少法定职责。"},{"i":4,"n":"第四条","txt":"制定政治方面法律的配套规章和涉及金融体制改革、金融对外开放等重大经济社会方面的规章，应当在起草过程中按规定及时向中国人民银行党委报告。"},{"i":5,"n":"第五条","txt":"规章的名称一般为“规定”、“办法”，不得称“法”、“条例”。"},{"i":6,"n":"第六条","txt":"涉及下列事项，原则上应当制定规章： （一）在上位法设定的行政许可事项范围内，对实施该行政许可作出具体规定； （二）设定行政处罚，或者在法律、行政法规规定的给予行政处罚的行为、种类和幅度的范围内作出具体规定； （三）委托符合《中华人民共和国行政处罚法》规定条件的组织实施行政处罚； （四）新设执法检查事项； （五）相关规定可能对公民、法人和其他组织权利义务造成重大影响的。 对同一或者类似事项已经制定多部规范性文件、相关制度已经较为成熟的，应当及时制定规章。"},{"i":7,"n":"第七条","txt":"中国人民银行条法司牵头负责规章的制定和管理工作，承担组织规章的立项、起草、审查、解释、备案、修改、清理等工作；办公厅负责规章的公文审核、公布、档案管理等工作。中国人民银行和国家外汇管理局内设机构（以下简称起草单位）依职责做好规章的立项、起草等工作。"},{"i":8,"n":"第八条","txt":"条法司组织编列年度规章制定工作计划。 起草单位结合工作实际情况和监管工作需要，认为需要制定规章的，应当于每年年初提出本年度的规章立项申请。 中国人民银行各省会（首府）城市中心支行以上分支机构可以于每年年初提出本年度规章制定项目建议。 条法司可以视情况向社会公开征集规章制定项目建议。"},{"i":9,"n":"第九条","txt":"立项申请应当着重说明以下内容： （一）制定规章的依据； （二）制定规章的必要性； （三）所要解决的主要问题； （四）拟确立的主要制度； （五）规章制定计划和拟发布时间。"},{"i":10,"n":"第十条","txt":"条法司应当对立项申请和规章制定项目建议进行评估论证，拟订年度规章制定工作计划，报中国人民银行负责同志批准后向社会公布。 规章制定工作计划包括规章名称、起草单位、拟发布时间等。"},{"i":11,"n":"第十一条","txt":"中国人民银行按照相关财务管理规定对年度规章制定工作计划给予经费保障。"},{"i":12,"n":"第十二条","txt":"对列入年度规章制定工作计划的项目，起草单位应当抓紧起草工作，按照计划及时上报。 条法司应当及时跟踪了解年度规章制定工作计划执行情况，加强组织协调和督促指导。对列入年度规章制定工作计划但未完成的项目，原则上应当在下一年度重新立项。 根据工作需要，未列入年度规章制定工作计划而又确有制定必要的规章，由起草单位商条法司并报中国人民银行负责同志批准后，可以作为补充计划项目执行。"},{"i":13,"n":"第十三条","txt":"规章一般由起草单位具体负责起草工作，条法司负责指导协调。 涉及重大事项、多个内设机构职权等的规章，可以由条法司负责起草或者组织相关内设机构起草。"},{"i":14,"n":"第十四条","txt":"规章应当采用条文形式，一般包括制定目的和依据、适用范围、职责分工、具体规范、法律责任、解释权、施行日期等内容。条文较多的规章可以区分章节。"},{"i":15,"n":"第十五条","txt":"起草规章时，起草单位应当同时撰写起草说明，说明以下事项： （一）制定规章的依据和必要性； （二）主要起草过程； （三）拟解决的主要问题和拟确立的主要制度； （四）意见征求及采纳、协调处理情况； （五）开展贸易政策合规性评估和公平竞争审查的情况； （六）其他需要说明的问题。"},{"i":16,"n":"第十六条","txt":"起草单位在起草过程中应当深入调查研究，广泛征求有关机关、组织和公民的意见。 起草的规章涉及国务院其他部门的职责或者与其他部门关系紧密的，涉及中国人民银行其他内设机构职责的，起草单位应当征求国务院其他部门或者有关内设机构对规章条文或者规章涉及的主要问题的意见。征求意见可以采取书面征求意见、座谈会、论证会、听证会等多种形式。 起草专业性较强的规章，起草单位可以吸收相关领域的专家参与起草工作，或者委托有关专家、教学科研单位、社会组织起草。 起草规章符合《规章制定程序条例》第十六条规定的情况，需要听证的，起草单位应当按照相关程序举办听证会，广泛听取有关方面的意见。"},{"i":17,"n":"第十七条","txt":"规章起草过程中，除依法需要保密的外，起草单位应当将规章条文及其说明等向社会公布，公开征求意见。公开征求意见的期限一般不少于30日。 公开征求意见前，起草单位应当充分评估舆情风险，做好宣传引导和应急处置预案，商条法司、办公厅并报中国人民银行负责同志批准。"},{"i":18,"n":"第十八条","txt":"起草的规章与贸易有关或者可能影响贸易的，起草单位应当在起草过程中按照规定开展贸易政策合规性评估。 起草的规章涉及市场主体经济活动的，起草单位应当在起草过程中按照规定开展公平竞争审查。 法律、行政法规规定和国务院文件要求对规章进行其他审查的，起草单位应当在起草过程中按照规定及时完成审查。"},{"i":19,"n":"第十九条","txt":"起草的规章应当与现行法律、行政法规和相关规章相衔接，法律、行政法规已经明确规定的内容不作重复规定。 新起草的规章拟替代相关规章或者修改相关规章部分条款的，应当明确拟废止的相应规章或者拟废止、修改相关规章的相应条款。"},{"i":20,"n":"第二十条","txt":"起草政治方面法律的配套规章和涉及金融体制改革、金融对外开放等重大经济社会方面的规章，起草单位应当在起草过程中，及时商条法司将重大问题向中国人民银行党委报告。"},{"i":21,"n":"第二十一条","txt":"规章起草完成后，起草单位应当制作规章送审稿，并将规章送审稿及起草说明、对规章送审稿主要问题的不同意见和其他有关材料报送条法司审查。 有关材料主要包括所规范领域的实际情况和相关数据、实践中存在的主要问题、汇总的意见、调研报告、国内外有关立法资料等。 修改规章的，还应当提供修改内容对照表。"},{"i":22,"n":"第二十二条","txt":"规章送审稿由条法司负责统一审查。审查主要包括以下方面： （一）是否列入年度规章制定工作计划或者补充计划； （二）是否符合《规章制定程序条例》第三条、第四条、第五条、第六条的规定； （三）是否符合社会主义核心价值观的要求； （四）是否与现行法律、行政法规和规章协调、衔接； （五）是否按照本规定的要求广泛征求各方面意见，并充分采纳相关意见、协调正确处理主要争议； （六）条文结构和法律用语是否准确，是否符合立法技术要求； （七）主要规定是否具有针对性和可执行性； （八）开展贸易政策合规性评估和公平竞争审查的情况； （九）需要审查的其他内容。"},{"i":23,"n":"第二十三条","txt":"规章送审稿有下列情形之一的，条法司经司务会审议通过，可以缓办或者退回起草单位： （一）立法依据不足，或者与宪法、法律、行政法规和其他上位法存在冲突的； （二）制定规章的基本条件尚不成熟、发生重大变化，或者没有制定规章必要的； （三）未充分征求意见，或者对主要制度存在较大争议，起草单位未与有关机构或者部门达成较为一致意见的； （四）主要内容严重脱离实际，或者缺乏针对性和可执行性的； （五）在立法技术上存在较大缺陷，需要作全面调整和修改的； （六）存在不符合本规定第二十一条或未通过第二十二条审查的其他情形的。"},{"i":24,"n":"第二十四条","txt":"条法司应当就规章送审稿涉及的主要问题，深入基层进行实地调查研究，听取基层有关机关、组织和公民的意见；将规章送审稿或者规章送审稿涉及的主要问题发送至有关机关、组织和专家征求意见。 对规章送审稿作重大修改的，条法司可以将规章送审稿或者修改稿及其说明等向社会公布，征求意见。征求意见的期限一般不少于30日。 条法司在公开征求意见前，应当充分评估舆情风险，做好宣传引导和应急处置预案。"},{"i":25,"n":"第二十五条","txt":"规章送审稿涉及重大利益调整的，条法司应当进行论证咨询，广泛听取有关方面的意见。论证咨询可以采取座谈会、论证会、听证会、委托研究等多种形式。 规章送审稿涉及重大利益调整或者存在重大意见分歧，对公民、法人或者其他组织的权利义务有较大影响，人民群众普遍关注，起草单位在起草过程中未举行听证会的，经中国人民银行负责同志批准，条法司可以举行听证会。"},{"i":26,"n":"第二十六条","txt":"有关机构或者部门对规章送审稿涉及的主要措施、管理体制、权限分工等问题有不同意见的，条法司应当进行协调，力求达成一致意见。 经过充分协调不能达成一致意见的，条法司应当将主要问题、有关机构或者部门的意见和条法司倾向性的意见及时报中国人民银行负责同志决定。"},{"i":27,"n":"第二十七条","txt":"在审查过程中，条法司应当加强与起草单位的沟通，及时将意见反馈至起草单位，需要补充材料的，起草单位应当及时补充。 条法司应当认真研究各方面的意见，与起草单位协商后，对规章送审稿进行修改，形成规章草案和草案说明。草案说明应当包括制定规章拟解决的主要问题、确立的主要措施以及与有关部门的协调情况等。"},{"i":28,"n":"第二十八条","txt":"规章草案和草案说明由条法司主要负责同志签署，经中国人民银行负责同志同意后，提请中国人民银行行长办公会议审议。"},{"i":29,"n":"第二十九条","txt":"规章应当经中国人民银行行长办公会议审议。 审议规章草案时，由条法司作说明，也可以由起草单位作说明。"},{"i":30,"n":"第三十条","txt":"条法司应当在根据中国人民银行行长办公会议审议意见，对规章草案进行修改和完善后，报请中国人民银行行长签署命令予以公布。 公布规章使用“中国人民银行令”，载明该规章的序号、名称、通过日期、施行日期、中国人民银行行长署名以及公布日期。"},{"i":31,"n":"第三十一条","txt":"涉外规章有下列情形之一的，在正式发布前应当向国务院请示报告： （一）涉及对外开放的方针性、政策性、原则性的制度设定或者调整的； （二）专门规范外国人和外国企业、组织及其活动的制度设定或者调整的； （三）存在有必要向国务院请示报告的其他情形的。"},{"i":32,"n":"第三十二条","txt":"规章的规定需要进一步明确具体含义，或者制定后出现新的情况、需要明确适用规章依据的，由条法司参照规章送审稿审查程序提出意见，报中国人民银行负责同志批准后以“中国人民银行公告”的形式发布。 规章的解释与规章具有同等效力。"},{"i":33,"n":"第三十三条","txt":"条法司应当在规章公布之日起30日内，按照《中华人民共和国立法法》和《法规规章备案条例》的规定进行备案。"},{"i":34,"n":"第三十四条","txt":"条法司应当根据全面深化改革、经济社会发展需要以及上位法规定，及时组织开展规章清理工作，制定并发布有效规章目录。"},{"i":35,"n":"第三十五条","txt":"规章的修改、废止，参照本规定第二章至第五章规定的相关程序执行。 修改、废止规章，以“中国人民银行令”及时公布。"},{"i":36,"n":"第三十六条","txt":"条法司可以组织对已发布的规章进行立法后评估。 条法司可以根据评估结果，提出修改、废止有关规章的建议。"},{"i":37,"n":"第三十七条","txt":"国家外汇管理局以中国人民银行名义制定规章及相关规章的管理工作，适用本规定。 国务院委托中国人民银行代拟的法律、行政法规草案的行内起草程序，参照本规定执行。 中国人民银行与国务院其他部门联合制定规章，使用中国人民银行文号的，适用本规定；使用其他部门文号的，应当由主办单位提出意见，参照本规定第四章的规定报条法司审查，并经中国人民银行行长办公会议审议通过。"},{"i":38,"n":"第三十八条","txt":"规章涉及或影响货物贸易、服务贸易以及与贸易有关的知识产权的，应当制作英文译本。 规章的英文译本由起草单位负责制作，一般应当在规章实施前报条法司，确有特殊情况的，不晚于规章施行之日起75日内报送。 条法司对规章的英文译本进行审核后，按照相关规定对外公布。"},{"i":39,"n":"第三十九条","txt":"本规定由中国人民银行负责解释。"},{"i":40,"n":"第四十条","txt":"本规定自2018年11月1日起施行。《规章制定标准规程》（银办发〔2002〕268号文印发）同时废止。"}],"zhongguorenminyinhanghuobijianbiejijiabishoujiaojied9ae0":[{"i":1,"n":"第一条","txt":"为规范货币鉴别及假币收缴、鉴定行为，保护货币持有人的合法权益，根据《中华人民共和国中国人民银行法》、《中华人民共和国商业银行法》、《全国人民代表大会常务委员会关于惩治破坏金融秩序犯罪的决定》和《中华人民共和国人民币管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内设立的办理存取款、货币兑换等业务的银行业金融机构（以下简称金融机构）鉴别货币和收缴假币，中国人民银行及其分支机构和其授权的鉴定机构（以下统称鉴定单位）鉴定货币真伪，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称货币是指人民币和外币。人民币是指中 国人民银行依法发行的货币，包括纸币和硬币。外币是指在中华人民共和国境内可存取、兑换的其他国家（地区）流通中的法定货币。 本办法所称假币是指不由国家（地区）货币当局发行，仿照货币外观或者理化特性，足以使公众误辨并可能行使货币职能的媒介。 假币包括伪造币和变造币。伪造币是指仿照真币的图案、形状、色彩等，采用各种手段制作的假币。变造币是指在真币的基础上，利用挖补、揭层、涂改、拼凑、移位、重印等多种方法制作，改变真币原形态的假币。"},{"i":4,"n":"第四条","txt":"本办法所称鉴别是指金融机构在办理存取款、货币兑换等业务过程中，对货币真伪进行判断的行为。 本办法所称收缴是指金融机构在办理存取款、货币兑换等业务过程中，对发现的假币通过法定程序强制扣留的行为。 本办法所称鉴定是指被收缴人对被收缴假币的真伪判断存在异议的情况下，鉴定单位根据被收缴人或者收缴假币的金融机构（以下简称收缴单位）提出的申请，对被收缴假币的真伪进行裁定的行为。 本办法所称误收是指金融机构在办理存取款、货币兑换等业务过程中，将假币作为真币收入的行为。 本办法所称误付是指金融机构在办理存取款、货币兑换等业务过程中，将假币付出给客户的行为。"},{"i":5,"n":"第五条","txt":"个人或者单位主动向中国人民银行分支机构上缴假币的，中国人民银行分支机构予以没收。 个人或者单位主动向金融机构上缴假币的，金融机构依照本办法第三章实施。"},{"i":6,"n":"第六条","txt":"中国人民银行及其分支机构依照本办法对货币鉴别及假币收缴、鉴定实施监督管理。 金融机构依照本办法对货币进行鉴别，对假币进行收缴，协助被收缴人向鉴定单位提出鉴定申请。 鉴定单位依照本办法实施鉴定。"},{"i":7,"n":"第七条","txt":"对于贵金属纪念币的鉴定比照本办法实施，具体办 法另行制定。"},{"i":8,"n":"第八条","txt":"金融机构办理存取款、货币兑换等业务时，应当准确鉴别货币真伪，防止误收及误付。"},{"i":9,"n":"第九条","txt":"金融机构在履行货币鉴别义务时，应当采取以下措施： （一）确保在用现金机具的鉴别能力符合国家和行业标准； （二）按照中国人民银行有关规定，负责组织开展机构内反假货币知识与技能培训，对办理货币收付、清分业务人员的反假货币水平进行评估，确保其具备判断和挑剔假币的专业能力； （三）按照中国人民银行有关规定，采集、存储人民币和主要外币冠字号码。"},{"i":10,"n":"第十条","txt":"金融机构与客户发生假币纠纷的，若相应存取款、货币兑换等业务的记录在中国人民银行规定的记录保存期限内，金融机构应当提供相关记录。"},{"i":11,"n":"第十一条","txt":"金融机构误付假币，由误付的金融机构对客户等值赔付。若发生负面舆情，金融机构应当妥善处理并消除不良影响。"},{"i":12,"n":"第十二条","txt":"金融机构向中国人民银行分支机构解缴的回笼款中夹杂假币的，中国人民银行分支机构予以没收，向解缴单位开具《假人民币没收收据》，并要求其补足等额人民币回笼款。"},{"i":13,"n":"第十三条","txt":"金融机构确认误收或者误付假币的，应当在3个工作日内向当地中国人民银行分支机构报告，并在上述期限内将假币实物解缴至当地中国人民银行分支机构。金融机构所在地没有中国人民银行分支机构的，由该金融机构向其所在地上一级中国人民银行分支机构报告及解缴假币。"},{"i":14,"n":"第十四条","txt":"金融机构在办理存取款、货币兑换等业务时发现假币的，应当予以收缴。"},{"i":15,"n":"第十五条","txt":"金融机构柜面发现假币后，应当由2名以上业务人员当面予以收缴，被收缴人不能接触假币。对假人民币纸币，应当当面加盖“假币”字样的戳记；对假外币纸币及各种假硬币，应当当面以统一格式的专用袋加封，封口处加盖“假币”字样戳记，并在专用袋上标明币种、券别、面额、张（枚）数、冠字号码（如有）、收缴人、复核人名章等细项。收缴单位向被收缴人出具按照中国人民银行统一规范制作的《假币收缴凭证》，加盖收缴单位业务公章，并告知被收缴人如对被收缴的货币真伪判断有异议，可以向鉴定单位申请鉴定。 金融机构在清分过程中发现假币后，应当比照前款假外币纸币及各种假硬币的收缴方式，由2名以上业务人员予以收缴。假币来源为柜面或者现金自助设备收入的，应当确认为误收差错，假币实物依照第十三条处理。 假币收缴应当在监控下实施，监控记录保存期限不得少于3个月。"},{"i":16,"n":"第十六条","txt":"金融机构在收缴假币过程中有下列情形之一的，应当立即报告当地中国人民银行分支机构和公安机关： （一）一次性发现假币5张（枚）以上和当地中国人民银行分支机构和公安机关发文另有规定的两者较小者； （二）利用新的造假手段制造假币的； （三）获得制造、贩卖、运输、持有或者使用假币线索的； （四）被收缴人不配合金融机构收缴行为的； （五）中国人民银行规定的其他情形。"},{"i":17,"n":"第十七条","txt":"金融机构应当对收缴的假币实物进行单独管理，并建立假币收缴代保管登记制度，账实分管，确保账实相符。"},{"i":18,"n":"第十八条","txt":"金融机构应当将收缴的假币每月全额解缴到当地中国人民银行分支机构，不得自行处理。 金融机构所在地没有中国人民银行分支机构的，由其所在地上一级中国人民银行分支机构确定假币解缴单位。"},{"i":19,"n":"第十九条","txt":"现金自助设备发现可疑币后的处置及相关假币收缴的管理办法另行制定。"},{"i":20,"n":"第二十条","txt":"被收缴人对收缴单位作出的有关收缴具体行政行为有异议，可以在收到《假币收缴凭证》之日起60日内向直接监管该金融机构的中国人民银行分支机构申请行政复议，或者依法提起行政诉讼。"},{"i":21,"n":"第二十一条","txt":"被收缴人对被收缴货币的真伪有异议的，可以自收缴之日起3个工作日内，持《假币收缴凭证》直接或者通过收缴单位向当地鉴定单位提出书面鉴定申请。鉴定单位应当即时回复能否受理鉴定申请，不得无故拒绝。 鉴定单位应当无偿提供鉴定服务，鉴定后应当出具按照中国人民银行统一规范制作的《货币真伪鉴定书》，并加盖货币鉴定专用章和鉴定人名章。"},{"i":22,"n":"第二十二条","txt":"鉴定单位鉴定时，应当至少有2名具备货币真伪鉴定能力的专业人员参与，并作出鉴定结论。"},{"i":23,"n":"第二十三条","txt":"鉴定单位应当自收到鉴定申请之日起2个工作日内，通知收缴单位报送待鉴定货币。 收缴单位应当自收到鉴定单位通知之日起2个工作日内，将待鉴定货币送达鉴定单位。"},{"i":24,"n":"第二十四条","txt":"鉴定单位应当自受理鉴定之日起15个工作日内完成鉴定并出具《货币真伪鉴定书》。因情况复杂不能在规定期限内完成的，可以延长至30个工作日，但应当以书面形式向收缴单位或者被收缴人说明原因。"},{"i":25,"n":"第二十五条","txt":"对盖有“假币”字样戳记的人民币纸币，经鉴定为真币的，由鉴定单位交收缴单位按照面额兑换完整券退还被收缴人，并收回《假币收缴凭证》，盖有“假币”戳记的人民币按不宜流通人民币处理；经鉴定为假币的，由鉴定单位予以没收，并向收缴单位和被收缴人开具《货币真伪鉴定书》和《假人民币没收收据》。 对收缴的外币纸币和各种硬币，经鉴定为真币的，由鉴定单位交收缴单位退还被收缴人，并收回《假币收缴凭证》；经鉴定为假币的，由鉴定单位将假币退回收缴单位依法收缴，并向收缴单位和被收缴人出具《货币真伪鉴定书》。"},{"i":26,"n":"第二十六条","txt":"鉴定单位应当具备以下条件： （一）具有2名以上具备货币真伪鉴定能力的专业人员； （二）满足鉴定需要的货币分析技术条件； （三）具有固定的货币真伪鉴定场所； （四）中国人民银行要求的其他条件。"},{"i":27,"n":"第二十七条","txt":"鉴定单位应当公示鉴定业务范围。中国人民银行及其分支机构应当公示授权的鉴定机构名录。中国人民银行及其分支机构授权的鉴定机构应当公示授权证书。"},{"i":28,"n":"第二十八条","txt":"被收缴人对中国人民银行及其分支机构授权的鉴定机构作出的鉴定结果有异议，可以在收到《货币真伪鉴定书》之日起60日内向鉴定机构所在地的中国人民银行分支机构申请再鉴定。 被收缴人对中国人民银行分支机构作出的鉴定结果有异议，可以在收到《货币真伪鉴定书》之日起60日内向中国人民银行分支机构的上一级机构申请再鉴定。"},{"i":29,"n":"第二十九条","txt":"中国人民银行负责组织制定、实施现金机具鉴别能力管理、反假货币培训管理、金融机构冠字号码数据信息管理、假币收缴鉴定等的制度规范。 中国人民银行及其分支机构有权对金融机构执行本办法的情况开展监督检查。"},{"i":30,"n":"第三十条","txt":"金融机构应当按照《中华人民共和国人民币管理条例》和本办法的相关规定，建立货币鉴别及假币收缴、鉴定内部管理制度和操作规范。"},{"i":31,"n":"第三十一条","txt":"金融机构应当按照中国人民银行有关规定，对现金机具、人员培训、冠字号码以及假币收缴鉴定业务等进行数据管理，并将相关数据报送中国人民银行或其分支机构。"},{"i":32,"n":"第三十二条","txt":"金融机构应当定期对本办法及相关内部管理制度和操作规范的执行情况进行自查，并接受中国人民银行及其分支机构的检查。"},{"i":33,"n":"第三十三条","txt":"金融机构开展货币鉴别和假币收缴，中国人民 银行及其分支机构授权的鉴定机构开展假币鉴定业务，有下列行为之一，但尚未构成犯罪，涉及假人民币的，按照《中华人民共和国人民币管理条例》第四十四条的规定予以处罚；涉及假外币的，处以1000元以上3万元以下的罚款： （一）在用现金机具鉴别能力不符合国家和行业标准的； （二）未按本办法规定组织开展机构内反假货币知识与技能培训，未按本办法规定对办理货币收付、清分业务人员的反假货币水平进行评估，或者办理货币收付、清分业务人员不具备判断和挑剔假币专业能力的； （三）未按本办法规定采集、存储人民币和主要外币冠字号码的； （四）未按本办法规定建立货币鉴别及假币收缴、鉴定内部管理制度和操作规范的； （五）发生假币误付行为的； （六）与客户发生假币纠纷，在记录保存期限内，金融机构未能提供相应存取款、货币兑换等业务记录的； （七）发现假币而不收缴的； （八）未按本办法"},{"i":34,"n":"第三十四条","txt":"金融机构开展货币鉴别和假币收缴，中国人民 银行及其分支机构授权的鉴定机构开展假币鉴定业务，有下列行为之一，但尚未构成犯罪，涉及假人民币的，按照《中华人民共和国中国人民银行法》第四十六条的规定予以处罚；涉及假外币的，处以1000元以上3万元以下的罚款： （一）发生假币误收行为的； （二）误付假币，未对客户等值赔付，或者对负面舆情处置不力造成不良影响的； （三）误收、误付假币，应当向中国人民银行分支机构报告而不报告的； （四）违反本办法第十六条规定，应当向中国人民银行分支机构报告而不报告的; （五）向中国人民银行分支机构解缴的回笼款中夹杂假币的； （六）未按本办法规定对现金机具、人员培训、冠字号码以及假币收缴鉴定业务等进行数据管理，并报送中国人民银行或其分支机构的； （七）未公示鉴定机构授权证书或者鉴定业务范围的。"},{"i":35,"n":"第三十五条","txt":"拒绝、阻挠、逃避中国人民银行及其分支机构检查，或者谎报、隐匿、销毁相关证据材料的，有关法律、行政法规有处罚规定的，依照其规定给予处罚；有关法律、行政法规未作处罚规定的，由中国人民银行及其分支机构予以警告，并处5000元以上3万元以下的罚款。"},{"i":36,"n":"第三十六条","txt":"中国人民银行及其分支机构工作人员有下列行为之一，但尚未构成犯罪的，对直接负责的主管人员和直接责任人员，依法给予行政处分： （一）无故拒绝受理收缴单位、被收缴人或者中国人民银行及其分支机构授权的鉴定机构提出的货币真伪鉴定申请的； （二）未按本办法规定鉴定假币的； （三）不当保管、截留或者私自处理假币，或者使已收缴、没收的假币重新流入市场的。"},{"i":37,"n":"第三十七条","txt":"本办法由中国人民银行负责解释。"},{"i":38,"n":"第三十八条","txt":"本办法自2020年4月1日起施行。《中国人民银行假币收缴、鉴定管理办法》（中国人民银行令〔2003〕第4号发布）同时废止。"}],"zhongguorenminyinhangjinrongxiaofeizhequanyibaohus97115c":[{"i":1,"n":"第一条","txt":"为了保护金融消费者合法权益，规范金融机构提供金融产品和服务的行为，维护公平、公正的市场环境，促进金融市场健康稳定运行，根据《中华人民共和国中国人民银行法》《中华人民共和国商业银行法》《中华人民共和国消费者权益保护法》和《国务院办公厅关于加强金融消费者权益保护工作的指导意见》（国办发〔2015〕81号）等，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内依法设立的为金融消费者提供金融产品或者服务的银行业金融机构（以下简称银行），开展与下列业务相关的金融消费者权益保护工作，适用本办法： （一）与利率管理相关的。 （二）与人民币管理相关的。 （三）与外汇管理相关的。 （四）与黄金市场管理相关的。 （五）与国库管理相关的。 （六）与支付、清算管理相关的。 （七）与反洗钱管理相关的。 （八）与征信管理相关的。 （九）与上述第一项至第八项业务相关的金融营销宣传和消费者金融信息保护。 （十）其他法律、行政法规规定的中国人民银行职责范围内的金融消费者权益保护工作。 在中华人民共和国境内依法设立的非银行支付机构（以下简称支付机构）提供支付服务的，适用本办法。 本办法所称金融消费者是指购买、使用银行、支付机构提供的金融产品或者服务的自然人。"},{"i":3,"n":"第三条","txt":"银行、支付机构向金融消费者提供金融产品或者服务，应当遵循自愿、平等、公平、诚实信用的原则，切实承担金融消费者合法权益保护的主体责任，履行金融消费者权益保护的法定义务。"},{"i":4,"n":"第四条","txt":"金融消费者应当文明、理性进行金融消费，提高自我保护意识，诚实守信，依法维护自身的合法权益。"},{"i":5,"n":"第五条","txt":"中国人民银行及其分支机构坚持公平、公正原则，依法开展职责范围内的金融消费者权益保护工作，依法保护金融消费者合法权益。 中国人民银行及其分支机构会同有关部门推动建立和完善金融机构自治、行业自律、金融监管和社会监督相结合的金融消费者权益保护共同治理体系。"},{"i":6,"n":"第六条","txt":"鼓励金融消费者和银行、支付机构充分运用调解、仲裁等方式解决金融消费纠纷。"},{"i":7,"n":"第七条","txt":"银行、支付机构应当将金融消费者权益保护纳入公司治理、企业文化建设和经营发展战略，制定本机构金融消费者权益保护工作的总体规划和具体工作措施。建立金融消费者权益保护专职部门或者指定牵头部门，明确部门及人员职责，确保部门有足够的人力、物力能够独立开展工作，并定期向高级管理层、董（理）事会汇报工作开展情况。"},{"i":8,"n":"第八条","txt":"银行、支付机构应当落实法律法规和相关监管规定关于金融消费者权益保护的相关要求，建立健全金融消费者权益保护的各项内控制度： （一）金融消费者权益保护工作考核评价制度。 （二）金融消费者风险等级评估制度。 （三）消费者金融信息保护制度。 （四）金融产品和服务信息披露、查询制度。 （五）金融营销宣传管理制度。 （六）金融知识普及和金融消费者教育制度。 （七）金融消费者投诉处理制度。 （八）金融消费者权益保护工作内部监督和责任追究制度。 （九）金融消费者权益保护重大事件应急制度。 （十）中国人民银行明确规定应当建立的其他金融消费者权益保护工作制度。"},{"i":9,"n":"第九条","txt":"银行、支付机构应当建立健全涉及金融消费者权益保护工作的全流程管控机制，确保在金融产品或者服务的设计开发、营销推介及售后管理等各个业务环节有效落实金融消费者权益保护工作的相关规定和要求。全流程管控机制包括但不限于下列内容： （一）事前审查机制。银行、支付机构应当实行金融消费者权益保护事前审查，及时发现并更正金融产品或者服务中可能损害金融消费者合法权益的问题，有效督办落实金融消费者权益保护审查意见。 （二）事中管控机制。银行、支付机构应当履行金融产品或者服务营销宣传中须遵循的基本程序和标准，加强对营销宣传行为的监测与管控。 （三）事后监督机制。银行、支付机构应当做好金融产品和服务的售后管理，及时调整存在问题或者隐患的金融产品和服务规则。"},{"i":10,"n":"第十条","txt":"银行、支付机构应当开展金融消费者权益保护工作人员培训，增强工作人员的金融消费者权益保护意识和能力。 银行、支付机构应当每年至少开展一次金融消费者权益保护专题培训，培训对象应当全面覆盖中高级管理人员、基层业务人员及新入职人员。对金融消费者投诉多发、风险较高的业务岗位，应当适当提高培训的频次。"},{"i":11,"n":"第十一条","txt":"银行、支付机构开展考核评价时，应当将金融消费者权益保护工作作为重要内容，并合理分配相关指标的占比和权重，综合考虑业务合规性、客户满意度、投诉处理及时率与合格率等，不得简单以投诉数量作为考核指标。"},{"i":12,"n":"第十二条","txt":"银行、支付机构应当根据金融产品或者服务的特性评估其对金融消费者的适合度，合理划分金融产品和服务风险等级以及金融消费者风险承受等级，将合适的金融产品或者服务提供给适当的金融消费者。"},{"i":13,"n":"第十三条","txt":"银行、支付机构应当依法保障金融消费者在购买、使用金融产品和服务时的财产安全，不得挪用、非法占用金融消费者资金及其他金融资产。"},{"i":14,"n":"第十四条","txt":"银行、支付机构应当尊重社会公德，尊重金融消费者的人格尊严和民族风俗习惯，不得因金融消费者性别、年龄、种族、民族或者国籍等不同实行歧视性差别对待，不得使用歧视性或者违背公序良俗的表述。"},{"i":15,"n":"第十五条","txt":"银行、支付机构应当尊重金融消费者购买金融产品或者服务的真实意愿，不得擅自代理金融消费者办理业务，不得擅自修改金融消费者的业务指令，不得强制搭售其他产品或者服务。"},{"i":16,"n":"第十六条","txt":"银行、支付机构应当依据金融产品或者服务的特性，及时、真实、准确、全面地向金融消费者披露下列重要内容： （一）金融消费者对该金融产品或者服务的权利和义务，订立、变更、中止和解除合同的方式及限制。 （二）银行、支付机构对该金融产品或者服务的权利、义务及法律责任。 （三）贷款产品的年化利率。 （四）金融消费者应当负担的费用及违约金，包括金额的确定方式，交易时间和交易方式。 （五）因金融产品或者服务产生纠纷的处理及投诉途径。 （六）银行、支付机构对该金融产品或者服务所执行的强制性标准、推荐性标准、团体标准或者企业标准的编号和名称。 （七）在金融产品说明书或者服务协议中，实际承担合同义务的经营主体完整的中文名称。 （八）其他可能影响金融消费者决策的信息。"},{"i":17,"n":"第十七条","txt":"银行、支付机构对金融产品和服务进行信息披露时，应当使用有利于金融消费者接收、理解的方式。对利率、费用、收益及风险等与金融消费者切身利益相关的重要信息，应当根据金融产品或者服务的复杂程度及风险等级，对其中关键的专业术语进行解释说明，并以适当方式供金融消费者确认其已接收完整信息。"},{"i":18,"n":"第十八条","txt":"银行、支付机构向金融消费者说明重要内容和披露风险时，应当依照法律法规和监管规定留存相关资料，自业务关系终止之日起留存时间不得少于3年。法律、行政法规另有规定的，从其规定。 留存的资料包括但不限于： （一）金融消费者确认的金融产品说明书或者服务协议。 （二）金融消费者确认的风险提示书。 （三）记录向金融消费者说明重要内容的录音、录像资料或者系统日志等相关数据电文资料。"},{"i":19,"n":"第十九条","txt":"银行、支付机构不得利用技术手段、优势地位，强制或者变相强制金融消费者接受金融产品或者服务，或者排除、限制金融消费者接受同业机构提供的金融产品或者服务。"},{"i":20,"n":"第二十条","txt":"银行、支付机构在提供金融产品或者服务的过程中，不得通过附加限制性条件的方式要求金融消费者购买、使用协议中未作明确要求的产品或者服务。"},{"i":21,"n":"第二十一条","txt":"银行、支付机构向金融消费者提供金融产品或者服务时使用格式条款的，应当以足以引起金融消费者注意的字体、字号、颜色、符号、标识等显著方式，提请金融消费者注意金融产品或者服务的数量、利率、费用、履行期限和方式、注意事项、风险提示、纠纷解决等与金融消费者有重大利害关系的内容，并按照金融消费者的要求予以说明。格式条款采用电子形式的，应当可被识别且易于获取。 银行、支付机构不得以通知、声明、告示等格式条款的方式作出含有下列内容的规定： （一）减轻或者免除银行、支付机构造成金融消费者财产损失的赔偿责任。 （二）规定金融消费者承担超过法定限额的违约金或者损害赔偿金。 （三）排除或者限制金融消费者依法对其金融信息进行查询、删除、修改的权利； （四）排除或者限制金融消费者选择同业机构提供的金融产品或者服务的权利。 （五）其他对金融消费者不公平、不合理的规定。 银行、支付机构应当对存在侵害金融消费者合法权益"},{"i":22,"n":"第二十二条","txt":"银行、支付机构应当对营销宣传内容的真实性负责。银行、支付机构实际承担的义务不得低于在营销宣传活动中通过广告、资料或者说明等形式对金融消费者所承诺的标准。 前款“广告、资料或者说明”是指以营销为目的，利用各种传播媒体、宣传工具或者方式，就银行、支付机构的金融产品或者服务进行直接或者间接的宣传、推广等。"},{"i":23,"n":"第二十三条","txt":"银行、支付机构在进行营销宣传活动时，不得有下列行为： （一）虚假、欺诈、隐瞒或者引人误解的宣传。 （二）引用不真实、不准确的数据和资料或者隐瞒限制条件等，对过往业绩或者产品收益进行夸大表述。 （三）利用金融管理部门对金融产品或者服务的审核或者备案程序，误导金融消费者认为金融管理部门已对该金融产品或者服务提供保证。 （四）明示或者暗示保本、无风险或者保收益等，对非保本投资型金融产品的未来效果、收益或者相关情况作出保证性承诺。 （五）其他违反金融消费者权益保护相关法律法规和监管规定的行为。"},{"i":24,"n":"第二十四条","txt":"银行、支付机构应当切实承担金融知识普及和金融消费者教育的主体责任，提高金融消费者对金融产品和服务的认知能力，提升金融消费者金融素养和诚实守信意识。 银行、支付机构应当制定年度金融知识普及与金融消费者教育工作计划，结合自身特点开展日常性金融知识普及与金融消费者教育活动，积极参与中国人民银行及其分支机构组织的金融知识普及活动。银行、支付机构不得以营销金融产品或者服务替代金融知识普及与金融消费者教育。"},{"i":25,"n":"第二十五条","txt":"银行、支付机构应当重视金融消费者需求的多元性与差异性，积极支持普惠金融重点目标群体获得必要、及时的基本金融产品和服务。"},{"i":26,"n":"第二十六条","txt":"出现侵害金融消费者合法权益重大事件的，银行、支付机构应当根据重大事项报告的相关规定及时向中国人民银行或其分支机构报告。"},{"i":27,"n":"第二十七条","txt":"银行、支付机构应当配合中国人民银行及其分支机构开展金融消费者权益保护领域的相关工作，按照规定报送相关资料。"},{"i":28,"n":"第二十八条","txt":"本办法所称消费者金融信息，是指银行、支付机构通过开展业务或者其他合法渠道处理的消费者信息，包括个人身份信息、财产信息、账户信息、信用信息、金融交易信息及其他与特定消费者购买、使用金融产品或者服务相关的信息。 消费者金融信息的处理包括消费者金融信息的收集、存储、使用、加工、传输、提供、公开等。"},{"i":29,"n":"第二十九条","txt":"银行、支付机构处理消费者金融信息，应当遵循合法、正当、必要原则，经金融消费者或者其监护人明示同意，但是法律、行政法规另有规定的除外。银行、支付机构不得收集与业务无关的消费者金融信息，不得采取不正当方式收集消费者金融信息，不得变相强制收集消费者金融信息。银行、支付机构不得以金融消费者不同意处理其金融信息为由拒绝提供金融产品或者服务，但处理其金融信息属于提供金融产品或者服务所必需的除外。 金融消费者不能或者拒绝提供必要信息，致使银行、支付机构无法履行反洗钱义务的，银行、支付机构可以根据《中华人民共和国反洗钱法》的相关规定对其金融活动采取限制性措施；确有必要时，银行、支付机构可以依法拒绝提供金融产品或者服务。"},{"i":30,"n":"第三十条","txt":"银行、支付机构收集消费者金融信息用于营销、用户体验改进或者市场调查的，应当以适当方式供金融消费者自主选择是否同意银行、支付机构将其金融信息用于上述目的；金融消费者不同意的，银行、支付机构不得因此拒绝提供金融产品或者服务。银行、支付机构向金融消费者发送金融营销信息的，应当向其提供拒绝继续接收金融营销信息的方式。"},{"i":31,"n":"第三十一条","txt":"银行、支付机构应当履行《中华人民共和国消费者权益保护法》第二十九条规定的明示义务，公开收集、使用消费者金融信息的规则，明示收集、使用消费者金融信息的目的、方式和范围，并留存有关证明资料。 银行、支付机构通过格式条款取得消费者金融信息收集、使用同意的，应当在格式条款中明确收集消费者金融信息的目的、方式、内容和使用范围，并在协议中以显著方式尽可能通俗易懂地向金融消费者提示该同意的可能后果。"},{"i":32,"n":"第三十二条","txt":"银行、支付机构应当按照法律法规的规定和双方约定的用途使用消费者金融信息，不得超出范围使用。"},{"i":33,"n":"第三十三条","txt":"银行、支付机构应当建立以分级授权为核心的消费者金融信息使用管理制度，根据消费者金融信息的重要性、敏感度及业务开展需要，在不影响本机构履行反洗钱等法定义务的前提下，合理确定本机构工作人员调取信息的范围、权限，严格落实信息使用授权审批程序。"},{"i":34,"n":"第三十四条","txt":"银行、支付机构应当按照国家档案管理和电子数据管理等规定，采取技术措施和其他必要措施，妥善保管和存储所收集的消费者金融信息，防止信息遗失、毁损、泄露或者被篡改。 银行、支付机构及其工作人员应当对消费者金融信息严格保密，不得泄露或者非法向他人提供。在确认信息发生泄露、毁损、丢失时，银行、支付机构应当立即采取补救措施；信息泄露、毁损、丢失可能危及金融消费者人身、财产安全的，应当立即向银行、支付机构住所地的中国人民银行分支机构报告并告知金融消费者；信息泄露、毁损、丢失可能对金融消费者产生其他不利影响的，应当及时告知金融消费者，并在72小时以内报告银行、支付机构住所地的中国人民银行分支机构。中国人民银行分支机构接到报告后，视情况按照本办法第五十五条规定处理。"},{"i":35,"n":"第三十五条","txt":"金融消费者与银行、支付机构发生金融消费争议的，鼓励金融消费者先向银行、支付机构投诉，鼓励当事人平等协商，自行和解。 金融消费者应当依法通过正当途径客观、理性反映诉求，不扰乱正常的金融秩序和社会公共秩序。 本办法所称金融消费争议，是指金融消费者与银行、支付机构因购买、使用金融产品或者服务所产生的民事争议。"},{"i":36,"n":"第三十六条","txt":"银行、支付机构应当切实履行金融消费投诉处理的主体责任，银行、支付机构的法人机构应当按年度向社会发布金融消费者投诉数据和相关分析报告。"},{"i":37,"n":"第三十七条","txt":"银行、支付机构应当通过金融消费者方便获取的渠道公示本机构的投诉受理方式，包括但不限于营业场所、官方网站首页、移动应用程序的醒目位置及客服电话主要菜单语音提示等。"},{"i":38,"n":"第三十八条","txt":"银行、支付机构应当按照中国人民银行要求，加强对金融消费者投诉处理信息系统的建设与管理，对投诉进行正确分类并按时报送相关信息，不得迟报、漏报、谎报、错报或者瞒报投诉数据。"},{"i":39,"n":"第三十九条","txt":"银行、支付机构收到金融消费者投诉后，依照相关法律法规和合同约定进行处理，并告知投诉人处理情况，但因投诉人原因导致无法告知的除外。"},{"i":40,"n":"第四十条","txt":"中国人民银行分支机构设立投诉转办服务渠道。金融消费者对银行、支付机构作出的投诉处理不接受的，可以通过银行、支付机构住所地、合同签订地或者经营行为发生地中国人民银行分支机构进行投诉。 通过电子商务、网络交易购买、使用金融产品或者服务的，金融消费者通过银行、支付机构住所地的中国人民银行分支机构进行投诉。"},{"i":41,"n":"第四十一条","txt":"金融消费者通过中国人民银行分支机构进行投诉，应当提供以下信息：姓名，有效身份证件信息，联系方式，明确的投诉对象及其住所地，具体的投诉请求、事实和理由。 金融消费者可以本人提出投诉，也可以委托他人代为提出投诉。以来信来访方式进行委托投诉的，应当向中国人民银行分支机构提交前款规定的投诉材料、授权委托书原件、委托人和受托人的身份证明。授权委托书应当载明受托人、委托事项、权限和期限，并由委托人本人签名。"},{"i":42,"n":"第四十二条","txt":"中国人民银行分支机构对下列投诉不予接收： （一）投诉人投诉的机构、产品或者服务不属于中国人民银行监管范围的。 （二）投诉人未提供真实身份，或者没有明确的被投诉人、没有具体的投诉请求和事实依据的。 （三）投诉人并非金融消费者本人，也未经金融消费者本人委托的。 （四）人民法院、仲裁机构、其他金融管理部门、行政部门或者依法设立的调解组织已经受理、接收或者处理的。 （五）双方达成和解协议并已经执行，没有新情况、新理由的。 （六）被投诉机构已提供公平合理的解决方案，投诉人就同一事项再次向中国人民银行分支机构投诉的。 （七）其他不符合法律、行政法规、规章有关规定的。"},{"i":43,"n":"第四十三条","txt":"中国人民银行分支机构收到金融消费者投诉的，应当自收到投诉之日起7个工作日内作出下列处理： （一）对投诉人和被投诉机构信息、投诉请求、事实和理由等进行登记。 （二）作出是否接收投诉的决定。决定不予接收的，应当告知投诉人。 （三）决定接收投诉的，应当将投诉转交被投诉机构处理或者转交金融消费纠纷调解组织提供调解服务。 需要投诉人对投诉内容进行补正的，处理时限于补正完成之日起计算。 银行、支付机构应当自收到中国人民银行分支机构转交的投诉之日起15日内答复投诉人。情况复杂的，经本机构投诉处理工作负责人批准，可以延长处理期限，并告知投诉人延长处理期限的理由，但最长处理期限不得超过60日。"},{"i":44,"n":"第四十四条","txt":"银行、支付机构收到中国人民银行分支机构转交的投诉，应当按要求向中国人民银行分支机构反馈投诉处理情况。 反馈的内容包括投诉基本情况、争议焦点、调查结果及证据、处理依据、与金融消费者的沟通情况、延期处理情况及投诉人满意度等。 银行、支付机构应当妥善保存投诉资料，投诉资料留存时间自投诉办结之日起不得少于3年。法律、行政法规另有规定的，从其规定。"},{"i":45,"n":"第四十五条","txt":"银行、支付机构、金融消费者可以向调解组织申请调解、中立评估。调解组织受理调解、中立评估申请后，可在合理、必要范围内请求当事人协助或者提供相关文件、资料。 本办法所称中立评估，是指调解组织聘请独立专家就争议解决提出参考性建议的行为。"},{"i":46,"n":"第四十六条","txt":"金融消费纠纷调解组织应当依照法律、行政法规、规章及其章程的规定，组织开展金融消费纠纷调解、中立评估等工作，对银行、支付机构和金融消费者进行金融知识普及和教育宣传引导。"},{"i":47,"n":"第四十七条","txt":"中国人民银行综合研究金融消费者保护重大问题，负责拟定发展规划和业务标准，建立健全金融消费者保护基本制度。"},{"i":48,"n":"第四十八条","txt":"中国人民银行及其分支机构与其他金融管理部门、地方政府有关部门建立健全金融消费者权益保护工作协调机制，加强跨市场跨业态跨区域金融消费者权益保护的监管，强化信息共享和部门间沟通协作。"},{"i":49,"n":"第四十九条","txt":"中国人民银行及其分支机构统筹开展金融消费者教育，引导、督促银行、支付机构开展金融知识普及宣传活动，协调推进金融知识纳入国民教育体系，组织开展消费者金融素养调查。"},{"i":50,"n":"第五十条","txt":"中国人民银行及其分支机构会同有关部门构建监管执法合作机制，探索合作开展金融消费者权益保护监督检查、评估等具体工作。"},{"i":51,"n":"第五十一条","txt":"中国人民银行及其分支机构牵头构建非诉第三方解决机制，鼓励、支持金融消费者权益保护社会组织依法履行职责，推动构建公正、高效、便捷的多元化金融消费纠纷解决体系。"},{"i":52,"n":"第五十二条","txt":"中国人民银行及其分支机构协调推进相关普惠金融工作，建立健全普惠金融工作机制，指导、督促银行、支付机构落实普惠金融发展战略，组织开展职责范围内的普惠金融具体工作。"},{"i":53,"n":"第五十三条","txt":"中国人民银行及其分支机构对金融消费者投诉信息进行汇总和分析，根据汇总和分析结果适时优化金融消费者权益保护监督管理方式、金融机构行为规范等。"},{"i":54,"n":"第五十四条","txt":"中国人民银行及其分支机构可以采取下列措施，依法在职责范围内开展对银行、支付机构金融消费者权益保护工作的监督检查： （一）进入被监管机构进行检查。 （二）询问被监管机构的工作人员，要求其对有关检查事项作出说明。 （三）查阅、复制被监管机构与检查事项有关的文件、资料，对可能被转移、隐匿或者毁损的文件、资料予以登记保存。 （四）检查被监管机构的计算机网络与信息系统。 进行现场检查时，检查人员不得少于二人，并应当出示合法证件和检查通知书。 银行、支付机构应当积极配合中国人民银行及其分支机构的现场检查和非现场检查，如实提供有关资料，不得拒绝、阻挠、逃避检查，不得谎报、隐匿、销毁相关证据材料。"},{"i":55,"n":"第五十五条","txt":"银行、支付机构有侵害金融消费者合法权益行为的，中国人民银行及其分支机构可以对其采取下列措施： （一）要求提交书面说明或者承诺。 （二）约见谈话。 （三）责令限期整改。 （四）视情将相关信息向其上级机构、行业监管部门反馈，在行业范围内发布，或者向社会公布。 （五）建议银行、支付机构对直接负责的董事、高级管理人员和其他直接责任人员给予处分。 （六）依法查处或者建议其他行政管理部门依法查处。 （七）中国人民银行职责范围内依法可以采取的其他措施。"},{"i":56,"n":"第五十六条","txt":"中国人民银行及其分支机构组织开展银行、支付机构履行金融消费者权益保护义务情况的评估工作。 评估工作以银行、支付机构自评估为基础。银行、支付机构应当按年度进行自评估，并于次年1月31日前向中国人民银行或其分支机构报送自评估报告。 中国人民银行及其分支机构根据日常监督管理、投诉管理以及银行、支付机构自评估等情况进行非现场评估，必要时可以进行现场评估。"},{"i":57,"n":"第五十七条","txt":"中国人民银行及其分支机构可以根据具体情况开展金融消费者权益保护环境评估工作。"},{"i":58,"n":"第五十八条","txt":"中国人民银行及其分支机构建立金融消费者权益保护案例库制度，按照预防为先、教育为主的原则向银行、支付机构和金融消费者进行风险提示。"},{"i":59,"n":"第五十九条","txt":"中国人民银行及其分支机构对于涉及金融消费者权益保护的重大突发事件，应当按照有关规定做好相关应急处置工作。"},{"i":60,"n":"第六十条","txt":"银行、支付机构有下列情形之一，侵害消费者金融信息依法得到保护的权利的，中国人民银行或其分支机构应当在职责范围内依照《中华人民共和国消费者权益保护法》第五十六条的规定予以处罚： （一）未经金融消费者明示同意，收集、使用其金融信息的。 （二）收集与业务无关的消费者金融信息，或者采取不正当方式收集消费者金融信息的。 （三）未公开收集、使用消费者金融信息的规则，未明示收集、使用消费者金融信息的目的、方式和范围的。 （四）超出法律法规规定和双方约定的用途使用消费者金融信息的。 （五）未建立以分级授权为核心的消费者金融信息使用管理制度，或者未严格落实信息使用授权审批程序的。 （六）未采取技术措施和其他必要措施，导致消费者金融信息遗失、毁损、泄露或者被篡改，或者非法向他人提供的。"},{"i":61,"n":"第六十一条","txt":"银行、支付机构有下列情形之一，对金融产品或者服务作出虚假或者引人误解的宣传的，中国人民银行或其分支机构应当在职责范围内依照《中华人民共和国消费者权益保护法》第五十六条的规定予以处罚： （一）实际承担的义务低于在营销宣传活动中通过广告、资料或者说明等形式对金融消费者所承诺的标准的。 （二）引用不真实、不准确的数据和资料或者隐瞒限制条件等，对过往业绩或者产品收益进行夸大表述的。 （三）利用金融管理部门对金融产品或者服务的审核或者备案程序，误导金融消费者认为金融管理部门已对该金融产品或者服务提供保证的。 （四）明示或者暗示保本、无风险或者保收益等，对非保本投资型金融产品的未来效果、收益或者相关情况作出保证性承诺的。"},{"i":62,"n":"第六十二条","txt":"银行、支付机构违反本办法规定，有下列情形之一，有关法律、行政法规有处罚规定的，依照其规定给予处罚；有关法律、行政法规未作处罚规定的，中国人民银行或其分支机构应当根据情形单处或者并处警告、处以五千元以上三万元以下罚款： （一）未建立金融消费者权益保护专职部门或者指定牵头部门，或者金融消费者权益保护部门没有足够的人力、物力独立开展工作的。 （二）擅自代理金融消费者办理业务，擅自修改金融消费者的业务指令，或者强制搭售其他产品或者服务的。 （三）未按要求向金融消费者披露与金融产品和服务有关的重要内容的。 （四）利用技术手段、优势地位，强制或者变相强制金融消费者接受金融产品或者服务，或者排除、限制金融消费者接受同业机构提供的金融产品或者服务的。 （五）通过附加限制性条件的方式要求金融消费者购买、使用协议中未作明确要求的产品或者服务的。 （六）未按要求使用格式条款的。 （七）出现侵害金融消费者合法"},{"i":63,"n":"第六十三条","txt":"对银行、支付机构侵害金融消费者权益重大案件负有直接责任的董事、高级管理人员和其他直接责任人员，有关法律、行政法规有处罚规定的，依照其规定给予处罚；有关法律、行政法规未作处罚规定的，中国人民银行或其分支机构应当根据情形单处或者并处警告、处以五千元以上三万元以下罚款。"},{"i":64,"n":"第六十四条","txt":"中国人民银行及其分支机构的工作人员在开展金融消费者权益保护工作过程中有下列情形之一的，依法给予处分；涉嫌构成犯罪的，移送司法机关依法追究刑事责任： （一）违反规定对银行、支付机构进行检查的。 （二）泄露知悉的国家秘密或者商业秘密的。 （三）滥用职权、玩忽职守的其他行为。"},{"i":65,"n":"第六十五条","txt":"商业银行理财子公司、金融资产管理公司、信托公司、汽车金融公司、消费金融公司以及征信机构、个人本外币兑换特许业务经营机构参照适用本办法。法律、行政法规另有规定的，从其规定。"},{"i":66,"n":"第六十六条","txt":"本办法中除“工作日”以外的“日”为自然日。"},{"i":67,"n":"第六十七条","txt":"本办法由中国人民银行负责解释。"},{"i":68,"n":"第六十八条","txt":"本办法自2020年11月1日起施行。《中国人民银行金融消费权益保护工作管理办法（试行）》（银办发〔2013〕107号文印发）与《中国人民银行金融消费者权益保护实施办法》（银发〔2016〕314号文印发）同时废止。"}],"renminbililvguanliguiding":[{"i":1,"n":"第一条","txt":"为有效发挥利率杠杆对国民经济的调节作用，加强利率管理，维护正常的金融秩序，创造公平有序的竟争环境，根据《中华人民共和国中国人民银行法》、《中华人民共和国商业银行法》及其他相关法律、法规制定本规定。"},{"i":2,"n":"第二条","txt":"凡在中华人民共和国境内（不含香港、澳门、台湾）经营人民币存、贷款业务的金融机构，邮政储蓄部门，其他法人、自然人和其他组织，均遵守本规定。"},{"i":3,"n":"第三条","txt":"中国人民银行是经国务院授权的利率主管机关，代表国家依法行使利率管理权，其他任何单位和个人不得干预。"},{"i":4,"n":"第四条","txt":"中国人民银行制定的各种利率是法定利率。法定利率具有法律效力，其他任何单位和个人均无权变动。"},{"i":5,"n":"第五条","txt":"中国人民银行制定、调整以下利率： （一）中国人民银行对金融机构存、贷款利率和再贴现利率； （二）金融机构存、贷款利率； （三）优惠贷款利率； （四）罚息利率； （五）同业存款利率； （六）利率浮动幅度； （七）其他。"},{"i":6,"n":"第六条","txt":"金融机构根据中国人民银行的有关规定确定以下利率： （一）浮动利率； （二）内部资金往来利率； （三）同业拆借利率； （四）贴现利率和转贴现利率； （五）中国人民银行允许确定的其他利率。"},{"i":7,"n":"第七条","txt":"中国人民银行总行履行下列利率管理职责： （一）根据国民经济发展的需要和货币政策要求，制定利率政策和利率管理法规并组织实施； （二）领导中国人民银行分支机构的利率管理工作； （三）监督、检查金融机构执行国家利率政策、法规的情况； （四）协调、处理金融机构的利率纠纷和利率违现行为； （五）宣传、解释国家的利率政策及相关法规； （六）研究、制定、实施国家的利率改革规划； （七）监测、调控金融市场利率； （八）其他利率管理工作。"},{"i":8,"n":"第八条","txt":"中国人民银行分支机构在中国人民银行总行授权的范围内履行下列利率管理职责： （一）实施对辖区内金融机构的利率管理，指导下级行的利率管理工作; （二）及时转发中国人民银行总行的有关文件，对有关利率调整等内容的重要文件，应在生效日之前传送到辖区内金融机构，并严守机密； （三）监督、检查辖区内金融机构执行利率政策的情况，处理利率违规行为，并及时向上级行报告本辖区内利率政策执行情况； （四）建立和完善利率违规举报制度，加强社会监督； （五）宣传、解释国家的利率政策及相关法规； （六）组织有关利率政策的调查研究； （七）完成上级行安排的其他利率管理工作。"},{"i":9,"n":"第九条","txt":"金融机构履行下列职责： （一）协助和配合中国人民银行进行利率管理工作，宣传、贯彻、执行国家利率政策； （二）系统内发布的有关利率的文件必须抄送辖区内中国人民银行，凡与中国人民银行有关规定不一致的内容，以中国人民银行的规定为准； （三）严格执行国家的利率政策和相关法规，加强自身及所辖分支机构的利率管理，发现问题应主动处理； （四）自觉接受并主动配合中国人民银行的利率管理和检查，提供真实的相关资料； （五）在营业场所挂牌公告法定利率水平； （六）对利率政策执行过程中出现的问题及时向中国人民银行报告。"},{"i":10,"n":"第十条","txt":"利率管理人员应当坚持原则，依法办事，不得悯私舞弊，泄露机密，玩忽职守。"},{"i":11,"n":"第十一条","txt":"城乡居民储蓄存款的计息和结息按《储蓄管理条例》有关条款办理。活期储蓄存款每年结息一次，六月三十日为结息日，结息后的利息并人本金起息，元以下尾数不计息。未到结息日清户时，按清户日挂牌公告的利率计息到清户前一日止。　　定期储蓄存款按存人日挂牌公告的利率计息，利随本清，遇利率调整不分段计息。 定活两便储蓄存款按支取日挂牌公告的一年期以内（含一年）相应档次的定期整存整取存款利率打折计息，打折后低于活期存款利率时，按活期存款利率计息。 通知存款的计息和结息按《通知存款管理办法》执行。 大额可转让定期存单在存期内按照存单开户日银行挂牌公告的利率计息，利随本清，遇利率调整不分段计息，逾期期间不计息。"},{"i":12,"n":"第十二条","txt":"单位存款的计息和结息按《人民币单位存款管理办法》的有关条款办理。 活期存款按季结息，每季末月的二十日为结息日。 单位通知存款计息和结息按《通知存款管理办法》执行。　　单位协定存款按结息日或清户日挂牌公告的利率计息，按季结息。"},{"i":13,"n":"第十三条","txt":"金融机构经中国人民银行批准收取的保证金，按照单位存款计息、结息。"},{"i":14,"n":"第十四条","txt":"职工个人住房公积金存款，当年归集的按结息日挂牌公告的活期存款利率计息，结息后转入上年结转户；上年结转的按结息日挂牌公告的三个月定期整存整取存款利率计息。公积金存款的结息日为每年的六月三十日。"},{"i":15,"n":"第十五条","txt":"金融机构的准备金存款按季结息，每季度末月的二十日为结息日，按结息日的利率计息，遇利率调整不分段计息。　　对欠交准备金的金融机构，从欠交之日起按罚息利率计收罚息，直至交足准备金止，遇罚息利率调整分段计息。"},{"i":16,"n":"第十六条","txt":"邮政储蓄转存款，按季结息，每季度末月的二十日为结息日，遇利率调整分段计息。"},{"i":17,"n":"第十七条","txt":"保险公司在中国人民银行的保证金存款按金融机构准备金存款利率计息，在其他金融机构的存款按单位存款利率计息。"},{"i":18,"n":"第十八条","txt":"金融机构按规定全额划缴中国人民银行的财政存款一律不计息，不划缴的部分按单位存款利率计息。"},{"i":19,"n":"第十九条","txt":"金融机构同业存款利率，最高不得超过准备金存款利率，计息和结息同第十五条。"},{"i":20,"n":"第二十条","txt":"短期贷款（期限在一年以下，含一年），按贷款合同签定日的相应档次的法定贷款利率计息。贷款合同期内，遇利率调整不分段计息。 短期贷款按季结息的，每季度末月的二十日为结息日；按月结息的，每月的二十日为结息日。具体结息方式由借贷双方协商确定。对贷款期内不能按期支付的利息按贷款合同利率按季或按月计收复利，贷款逾期后改按罚息利率计收复利。最后一笔贷款清偿时，利随本清。"},{"i":21,"n":"第二十一条","txt":"中长期贷款（期限在一年以上）利率实行一年一定。贷款（包括贷款合同生效日起一年内应分笔拨付的所有资金）根据贷款合同确定的期限，按贷款合同生效日相应档次的法定贷款利率计息，每满一年后（分笔拨付的以第一笔贷款的发放日为准），再按当时相应档次的法定贷款利率确定下一年度利率。中长期贷款按季结息，每季度末月二十日为结息日。对贷款期内不能按期支付的利息按合同利率按季计收复利，贷款逾期后改接罚息利率计收复利。"},{"i":22,"n":"第二十二条","txt":"贴现按贴现日确定的贴现利率一次性收取利息。"},{"i":23,"n":"第二十三条","txt":"信托贷款利率由委托双方在不超过同期同档次法定贷款利率水平（含浮动）的范围内协商确定；租赁贷款利率按同期同档次法定贷款利率（含浮动）执行。"},{"i":24,"n":"第二十四条","txt":"贷款展期，期限累计计算，累计期限达到新的利率期限档次时，自展期之日起，按展期日挂牌的同档次利率计息；达不到新的期限档次时，按展期日的原档次利率计息。"},{"i":25,"n":"第二十五条","txt":"逾期贷款或挤占挪用贷款，从逾期或挤占挪用之日起，按罚息利率计收罚息，直到清偿本息为止，遇罚息利率调整分段计息。对贷款逾期或挪用期间不能按期支付的利息按罚息利率按季（短期贷款也可按月）计收复利。如同一笔贷款既逾期又挤占挪用，应择其重，不能并处。"},{"i":26,"n":"第二十六条","txt":"借款人在借款合同到期日之前归还借款时，贷款人有权按原贷款合同向借款人收取利息。"},{"i":27,"n":"第二十七条","txt":"个人住房贷款利率及其计结息办法按《个人住房贷款管理办法》有关规定执行，贷款逾期按本规定第二十五条办理。"},{"i":28,"n":"第二十八条","txt":"中国人民银行对金融机构再贷款按合同利率计息，遇利率调整不分段计息。按季结息，每季度末月二十日为结息日。对贷款期内不能按期支付的利息按合同利率计收复利。　　再贷款展期，贷款期限不累计计算，按展期日相应档次的再贷款利率计息。再贷款逾期，按逾期日的罚息利率计收罚息，直到归还本息，遇罚息利率调整分段计息。对逾期期间不能按期支付的利息按罚息利率按季计收复利。"},{"i":29,"n":"第二十九条","txt":"再贴现按再贴现日的再贴现利率一次性收取利息。"},{"i":30,"n":"第三十条","txt":"有下列行为之一的，属于利率违规行为： （一）擅自提高或降低存、贷款利率的； （二）变相提高或降低存、贷款利率的； （三）擅自或变相以高利率发行债券的； （四）其他违反本规定和国家利率政策的。"},{"i":31,"n":"第三十一条","txt":"对存在上述利率违规行为的金融机构，中国人民银行将视其情节及所致后果轻重，依照有关法律法规给予相应处罚。"},{"i":32,"n":"第三十二条","txt":"金融机构违反国家法律法规和利率政策而多收的贷款利息或少付的存款利息，以及个人、法人及其他组织因金融机构违规而多收的存款利息或少付的贷款利息，不受法律保护。"},{"i":33,"n":"第三十三条","txt":"金融机构因非不可抗力拖延或拒绝支付存款人已到期合法存款的，末付期间按该笔存款原存单利率对存款人支付利息。"},{"i":34,"n":"第三十四条","txt":"对违反《企业债券管理条例》，擅自或变相以高利率发行债券的企业，辖区内中国人民银行有权制止，并会同有关部门依照《企业债券管理条例》等有关法规进行处罚。"},{"i":35,"n":"第三十五条","txt":"对违反本规定的金融机构的主要负责人、业务部门负责人及直接业务人员，视情节轻重和造成危害的程度，按照中国人民银行《关于对金融机构违法违规经营责任人的行政处分规定》给予相应处分。"},{"i":36,"n":"第三十六条","txt":"违反利率管理规定的当事人，对中国人民银行做出的处罚不服的，可以按《行政复议条例》有关规定向上一级人民银行申请复议。"},{"i":37,"n":"第三十七条","txt":"本规定由中国人民银行总行负责解释、说明和修改。"},{"i":38,"n":"第三十八条","txt":"本规定自一九九九年四月一日起实行。此前凡与本规定相抵触的，皆以本规定为准。"}],"renminbidanweicunkuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强单位存款的管理，规范金融机构的单位存款业务，根据《中华人民共和国中国人民银行法》、《中华人民共和国商业银行法》及其他有关法律、行政法规，制订本办法。"},{"i":2,"n":"第二条","txt":"凡在中华人民共和国境内办理人民币单位存款业务的金融机构和参加人民币存款的单位，必须遵守本办法的规定。"},{"i":3,"n":"第三条","txt":"本办法所称单位存款是指企业、事业、机关、部队和社会团体等单位在金融机构办理的人民币存款，包括定期存款、活期存款、通知存款、协定存款及经中国人民银行批准的其他存款。"},{"i":4,"n":"第四条","txt":"中国人民银行负责金融机构单位存款业务的管理、监督和稽核工作，协调存款单位与金融机构的争议。"},{"i":5,"n":"第五条","txt":"除经中国人民银行批准办理单位存款业务的金融机构外，其他任何单位和个人不得办理此项业务。"},{"i":6,"n":"第六条","txt":"经批准的金融机构吸收单位存款应不超过中国人民银行核定的范围，同时遵守本办法的有关规定。"},{"i":7,"n":"第七条","txt":"财政拨款、预算内资金及银行贷款不得作为单位定期存款存入金融机构。"},{"i":8,"n":"第八条","txt":"任何单位和个人不得将公款以个人名义转为储蓄存款。 任何个人不得将私款以单位名义存入金融机构；任何单位不得将个人或其他单位的款项以本单位名义存入金融机构。"},{"i":9,"n":"第九条","txt":"单位定期存款的期限分三个月、半年、一年三个档次。起存金额１万元，多存不限。"},{"i":10,"n":"第十条","txt":"金融机构对单位定期存款实行帐户管理（大额可转让定期存款除外）。存款时单位须提交开户申请书、营业执照正本等，并预留印鉴。印鉴应包括单位财务专用章、单位法定代表人章（或主要负责人印章）和财会人员章。由接受存款的金融机构给存款单位开出“单位定期存款开户证实书”（以下简称“证实书”），证实书仅对存款单位开户证实，不得作为质押的权利凭证。"},{"i":11,"n":"第十一条","txt":"存款单位支取定期存款只能以转帐方式将存款转入其基本存款帐户，不得将定期存款用于结算或从定期存款帐户中提取现金。支取定期存款时，须出具证实书并提供预留印鉴，存款所在金融机构审核无误后为其办理支取手续，同时收回证实书。"},{"i":12,"n":"第十二条","txt":"单位定期存款在存期内按存款存入日挂牌公告的定期存款利率计付利息，遇利率调整，不分段计息。"},{"i":13,"n":"第十三条","txt":"单位定期存款可以全部或部分提前支取，但只能提前支取一次。全部提前支取的，按支取日挂牌公告的活期存款利率计息；部分提前支取的，提前支取的部分按支取日挂牌公告的活期存款利率计息，其余部分如不低于起存金额由金融机构按原存期开具新的证实书，按原存款开户日挂牌公告的同档次定期存款利率计息；不足起存金额则予以清户。"},{"i":14,"n":"第十四条","txt":"单位定期存款到期不取，逾期部分按支取日挂牌公告的活期存款利率计付利息。"},{"i":15,"n":"第十五条","txt":"金融机构办理大额可转让定期存单业务按照《大额可转让定期存单管理办法》执行。"},{"i":16,"n":"第十六条","txt":"金融机构对单位活期存款实行帐户管理。金融机构和开立活期存款帐户的单位必须遵守《银行帐户管理办法》。"},{"i":17,"n":"第十七条","txt":"单位活期存款按结息日挂牌公告的活期存款利率计息，遇利率调整不分段计息。"},{"i":18,"n":"第十八条","txt":"金融机构开办单位通知存款须经中国人民银行批准，并遵守经中国人民银行核准的通知存款章程。通知存款按支取日挂牌公告的同期同档次通知存款利息计息。"},{"i":19,"n":"第十九条","txt":"金融机构开办协定存款须经中国人民银行批准，并遵守经人民银行核准的协定存款章程。协定存款利率由中国人民银行确定并公布。"},{"i":20,"n":"第二十条","txt":"因存款单位人事变动，需要更换单位法定代表人章（或单位负责人章）或财会人员印章时，必须持单位公函及经办人身份证件向存款所在金融机构办理更换印鉴手续，如为单位定期存款，应同时出示金融机构为其开具的证实书。"},{"i":21,"n":"第二十一条","txt":"因存款单位机构合并或分立，其定期存款需要过户或分户，必须持原单位公函、工商部门的变更、注销或设立登记证明及新印鉴（分户时还须提供双方同意的存款分户协定）等有关证件向存款所在金融机构办理过户或分户手续，由金融机构换发新证实书。"},{"i":22,"n":"第二十二条","txt":"存款单位的密码失密或印鉴遗失、损毁，必须持单位公函，向存款所在金融机构申请挂失。 金融机构受理挂失后，挂失生效。如存款在挂失生效前已被人按规定手续支取，金融机构不负赔偿责任。"},{"i":23,"n":"第二十三条","txt":"存款单位迁移时，其定期存款如未到期转移，应办理提前支取手续，按支取日挂牌公布的活期利率一次性结清。"},{"i":24,"n":"第二十四条","txt":"金融机构应对存款单位的存款保密，有权拒绝除法律、行政法规另有规定以外的任何单位或个人查询；有权拒绝除法律另有规定以外的任何单位冻结、扣划。"},{"i":25,"n":"第二十五条","txt":"未经中国人民银行批准，擅自开办单位存款业务的单位或个人，按照《中华人民共和国商业银行法》第七十九条予以处罚。"},{"i":26,"n":"第二十六条","txt":"商业银行违反国家利率政策提高或降低利率以及采用其他不正当手段吸收存款，或者超范围吸收单位存款的，按照《中华人民共和国商业银行法》第七十五条、第七十六条及《中国人民银行利率管理规定》的有关条款予以处罚。"},{"i":27,"n":"第二十七条","txt":"商业银行违反本办法第十一条规定，为存款单位支付现金的，或办理活期存款业务时违反《银行帐户管理办法》的，按照《现金管理暂行条例》、《大额现金支付登记备案制度》、《关于大额现金支付管理的通知》及《银行帐户管理办法》的有关规定予以处罚。"},{"i":28,"n":"第二十八条","txt":"商业银行违反本办法第二十四条规定，泄漏存款单位的存款情况或未经法定程序代为查询、冻结、扣划单位存款的，按照《中华人民共和国商业银行法》第七十三条予以处罚。"},{"i":29,"n":"第二十九条","txt":"非银行金融机构违反本办法规定的，按有关法律法规及金融管理规定予以处罚。"},{"i":30,"n":"第三十条","txt":"对处罚决定不服的，当事人可以依照《行政复议条例》的规定申请复议。对复议决定不服的，当事人可以依照《中华人民共和国行政诉讼法》的规定向人民法院提起诉讼。"},{"i":31,"n":"第三十一条","txt":"本办法由中国人民银行负责解释。"},{"i":32,"n":"第三十二条","txt":"本办法从发布之日起执行。中国人民银行1982年制订的《单位定期存款暂行办法》（银发〔1982〕165号）同时废止。"}],"renminbituyangshiyongguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范人民币图样使用行为，维护人民币信誉和流通秩序，根据《中华人民共和国中国人民银行法》和《中华人民共和国人民币管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称人民币图样是指中国人民银行发行的货币的完整图案或者局部图案。"},{"i":3,"n":"第三条","txt":"本办法所称使用人民币图样是指通过各种形式在宣传品、出版物或者其他商品上使用放大、缩小和同样大小人民币图样的行为。"},{"i":4,"n":"第四条","txt":"禁止在祭祀用品、生活用品、票券上使用人民币图样。"},{"i":5,"n":"第五条","txt":"在中华人民共和国境内依法设立的法人、其他组织及自然人以弘扬民族优秀文化和反映国内外科学文化成果、宣传爱护人民币和人民币防伪知识、展示人民币设计艺术、促进钱币文化健康发展为目的，可以申请使用人民币图样。"},{"i":6,"n":"第六条","txt":"使用人民币图样实行属地管理、一事一批。中国人民银行上海总部、各分行、营业管理部、省会（首府）城市中心支行、深圳市中心支行是使用人民币图样的审批机构。中国人民银行当地分支机构是使用人民币图样申请的受理机构。 中国人民银行对其分支机构的审批工作进行统一监督管理。"},{"i":7,"n":"第七条","txt":"申请使用人民币图样的申请人，应当向中国人民银行当地分支机构提供以下材料： （一）《人民币图样使用申请表》（见附件）。 （二）申请人身份证件、营业执照或者法人登记证书。 （三）拟使用人民币图样产品的设计稿。 （四）拟使用人民币图样产品的广告宣传文案。 （五）中国人民银行要求的其他相关材料。"},{"i":8,"n":"第八条","txt":"审批机构应当在《中华人民共和国行政许可法》规定时间内完成人民币图样使用申请的受理及审核工作，作出是否准予使用人民币图样的决定。"},{"i":9,"n":"第九条","txt":"使用人民币图样应当遵守下列规定： （一）单面使用。 （二）不损害人民币形象、不损害国家利益和社会公共利益。 （三）不使公众误认为是人民币。 （四）保证人民币图样中人物头像、国徽的原有比例，不变形、失真、破坏或者被替换。 （五）使用人民币图样，须在图样中部明显位置标注清晰可辨的“图样”字样。“图样”字样的长度、宽度分别不低于图样长度、宽度的三分之一。以下情形除外： 1.使用人民币硬币图样； 2.使用人民币纸币图样单面面积小于原大小的50%； 3.在有形载体上使用各边长放大和缩小比例超过原边长50%的人民币纸币图样； 4.在数字载体上使用分辨率小于28像素/厘米（72dpi）的人民币纸币图样。 （六）使用人民币图样制作商品时，不得使用“中国人民银行”行名和货币单位。"},{"i":10,"n":"第十条","txt":"被许可人应当在产品面市前将产品照片及说明产品制作单位、规格材质、宣传方式等情况的材料报审批机构备案。"},{"i":11,"n":"第十一条","txt":"被许可人应当按照许可批准文件核准的范围使用人民币图样，并与申请事项保持一致。被许可人应当在使用人民币图样时注明被许可人名称、许可批准文件号及产品制作单位名称。"},{"i":12,"n":"第十二条","txt":"依法取得的人民币图样使用许可不得转让。不得涂改、倒卖、出租、出借人民币图样使用许可批准文件。 被许可人应当妥善保管图样制作模具和图样源信息，防止人民币图样被非法使用。"},{"i":13,"n":"第十三条","txt":"中国人民银行及其分支机构有权对被许可人进行监督检查，被许可人应当如实提供有关资料，不得拒绝、阻挠、逃避检查，不得谎报、隐匿、销毁相关证据材料。"},{"i":14,"n":"第十四条","txt":"任何单位和个人不得销售非法使用人民币图样的宣传品、出版物或者其他商品。销售经批准使用人民币图样的宣传品、出版物或者其他商品时，不得滥用许可进行虚假宣传和炒作。"},{"i":15,"n":"第十五条","txt":"出于以下目的在宣传品、出版物上使用中国人民银行网站人民币图样库中公布的人民币图样的行为可以不经审批，但必须遵守本办法第九条的规定，并随时接受中国人民银行及其分支机构的监督检查： （一）中华人民共和国境内依法设立的图书出版、教学研究、新闻媒体、文博机构等单位出于教学、学术研究、人民币知识普及、公益宣传目的使用人民币图样。 （二）银行业金融机构、人民币印制企业出于人民币宣传目的使用人民币图样。"},{"i":16,"n":"第十六条","txt":"有下列行为之一的，由中国人民银行或其分支机构给予警告，并按照《中华人民共和国中国人民银行法》第四十四条的规定予以处罚： （一）违反本办法规定，未经许可使用人民币图样的。 （二）违反本办法第四条，在祭祀用品、生活用品、票券上使用人民币图样的。 （三）违反本办法第九条，未按规定使用人民币图样的。 （四）违反本办法第十条，未按要求将相关材料报审批机构备案的。 （五）违反本办法第十一条，未按照许可批准文件核准的范围使用人民币图样、使用人民币图样与申请事项不一致或者未在使用人民币图样时注明规定信息的。 （六）违反本办法第十二条第一款，转让人民币图样使用许可，涂改、倒卖、出租、出借人民币图样使用许可批准文件的。 违反本办法第十二条第二款、第十四条规定的,由中国人民银行或其分支机构予以警告，并处5000元以上3万元以下罚款。"},{"i":17,"n":"第十七条","txt":"违反本办法第十三条、第十五条，拒绝、阻挠、逃避中国人民银行及其分支机构检查，或者谎报、隐匿、销毁相关证据材料的，有关法律、行政法规有处罚规定的，依照其规定给予处罚；有关法律、行政法规未作处罚规定的，由中国人民银行或其分支机构予以警告，并处5000元以上3万元以下罚款。"},{"i":18,"n":"第十八条","txt":"本办法由中国人民银行负责解释。"},{"i":19,"n":"第十九条","txt":"本办法自2019年11月15日起施行。原《人民币图样使用管理办法》（中国人民银行令〔2005〕第4号发布）同时废止。"}],"renminbiyinhangjiesuanzhanghuguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范人民币银行结算账户（以下简称银行结算账户）的开立和使用，加强银行结算账户管理，维护经济金融秩序稳定，根据《中华人民共和国中国人民银行法》和《中华人民共和国商业银行法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"存款人在中国境内的银行开立的银行结算账户适用本办法。 本办法所称存款人，是指在中国境内开立银行结算账户的机关、团体、部队、企业、事业单位、其他组织（以下统称单位）、个体工商户和自然人。 本办法所称银行，是指在中国境内经中国人民银行批准经营支付结算业务的政策性银行、商业银行（含外资独资银行、中外合资银行、外国银行分行）、城市信用合作社、农村信用合作社。 本办法所称银行结算账户，是指银行为存款人开立的办理资金收付结算的人民币活期存款账户。"},{"i":3,"n":"第三条","txt":"银行结算账户按存款人分为单位银行结算账户和个人银行结算账户。 （一）存款人以单位名称开立的银行结算账户为单位银行结算账户。单位银行结算账户按用途分为基本存款账户、一般存款账户、专用存款账户、临时存款账户。 个体工商户凭营业执照以字号或经营者姓名开立的银行结算账户纳入单位银行结算账户管理。 （二）存款人凭个人身份证件以自然人名称开立的银行结算账户为个人银行结算账户。 邮政储蓄机构办理银行卡业务开立的账户纳入个人银行结算账户管理。"},{"i":4,"n":"第四条","txt":"单位银行结算账户的存款人只能在银行开立一个基本存款账户。"},{"i":5,"n":"第五条","txt":"存款人应在注册地或住所地开立银行结算账户。符合本办法规定可以在异地（跨省、市、县）开立银行结算账户的除外。"},{"i":6,"n":"第六条","txt":"存款人开立基本存款账户、临时存款账户和预算单位开立专用存款账户实行核准制度，经中国人民银行核准后由开户银行核发开户登记证。但存款人因注册验资需要开立的临时存款账户除外。"},{"i":7,"n":"第七条","txt":"存款人可以自主选择银行开立银行结算账户。除国家法律、行政法规和国务院规定外，任何单位和个人不得强令存款人到指定银行开立银行结算账户。"},{"i":8,"n":"第八条","txt":"银行结算账户的开立和使用应当遵守法律、行政法规，不得利用银行结算账户进行偷逃税款、逃废债务、套取现金及其他违法犯罪活动。"},{"i":9,"n":"第九条","txt":"银行应依法为存款人的银行结算账户信息保密。对单位银行结算账户的存款和有关资料，除国家法律、行政法规另有规定外，银行有权拒绝任何单位或个人查询。对个人银行结算账户的存款和有关资料，除国家法律另有规定外，银行有权拒绝任何单位或个人查询。"},{"i":10,"n":"第十条","txt":"中国人民银行是银行结算账户的监督管理部门。"},{"i":11,"n":"第十一条","txt":"基本存款账户是存款人因办理日常转账结算和现金收付需要开立的银行结算账户。下列存款人，可以申请开立基本存款账户： （一）企业法人。 （二）非法人企业。 （三）机关、事业单位。 （四）团级（含）以上军队、武警部队及分散执勤的支（分）队。 （五）社会团体。 （六）民办非企业组织。 （七）异地常设机构。 （八）外国驻华机构。 （九）个体工商户。 （十）居民委员会、村民委员会、社区委员会。 （十一）单位设立的独立核算的附属机构。 （十二）其他组织。"},{"i":12,"n":"第十二条","txt":"一般存款账户是存款人因借款或其他结算需要，在基本存款账户开户银行以外的银行营业机构开立的银行结算账户。"},{"i":13,"n":"第十三条","txt":"专用存款账户是存款人按照法律、行政法规和规章，对其特定用途资金进行专项管理和使用而开立的银行结算账户。对下列资金的管理与使用，存款人可以申请开立专用存款账户： （一）基本建设资金。 （二）更新改造资金。 （三）财政预算外资金。 （四）粮、棉、油收购资金。 （五）证券交易结算资金。 （六）期货交易保证金。 （七）信托基金。 （八）金融机构存放同业资金。 （九）政策性房地产开发资金。 （十）单位银行卡备用金。 （十一）住房基金。 （十二）社会保障基金。 （十三）收入汇缴资金和业务支出资金。 （十四）党、团、工会设在单位的组织机构经费。 （十五）其他需要专项管理和使用的资金。 收入汇缴资金和业务支出资金，是指基本存款账户存款人附属的非独立核算单位或派出机构发生的收入和支出的资金。 因收入汇缴资金和业务支出资金开立的专用存款账户，应使用隶属单位的名称。"},{"i":14,"n":"第十四条","txt":"临时存款账户是存款人因临时需要并在规定期限内使用而开立的银行结算账户。有下列情况的，存款人可以申请开立临时存款账户： （一）设立临时机构。 （二）异地临时经营活动。 （三）注册验资。"},{"i":15,"n":"第十五条","txt":"个人银行结算账户是自然人因投资、消费、结算等而开立的可办理支付结算业务的存款账户。有下列情况的，可以申请开立个人银行结算账户： （一）使用支票、信用卡等信用支付工具的。 （二）办理汇兑、定期借记、定期贷记、借记卡等结算业务的。 自然人可根据需要申请开立个人银行结算账户，也可以在已开立的储蓄账户中选择并向开户银行申请确认为个人银行结算账户。"},{"i":16,"n":"第十六条","txt":"存款人有下列情形之一的，可以在异地开立有关银行结算账户： （一）营业执照注册地与经营地不在同一行政区域（跨省、市、县）需要开立基本存款账户的。 （二）办理异地借款和其他结算需要开立一般存款账户的。 （三）存款人因附属的非独立核算单位或派出机构发生的收入汇缴或业务支出需要开立专用存款账户的。 （四）异地临时经营活动需要开立临时存款账户的。 （五）自然人根据需要在异地开立个人银行结算账户的。"},{"i":17,"n":"第十七条","txt":"存款人申请开立基本存款账户，应向银行出具下列证明文件： （一）企业法人，应出具企业法人营业执照正本。 （二）非法人企业，应出具企业营业执照正本。 （三）机关和实行预算管理的事业单位，应出具政府人事部门或编制委员会的批文或登记证书和财政部门同意其开户的证明；非预算管理的事业单位，应出具政府人事部门或编制委员会的批文或登记证书。 （四）军队、武警团级（含）以上单位以及分散执勤的支（分）队，应出具军队军级以上单位财务部门、武警总队财务部门的开户证明。 （五）社会团体，应出具社会团体登记证书，宗教组织还应出具宗教事务管理部门的批文或证明。 （六）民办非企业组织，应出具民办非企业登记证书。 （七）外地常设机构，应出具其驻在地政府主管部门的批文。 （八）外国驻华机构，应出具国家有关主管部门的批文或证明；外资企业驻华代表处、办事处应出具国家登记机关颁发的登记证。 （九）个体工商户，应出具个体工商户营"},{"i":18,"n":"第十八条","txt":"存款人申请开立一般存款账户，应向银行出具其开立基本存款账户规定的证明文件、基本存款账户开户登记证和下列证明文件： （一）存款人因向银行借款需要，应出具借款合同。 （二）存款人因其他结算需要，应出具有关证明。"},{"i":19,"n":"第十九条","txt":"存款人申请开立专用存款账户，应向银行出具其开立基本存款账户规定的证明文件、基本存款账户开户登记证和下列证明文件： （一）基本建设资金、更新改造资金、政策性房地产开发资金、住房基金、社会保障基金，应出具主管部门批文。 （二）财政预算外资金，应出具财政部门的证明。 （三）粮、棉、油收购资金，应出具主管部门批文。 （四）单位银行卡备用金，应按照中国人民银行批准的银行卡章程的规定出具有关证明和资料。 （五）证券交易结算资金，应出具证券公司或证券管理部门的证明。 （六）期货交易保证金，应出具期货公司或期货管理部门的证明。 （七）金融机构存放同业资金，应出具其证明。 （八）收入汇缴资金和业务支出资金，应出具基本存款账户存款人有关的证明。 （九）党、团、工会设在单位的组织机构经费，应出具该单位或有关部门的批文或证明。 （十）其他按规定需要专项管理和使用的资金，应出具有关法规、规章或政府部门的有关文件"},{"i":20,"n":"第二十条","txt":"合格境外机构投资者在境内从事证券投资开立的人民币特殊账户和人民币结算资金账户纳入专用存款账户管理。其开立人民币特殊账户时应出具国家外汇管理部门的批复文件，开立人民币结算资金账户时应出具证券管理部门的证券投资业务许可证。"},{"i":21,"n":"第二十一条","txt":"存款人申请开立临时存款账户，应向银行出具下列证明文件： （一）临时机构，应出具其驻在地主管部门同意设立临时机构的批文。 （二）异地建筑施工及安装单位，应出具其营业执照正本或其隶属单位的营业执照正本，以及施工及安装地建设主管部门核发的许可证或建筑施工及安装合同。 （三）异地从事临时经营活动的单位，应出具其营业执照正本以及临时经营地工商行政管理部门的批文。 （四）注册验资资金，应出具工商行政管理部门核发的企业名称预先核准通知书或有关部门的批文。 本条第二、三项还应出具其基本存款账户开户登记证。"},{"i":22,"n":"第二十二条","txt":"存款人申请开立个人银行结算账户，应向银行出具下列证明文件： （一）中国居民，应出具居民身份证或临时身份证。 （二）中国人民解放军军人，应出具军人身份证件。 （三）中国人民武装警察，应出具武警身份证件。 （四）香港、澳门居民，应出具港澳居民往来内地通行证；台湾居民，应出具台湾居民来往大陆通行证或者其他有效旅行证件。 （五）外国公民，应出具护照。 （六）法律、法规和国家有关文件规定的其他有效证件。 银行为个人开立银行结算账户时，根据需要还可要求申请人出具户口簿、驾驶执照、护照等有效证件。"},{"i":23,"n":"第二十三条","txt":"存款人需要在异地开立单位银行结算账户，除出具本办法第十七条、十八条、十九条、二十一条规定的有关证明文件外，应出具下列相应的证明文件： （一）经营地与注册地不在同一行政区域的存款人，在异地开立基本存款账户的，应出具注册地中国人民银行分支行的未开立基本存款账户的证明。 （二）异地借款的存款人，在异地开立一般存款账户的，应出具在异地取得贷款的借款合同。 （三）因经营需要在异地办理收入汇缴和业务支出的存款人，在异地开立专用存款账户的，应出具隶属单位的证明。 属本条第二、三项情况的，还应出具其基本存款账户开户登记证。 存款人需要在异地开立个人银行结算账户，应出具本办法第二十二条规定的证明文件。"},{"i":24,"n":"第二十四条","txt":"单位开立银行结算账户的名称应与其提供的申请开户的证明文件的名称全称相一致。有字号的个体工商户开立银行结算账户的名称应与其营业执照的字号相一致；无字号的个体工商户开立银行结算账户的名称，由“个体户”字样和营业执照记载的经营者姓名组成。自然人开立银行结算账户的名称应与其提供的有效身份证件中的名称全称相一致。"},{"i":25,"n":"第二十五条","txt":"银行为存款人开立一般存款账户、专用存款账户和临时存款账户的，应自开户之日起3个工作日内书面通知基本存款账户开户银行。"},{"i":26,"n":"第二十六条","txt":"存款人申请开立单位银行结算账户时，可由法定代表人或单位负责人直接办理，也可授权他人办理。 由法定代表人或单位负责人直接办理的，除出具相应的证明文件外，还应出具法定代表人或单位负责人的身份证件；授权他人办理的，除出具相应的证明文件外，还应出具其法定代表人或单位负责人的授权书及其身份证件，以及被授权人的身份证件。"},{"i":27,"n":"第二十七条","txt":"存款人申请开立银行结算账户时，应填制开户申请书。开户申请书按照中国人民银行的规定记载有关事项。"},{"i":28,"n":"第二十八条","txt":"银行应对存款人的开户申请书填写的事项和证明文件的真实性、完整性、合规性进行认真审查。 开户申请书填写的事项齐全，符合开立基本存款账户、临时存款账户和预算单位专用存款账户条件的，银行应将存款人的开户申请书、相关的证明文件和银行审核意见等开户资料报送中国人民银行当地分支行，经其核准后办理开户手续；符合开立一般存款账户、其他专用存款账户和个人银行结算账户条件的，银行应办理开户手续，并于开户之日起5个工作日内向中国人民银行当地分支行备案。"},{"i":29,"n":"第二十九条","txt":"中国人民银行应于2个工作日内对银行报送的基本存款账户、临时存款账户和预算单位专用存款账户的开户资料的合规性予以审核，符合开户条件的，予以核准；不符合开户条件的，应在开户申请书上签署意见，连同有关证明文件一并退回报送银行。"},{"i":30,"n":"第三十条","txt":"银行为存款人开立银行结算账户，应与存款人签订银行结算账户管理协议，明确双方的权利与义务。除中国人民银行另有规定的以外，应建立存款人预留签章卡片，并将签章式样和有关证明文件的原件或复印件留存归档。"},{"i":31,"n":"第三十一条","txt":"开户登记证是记载单位银行结算账户信息的有效证明，存款人应按本办法的规定使用，并妥善保管。"},{"i":32,"n":"第三十二条","txt":"银行在为存款人开立一般存款账户、专用存款账户和临时存款账户时，应在其基本存款账户开户登记证上登记账户名称、账号、账户性质、开户银行、开户日期，并签章。但临时机构和注册验资需要开立的临时存款账户除外。"},{"i":33,"n":"第三十三条","txt":"基本存款账户是存款人的主办账户。存款人日常经营活动的资金收付及其工资、奖金和现金的支取，应通过该账户办理。"},{"i":34,"n":"第三十四条","txt":"一般存款账户用于办理存款人借款转存、借款归还和其他结算的资金收付。该账户可以办理现金缴存，但不得办理现金支取。"},{"i":35,"n":"第三十五条","txt":"专用存款账户用于办理各项专用资金的收付。 单位银行卡账户的资金必须由其基本存款账户转账存入。该账户不得办理现金收付业务。 财政预算外资金、证券交易结算资金、期货交易保证金和信托基金专用存款账户不得支取现金。 基本建设资金、更新改造资金、政策性房地产开发资金、金融机构存放同业资金账户需要支取现金的，应在开户时报中国人民银行当地分支行批准。中国人民银行当地分支行应根据国家现金管理的规定审查批准。 粮、棉、油收购资金、社会保障基金、住房基金和党、团、工会经费等专用存款账户支取现金应按照国家现金管理的规定办理。 收入汇缴账户除向其基本存款账户或预算外资金财政专用存款户划缴款项外，只收不付，不得支取现金。业务支出账户除从其基本存款账户拨入款项外，只付不收，其现金支取必须按照国家现金管理的规定办理。 银行应按照本条的各项规定和国家对粮、棉、油收购资金使用管理规定加强监督，对不符合规定的资金收付和现"},{"i":36,"n":"第三十六条","txt":"临时存款账户用于办理临时机构以及存款人临时经营活动发生的资金收付。 临时存款账户应根据有关开户证明文件确定的期限或存款人的需要确定其有效期限。存款人在账户的使用中需要延长期限的，应在有效期限内向开户银行提出申请，并由开户银行报中国人民银行当地分支行核准后办理展期。临时存款账户的有效期最长不得超过2年。 临时存款账户支取现金，应按照国家现金管理的规定办理。"},{"i":37,"n":"第三十七条","txt":"注册验资的临时存款账户在验资期间只收不付，注册验资资金的汇缴人应与出资人的名称一致。"},{"i":38,"n":"第三十八条","txt":"存款人开立单位银行结算账户，自正式开立之日起3个工作日后，方可办理付款业务。但注册验资的临时存款账户转为基本存款账户和因借款转存开立的一般存款账户除外。"},{"i":39,"n":"第三十九条","txt":"个人银行结算账户用于办理个人转账收付和现金存取。下列款项可以转入个人银行结算账户： （一）工资、奖金收入。 （二）稿费、演出费等劳务收入。 （三）债券、期货、信托等投资的本金和收益。 （四）个人债权或产权转让收益。 （五）个人贷款转存。 （六）证券交易结算资金和期货交易保证金。 （七）继承、赠与款项。 （八）保险理赔、保费退还等款项。 （九）纳税退还。 （十）农、副、矿产品销售收入。 （十一）其他合法款项。"},{"i":40,"n":"第四十条","txt":"单位从其银行结算账户支付给个人银行结算账户的款项，每笔超过5万元的，应向其开户银行提供下列付款依据： （一）代发工资协议和收款人清单。 （二）奖励证明。 （三）新闻出版、演出主办等单位与收款人签订的劳务合同或支付给个人款项的证明。 （四）证券公司、期货公司、信托投资公司、奖券发行或承销部门支付或退还给自然人款项的证明。 （五）债权或产权转让协议。 （六）借款合同。 （七）保险公司的证明。 （八）税收征管部门的证明。 （九）农、副、矿产品购销合同。 （十）其他合法款项的证明。 从单位银行结算账户支付给个人银行结算账户的款项应纳税的，税收代扣单位付款时应向其开户银行提供完税证明。"},{"i":41,"n":"第四十一条","txt":"有下列情形之一的，个人应出具本办法第四十条规定的有关收款依据。 （一）个人持出票人为单位的支票向开户银行委托收款，将款项转入其个人银行结算账户的。 （二）个人持申请人为单位的银行汇票和银行本票向开户银行提示付款，将款项转入其个人银行结算账户的。"},{"i":42,"n":"第四十二条","txt":"单位银行结算账户支付给个人银行结算账户款项的，银行应按第四十条、第四十一条规定认真审查付款依据或收款依据的原件，并留存复印件，按会计档案保管。未提供相关依据或相关依据不符合规定的，银行应拒绝办理。"},{"i":43,"n":"第四十三条","txt":"储蓄账户仅限于办理现金存取业务，不得办理转账结算。"},{"i":44,"n":"第四十四条","txt":"银行应按规定与存款人核对账务。银行结算账户的存款人收到对账单或对账信息后，应及时核对账务并在规定期限内向银行发出对账回单或确认信息。"},{"i":45,"n":"第四十五条","txt":"存款人应按照本办法的规定使用银行结算账户办理结算业务。 存款人不得出租、出借银行结算账户，不得利用银行结算账户套取银行信用。"},{"i":46,"n":"第四十六条","txt":"存款人更改名称，但不改变开户银行及账号的，应于5个工作日内向开户银行提出银行结算账户的变更申请，并出具有关部门的证明文件。"},{"i":47,"n":"第四十七条","txt":"单位的法定代表人或主要负责人、住址以及其他开户资料发生变更时，应于5个工作日内书面通知开户银行并提供有关证明。"},{"i":48,"n":"第四十八条","txt":"银行接到存款人的变更通知后，应及时办理变更手续，并于2个工作日内向中国人民银行报告。"},{"i":49,"n":"第四十九条","txt":"有下列情形之一的，存款人应向开户银行提出撤销银行结算账户的申请： （一）被撤并、解散、宣告破产或关闭的。 （二）注销、被吊销营业执照的。 （三）因迁址需要变更开户银行的。 （四）其他原因需要撤销银行结算账户的。 存款人有本条第一、二项情形的，应于5个工作日内向开户银行提出撤销银行结算账户的申请。 本条所称撤销是指存款人因开户资格或其他原因终止银行结算账户使用的行为。"},{"i":50,"n":"第五十条","txt":"存款人因本办法第四十九条第一、二项原因撤销基本存款账户的，存款人基本存款账户的开户银行应自撤销银行结算账户之日起2个工作日内将撤销该基本存款账户的情况书面通知该存款人其他银行结算账户的开户银行；存款人其他银行结算账户的开户银行，应自收到通知之日起2个工作日内通知存款人撤销有关银行结算账户；存款人应自收到通知之日起3个工作日内办理其他银行结算账户的撤销。"},{"i":51,"n":"第五十一条","txt":"银行得知存款人有本办法第四十九条第一、二项情况，存款人超过规定期限未主动办理撤销银行结算账户手续的，银行有权停止其银行结算账户的对外支付。"},{"i":52,"n":"第五十二条","txt":"未获得工商行政管理部门核准登记的单位，在验资期满后，应向银行申请撤销注册验资临时存款账户，其账户资金应退还给原汇款人账户。注册验资资金以现金方式存入，出资人需提取现金的，应出具缴存现金时的现金缴款单原件及其有效身份证件。"},{"i":53,"n":"第五十三条","txt":"存款人尚未清偿其开户银行债务的，不得申请撤销该账户。"},{"i":54,"n":"第五十四条","txt":"存款人撤销银行结算账户，必须与开户银行核对银行结算账户存款余额，交回各种重要空白票据及结算凭证和开户登记证，银行核对无误后方可办理销户手续。存款人未按规定交回各种重要空白票据及结算凭证的，应出具有关证明，造成损失的，由其自行承担。"},{"i":55,"n":"第五十五条","txt":"银行撤销单位银行结算账户时应在其基本存款账户开户登记证上注明销户日期并签章，同时于撤销银行结算账户之日起2个工作日内，向中国人民银行报告。"},{"i":56,"n":"第五十六条","txt":"银行对一年未发生收付活动且未欠开户银行债务的单位银行结算账户，应通知单位自发出通知之日起30日内办理销户手续，逾期视同自愿销户，未划转款项列入久悬未取专户管理。"},{"i":57,"n":"第五十七条","txt":"中国人民银行负责监督、检查银行结算账户的开立和使用，对存款人、银行违反银行结算账户管理规定的行为予以处罚。"},{"i":58,"n":"第五十八条","txt":"中国人民银行对银行结算账户的开立和使用实施监控和管理。"},{"i":59,"n":"第五十九条","txt":"中国人民银行负责基本存款账户、临时存款账户和预算单位专用存款账户开户登记证的管理。 任何单位及个人不得伪造、变造及私自印制开户登记证。"},{"i":60,"n":"第六十条","txt":"银行负责所属营业机构银行结算账户开立和使用的管理，监督和检查其执行本办法的情况，纠正违规开立和使用银行结算账户的行为。"},{"i":61,"n":"第六十一条","txt":"银行应明确专人负责银行结算账户的开立、使用和撤销的审查和管理，负责对存款人开户申请资料的审查，并按照本办法的规定及时报送存款人开销户信息资料，建立健全开销户登记制度，建立银行结算账户管理档案，按会计档案进行管理。 银行结算账户管理档案的保管期限为银行结算账户撤销后10年。"},{"i":62,"n":"第六十二条","txt":"银行应对已开立的单位银行结算账户实行年检制度，检查开立的银行结算账户的合规性，核实开户资料的真实性；对不符合本办法规定开立的单位银行结算账户，应予以撤销。对经核实的各类银行结算账户的资料变动情况，应及时报告中国人民银行当地分支行。 银行应对存款人使用银行结算账户的情况进行监督，对存款人的可疑支付应按照中国人民银行规定的程序及时报告。"},{"i":63,"n":"第六十三条","txt":"存款人应加强对预留银行签章的管理。单位遗失预留公章或财务专用章的，应向开户银行出具书面申请、开户登记证、营业执照等相关证明文件；更换预留公章或财务专用章时，应向开户银行出具书面申请、原预留签章的式样等相关证明文件。个人遗失或更换预留个人印章或更换签字人时，应向开户银行出具经签名确认的书面申请，以及原预留印章或签字人的个人身份证件。银行应留存相应的复印件，并凭以办理预留银行签章的变更。"},{"i":64,"n":"第六十四条","txt":"存款人开立、撤销银行结算账户，不得有下列行为： （一）违反本办法规定开立银行结算账户。 （二）伪造、变造证明文件欺骗银行开立银行结算账户。 （三）违反本办法规定不及时撤销银行结算账户。 非经营性的存款人，有上述所列行为之一的，给予警告并处以1000元的罚款；经营性的存款人有上述所列行为之一的，给予警告并处以1万元以上3万元以下的罚款；构成犯罪的，移交司法机关依法追究刑事责任。"},{"i":65,"n":"第六十五条","txt":"存款人使用银行结算账户，不得有下列行为： （一）违反本办法规定将单位款项转入个人银行结算账户。 （二）违反本办法规定支取现金。 （三）利用开立银行结算账户逃废银行债务。 （四）出租、出借银行结算账户。 （五）从基本存款账户之外的银行结算账户转账存入、将销货收入存入或现金存入单位信用卡账户。 （六）法定代表人或主要负责人、存款人地址以及其他开户资料的变更事项未在规定期限内通知银行。 非经营性的存款人有上述所列一至五项行为的，给予警告并处以1000元罚款；经营性的存款人有上述所列一至五项行为的，给予警告并处以5000元以上3万元以下的罚款；存款人有上述所列第六项行为的，给予警告并处以1000元的罚款。"},{"i":66,"n":"第六十六条","txt":"银行在银行结算账户的开立中，不得有下列行为： （一）违反本办法规定为存款人多头开立银行结算账户。 （二）明知或应知是单位资金，而允许以自然人名称开立账户存储。 银行有上述所列行为之一的，给予警告，并处以5万元以上30万元以下的罚款；对该银行直接负责的高级管理人员、其他直接负责的主管人员、直接责任人员按规定给予纪律处分；情节严重的，中国人民银行有权停止对其开立基本存款账户的核准，责令该银行停业整顿或者吊销经营金融业务许可证；构成犯罪的，移交司法机关依法追究刑事责任。"},{"i":67,"n":"第六十七条","txt":"银行在银行结算账户的使用中，不得有下列行为： （一）提供虚假开户申请资料欺骗中国人民银行许可开立基本存款账户、临时存款账户、预算单位专用存款账户。 （二）开立或撤销单位银行结算账户，未按本办法规定在其基本存款账户开户登记证上予以登记、签章或通知相关开户银行。 （三）违反本办法第四十二条规定办理个人银行结算账户转账结算。 （四）为储蓄账户办理转账结算。 （五）违反规定为存款人支付现金或办理现金存入。 （六）超过期限或未向中国人民银行报送账户开立、变更、撤销等资料。 银行有上述所列行为之一的，给予警告，并处以5000元以上3万元以下的罚款；对该银行直接负责的高级管理人员、其他直接负责的主管人员、直接责任人员按规定给予纪律处分；情节严重的，中国人民银行有权停止对其开立基本存款账户的核准；构成犯罪的，移交司法机关依法追究刑事责任。"},{"i":68,"n":"第六十八条","txt":"违反本办法规定，伪造、变造、私自印制开户登记证的存款人，属非经营性的处以1000元罚款；属经营性的处以1万元以上3万元以下的罚款；构成犯罪的，移交司法机关依法追究刑事责任。"},{"i":69,"n":"第六十九条","txt":"开户登记证由中国人民银行总行统一式样，中国人民银行各分行、营业管理部、省会（首府）城市中心支行负责监制。"},{"i":70,"n":"第七十条","txt":"本办法由中国人民银行负责解释、修改。"},{"i":71,"n":"第七十一条","txt":"本办法自2003年9月1日起施行。1994年10月9日中国人民银行发布的《银行账户管理办法》同时废止。"}],"xinyongpingjiyeguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了规范信用评级业务，保护当事人合法权益，促进信用评级业健康发展，根据《中华人民共和国中国人民银行法》、《中华人民共和国公司法》、《中华人民共和国证券法》、《中华人民共和国预算法》、《企业债券管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事信用评级业务，适用本办法。法律法规和有关业务管理部门制定的信用评级机构监督管理规则中另有规定的，适用其规定。 本办法所称信用评级，是指信用评级机构对影响经济主体或者债务融资工具的信用风险因素进行分析，就其偿债能力和偿债意愿作出综合评价，并通过预先定义的信用等级符号进行表示。 本办法所称信用评级业务，是指为开展信用评级而进行的信息收集、分析、评估、审核和结果发布等活动。 本办法所称信用评级机构，是指依法设立，主要从事信用评级业务的社会中介机构。 本办法所称评级对象，是指受评经济主体或者受评债务融资工具。 本办法所称债务融资工具，包括：贷款，地方政府债券、金融债券、非金融企业债务融资工具、企业债券、公司债券等债券，资产支持证券等结构化融资产品，其他债务类融资产品。"},{"i":3,"n":"第三条","txt":"本办法所称监管主体包括信用评级行业主管部门和业务管理部门。中国人民银行是信用评级行业主管部门，主管全国的信用评级监督管理工作。 发展改革委、财政部、证监会为信用评级业务管理部门（以下统称业务管理部门），在职责范围内依法对信用评级业务实施监督管理。"},{"i":4,"n":"第四条","txt":"信用评级行业主管部门履行以下职责： （一）研究起草信用评级相关法律法规草案； （二）拟定信用评级业发展战略、规划和政策； （三）制定信用评级机构的准入原则和基本规范； （四）研究制定信用评级业对外开放政策; （五）促进信用评级业健康发展。"},{"i":5,"n":"第五条","txt":"业务管理部门依据相关法律法规和监管职责，对信用评级业务进行监督管理。业务管理部门可以根据需要，对信用评级机构的监督管理制定相应规则。"},{"i":6,"n":"第六条","txt":"信用评级行业主管部门和业务管理部门建立部际协调机制，根据职责分工，协调配合，共同加强监管工作。"},{"i":7,"n":"第七条","txt":"信用评级行业主管部门、业务管理部门在各自职责范围内分别建立信用评级机构信用档案和信用评级机构高级管理人员信用档案，并将信用评级机构及高级管理人员信用档案信息、评级业务信息、检查及行政处罚等信息纳入全国信用信息共享平台，按照有关规定，实现信息公开与共享。 信用评级机构应当建立本机构从业人员信用档案，并将从业人员信用档案信息纳入全国信用信息共享平台，按照有关规定,实现信息公开与共享。"},{"i":8,"n":"第八条","txt":"信用评级机构从事信用评级业务应当遵循独立、客观、公正和审慎性原则，勤勉尽责，诚信经营，不得损害国家利益、社会公共利益和市场主体合法权益。 信用评级机构从事评级业务，应当遵循一致性原则，对同一类对象评级，或者对同一评级对象跟踪评级，应当采用一致的评级标准和工作程序。评级标准和工作程序及其调整，应当予以充分披露。 信用评级机构依法独立开展业务，不受任何单位和个人的干涉。"},{"i":9,"n":"第九条","txt":"设立信用评级机构，应当符合《中华人民共和国公司法》规定的公司设立条件，自公司登记机关准予登记之日起30日内向所在地的信用评级行业主管部门省一级派出机构（以下简称备案机构）办理备案，并提交以下材料： （一）信用评级机构备案表； （二）营业执照复印件； （三）全球法人机构识别编码； （四）股权结构说明，包括注册资本、股东名单及其出资额或者所持股份，股东在本机构以外的实体持股情况，实际控制人、受益所有人情况； （五）董事、监事、高级管理人员以及信用评级分析人员的情况说明和证明文件； （六）主要股东、实际控制人、受益所有人、董事、监事、高级管理人员未因犯有贪污、贿赂、侵占财产、挪用财产罪或者破坏社会主义市场经济秩序罪，被判处刑罚，或者因犯罪被剥夺政治权利的声明，以及主要股东、实际控制人、受益所有人的信用报告； （七）营业场所、组织机构设置及公司治理情况; （八）独立性、信息披露以及业务制度说明"},{"i":10,"n":"第十条","txt":"信用评级机构设立分支机构的，自该分支机构成立之日起30日内，信用评级机构应当向原备案机构、信用评级机构分支机构应当向备案机构分别办理备案，并提交以下材料： （一）信用评级机构分支机构备案表； （二）信用评级机构分支机构营业执照复印件； （三）信用评级机构分支机构营业场所及组织机构设置说明； （四）信用评级机构分支机构高级管理人员和信用评级分析人员情况说明和证明文件。"},{"i":11,"n":"第十一条","txt":"信用评级机构应当自下列事项变更或者发生之日起30日内，向备案机构办理变更备案： （一）机构名称、营业场所； （二）持有出资额或者股份5%以上的股东，实际控制人、受益所有人; （三）董事、监事、高级管理人员、信用评级分析人员； （四）按照法律法规、行业主管部门和业务管理部门的规定开展相关市场信用评级业务； （五）不再从事信用评级业务。 信用评级机构分支机构前款第一项、第三项和第五项事项变更或者发生的，信用评级机构及其分支机构应当自相关事项变更或者发生之日起30日内向各自的备案机构办理变更备案。"},{"i":12,"n":"第十二条","txt":"信用评级机构解散或者被依法宣告破产的，应当向备案机构报告，并按照以下方式处理信用评级数据库系统： （一）与其他信用评级机构约定，转让给其他信用评级机构； （二）不能依照前项规定转让的，移交给备案机构指定的信用评级机构； （三）不能依照前两项规定转让、移交的，在备案机构的监督下销毁。"},{"i":13,"n":"第十三条","txt":"业务管理部门对有关信用评级业务资质另有规定的，从其规定。"},{"i":14,"n":"第十四条","txt":"信用评级机构应当将高级管理人员和信用评级分析人员的基本信息向备案机构办理备案。"},{"i":15,"n":"第十五条","txt":"信用评级机构的高级管理人员和信用评级分析人员离职并受聘于其曾参与评级的受评经济主体、受评债务融资工具发行人、信用评级委托方或者主承销商的，信用评级机构应当检查其离职前两年内参与的与其受聘机构有关的信用评级工作。对评级结果确有影响的，信用评级机构应当及时披露检查结果以及对原信用评级结果的调整情况。"},{"i":16,"n":"第十六条","txt":"信用评级机构应当定期对高级管理人员和信用评级分析人员进行业务培训和业务能力测试，采取有效措施提高从业人员的职业道德和业务水平，并做好培训和测试记录。"},{"i":17,"n":"第十七条","txt":"信用评级机构应当对内部管理制度的有效性进行年度检查和评估，就存在的问题提出处理措施，并于每个财务年度结束之日起四个月内将检查和评估报告向信用评级行业主管部门和业务管理部门报备。"},{"i":18,"n":"第十八条","txt":"信用评级机构应当建立完善的信用评级制度，对信用等级的划分与定义、评级方法与程序、评级质量控制、尽职调查、信用评级评审委员会、评级结果公布、跟踪评级等进行明确规定。"},{"i":19,"n":"第十九条","txt":"信用评级机构在开展委托评级项目前，应当与委托人签订评级协议，明确评级双方的权利和义务。"},{"i":20,"n":"第二十条","txt":"信用评级机构在开展信用评级业务时，应当组建评级项目组。 信用评级机构应当对每一评级项目投入充分的富有经验的分析资源。评级项目组成员应当具备从事相关项目的工作经历或者与评级项目相适应的知识结构，评级项目组长应当有充分的经验且至少从事信用评级业务三年以上。"},{"i":21,"n":"第二十一条","txt":"信用评级机构应当对评级对象开展尽职调查，进行必要的评估以确信评级所需信息来源可靠且充分满足使用需求，并在调查前制定详细的调查提纲。 调查过程中，信用评级机构应当制作尽职调查工作底稿，作为评级资料一并存档保管。"},{"i":22,"n":"第二十二条","txt":"评级项目组应当依法收集评级对象的相关资料，并对所依据的文件资料内容进行核查验证和客观分析，在此基础上得出初评结果。"},{"i":23,"n":"第二十三条","txt":"信用评级初评结果应当经过三级审核程序，包括评级小组初审、部门再审和公司三审。 各审核阶段应当相互独立，三级审核文件资料应当按相关要求存档保管。"},{"i":24,"n":"第二十四条","txt":"信用评级机构应当成立内部信用评审委员会。信用评级结果由内部信用评审委员会召开评审会议，以投票表决方式最终确定。信用评级机构应当根据每一评级项目的具体情况，安排充足且具有相关经验的人员参加评审会议。"},{"i":25,"n":"第二十五条","txt":"信用评级机构应当将信用评级结果反馈至评级委托方，评级委托方应当在规定期限内反馈意见。如评级委托方、受评经济主体、受评债务融资工具发行人不是同一主体的，信用评级机构还应当将信用评级结果反馈至受评经济主体和受评债务融资工具发行人。 评级委托方、受评经济主体或者受评债务融资工具发行人对信用评级结果有异议且向信用评级机构提供充分、有效的补充材料的，可以在约定时间内申请复评一次。"},{"i":26,"n":"第二十六条","txt":"信用评级机构公布受评债务融资工具及受评经济主体信用评级结果，应当符合下列要求： （一）评级结果应当包括评级等级和评级报告，评级报告应当采用简洁、明了的语言，对评级对象的信用等级和有效期等内容作出明确解释； （二）按照本办法第三十八条的规定公布评级结果； （三）存在多个评级结果的，多个评级结果均应当予以公布。 业务管理部门另有规定的，从其规定。"},{"i":27,"n":"第二十七条","txt":"在信用评级结果有效期内，信用评级机构应当对评级对象进行跟踪评级，并在签订评级协议时明确跟踪评级安排。其中，评级结果有效期为一年以上的，信用评级机构应当每年跟踪评级一次，并及时公布跟踪评级结果。 业务管理部门另有规定的，从其规定。"},{"i":28,"n":"第二十八条","txt":"在评级结果有效期内发生可能影响评级对象偿债能力和偿债意愿的重大事项的，信用评级机构应当及时进行不定期跟踪评级，并公布跟踪评级结果。"},{"i":29,"n":"第二十九条","txt":"信用评级机构应当建立评级业务档案管理制度。业务档案应当包括受托开展评级业务的委托书、出具评级报告所依据的原始资料、工作底稿、初评报告、评级报告、内部信用评审委员会表决意见及会议记录、跟踪评级资料、跟踪评级报告等。 业务档案应当保存至评级合同期满后五年、评级对象存续期满后五年或者评级对象违约后五年，且不得少于十年。"},{"i":30,"n":"第三十条","txt":"信用评级机构应当建立信用评级业务信息保密制度。对于在开展信用评级业务、处理信用评级数据库系统过程中知悉的国家秘密、商业秘密和个人隐私，信用评级机构及其从业人员应当依法履行保密义务。 信用评级机构在中国境内采集的信息的整理、保存和加工，应当在中国境内进行。信用评级机构向境外组织或者个人提供信息，应当遵守法律法规以及信用评级行业主管部门和业务管理部门的有关规定。"},{"i":31,"n":"第三十一条","txt":"发生下列情形之一的，信用评级机构可以终止或者撤销评级： （一）受评经济主体及债务融资工具发行人拒不提供评级所需关键材料或者提供的材料存在虚假记载、误导性陈述或者重大遗漏的； （二）受评经济主体解散或者被依法宣告破产的； （三）受评债务融资工具不再存续的； （四）评级工作不能正常开展的其他情形。 因上述原因终止或者撤销评级的，信用评级机构应当及时公告并说明原因。"},{"i":32,"n":"第三十二条","txt":"信用评级机构不得有下列行为： （一）篡改相关资料或者歪曲评级结果； （二）以承诺分享投资收益或者分担投资损失、承诺高等级、承诺低收费、诋毁同行等手段招揽业务； （三）以挂靠、外包等形式允许其他机构使用其名义开展信用评级业务； （四）与受评经济主体、受评债务融资工具发行人或者相关第三方存在不正当交易或者商业贿赂； （五）向受评经济主体、受评债务融资工具发行人或者相关第三方提供顾问或者咨询服务； （六）对受评经济主体、受评债务融资工具发行人或者相关第三方进行敲诈勒索； （七）违反信用评级业务规则，损害投资人、评级对象合法权益，损害信用评级业声誉的其他行为。"},{"i":33,"n":"第三十三条","txt":"信用评级机构、信用评级从业人员应当在对经济主体、债务融资工具本身风险进行充分分析的基础之上独立得出信用评级结果，防止评级结果受到其他商业行为的不当影响。"},{"i":34,"n":"第三十四条","txt":"信用评级机构与受评经济主体或者受评债务融资工具发行人存在下列情形之一的，不得开展信用评级业务： （一）信用评级机构与受评经济主体或者受评债务融资工具发行人为同一实际控制人所控制，或者由同一股东持股均达到5%以上； （二）受评经济主体、受评债务融资工具发行人或者其实际控制人直接或者间接持有信用评级机构出资额或者股份达到5%以上； （三）信用评级机构或者其实际控制人直接或者间接持有受评经济主体、受评债务融资工具发行人出资额或者股份达到5%以上； （四）信用评级机构或者其实际控制人在开展评级业务之前六个月内及开展评级业务期间买卖受评经济主体或者受评债务融资工具发行人发行的证券等产品； （五）影响信用评级机构独立性的其他情形。"},{"i":35,"n":"第三十五条","txt":"信用评级机构应当建立回避制度。信用评级从业人员在开展信用评级业务期间有下列情形之一的，应当回避： （一）本人、直系亲属持有受评经济主体或者受评债务融资工具发行人的出资额或者股份达到5%以上，或者是受评经济主体、受评债务融资工具发行人的实际控制人； （二）本人、直系亲属担任受评经济主体或者受评债务融资工具发行人的董事、监事或者高级管理人员； （三）本人、直系亲属担任受评经济主体或者受评债务融资工具发行人聘任的会计师事务所、律师事务所、财务顾问等服务机构的负责人或者项目签字人； （四）本人、直系亲属持有债务融资工具或者受评经济主体发行的证券金额超过50万元，或者与受评经济主体、受评债务融资工具发行人发生累计超过50万元的交易； （五）信用评级行业主管部门和业务管理部门认定的足以影响独立、客观、公正原则的其他情形。"},{"i":36,"n":"第三十六条","txt":"信用评级机构应建立完善的公司治理机制，确保其主要股东及实际控制人在出资比例、股权比例或投票权等方面不存在足以影响评级独立性的情形。 信用评级机构应当建立清晰合理的内部组织结构，建立健全防火墙，确保信用评级业务部门独立于营销等其他部门。 信用评级机构应当建立独立的合规部门，负责监督并报告评级机构及其员工的合规状况。"},{"i":37,"n":"第三十七条","txt":"信用评级从业人员的薪酬不得与评级对象的信用级别、债务融资工具发行状况等因素相关联。"},{"i":38,"n":"第三十八条","txt":"信用评级机构应当通过信用评级行业主管部门和业务管理部门指定的网站和其公司网站进行信息披露。"},{"i":39,"n":"第三十九条","txt":"信用评级机构应当披露下列基本信息： （一）机构基本情况、经营范围； （二）股东及其出资额或者所持股份、出资方式、出资比例、股东之间是否存在关联关系的说明，股权变更信息； （三）保证评级质量的内部控制制度； （四）评级报告采用的评级符号、评级方法、评级模型和关键假设，披露程度以反映评级可靠性为限，不得涉及商业秘密或妨碍创新。 以上内容发生变更的，应当披露变更原因和对已评级项目的影响。"},{"i":40,"n":"第四十条","txt":"信用评级机构应当在每个财务年度结束之日起四个月内披露下列独立性相关信息： （一）每年对其独立性的内部审核结果； （二）信用评级分析人员轮换政策； （三）财务年度评级收入前20名或者占比5%以上的客户名单； （四）信用评级机构的关联公司为受评经济主体、受评债务融资工具发行人或者相关第三方提供顾问、咨询服务的情况； （五）信用评级机构为受评经济主体、受评债务融资工具发行人或者相关第三方提供其他附加服务的情况。 信用评级机构在前款规定时间内将前款第三项信息向行业主管部门以及业务管理部门备案的，可以不披露该信息。"},{"i":41,"n":"第四十一条","txt":"信用评级机构应当披露下列评级质量相关信息： （一）一年、三年、五年期的信用评级违约率和信用等级迁移情况； （二）任何终止或撤销信用评级的决定及原因； （三）其他依法应当披露的信息。"},{"i":42,"n":"第四十二条","txt":"信用评级机构应当披露开展信用评级项目依据的主要信息来源。"},{"i":43,"n":"第四十三条","txt":"信用评级机构应当披露聘用第三方进行尽职调查的情况。"},{"i":44,"n":"第四十四条","txt":"信用评级机构开展结构化融资产品信用评级的，应当持续更新，并按照第三十九条第一款第四项的要求，及时披露结构化融资产品评级方法、评级模型和关键假设。"},{"i":45,"n":"第四十五条","txt":"信用评级行业主管部门、业务管理部门及其派出机构依照法律法规和本办法相关规定，履行对信用评级机构的监督管理职责，可以采取下列监督检查措施： （一）进入信用评级机构进行现场检查； （二）询问相关的单位和个人，要求其对有关事项作出说明； （三）查询、复制相关文件、资料，封存可能被转移、销毁、隐匿或者篡改的文件、资料； （四）检查信用评级数据库系统； （五）其他现场检查措施。"},{"i":46,"n":"第四十六条","txt":"现场检查内容包括下列事项： （一）备案信息与实际情况的一致性； （二）信用评级业务与评级模型、程序、方法的一致性； （三）内部管理情况； （四）独立性管理情况； （五）信息披露情况； （六）执行信用评级行业主管部门、业务管理部门信用评级管理规定情况； （七）信用评级行业主管部门、业务管理部门认为有必要检查的其他内容。"},{"i":47,"n":"第四十七条","txt":"现场检查程序按照信用评级行业主管部门、业务管理部门的规定执行。 相关信用评级机构和从业人员应当配合，如实提供有关文件、资料，不得隐瞒、拒绝和阻碍。"},{"i":48,"n":"第四十八条","txt":"信用评级机构按照相关规定向信用评级行业主管部门、业务管理部门及其派出机构报送信用评级结果、信用评级报告、统计报表、违约率数据、经审计的财务报表、财务年度信用评级工作报告等资料，并对报表和资料的真实性、准确性、完整性负责。"},{"i":49,"n":"第四十九条","txt":"信用评级行业主管部门、业务管理部门及其派出机构对信用评级机构报送内容进行监测、分析和统计。对发现的问题依据本办法相关规定及时处理。"},{"i":50,"n":"第五十条","txt":"信用评级行业主管部门组织建立违约率检验系统对信用评级结果进行事后检验，并建立违约率检验和通报机制。"},{"i":51,"n":"第五十一条","txt":"信用评级行业主管部门可以将现场与非现场检查情况形成行业监管报告并适时公布。"},{"i":52,"n":"第五十二条","txt":"信用评级行业主管部门、业务管理部门及其派出机构根据监管需要，可以约谈信用评级机构董事、监事和高级管理人员，要求其就相关重大事项作出说明。"},{"i":53,"n":"第五十三条","txt":"信用评级行业主管部门、业务管理部门及其派出机构的工作人员泄露知悉的国家秘密或者商业秘密，或者徇私舞弊、滥用职权、玩忽职守的，依法给予行政处分；涉嫌构成犯罪的，移送司法机关依法追究刑事责任。"},{"i":54,"n":"第五十四条","txt":"信用评级机构及其从业人员违反本办法的，依照本章的有关规定给予处罚。 法律法规和业务管理部门另有规定的，从其规定。"},{"i":55,"n":"第五十五条","txt":"信用评级机构开展业务，未按本办法规定办理备案的，由信用评级行业主管部门或者其省一级派出机构责令限期改正，并处未备案期间评级业务收入50%的罚款，没有评级业务收入或者评级业务收入无法计算的，处50万元以上200万元以下的罚款；逾期不改正的，处未备案期间评级业务收入1倍以上3倍以下的罚款，没有评级业务收入或者评级业务收入无法计算的，处200万元以上500万元以下的罚款。"},{"i":56,"n":"第五十六条","txt":"信用评级机构未按本办法规定办理信用评级从业人员备案的，由信用评级行业主管部门或者其省一级派出机构责令限期改正，对信用评级机构处该评级从业人员未备案期间参与的评级业务收入50%的罚款，没有评级业务收入或者评级业务收入无法计算的，处20万元以上50万元以下的罚款；逾期不改正的，对信用评级机构处该评级从业人员未备案期间参与的评级业务收入1倍以上3倍以下的罚款，没有评级业务收入或者评级业务收入无法计算的，处50万元以上200万元以下的罚款。"},{"i":57,"n":"第五十七条","txt":"信用评级机构隐瞒相关情况或者提交虚假备案材料的，信用评级行业主管部门省一级派出机构不予办理备案或者注销备案；已经开展信用评级业务的，处虚假备案期间评级业务收入50%的罚款，没有评级业务收入或者评级业务收入无法计算的，处50万元以上200万元以下的罚款；情节严重的，处虚假备案期间评级业务收入1倍以上3倍以下的罚款，没有评级业务收入或者评级业务收入无法计算的，处200万元以上500万元以下的罚款。"},{"i":58,"n":"第五十八条","txt":"信用评级机构违反本办法规定，有下列行为之一的，由信用评级行业主管部门、业务管理部门或者其派出机构给予警告，并处相关评级业务收入50%的罚款，没有评级业务收入或者评级业务收入无法计算的，处50万元以上200万元以下的罚款；情节严重或者拒不改正的，并处相关评级业务收入1倍以上3倍以下的罚款，没有评级业务收入或者评级业务收入无法计算的，处200万元以上500万元以下的罚款；对直接责任人员给予警告，并处3万元以上10万元以下的罚款： （一）未按照法定评级程序及业务规则开展信用评级业务的； （二）违反独立性要求的； （三）未按照规定披露信息或者披露虚假信息的。"},{"i":59,"n":"第五十九条","txt":"信用评级机构违反本办法规定，有下列行为之一的，由信用评级行业主管部门、业务管理部门或者其派出机构给予警告，并处3万元罚款；拒不改正的，自违规行为发生之日起每日处1万元的罚款： （一）拒绝、阻碍信用评级行业主管部门、业务管理部门或者其派出机构检查、监管，或者不如实提供文件、资料的； （二）未按规定向信用评级行业主管部门、业务管理部门或者其派出机构报送报告、资料的； （三）违反本办法其他规定的。"},{"i":60,"n":"第六十条","txt":"信用评级从业人员违反本办法规定，有下列行为之一的，由信用评级行业主管部门、业务管理部门或者其派出机构给予警告，并处违规收入50%的罚款，没有违规收入或者违规收入无法计算的，处50万元以上200万元以下的罚款；情节严重的，并处违规收入1倍以上3倍以下的罚款，没有违规收入或者违规收入无法计算的，处200万元以上500万元以下的罚款；涉嫌犯罪的，移送司法机关依法追究刑事责任： （一）从事与信用评级业务有利益冲突的兼职行为的； （二）以礼金、回扣等方式输送或者接受不正当利益的； （三）接受受评经济主体、受评债务融资工具发行人等相关主体的礼物或者现金馈赠，参与受评经济主体、受评债务融资工具发行人等相关主体组织的可能影响评级结果独立、客观、公正的活动的； （四）违反本办法第三十五条相关规定的； （五）离职并受聘于曾参与评级的受评经济主体、受评债务融资工具发行人、信用评级委托方或者主承销商，未通知信"},{"i":61,"n":"第六十一条","txt":"信用评级机构由于故意或者重大过失，对投资人、评级委托人或者评级对象利益造成严重损害的，由信用评级行业主管部门、业务管理部门或者其派出机构给予警告，并处相关评级业务收入1倍以上3倍以下的罚款，没有评级业务收入或者评级业务收入无法计算的，处200万元以上500万元以下的罚款；对直接责任人员给予警告，并处3万元以上10万元以下的罚款。"},{"i":62,"n":"第六十二条","txt":"信用评级行业主管部门、业务管理部门依据本办法相关规定，建立信用评价机制，定期对信用评级机构及信用评级从业人员的违法失信行为等开展信用评价，并将信用评价结果纳入信用评级机构信用档案。对信用评价较低的信用评级机构，可以采取向市场公开通报等惩戒措施。 信用评级行业主管部门会同业务管理部门健全守信联合激励和失信联合惩戒机制。建立信用评级机构及信用评级从业人员“失信联合惩戒对象名单”管理制度，根据失信严重程度采取不同惩戒措施;对失信较严重的信用评级机构及信用评级从业人员，纳入“失信联合惩戒对象名单”管理范畴，列为市场不信任信用评级机构及失信信用评级从业人员，发起多部门联合惩戒与约束，情节严重的依法依规实施暂停业务或市场禁入措施。"},{"i":63,"n":"第六十三条","txt":"信用评级机构违反本办法有关规定，受到行政处罚的，信用评级行业主管部门、业务管理部门依法通过“信用中国”网站等渠道向社会公布。"},{"i":64,"n":"第六十四条","txt":"信用评级机构自律组织依法开展行业自律管理，接受信用评级行业主管部门和业务管理部门的监督指导。"},{"i":65,"n":"第六十五条","txt":"本办法实施前已经开展信用评级业务的机构，应当自本办法实施之日起六个月内，依照本办法规定向备案机构办理备案。"},{"i":66,"n":"第六十六条","txt":"非信用评级机构为了自身业务开展的内部信用评级结果不得对外提供。"},{"i":67,"n":"第六十七条","txt":"主动评级是指信用评级机构未经委托，主要通过公开渠道收集评级对象相关资料，并以此为依据对相关经济主体或者债务融资工具开展的信用评级。 信用评级机构开展主动评级的，不适用本办法第十九条、第二十五条、第二十六条、第二十七条、第二十八条的规定。"},{"i":68,"n":"第六十八条","txt":"依照评级协议，评级结果不公开的，信用评级机构在开展相关业务时，不适用本办法第二十六条、第二十七条、第二十八条的规定。"},{"i":69,"n":"第六十九条","txt":"境外信用评级机构申请中华人民共和国境内有关信用评级业务资质的，依照信用评级行业主管部门和业务管理部门的相关规定执行。"},{"i":70,"n":"第七十条","txt":"本办法所称受益所有人，是指最终拥有或控制信用评级机构的自然人，包括直接或间接拥有超过25%公司股权或者表决权，或者以其他形式可以对公司的决策、经营、管理形成有效控制或者实际影响的自然人。"},{"i":71,"n":"第七十一条","txt":"本办法由信用评级行业主管部门会同业务管理部门解释。"},{"i":72,"n":"第七十二条","txt":"本办法自2019年12月26日起施行。"}],"quanguoyinhangjianzhaiquanshichangzhaiquanmaiduansf55cdd":[{"i":1,"n":"第一条","txt":"为促进债券市场进一步发展，规范债券买断式回购业务，防范市场风险，维护市场参与者合法权益，根据《中华人民共和国中国人民银行法》和《中华人民共和国合同法》等有关法律规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称债券买断式回购业务（以下简称买断式回购）是指债券持有人（正回购方）将债券卖给债券购买方（逆回购方）的同时，交易双方约定在未来某一日期，正回购方再以约定价格从逆回购方买回相等数量同种债券的交易行为。"},{"i":3,"n":"第三条","txt":"买断式回购的债券券种范围与用于现券买卖的相同。"},{"i":4,"n":"第四条","txt":"买断式回购遵循公平、诚信、自律、风险自担的原则。 市场参与者应建立、健全相应的内部管理制度和风险防范机制。 本规定所称市场参与者与中国人民银行发布的《全国银行间债券市场债券交易管理办法》中的市场参与者含义相同。"},{"i":5,"n":"第五条","txt":"市场参与者进行买断式回购应签订买断式回购主协议，该主协议须具有履约保证条款，以保证买断式回购合同的切实履行。"},{"i":6,"n":"第六条","txt":"市场参与者进行每笔买断式回购均应订立书面形式的合同，其书面形式包括全国银行间同业拆借中心（以下简称同业中心）交易系统生成的成交单，或者合同书、信件和数据电文等形式。 买断式回购主协议和上述书面形式的合同构成买断式回购的完整合同。交易双方认为必要时，可签订补充协议。"},{"i":7,"n":"第七条","txt":"买断式回购期间，交易双方不得换券、现金交割和提前赎回。"},{"i":8,"n":"第八条","txt":"进行买断式回购，交割时应有足额的债券和资金。"},{"i":9,"n":"第九条","txt":"买断式回购以净价交易，全价结算。"},{"i":10,"n":"第十条","txt":"买断式回购的首期交易净价、到期交易净价和回购债券数量由交易双方确定，但到期交易净价加债券在回购期间的新增应计利息应大于首期交易净价。"},{"i":11,"n":"第十一条","txt":"买断式回购的期限由交易双方确定，但最长不得超过91天。交易双方不得以任何方式延长回购期限。"},{"i":12,"n":"第十二条","txt":"买断式回购首期结算金额与回购债券面额的比例应符合中国人民银行的有关规定。"},{"i":13,"n":"第十三条","txt":"进行买断式回购，交易双方可以按照交易对手的信用状况协商设定保证金或保证券。设定保证券时，回购期间保证券应在交易双方中的提供方托管账户冻结。"},{"i":14,"n":"第十四条","txt":"进行买断式回购，任何一家市场参与者单只券种的待返售债券余额应小于该只债券流通量的20％，任何一家市场参与者待返售债券总余额应小于其在中央国债登记结算有限责任公司（以下简称中央结算公司）托管的自营债券总量的200%。"},{"i":15,"n":"第十五条","txt":"买断式回购发生违约，对违约事实或违约责任存在争议的，交易双方可以协议申请仲裁或者向人民法院提起诉讼，并将最终仲裁或诉讼结果报告同业中心和中央结算公司，同业中心和中央结算公司应在接到报告后5个工作日内将最终结果予以公告。"},{"i":16,"n":"第十六条","txt":"同业中心和中央结算公司应按照中国人民银行的规定和授权，及时向市场披露上一交易日单只券种买断式回购待返售债券总余额占该券种流通量的比例等有关买断式回购信息。"},{"i":17,"n":"第十七条","txt":"同业中心负责买断式回购交易的日常监测工作，中央结算公司负责买断式回购结算的日常监测工作；发现异常交易、结算情况应及时向中国人民银行报告。"},{"i":18,"n":"第十八条","txt":"同业中心和中央结算公司应依据本规定制定相应的买断式回购的交易、结算规则。"},{"i":19,"n":"第十九条","txt":"中国人民银行各分支机构对辖区内市场参与者的买断式回购进行日常监督。"},{"i":20,"n":"第二十条","txt":"进行买断式回购除应遵守本规定外，还应遵守全国银行间债券市场其他有关规定。"},{"i":21,"n":"第二十一条","txt":"市场参与者以及同业中心和中央结算公司违反本规定的，由中国人民银行按照《中华人民共和国中国人民银行法》第四十六条的规定予以处罚。 市场参与者进行买断式回购违反全国银行间债券市场其他有关规定的，由中国人民银行按照《中华人民共和国中国人民银行法》第四十六的规定予以处罚。"},{"i":22,"n":"第二十二条","txt":"本规定由中国人民银行负责解释。"},{"i":23,"n":"第二十三条","txt":"本规定自2004年5月20日起施行。"}],"quanguoyinhangjianzhaiquanshichangzhaiquanjiaoyigub3c744":[{"i":1,"n":"第一条","txt":"为规范全国银行间债券市场债券交易行为，防范交易风险，维护交易各方合法权益，促进全国银行间债券市场健康发展，根据国家有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所指全国银行间债券市场债券交易（以下称债券交易）是指以商业银行等金融机构为主的机构投资者之间以询价方式进行的债券交易行为。"},{"i":3,"n":"第三条","txt":"债券交易品种包括回购和现券买卖两种。 回购是交易双方进行的以债券为权利质押的一种短期资金融通业务，指资金融入方（正回购方）在将债券出质给资金融出方（逆回购方）融入资金的同时，双方约定在将来某一日期由正回购方按约定回购利率计算的资金额向逆回购方返还资金，逆回购方向正回购方返还原出质债券的融资行为。 现券买卖是指交易双方以约定的价格转让债券所有权的交易行为。"},{"i":4,"n":"第四条","txt":"本办法所称债券是指经中国人民银行批准可用于在全国银行间债券市场进行交易的政府债券、中央银行债券和金融债券等记帐式债券。"},{"i":5,"n":"第五条","txt":"债券交易应遵循公平、诚信、自律的原则。"},{"i":6,"n":"第六条","txt":"中央国债登记结算有限责任公司（简称中央结算公司）为中国人民银行指定的办理债券的登记、托管与结算机构。"},{"i":7,"n":"第七条","txt":"中国人民银行是全国银行间债券市场的主管部门。中国人民银行各分支机构对辖内金融机构的债券交易活动进行日常监督。"},{"i":8,"n":"第八条","txt":"下列机构可成为全国银行间债券市场参与者，从事债券交易业务： （一）在中国境内具有法人资格的商业银行及其授权分支机构； （二）在中国境内具有法人资格的非银行金融机构和非金融机构； （三）经中国人民银行批准经营人民币业务的外国银行分行。"},{"i":9,"n":"第九条","txt":"上述机构进入全国银行间债券市场，应签署债券回购主协议。"},{"i":10,"n":"第十条","txt":"金融机构可直接进行债券交易和结算，也可委托结算代理人进行债券交易和结算；非金融机构应委托结算代理人进行债券交易和结算。"},{"i":11,"n":"第十一条","txt":"结算代理人系指经中国人民银行批准代理其他参与者办理债券交易、结算等业务的金融机构。其有关规定由中国人民银行另行制定。"},{"i":12,"n":"第十二条","txt":"双边报价商系指经中国人民银行批准的，在进行债券交易时同时连续报出现券买、卖双边价格，承担维持市场流动性等有关义务的金融机构。双边报价商有关规定由中国人民银行另行制定。"},{"i":13,"n":"第十三条","txt":"全国银行间同业拆借中心（简称同业中心）为参与者的报价、交易提供中介及信息服务，中央结算公司为参与者提供托管、结算和信息服务。 经中国人民银行授权，同业中心和中央结算公司可披露市场有关信息。"},{"i":14,"n":"第十四条","txt":"债券交易的资金清算银行为参与者提供资金清算服务。"},{"i":15,"n":"第十五条","txt":"债券交易以询价方式进行，自主谈判，逐笔成交。"},{"i":16,"n":"第十六条","txt":"进行债券交易，应订立书面形式的合同。合同应对交易日期、交易方向、债券品种、债券数量、交易价格或利率、帐户与结算方式、交割金额和交割时间等要素作出明确的约定，其书面形式包括同业中心交易系统生成的成交单、电报、电传、传真、合同书和信件等。 债券回购主协议和上述书面形式的回购合同构成回购交易的完整合同。"},{"i":17,"n":"第十七条","txt":"以债券为质押进行回购交易，应办理登记；回购合同在办理质押登记后生效。"},{"i":18,"n":"第十八条","txt":"合同一经成立，交易双方应全面履行合同规定的义务，不得擅自变更或解除合同。"},{"i":19,"n":"第十九条","txt":"债券交易现券买卖价格或回购利率由交易双方自行确定。"},{"i":20,"n":"第二十条","txt":"参与者进行债券交易不得在合同约定的价款或利息之外收取未经批准的其他费用。"},{"i":21,"n":"第二十一条","txt":"回购期间，交易双方不得动用质押的债券。"},{"i":22,"n":"第二十二条","txt":"回购期限最长为365天。回购到期应按照合同约定全额返还回购项下的资金，并解除质押关系，不得以任何方式展期。"},{"i":23,"n":"第二十三条","txt":"参与者不得从事借券、租券等融券业务。"},{"i":24,"n":"第二十四条","txt":"金融机构应每季定期以书面形式向人民银行当地分支行报告其在全国银行间债券市场的活动情况。"},{"i":25,"n":"第二十五条","txt":"同业中心和中央结算公司应定期向中国人民银行报告债券交易、交割有关情况。"},{"i":26,"n":"第二十六条","txt":"参与者应在中央结算公司开立债券托管帐户，并将持有的债券托管于其帐户。"},{"i":27,"n":"第二十七条","txt":"债券托管帐户按功能实行分类管理，其管理规定另行制定。"},{"i":28,"n":"第二十八条","txt":"债券交易的债券结算通过中央结算公司的中央债券簿记系统进行。"},{"i":29,"n":"第二十九条","txt":"债券交易的资金结算以转帐方式进行。 商业银行应通过其准备金存款帐户和人民银行资金划拨清算系统进行债券交易的资金结算，商业银行与其他参与者、其他参与者之间债券交易的资金结算途径由双方自行商定。"},{"i":30,"n":"第三十条","txt":"债券交易结算方式包括券款对付、见款付券、见券付款和纯券过户四种。具体方式由交易双方协商选择。"},{"i":31,"n":"第三十一条","txt":"交易双方应按合同约定及时发送债券和资金的交割指令，在约定交割日有用于交割的足额债券和资金，不得买空或卖空。"},{"i":32,"n":"第三十二条","txt":"中央结算公司应按照交易双方发送的诸要素相匹配的指令按时办理债券交割。 资金清算银行应及时为参与者办理债券交易的资金划拨和转帐。"},{"i":33,"n":"第三十三条","txt":"中央结算公司应定期向中国人民银行报告债券托管、结算有关情况，及时为参与者提供债券托管、债券结算、本息兑付和帐务查询等服务；应建立严格的内部稽核制度，对债券帐务数据的真实性、准确性和完整性负责，并为帐户所有人保密。"},{"i":34,"n":"第三十四条","txt":"参与者有下列行为之一的，由中国人民银行给予警告，并可处三万元人民币以下的罚款，可暂停或取消其债券交易业务资格；对直接负责的主管人员和直接责任人员由其主管部门给予纪律处分；违反中国人民银行有关金融机构高级管理人员任职资格管理规定的，按其规定处理。 （一）擅自从事借券、租券等融券业务； （二）擅自交易未经批准上市债券； （三）制造并提供虚假资料和交易信息； （四）恶意操纵债券交易价格，或制造债券虚假价格； （五）不遵守有关规则或协议并造成严重后果； （六）违规操作对交易系统和债券簿记系统造成破坏； （七）其他违反本办法的行为。"},{"i":35,"n":"第三十五条","txt":"结算代理人和双边报价商违反规定的，按中国人民银行的有关规定处理。"},{"i":36,"n":"第三十六条","txt":"同业中心和中央结算公司有下列行为之一的，由中国人民银行给予警告，并可处三万元人民币以下的罚款；对直接负责的主管人员和直接责任人员由其主管部门给予纪律处分。 （一）工作失职，给参与者造成严重损失； （二）发布虚假信息或泄露非公开信息； （三）欺诈或误导参与者，并造成损失； （四）为参与者恶意操纵市场和融券等违规行为提供便利； （五）其他违反本办法的行为。"},{"i":37,"n":"第三十七条","txt":"债券交易的资金清算银行不及时为参与者划拨资金和转帐，给参与者造成损失的，应承担相应的民事责任。"},{"i":38,"n":"第三十八条","txt":"同业中心和中央结算公司应依据本办法制订相应的业务规则和实施细则，报中国人民银行批准或备案，并组织实施。"},{"i":39,"n":"第三十九条","txt":"本办法施行前制定的有关规定，与本办法相抵触的，以本办法为准。"},{"i":40,"n":"第四十条","txt":"本办法由中国人民银行负责解释。"},{"i":41,"n":"第四十一条","txt":"本办法自发布之日起施行。"}],"quanguoyinhangjianzhaiquanshichangjinrongzhaiquanf8c9969":[{"i":1,"n":"第一条","txt":"为规范全国银行间债券市场金融债券发行行为，维护投资者合法权益，根据《中华人民共和国中国人民银行法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称金融债券，是指依法在中华人民共和国境内设立的金融机构法人在全国银行间债券市场发行的、按约定还本付息的有价证券。 本办法所称金融机构法人，包括政策性银行、商业银行、企业集团财务公司及其他金融机构。"},{"i":3,"n":"第三条","txt":"中国人民银行依法对金融债券的发行进行监督管理。未经中国人民银行核准，任何金融机构不得擅自发行金融债券。"},{"i":4,"n":"第四条","txt":"金融债券的发行应遵循公平、公正、诚信、自律的原则，金融债券发行人（以下简称“发行人”）及相关中介机构应充分披露有关信息，并提示投资风险。"},{"i":5,"n":"第五条","txt":"金融债券的投资风险由投资者自行承担。"},{"i":6,"n":"第六条","txt":"政策性银行发行金融债券，应按年向中国人民银行报送金融债券发行申请，经中国人民银行核准后方可发行。政策性银行金融债券发行申请应包括发行数量、期限安排、发行方式等内容，如需调整，应及时报中国人民银行核准。 本办法所称政策性银行，是指国家开发银行、中国进出口银行、中国农业发展银行。"},{"i":7,"n":"第七条","txt":"商业银行发行金融债券应具备以下条件： （一）具有良好的公司治理机制； （二）核心资本充足率不低于4%； （三）最近三年连续盈利； （四）贷款损失准备计提充足； （五）风险监管指标符合监管机构的有关规定； （六）最近三年没有重大违法、违规行为； （七）中国人民银行要求的其他条件。 根据商业银行的申请，中国人民银行可以豁免前款所规定的个别条件。"},{"i":8,"n":"第八条","txt":"企业集团财务公司发行金融债券应具备以下条件： （一）具有良好的公司治理机制； （二）资本充足率不低于10%； （三）风险监管指标符合监管机构的有关规定； （四）最近三年没有重大违法、违规行为； （五）中国人民银行要求的其他条件。"},{"i":9,"n":"第九条","txt":"其它金融机构发行金融债券应具备的条件另行规定。"},{"i":10,"n":"第十条","txt":"金融机构（不包括政策性银行）发行金融债券应向中国人民银行报送下列文件（申请材料格式见附1）： （一）金融债券发行申请报告； （二）发行人公司章程或章程性文件规定的权力机构的书面同意文件； （三）监管机构同意金融债券发行的文件； （四）发行人近三年经审计的财务报告及审计报告； （五）募集说明书（格式要求见附2）； （六）发行公告或发行章程（格式要求见附3、4）； （七）承销协议； （八）发行人关于本期债券偿债计划及保障措施的专项报告； （九）信用评级机构出具的金融债券信用评级报告及有关持续跟踪评级安排的说明； （十）发行人律师出具的法律意见书； （十一）中国人民银行要求的其他文件。 采用担保方式发行金融债券的，还应提供担保协议及担保人资信情况说明。 如有必要，中国人民银行可商请其监管机构出具相关监管意见。"},{"i":11,"n":"第十一条","txt":"政策性银行发行金融债券应向中国人民银行报送下列文件： （一）金融债券发行申请报告； （二）发行人近三年经审计的财务报告及审计报告； （三）金融债券发行办法； （四）承销协议； （五）中国人民银行要求的其他文件。"},{"i":12,"n":"第十二条","txt":"中国人民银行核准金融债券发行申请的期限，适用《中国人民银行行政许可实施办法》的有关规定。"},{"i":13,"n":"第十三条","txt":"金融债券可在全国银行间债券市场公开发行或定向发行。"},{"i":14,"n":"第十四条","txt":"金融债券的发行可以采取一次足额发行或限额内分期发行的方式。发行人分期发行金融债券的，应在募集说明书中说明每期发行安排。发行人（不包括政策性银行）应在每期金融债券发行前5个工作日将第十条（五）、（六）、（八）、（九）项要求文件报中国人民银行备案，并按中国人民银行的要求披露有关信息。 政策性银行应在每期金融债券发行前5个工作日将第十一条（二）、（三）、（四）项要求文件报中国人民银行备案，并按中国人民银行的要求披露有关信息。"},{"i":15,"n":"第十五条","txt":"金融债券的发行应由具有债券评级能力的信用评级机构进行信用评级。金融债券发行后信用评级机构应每年对该金融债券进行跟踪信用评级。如发生影响该金融债券信用评级的重大事项，信用评级机构应及时调整该金融债券的信用评级，并向投资者公布。"},{"i":16,"n":"第十六条","txt":"发行金融债券时，发行人应组建承销团，承销人可在发行期内向其他投资者分销其所承销的金融债券。 发行人和承销人应在承销协议中明确双方的权利与义务并加以披露。"},{"i":17,"n":"第十七条","txt":"发行金融债券的承销可采用协议承销、招标承销等方式。承销人应为金融机构，并须具备下列条件： （一）注册资本不低于2亿元人民币； （二）具有较强的债券分销能力； （三）具有合格的从事债券市场业务的专业人员和债券分销渠道； （四）最近两年内没有重大违法、违规行为； （五）中国人民银行要求的其他条件。"},{"i":18,"n":"第十八条","txt":"以招标承销方式发行金融债券，发行人应向承销人发布下列信息： （一）招标前，至少提前3个工作日向承销人公布招标具体时间、招标方式、招标标的、中标确定方式和应急招投标方案等内容； （二）招标开始时，向承销人发出招标书； （三）招标结束后，发行人应立即向承销人公布中标结果，并不迟于次一工作日发布金融债券招标结果公告。承销人中标后应履行相应的认购义务。"},{"i":19,"n":"第十九条","txt":"金融债券的招投标发行通过中国人民银行债券发行系统进行。 在招标过程中发行人及相关各方不得透露投标情况，不得干预投标过程。中国人民银行对招标过程进行现场监督。"},{"i":20,"n":"第二十条","txt":"发行人不得认购或变相认购自己发行的金融债券。"},{"i":21,"n":"第二十一条","txt":"发行人应在中国人民银行核准金融债券发行之日起60个工作日内开始发行金融债券，并在规定期限内完成发行。 发行人未能在规定期限内完成发行的，原金融债券发行核准文件自动失效。发行人不得继续发行本期金融债券。发行人仍需发行金融债券的，应依据本办法另行申请。"},{"i":22,"n":"第二十二条","txt":"金融债券发行结束后10个工作日内，发行人应向中国人民银行书面报告金融债券发行情况。"},{"i":23,"n":"第二十三条","txt":"金融债券定向发行的，经认购人同意，可免于信用评级。定向发行的金融债券只能在认购人之间进行转让。"},{"i":24,"n":"第二十四条","txt":"金融债券的交易按照全国银行间债券市场债券交易的有关规定执行。"},{"i":25,"n":"第二十五条","txt":"中央国债登记结算有限责任公司（以下简称“中央结算公司”）为金融债券的登记、托管机构。"},{"i":26,"n":"第二十六条","txt":"金融债券发行结束后，发行人应及时向中央结算公司确认债权债务关系，由中央结算公司及时办理债券登记工作。"},{"i":27,"n":"第二十七条","txt":"金融债券付息或兑付日前（含当日），发行人应将相应资金划入债券持有人指定资金账户。"},{"i":28,"n":"第二十八条","txt":"发行人应在金融债券发行前和存续期间履行信息披露义务。信息披露应通过中国货币网、中国债券信息网进行。"},{"i":29,"n":"第二十九条","txt":"发行人应保证信息披露真实、准确、完整、及时，不得有虚假记载、误导性陈述和重大遗漏。 发行人及相关知情人在信息披露前不得泄漏其内容。"},{"i":30,"n":"第三十条","txt":"对影响发行人履行债务的重大事件，发行人应在第一时间向中国人民银行报告，并按照中国人民银行指定的方式披露。"},{"i":31,"n":"第三十一条","txt":"经中国人民银行核准发行金融债券的，发行人应于每期金融债券发行前3个工作日披露募集说明书和发行公告。 发行人应在募集说明书与发行公告中说明金融债券的清偿顺序和投资风险，并在显著位置提示投资者：“投资者购买本期债券，应当认真阅读本文件及有关的信息披露文件，进行独立的投资判断。主管部门对本期债券发行的核准，并不表明对本期债券的投资价值做出了任何评价，也不表明对本期债券的投资风险做出了任何判断”。"},{"i":32,"n":"第三十二条","txt":"金融债券存续期间，发行人应于每年4月30日前向投资者披露年度报告，年度报告应包括发行人上一年度的经营情况说明、经注册会计师审计的财务报告以及涉及的重大诉讼事项等内容。 采用担保方式发行金融债券的，发行人还应在其年度报告中披露担保人上一年度的经营情况说明、经审计的财务报告以及涉及的重大诉讼事项等内容。"},{"i":33,"n":"第三十三条","txt":"发行人应于金融债券每次付息日前2个工作日公布付息公告，最后一次付息暨兑付日前5个工作日公布兑付公告。"},{"i":34,"n":"第三十四条","txt":"金融债券存续期间，发行人应于每年7月31日前披露债券跟踪信用评级报告。"},{"i":35,"n":"第三十五条","txt":"信息披露涉及的财务报告，应经注册会计师审计，并出具审计报告；信息披露涉及的法律意见书和信用评级报告，应分别由执业律师和具有债券评级能力的信用评级机构出具。上述注册会计师、律师和信用评级机构所出具的有关报告文件不得含有虚假记载、误导性陈述或重大遗漏。"},{"i":36,"n":"第三十六条","txt":"发行人应将相关信息披露文件分别送全国银行间同业拆借中心（以下简称“同业拆借中心”）和中央结算公司，由同业拆借中心和中央结算公司分别通过中国货币网和中国债券信息网披露。 同业拆借中心和中央结算公司应为金融债券信息披露提供服务，及时将违反信息披露规定的行为向中国人民银行报告并公告。"},{"i":37,"n":"第三十七条","txt":"金融债券定向发行的，其信息披露的内容与形式应在发行章程与募集说明书中约定；信息披露的对象限于其认购人。"},{"i":38,"n":"第三十八条","txt":"发行人有下列行为之一的，由中国人民银行按照《中华人民共和国中国人民银行法》第四十六条的规定予以处罚。 （一）未经中国人民银行核准擅自发行金融债券； （二）超规模发行金融债券； （三）以不正当手段操纵市场价格、误导投资者； （四）未按规定报送文件或披露信息； （五）其他违反本办法的行为。"},{"i":39,"n":"第三十九条","txt":"承销人有下列行为之一的，由中国人民银行按照《中华人民共和国中国人民银行法》第四十六条的规定予以处罚。 （一）以不正当竞争手段招揽承销业务； （二）发布虚假信息或泄露非公开信息； （三）其他违反本办法的行为。"},{"i":40,"n":"第四十条","txt":"托管机构有下列行为之一的，由中国人民银行按照《中华人民共和国中国人民银行法》第四十六条的规定予以处罚。 （一）挪用托管客户金融债券； （二）债券登记错误或遗失； （三）发布虚假信息或泄露非公开信息； （四）其他违反本办法的行为。"},{"i":41,"n":"第四十一条","txt":"注册会计师、律师、信用评级机构等相关机构和人员所出具的文件含有虚假记载、误导性陈述或重大遗漏的，由中国人民银行按照《中华人民共和国中国人民银行法》第四十六条的规定予以处罚。其行为给他人造成损失的，应当就其负有责任的部分依法承担民事责任。"},{"i":42,"n":"第四十二条","txt":"在全国银行间债券市场发行商业银行次级债券和资产支持证券适用本办法，另有规定的，依照其规定。"},{"i":43,"n":"第四十三条","txt":"本办法由中国人民银行负责解释。"},{"i":44,"n":"第四十四条","txt":"本办法自2005年6月1日起施行。中国人民银行1998年11月28日发布的《政策性银行金融债券市场发行管理暂行规定》同时废止。 附件： 1.金融债券发行报送申请材料的格式 2.金融债券募集说明书编制要求 3.金融债券发行公告编制要求 4.金融债券发行章程的编制要求 附件1：金融债券发行报送申请材料的格式 一、总体要求 （一）申请材料是发行人为发行金融债券向中国人民银行报送的必备文件。本办法规定的目录是金融债券发行申请材料的最低要求，发行人可视实际情况增加。 （二）发行人及负责出具专业意见的注册会计师、律师、信用评级机构等相关机构和人员应审慎对待所申报的材料和所出具的意见。发行人全体董事或其授权的代理人及有关中介机构应按要求在所提供的有关文件上发表声明或签字，对申请文件的真实性、准确性和完整性做出承诺。 二、发行申请材料的格式标准 （一）申请材料应采用标准A4纸张规格。 （二）申请材料的"}],"quanqiuxitongzhongyaoxingyinhangzongsunshixishounee2056a":[{"i":1,"n":"第一条","txt":"为确保全球系统重要性银行进入处置阶段时具备充足的损失吸收和资本重组能力，维持关键业务和服务功能的连续性，防范化解系统性金融风险，维护金融稳定，根据《中华人民共和国中国人民银行法》《中华人民共和国银行业监督管理法》《中华人民共和国商业银行法》《存款保险条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内设立的、被金融稳定理事会认定为全球系统重要性银行的商业银行。"},{"i":3,"n":"第三条","txt":"本办法所称总损失吸收能力，是指全球系统重要性银行进入处置阶段时，可以通过减记或转为普通股等方式吸收损失的资本和债务工具的总和。外部总损失吸收能力是指全球系统重要性银行的处置实体应当持有的损失吸收能力，内部总损失吸收能力是指全球系统重要性银行的处置实体向其重要附属公司承诺和分配的损失吸收能力。 处置实体是指根据全球系统重要性银行的处置计划，作为处置工具实施对象的法人实体。处置实体及其附属公司构成处置集团。附属公司是指符合银保监会资本监管规定的由处置实体直接或间接投资的金融机构。"},{"i":4,"n":"第四条","txt":"全球系统重要性银行应当按照本办法规定计算外部总损失吸收能力比率。"},{"i":5,"n":"第五条","txt":"全球系统重要性银行应当同时符合本办法规定的外部总损失吸收能力监管要求和相关资本监管要求。"},{"i":6,"n":"第六条","txt":"全球系统重要性银行应当按照本办法规定披露外部总损失吸收能力的相关信息。"},{"i":7,"n":"第七条","txt":"人民银行、银保监会和财政部依法对全球系统重要性银行总损失吸收能力状况进行监督检查，并按照法律法规规定和职责分工对总损失吸收能力非资本债务工具的发行进行管理。"},{"i":8,"n":"第八条","txt":"外部总损失吸收能力比率要求适用于并表的全球系统重要性银行处置集团。"},{"i":9,"n":"第九条","txt":"外部总损失吸收能力比率包括外部总损失吸收能力风险加权比率和外部总损失吸收能力杠杆比率。"},{"i":10,"n":"第十条","txt":"全球系统重要性银行应当按照以下公式计算外部总损失吸收能力比率： 外部总损失吸收能力风险加权比率=（外部总损失吸收能力-扣除项）÷风险加权资产×100% 外部总损失吸收能力杠杆比率=（外部总损失吸收能力-扣除项）÷调整后的表内外资产余额×100%"},{"i":11,"n":"第十一条","txt":"全球系统重要性银行应当按照本办法第三章和第四章规定计算本办法第十条规定的外部总损失吸收能力及扣除项。"},{"i":12,"n":"第十二条","txt":"全球系统重要性银行应当分别按照银保监会资本监管规定和杠杆率监管规定计算本办法第十条规定的风险加权资产和调整后的表内外资产余额。"},{"i":13,"n":"第十三条","txt":"全球系统重要性银行应当同时满足外部总损失吸收能力比率要求和缓冲资本（储备资本、逆周期资本和系统重要性银行附加资本）监管要求。计算外部总损失吸收能力风险加权比率时，为满足缓冲资本要求计提的核心一级资本工具不能计入外部总损失吸收能力。"},{"i":14,"n":"第十四条","txt":"全球系统重要性银行外部总损失吸收能力比率应当满足以下要求： （一）外部总损失吸收能力风险加权比率自2025年1月1日起不得低于16%，自2028年1月1日起不得低于18%。 （二）外部总损失吸收能力杠杆比率自2025年1月1日起不得低于6%，自2028年1月1日起不得低于6.75%。"},{"i":15,"n":"第十五条","txt":"除本办法第十四条规定的外部总损失吸收能力比率要求以外，在确有必要的情形下，人民银行、银保监会有权针对单家银行提出更审慎的要求，确保其具备充足的损失吸收能力。"},{"i":16,"n":"第十六条","txt":"下列负债不可计入外部总损失吸收能力（以下统称除外负债）： （一）受保存款。 （二）活期存款和原始期限一年以内的短期存款。 （三）衍生品负债。 （四）具有衍生品性质的债务工具，如结构性票据等。 （五）非合同产生的负债，如应付税金等。 （六）根据《中华人民共和国企业破产法》等相关法律法规规定，优先于普通债权受偿的负债。 （七）根据法律法规规定，难以核销、减记或转为普通股的负债。"},{"i":17,"n":"第十七条","txt":"符合银保监会资本监管规定的监管资本，在满足剩余期限一年以上（或无到期日）的情况下，可全额计入外部总损失吸收能力。"},{"i":18,"n":"第十八条","txt":"满足下列合格标准的全球系统重要性银行外部总损失吸收能力非资本债务工具可全额计入外部总损失吸收能力： （一）实缴。 （二）无担保。 （三）不适用破产抵销或净额结算等影响损失吸收能力的机制安排。 （四）剩余期限一年以上（或无到期日）。 （五）工具到期前，投资者无权要求提前赎回。 （六）由全球系统重要性银行处置实体直接发行。 （七）工具到期前，如果发行银行赎回将导致其不满足外部总损失吸收能力要求，则未经人民银行批准，发行银行不得赎回该工具。 （八）发行银行及受其控制或有重要影响的关联方不得购买该工具，且发行银行不得直接或间接为其他主体购买该工具提供融资。 （九）外部总损失吸收能力非资本债务工具应当符合以下任意一项要求，以确保其受偿顺序排在本办法第十六条所列的除外负债之后: 1.外部总损失吸收能力非资本债务工具的发行合同中明确其受偿顺序排在处置实体资产负债表的除外负债之后。 2.相关法律法规规"},{"i":19,"n":"第十九条","txt":"由存款保险基金管理机构管理的存款保险基金，可以计入全球系统重要性银行的外部总损失吸收能力。当外部总损失吸收能力风险加权比率最低要求为16%时，存款保险基金可计入的规模上限为银行风险加权资产的2.5%；当外部总损失吸收能力风险加权比率最低要求为18%时，存款保险基金可计入的规模上限为银行风险加权资产的3.5%。"},{"i":20,"n":"第二十条","txt":"全球系统重要性银行可计入外部总损失吸收能力的资本工具的扣除适用银保监会资本监管的扣除规定。"},{"i":21,"n":"第二十一条","txt":"全球系统重要性银行直接或间接持有本银行发行的外部总损失吸收能力非资本债务工具，或人民银行认定为虚增外部总损失吸收能力非资本债务工具的投资，应从自身外部总损失吸收能力中扣除。"},{"i":22,"n":"第二十二条","txt":"全球系统重要性银行之间通过协议相互持有的外部总损失吸收能力非资本债务工具，应从各自二级资本中全额扣除。二级资本小于扣除数额的，缺口部分应依次从更高一级的资本中扣除。"},{"i":23,"n":"第二十三条","txt":"全球系统重要性银行持有其他全球系统重要性银行外部总损失吸收能力非资本债务工具，应当区分小额投资和大额投资两种情形进行扣除： （一）小额投资，指全球系统重要性银行对其他全球系统重要性银行的各级资本和外部总损失吸收能力非资本债务工具投资（包括直接投资和间接投资）之和占该被投资银行普通股（含溢价）10%（不含）以下的投资。 1.小额投资中满足以下条件的投资无需从资本中扣除：在交易账簿中持有，持有期限不超过30个交易日，且持有规模在自身核心一级资本净额的5%（不含）以下。 2.小额投资扣除上述第1目中的部分后，仍超出自身核心一级资本净额10%的部分应从各级监管资本中对应扣除。其中，外部总损失吸收能力非资本债务工具投资从二级资本中对应扣除。全球系统重要性银行某级资本小于应扣除数额的，缺口部分应依次从更高一级的资本中扣除。 3.不进行资本扣除的投资，应当按照银保监会资本监管的相关规定计算风险加权资"},{"i":24,"n":"第二十四条","txt":"全球系统重要性银行以外的其他商业银行对全球系统重要性银行外部总损失吸收能力非资本债务工具的投资，应当按照银保监会资本监管相关规定计算风险加权资产。划入交易账簿的，按市场风险加权资产计量规则计量；划入银行账簿的，按信用风险加权资产计量规则计量，其中按权重法计量的，投资外部总损失吸收能力非资本债务工具的风险权重比照投资二级资本债的风险权重计量。银保监会另有规定的，从其规定。"},{"i":25,"n":"第二十五条","txt":"人民银行、银保监会和财政部依法对全球系统重要性银行实施本办法的情况进行监督检查，确保全球系统重要性银行具备充足的损失吸收能力，能够在处置阶段维持关键业务和服务功能的连续性，不引发系统性金融风险。"},{"i":26,"n":"第二十六条","txt":"人民银行、银保监会和财政部通过非现场监管和现场检查的方式对全球系统重要性银行进行监督检查，包括但不限于以下内容： （一）评估全球系统重要性银行外部总损失吸收能力管理框架，包括公司治理、内部控制、总损失吸收能力规划等。 （二）审查全球系统重要性银行对外部总损失吸收能力工具的认定，以及外部总损失吸收能力比率的计量方法，评估计量结果的合理性和准确性。 （三）定期组织召开全球系统重要性银行跨境危机管理工作组会议，审查全球系统重要性银行的恢复处置计划，对全球系统重要性银行开展可处置性评估，评估外部总损失吸收能力工具的可执行性。"},{"i":27,"n":"第二十七条","txt":"全球系统重要性银行应当按季度向人民银行、银保监会和财政部报告外部总损失吸收能力比率，如遇影响外部总损失吸收能力比率的重大事项，应当及时向人民银行、银保监会和财政部报告。"},{"i":28,"n":"第二十八条","txt":"全球系统重要性银行应在年度结束后4个月内向人民银行、银保监会和财政部提交上一年度对外部总损失吸收能力监管要求的执行情况。"},{"i":29,"n":"第二十九条","txt":"全球系统重要性银行应当通过公开渠道，向投资者和公众披露相关信息，确保信息披露的集中性、公开性和可访问性，并保证披露信息的真实性、准确性和完整性。"},{"i":30,"n":"第三十条","txt":"全球系统重要性银行应当分别按照以下要求披露相关内容： （一）外部总损失吸收能力比率应按季度披露。 （二）外部总损失吸收能力规模、构成、期限等信息应每半年披露一次。 （三）人民银行和银保监会规定的其他披露事项按照要求定期披露。"},{"i":31,"n":"第三十一条","txt":"本办法第三十条规定的披露内容是外部总损失吸收能力信息披露的最低要求，全球系统重要性银行应当遵循充分披露的原则，并根据人民银行和银保监会的要求及时调整披露事项。"},{"i":32,"n":"第三十二条","txt":"全球系统重要性银行外部总损失吸收能力信息披露频率分为临时、季度、半年度及年度披露。其中，临时信息应及时披露，季度、半年度信息披露时间为每期期末后30个工作日内，年度信息披露时间为会计年度终了后4个月内。因特殊原因不能按时披露的，应至少提前15个工作日向人民银行、银保监会申请延迟披露。"},{"i":33,"n":"第三十三条","txt":"全球系统重要性银行应当自2025年1月1日起按照本办法和银保监会有关规定披露外部总损失吸收能力相关信息。"},{"i":34,"n":"第三十四条","txt":"本办法第二十一条、第二十二条和第二十四条规定自2025年1月1日起实施。第二十三条规定自2030年1月1日起实施，2025年1月1日至2029年12月31日，全球系统重要性银行对其他全球系统重要性银行外部总损失吸收能力非资本债务工具的投资，不进行资本扣除，应当按照本办法第二十四条规定计算风险加权资产。"},{"i":35,"n":"第三十五条","txt":"2022年1月1日之前被认定为全球系统重要性银行的商业银行，应当在本办法规定期限内满足外部总损失吸收能力要求。2022年1月1日之后被认定为全球系统重要性银行的商业银行，应当自被认定之日起三年内满足本办法规定的外部总损失吸收能力要求。"},{"i":36,"n":"第三十六条","txt":"在中华人民共和国境外设立，被金融稳定理事会认定为全球系统重要性银行的商业银行，其在中华人民共和国境内的附属公司若被认定为处置实体，对该附属公司的管理参照本办法执行。"},{"i":37,"n":"第三十七条","txt":"进入处置阶段的全球系统重要性银行，若仍被金融稳定理事会认定为全球系统重要性银行，应自处置结束之日起两年内重新满足本办法规定的外部总损失吸收能力要求。"},{"i":38,"n":"第三十八条","txt":"若全球系统重要性银行在采取恢复措施时，与债权人达成协议将债权转为股权，从而在不进入处置阶段的情况下完成资本重组，但仍被金融稳定理事会认定为全球系统重要性银行，应自与债权人签订协议之日起两年内重新满足本办法规定的外部总损失吸收能力要求。"},{"i":39,"n":"第三十九条","txt":"全球系统重要性银行内部总损失吸收能力要求和重要附属公司的认定标准另行规定。"},{"i":40,"n":"第四十条","txt":"本办法由人民银行、银保监会和财政部负责解释。"},{"i":41,"n":"第四十一条","txt":"本办法自2021年12月1日起施行。"}],"guanyuzhixingchuxuguanlitiaolideruoganguiding":[{"i":1,"n":"第一条","txt":"储蓄存款是指个人所有的存入在中国境内储蓄机构的人民币或外币存款。任何单位不许将公款转为个人储蓄存款。公款的范围包括：凡列在国家机关、企业及事业单位会计科目的任何款项；各保险机构、企事业单位吸收的保险金存款；属于财政性存款范围的款项；国家机关和企事业单位的库存现金等。"},{"i":2,"n":"第二条","txt":"储蓄机构是指经中国人民银行及其分支机构批准的各银行以及城市信用社、农村信用社和邮政企业依法办理个人储蓄存款业务的机构。"},{"i":3,"n":"第三条","txt":"国家宪法保护个人合法储蓄存款的所有权不受侵犯。储蓄机构办理储蓄业务必须遵循“存款自愿、取款自由、存款有息、为储户保密”的原则。"},{"i":4,"n":"第四条","txt":"中国人民银行是我国储蓄事业的主管机关，负责全国储蓄管理工作。中国人民银行根据宏观经济、金融及保护储户利益的需要，在报经国务院批准后，可以采取一些必要的措施，以稳定储蓄，稳定金融。"},{"i":5,"n":"第五条","txt":"未经中国人民银行批准，任何部门和单位以及居民个人不得经办个人储蓄业务和类似储蓄的业务。"},{"i":6,"n":"第六条","txt":"储蓄机构的设置，要遵循统一规划、合理布局、方便群众、讲求实效、确保安全的原则。储蓄机构的各业务主管部门，须向当地人民银行上报下一年度增设储蓄机构计划，由当地人民银行审核后汇总上报，于年底前上报人民银行总行审批。各地人民银行根据批准的计划逐一办理储蓄网点审批手续，统一发给《经营金融业务许可证》。但国家法律、行政法规另有规定的除外。"},{"i":7,"n":"第七条","txt":"储蓄机构的设置必须同时具备三个条件：第一，有机构名称、组织机构和营业场所；第二，熟悉储蓄业务的工作人员不少于四人，保证营业时间内双人临柜；第三，有必要的安全防范设备。"},{"i":8,"n":"第八条","txt":"直接办理储蓄存款业务的所有储蓄网点，是各银行和其他金融机构、邮政企业具体办理储蓄业务的基层单位，不具有法人资格。"},{"i":9,"n":"第九条","txt":"储蓄代办网点是银行委托企业、机关、学校、军队等单位办理储蓄业务的代理机构，代办业务的开办、管理等必须严格按本《规定》的有关规定执行。"},{"i":10,"n":"第十条","txt":"储蓄机构的更名、迁址、撤并，应事先报当地人民银行，按规定程序批准后，方可正式对外公布。"},{"i":11,"n":"第十一条","txt":"储蓄机构的业务主管部门，对其所属的储蓄机构及其储蓄业务，负有直接的领导和管理责任；要认真贯彻国家的储蓄政策，对其所属储蓄机构做好监督和检查工作。"},{"i":12,"n":"第十二条","txt":"储蓄机构应当按照规定时间营业，不得擅自停业或者缩短营业时间。"},{"i":13,"n":"第十三条","txt":"各储蓄机构必须保证储蓄存款的支取，不得以任何理由拒绝储蓄存款的提取。"},{"i":14,"n":"第十四条","txt":"储蓄机构以发展我国的储蓄事业，为储户提供优质服务为宗旨。下列做法属于“使用不正当手段吸收存款”： （一）以散发有价馈赠品为条件吸收储蓄存款； （二）发放各种名目的揽储费； （三）利用不确切的广告宣传； （四）利用汇款、贷款或其它业务手段强迫储户存款； （五）利用各种名目多付利息、奖品或其它费用。"},{"i":15,"n":"第十五条","txt":"下列储蓄种类，储蓄机构可根据条件开办全部或部分储蓄种类： （一）活期储蓄存款。一元起存，由储蓄机构发给存折，凭折存取，开户后可以随时存取。 （二）整存整取定期储蓄存款。一般五十元起存，存期分三个月、半年、一年、二年、三年和五年，本金一次存入，由储蓄机构发给存单，到期凭存单支取本息。 （三）零存整取定期储蓄存款。每月固定存额，一般五元起存，存期分一年、三年、五年，存款金额由储户自定，每月存入一次，中途如有漏存，应在次月补存，未补存者，到期支取时按实存金额和实际存期计算利息。 （四）存本取息定期储蓄存款。本金一次存入，一般五千元起存。存期分一年、三年、五年，由储蓄机构发给存款凭证，到期一次支取本金，利息凭存单分期支取，可以一个月或几个月取息一次，由储户与储蓄机构协商确定。如到取息日未取息，以后可随时取息。如果储户需要提前支取本金，则要按定期存款提前支取的规定计算存期内利息，并扣回多支付的利"},{"i":16,"n":"第十六条","txt":"储蓄机构办理上述第十七条范围以外的储蓄种类，必须报经中国人民银行总行批准。储蓄机构未经审批擅自开办新的储蓄种类档次，由中国人民银行及其分支机构负责查处，并将这部分存款转存当地人民银行。存款自转存人民银行到期满止，这部分利息仍由储蓄机构支付。"},{"i":17,"n":"第十七条","txt":"经省级外汇管理部门批准，储蓄机构可办理外币储蓄业务，个人外币储蓄存款的种类、利率、档次及其利息支付办法，按中国人民银行总行的统一规定执行；办理其他外币储蓄业务需经中国人民银行总行审批。"},{"i":18,"n":"第十八条","txt":"储蓄机构在为储户开立定期存款帐户时，可根据储户意愿，办理定期存款到期约定或自动转存业务。约定转存、自动转存的具体办法由经营储蓄的主管部门自行制定、公布。"},{"i":19,"n":"第十九条","txt":"经中国人民银行省级分行批准，储蓄机构可以办理个人住房储蓄业务。住房储蓄的利率要执行中国人民银行总行的规定。住房储蓄存款的运用必须与商品房的建设和商品房的销售直接挂钩，不得用到其它地方。"},{"i":20,"n":"第二十条","txt":"储蓄机构经中国人民银行或其分支机构批准，可以办理以下金融业务： （一）发售和兑付以居民个人为对象的国库券、金融债券、企业债券等有价证券； （二）开办个人定期储蓄存单小额抵押贷款业务，须由储蓄机构业务主管部门拟订具体办法，并向省级人民银行申报，经批准后方可办理。 （三）经批准的其他金融业务。 储蓄机构经申报、批准后办理的不属于储蓄业务的其它金融业务，必须遵循国家的有关规定。"},{"i":21,"n":"第二十一条","txt":"储蓄机构可以办理代发工资、代收房租、水电费、电话费等服务性业务，代理服务性业务由各储蓄机构主管部门与被代理业务部门自行商定。"},{"i":22,"n":"第二十二条","txt":"储蓄存款利率由中国人民银行统一拟定，报经国务院批准后公布或由国务院授权中国人民银行制定、公布，各储蓄机构必须挂牌公告，并严格执行国家规定的统一利率标准，不得以任何形式自行变动。"},{"i":23,"n":"第二十三条","txt":"《条例》实施前存入的各种定期储蓄存款，在原定存期内如遇利率上调，仍实行分段计息的办法。"},{"i":24,"n":"第二十四条","txt":"《条例》实施前存入的各种定期储蓄存款，储户如提前支取，其提前支取的部分，仍按原规定执行。"},{"i":25,"n":"第二十五条","txt":"《条例》实施前存入的各种定期储蓄存款，其逾期部分的计息，以《条例》生效日（一九九三年三月一日）为界，以前的逾期部分仍按原办法计息，以后的逾期部分，均按照该存款支取日银行挂牌公告的活期存款利率计付。"},{"i":26,"n":"第二十六条","txt":"《条例》实施后，新存入的各种定期储蓄存款，在原定存期内如遇调整利率，不论调高或调低，均按存单开户日所定利率计付利息，不分段计息。"},{"i":27,"n":"第二十七条","txt":"《条例》实施后，新存入的定期储蓄存款，全部提前支取和部分提前支取的部分，均按支取日挂牌公告的活期储蓄利率计息；未提前支取的部分，仍按原存单所定利率计付利息。"},{"i":28,"n":"第二十八条","txt":"《条例》实施后，新存入的各种定期储蓄存款，逾期部分均按支取日挂牌公告的活期存款利率计付利息。"},{"i":29,"n":"第二十九条","txt":"《条例》实施后，不论何时存入的活期储蓄存款，如遇利率调整，不分段计息，均以结息日挂牌公告的活期存款利率计付利息（每年六月三十日为结息日，结算利息一次，并入本金起息，元以下的尾数不计利息）。未到结息日清户者，按清户日挂牌公告的活期存款利率算至清户前一天止。"},{"i":30,"n":"第三十条","txt":"如定期存款恰逢法定节假日到期，造成储户不能按期取款，储户可在储蓄机构节假日前一天办理支取存款，对此，手续上视同提前支取，但利息按到期支取计算。"},{"i":31,"n":"第三十一条","txt":"储户若发现利息支付有误，有权向经办的储蓄机构查询，储蓄机构应及时为储户复核，如核实确认有误，要如实更正。"},{"i":32,"n":"第三十二条","txt":"储蓄机构因擅自提高或变相提高利率的，由当地中国人民银行责令其纠正，并予以通报批评；由于提高利率而吸收的存款，缴存当地人民银行专户管理，不付利息，到存款期满止，这部分利息仍由该储蓄机构支付给储户。"},{"i":33,"n":"第三十三条","txt":"对吸收公款的储蓄机构，由当地中国人民银行责令限期清理。未按期清理的按吸收存款额每天处以万分之五的罚息；储蓄代办点吸收的公款，除按吸收存款额每天处以万分之五的罚息外，还要追回向银行收取的利息或代办费。凡未经批准而开办业务的储蓄机构，一经查出，要责令其限期关闭，其吸收的储蓄存款由当地中国人民银行指定转存就近储蓄机构。"},{"i":34,"n":"第三十四条","txt":"储户支取未到期的定期储蓄存款，必须持存单和本人居民身份证明（居民身份证、户口薄、军人证，外籍储户凭护照、居住证——下同）办理。代他人支取未到期定期存款的，代支取人还必须出具其居民身份证明。办理提前支取手续，出具其它身份证明无效，特殊情况的处理，可由储蓄机构业务主管部门自定。"},{"i":35,"n":"第三十五条","txt":"储蓄机构对于储户要求提前支取定期存款，在具备上述第三十六条条件下，验证存单开户人姓名与证件姓名一致后，即可支付该笔未到期定期存款。"},{"i":36,"n":"第三十六条","txt":"储户的存单（折）分为记名式和不记名式，记名式的存单（折）可挂失，不记名式的不可以挂失。"},{"i":37,"n":"第三十七条","txt":"储户的存单、存折如有遗失，必须立即持本人居民身份证明，并提供姓名、存款时间、种类、金额、帐号及住址等有关情况，书面向原储蓄机构正式声明挂失止付。储蓄机构在确认该笔存款未被支取的前提下，方可受理挂失手续。挂失七天后，储户需与储蓄机构约定时间，办理补领新存单（折）或支取存款手续。如储户本人不能前往办理，可委托他人代为办理挂失手续，但被委托人要出示其身份证明。如储户不能办理书面挂失手续，而用电话、电报、信函挂失，则必须在挂失五天之内补办书面挂失手续，否则挂失不再有效。若存款在挂失前或挂失失效后已被他人支取，储蓄机构不负责任。"},{"i":38,"n":"第三十八条","txt":"储蓄机构若发现有伪造、涂改存单和冒领存款者，应扣留存单（折），并报告有关部门进行处理。"},{"i":39,"n":"第三十九条","txt":"为维护储户的利益，凡查询、冻结、扣划个人存款者必须按法律、行政法规规定办理，任何单位不得擅自查询、冻结和扣划储户的存款。人民法院、人民检察院、公安机关和国家安全部门等因侦查、起诉、审理案件，需要向储蓄机构查询与案件直接有关的个人存款时，须向储蓄机构提出县级或县级以上法院、检察院、公安机关或国家安全机关等正式查询公函，并提供存款人的有关线索，如存款人的姓名、储蓄机构名称、存款日期等情况；储蓄机构不能提供原始帐册，只能提供复印件。对储蓄机构提供的存款情况，查询单位应保守秘密。"},{"i":40,"n":"第四十条","txt":"储蓄存款的所有权发生争议，涉及办理过户或支付手续，应慎重处理。 （一）存款人死亡后，合法继承人为证明自己的身份和有权提取该项存款，应向储蓄机构所在地的公证处（未设公证处的地方向县、市人民法院——下同）申请办理继承权证明书，储蓄机构凭以办理过户或支付手续。该项存款的继承权发生争执时，由人民法院判处。储蓄机构凭人民法院的判决书、裁定书或调解书办理过户或支付手续。 （二）存款人已死亡，但存单持有人没有向储蓄机构申明遗产继承过程，也没有持存款所在地法院判决书，直接去储蓄机构支取或转存存款人生前的存款，储蓄机构都视为正常支取或转存，事后而引起的存款继承争执，储蓄机构不负责任。 （三）在国外的华侨和港澳台同胞等在国内储蓄机构的存款或委托银行代为保管的存款，原存款人死亡，其合法继承人在国内者，凭原存款人的死亡证明向储蓄机构所在地的公证处申请办理继承权证明书，储蓄机构凭以办理存款的过户或支付手续。 （"},{"i":41,"n":"第四十一条","txt":"具有《储蓄管理条例》第三十四条行为之一的，中国人民银行及其分支机构有权令其纠正，根据国家有关法律、行政法规及政策，可处予罚款、停业整顿、吊销《经营金融业务许可证》，情节严重，构成犯罪的，由有关部门依法追究刑事责任。当事人若对有关部门的处罚决定不服，可依照《行政复议条例》的规定申请复议。对复议决定不服的，当事人可依照《中华人民共和国行政诉讼法》的规定向人民法院提起诉讼，由法院予以裁决。但当事人既不履行复议决定又不起诉的，则要按《行政复议条例》的规定执行。"},{"i":42,"n":"第四十二条","txt":"储蓄机构违反国家有关规定，侵犯储户合法权益，造成损失的，储蓄机构应当依法承担赔偿责任。"},{"i":43,"n":"第四十三条","txt":"《条例》和本《规定》执行过程中遇到的问题，请各行及时反馈中国人民银行总行利率储蓄司。"},{"i":44,"n":"第四十四条","txt":"根据《条例》和本《规定》的执行情况，中国人民银行将在适当的时候颁布《储蓄管理条例实施细则》。"}],"neidiyuxianggangzhaiquanshichanghulianhutonghezuogfea799":[{"i":1,"n":"第一条","txt":"为规范开展内地与香港债券市场互联互通合作相关业务，保护境内外投资者合法权益，维护债券市场秩序，根据《中华人民共和国中国人民银行法》和其他有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称内地与香港债券市场互联互通合作是指境内外投资者通过香港与内地债券市场基础设施机构连接，买卖香港与内地债券市场交易流通债券的机制安排，即“债券通”，包括“北向通”及“南向通”。 本办法适用于“北向通”。“北向通”是指香港及其他国家与地区的境外投资者（以下简称境外投资者）经由香港与内地基础设施机构之间在交易、托管、结算等方面互联互通的机制安排，投资于内地银行间债券市场。 “南向通”有关办法另行制定。"},{"i":3,"n":"第三条","txt":"“北向通”遵循香港与内地市场现行法律法规，相关交易结算活动遵守交易结算发生地的监管规定及业务规则。本办法另有规定的除外。"},{"i":4,"n":"第四条","txt":"符合中国人民银行要求的境外投资者可通过“北向通”投资内地银行间债券市场，标的债券为可在内地银行间债券市场交易流通的所有券种。 中国人民银行认可的电子交易平台和其他机构可代境外投资者向中国人民银行上海总部备案。"},{"i":5,"n":"第五条","txt":"香港金融管理局认可的香港地区债券登记托管机构（以下简称境外托管机构），应在中国人民银行认可的境内债券登记托管机构（以下简称境内托管机构）开立名义持有人账户，用于记载名义持有的全部债券余额。 境内托管机构为境外托管机构办理债券登记托管，境外托管机构为在其开立名义持有人债券账户和自营债券账户的债券持有人办理债券登记托管。 境外托管机构为在其开立债券账户的债券持有人登记的债券总额应当与境内托管机构为其名义持有人账户登记的债券余额相等。 境外投资者通过“北向通”买入的债券应当登记在境外托管机构名下，并依法享有证券权益。 本条所称名义持有人，是指受他人指定并代表他人持有债券的机构。"},{"i":6,"n":"第六条","txt":"境外投资者可通过“北向通”参与内地银行间债券市场发行认购。境内外托管机构应做好衔接，确保在确认债权债务关系后，及时为债券持有人办理登记托管。"},{"i":7,"n":"第七条","txt":"境外投资者通过中国人民银行认可的境外电子交易平台发送交易指令，并在中国人民银行认可的境内电子交易平台与其他投资者达成交易。境内电子交易平台应将交易结果发送至境内托管机构进行结算。"},{"i":8,"n":"第八条","txt":"境内托管机构为在其开立债券账户的内地银行间债券市场投资者和境外托管机构提供券款对付结算服务。债券过户通过境内托管机构的债券账务系统办理，资金支付通过人民币跨境支付系统办理。 境外托管机构为在其开立债券账户的债券持有人提供债券结算服务。"},{"i":9,"n":"第九条","txt":"境内外电子交易平台、境内外托管机构应及时、准确、完整地记录境外投资者的交易、托管、结算等数据。 托管机构应当逐级签订协议，约定债券本息兑付有关事宜，明确各方责任，确保债券本息资金按时足额支付到每一位投资者，下一级托管机构应逐级向上一级托管机构按时上报境外投资者信息和其托管结算数据，下一级托管机构对上报数据的真实性、准确性、完整性负责。 境内托管机构或中国人民银行指定的其他机构应及时、准确、完整地向人民币跨境收付信息管理系统（RCPMIS）报送跨境人民币收支信息。"},{"i":10,"n":"第十条","txt":"境外投资者可使用自有人民币或外汇投资。使用外汇投资的，可通过债券持有人在香港人民币业务清算行及香港地区经批准可进入境内银行间外汇市场进行交易的境外人民币业务参加行（以下统称香港结算行）办理外汇资金兑换。香港结算行由此所产生的头寸可到境内银行间外汇市场平盘。 使用外汇投资的，其投资的债券到期或卖出后不再投资的，原则上应兑换回外汇汇出，并通过香港结算行办理。"},{"i":11,"n":"第十一条","txt":"使用外汇投资的，债券持有人应在一家香港结算行开立人民币资金账户，专门用于办理“北向通”下的资金汇兑和结算业务。"},{"i":12,"n":"第十二条","txt":"境外投资者可通过债券持有人在香港结算行办理“北向通”下的外汇风险对冲业务。香港结算行由此所产生的头寸可到境内银行间外汇市场平盘。"},{"i":13,"n":"第十三条","txt":"“北向通”下的资金兑换纳入人民币购售业务管理。香港结算行应遵守反洗钱和反恐怖融资、人民币购售业务等相关规定，履行反洗钱和反恐怖融资、真实性审核、信息统计和报送等义务，并对债券持有人的自有人民币和购售人民币以适当方式进行分账。 香港结算行在境内银行间外汇市场平盘头寸时，应确保与其相关的境外投资者在本机构的资金兑换和外汇风险对冲，是基于“北向通”下的真实合理需求。"},{"i":14,"n":"第十四条","txt":"中国人民银行依法对“北向通”进行监督管理，并与香港金融管理局及其他有关国家或地区的相关监督管理机构建立监管合作安排，共同维护投资者跨境投资的合法权益，加强反洗钱监管。 中国人民银行会同国家外汇管理部门依法对“北向通”下人民币购售业务、资金汇出入、外汇风险对冲、信息统计和报送等实施监督管理，并与香港金融管理局及其他有关国家或地区的相关监督管理机构加强跨境监管合作，防范利用“北向通”进行违法违规套利套汇等活动。 中国人民银行及相关监管部门有权及时调取“北向通”境外投资者数据。"},{"i":15,"n":"第十五条","txt":"对违反法律法规、本办法以及内地银行间债券市场、银行间外汇市场等有关规定的，中国人民银行会同国家外汇管理部门依法采取监督管理措施；依法应予行政处罚的，依照《中华人民共和国中国人民银行法》、《中华人民共和国行政处罚法》、《中华人民共和国外汇管理条例》等法律法规进行处罚；涉嫌犯罪的，移送司法机关依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"中国人民银行认可的电子交易平台和托管机构应依据本办法制定“北向通”相关业务规则，报中国人民银行批准后实施。"},{"i":17,"n":"第十七条","txt":"本办法由中国人民银行负责解释。"},{"i":18,"n":"第十八条","txt":"本办法自发布之日起施行。"}],"dongchanhequanlidanbaotongyidengjibanfa":[{"i":1,"n":"第一条","txt":"为规范动产和权利担保统一登记，保护担保当事人和利害关系人的合法权益，根据《中华人民共和国民法典》《优化营商环境条例》《国务院关于实施动产和权利担保统一登记的决定》（国发〔2020〕18号）等相关法律法规规定，制定本办法。"},{"i":2,"n":"第二条","txt":"纳入动产和权利担保统一登记范围的担保类型包括： （一）生产设备、原材料、半成品、产品抵押； （二）应收账款质押； （三）存款单、仓单、提单质押； （四）融资租赁； （五）保理； （六）所有权保留； （七）其他可以登记的动产和权利担保，但机动车抵押、船舶抵押、航空器抵押、债券质押、基金份额质押、股权质押、知识产权中的财产权质押除外。"},{"i":3,"n":"第三条","txt":"本办法所称应收账款是指应收账款债权人因提供一定的货物、服务或设施而获得的要求应收账款债务人付款的权利以及依法享有的其他付款请求权，包括现有的以及将有的金钱债权，但不包括因票据或其他有价证券而产生的付款请求权，以及法律、行政法规禁止转让的付款请求权。 本办法所称的应收账款包括下列权利： （一）销售、出租产生的债权，包括销售货物，供应水、电、气、暖，知识产权的许可使用，出租动产或不动产等； （二）提供医疗、教育、旅游等服务或劳务产生的债权； （三）能源、交通运输、水利、环境保护、市政工程等基础设施和公用事业项目收益权； （四）提供贷款或其他信用活动产生的债权； （五）其他以合同为基础的具有金钱给付内容的债权。"},{"i":4,"n":"第四条","txt":"中国人民银行征信中心（以下简称征信中心）是动产和权利担保的登记机构，具体承担服务性登记工作，不开展事前审批性登记，不对登记内容进行实质审查。 征信中心建立基于互联网的动产融资统一登记公示系统（以下简称统一登记系统）为社会公众提供动产和权利担保登记和查询服务。"},{"i":5,"n":"第五条","txt":"中国人民银行对征信中心登记和查询服务有关活动进行督促指导。"},{"i":6,"n":"第六条","txt":"纳入统一登记范围的动产和权利担保登记通过统一登记系统办理。"},{"i":7,"n":"第七条","txt":"担保权人办理登记。担保权人办理登记前，应当与担保人就登记内容达成一致。 担保权人也可以委托他人办理登记。委托他人办理登记的，适用本办法关于担保权人办理登记的规定。"},{"i":8,"n":"第八条","txt":"担保权人办理登记时，应当注册为统一登记系统的用户。"},{"i":9,"n":"第九条","txt":"登记内容包括担保权人和担保人的基本信息、担保财产的描述、登记期限。 担保权人或担保人为法人、非法人组织的，应当填写法人、非法人组织的法定注册名称、住所、法定代表人或负责人姓名，金融机构编码、统一社会信用代码、全球法人识别编码等机构代码或编码以及其他相关信息。 担保权人或担保人为自然人的，应当填写有效身份证件号码、有效身份证件载明的地址等信息。 担保权人可以与担保人约定将主债权金额、担保范围、禁止或限制转让的担保财产等项目作为登记内容。对担保财产进行概括性描述的，应当能够合理识别担保财产。 最高额担保应登记最高债权额。"},{"i":10,"n":"第十条","txt":"担保权人应当将填写完毕的登记内容提交统一登记系统。统一登记系统记录提交时间并分配登记编号，生成初始登记证明和修改码提供给担保权人。"},{"i":11,"n":"第十一条","txt":"担保权人应当根据主债权履行期限合理确定登记期限。登记期限最短1个月，最长不超过30年。"},{"i":12,"n":"第十二条","txt":"在登记期限届满前，担保权人可以申请展期。 担保权人可以多次展期，每次展期期限最短1个月，最长不超过30年。"},{"i":13,"n":"第十三条","txt":"登记内容存在遗漏、错误等情形或登记内容发生变化的，担保权人应当办理变更登记。 担保权人在原登记中增加新的担保财产的，新增加的部分视为新的登记。"},{"i":14,"n":"第十四条","txt":"担保权人办理登记时所填写的担保人法定注册名称或有效身份证件号码变更的，担保权人应当自变更之日起4个月内办理变更登记。"},{"i":15,"n":"第十五条","txt":"担保权人办理展期、变更登记的，应当与担保人就展期、变更事项达成一致。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，担保权人应当自该情形发生之日起10个工作日内办理注销登记： （一）主债权消灭； （二）担保权利实现； （三）担保权人放弃登记载明的担保财产之上的全部担保权； （四）其他导致所登记权利消灭的情形。 担保权人迟延办理注销登记，给他人造成损害的，应当承担相应的法律责任。"},{"i":17,"n":"第十七条","txt":"担保权人凭修改码办理展期、变更登记、注销登记。"},{"i":18,"n":"第十八条","txt":"担保人或其他利害关系人认为登记内容错误的，可以要求担保权人办理变更登记或注销登记。担保权人不同意变更或注销的，担保人或其他利害关系人可以办理异议登记。 办理异议登记的担保人或其他利害关系人可以自行注销异议登记。"},{"i":19,"n":"第十九条","txt":"担保人或其他利害关系人应当自异议登记办理完毕之日起7日内通知担保权人。"},{"i":20,"n":"第二十条","txt":"担保人或其他利害关系人自异议登记之日起30日内，未就争议起诉或提请仲裁并在统一登记系统提交案件受理通知的，征信中心撤销异议登记。"},{"i":21,"n":"第二十一条","txt":"应担保人或其他利害关系人、担保权人的申请，征信中心根据对担保人或其他利害关系人、担保权人生效的人民法院判决、裁定或仲裁机构裁决等法律文书撤销相关登记。"},{"i":22,"n":"第二十二条","txt":"担保权人办理变更登记和注销登记、担保人或其他利害关系人办理异议登记后，统一登记系统记录登记时间、分配登记编号，并生成变更登记、注销登记或异议登记证明。"},{"i":23,"n":"第二十三条","txt":"担保权人开展动产和权利担保融资业务时，应当严格审核确认担保财产的真实性，并在统一登记系统中查询担保财产的权利负担状况。"},{"i":24,"n":"第二十四条","txt":"担保权人、担保人和其他利害关系人应当按照统一登记系统提示项目如实登记，并对登记内容的真实性、完整性和合法性负责。因担保权人或担保人名称填写错误，担保财产描述不能够合理识别担保财产等情形导致不能正确公示担保权利的，其法律后果由当事人自行承担。办理登记时，存在提供虚假材料等行为给他人造成损害的，应当承担相应的法律责任。"},{"i":25,"n":"第二十五条","txt":"任何法人、非法人组织和自然人均可以在注册为统一登记系统的用户后，查询动产和权利担保登记信息。"},{"i":26,"n":"第二十六条","txt":"担保人为法人、非法人组织的，查询人以担保人的法定注册名称进行查询。 担保人为自然人的，查询人以担保人的身份证件号码进行查询。"},{"i":27,"n":"第二十七条","txt":"征信中心根据查询人的申请，提供查询证明。"},{"i":28,"n":"第二十八条","txt":"担保权人、担保人或其他利害关系人、查询人可以通过证明编号在统一登记系统对登记证明和查询证明进行验证。"},{"i":29,"n":"第二十九条","txt":"征信中心应当建立登记信息内部控制制度，采取技术措施和其他必要措施，做好统一登记系统建设和维护工作，保障系统安全、稳定运行，建立高效运转的服务体系，不断提高服务效率和质量，防止登记信息泄露、丢失，保护当事人合法权益。"},{"i":30,"n":"第三十条","txt":"征信中心应当制定登记操作规则和内部管理制度，并报中国人民银行备案。"},{"i":31,"n":"第三十一条","txt":"登记注销、登记期限届满或登记撤销后，征信中心应当对登记记录进行电子化离线保存，保存期限为15年。"},{"i":32,"n":"第三十二条","txt":"征信中心按照国务院价格主管部门批准的收费标准收取登记服务费用。"},{"i":33,"n":"第三十三条","txt":"本办法由中国人民银行负责解释。"},{"i":34,"n":"第三十四条","txt":"本办法自2022年2月1日起施行。《应收账款质押登记办法》（中国人民银行令〔2019〕第4号发布）同时废止。"}],"fanxiqiantebieyufangcuoshiguanlibanfa":[{"i":1,"n":"第一条","txt":"为预防洗钱、恐怖融资及大规模杀伤性武器扩散融资活动，规范反洗钱特别预防措施，根据《中华人民共和国反洗钱法》《中华人民共和国反恐怖主义法》《中华人民共和国对外关系法》等法律，制定本办法。"},{"i":2,"n":"第二条","txt":"任何单位和个人应当依法对下列名单所列对象采取反洗钱特别预防措施： （一）国家反恐怖工作领导小组认定并由其办公室公告的恐怖活动组织和人员名单； （二）外交部发布的执行联合国安理会决议通知中涉及定向金融制裁的组织和人员名单； （三）中国人民银行认定或者会同国家有关机关认定的，具有重大洗钱风险、不采取措施可能造成严重后果的组织和人员名单。"},{"i":3,"n":"第三条","txt":"本办法所称反洗钱特别预防措施，包括立即停止向本办法第二条规定的名单所列对象及其代理人、受其指使的组织和人员、其直接或者间接控制的组织提供金融等服务或者资金、资产，立即限制相关资金、资产转移等。 采取反洗钱特别预防措施不得事先通知前款规定的相关组织和人员。"},{"i":4,"n":"第四条","txt":"采取反洗钱特别预防措施应当依法保护善意第三人的合法权益。 善意第三人可以依法进行权利救济。"},{"i":5,"n":"第五条","txt":"对依法履行反洗钱特别预防措施相关职责或者义务获得的客户身份资料和交易信息等反洗钱信息，应当予以保密。非依法律规定，不得向任何单位和个人提供。"},{"i":6,"n":"第六条","txt":"单位和个人依法采取反洗钱特别预防措施受法律保护。"},{"i":7,"n":"第七条","txt":"公安部、国家安全部、外交部、中国人民银行在各自职责范围内开展本办法第二条规定的名单的认定、发布、除名等相关工作，并互相配合。 中国人民银行依法对金融机构履行反洗钱特别预防措施义务的情况进行监督管理和指导。 国务院有关特定非金融机构主管部门依法对特定非金融机构履行反洗钱特别预防措施义务的情况进行监督管理和指导。"},{"i":8,"n":"第八条","txt":"国家有关机关通过多种形式开展反洗钱特别预防措施宣传教育活动，增强社会公众对洗钱、恐怖融资及大规模杀伤性武器扩散融资活动的防范意识和识别能力。"},{"i":9,"n":"第九条","txt":"对本办法第二条第一项规定的名单有异议的，当事人可以依照《中华人民共和国反恐怖主义法》的相关规定，通过国家反恐怖工作领导小组办公室申请复核。 对本办法第二条第二项规定的名单有异议的，当事人可以按照外交部公布的有关程序提出除名申请。 对本办法第二条第三项规定的名单有异议的，当事人可以向作出认定的部门申请行政复议；对行政复议决定不服的，可以依法提起行政诉讼。"},{"i":10,"n":"第十条","txt":"为支付基本开支及其他必需的费用，名单所列对象可以根据名单类型向公安部、外交部、中国人民银行申请使用被限制转移的资金、资产。 申请通过后，资金、资产的所有人、控制人或者管理人应当配合按照指定用途、金额、方式等动用资金、资产。"},{"i":11,"n":"第十一条","txt":"金融机构应当建立健全反洗钱特别预防措施内控制度，识别和评估相关风险，采取与风险相适应的管理措施。"},{"i":12,"n":"第十二条","txt":"金融机构应当持续关注并及时获取本办法第二条规定的名单。"},{"i":13,"n":"第十三条","txt":"本办法第二条规定的名单发布或者发生调整时，金融机构应当根据名单对所有客户进行核查。 金融机构与客户建立业务关系、为客户提供一次性金融服务，或者业务关系存续期间客户身份基本信息发生变化的，应当根据名单对客户进行核查。"},{"i":14,"n":"第十四条","txt":"金融机构应当根据名单对客户的交易对象进行核查。"},{"i":15,"n":"第十五条","txt":"金融机构应当对所有业务开展名单核查。"},{"i":16,"n":"第十六条","txt":"核查发现客户或者其交易对象属于名单所列对象或者其代理人、受其指使的组织或者人员、其直接或者间接控制的组织的，金融机构应当立即采取反洗钱特别预防措施。 在采取限制转移措施时，前款规定的组织或者人员与他人共同拥有或者控制的资金、资产，如无法分割或者确定份额的，金融机构应当一并采取措施。"},{"i":17,"n":"第十七条","txt":"金融机构对客户或者其交易对象是否属于名单所列对象存在疑问的，可以向名单发布机关申请协助核实。"},{"i":18,"n":"第十八条","txt":"金融机构采取反洗钱特别预防措施后，应当将采取的措施、被限制转移的资金或者资产、客户试图进行的交易等信息按照规定及时书面报告中国人民银行或者其分支机构。 对本办法第二条第一项规定的名单所列对象采取反洗钱特别预防措施的，还应当按照规定及时向国务院公安部门、国家安全部门书面报告。"},{"i":19,"n":"第十九条","txt":"金融机构采取反洗钱特别预防措施后，可以以适当方式告知被采取反洗钱特别预防措施的对象，说明采取的措施和理由。法律、行政法规或者相关部门另有保密要求的除外。"},{"i":20,"n":"第二十条","txt":"被采取反洗钱特别预防措施的组织和个人认为金融机构采取反洗钱特别预防措施不符合有关法律法规要求的，可以向金融机构提出，金融机构应当及时处理。"},{"i":21,"n":"第二十一条","txt":"采取反洗钱特别预防措施期间，金融机构可以通过有关账户收取被列名对象根据名单发布前签订的合同、协议或者其他债权债务关系应收的款项及其他收入。 对于前款规定的应收款项和其他收入，金融机构应当一并采取反洗钱特别预防措施。"},{"i":22,"n":"第二十二条","txt":"在采取限制转移措施期间，相关资金、资产发生变动的，金融机构应当及时报告中国人民银行或者其分支机构。"},{"i":23,"n":"第二十三条","txt":"任何单位和个人不得擅自解除反洗钱特别预防措施。 符合下列情形之一的，应当立即解除反洗钱特别预防措施： （一）本办法第二条规定的名单发生调整，相关组织或者人员不再属于名单范围的； （二）经核实采取反洗钱特别预防措施有误的； （三）经相关部门通过法定程序认定需要解除反洗钱特别预防措施的。 金融机构解除反洗钱特别预防措施，应当按照本办法第十八条的规定报告。"},{"i":24,"n":"第二十四条","txt":"特定非金融机构在从事规定的特定业务时，参照本办法关于金融机构履行反洗钱特别预防措施的相关规定，根据行业特点、经营规模、洗钱风险状况履行反洗钱特别预防措施义务。"},{"i":25,"n":"第二十五条","txt":"依法负有反洗钱特别预防措施相关职责的部门工作人员违反规定，泄露应予保密的信息的，依法给予处分。"},{"i":26,"n":"第二十六条","txt":"金融机构违反本办法，未按照规定制定、完善反洗钱特别预防措施内控制度的，由中国人民银行或者其设区的市级以上分支机构依照《中华人民共和国反洗钱法》第五十二条的规定进行处罚。 金融机构未按照本办法规定履行反洗钱特别预防措施义务的，由中国人民银行或者其设区的市级以上分支机构依照《中华人民共和国反洗钱法》第五十四条的规定进行处罚；致使犯罪所得及其收益通过本机构得以掩饰、隐瞒的，或者致使恐怖主义融资后果发生的，依照《中华人民共和国反洗钱法》第五十五条的规定进行处罚。 中国人民银行或者其设区的市级以上分支机构按照以上两款规定对金融机构进行处罚的，还可以根据情形对负有责任的董事、监事、高级管理人员或者其他直接责任人员，依照《中华人民共和国反洗钱法》第五十六条的规定进行处罚。"},{"i":27,"n":"第二十七条","txt":"特定非金融机构违反本办法规定的，由特定非金融机构主管部门依照《中华人民共和国反洗钱法》第五十八条的规定进行处罚。"},{"i":28,"n":"第二十八条","txt":"金融机构以及特定非金融机构以外的单位和个人违反本办法规定的，由中国人民银行或者其设区的市级以上分支机构依照《中华人民共和国反洗钱法》第五十九条的规定进行处罚。"},{"i":29,"n":"第二十九条","txt":"本办法所称任何单位和个人，是指中华人民共和国公民、依照中华人民共和国法律设立的法人、非法人组织及其境内外分支机构，以及位于中华人民共和国境内的其他单位和个人。 本办法第三条要求立即限制转移的资金、资产包括： （一）名单所列对象直接或者间接、单独或者与他人共同所有或者控制的所有资金、资产，不仅限于与特定恐怖行为或者扩散行为相关的资金、资产； （二）前一项规定的资金、资产所产生的孳息和其他收益； （三）名单所列对象的代理人、受其指使的组织和人员的资金、资产。 本办法所称基本开支，包括购买食物、住房支出、医药费、水电费等用于维持生活的基本费用，以及税费、资金管理费、资产维护费等。 本办法所称资金、资产包括任何形式的资金或者资产，不论是有形资产或者无形资产，动产或者不动产，包括但不限于银行存款、票据、邮政汇票、保单、提单、仓单、信用证，股票、债券及其他证券，房屋、土地、车辆、船舶、货物，石油等"},{"i":30,"n":"第三十条","txt":"本办法由中国人民银行会同外交部、公安部、国家安全部、司法部、财政部、住房城乡建设部、市场监管总局解释。"},{"i":31,"n":"第三十一条","txt":"本办法自2026年2月16日起施行。《涉及恐怖活动资产冻结管理办法》（中国人民银行 公安部 国家安全部令〔2014〕第1号）同时废止。"}],"shouyisuoyourenxinxiguanlibanfa":[{"i":1,"n":"第一条","txt":"为提高市场透明度，维护市场秩序、金融秩序，预防和遏制洗钱、恐怖主义融资活动，根据反洗钱和企业登记管理有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"下列主体（以下统称备案主体）应当根据本办法规定通过相关登记注册系统备案受益所有人信息： （一）公司； （二）合伙企业； （三）外国公司分支机构； （四）中国人民银行、国家市场监督管理总局规定的其他主体。 个体工商户无需备案受益所有人信息。"},{"i":3,"n":"第三条","txt":"注册资本（出资额）不超过1000万元人民币（或者等值外币）且股东、合伙人全部为自然人的备案主体，如果不存在股东、合伙人以外的自然人对其实际控制或者从其获取收益，也不存在通过股权、合伙权益以外的方式对其实施控制或者从其获取收益的情形，承诺后免于备案受益所有人信息。"},{"i":4,"n":"第四条","txt":"国家市场监督管理总局统筹指导相关登记注册系统建设，指导地方登记机关依法开展受益所有人信息备案工作，及时将归集的受益所有人信息推送至中国人民银行。县级以上地方市场监督管理部门督促备案主体及时备案受益所有人信息。 中国人民银行建立受益所有人信息管理系统，及时接收、保存、处理受益所有人信息。中国人民银行及其分支机构督促备案主体准确备案受益所有人信息。"},{"i":5,"n":"第五条","txt":"中国人民银行及其分支机构为受益所有人信息备案工作提供指导，市场监督管理部门予以配合。"},{"i":6,"n":"第六条","txt":"符合下列条件之一的自然人为备案主体的受益所有人： （一）通过直接方式或者间接方式最终拥有备案主体25%以上股权、股份或者合伙权益； （二）虽未满足第一项标准，但最终享有备案主体25%以上收益权、表决权； （三）虽未满足第一项标准，但单独或者联合对备案主体进行实际控制。 前款第三项所称实际控制包括但不限于通过协议约定、关系密切的人等方式实施控制，例如决定法定代表人、董事、监事、高级管理人员或者执行事务合伙人的任免，决定重大经营、管理决策的制定或者执行，决定财务收支，长期实际支配使用重要资产或者主要资金等。 不存在第一款规定三种情形的，应当将备案主体中负责日常经营管理的人员视为受益所有人进行备案。"},{"i":7,"n":"第七条","txt":"国有独资公司、国有控股公司应当将法定代表人视为受益所有人进行备案。"},{"i":8,"n":"第八条","txt":"外国公司分支机构的受益所有人为外国公司按照本办法第六条规定认定的受益所有人，以及该分支机构的高级管理人员。 外国公司在其本国享受的受益所有人申报豁免标准不适用于中国。"},{"i":9,"n":"第九条","txt":"备案主体在设立登记时，应当通过相关登记注册系统备案受益所有人信息。 无法通过相关登记注册系统办理设立登记的，可以现场办理，并在设立登记之日起30日内，通过相关登记注册系统备案受益所有人信息。"},{"i":10,"n":"第十条","txt":"备案主体受益所有人信息发生变化，或者不再符合本办法第三条规定的承诺免报条件的，应当自发生变化或者不符合承诺免报条件之日起30日内，通过相关登记注册系统备案受益所有人信息。"},{"i":11,"n":"第十一条","txt":"备案主体备案受益所有人信息时，应当填报下列信息： （一）姓名； （二）性别； （三）国籍； （四）出生日期； （五）经常居住地或者工作单位地址； （六）联系方式； （七）身份证件或者身份证明文件种类、号码、有效期限； （八）受益所有权关系类型以及形成日期、终止日期（如有）。 存在本办法第六条第一款第一项规定情形的，还应当填报持有股权、股份或者合伙权益的比例；存在本办法第六条第一款第二项规定情形的，还应当填报收益权、表决权的比例；存在本办法第六条第一款第三项规定情形的，还应当填报实际控制的方式。"},{"i":12,"n":"第十二条","txt":"国家有关机关为履行职责需要，可以依法向中国人民银行获取受益所有人信息。 金融机构、特定非金融机构履行反洗钱和反恐怖主义融资义务时，可以通过中国人民银行查询受益所有人信息。 国家有关机关以及金融机构、特定非金融机构对依法获得的受益所有人信息应当予以保密。"},{"i":13,"n":"第十三条","txt":"国家有关机关以及金融机构、特定非金融机构发现受益所有人信息管理系统中的备案主体受益所有人信息存在错误、不一致或者不完整的，应当及时向中国人民银行反馈。中国人民银行可以根据情形依法采取措施进行核实，备案主体应当配合。 对市场透明度、金融透明度有显著影响的备案主体，中国人民银行等主管部门可以要求其补充提供确定受益所有人所需要的股权、合伙权益、收益权、表决权、控制关系等情况的材料。"},{"i":14,"n":"第十四条","txt":"备案主体未按照规定办理受益所有人信息备案的，依照企业登记管理有关行政法规处理。 中国人民银行及其分支机构发现备案主体备案的受益所有人信息不准确的，应当责令备案主体限期改正；拒不改正的，处5万元以下的罚款。"},{"i":15,"n":"第十五条","txt":"本办法所称受益所有人，是指最终拥有或者实际控制备案主体，或者享有备案主体最终收益的自然人。"},{"i":16,"n":"第十六条","txt":"在本办法实施前已经登记注册的备案主体，应当于2025年11月1日前，按照本办法规定备案受益所有人信息。"},{"i":17,"n":"第十七条","txt":"本办法自2024年11月1日起施行。"}],"tongyechaijieguanlibanfa":[{"i":1,"n":"第一条","txt":"为进一步发展货币市场、规范同业拆借交易、防范同业拆借风险、维护同业拆借各方当事人的合法权益，根据《中华人民共和国中国人民银行法》、《中华人民共和国商业银行法》等有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内依法设立的金融机构之间进行的人民币同业拆借交易。"},{"i":3,"n":"第三条","txt":"本办法所称同业拆借，是指经中国人民银行批准进入全国银行间同业拆借市场（以下简称同业拆借市场）的金融机构之间，通过全国统一的同业拆借网络进行的无担保资金融通行为。全国统一的同业拆借网络包括： （一）全国银行间同业拆借中心的电子交易系统； （二）中国人民银行分支机构的拆借备案系统； （三）中国人民银行认可的其他交易系统。"},{"i":4,"n":"第四条","txt":"中国人民银行依法对同业拆借市场进行监督管理。金融机构进入同业拆借市场必须经中国人民银行批准，从事同业拆借交易接受中国人民银行的监督和检查。"},{"i":5,"n":"第五条","txt":"同业拆借交易应遵循公平自愿、诚信自律、风险自担的原则。"},{"i":6,"n":"第六条","txt":"下列金融机构可以向中国人民银行申请进入同业拆借市场： （一）政策性银行； （二）中资商业银行； （三）外商独资银行、中外合资银行； （四）城市信用合作社； （五）农村信用合作社县级联合社； （六）企业集团财务公司； （七）信托公司； （八）金融资产管理公司； （九）金融租赁公司； （十）汽车金融公司； （十一）证券公司； （十二）保险公司； （十三）保险资产管理公司； （十四）中资商业银行（不包括城市商业银行、农村商业银行和农村合作银行）授权的一级分支机构； （十五）外国银行分行； （十六）中国人民银行确定的其他机构。"},{"i":7,"n":"第七条","txt":"申请进入同业拆借市场的金融机构应当具备以下条件： （一）在中华人民共和国境内依法设立； （二）有健全的同业拆借交易组织机构、风险管理制度和内部控制制度； （三）有专门从事同业拆借交易的人员； （四）主要监管指标符合中国人民银行和有关监管部门的规定； （五）最近二年未因违法、违规行为受到中国人民银行和有关监管部门处罚； （六）最近二年未出现资不抵债情况； （七）中国人民银行规定的其他条件。"},{"i":8,"n":"第八条","txt":"下列金融机构申请进入同业拆借市场，除具备本办法第七条所规定的条件外，还应具备以下条件： （一）外商独资银行、中外合资银行、外国银行分行经国务院银行业监督管理机构批准获得经营人民币业务资格； （二）企业集团财务公司、信托公司、金融资产管理公司、金融租赁公司、汽车金融公司、保险资产管理公司在申请进入同业拆借市场前最近两个年度连续盈利； （三）证券公司应在申请进入同业拆借市场前最近两个年度连续盈利，同期未出现净资本低于2亿元的情况； （四）保险公司应在申请进入同业拆借市场前最近四个季度连续的偿付能力充足率在120%以上。"},{"i":9,"n":"第九条","txt":"金融机构申请进入同业拆借市场，应按照中国人民银行规定的程序向中国人民银行或其分支机构提交申请材料。"},{"i":10,"n":"第十条","txt":"中国人民银行及其分支机构审核金融机构进入同业拆借市场申请的期限，适用《中国人民银行行政许可实施办法》第二十八条和第二十九条的规定。"},{"i":11,"n":"第十一条","txt":"已进入同业拆借市场的金融机构决定退出同业拆借市场时，应至少提前30日报告中国人民银行或其分支机构，并说明退出同业拆借市场的原因，提交债权债务清理处置方案。 金融机构退出同业拆借市场必须采取有效措施保证债权债务关系顺利清理，并针对可能出现的问题制定有效的风险处置预案。"},{"i":12,"n":"第十二条","txt":"中国人民银行及其分支机构批准金融机构进入同业拆借市场或者接到金融机构退出同业拆借市场的报告后，应以适当方式向同业拆借市场发布公告。在中国人民银行或其分支机构正式发布公告之前，任何机构不得擅自对市场发布相关信息。"},{"i":13,"n":"第十三条","txt":"中国人民银行及其分支机构自发布金融机构退出同业拆借市场公告之日起两年之内不再受理该金融机构进入同业拆借市场的申请。"},{"i":14,"n":"第十四条","txt":"同业拆借交易必须在全国统一的同业拆借网络中进行。 政策性银行、企业集团财务公司、信托公司、金融资产管理公司、金融租赁公司、汽车金融公司、证券公司、保险公司、保险资产管理公司以法人为单位，通过全国银行间同业拆借中心的电子交易系统进行同业拆借交易。 通过中国人民银行分支机构拆借备案系统进行同业拆借交易的金融机构应按照中国人民银行当地分支机构的规定办理相关手续。"},{"i":15,"n":"第十五条","txt":"同业拆借交易以询价方式进行，自主谈判、逐笔成交。"},{"i":16,"n":"第十六条","txt":"同业拆借利率由交易双方自行商定。"},{"i":17,"n":"第十七条","txt":"金融机构进行同业拆借交易，应逐笔订立交易合同。交易合同的内容应当具体明确，详细约定同业拆借双方的权利和义务。合同应包括以下内容： （一）同业拆借交易双方的名称、住所及法定代表人的姓名； （二）同业拆借成交日期； （三）同业拆借交易金额； （四）同业拆借交易期限； （五）同业拆借利率、利率计算规则和利息支付规则； （六）违约责任； （七）中国人民银行要求载明的其他事项。"},{"i":18,"n":"第十八条","txt":"交易合同可采用全国银行间同业拆借中心电子交易系统生成的成交单，或者采取合同书、信件和数据电文等书面形式。"},{"i":19,"n":"第十九条","txt":"同业拆借的资金清算涉及不同银行的，应直接或委托开户银行通过中国人民银行大额实时支付系统办理。同业拆借的资金清算可以在同一银行完成的，应以转账方式进行。任何同业拆借清算均不得使用现金支付。"},{"i":20,"n":"第二十条","txt":"金融机构应当将同业拆借风险管理纳入本机构风险管理的总体框架之中，并根据同业拆借业务的特点，建立健全同业拆借风险管理制度，设立专门的同业拆借风险管理机构，制定同业拆借风险管理内部操作规程和控制措施。"},{"i":21,"n":"第二十一条","txt":"金融机构应当依法妥善保存其同业拆借交易的所有交易记录和与交易记录有关的文件、账目、原始凭证、报表、电话录音等资料。"},{"i":22,"n":"第二十二条","txt":"商业银行同业拆借的拆入资金用途应符合《中华人民共和国商业银行法》的有关规定。"},{"i":23,"n":"第二十三条","txt":"同业拆借的期限在符合以下规定的前提下，由交易双方自行商定： （一）政策性银行、中资商业银行、中资商业银行授权的一级分支机构、外商独资银行、中外合资银行、外国银行分行、城市信用合作社、农村信用合作社县级联合社拆入资金的最长期限为1年； （二）金融资产管理公司、金融租赁公司、汽车金融公司、保险公司拆入资金的最长期限为3个月； （三）企业集团财务公司、信托公司、证券公司、保险资产管理公司拆入资金的最长期限为7天； （四）金融机构拆出资金的最长期限不得超过对手方由中国人民银行规定的拆入资金最长期限。 中国人民银行可以根据市场发展和管理的需要调整金融机构的拆借资金最长期限。"},{"i":24,"n":"第二十四条","txt":"同业拆借到期后不得展期。"},{"i":25,"n":"第二十五条","txt":"对金融机构同业拆借实行限额管理，拆借限额由中国人民银行及其分支机构按照以下原则核定： （一）政策性银行的最高拆入限额和最高拆出限额均不超过该机构上年末待偿还金融债券余额的8%； （二）中资商业银行、城市信用合作社、农村信用合作社县级联合社的最高拆入限额和最高拆出限额均不超过该机构各项存款余额的8%； （三）外商独资银行、中外合资银行的最高拆入限额和最高拆出限额均不超过该机构实收资本的2倍； （四）外国银行分行的最高拆入限额和最高拆出限额均不超过该机构人民币营运资金的2倍； （五）企业集团财务公司、金融资产管理公司、金融租赁公司、汽车金融公司、保险公司的最高拆入限额和最高拆出限额均不超过该机构实收资本的100%； （六）信托公司、保险资产管理公司的最高拆入限额和最高拆出限额均不超过该机构净资产的20%； （七）证券公司的最高拆入限额和最高拆出限额均不超过该机构净资本的80%； （八）中资"},{"i":26,"n":"第二十六条","txt":"金融机构申请调整拆借资金限额，应比照申请进入同业拆借市场的程序向中国人民银行或其分支机构提交申请材料。"},{"i":27,"n":"第二十七条","txt":"中国人民银行可以根据金融机构的申请临时调整拆借资金限额。 中国人民银行分支机构可在总行授权的范围内临时调整辖内金融机构的拆借资金限额。"},{"i":28,"n":"第二十八条","txt":"进入同业拆借市场的金融机构承担向同业拆借市场披露信息的义务。金融机构的董事或法定代表人应当保证所披露的信息真实、准确、完整、及时。"},{"i":29,"n":"第二十九条","txt":"中国人民银行负责制定同业拆借市场中各类金融机构的信息披露规范并监督实施。"},{"i":30,"n":"第三十条","txt":"全国银行间同业拆借中心是同业拆借市场的中介服务机构，为金融机构在同业拆借市场的交易和信息披露提供服务。 全国银行间同业拆借中心应依据本办法制定同业拆借市场交易和信息披露操作规则，报中国人民银行批准后实施。"},{"i":31,"n":"第三十一条","txt":"全国银行间同业拆借中心应及时向市场公布利率、交易量、重大异常交易等市场信息和统计数据。"},{"i":32,"n":"第三十二条","txt":"全国银行间同业拆借中心负责同业拆借市场日常监测和市场统计，定期向中国人民银行上报同业拆借市场统计数据，向中国人民银行省一级分支机构提供备案系统统计信息，发现同业拆借市场异常情况及时向中国人民银行报告并通知中国人民银行相关省一级分支机构。"},{"i":33,"n":"第三十三条","txt":"金融机构未按照中国人民银行的规定向同业拆借市场披露信息，或者所披露信息有虚假记载、误导性陈述或重大遗漏的，中国人民银行有权对该金融机构采取限期补充信息披露、核减同业拆借限额、缩短同业拆借最长期限、限制同业拆借交易范围、暂停或停止与全国银行间同业拆借中心交易联网等约束措施。"},{"i":34,"n":"第三十四条","txt":"中国人民银行依法对同业拆借交易实施非现场监管和现场检查，并对同业拆借市场的行业自律组织进行指导和监督。"},{"i":35,"n":"第三十五条","txt":"中国人民银行省一级分支机构负责拟定辖区同业拆借备案管理实施办法，并对辖区内金融机构通过拆借备案系统进行的同业拆借交易进行监管。"},{"i":36,"n":"第三十六条","txt":"中国人民银行或者其省一级分支机构根据履行同业拆借市场监管职责的需要，可以采取下列措施进行同业拆借现场检查： （一）进入金融机构进行检查； （二）询问金融机构的工作人员，要求其对有关检查事项作出说明； （三）查阅、复制金融机构与检查事项有关的文件、资料，并对可能被转移、销毁、隐匿或者篡改的文件资料予以封存； （四）检查金融机构运用电子计算机管理业务数据的系统。"},{"i":37,"n":"第三十七条","txt":"中国人民银行地市中心支行发现同业拆借异常交易，认为有必要进行同业拆借现场检查的，应报告有管辖权的中国人民银行省一级分支机构批准后实施。"},{"i":38,"n":"第三十八条","txt":"中国人民银行及其地市中心支行以上分支机构进行同业拆借现场检查的，应当遵守中国人民银行有关监督检查程序的规定。"},{"i":39,"n":"第三十九条","txt":"中国人民银行及其地市中心支行以上分支机构根据履行同业拆借市场监管职责的需要，可以与金融机构董事、高级管理人员谈话，要求其就金融机构执行同业拆借市场管理规定的重大事项作出说明。"},{"i":40,"n":"第四十条","txt":"中国人民银行及其地市中心支行以上分支机构对金融机构实施同业拆借现场检查，必要时将检查情况通报有关监管部门。"},{"i":41,"n":"第四十一条","txt":"金融机构有下列行为之一的，由中国人民银行或者其地市中心支行以上分支机构实施处罚： （一）不具有同业拆借业务资格而从事同业拆借业务； （二）与不具备同业拆借业务资格的机构进行同业拆借； （三）在全国统一同业拆借市场网络之外从事同业拆借业务； （四）拆入资金用途违反相关法律规定； （五）同业拆借超过中国人民银行规定的拆借资金最长期限； （六）同业拆借资金余额超过中国人民银行核定的限额； （七）未按照中国人民银行的规定向同业拆借市场披露信息； （八）违反同业拆借市场规定的其他行为。"},{"i":42,"n":"第四十二条","txt":"商业银行有本办法第四十一条规定情形之一的，由中国人民银行或者其地市中心支行以上分支机构按照《中华人民共和国商业银行法》第七十六条的规定处罚。"},{"i":43,"n":"第四十三条","txt":"政策性银行、信用合作社、企业集团财务公司、信托公司、金融租赁公司有本办法第四十一条规定情形之一的，由中国人民银行或者其地市中心支行以上分支机构按照《金融违法行为处罚办法》第十七条的规定处罚。"},{"i":44,"n":"第四十四条","txt":"证券公司、保险公司、保险资产管理公司、金融资产管理公司、汽车金融公司有本办法第四十一条规定情形之一的，由中国人民银行或者其地市中心支行以上分支机构按照《中华人民共和国中国人民银行法》第四十六条规定处罚。"},{"i":45,"n":"第四十五条","txt":"对本办法第四十一条所列行为负有直接责任的金融机构董事、高级管理人员和其他直接责任人员，按照《中华人民共和国中国人民银行法》第四十六条的规定处罚。"},{"i":46,"n":"第四十六条","txt":"全国银行间同业拆借中心有下列行为之一的，由中国人民银行按照《中华人民共和国中国人民银行法》第四十六条的规定处罚： （一）不按照规定及时发布市场信息、发布虚假信息或泄露非公开信息； （二）交易系统和信息系统发生严重安全事故，对市场造成重大影响； （三）因不履行职责，给市场参与者造成严重损失或对市场造成重大影响； （四）为金融机构同业拆借违规行为提供便利； （五）不按照规定报送统计数据或未及时上报同业拆借市场异常情况； （六）违反同业拆借市场规定的其他行为。 对前款所列行为负有直接责任的高级管理人员和其他直接责任人员，按照《中华人民共和国中国人民银行法》第四十六条的规定处罚。"},{"i":47,"n":"第四十七条","txt":"为金融机构向同业拆借市场披露信息提供专业化服务的注册会计师、律师、信用评级机构等专业机构和人员出具的文件含有虚假记载、误导性陈述或重大遗漏的，不得再为同业拆借市场提供专业化服务。违反有关法律规定的，应当承担相应的法律责任。"},{"i":48,"n":"第四十八条","txt":"中国人民银行或者其地市中心支行以上分支机构对违反本办法的金融机构进行处罚后，应当通报有关监管部门。中国人民银行县（市）支行发现金融机构违反本办法的，应报告上一级分支机构，由其按照本办法规定进行处罚。"},{"i":49,"n":"第四十九条","txt":"中国人民银行及其地市中心支行以上分支机构对金融机构违反本办法的行为给予行政处罚的，应当遵守《中国人民银行行政处罚程序规定》的有关规定。"},{"i":50,"n":"第五十条","txt":"中国人民银行及其分支机构从事同业拆借市场监督管理的行为依法接受监督并承担法律责任。"},{"i":51,"n":"第五十一条","txt":"本办法所称中国人民银行省一级分支机构包括中国人民银行各分行、营业管理部、省会（首府）城市中心支行和副省级城市中心支行。"},{"i":52,"n":"第五十二条","txt":"金融机构进行外汇同业拆借由中国人民银行另行规定。"},{"i":53,"n":"第五十三条","txt":"本办法由中国人民银行负责解释，并由中国人民银行上海总部组织实施。"},{"i":54,"n":"第五十四条","txt":"本办法自2007年8月6日起施行，1990年3月8日中国人民银行发布的《同业拆借管理试行办法》同时废止。其他有关同业拆借的规定与本办法相抵触的，适用本办法的规定。"}],"shangyehuipiaochengduitiexianyuzaitiexianguanlibanf94769":[{"i":1,"n":"第一条","txt":"为了规范商业汇票承兑、贴现与再贴现业务，根据《中华人民共和国票据法》《中华人民共和国中国人民银行法》《中华人民共和国银行业监督管理法》《中华人民共和国商业银行法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称商业汇票是出票人签发的，委托付款人在见票时或者在指定日期无条件支付确定的金额给收款人或者持票人的票据，包括但不限于纸质或电子形式的银行承兑汇票、财务公司承兑汇票、商业承兑汇票等。"},{"i":3,"n":"第三条","txt":"电子商业汇票的出票、承兑、贴现、贴现前的背书、质押、保证、提示付款和追索等业务，应当通过人民银行认可的票据市场基础设施办理。供应链票据属于电子商业汇票。"},{"i":4,"n":"第四条","txt":"本办法所称承兑是指付款人承诺在商业汇票到期日无条件支付汇票金额的票据行为。"},{"i":5,"n":"第五条","txt":"本办法所称贴现是指持票人在商业汇票到期日前，贴付一定利息将票据转让至具有贷款业务资质机构的行为。持票人持有的票据应为依法合规取得，具有真实交易关系和债权债务关系，因税收、继承、赠与依法无偿取得票据的除外。"},{"i":6,"n":"第六条","txt":"本办法所称再贴现是指人民银行对金融机构持有的已贴现未到期商业汇票予以贴现的行为，是中央银行的一种货币政策工具。"},{"i":7,"n":"第七条","txt":"商业汇票的承兑、贴现和再贴现，应当遵循依法合规、公平自愿、诚信自律、风险自担的原则。"},{"i":8,"n":"第八条","txt":"银行承兑汇票是指银行和农村信用合作社承兑的商业汇票。银行主要包括政策性开发性银行、商业银行和农村合作银行。银行承兑汇票承兑人应在中华人民共和国境内依法设立，具有银保监会或其派出机构颁发的金融许可证，且业务范围包含票据承兑。"},{"i":9,"n":"第九条","txt":"财务公司承兑汇票是指企业集团财务公司承兑的商业汇票。财务公司承兑汇票承兑人应在中华人民共和国境内依法设立，具有银保监会或其派出机构颁发的金融许可证，且业务范围包含票据承兑。"},{"i":10,"n":"第十条","txt":"商业承兑汇票是由银行、农村信用合作社、财务公司以外的法人或非法人组织承兑的商业汇票。商业承兑汇票承兑人应为在中华人民共和国境内依法设立的法人及其分支机构和非法人组织。"},{"i":11,"n":"第十一条","txt":"银行、农村信用合作社、财务公司承兑人开展承兑业务时，应当严格审查出票人的真实交易关系和债权债务关系以及承兑风险，出票人应当具有良好资信。承兑的金额应当与真实交易关系和债权债务关系、承兑申请人的偿付能力相匹配。"},{"i":12,"n":"第十二条","txt":"银行、农村信用合作社、财务公司承兑的担保品应当严格管理。担保品为保证金的，保证金账户应当独立设置，不得挪用或随意提前支取保证金。"},{"i":13,"n":"第十三条","txt":"银行、农村信用合作社、财务公司承兑业务应当纳入存款类金融机构统一授信管理和风险管理框架。"},{"i":14,"n":"第十四条","txt":"商业汇票的贴现人应为在中华人民共和国境内依法设立的、具有贷款业务资质的法人及其分支机构。申请贴现的商业汇票持票人应为自然人、在中华人民共和国境内依法设立的法人及其分支机构和非法人组织。"},{"i":15,"n":"第十五条","txt":"申请贴现的持票人取得贴现票据应依法合规，与出票人或前手之间具有真实交易关系和债权债务关系，因税收、继承、赠与依法无偿取得票据的除外。"},{"i":16,"n":"第十六条","txt":"持票人申请贴现，须提交贴现申请、持票人背书的未到期商业汇票以及能够反映真实交易关系和债权债务关系的材料。"},{"i":17,"n":"第十七条","txt":"持票人可以通过票据经纪机构进行票据贴现询价和成交，贴现撮合交易应当通过人民银行认可的票据市场基础设施开展。"},{"i":18,"n":"第十八条","txt":"票据经纪机构应为市场信誉良好、票据业务活跃的金融机构。票据经纪机构应当具有独立的票据经纪部门和完善的内控管理机制，具有专门的经纪渠道，票据经纪业务与自营业务严格隔离。票据经纪机构应当具有专业的从业人员。"},{"i":19,"n":"第十九条","txt":"转贴现业务按照人民银行和银保监会票据交易有关规定执行。"},{"i":20,"n":"第二十条","txt":"办理商业汇票贴现业务的金融机构，可以申请办理再贴现业务。再贴现业务办理的条件、利率、期限和方式，按照人民银行有关规定执行。"},{"i":21,"n":"第二十一条","txt":"金融机构应当具备健全的票据业务管理制度和内部控制制度，审慎开展商业汇票承兑和贴现业务，采取有效措施防范市场风险、信用风险和操作风险。"},{"i":22,"n":"第二十二条","txt":"商业汇票的承兑人和贴现人应当具备良好的经营和财务状况，最近二年不得发生票据持续逾期或者未按规定披露信息的行为。商业汇票承兑人对承兑的票据应当具备到期付款的能力。"},{"i":23,"n":"第二十三条","txt":"财务公司承兑人所属的集团法人应当具备良好的经营和财务状况，最近二年不得发生票据持续逾期或者未按规定披露信息的行为，最近二年不得发生重大违法行为，以及其他严重损害市场主体合法权益或社会公共利益的行为。"},{"i":24,"n":"第二十四条","txt":"银行承兑汇票和财务公司承兑汇票的最高承兑余额不得超过该承兑人总资产的15%。银行承兑汇票和财务公司承兑汇票保证金余额不得超过该承兑人吸收存款规模的10%。人民银行和银保监会可以根据金融机构内控情况设置承兑余额与贷款余额比例上限等其他监管指标。"},{"i":25,"n":"第二十五条","txt":"商业汇票的付款期限应当与真实交易的履行期限相匹配，自出票日起至到期日止，最长不得超过6个月。"},{"i":26,"n":"第二十六条","txt":"商业汇票信息披露按照人民银行有关规定执行，应当遵循及时、真实、准确、完整的原则。"},{"i":27,"n":"第二十七条","txt":"商业承兑汇票承兑人和财务公司承兑汇票承兑人应当按照人民银行规定披露票据主要要素及信用信息。银行承兑汇票承兑人应当披露承兑人信用信息。"},{"i":28,"n":"第二十八条","txt":"贴现人办理商业汇票贴现的，应当按照人民银行规定核对票据披露信息，信息不存在或者记载事项与披露信息不一致的，不得为持票人办理贴现。"},{"i":29,"n":"第二十九条","txt":"商业汇票背书转让时，被背书人可以按照人民银行规定核对票据信息，信息不存在或者记载事项与披露信息不一致的，可以采取有效措施识别票据信息真伪及信用风险，加强风险防范。"},{"i":30,"n":"第三十条","txt":"商业汇票承兑人为非上市公司、在债券市场无信用评级的，鼓励商业汇票流通前由信用评级机构对承兑人进行主体信用评级，并按照人民银行有关规定披露相关信息。"},{"i":31,"n":"第三十一条","txt":"票据市场基础设施按人民银行有关要求对承兑人信息披露情况进行监测，承兑人存在票据持续逾期或披露信息存在虚假、遗漏、延迟的，票据市场基础设施应根据业务规则采取相应处置措施，并向人民银行报告。"},{"i":32,"n":"第三十二条","txt":"人民银行依法监测商业汇票承兑和贴现的运行情况，依法对票据市场进行管理。"},{"i":33,"n":"第三十三条","txt":"人民银行、银保监会按照法定职责对商业汇票的承兑、贴现、风险控制和信息披露进行监督管理。人民银行对再贴现进行监督管理。"},{"i":34,"n":"第三十四条","txt":"票据市场基础设施和办理商业汇票承兑、贴现、再贴现业务的主体，应当按规定和监管需要向人民银行和银保监会报送有关业务数据。"},{"i":35,"n":"第三十五条","txt":"银行承兑汇票、财务公司承兑汇票的承兑限额、付款期限超出规定的，由人民银行及其分支机构、银保监会及其派出机构对承兑人进行警告、通报批评，并由银保监会及其派出机构依法处以罚款。"},{"i":36,"n":"第三十六条","txt":"商业汇票承兑人最近二年发生票据持续逾期或者未按规定披露信息的，金融机构不得为其办理票据承兑、贴现、保证、质押等业务。"},{"i":37,"n":"第三十七条","txt":"金融机构为不具有真实交易关系和债权债务关系（因税收、继承、赠与依法无偿取得票据的除外）的出票人、持票人办理商业汇票承兑、贴现的，由银保监会及其派出机构根据不同情形依法采取暂停其票据业务等监管措施或者实施行政处罚；对直接负责的董事、高级管理人员和其他直接责任人员，依法追究相关责任。"},{"i":38,"n":"第三十八条","txt":"商业汇票出票人、持票人通过欺诈手段骗取金融机构承兑、贴现的，依法承担相应责任；涉嫌构成犯罪的，移送司法机关依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"未经依法许可或者违反国家金融管理规定，擅自从事票据贴现的，依照有关法律法规进行处置。"},{"i":40,"n":"第四十条","txt":"本办法由人民银行、银保监会负责解释。"},{"i":41,"n":"第四十一条","txt":"本办法第二十四条规定自2024年1月1日起实施。"},{"i":42,"n":"第四十二条","txt":"本办法自2023年1月1日起施行。《商业汇票承兑、贴现与再贴现管理暂行办法》（银发〔1997〕216号文印发）、《中国人民银行关于切实加强商业汇票承兑贴现和再贴现业务管理的通知》（银发〔2001〕236号）同时废止。"}],"shangyehuipiaochengduitiexianyuzaitiexianguanlizan2a10ed":[{"i":1,"n":"第一条","txt":"为了规范商业汇票承兑、贴现与再贴现业务操作，根据《中华人民共和国中国人民银行法》、《中华人民共和国商业银行法》、《中华人民共和国票据法》及有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称承兑系指付款人承诺在商业汇票到期日支付汇票金额的票据行为。本办法所称贴现系指商业汇票的持票人在汇票到期日前，为了取得资金贴付一定利息将票据权利转让给金融机构的票据行为，是金融机构向持票人融通资金的一种方式。 本办法所称转贴现系指金融机构为了取得资金，将未到期的已贴现商业汇票再以贴现方式向另一金融机构转让的票据行为，是金融机构间融通资金的一种方式。 本办法所称再贴现系指金融机构为了取得资金，将未到期的已贴现商业汇票再以贴现方式向中国人民银行转让的票据行为，是中央银行的一种货币政策工具。"},{"i":3,"n":"第三条","txt":"承兑、贴现、转贴现、再贴现的商业汇票，应以真实、合法的商品交易为基础。"},{"i":4,"n":"第四条","txt":"承兑、贴现、转贴现、再贴现等票据活动，应当遵循平等、自愿、公平和诚实信用的原则。再贴现应当有利于实现货币政策目标。"},{"i":5,"n":"第五条","txt":"承兑、贴现、转贴现的期限，最长不超过六个月。再贴现的期限，最长不超过四个月。"},{"i":6,"n":"第六条","txt":"再贴现利率由中国人民银行制定、发布与调整。贴现利率采取在再贴现利率基础上加百分点的方式生成，加点幅度由中国人民银行确定。转贴现利率由交易双方自主商定。"},{"i":7,"n":"第七条","txt":"为防范商业汇票业务风险，有关金融机构要健全商业汇票承兑、贴现、转贴现、再贴现的申请、审查、审批制度，依法进行业务操作。"},{"i":8,"n":"第八条","txt":"商业汇票承兑、贴现、转贴现、再贴现的处理手续，按照中国人民银行《支付结算会计核算手续》的有关规定办理。"},{"i":9,"n":"第九条","txt":"办理商业汇票承兑、贴现、转贴现、再贴现业务的金融机构，须健全有关业务统计和原始凭证档案管理制度，并按规定向其上级行和中国人民银行或其分支机构报送有关业务统计数据。"},{"i":10,"n":"第十条","txt":"向银行申请承兑的商业汇票出票人，必须具备下列条件： 一、为企业法人和其他经济组织，并依法从事经营活动； 二、资信状况良好，具有支付汇票金额的资金来源； 三、在承兑银行开立存款帐户。 商业汇票的出票人应首先向其主办银行申请承兑。"},{"i":11,"n":"第十一条","txt":"商业银行、政策性银行及经其授权或转授权的银行分支机构可承兑商业汇票。 非银行金融机构、不具有贷款权限或未经其上级行承兑授权、转授权的银行分支机构，不得承兑商业汇票。"},{"i":12,"n":"第十二条","txt":"承兑商业汇票的银行，必须具备下列条件： 一、具有承兑商业汇票的资格； 二、与出票人建立委托付款关系； 三、有支付汇票金额的资金来源。"},{"i":13,"n":"第十三条","txt":"银行承兑商业汇票时，应考核承兑申请人的资信情况，必要时可依法要求承兑申请人提供担保。"},{"i":14,"n":"第十四条","txt":"承兑人按中国人民银行的规定，向承兑申请人收取承兑手续费。"},{"i":15,"n":"第十五条","txt":"各商业银行、政策性银行应对其分支机构核定可承兑总量或比例，实行承兑授权管理，并依法承担承兑风险。银行分支机构依据其上级行的承兑授权，在核定的可承兑总量或比例内承兑商业汇票。"},{"i":16,"n":"第十六条","txt":"中国人民银行一级分行对辖内城市合作银行、农村合作银行承兑商业汇票实行总量控制。上列商业银行要在当地人民银行核定的可承兑总量或比例内承兑商业汇票。"},{"i":17,"n":"第十七条","txt":"中国人民银行各分支行应督促辖内银行或银行分支机构完善商业汇票承兑业务管理和风险防范制度，监控辖内承兑总量与风险度。"},{"i":18,"n":"第十八条","txt":"向金融机构申请票据贴现的商业汇票持票人，必须具备下列条件： 一、为企业法人和其他经济组织，并依法从事经营活动； 二、与出票人或其前手之间具有真实的商品交易关系； 三、在申请贴现的金融机构开立存款帐户。"},{"i":19,"n":"第十九条","txt":"持票人申请贴现时，须提交贴现申请书，经其背书的未到期商业汇票，持票人与出票人或其前手之间的增值税发票和商品交易合同复印件。"},{"i":20,"n":"第二十条","txt":"办理票据贴现业务的机构，是经中国人民银行批准经营贷款业务的金融机构（以下简称贴现人）。"},{"i":21,"n":"第二十一条","txt":"贴现人选择贴现票据应当遵循效益性、安全性和流动性的原则，贴现资金投向应符合国家产业政策和信贷政策。"},{"i":22,"n":"第二十二条","txt":"贴现人应将贴现、转贴现纳入其信贷总量，并在存贷比例内考核。"},{"i":23,"n":"第二十三条","txt":"贴现人对贴现申请人提交的商业汇票，应按规定向承兑人以书面方式查询。承兑人须按照中国人民银行的有关规定查复贴现人。"},{"i":24,"n":"第二十四条","txt":"各商业银行、政策性银行应当运用贴现、转贴现方式增加票据资产，调整信贷结构。"},{"i":25,"n":"第二十五条","txt":"再贴现的对象是在中国人民银行及其分支机构开立存款帐户的商业银行、政策性银行及其分支机构。 对非银行金融机构再贴现，须经中国人民银行总行批准。"},{"i":26,"n":"第二十六条","txt":"再贴现的操作体系： 一、中国人民银行总行设立再贴现窗口，受理、审查、审批各银行总行的再贴现申请，并经办有关的再贴现业务（以下简称再贴现窗口）。 二、中国人民银行各一级分行和计划单列城市分行设立授权再贴现窗口，受理、审查、并在总行下达的再贴现限额之内审批辖内银行及其分支机构的再贴现申请，经办有关的再贴现业务（以下简称授权窗口）。 三、授权窗口认为必要时可对辖内一部分二级分行实行再贴现转授权（以下简称转授权窗口），转授权窗口的权限由授权窗口规定。 四、中国人民银行县级支行和未被转授权的二级分行，可受理、审查辖内银行及其分支机构的再贴现申请，并提出审批建议，在报经授权窗口或转授权窗口审批后，经办有关的再贴现业务。"},{"i":27,"n":"第二十七条","txt":"中国人民银行根据金融宏观调控和结构调整的需要，不定期公布再贴现优先支持的行业、企业和产品目录。各授权窗口须据此选择再贴现票据，安排再贴现资金投向，并对有商业汇票基础、业务操作规范的金融机构和跨地区、跨系统的贴现票据优先办理再贴现。"},{"i":28,"n":"第二十八条","txt":"持票人申请再贴现时，须提交贴现申请人与出票人或其前手之间的增值税发票。"},{"i":29,"n":"第二十九条","txt":"中国人民银行对各授权窗口的再贴现操作效果实行量化考核： 一、总量比例：按发生额计算，再贴现与贴现、商业汇票三者之比不高于1：2：4。 二、期限比例：累计三个月以内（含三个月）的再贴现不低于再贴现总量的70％。 三、投向比例：对国家重点产业、行业和产品的再贴现不低于再贴现总量的70％；对国有独资商业银行的再贴现不低于再贴现总量的80％。"},{"i":30,"n":"第三十条","txt":"中国人民银行对各授权窗口的再贴现实行总量控制，并根据金融宏观调控的需要适时调增或调减各授权窗口的再贴现限额。各授权窗口对再贴现限额实行集中管理和统一调度，不得逐级分配再贴现限额。"},{"i":31,"n":"第三十一条","txt":"承兑、贴现申请人有下列情形之一，承兑人和贴现人暂停对其办理商业汇票承兑和贴现： 一、未支付或未足额支付其签发商业汇票票面金额的； 二、未以商品交易为基础签发商业汇票的； 三、以非法手段骗取金融机构承兑、贴现的。"},{"i":32,"n":"第三十二条","txt":"金融机构有下列情形之一，同级人民银行暂停对其办理再贴现，情节严重的，由其上级行责令其暂停承兑、贴现业务： 一、对未以商品交易为基础的商业汇票办理承兑、贴现的； 二、将未以商品交易为基础的商业汇票用于申请再贴现的； 三、越权承兑商业汇票的； 四、未按规定办理票据查复或查复内容不真实的。"},{"i":33,"n":"第三十三条","txt":"授权窗口或转授权窗口有下列情形之一，中国人民银行上级行给予通报批评，情节严重的，暂停其再贴现授权： 一、越权办理再贴现的； 二、逐级分配再贴现限额，执行限额集中管理、统一调度原则不力的； 三、对未以商品交易为基础的商业汇票办理再贴现的； 四、再贴现投向不合理的。"},{"i":34,"n":"第三十四条","txt":"承兑、贴现申请人采取欺诈手段骗取金融机构承兑、贴现，情节严重并构成犯罪的，由司法机关依法追究其刑事责任。"},{"i":35,"n":"第三十五条","txt":"对未以商品交易为基础的商业汇票办理承兑、贴现、再贴现，并造成信贷资金损失的，分别由中国人民银行上级行、有关商业银行上级行对有关责任人给予纪律处分，情节严重并构成犯罪的，由司法机关依法追究其刑事责任。"},{"i":36,"n":"第三十六条","txt":"经中国人民银行核准经营人民币存款、贷款和结算业务的外资银行或其分支机构适用本办法。"},{"i":37,"n":"第三十七条","txt":"经中国人民银行核准经营有关商业汇票业务的非银行金融机构，适用本办法有关规定。"},{"i":38,"n":"第三十八条","txt":"各授权窗口、商业银行、政策性银行要根据本办法制定实施细则，并报中国人民银行备案。"},{"i":39,"n":"第三十九条","txt":"本办法由中国人民银行负责解释。"},{"i":40,"n":"第四十条","txt":"本办法自颁布之日起施行。"}],"shangyeyinhangxinyongshedailiguokuyewuguanlibanfa":[{"i":1,"n":"第一条","txt":"为进一步加强对商业银行代理国库支库和商业银行、信用社办理国库经收处业务的监督和管理，规范国库代理和国库经收业务，确保国库资金安全，根据《中华人民共和国中国人民银行法》、《中华人民共和国国家金库条例》和《金融违法行为处罚办法》等法规有关国库管理的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"人民银行可以按照机构分布情况委托商业银行代理国库支库(以下简称“代理支库”)业务。经收预算收入的商业银行分支机构和信用社均为国库经收处。"},{"i":3,"n":"第三条","txt":"人民银行依法对商业银行代理支库和商业银行、信用社国库经收处所办国库业务实施垂直管理。"},{"i":4,"n":"第四条","txt":"代理支库机构的设置与财政管理体制相适应，原则上一级财政设立一级国库。 本办法所称商业银行包括国有独资商业银行、股份制商业银行和城市商业银行；信用社包括城市信用社和农村信用社。"},{"i":5,"n":"第五条","txt":"代理支库业务的商业银行(以下简称“代理行”)必须严格按国库业务的各项规定，加强国库业务管理，准确、及时地办理国库业务；负责对辖内各分支机构和其他金融机构办理的乡(镇)国库及国库经收业务进行监督、管理、检查和指导。"},{"i":6,"n":"第六条","txt":"商业银行代理支库和商业银行、信用社办理国库经收处业务的会计核算手续，按照《中国人民银行关于国库会计核算管理与操作的规定》办理。"},{"i":7,"n":"第七条","txt":"国库经收处必须准确、及时地办理各项预算收入的收纳，完整地将预算收入划转到指定收款国库。"},{"i":8,"n":"第八条","txt":"国库经收处必须接受上级国库及当地代理支库和乡(镇)国库的监督、管理、检查和指导，不得以任何理由拒绝。"},{"i":9,"n":"第九条","txt":"国库经收处应认真履行国库经收职责。在收纳预算收入时，国库经收处应对缴款书的以下内容进行认真审核： (一)预算级次、预算科目、征收机关和指定收款国库等要素是否填写清楚； (二)大小写金额是否相符，字迹有无涂改； (三)纳税人(包括缴款单位或个人)名称、账号、开户银行填写是否正确、齐全； (四)印章是否齐全、清晰；与预留印鉴是否相符； (五)纳税人存款账户是否有足够的余额。纳税人以现金缴税时，应核对票款是否相符。 对不符合要求的缴款书，应拒绝受理。"},{"i":10,"n":"第十条","txt":"国库经收处不得无理拒收纳税人缴纳或征收机关负责组织征收的预算收入。"},{"i":11,"n":"第十一条","txt":"国库经收处在受理缴款书后，必须及时办理转账，不得无故压票，在各联次上加盖收(转)讫业务印章的日期必须相同。"},{"i":12,"n":"第十二条","txt":"凡代理国库业务和办理国库经收业务的商业银行、信用社均应设立“待结算财政款项”一级科目。国库经收处收纳的预算收入，一律使用“待结算财政款项”科目下的“待报解预算收入”专户进行核算，不得转入其他科目。"},{"i":13,"n":"第十三条","txt":"国库经收处收纳的预算收入，应在收纳当日办理报解入库手续，不得延解、占压和挪用；如当日确实不能报解的，必须在下一个工作日报解。"},{"i":14,"n":"第十四条","txt":"国库经收处收纳的预算收入属代收性质，不是正式入库。国库经收处不得办理预算收入退付。 国库经收处收纳的预算收入在未上划以前，如发现错误，应将缴款书退征收机关或纳税人更正，重新办理缴纳手续。"},{"i":15,"n":"第十五条","txt":"代理支库的商业银行，以及办理国库经收业务的商业银行和信用社不得违规为征收机关开立预算收入过渡账户。违反规定为征收机关设立过渡账户的，人民银行有权责令其撤销过渡账户，并将预算收入在过渡账户中滋生的利息及罚没款项缴入当地中央国库；预算收入资金按预算级次缴入相关国库。"},{"i":16,"n":"第十六条","txt":"纳税人缴纳小额税款，凡在商业银行开有存款账户的，应直接通过银行办理转账缴税；未开立存款账户、用现金缴税的，各商业银行不得以任何理由拒收。"},{"i":17,"n":"第十七条","txt":"代理行应按照《中华人民共和国国家金库条例》及其《中华人民共和国国家金库条例实施细则》的规定，设立专门的国库工作机构。 代理支库年业务量在30万笔以上或年预算收入3亿元以上的代理行，必须设立国库科(股)专门办理国库业务。业务量较小、预算收入较少的代理行，经上一级人民银行批准，可设立国库专柜办理国库业务，但至少应配备3名以上人员专职办理国库业务。"},{"i":18,"n":"第十八条","txt":"京、津、沪、渝等大城市中，代理支库业务量大且又集中于一家或几家代理行的，人民银行可以要求这些代理行的市分行专门设立机构，配备专门人员，负责对下属支行代理支库业务进行管理。"},{"i":19,"n":"第十九条","txt":"代理支库的国库主任由代理行行长兼任，副主任由分管国库工作的副行长兼任。"},{"i":20,"n":"第二十条","txt":"代理行应在现行国库法规和规章框架下，制定代理支库业务的内部规章制度，并报批准其办理代理支库业务的人民银行审查、备案。"},{"i":21,"n":"第二十一条","txt":"代理支库应设置记账、复核、事后监督和国库会计主管等岗位，以确保准确、及时、完整地办理预算收入收纳、划分、报解、入库、更正、退付和预算支出的拨付等国库业务。"},{"i":22,"n":"第二十二条","txt":"代理行应配备政治素质好、具有高中或中专以上学历、持有国家颁发的会计从业资格证书的人员，经国库专业知识培训合格后，方可正式上岗办理国库业务。国库业务人员应保持相对稳定，人员变动情况应报人民银行备案。"},{"i":23,"n":"第二十三条","txt":"代理支库的负责人要以身作则，严格遵守各项规章制度，敢抓敢管，杜绝风险隐患。"},{"i":24,"n":"第二十四条","txt":"代理支库的基本职责如下： (一)根据政府预算收入科目以及现行的财政管理体制确定的预算收入级次、分成和留解比例，准确、及时、完整地办理各级预算收入的收纳、划分、报解、入库； (二)按照《中华人民共和国国家金库条例》及其《中华人民共和国国家金库条例实施细则》等法规和规章的规定，为同级财政机关开立预算存款账户。根据同级财政机关填发的预算拨款凭证及时办理同级预算支出的拨付； (三)按照国家政策、法规规定的退库范围和审批程序，凭财政机关或其授权单位开具的预算收入退还凭证，审核办理预算收入的退付； (四)对各级预算收入和本级预算支出进行会计账务核算；按照人民银行的要求，定期向上一级国库和同级财政、征收机关报送或提供有关报表；定期与财政、征收机关对账签证，保证数字准确一致； (五)协助同级财政、征收机关督促纳税人及时缴纳预算收入，组织预算收入及时入库。根据征收机关开具的缴款凭证核收滞纳金。按照国家税"},{"i":25,"n":"第二十五条","txt":"代理支库的主要权限如下： (一)有权督促检查辖区内各乡(镇)国库和国库经收处办理国库业务的情况，以及征收机关所收预算收入款项是否按规定及时、足额缴入指定收款国库； (二)对于任何单位或个人擅自变更财政机关规定的各级预算收入划分办法、范围和分成留解比例，以及随意调整库款账户之间存款余额的，有权拒绝执行； (三)对不符合国家政策、法规规定的范围、项目和审批程序，要求办理预算收入退付的，有权拒绝办理； (四)对违反有关规定，要求办理预算收入汇总更正的，有权拒绝受理； (五)对违反财经制度规定的同级财政存款的开户和预算资金的支拨，有权拒绝拨付； (六)对不符合规定的凭证，有权拒绝受理； (七)对任何单位和个人强令办理违反国家规定的事项，有权拒绝执行并及时向上级国库报告。"},{"i":26,"n":"第二十六条","txt":"同级财政预算资金应存入同级代理支库为财政开立的地方财政预算存款账户，所有的预算支出均通过此账户拨付。"},{"i":27,"n":"第二十七条","txt":"代理支库办理的拨款、退付业务实行三级审核制度。代理支库的经办人员、国库部门负责人(或国库会计主管)和国库主任，按照规定的审核权限，履行审核手续，及时、准确地办理拨款、退付业务。"},{"i":28,"n":"第二十八条","txt":"代理支库应加强对同级财政预算拨款的监督和管理，发现有下列情况之一的，一律拒绝受理： (一)凭证要素不全的； (二)擅自涂改凭证的； (三)大小写金额不符的； (四)小写金额前不写人民币符号的； (五)大写金额与“人民币”字样间留有空白的； (六)前后联次填写内容不一致的； (七)拨款金额超过库存余额的； (八)“预算拨款凭证”第一联及信、电汇凭证的第二联未加盖拨款专用印鉴，或所盖印鉴与预留印鉴不符的； (九)拨款用途违反财经制度规定的； (十)拨往非预算单位又无正式文件或书面说明的； (十一)超预算的； (十二)预算级次有误或所填科目与政府预算收支科目不符的。"},{"i":29,"n":"第二十九条","txt":"代理支库办理预算资金拨付，应于接到拨付指令当日及时办理，不得延误、积压；如当日确实不能办理的，最迟在下一个工作日办理。如遇特殊情况不能在规定时间内拨付的，必须向国库主任(副主任)报告，并在“柜面监督登记簿”的“其他事项”栏中注明，由国库主任(副主任)签字。"},{"i":30,"n":"第三十条","txt":"代理支库应加强对各级预算收入退付的监督和管理。除按规定加强对退库申请书和预算收入退还书的要素进行审核外，有以下情况之一的，也不予受理，并将有关凭证退还签发机关： (一)地方政府、财政部门或其他未经财政部授权的机构，要求国库办理中央预算收入、中央与地方共享收入退库的； (二)未经上级财政部门授权的机构，要求国库办理上级地方预算收入或共享收入退库的； (三)退库款项退给非退库申请单位或申请人的； (四)口头或电话通知要求国库办理退库的； (五)要求国库办理退库，但拒不提供有关文件或依据、退库申请书和原缴款凭证复印件的； (六)超计划又无追加文件要求退库的； (七)其他违反规定要求国库办理退库的。"},{"i":31,"n":"第三十一条","txt":"代理支库除做好自身业务工作外，还应持上级人民银行核发的“中国人民银行国库业务检查证”定期或不定期检查、辅导辖区内各分支机构和其他金融机构办理乡(镇)国库和国库经收处执行国库制度的情况。并配合上级国库部门对辖区内在国库业务中发生的重大问题进行核查。 代理支库应将检查辖区乡(镇)国库和国库经收处办理国库业务情况，每半年汇总一次，分别在当年7月31日和次年1月31日前报上一级人民银行。人民银行每年对代理支库检查过的乡(镇)国库和国库经收处进行抽查。"},{"i":32,"n":"第三十二条","txt":"代理支库原则上应设在国有独资商业银行。未设国有独资商业银行分支机构的地区，经人民银行商当地财政部门选择审定，代理支库也可设在其他商业银行。"},{"i":33,"n":"第三十三条","txt":"代理支库业务的商业银行，必须严格执行《中华人民共和国国家金库条例》及其《中华人民共和国国家金库条例实施细则》和《中国人民银行关于国库会计核算管理与操作的规定》等法规、制度，认真办理各项国库业务。"},{"i":34,"n":"第三十四条","txt":"代理支库名称定为：中华人民共和国国家金库××县(市)支库(代理)或中华人民共和国国家金库××市××区支库(代理)。"},{"i":35,"n":"第三十五条","txt":"代理支库的设立条件。代理支库的金融机构必须是经过人民银行批准设立，具有良好的信誉，较好的经营业绩，配备专职人员，内控机制健全，资金结算渠道畅通，核算工具先进，认真履行国库职责，并能按规定设置国库工作机构的金融机构。"},{"i":36,"n":"第三十六条","txt":"设立代理支库的审批权限。商业银行分支机构代理支库的，由各省、自治区、直辖市及计划单列市分库商同级财政部门后，由分库审批。已经办理代理支库业务的商业银行必须补办审批手续。"},{"i":37,"n":"第三十七条","txt":"代理支库的审批程序。凡要求代理支库的商业银行，应向上一级人民银行提出书面申请。上一级人民银行审议后，附书面审议意见报分库。 代理申请书中必须包含本商业银行对代理支库业务的机构、岗位设置和人员配备情况，对办理国库业务的承诺和内控管理措施等内容，并必须提供以下书面资料： (一)人民银行颁发的经营金融业务许可证复印件一份； (二)上两年度的资产负债表和损益表复印件各一份； (三)相关的内部管理制度和资金结算情况报告； (四)金融机构负责人、拟设国库机构负责人或办理国库业务负责人、主要经办人员情况简介。 分库对上述材料审查后，认为符合代理支库条件的，由分库向商业银行颁发“代理支库资格证书”，并与其签定“代理支库业务协议书”，明确商业银行代理支库业务的有关问题，具体填制内容由各分库确定。分库将上述审批资料按代理行归档保存。 商业银行凭“代理支库资格证书”和“代理支库业务协议书”办理当年代理支库业"},{"i":38,"n":"第三十八条","txt":"代理支库的年审。每年年度终了后，代理行必须在新年度一月底之前以该行正式文件形式，向上一级人民银行报告上年度的代理情况。收到代理行提交的年审材料后，人民银行必须在十个工作日内完成审查，并提出对代理行的年审意见。 年审合格的，上一级人民银行批准代理行继续代理国库支库业务的，经上一级人民银行颁发新的年度代理资格证书，并与其签定新年度代理支库业务协议书后，代理行方可继续办理国库业务。年审期间，不论代理行年审是否合格，在人民银行下发新年度代理资格证书前，其支库业务仍由原代理行办理。 年审报告的内容主要包括： (一)年国库业务量； (二)年预算收、支情况； (三)年内国库业务人员和主管国库工作的各级领导人员及变动情况； (四)年内自身国库工作开展情况； (五)年内对辖区内乡(镇)国库或国库经收处的检查情况； (六)同级财政、征收机关对代理行办理国库业务的书面意见； (七)年内审计、检查部门的审计、"},{"i":39,"n":"第三十九条","txt":"代理支库有下列情况之一的，即为年审不合格： (一)机构不健全、人员不到位、内部管理不严、制度不落实，存在风险隐患的； (二)发生国库资金挪用、盗窃案件的； (三)存在严重的税款延解、占压现象的； (四)对财政、税务等部门签发的拨款、退库凭证审核不严，造成资金损失，有连带责任的； (五)国库业务核算质量低，屡次发生差错又无改进措施或改进无成效的； (六)对自身或辖区内乡(镇)国库和国库经收处发生的重大问题隐匿不报的。"},{"i":40,"n":"第四十条","txt":"上一级人民银行建立“代理支库年审登记表”，将代理支库上报的年审资料，按年度、附“代理支库年审登记表”后装订存档。并将代理支库的年审情况和违纪、违规、违法情况送人民银行监管部门，记入人民银行金融监管档案和金融机构高级管理人员任职资格档案。"},{"i":41,"n":"第四十一条","txt":"代理支库在业务检查中，发现辖区内乡(镇)国库和国库经收处有占压、挪用税款等违规、违法问题，应及时向上一级人民银行报告，上一级人民银行核实后，视情节轻重，按有关法规、制度的规定，对有关商业银行、信用社进行处罚。行政处罚决定书由上一级人民银行下达。有关违规行为的处罚标准如下： (一)商业银行、信用社占压、挪用所收纳税款的，按《金融违法行为处罚办法》予以处罚； (二)国库经收处不按规定设置“待结算财政款项”科目核算其经收税款的，视情节轻重，处1000元以上、5000元以下的罚款； (三)国库经收处将经收税款转入“待结算财政款项”以外其他科目或账户的，视同挪用预算收入处理。并视情节轻重，处5000元以上、20000元以下的罚款； (四)国库经收处拒收纳税人缴纳的现金税款或纳税人存款账户余额充足而拒绝划转税款的，视情节轻重，处5000元以上、20000元以下的罚款； (五)乡(镇)国库和国库经收"},{"i":42,"n":"第四十二条","txt":"代理支库在业务检查中，发现辖区内乡(镇)国库或国库经收处有占压、挪用税款等违法、违规问题而隐匿不报的，除对乡(镇)国库或国库经收处按前条所列标准予以处罚外，对代理行要视情节轻重处5000元以上、20000元以下的罚款，直至取消其代理资格。"},{"i":43,"n":"第四十三条","txt":"对代理行在办理国库业务中的违法、违规问题，由上一级人民银行按本办法第四十一条所列处罚标准进行处罚。 凡有以下情况之一者，代理行的上级行应要求代理行限期改正、并对直接责任人员予以纪律处分。人民银行可对代理行提出警告、并要求限期整改，情节严重的，可撤销其代理资格，并依法追究直接责任人员和主管领导的责任： (一)未按规定切实履行国库职责、发挥国库在预算执行中的促进、反映、监督作用的； (二)违反国库有关规章制度，影响国库资金安全的； (三)利用代理支库业务之便，截留、占压、挪用、拖欠、转存国库资金的； (四)擅自为征收机关开立预算收入过渡账户或将预算收入存入征收机关在该行设立的经费账户或其他账户的； (五)其他违反国库规定的行为。"},{"i":44,"n":"第四十四条","txt":"代理支库的代办业务费，按受理各种原始凭证的笔数，以适当标准计付。具体计付标准和拨付办法由上一级人民银行与当地财政部门商定后，由当地财政拨付至人民银行，再由人民银行拨付至代理行。 商业银行经收预算收入计付代办业务费的标准、办法，由基层人民银行商当地财政部门确定。"},{"i":45,"n":"第四十五条","txt":"代办业务费主要用于代理行办理国库业务的机器、设备的配置，以及代办人员的培训、奖励等费用的支出。"},{"i":46,"n":"第四十六条","txt":"本办法中涉及的罚款收入，应按规定就地缴入中央国库。"},{"i":47,"n":"第四十七条","txt":"代理支库应按规范名称统一对外挂牌。其代理支库业务所用印章，由各分库按规定样式统一刻制。"},{"i":48,"n":"第四十八条","txt":"代理支库资格证书由中国人民银行统一印制，各省、自治区、直辖市及计划单列市分库领取、下发。代理支库业务协议书由各分库印制，辖区内统一。"},{"i":49,"n":"第四十九条","txt":"本办法自2001年2月1日起执行。1989年12月27日中国人民银行与中国工商银行、中国农业银行、中国银行、中国建设银行联合发布的《专业银行办理国库业务管理办法》同时废止。"}],"shangyeyinhangxinyongshedailizhikuyewushenpiguanli214325":[{"i":1,"n":"第一条","txt":"为规范中国人民银行分支机构代理支库业务审批行为，保障国库资金安全，根据《中华人民共和国行政许可法》、《中华人民共和国中国人民银行法》、《中华人民共和国预算法实施条例》、《中华人民共和国国家金库条例》、《中国人民银行行政许可实施办法》（中国人民银行令〔2020〕第1号发布）等法律、法规和规章，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称代理支库业务审批，是指中国人民银行分支机构根据商业银行、信用社的申请，经依法审查，准予其代理支库业务的行为。 本办法所称代理支库，是指经中国人民银行分支机构审批，由商业银行、信用社代理的中华人民共和国国家金库支库。"},{"i":3,"n":"第三条","txt":"中国人民银行分支机构对代理支库业务的审批，遵循公开、公平、公正、便利、高效的原则。"},{"i":4,"n":"第四条","txt":"商业银行、信用社申请代理支库业务的，由中国人民银行地市分行（以下统称初审行）受理与初步审查，中国人民银行各省级分行、计划单列市分行（以下统称审批行）负责审批。未设中国人民银行地市分行的，审批行同时为初审行。"},{"i":5,"n":"第五条","txt":"中国人民银行分支机构的国库部门具体承办代理支库业务审批事项，负责代理支库业务审批申请材料受理、相关文书制作送达、信息公开等工作。"},{"i":6,"n":"第六条","txt":"申请人原则上为拟具体承办代理支库业务的商业银行、信用社或其分支机构。"},{"i":7,"n":"第七条","txt":"未经中国人民银行分支机构批准，任何商业银行、信用社不得开展代理支库业务。"},{"i":8,"n":"第八条","txt":"初审行依法制作代理支库业务审批事项服务指南，并在办公场所、官方网站公示。服务指南应当明确代理支库业务审批相关事项信息、提交材料目录和示范文本等。"},{"i":9,"n":"第九条","txt":"初审行辖内新设代理支库，应当书面报经审批行同意后，开展代理支库业务审批初审工作。"},{"i":10,"n":"第十条","txt":"初审行应当以公告形式向社会公布辖内集中接收代理支库业务申请材料的时间，相关公告发布时间不得晚于集中接收申请材料起始日前10日。"},{"i":11,"n":"第十一条","txt":"申请人应当具备以下条件： （一）依法持有金融许可证和营业执照。 （二）资产负债状况良好，具有较好的经营业绩和较强的风险控制能力。 （三）内部管理规范，内控制度健全，具有严格的操作规程和保密措施。 （四）所在地域的机构网点数量和分布能够满足代理支库业务的需要。 （五）具备代理支库业务所需的办公场所，承诺获准代理后依据中国人民银行国库管理各项要求，设立或明确办理国库业务的部门，并配备足额、合格的国库业务人员。 （六）具备代理支库业务所需的技术条件，相关业务系统和内部网络安全、高效，能够全面、准确地记录并反映所代理的业务信息；承诺获准代理后，及时接入并使用中国人民银行统一规范的数据系统。 （七）资金结算渠道畅通，确保资金收支运行安全、稳定、及时、可靠。 （八）经营合规稳健，申请时前2年内无重大违法违规行为、被采取限制业务活动、被责令停业整顿、被接管等影响代理支库业务审批的事项。"},{"i":12,"n":"第十二条","txt":"申请人应当按照代理支库业务审批事项服务指南和有关要求提交申请材料，并对申请材料内容的真实性负责。申请材料包括： （一）申请材料目录。 （二）代理支库业务申请书（见附件1），内容应当包括机构的基本情况、岗位设置及人员配备情况、内控管理情况、信息系统建设和资金结算渠道情况、既往代理国库相关业务开展情况、申请时前2年内代理国库相关业务的违法违规行为发生情况及整改情况、服务承诺等。 （三）申请人法定代表人或主要负责人有效身份证件，如委托代理人提出申请的，还需提供授权委托书和被委托人有效身份证件。 （四）最近2个年度金融监管部门、会计师事务所的监管通报、审计报告等。 （五）中国人民银行及其分支机构要求提供的其他材料。 上述申请资料如为复印件，应当加盖单位公章。其中涉及前款第四项内容，应当按照证明事项告知承诺制相关要求办理。"},{"i":13,"n":"第十三条","txt":"代理支库业务审批前，初审行应当以适当方式与有关代理支库相对应的财政部门沟通协商相关事项。 沟通协商后，由初审行和审批行依法开展行政许可工作。"},{"i":14,"n":"第十四条","txt":"初审行应当成立代理支库业务审批评审组，评审组组长由本行主要负责人或分管国库工作的负责人担任，其他成员根据代理支库业务审批工作需要，选择国库和其他相关部门具有相应专业能力的正式人员担任。评审组成员不少于7人，且应当为单数。"},{"i":15,"n":"第十五条","txt":"初审行组织评审组按照评审指标对申请材料进行评审。"},{"i":16,"n":"第十六条","txt":"中国人民银行国库局负责具体评审指标、评审方法与评审标准的制定，分支机构国库部门可结合本地实际情况进行补充细化。 评审指标主要包括资金安全性、流动性、效益性等方面的金融管理部门综合评价结果，网点覆盖情况，内控管理情况，信息系统建设情况，机构设置及人员配备情况，代理国库相关业务开展情况及代理支库业务年审情况，业务安全综合情况，申请材料质量等。"},{"i":17,"n":"第十七条","txt":"初审行根据评审组评审结果拟定初审意见，连同申请材料以行发文形式报送审批行。"},{"i":18,"n":"第十八条","txt":"审批行应当对初审行审查程序的规范性和初审意见的公正性等情况进行审核。对初审行未按本办法规定的程序进行评定，或存在其他违反法律、法规和规章制度的行为的，审批行应当要求初审行进行解释或修正。 审批行审查后，作出准予行政许可或不予行政许可决定、制作决定书并依法公布，同时将准予行政许可决定书的复印件报总行备案。"},{"i":19,"n":"第十九条","txt":"中国人民银行分支机构应当自受理申请之日起20日内，作出准予行政许可或不予行政许可决定。在规定期限内不能作出审批决定的，经审批行主要负责人批准，可延长10日，同时将延长期限理由告知申请人。"},{"i":20,"n":"第二十条","txt":"经准予代理支库业务的商业银行、信用社（以下统称代理银行）凭准予行政许可决定书，与初审行签订“代理支库业务协议书”。协议书应当明确双方的权利义务、服务承诺等。"},{"i":21,"n":"第二十一条","txt":"中国人民银行及其分支机构依法履行对商业银行、信用社代理支库业务的监督管理和检查职责。"},{"i":22,"n":"第二十二条","txt":"代理银行应当按照国库管理各项制度要求组织开展代理支库工作，接受中国人民银行及其分支机构的监督管理和检查，配合开展年审，并依法履行下列职责： （一）根据业务需要，建立健全内控管理机制和风险防范体系，建立并完善代理支库业务各项制度，并及时报送初审行国库部门。 （二）及时、准确、安全、规范办理预算资金的收纳、划分、留解、退付、拨付等国库会计核算业务，不断提升电子化业务办理水平。 （三）履行国库其他职责，防范国库资金风险，维护国库资金安全；发现辖内代理乡（镇）国库、国库经收处、代理国库集中收付业务等其他代理国库相关业务存在违规行为的，应当及时报告初审行国库部门。 （四）按照国库业务管理要求，将代理支库业务相关的数据、信息和材料等及时报送初审行国库部门。"},{"i":23,"n":"第二十三条","txt":"每年年终，初审行应当对代理支库业务开展年审。"},{"i":24,"n":"第二十四条","txt":"代理银行应当在下一年度1月15日前，以正式文件向初审行国库部门报告上一年度代理支库业务办理情况，同时填报代理支库业务年审登记表（见附件2）。报告的主要内容包括： （一）工作开展情况，包括国库业务量、预算收支、系统建设等情况。 （二）国库工作机构设置，国库管理人员和业务人员配备、变动情况。 （三）风险控制情况，包括内控制度建设及执行，内部、外部审计等情况。 （四）上一年度代理国库相关业务违法违规行为发生情况及整改情况。 （五）中国人民银行及其分支机构要求报告的其他情况。"},{"i":25,"n":"第二十五条","txt":"初审行国库部门在收到代理银行提交的代理支库年审材料后，应当核实年审材料，并结合下列情况进行年审： （一）现场或非现场监督、执法检查情况。 （二）日常管理情况。 （三）财政、税务、海关等相关部门对代理银行履职服务情况的反馈等。"},{"i":26,"n":"第二十六条","txt":"初审行国库部门应当在收到代理银行提交的年审材料之日起20日内，作出“合格”或“不合格”的年审结论，并告知代理银行。确因材料核实等需要延期作出年审结论的，经初审行负责人批准，可延长10日。 对年审结论为“不合格”的，初审行应当督促代理银行限时整改到位并提交整改报告。 初审行国库部门应当将加盖本行公章的代理支库业务年审登记表报送审批行国库部门备案。"},{"i":27,"n":"第二十七条","txt":"代理银行有下列情况之一的，即为年审不合格： （一）机构设置不健全、人员配备不到位、内部管理混乱、国库相关制度及国家重大财税政策落实不到位，存在较大风险隐患的。 （二）挪用、盗窃国库资金的。 （三）严重延解、占压预算资金的。 （四）对拨款、退库、更正（调库）等业务审核不严，造成资金损失或重大负面影响的。 （五）违规修改国库系统数据库信息、屡次未按规定升级系统或出现设施故障等影响国库业务正常开展的。 （六）核算质量低，屡次发生差错且拒不整改或整改不到位的。 （七）对本机构或下辖分支机构代理国库相关业务发生的重大问题隐匿不报的；对本机构代理支库业务过程中发现的辖内其他机构代理国库相关业务的重大问题隐匿不报的。 （八）存在其他严重违反相关法律、法规和制度要求，或严重违反“代理支库业务协议书”的情况的。"},{"i":28,"n":"第二十八条","txt":"准予代理支库业务所依据的客观情况发生重大变化的，为保障国库资金安全，初审行可以报请审批行依法变更或者撤回已经生效的行政许可。"},{"i":29,"n":"第二十九条","txt":"在本办法施行前已通过代理支库业务审批的代理银行，初审行应当对照本办法第十一条梳理代理银行情况，对于不符合申请条件的，督促其限时整改到位并提交整改报告。"},{"i":30,"n":"第三十条","txt":"中国人民银行分支机构将代理支库业务审批的行政许可决定、年审结论以书面形式告知与有关代理支库相对应的财政部门。"},{"i":31,"n":"第三十一条","txt":"本办法未尽事宜，按《中国人民银行行政许可实施办法》等制度执行。"},{"i":32,"n":"第三十二条","txt":"农村合作银行申请开展代理支库业务的，适用本办法规定。法律、行政法规另有规定的，依照其规定。"},{"i":33,"n":"第三十三条","txt":"本办法规定的期限以“日”为单位的，均以工作日计算，不含法定节假日。"},{"i":34,"n":"第三十四条","txt":"本办法由中国人民银行负责解释。"},{"i":35,"n":"第三十五条","txt":"本办法自2026年1月1日起施行，《商业银行、信用社代理支库业务审批工作规程（暂行）》（银发〔2005〕89号文印发）同时废止。此前发布的有关制度与本办法内容不一致的，以本办法为准。 附件1：代理支库业务申请书.pdf 附件2：代理支库业务年审登记表.pdf"}],"guokujizhongshoufudailiyinhangzigerendingguanliban17d870":[{"i":1,"n":"第一条","txt":"为规范中国人民银行及其分支机构实施国库集中收付代理银行资格认定行为，保障国库资金安全，根据《中华人民共和国行政许可法》、《中华人民共和国中国人民银行法》、《中华人民共和国预算法》、《国务院对确需保留的行政审批项目设定行政许可的决定》（中华人民共和国国务院令第412号）、《国务院关于深化“证照分离”改革进一步激发市场主体发展活力的通知》（国发〔2021〕7号）等法律法规和制度规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称国库集中收付代理银行资格认定，是指中国人民银行及其分支机构受理商业银行的申请，经依法审查，认定其是否具备代理政府非税收入收缴或国库集中支付业务资格的行为。"},{"i":3,"n":"第三条","txt":"国库集中收付代理银行资格认定按照分级管理的原则实施。中国人民银行负责中央级国库集中收付代理银行资格认定，中国人民银行分支机构负责本单位组织实施的地方级国库集中收付代理银行资格认定。当地未设中国人民银行分支机构的，由上一级中国人民银行分支机构履行相应职责；当地设有中国人民银行县域派出机构的，可由县域派出机构履行相应职责。"},{"i":4,"n":"第四条","txt":"中国人民银行及其分支机构国库部门具体承办本单位国库集中收付代理银行资格认定工作，负责国库集中收付代理银行资格认定申请材料受理、相关文书制作和送达、信息公开等工作。"},{"i":5,"n":"第五条","txt":"中央级国库集中收付代理银行资格认定，原则上由商业银行总行申请；地方各级国库集中收付代理银行资格认定，由中国人民银行分支机构所在地的商业银行总行或最高级别的分支机构申请。"},{"i":6,"n":"第六条","txt":"申请机构应当具备以下条件： （一）依法持有金融许可证和营业执照，存续2年以上； （二）资产负债状况良好，具有较好的经营业绩和较强的风险控制能力； （三）机构网点数量和分布能够满足代理业务需要； （四）内部管理规范，内控制度健全，具有严格的操作规程和保密措施； （五）人员配备能够满足代理业务需要，业务人员应当熟悉国库相关制度规定，具备办理国库集中收付业务所需的专业能力； （六）具备办理国库集中收付业务所需的技术条件，资金汇划系统和内部网络安全、高效、稳定、可靠，信息系统能够及时、全面、准确地记录并反映所代理的业务信息； （七）经营合规稳健，申请时前2年内无重大违法违规行为、被采取限制业务活动、被责令停业整顿、被接管等影响资格认定的事项。"},{"i":7,"n":"第七条","txt":"申请机构应当按照要求提交申请材料，并对申请材料内容的真实性负责。申请材料包括： （一）《国库集中收付代理银行资格认定申请表》（附件1）； （二）国库集中收付代理银行资格认定申请书，内容应当包括申请机构总行前10大股东控股情况，申请机构的部门设置与分工、机构网点数量与分布、内控管理建设、资金汇划渠道、信息系统建设、代理国库相关业务开展情况、服务承诺等（详见附件2）； （三）金融许可证和营业执照副本； （四）申请机构法定代表人或主要负责人有效身份证件，如委托代理人提出申请的，还需提供授权委托书和被委托人有效身份证件； （五）最近2个年度金融监管部门、会计师事务所出具的监管通报、审计报告等； （六）申请时前2年内代理国库相关业务的违法违规行为发生情况及整改情况（申请机构及其分支机构需汇总提供）； （七）中国人民银行及其分支机构要求提供的其他材料。 上述申请资料如为复印件，应当加盖申请机构单位"},{"i":8,"n":"第八条","txt":"中国人民银行及其分支机构负责成立本单位国库集中收付代理银行资格认定评审组，组织评审组结合国库集中收付业务需要，按照评审指标对申请材料进行评分。评分实行百分制，合格分数线为60分。 地方各级国库集中收付代理银行资格认定评审组组长由本单位主要负责人或分管国库工作的负责人担任；其他成员根据资格认定工作需要，选择国库和其他相关部门具有相应专业能力的正式人员担任。评审组成员不少于7人，且应当为单数。"},{"i":9,"n":"第九条","txt":"中国人民银行国库局负责具体评审指标、评审方法与评审标准的制定，分支机构国库部门可结合当地实际情况进行补充细化。 评审指标主要包括申请机构资金安全性、流动性、效益性等方面的金融管理部门综合评价结果，机构网点数量与分布，内控管理建设，信息化能力，业务安全综合情况，申请材料质量等。"},{"i":10,"n":"第十条","txt":"中国人民银行及其分支机构国库部门依据评审组评分结果形成审查意见，拟定准予行政许可决定书或不予行政许可决定书。"},{"i":11,"n":"第十一条","txt":"中国人民银行及其分支机构应当自受理资格认定申请之日起15个工作日内作出资格认定决定。15个工作日内不能作出决定的，经本单位主要负责人批准，可延长10个工作日，并将延长期限的理由告知申请机构。"},{"i":12,"n":"第十二条","txt":"国库集中收付代理银行资格认定有效期为5年。代理银行在期满后拟延续资格认定有效期的，应当在期满6个月前向作出资格认定决定的中国人民银行或其分支机构申请延续，并提供本办法第七条所列申请材料。如原申请材料无变化的，可不再重复提供，但应当在延续申请书中作出说明。"},{"i":13,"n":"第十三条","txt":"中国人民银行及其分支机构收到代理银行延续申请后，综合国库集中收付代理银行资格认定条件和代理银行以往代理国库集中收付业务情况，经本单位主要负责人或分管国库工作的负责人审查批准后，在有效期届满前依法作出是否准予延续的决定。 中国人民银行及其分支机构对代理银行作出准予延续决定的，应当为其换发准予行政许可决定书。"},{"i":14,"n":"第十四条","txt":"中国人民银行及其分支机构就资格认定业务内容、协议要素等，与有关国库集中收付业务相对应的财政部门沟通协商。"},{"i":15,"n":"第十五条","txt":"中国人民银行及其分支机构依法履行对商业银行代理国库集中收付业务的监督管理职责。 未获得国库集中收付代理银行资格认定的商业银行，不得代理相应国库集中收付业务。"},{"i":16,"n":"第十六条","txt":"代理银行在正式开办国库集中支付业务前，应当与对应国库所在机构签订国库集中支付清算协议。清算协议需明确双方的权利义务、代理银行清算行和主办行信息、清算方式、协议有效期及违约责任等。 未按照规定签订国库集中支付清算协议的，对应国库所在机构有权拒绝受理代理银行的相关支付清算申请。 代理银行在正式开办政府非税收入收缴业务前，应当向对应国库所在机构报送其与财政部门签订的协议或文件等。"},{"i":17,"n":"第十七条","txt":"中国人民银行及其分支机构应当履行下列职责： （一）按照规定审核代理银行的支付清算和缴库业务； （二）对商业银行从事代理国库集中收付业务进行监督管理和检查。根据规范业务开展，防范国库资金风险的需要，调取、查阅商业银行有关资料数据等，依法对商业银行进行非现场监管和现场检查。"},{"i":18,"n":"第十八条","txt":"代理银行应当履行下列职责： （一）根据业务需要，建立健全内控管理机制和风险防范体系，完善国库集中收付业务相关制度并及时向中国人民银行及其分支机构报送； （二）按照国库管理规定和相关协议要求，及时、准确办理国库集中收付业务，提供安全、便捷、稳定的服务； （三）接受中国人民银行及其分支机构的监督管理和检查，如实提供国库集中收付业务活动情况的有关材料或数据，不得谎报、隐匿、篡改、销毁。"},{"i":19,"n":"第十九条","txt":"商业银行隐瞒有关情况或提供虚假申请材料的，中国人民银行及其分支机构不予受理或不予资格认定，并给予警告。 商业银行未经中国人民银行及其分支机构资格认定，擅自从事或变相从事国库集中收付业务的，中国人民银行及其分支机构应当责令改正，并依据《中华人民共和国中国人民银行法》第四十六条进行处罚。"},{"i":20,"n":"第二十条","txt":"代理银行在代理国库集中收付业务期间，有下列情形之一，构成占压财政存款或资金的，中国人民银行及其分支机构依据《金融违法行为处罚办法》第二十二条进行处罚： （一）向国库申请清算的金额超过实际支付金额的； （二）未按规定及时将国库集中支付退回资金退回国库的； （三）未按规定及时将政府非税收入缴入国库的。"},{"i":21,"n":"第二十一条","txt":"代理银行在代理国库集中收付业务期间，有下列情形之一且情节严重的，中国人民银行及其分支机构依据《中华人民共和国中国人民银行法》第四十六条进行处罚： （一）未按规定设置、使用国库集中收付会计科目和账户的； （二）未按规定支付国库集中支付资金的； （三）在代理国库集中支付业务中违规垫款的； （四）未按规定核算政府非税收入收缴业务，影响政府非税收入资金安全、完整、准确的； （五）无正当理由中断或终止国库集中收付业务的。"},{"i":22,"n":"第二十二条","txt":"代理银行未按规定向中国人民银行及其分支机构报送国库集中收付业务材料或数据，中国人民银行及其分支机构应当责令改正，逾期不改正的，依据《中华人民共和国商业银行法》第八十条进行处罚。"},{"i":23,"n":"第二十三条","txt":"本办法施行前，已获得国库集中收付代理银行资格认定，或经中国人民银行分支机构与地方财政部门共同选定为代理银行的，在本办法施行后，代理银行获得资格认定或被选定未满5年的情形下，中国人民银行及其分支机构要及时换发或补发准予行政许可决定书，明确资格认定有效期。 除上述情形外，中国人民银行分支机构应当在本办法施行后的6个月内，组织辖区内商业银行开展国库集中收付代理银行资格认定。"},{"i":24,"n":"第二十四条","txt":"本办法未尽事宜和涉及的其他格式文本，按《中国人民银行行政许可实施办法》（中国人民银行令〔2020〕第1号发布）等制度要求执行。"},{"i":25,"n":"第二十五条","txt":"农村信用合作社、农村合作银行申请国库集中收付代理银行资格认定的，适用本办法有关规定。"},{"i":26,"n":"第二十六条","txt":"本办法由中国人民银行负责解释。"},{"i":27,"n":"第二十七条","txt":"本办法自2026年1月1日起施行，《中国人民银行关于明确地方国库集中收付代理银行资格认定有关事项的通知》（银发〔2009〕385号）同时废止。此前发布的有关制度与本办法内容不一致的，以本办法为准。 附件1：国库集中收付代理银行资格认定申请表.pdf 附件2：国库集中收付代理银行资格认定申请书主要内容.pdf"}],"difangzhengfuxiangzhongyangzhuanxiangjiekuanguanlib961c3":[{"i":1,"n":"第一条","txt":"为了维护地方金融稳定，防范化解金融风险，确保专项借款资金专款专用，到期归还，特制定本规定。"},{"i":2,"n":"第二条","txt":"本规定中所称的专项借款是指经国务院批准，中国人民银行发放再贷款，并通过指定的地方商业银行向省（自治区、直辖市）政府（以下简称省级政府）的融资，专项用于解决地方要关闭的农村合作基金会、各类信托投资公司、城市商业银行、城市信用社的个人债务和合法外债。专项借款必须根据《中华人民共和国中国人民银行法》和中国人民银行再贷款管理的有关规定使用和管理。"},{"i":3,"n":"第三条","txt":"省级政府根据上述地方性金融机构和非金融性机构的资产和负债情况及政府借债的偿还能力，在多方筹措偿还资金仍难以解决支付风险的情况下，由省级政府向国务院报告地方金融风险及处理情况，请求国务院批准同意向中央专项借款。"},{"i":4,"n":"第四条","txt":"根据国务院办公厅批转的申请，中国人民银行、财政部和其它有关部门对该省（自治区、直辖市）金融风险情况及支付资金缺口等情况进行审查；其中中国人民银行主要负责对承贷的地方商业银行的资产负债、信贷收支等经营状况的审核；财政部主要负责审查该省（自治区、直辖市）近几年的财政收支、当年的财政预算、还款期内财政预算安排及政府的实际偿还能力等情况。按照审查意见，财政部、中国人民银行和其它有关部门联合行文提出省（自治区、直辖市）向中央专项借款的意见，并报国务院核准。"},{"i":5,"n":"第五条","txt":"省级政府根据国务院批准的借款报告，向财政部提出申请，承诺如期归还中国人民银行向省（自治区、直辖市）发放的专项贷款，如果不能按期归还专项贷款本息，由财政部根据中国人民银行扣款通知在中央向该省（自治区、直辖市）的转移支付资金和税收返还资金中扣还。"},{"i":6,"n":"第六条","txt":"财政部接到省级政府承诺如期归还贷款的报告，经审查后给省政府复函，并抄送中国人民银行。明确如果省政府不能按期归还再贷款本息，财政部按中国人民银行提供的扣款承诺书等文件，从对该省（自治区、直辖市）的转移支付资金和税收返还资金中扣还。"},{"i":7,"n":"第七条","txt":"中国人民银行根据国务院对财政部、中国人民银行和其它有关部门联合文件的批准意见及财政部对政府承诺申请的复函抄送件，对所在地分行、营业管理部下达贷款限额。中国人民银行分行、营业管理部在与省（自治区、直辖市）政府签定贷款协议书后，在总行下达的贷款限额内，对政府所在地的中心支行或营业管理部下达贷款限额。"},{"i":8,"n":"第八条","txt":"政府所在地的中心支行或营业管理部根据分行下达的贷款限额与承贷的地方商业银行签订贷款合同，方可发放贷款。地方商业银行设立表外临时账户，记载该项再贷款的运用情况。该项再贷款实行专户管理，专款专用，地方商业银行对该项再贷款没有支配权，不体现营业收入。"},{"i":9,"n":"第九条","txt":"专项借款的使用期限一般为六至八年，一次落实借款合同，分年签订借款借据。专项借款从划拨至专户之日起计息，借款期内按季付息，从第二年开始或按协议偿还本金，也可提前归还部分或全部借款。专项借款利率按年利率2.25%计息。"},{"i":10,"n":"第十条","txt":"中国人民银行分行、营业管理部要加强对专项借款使用情况的监督检查，派专人负责，单独考核，并负责到期收回；省（自治区、直辖市）政府要全面负责借款的使用，根据地方金融机构和非金融性机构的个人存款兑付进度下拨资金，严防各级政府将专项借款挪作他用。要逐年落实还款计划，并将每年的还款列入省（自治区、直辖市）预算内，确保专项借款按时归还。"},{"i":11,"n":"第十一条","txt":"本规定自下发日起实行。"}],"jingneiwaihuizhanghuguanliguiding":[{"i":1,"n":"第一条","txt":"为规范外汇帐户的开立和使用，加强外汇帐户的监督管理，根据《中华人民共和国外汇管理条例》和《结汇、售汇及付汇管理规定》，特制定本规定。"},{"i":2,"n":"第二条","txt":"国家外汇管理局及其分、支局（以下简称“外汇局”）为外汇帐户的管理机关。"},{"i":3,"n":"第三条","txt":"境内机构、驻华机构、个人及来华人员开立、使用、关闭外汇帐户适用本规定。 开户金融机构应当按照本规定办理外汇帐户的开立、关闭手续并监督收付。"},{"i":4,"n":"第四条","txt":"本规定下列用语的含义： “开户金融机构”是指经批准经营外汇业务的银行和非银行金融机构。 “外汇帐户”是指境内机构、驻华机构、个人及来华人员以可自由兑换货币在开户金融机构开立的帐户。"},{"i":5,"n":"第五条","txt":"境内机构、驻华机构一般不允许开立外币现钞帐户。个人及来华人员一般不允许开立用于结算的外汇帐户。"},{"i":6,"n":"第六条","txt":"下列经常项目外汇，可以开立外汇帐户保留外汇： （一）经营境外承包工程、向境外提供劳务、技术合作的境内机构，在其业务项目进行过程中发生的业务往来外汇； （二）从事代理对外或者境外业务的境内机构代收代付的外汇； （三）境内机构暂收待付或者暂收待结项下的外汇，包括境外汇入的投标保证金、履约保证金、先收后支的转口贸易收汇、邮电部门办理国际汇兑业务的外汇汇兑款、铁路部门办理境外保价运输业务收取的外汇、海关收取的外汇保证金、抵押金等； （四）经交通部批准从事国际海洋运输业务的远洋运输公司，经外经贸部批准从事国际货运的外运公司和租船公司的业务往来外汇； （五）保险机构受理外汇保险、需向境外分保以及尚未结算的保费； （六）根据协议规定需用于境外支付的境外捐赠、资助或者援助的外汇； （七）免税品公司经营免税品业务收入的外汇； （八）有进出口经营权的企业从事大型机电产品出口项目，该项目总金额和执行期达到规"},{"i":7,"n":"第七条","txt":"境内机构按照本规定第六条（一）至（十）及（十四）规定开立的外汇帐户，其收入为来源于经常项目的外汇，支出用于经常项目支出或者经外汇局批准的资本项目支出。"},{"i":8,"n":"第八条","txt":"驻华机构按照本规定第六条（十二）开立的外汇帐户，其收入为来源于境外汇入的办公经费，支出用于办公费用。"},{"i":9,"n":"第九条","txt":"个人及来华人员可以按照本规定第六条（十三）开立个人外汇或者外币现钞存款帐户。"},{"i":10,"n":"第十条","txt":"境内机构开立经常项目外汇帐户应当经外汇局批准。"},{"i":11,"n":"第十一条","txt":"境内机构（外商投资企业除外）应当持下列材料向外汇局申请开户，并填写《国家外汇管理局开立外汇帐户批准书》（附表一），经批准后在中资开户金融机构开立外汇帐户，开户后5日内凭开户回执向外汇局领取《外汇帐户使用证》（附表二）： （一）申请开立外汇帐户的报告； （二）根据开户单位性质分别提供工商行政管理部门颁发的营业执照，或者民政部门颁发的社团登记证，或者国家授权机关批准成立的有效批件； （三）国务院授权机关批准经营业务的批件； （四）外汇局要求提供的相应合同、协议或者其他有关材料。 中资开户金融机构为境内机构开立外汇帐户后，应当在开户回执行上注明帐号、币种和开户日期，并加盖该金融机构戳记。"},{"i":12,"n":"第十二条","txt":"外商投资企业开立经常项目下外汇帐户应当持申请开立外汇帐户的报告、《外商投资企业外汇登记证》向外汇局申请，持外汇局核发的“开户通知书”和《外商投资企业外汇登记证》到开户金融机构办理开户手续。开户金融机构为外商投资企业开立外汇帐户后，应当在《外商投资企业外汇登记证》相应栏目中注明帐号、币种和开户日期，并加盖该金融机构戳记。"},{"i":13,"n":"第十三条","txt":"境内机构申请开户时，外汇局应当根据外汇帐户的用途，规定帐户的收支范围、使用期限及相应的结汇方式或者核定最高金额，并在《外汇帐户使用证》或者《外商投资企业外汇登记证》中注明。"},{"i":14,"n":"第十四条","txt":"驻华机构应当持有关部门批准设立机构的文件及工商登记证到外汇局登记备案，领取《驻华机构外汇帐户备案表》（附表三）后，凭《驻华机构外汇帐户备案表》到开户银行办理开户手续。"},{"i":15,"n":"第十五条","txt":"个人及来华人员外汇或者外币现钞存取自由，对于超过等值1万美元以上的大额外币现钞存取，应当向开户银行提供身份证或者护照，开户银行应当逐笔登记备案。"},{"i":16,"n":"第十六条","txt":"境内机构、驻华机构开立的经常项目外汇帐户，应当按照《外汇帐户使用证》、《外商投资企业外汇登记证》或者《驻华机构外汇帐户备案表》规定的收支范围办理收付。"},{"i":17,"n":"第十七条","txt":"外商投资企业经常项目外汇收入进入外汇结算帐户的，在外汇局核定的最高金额内保留外汇；超过最高金额的外汇，应当卖给外汇指定银行或者通过外汇调剂中心卖出。 开户金融机构收到外商投资企业超过外汇结算帐户最高金额的经常项目外汇，可以暂时予以入帐，同时通知外商投资企业在5个工作日内办理结汇或者通过外汇调剂中心卖出。逾期不办理的，开户金融机构应当抄报当地外汇局，由外汇局责令强制结汇。 外汇局根据外商投资企业实投资本和经常项目外汇资金周转的需要，调整核定外汇结算帐户最高金额的原则。"},{"i":18,"n":"第十八条","txt":"其他境内机构应当按照《外汇帐户使用证》规定的结汇方式办理外汇帐户内资金的结汇。"},{"i":19,"n":"第十九条","txt":"开户金融机构应当制定外汇开证保证金帐户统一管理办法，报外汇局备案，并根据风险控制的需要按照报备的管理办法为境内机构开立外汇开证保证金帐户。 外汇开证保证金帐户不得用于其他任何用途。"},{"i":20,"n":"第二十条","txt":"下列资本项目外汇，可以开立外汇帐户保留外汇： （一）境内机构借用的外债、外债转贷款和境内中资金融机构的外汇贷款； （二）境内机构用于偿付境内外外汇债务本金的外汇； （三）境内机构发行股票收入的外汇； （四）外商投资企业中外投资方以外汇投入的资本金； （五）境外法人或者自然人为筹建外商投资企业汇入的外汇； （六）境内机构资产存量变现取得的外汇； （七）境外法人或者自然人在境内买卖B股的外汇； （八）经外汇局批准的其他资本项目下的外汇。"},{"i":21,"n":"第二十一条","txt":"按照本规定第二十条（一）开立的贷款专户，其收入为外债、外债转贷款或者外汇贷款的合同款；支出用于贷款协议规定的用途。"},{"i":22,"n":"第二十二条","txt":"按照本规定第六条（十一）、第二十条（二）开立的还贷专户，其收入为经批准用人民币购买的外汇、经批准的贷款专户转入的资金及经批准保留的外汇收入；支出用于偿还债务本息及相关费用。"},{"i":23,"n":"第二十三条","txt":"按照本规定第二十条（三）开立的外币股票专户，其收入为外币股票发行收入，支出用于经证券监督管理部门批准的招股说明书规定的用途。"},{"i":24,"n":"第二十四条","txt":"按照本规定第二十条（四）开立的外商投资企业外汇资本金帐户，其收入为外商投资企业中外投资方以外汇投入的资本金；支出为外商投资企业经常项目外汇支出和经外汇局批准的资本项目外汇支出。"},{"i":25,"n":"第二十五条","txt":"按照本规定第二十条（五）开立的临时专户，其收入为境外法人或者自然人为筹建外商投资企业汇入的外汇；支出为筹建外商投资企业的开办费用及其他相关费用。企业成立后，临时帐户的资金余额可以转为外商投资款划入企业资本金帐户。如果企业未成立，经外汇局核准资金可以汇出境外。"},{"i":26,"n":"第二十六条","txt":"按照本规定第二十六条（六）开立的外汇帐户，其收入为境内机构转让现有资产收入的外汇；支出为经批准的资金用途。"},{"i":27,"n":"第二十七条","txt":"按照本规定第二十条（七）开立的外汇帐户，其收入为境外法人或者自然人买卖股票收入的外汇和境外汇入或者携入的外汇，支出用于买卖股票。"},{"i":28,"n":"第二十八条","txt":"开立资本项目外汇帐户（按照本规定第二十条（七）开立的外汇帐户除外）应当持开立外汇帐户的申请报告和下列相关文件及资料向外汇局申请，经批准后持外汇局核发的“开户通知书”到开户金融机构办理开户手续： （一）境内机构开立贷款专户和还贷专户，持借款合同正本、外债登记凭证或者《外汇（转）贷款登记证》； （二）境内机构申请开立股票专户，持证券监督管理部门批准的招股说明书等资料； （三）外商投资企业申请开立资本金帐户，持《外商投资企业外汇登记证》和其他资料； （四）境外法人或者自然人申请开立临时专户，持汇款凭证和签订的投资意向书； （五）境内机构按照本规定第二十条（六）开立的外汇帐户，持有权批准机构的批准转让文件、转让协议、资金使用计划等文件；"},{"i":29,"n":"第二十九条","txt":"境外法人或者自然人按照本规定第二十条（七）开立的B股帐户，持境外机构法人资格证明或者境外个人身份证明直接到证券公司开户。"},{"i":30,"n":"第三十条","txt":"境内机构申请开立资本项目外汇帐户时，外汇局应当规定外汇帐户的收支范围、使用期限和核定帐户最高金额，并在“开户通知书”中注明。"},{"i":31,"n":"第三十一条","txt":"开户金融机构为外商投资企业开立资本项目外汇帐户后，应当在《外商投资企业外汇登记证》相应栏目中注明帐号、币种和开户日期，并加盖该金融机构戳记。"},{"i":32,"n":"第三十二条","txt":"境内机构可以根据贷款协议中规定的用途使用贷款专户资本，不需经外汇局批准。 还贷专户的资金余额不得超过最近两期偿还本息总额，支出应当逐笔报外汇局审批。"},{"i":33,"n":"第三十三条","txt":"境内机构通过还贷专户偿还外债、外债转贷款本息及费用，应当持外债登记凭证、债权人还本付息通知单，提前５个工作日向所在地外汇局申请，领取“还本付息核准件”。开户金融机构凭外汇局核发的“还本付息核准件”办理支付手续。"},{"i":34,"n":"第三十四条","txt":"境内机构通过还贷专户偿还境内中资金融机构外汇贷款本息及费用，可以持《外汇（转）贷款登记证》、债权人还本付息通知单、借款合同直接到开户金融机构办理。"},{"i":35,"n":"第三十五条","txt":"境内机构资本项目外汇帐户内资金转换为人民币，应当报外汇局批准；境外法人或者自然人按照第二十条（七）开立的外汇帐户内的资金，不得转换为人民币使用。"},{"i":36,"n":"第三十六条","txt":"境内机构、驻华机构应当向注册地外汇局申请开户。需要在境内其他地区开立外汇帐户的，按照以下规定办理： （一）外商投资企业应当向注册地外汇局提出申请，凭注册地外汇局核发的“开户通知书”到开户地外汇局备案，经开户地外汇局审核并加盖戳记后，到开户金融机构办理手续； （二）其他境内机构按照本规定开立的经常项目外汇帐户，凭注册地外汇局的批准文件及有关材料向开户地外汇局申请，由开户地外汇局核发《开立外汇帐户批准书》及《外汇帐户使用证》； （三）其他境内机构按照本规定开立的资本项目外汇帐户，凭注册地外汇局核发的“开户通知书”到开户地外汇局备案，经开户地外汇局审核并加盖戳记后，到开户金融机构开立外汇帐户。 （四）驻华机构应当分别向注册地和开户地外汇局领取《驻华机构外汇帐户备案表》。"},{"i":37,"n":"第三十七条","txt":"境内机构、驻华机构如需变更《外汇帐户使用证》、《外商投资企业外汇登记证》或者《驻华机构外汇帐户备案表》“开户通知书”中外汇帐户相关内容的，应当持有关材料向外汇局提出申请，办理变更手续。"},{"i":38,"n":"第三十八条","txt":"境内机构、驻华机构如需关闭外汇帐户，应当在办理清户手续后10个工作日内将开户金融机构关闭帐户的证明及《外汇帐户使用证》、外债登记凭证、《外商投资企业外汇登记证》或者《驻华机构外汇帐户备案表》送交外汇局，办理关闭帐户手续。 境内机构关闭外汇帐户后，其外汇帐户余额属于外商投资者所有的或者经批准可以保留的，可以转移或者汇出；其余外汇应当全部结汇。 驻华机构关闭外汇帐户后，其外汇帐户余额可以转移或者汇出。"},{"i":39,"n":"第三十九条","txt":"外汇局对境内机构及驻华机构的外汇帐户实行年检制度。"},{"i":40,"n":"第四十条","txt":"开户金融机构应当根据外汇局要求向所在地外汇局报送外汇帐户变动情况。"},{"i":41,"n":"第四十一条","txt":"凡应当撤销的外汇帐户，由外汇局对开户金融机构及开户单位下达《撤销外汇帐户通知书》，并按照规定对该外汇帐户余额做出明确处理，限期办理撤户手续。"},{"i":42,"n":"第四十二条","txt":"境内机构、驻华机构应当按照本规定申请和办理开户手续，并按照外汇局核定的收支范围、使用期限、最高金额使用外汇帐户。不得擅自开立外汇帐户；不得出租、出借或者串用外汇帐户；不得利用外汇帐户代其他单位或者个人收付、保存或者转让外汇；不得将单位外汇以个人名义私存；不得擅自超出外汇局核定的使用期限、最高金额使用外汇帐户。"},{"i":43,"n":"第四十三条","txt":"开户金融机构应当按照本规定为境内机构、驻华机构、个人及来华人员办理帐户的开户、收付及关闭手续，监督开户单位及个人对其外汇帐户的使用。不得擅自为境内机构、驻华机构、个人及来华人员开立外汇帐户或者超范围办理资金收付。"},{"i":44,"n":"第四十四条","txt":"境内机构、驻华机构、个人及来华人员有下列违反外汇帐户管理规定行为的，由外汇局责令改正，撤销外汇帐户，通报批评，并处5万元以上30万元以下的罚款： （一）擅自在境内开立外汇帐户； （二）出借、串用、转让外汇帐户； （三）擅自改变外汇帐户使用范围； （四）擅自超出外汇局核定的外汇帐户最高金额、使用期限使用外汇帐户； （五）其他违反本规定行为。"},{"i":45,"n":"第四十五条","txt":"开户金融机构擅自为境内机构、驻华机构、个人及来华人员开立外汇帐户，擅自超过外汇局核定内容办理帐户收付或者违反其他外汇帐户管理规定，由外汇局责令改正，通报批评，并处10万元以上30万元以下的罚款。"},{"i":46,"n":"第四十六条","txt":"境内持有工商营业执照的外资非法人经济组织外汇帐户的开立、使用，按照本规定有关外商投资企业条款办理。"},{"i":47,"n":"第四十七条","txt":"以下帐户不适用本规定： （一）金融机构同业外汇存款帐户。 （二）具有外交豁免权的外国使领馆、国际组织驻华代表机构在境内开立的外汇帐户。"},{"i":48,"n":"第四十八条","txt":"本规定由国家外汇管理局负责解释。"},{"i":49,"n":"第四十九条","txt":"本规定自1997年10月15日起施行。 中国人民银行1994年4月1日发布的《外汇帐户管理暂行办法》、国家外汇管理局1994年5月30日发布的《关于〈外汇帐户管理暂行办法〉有关问题的通知》、1994年6月22日发布的《外债、外汇（转）贷款还本付息开立帐户操作规程》、1996年6月28日发布的《外商投资企业境内外汇帐户管理暂行办法》同时废止。"}],"jingwaiwaihuizhanghuguanliguiding":[{"i":1,"n":"第一条","txt":"为完善对境内机构境外外汇账户的管理，根据《中华人民共和国外汇管理条例》和《结汇、售汇及付汇管理规定》，特制定本规定。"},{"i":2,"n":"第二条","txt":"境内机构境外外汇账户的开立、使用及撤销的管理适用本规定。"},{"i":3,"n":"第三条","txt":"国家外汇管理局及其分局（以下简称“外汇局”）为境外外汇账户的管理机关。"},{"i":4,"n":"第四条","txt":"境内机构符合下列条件的，可以在境外开立外汇账户： （一）在境外有经常性零星收入，需在境外开立外汇账户，将收入集整后汇回境内的； （二）在境外有经常性零星支出，需在境外开立外汇账户的； （三）从事境外承包工程项目，需在境外开立外汇账户的； （四）在境外发行外币有价证券，需要境外开立外汇账户的； （五）因业务上特殊需要必须在境外开立外汇账户的。"},{"i":5,"n":"第五条","txt":"境内机构在境外开立外汇账户，应当持下列文件和资料向外汇局申请： （一）由境内机构法人代表或者其授权人签署并加盖公章的申请书。申请书应当包括开户理由、币别、账户最高金额、用途、收支范围、使用期限、拟开户银行及其所在地等内容； （二）工商行政管理部门颁发的营业执照正本及其复印件； （三）境外账户使用的内部管理规定； （四）外汇局要求提供的其他文件和资料。 从事境外承包工程业务的，除提供上述文件和资料外，还应当提供有关项目合同；外商投资企业在境外开立外汇账户的，除提供上述文件和资料外，还应当提供《外商投资企业外汇登记证》和注册会计师事务所验证的注册资本金已全部到位的验资证明。"},{"i":6,"n":"第六条","txt":"外汇局应当自收到前条规定的文件和资料起30个工作日内予以答复。"},{"i":7,"n":"第七条","txt":"经外汇局批准后，境内机构方可在境外开立外汇账户。"},{"i":8,"n":"第八条","txt":"境内机构应当以自己名义在境外开立外汇账户。未经外汇局批准不得以个人或者其他法人名义在境外开立外汇账户。"},{"i":9,"n":"第九条","txt":"境内机构应当选择其外汇收支主要发生国家或者地区资信较好的银行开立境外外汇账户。"},{"i":10,"n":"第十条","txt":"境内机构应当在开立境外外汇账户后30个工作日内，持境外外汇账户开户银行名称、帐号、开户人名称等资料到外汇局备案。"},{"i":11,"n":"第十一条","txt":"境内机构通过境外外汇账户办理资金的收付，应当遵守开户所在国或者地区的规定，并对境外外汇账户资金安全采取切实有效的管理措施。"},{"i":12,"n":"第十二条","txt":"境内机构应当按照外汇局批准的账户收支范围、账户最高金额和使用期限使用境外外汇账户，不得出租、出借、串用境外外汇账户。"},{"i":13,"n":"第十三条","txt":"境内机构变更境外外汇账户的开户行、收支范围、账户最高金额和使用期限等内容的，应当事先向外汇局申请，经批准后，方可变更。"},{"i":14,"n":"第十四条","txt":"境内机构应当在境外外汇账户使用期限到期后30个工作日内，将境外外汇账户的银行销户通知书报外汇局备案，余款调回境内，并提供账户清单；需要延期使用的，应当在到期前30个工作日内向外汇局提出书面申请，经外汇局批准后，方可继续使用。"},{"i":15,"n":"第十五条","txt":"境内机构应当保存其境外外汇账户完整的会计资料。境内机构应当在每季度初15个工作日内向外汇局提供开户银行上季度对帐单复印件；每年1月30日前向外汇局提供上年度资金使用情况书面说明。"},{"i":16,"n":"第十六条","txt":"境内机构有下列行为之一的，由外汇局责令改正，撤销境外外汇账户，通报批评，并处以5万元以上30万元以下的罚款： （一）违反本规定第七、十四条的规定，未经批准擅自开立或者延期使用境外外汇账户的； （二）违反本规定第八条的规定，擅自以他人名义开立境外外汇账户的； （三）违反本规定第十二、十三条的规定，出租、出借、串用境外外汇账户的，擅自改变境外外汇账户开户行、收支范围、最高金额的； （四）违反本规定第五、十、十三、十四、十五条的规定，提供虚假文件和资料的； （五）违反本规定第十、十四、十五条的规定，未向外汇局提供文件和资料的； （六）其他违反本规定的行为。"},{"i":17,"n":"第十七条","txt":"金融机构在境外开立外汇账户不适用本规定。"},{"i":18,"n":"第十八条","txt":"本规定由国家外汇管理局负责解释。"},{"i":19,"n":"第十九条","txt":"本规定自1998年1月1日起施行。1989年1月7日国家外汇管理局发布的《关于外商投资企业境外外汇账户的管理规定》同时废止。 注:根据《中国人民银行公告》(〔2015〕第12号),以下内容已被修改:将《境外外汇账户管理规定》(〔97〕汇政发字第10号印发)第五条第二款中“外商投资企业在境外开立外汇账户的,除提供上述文件和资料外,还应当提供《外商投资企业外汇登记证》和注册会计师事务所验证的注册资本金已全部到位的验资证明”的内容修改为“外商投资企业在境外开立外汇账户的,除提供上述文件和资料外,还应当提供相关外汇业务登记凭证”。"}],"zhengxinyewuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范征信业务及其相关活动，保护信息主体合法权益，促进征信业健康发展，推进社会信用体系建设，根据《中华人民共和国中国人民银行法》《中华人民共和国个人信息保护法》《征信业管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内，对法人和非法人组织（以下统称企业）、个人开展征信业务及其相关活动的，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称征信业务，是指对企业和个人的信用信息进行采集、整理、保存、加工，并向信息使用者提供的活动。 本办法所称信用信息，是指依法采集，为金融等活动提供服务，用于识别判断企业和个人信用状况的基本信息、借贷信息、其他相关信息，以及基于前述信息形成的分析评价信息。"},{"i":4,"n":"第四条","txt":"从事个人征信业务的，应当依法取得中国人民银行个人征信机构许可；从事企业征信业务的，应当依法办理企业征信机构备案；从事信用评级业务的，应当依法办理信用评级机构备案。"},{"i":5,"n":"第五条","txt":"金融机构不得与未取得合法征信业务资质的市场机构开展商业合作获取征信服务。 本办法所称金融机构，是指国务院金融管理部门监督管理的从事金融业务的机构。 地方金融监管部门负责监督管理的地方金融组织适用本办法关于金融机构的规定。"},{"i":6,"n":"第六条","txt":"从事征信业务及其相关活动，应当保护信息主体合法权益，保障信息安全，防范信用信息泄露、丢失、毁损或者被滥用，不得危害国家秘密，不得侵犯个人隐私和商业秘密。 从事征信业务及其相关活动，应当遵循独立、客观、公正的原则，不得违反法律法规的规定，不得违反社会公序良俗。"},{"i":7,"n":"第七条","txt":"采集个人信用信息，应当采取合法、正当的方式，遵循最小、必要的原则，不得过度采集。"},{"i":8,"n":"第八条","txt":"征信机构不得以下列方式采集信用信息： （一）欺骗、胁迫、诱导； （二）向信息主体收费； （三）从非法渠道采集； （四）以其他侵害信息主体合法权益的方式。"},{"i":9,"n":"第九条","txt":"信息提供者向征信机构提供信用信息的，征信机构应当制定相关制度，对信息提供者的信息来源、信息质量、信息安全、信息主体授权等进行必要的审查。"},{"i":10,"n":"第十条","txt":"征信机构与信息提供者在开办业务及合作中应当遵守《中华人民共和国个人信息保护法》等法律法规，通过协议等形式明确信息采集的原则以及各自在获得客户同意、信息采集、加工处理、信息更正、异议处理、信息安全等方面的权利义务和责任。"},{"i":11,"n":"第十一条","txt":"征信机构经营个人征信业务，应当制定采集个人信用信息的方案，并就采集的数据项、信息来源、采集方式、信息主体合法权益保护制度等事项及其变化向中国人民银行报告。"},{"i":12,"n":"第十二条","txt":"征信机构采集个人信用信息应当经信息主体本人同意，并且明确告知信息主体采集信用信息的目的。依照法律法规公开的信息除外。"},{"i":13,"n":"第十三条","txt":"征信机构通过信息提供者取得个人同意的，信息提供者应当向信息主体履行告知义务。"},{"i":14,"n":"第十四条","txt":"个人征信机构应当将与其合作，进行个人信用信息采集、整理、加工和分析的信息提供者，向中国人民银行报告。 个人征信机构应当规范与信息提供者的合作协议内容。信息提供者应当就个人信用信息处理事项接受个人征信机构的风险评估和中国人民银行的情况核实。"},{"i":15,"n":"第十五条","txt":"采集企业信用信息，应当基于合法的目的，不得侵犯商业秘密。"},{"i":16,"n":"第十六条","txt":"征信机构整理、保存、加工信用信息，应当遵循客观性原则，不得篡改原始信息。"},{"i":17,"n":"第十七条","txt":"征信机构应当采取措施，提高征信系统信息的准确性，保障信息质量。"},{"i":18,"n":"第十八条","txt":"征信机构在整理、保存、加工信用信息过程中发现信息错误的，如属于信息提供者报送错误的，应当及时通知信息提供者更正；如属于内部处理错误的，应当及时更正，并优化信用信息内部处理流程。"},{"i":19,"n":"第十九条","txt":"征信机构应当对来自不同信息提供者的信息进行比对，发现信息不一致的，及时进行核查和处理。"},{"i":20,"n":"第二十条","txt":"征信机构采集的个人不良信息的保存期限，自不良行为或者事件终止之日起为5年。 个人不良信息保存期限届满，征信机构应当将个人不良信息在对外服务和应用中删除；作为样本数据的，应当进行匿名化处理。"},{"i":21,"n":"第二十一条","txt":"征信机构对外提供征信产品和服务，应当遵循公平性原则，不得设置不合理的商业条件限制不同的信息使用者使用，不得利用优势地位提供歧视性或者排他性的产品和服务。"},{"i":22,"n":"第二十二条","txt":"征信机构应当采取适当的措施，对信息使用者的身份、业务资质、使用目的等进行必要的审查。 征信机构应当对信息使用者接入征信系统的网络和系统安全、合规性管理措施进行评估，对查询行为进行监测。发现安全隐患或者异常行为的，及时核查；发现违法违规行为的，停止提供服务。"},{"i":23,"n":"第二十三条","txt":"信息使用者应当采取必要的措施，保障查询个人信用信息时取得信息主体的同意，并且按照约定用途使用个人信用信息。"},{"i":24,"n":"第二十四条","txt":"信息使用者使用征信机构提供的信用信息，应当基于合法、正当的目的，不得滥用信用信息。"},{"i":25,"n":"第二十五条","txt":"个人信息主体有权每年两次免费获取本人的信用报告，征信机构可以通过互联网查询、营业场所查询等多种方式为个人信息主体提供信用报告查询服务。"},{"i":26,"n":"第二十六条","txt":"信息主体认为信息存在错误、遗漏的，有权向征信机构或者信息提供者提出异议；认为侵害自身合法权益的，可以向所在地中国人民银行分支机构投诉。对异议和投诉按照《征信业管理条例》及相关规定办理。"},{"i":27,"n":"第二十七条","txt":"征信机构不得以删除不良信息或者不采集不良信息为由，向信息主体收取费用。"},{"i":28,"n":"第二十八条","txt":"征信机构提供信用报告等信用信息查询产品和服务的，应当客观展示查询的信用信息内容，并对查询的信用信息内容及专业名词进行解释说明。 信息主体有权要求征信机构在信用报告中添加异议标注和声明。"},{"i":29,"n":"第二十九条","txt":"征信机构提供画像、评分、评级等信用评价类产品和服务的，应当建立评价标准，不得将与信息主体信用无关的要素作为评价标准。 征信机构正式对外提供信用评价类产品和服务前，应当履行必要的内部测试和评估验证程序，使评价规则可解释、信息来源可追溯。 征信机构提供经济主体或者债务融资工具信用评级产品和服务的，应当按照《信用评级业管理暂行办法》（中国人民银行 发展改革委 财政部 证监会令〔2019〕第5号发布）等相关规定开展业务。"},{"i":30,"n":"第三十条","txt":"征信机构提供信用反欺诈产品和服务的，应当建立欺诈信用信息的认定标准。"},{"i":31,"n":"第三十一条","txt":"征信机构提供信用信息查询、信用评价类、信用反欺诈产品和服务，应当向中国人民银行或其省会（首府）城市中心支行以上分支机构报告下列事项： （一）信用报告的模板及内容； （二）信用评价类产品和服务的评价方法、模型、主要维度要素； （三）信用反欺诈产品和服务的数据来源、欺诈信用信息认定标准。"},{"i":32,"n":"第三十二条","txt":"征信机构不得从事下列活动： （一）对信用评价结果进行承诺； （二）使用对信用评价结果有暗示性的内容宣传产品和服务； （三）未经政府部门或者行业协会同意，假借其名义进行市场推广； （四）以胁迫、欺骗、诱导的方式向信息主体或者信息使用者提供征信产品和服务； （五）对征信产品和服务进行虚假宣传； （六）提供其他影响征信业务客观公正性的征信产品和服务。"},{"i":33,"n":"第三十三条","txt":"征信机构应当落实网络安全等级保护制度，制定涉及业务活动和设备设施的安全管理制度，采取有效保护措施，保障征信系统的安全。"},{"i":34,"n":"第三十四条","txt":"个人征信机构、保存或者处理100万户以上企业信用信息的企业征信机构，应当符合下列要求： （一）核心业务信息系统网络安全保护等级具备三级或者三级以上安全保护能力； （二）设立信息安全负责人和个人信息保护负责人，由公司章程规定的高级管理人员担任； （三）设立专职部门，负责信息安全和个人信息保护工作，定期检查征信业务、系统安全、个人信息保护制度措施执行情况。"},{"i":35,"n":"第三十五条","txt":"征信机构应当保障征信系统运行设施设备、安全控制设施设备以及互联网应用程序的安全，做好征信系统日常运维管理，保障系统物理安全、通信网络安全、区域边界安全、计算环境安全、管理中心安全等，防范征信系统受到非法入侵和破坏。"},{"i":36,"n":"第三十六条","txt":"征信机构应当在人员录用、离岗、考核、安全教育、培训和外部人员访问管理等方面做好人员安全管理工作。"},{"i":37,"n":"第三十七条","txt":"征信机构应当严格限定公司内部查询和获取信用信息的工作人员的权限和范围。 征信机构应当留存工作人员查询、获取信用信息的操作记录，明确记载工作人员查询和获取信用信息的时间、方式、内容及用途。"},{"i":38,"n":"第三十八条","txt":"征信机构应当建立应急处置制度，在发生或者有可能发生信用信息泄露等事件时，立即采取必要措施降低危害，并及时向中国人民银行及其省会（首府）城市中心支行以上分支机构报告。"},{"i":39,"n":"第三十九条","txt":"征信机构在中华人民共和国境内开展征信业务及其相关活动，采集的企业信用信息和个人信用信息应当存储在中华人民共和国境内。"},{"i":40,"n":"第四十条","txt":"征信机构向境外提供个人信用信息，应当符合法律法规的规定。 征信机构向境外信息使用者提供企业信用信息查询产品和服务，应当对信息使用者的身份、信用信息用途进行必要的审查，确保信用信息用于跨境贸易、投融资等合理用途，不得危害国家安全。"},{"i":41,"n":"第四十一条","txt":"征信机构与境外征信机构合作的，应当在合作协议签署后、业务开展前将合作协议报告中国人民银行。"},{"i":42,"n":"第四十二条","txt":"征信机构应当将下列事项向社会公开，接受社会监督： （一）采集的信用信息类别； （二）信用报告的基本格式内容； （三）异议处理流程； （四）中国人民银行认为需要公开的其他事项。"},{"i":43,"n":"第四十三条","txt":"个人征信机构应当每年对自身个人征信业务遵守《中华人民共和国个人信息保护法》《征信业管理条例》的情况进行合规审计，并将合规审计报告及时报告中国人民银行。"},{"i":44,"n":"第四十四条","txt":"中国人民银行及其省会（首府）城市中心支行以上分支机构对征信机构的下列事项进行监督检查： （一）征信内控制度建设，包括各项制度和相关规程的齐备性、合规性和可操作性等； （二）征信业务合规经营情况，包括采集信用信息、对外提供和使用信用信息、异议与投诉处理、用户管理、其他事项合规性等； （三）征信系统安全情况，包括信息技术制度、安全管理、系统开发等； （四）与征信业务活动相关的其他事项。"},{"i":45,"n":"第四十五条","txt":"信息提供者和信息使用者违反《征信业管理条例》规定，侵犯信息主体合法权益的，由中国人民银行及其省会（首府）城市中心支行以上分支机构依法对其检查和处理。"},{"i":46,"n":"第四十六条","txt":"违反本办法第四条规定，擅自从事个人征信业务的，由中国人民银行按照《征信业管理条例》第三十六条进行处罚；擅自从事企业征信业务的，由中国人民银行省会（首府）城市中心支行以上分支机构按照《征信业管理条例》第三十七条进行处罚。 金融机构违反本办法第五条规定，与未取得合法征信业务资质的市场机构开展商业合作获取征信服务的，由中国人民银行及其分支机构责令改正，对单位处3万元以下罚款，对直接负责的主管人员处1000元以下罚款。"},{"i":47,"n":"第四十七条","txt":"征信机构违反本办法第八条、第十六条、第二十条、第二十七条、第三十二条规定的，由中国人民银行及其省会（首府）城市中心支行以上分支机构按照《征信业管理条例》第三十八条进行处罚。"},{"i":48,"n":"第四十八条","txt":"征信机构违反本办法第十四条、第二十一条、第三十一条、第三十四条、第三十九条、第四十二条规定的，由中国人民银行及其省会（首府）城市中心支行以上分支机构责令改正，没收违法所得，对单位处3万元以下罚款，对直接负责的主管人员处1000元以下罚款。法律、行政法规另有规定的，依照其规定。"},{"i":49,"n":"第四十九条","txt":"金融信用信息基础数据库从事征信业务、从事信贷业务的机构向金融信用信息基础数据库报送或者查询信用信息参照本办法执行。"},{"i":50,"n":"第五十条","txt":"以“信用信息服务”“信用服务”“信用评分”“信用评级”“信用修复”等名义对外实质提供征信服务的，适用本办法。"},{"i":51,"n":"第五十一条","txt":"本办法施行前未取得个人征信业务经营许可或者未进行企业征信机构备案但实质从事征信业务的机构，应当自本办法施行之日起18个月内完成合规整改。"},{"i":52,"n":"第五十二条","txt":"本办法由中国人民银行负责解释。"},{"i":53,"n":"第五十三条","txt":"本办法自2022年1月1日起施行。"}],"zhengxinjigouguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对征信机构的监督管理，促进征信业健康发展，根据《中华人民共和国中国人民银行法》、《中华人民共和国公司法》、《征信业管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称征信机构，是指依法设立、主要经营征信业务的机构。"},{"i":3,"n":"第三条","txt":"中国人民银行依法履行对征信机构的监督管理职责。中国人民银行分支机构在总行的授权范围内，履行对辖区内征信机构的监督管理职责。"},{"i":4,"n":"第四条","txt":"征信机构应当遵守法律、行政法规和中国人民银行的规定，诚信经营，不得损害国家利益、社会公共利益，不得侵犯他人合法权益。"},{"i":5,"n":"第五条","txt":"设立个人征信机构应当经中国人民银行批准。"},{"i":6,"n":"第六条","txt":"设立个人征信机构，除应当符合《征信业管理条例》第六条规定外，还应当具备以下条件： （一）有健全的组织机构； （二）有完善的业务操作、信息安全管理、合规性管理等内控制度； （三）个人信用信息系统符合国家信息安全保护等级二级或二级以上标准。 《征信业管理条例》第六条第一项所称主要股东是指出资额占公司资本总额5%以上或者持股占公司股份5%以上的股东。"},{"i":7,"n":"第七条","txt":"申请设立个人征信机构，应当向中国人民银行提交下列材料： （一）个人征信机构设立申请表； （二）征信业务可行性研究报告，包括发展规划、经营策略等； （三）公司章程； （四）股东关联关系和实际控制人说明； （五）主要股东最近3年无重大违法违规行为的声明以及主要股东的信用报告； （六）拟任董事、监事和高级管理人员任职资格证明； （七）组织机构设置以及人员基本构成说明； （八）已经建立的内控制度，包括业务操作、安全管理、合规性管理等； （九）具有国家信息安全等级保护测评资质的机构出具的个人信用信息系统安全测评报告，关于信息安全保障措施的说明和相关安全保障制度； （十）营业场所所有权或者使用权证明文件； （十一）工商行政管理部门出具的企业名称预先核准通知书复印件。 中国人民银行可以通过实地调查、面谈等方式对申请材料进行核实。"},{"i":8,"n":"第八条","txt":"中国人民银行在受理个人征信机构设立申请后公示申请人的下列事项： （一）拟设立征信机构的名称、营业场所、业务范围； （二）拟设立征信机构的资本； （三）拟设立征信机构的主要股东名单及其出资额或者所持股份； （四）拟任征信机构的董事、监事和高级管理人员名单。"},{"i":9,"n":"第九条","txt":"中国人民银行自受理个人征信机构设立申请之日起60日内对申请事项进行审查，并根据有利于征信业公平竞争和健康发展的审慎性原则作出批准或者不予批准的决定。决定批准的，依法颁发个人征信业务经营许可证；决定不予批准的，应当作出书面决定。"},{"i":10,"n":"第十条","txt":"经批准设立的个人征信机构，凭个人征信业务经营许可证向公司登记机关办理登记，领取营业执照；个人征信机构应当自公司登记机关准予登记之日起20日内，向中国人民银行提交营业执照复印件。"},{"i":11,"n":"第十一条","txt":"个人征信机构拟合并或者分立的，应当向中国人民银行提出申请，说明申请和理由，并提交相关证明材料。 中国人民银行自受理申请之日起20日内，作出批准或者不予批准的书面决定。"},{"i":12,"n":"第十二条","txt":"个人征信机构拟变更资本、主要股东的，应当向中国人民银行提出申请，说明变更事项和变更理由，并提交相关证明材料。 中国人民银行自受理申请之日起20日内，作出批准或者不予批准的书面决定。"},{"i":13,"n":"第十三条","txt":"个人征信机构拟设立分支机构的，应当符合以下条件： （一）对拟设立分支机构的可行性已经进行充分论证； （二）最近3年无受到重大行政处罚的记录。"},{"i":14,"n":"第十四条","txt":"个人征信机构申请设立分支机构，应当向中国人民银行提交下列材料： （一）个人征信机构分支机构设立申请表； （二）个人征信机构上一年度经审计的财务会计报告； （三）设立分支机构的可行性论证报告，包括拟设立分支机构的3年业务发展规划、市场分析和经营方针等； （四）针对设立分支机构所作出的内控制度安排和风险防范措施； （五）个人征信机构最近3年未受重大行政处罚的声明； （六）拟任职的分支机构高级管理人员履历材料。 中国人民银行自受理申请之日起20日内，作出批准或者不予批准的书面决定。"},{"i":15,"n":"第十五条","txt":"个人征信机构变更机构名称、营业场所、法定代表人的，应当向中国人民银行申请变更个人征信业务经营许可证记载事项。 个人征信机构应当在个人征信业务经营许可证记载事项变更后，向公司登记机关申办变更登记，并自公司登记机关准予变更之日起20日内，向中国人民银行备案。"},{"i":16,"n":"第十六条","txt":"个人征信业务经营许可证应当在个人征信机构营业场所的显著位置公示。"},{"i":17,"n":"第十七条","txt":"个人征信机构应当妥善保管个人征信业务经营许可证，不得涂改、倒卖、出租、出借、转让。"},{"i":18,"n":"第十八条","txt":"个人征信业务经营许可证有效期为3年。有效期届满需要续展的，应当在有效期届满60日前向中国人民银行提出申请，换发个人征信业务经营许可证。 有效期届满不再续展的，个人征信机构应当在个人征信业务经营许可证有效期届满60日前向中国人民银行报告，并依照本办法第二十条的规定，妥善处理信息数据库，办理个人征信业务经营许可证注销手续；个人征信机构在个人征信业务经营许可证有效期届满60日前未提出续展申请的，中国人民银行可以在个人征信业务经营许可证有效期届满之日注销其个人征信业务经营许可证，并依照《征信业管理条例》第十二条的规定处理信息数据库。"},{"i":19,"n":"第十九条","txt":"设立企业征信机构，应当符合《中华人民共和国公司法》规定的公司设立条件，自公司登记机关准予登记之日起30日内向所在地的中国人民银行省会（首府）城市中心支行以上分支机构办理备案，并提交下列材料： （一）企业征信机构备案表； （二）营业执照复印件； （三）股权结构说明，包括资本、股东名单及其出资额或者所持股份； （四）组织机构设置以及人员基本构成说明； （五）业务范围和业务规则基本情况报告； （六）业务系统的基本情况，包括企业信用信息系统建设情况报告和具有国家信息安全等级保护测评资质的机构出具的企业信用信息系统安全测评报告； （七）信息安全和风险防范措施，包括已经建立的内控制度和安全管理制度。 企业征信机构备案事项发生变更的，应当自变更之日起30日内向备案机构办理变更备案。"},{"i":20,"n":"第二十条","txt":"个人征信机构因解散或者被依法宣告破产等原因拟终止征信业务的，应当在拟终止之日前60日向中国人民银行报告退出方案，并依照《征信业管理条例》第十二条第一款规定处理信息数据库。 个人征信机构终止征信业务的，应当自终止之日起20日内，在中国人民银行指定的媒体上公告，并办理个人征信业务经营许可证注销手续，将许可证缴回中国人民银行；逾期不缴回的，中国人民银行应当依法收缴。"},{"i":21,"n":"第二十一条","txt":"企业征信机构因解散或者被依法宣告破产等原因拟终止征信业务的，应当在拟终止之日前60日向中国人民银行报告退出方案，并依照《征信业管理条例》第十二条第一款规定处理信息数据库。"},{"i":22,"n":"第二十二条","txt":"个人征信机构的董事、监事、高级管理人员，应当在任职前取得中国人民银行核准的任职资格。"},{"i":23,"n":"第二十三条","txt":"取得个人征信机构董事、监事和高级管理人员任职资格，应当具备以下条件： （一）正直诚实，品行良好； （二）具有大专以上学历； （三）从事征信工作3年以上或者从事金融、法律、会计、经济工作5年以上； （四）具有履行职责所需的管理能力； （五）熟悉与征信业务相关的法律法规和专业知识。"},{"i":24,"n":"第二十四条","txt":"有下列情形之一的，不得担任个人征信机构董事、监事和高级管理人员： （一）因贪污、贿赂、侵占财产、挪用财产或者破坏社会主义市场经济秩序，被判处刑罚，或者因犯罪被剥夺政治权利，执行期满未逾5年的； （二）最近3年有重大违法违规记录的。 本办法所称重大违法违规记录，是指除前款第一项所列之外的犯罪记录或者重大行政处罚记录。"},{"i":25,"n":"第二十五条","txt":"个人征信机构向中国人民银行申请核准董事、监事和高级管理人员的任职资格，应当提交下列材料： （一）董事、监事和高级管理人员任职资格申请表； （二）拟任职的董事、监事和高级管理人员的个人履历材料； （三）拟任职的董事、监事和高级管理人员的学历证书复印件； （四）拟任职的董事、监事和高级管理人员最近3年无重大违法违规记录的声明； （五）拟任职的董事、监事和高级管理人员的个人信用报告。 个人征信机构应当如实提交前款规定的材料，个人征信机构以及拟任职的董事、监事和高级管理人员应当对材料的真实性、完整性负责。中国人民银行根据需要对材料的真实性进行核实，并对申请任职资格的董事、监事和高级管理人员进行考察或者谈话。"},{"i":26,"n":"第二十六条","txt":"中国人民银行依法对个人征信机构董事、监事和高级管理人员的任职资格进行审查，作出核准或者不予核准的书面决定。"},{"i":27,"n":"第二十七条","txt":"企业征信机构的董事、监事、高级管理人员，应当由任职的征信机构自任命之日起20日内向所在地的中国人民银行省会（首府）城市中心支行以上分支机构备案，并提交下列材料： （一）董事、监事、高级管理人员备案表； （二）董事、监事、高级管理人员的个人履历材料； （三）董事、监事、高级管理人员的学历证书复印件； （四）董事、监事、高级管理人员的备案材料真实性声明。 企业征信机构的董事、监事、高级管理人员发生变更的，应当自变更之日起20日内向备案机构办理变更备案。"},{"i":28,"n":"第二十八条","txt":"个人征信机构应当在每年第一季度末，向中国人民银行报告上一年度征信业务开展情况。 企业征信机构应当在每年第一季度末，向备案机构报告上一年度征信业务开展情况。 报告内容应当包括信用信息采集、征信产品开发、信用信息服务、异议处理以及信用信息系统建设情况，信息安全保障情况等。"},{"i":29,"n":"第二十九条","txt":"个人征信机构应当按规定向中国人民银行报送征信业务统计报表、财务会计报告、审计报告等资料。 企业征信机构应当按规定向备案机构报送征信业务统计报表、财务会计报告、审计报告等资料。 征信机构应当对报送的报表和资料的真实性、准确性、完整性负责。"},{"i":30,"n":"第三十条","txt":"征信机构应当按照国家信息安全保护等级测评标准，对信用信息系统的安全情况进行测评。 征信机构信用信息系统安全保护等级为二级的，应当每两年进行测评；信用信息系统安全保护等级为三级以及以上的，应当每年进行测评。 个人征信机构应当自具有国家信息安全等级保护测评资质的机构出具测评报告之日起20日内，将测评报告报送中国人民银行，企业征信机构应当将测评报告报送备案机构。"},{"i":31,"n":"第三十一条","txt":"征信机构有下列情形之一的，中国人民银行及其分支机构可以将其列为重点监管对象： （一）上一年度发生严重违法违规行为的； （二）出现可能发生信息泄露征兆的； （三）出现财务状况异常或者严重亏损的； （四）被大量投诉的； （五）未按本办法第二十八条、第二十九条、第三十条规定报送相关材料的； （六）中国人民银行认为需要重点监管的其他情形。 征信机构被列为重点监管对象的，中国人民银行及其分支机构可以酌情缩短征信机构报告征信业务开展情况、进行信用信息系统安全情况测评的周期，并采取相应的监管措施，督促征信机构整改。 整改后第一款中所列情形消除的，中国人民银行及其分支机构可不再将其列为重点监管对象。"},{"i":32,"n":"第三十二条","txt":"中国人民银行及其分支机构可以根据监管需要，约谈征信机构董事、监事和高级管理人员，要求其就征信业务经营、风险控制、内部管理等有关重大事项作出说明。"},{"i":33,"n":"第三十三条","txt":"申请设立个人征信机构的申请人隐瞒有关情况或者提供虚假材料的，中国人民银行依照《中华人民共和国行政许可法》的相关规定进行处罚。"},{"i":34,"n":"第三十四条","txt":"个人征信机构的个人信用信息系统未达到国家信息安全保护等级二级或者二级以上要求的，中国人民银行可以责令整顿；情节严重或者拒不整顿的，中国人民银行依照《征信业管理条例》第三十八条的规定，吊销其个人征信业务经营许可证。"},{"i":35,"n":"第三十五条","txt":"申请个人征信机构的董事、监事、高级管理人员任职资格的申请人隐瞒有关情况或者提供虚假材料的，中国人民银行不予受理或者不予核准其任职资格，并给予警告；已经核准的，取消其任职资格。 禁止上述申请人3年内再次申请任职资格。"},{"i":36,"n":"第三十六条","txt":"个人征信机构任命未取得任职资格董事、监事、高级管理人员的，由中国人民银行责令改正并给予警告；情节严重的，处1万元以上3万元以下罚款。 企业征信机构任命董事、监事、高级管理人员未及时备案或者变更备案，以及在备案中提供虚假材料的，由中国人民银行分支机构责令改正并给予警告；情节严重的，处1万元以上3万元以下罚款。"},{"i":37,"n":"第三十七条","txt":"征信机构违反本办法第二十九条、第三十条规定的，由中国人民银行及其分支机构责令改正；情节严重的，处1万元以上3万元以下罚款；涉嫌犯罪的，依法移交司法机关追究其刑事责任。"},{"i":38,"n":"第三十八条","txt":"本办法由中国人民银行负责解释。"},{"i":39,"n":"第三十九条","txt":"本办法自2013年12月20日起施行。"}],"zhifujiesuanyewudailibanfa":[{"i":1,"n":"第一条","txt":"为规范政策性银行、国有独资商业银行、股份制商业银行、城市商业银行、外资银行、城市信用合作社、农村信用合作社（下称银行）之间支付结算业务代理行为，畅通汇路，改进服务，促进社会主义市场经济的发展，根据《支付结算办法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称支付结算业务代理，是指银行双方之间，一方委托另一方办理其支付结算业务的行为。委托方为被代理行，受委托方为代理行。"},{"i":3,"n":"第三条","txt":"本办法适用于中华人民共和国境内各银行人民币支付结算业务的代理。"},{"i":4,"n":"第四条","txt":"银行办理银行汇票、汇兑、委托收款、托收承付等支付结算业务，均可以实行代理。"},{"i":5,"n":"第五条","txt":"经中国人民银行批准可以经营支付结算业务的银行，方可办理支付结算业务的代理。未经中国人民银行批准可以经营支付结算业务的非银行金融机构和单位，不得办理支付结算业务的代理。"},{"i":6,"n":"第六条","txt":"实行支付结算业务代理的，被代理行和代理行必须签订支付结算业务代理协议。本办法另有规定的除外。"},{"i":7,"n":"第七条","txt":"支付结算业务的代理，应遵循平等自愿、互惠互利、长期合作的原则。"},{"i":8,"n":"第八条","txt":"支付结算业务的代理，应遵守法律、法规和规章，不得从事不正当竞争，不得损害支付结算当事人的合法权益。"},{"i":9,"n":"第九条","txt":"中国人民银行对银行的代理业务有权进行指导、协调和管理，调解代理业务纠纷。"},{"i":10,"n":"第十条","txt":"银行汇票业务代理，是指代理签发银行汇票和代理兑付银行汇票的行为。"},{"i":11,"n":"第十一条","txt":"银行汇票业务代理采取以下方式： （一）签发本行银行汇票，并委托他行代理兑付； （二）代理签发他行银行汇票，并由他行兑付。 代理行是代理签发他行银行汇票或代理兑付他行银行汇票的银行。 被代理行是委托他行代理本行签发银行汇票的银行，或委托他行代理兑付本行签发银行汇票的银行。"},{"i":12,"n":"第十二条","txt":"代理签发银行汇票和委托他行代理兑付银行汇票的，应采取全额移存汇票资金的方式。 银行汇票移存资金不计付利息。"},{"i":13,"n":"第十三条","txt":"具有签发银行汇票资格的银行，可以采取签发本行银行汇票并委托他行代理兑付的方式。 不具有签发银行汇票资格的银行，可以采取代理签发他行银行汇票并由他行兑付的方式。"},{"i":14,"n":"第十四条","txt":"代理签发他行银行汇票的银行，必须具备以下条件： （一）内部管理完善，内控制度健全； （二）经营状况较好，无重大违规违纪行为； （三）信誉良好，在人民银行存有充足的准备金，能保证及时移存签发银行汇票的资金。"},{"i":15,"n":"第十五条","txt":"银行汇票业务的代理行与被代理行必须签订书面代理协议，明确双方的权利和义务。"},{"i":16,"n":"第十六条","txt":"银行汇票业务代理协议的签订。 （一）采用签发本行银行汇票并委托他行代理兑付方式的，由被代理行总行与代理行总行签订代理协议，或者与代理行总行授权的分支行签订代理协议并报代理行总行备案。城市商业银行总部、外资银行、城市信用合作社和农村信用合作社县（市）联社可以与代理行当地分支行签订代理协议，并报代理行总行或其授权的分支行批准生效。 （二）采取代理签发他行银行汇票方式的，城市商业银行总部、外资银行、城市信用合作社和农村信用合作社县（市）联社与被代理行当地分支行签订代理协议，并报被代理行总行或其授权的分支行批准生效。"},{"i":17,"n":"第十七条","txt":"代理行与被代理行签订的代理协议必须报人民银行备案。实行签发本行银行汇票并委托他行代理兑付方式签订的代理协议，代理行总行应向人民银行总行备案；实行代理签发他行银行汇票方式签订的代理协议，被代理行分支行应向人民银行当地分支行备案。"},{"i":18,"n":"第十八条","txt":"银行汇票业务代理协议应订明以下主要条款： （一）银行汇票业务的代理方式； （二）代理行与被代理行的权利和义务； （三）银行汇票资金移存的方式； （四）代理业务手续费标准和付费方式； （五）违约责任。"},{"i":19,"n":"第十九条","txt":"签发本行银行汇票并委托他行代理兑付的银行，应履行以下职责： （一）按照支付结算制度规定签发银行汇票，并在签发的银行汇票凭证上加盖“请划付××银行××行号”戳记； （二）按照协议的规定将签发的银行汇票资金于当日至迟次日上午向代理行移存； （三）按照协议的规定将本行银行汇票票样、汇票专用章印模提供给代理行，并向代理行购置编押机具； （四）按照规定的费率和约定的付费方式向代理行支付代理业务手续费； （五）将行名、行号、营业地址、邮政编码、电报挂号等变更事项及时通知代理行； （六）与代理行约定的其他事项。"},{"i":20,"n":"第二十条","txt":"代理签发他行银行汇票的银行，应履行以下职责： （一）按照支付结算制度的规定签发银行汇票； （二）向被代理行购置被代理行的银行汇票凭证、银行汇票专用章、编押机具，并按照支付结算制度和被代理行的要求，实行严格的安全管理； （三）按照协议的规定将签发的银行汇票资金于当日至迟次日上午向被代理行移存； （四）按照规定的费率和约定的付费方式向被代理行支付代理业务手续费； （五）将行名、行号、营业地址、邮政编码、电报挂号等变更事项及时通知被代理行； （六）与被代理行约定的其他事项。"},{"i":21,"n":"第二十一条","txt":"代理兑付他行银行汇票的银行，应履行以下职责： （一）对被代理行签发的银行汇票，按照支付结算制度规定审核，及时兑付和清算； （二）对被代理行签发银行汇票的资金移存情况进行检查，并及时与被代理行进行账务核对； （三）与被代理行约定的其他事项。"},{"i":22,"n":"第二十二条","txt":"委托他行签发本行银行汇票的银行，应履行以下职责： （一）向代理行配售银行汇票凭证、汇票专用章和编押机具，并对代理行有关人员进行业务培训辅导； （二）对代理行签发的银行汇票，按照支付结算制度的规定审核兑付，并及时与代理行进行资金清算和账务核对； （三）按照支付结算制度和协议的规定，对代理行签发银行汇票、资金移存以及印、押、证安全管理情况进行检查； （四）与代理行约定的其他事项。"},{"i":23,"n":"第二十三条","txt":"其他支付结算业务的代理，是指被代理行委托代理行办理汇兑、委托收款、托收承付结算的行为。"},{"i":24,"n":"第二十四条","txt":"其他支付结算业务代理的方式，分为规定代理和约定代理。 规定代理是指银行之间根据支付结算制度的规定而产生的代理。 约定代理是指银行之间根据双方签订的协议而产生的代理。"},{"i":25,"n":"第二十五条","txt":"建立行内异地联行系统的银行之间应实行规定代理。 城市商业银行、外资银行、城市信用合作社、农村信用合作社可以与建立行内异地联行系统的银行实行约定代理。"},{"i":26,"n":"第二十六条","txt":"实行规定代理的，应执行中国人民银行支付结算制度的规定，不需签订代理协议。 实行约定代理的，应按照本办法的规定签订代理协议。"},{"i":27,"n":"第二十七条","txt":"银行之间的代理协议，可以由被代理行与代理行当地分支行签订。"},{"i":28,"n":"第二十八条","txt":"代理协议应订明以下主要条款： （一）代理业务种类； （二）代理行与被代理行的权利和义务； （三）资金清算方式； （四）代理业务手续费标准和付费方式； （五）违约责任。"},{"i":29,"n":"第二十九条","txt":"汇兑业务的代理是指被代理行委托代理行办理款项汇出和汇入的行为。 委托收款、托收承付业务的代理是指被代理行委托代理行将其托收的款项划回本行的行为。"},{"i":30,"n":"第三十条","txt":"汇兑、委托收款、托收承付代理业务的被代理行，应履行以下职责： （一）在人民银行开立准备金存款账户或在代理行开立同业往来账户，并存有足够资金保证清算； （二）按照支付结算制度的规定审核支付结算凭证和填制有关凭证； （三）按照规定费率和约定的付费方式支付代理费用。"},{"i":31,"n":"第三十一条","txt":"汇兑业务的代理行，应按照支付结算制度的规定于受理当日至迟次日上午将款项汇出，并及时将款项收入汇兑凭证记载的收款人账户。"},{"i":32,"n":"第三十二条","txt":"委托收款、托收承付业务的代理行，应按照支付结算制度的规定审核，将付款人支付的款项划回并收入被代理行的账户，同时将有关结算凭证转交被代理行。"},{"i":33,"n":"第三十三条","txt":"因机构迁址、撤并或其他原因，代理行与被代理行需要解除代理协议的，应比照本办法规定的签订协议的程序办理。"},{"i":34,"n":"第三十四条","txt":"代理签发银行汇票的代理行与被代理行解除代理协议的，代理行应即时将空白银行汇票凭证、汇票专用章、编押机具交还被代理行。 代理兑付银行汇票的代理行与被代理行解除代理协议的，代理行应将被代理行的银行汇票票样、汇票专用章印模及时销毁；被代理行应将代理行的编押机具交还代理行。"},{"i":35,"n":"第三十五条","txt":"代理协议双方应对移存的资金进行核对相符后，办理结清手续。"},{"i":36,"n":"第三十六条","txt":"代理协议当事人一方因对方违反协议的约定，需要解除代理协议的，应按照《中华人民共和国合同法》的有关规定办理。"},{"i":37,"n":"第三十七条","txt":"代理行与被代理行解除代理协议的，应向原备案行备案。"},{"i":38,"n":"第三十八条","txt":"支付结算业务代理实行有偿代理。代理费用的标准应根据代理业务的成本、风险以及支付给有关部门的费用确定。"},{"i":39,"n":"第三十九条","txt":"代理费用按照以下标准支付和收取： （一）采用委托他行代理兑付银行汇票方式的，被代理行应按实际兑付金额的0.2—0.3‰向代理行支付手续费。每笔不足2元的，按2元支付。 （二）采用代理签发他行银行汇票方式的，代理行应按签发金额的0.3—0.5‰向被代理行支付手续费，每笔不足3元的，按3元支付，并按支付结算制度规定的凭证工本费收费标准，向被代理行支付凭证工本费。 （三）委托他行代理汇兑、委托收款、托收承付业务，实行规定代理的，被代理行暂按支付结算制度的规定，向代理行支付50%的手续费和100%的邮电费。 （四）委托他行代理汇兑、委托收款、托收承付业务，实行约定代理的，被代理行应按支付结算制度规定的相应手续费和邮电费收费标准，向代理行支付200%的手续费和100%的邮电费。"},{"i":40,"n":"第四十条","txt":"代理费用可以实行定期支付或逐笔支付的方式，具体方式由代理行与被代理行协商确定。"},{"i":41,"n":"第四十一条","txt":"支付结算业务代理的当事人，不得擅自毁约、随意变更代理协议条款和拒绝履行义务，不得随意压票、无理退票和截留、挪用他行结算资金，不得随意提高、降低或变相改变收费标准和无故拖延支付代理手续费。"},{"i":42,"n":"第四十二条","txt":"支付结算业务代理一方未经双方协商同意，擅自毁约、变更代理协议条款和拒绝履行义务，给对方造成损失的，应依法承担民事责任。"},{"i":43,"n":"第四十三条","txt":"代理兑付他行银行汇票、代理他行办理汇兑、委托收款、托收承付业务，发生压票、无理退票，以及被代理行对代理行签发本行银行汇票发生无理退票的，应按照中国人民银行规定的存贷款利率以及压票、退票金额和天数向对方负责赔偿。"},{"i":44,"n":"第四十四条","txt":"代理行或被代理行在代理业务中，截留、挪用他行结算资金的，除负责纠正外，应按照银行同业往来利率以及截留、挪用的金额和天数向对方负责赔偿。"},{"i":45,"n":"第四十五条","txt":"代理行或被代理行随意提高或降低代理手续费收费标准的，除必须纠正外，应将多收的费用返还，少收的费用应予追回。"},{"i":46,"n":"第四十六条","txt":"代理行或被代理行未按规定移存汇票资金的，应按未移存金额和延误天数支付万分之七违约金；未按规定支付手续费的，应按延付手续费金额和延误天数支付万分之五违约金。"},{"i":47,"n":"第四十七条","txt":"代理签发他行银行汇票的银行，违反支付结算制度的规定和代理协议的条款而发生印、押、证丢失，造成被代理行资金损失的，应向被代理行负责赔偿。"},{"i":48,"n":"第四十八条","txt":"本办法由中国人民银行负责解释和修改。"},{"i":49,"n":"第四十九条","txt":"本办法自2000年7月1日起施行。"}],"zhifujiesuanbanfa":[{"i":1,"n":"第一条","txt":"为了规范支付结算行为，保障支付结算活动中当事人的合法权益，加速资金周转和商品流通，促进社会主义市场经济的发展，依据《中华人民共和国票据法》（以下简称《票据法》）和《票据管理实施办法》以及有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内人民币的支付结算适用本办法，但中国人民银行另有规定的除外。"},{"i":3,"n":"第三条","txt":"本办法所称支付结算是指单位、个人在社会经济活动中使用票据、信用卡和汇兑、托收承付、委托收款等结算方式进行货币给付及其资金清算的行为。"},{"i":4,"n":"第四条","txt":"支付结算工作的任务，是根据经济往来组织支付结算，准确、及时、安全办理支付结算，按照有关法律、行政法规和本办法的规定管理支付结算，保障支付结算活动的正常进行。"},{"i":5,"n":"第五条","txt":"银行、城市信用合作社、农村信用合作社（以下简称银行）以及单位和个人（含个体工商户），办理支付结算必须遵守国家的法律、行政法规和本办法的各项规定，不得损害社会公共利益。"},{"i":6,"n":"第六条","txt":"银行是支付结算和资金清算的中介机构。未经中国人民银行批准的非银行金融机构和其他单位不得作为中介机构经营支付结算业务。但法律、行政法规另有规定的除外。"},{"i":7,"n":"第七条","txt":"单位、个人和银行应当按照《银行帐户管理办法》的规定开立、使用帐户。"},{"i":8,"n":"第八条","txt":"在银行开立存款帐户的单位和个人办理支付结算，帐户内须有足够的资金保证支付，本办法另有规定的除外。没有开立存款帐户的个人向银行交付款项后，也可以通过银行办理支付结算。"},{"i":9,"n":"第九条","txt":"票据和结算凭证是办理支付结算的工具。单位、个人和银行办理支付结算，必须使用按中国人民银行统一规定印制的票据凭证和统一规定的结算凭证。 未使用按中国人民银行统一规定印制的票据，票据无效；未使用中国人民银行统一规定格式的结算凭证，银行不予受理。"},{"i":10,"n":"第十条","txt":"单位、个人和银行签发票据、填写结算凭证，应按照本办法和附一《正确填写票据和结算凭证的基本规定》记载，单位和银行的名称应当记载全称或者规范化简称。"},{"i":11,"n":"第十一条","txt":"票据和结算凭证上的签章，为签名、盖章或者签名加盖章。 单位、银行在票据上的签章和单位在结算凭证上的签章，为该单位、银行的盖章加其法定代表人或其授权的代理人的签名或盖章。 个人在票据和结算凭证上的签章，应为该个人本名的签名或盖章。"},{"i":12,"n":"第十二条","txt":"票据和结算凭证的金额、出票或签发日期、收款人名称不得更改，更改的票据无效；更改的结算凭证，银行不予受理。 对票据和结算凭证上的其他记载事项，原记载人可以更改，更改时应当由原记载人在更改处签章证明。"},{"i":13,"n":"第十三条","txt":"票据和结算凭证金额以中文大写和阿拉伯数码同时记载，二者必须一致，二者不一致的票据无效；二者不一致的结算凭证，银行不予受理。 少数民族地区和外国驻华使领馆根据实际需要，金额大写可以使用少数民族文字或者外国文字记载。"},{"i":14,"n":"第十四条","txt":"票据和结算凭证上的签章和其他记载事项应当真实，不得伪造、变造。 票据上有伪造、变造的签章的，不影响票据上其他当事人真实签章的效力。 本条所称的伪造是指无权限人假冒他人或虚构人名义签章的行为。签章的变造属于伪造。 本条所称的变造是指无权更改票据内容的人，对票据上签章以外的记载事项加以改变的行为。"},{"i":15,"n":"第十五条","txt":"办理支付结算需要交验的个人有效身份证件是指居民身份证、军官证、警官证、文职干部证、士兵证、户口簿、护照、港澳台同胞回乡证等符合法律、行政法规以及国家有关规定的身份证件。"},{"i":16,"n":"第十六条","txt":"单位、个人和银行办理支付结算必须遵守下列原则： 一、恪守信用，履约付款； 二、谁的钱进谁的帐，由谁支配； 三、银行不垫款。"},{"i":17,"n":"第十七条","txt":"银行以善意且符合规定和正常操作程序审查，对伪造、变造的票据和结算凭证上的签章以及需要交验的个人有效身份证件，未发现异常而支付金额的，对出票人或付款人不再承担受委托付款的责任，对持票人或收款人不再承担付款的责任。"},{"i":18,"n":"第十八条","txt":"依法背书转让的票据，任何单位和个人不得冻结票据款项。但是法律另有规定的除外。"},{"i":19,"n":"第十九条","txt":"银行依法为单位、个人在银行开立的基本存款帐户、一般存款帐户、专用存款帐户和临时存款帐户的存款保密，维护其资金的自主支配权。对单位、个人在银行开立上述存款帐户的存款，除国家法律、行政法规另有规定外，银行不得为任何单位或者个人查询；除国家法律另有规定外，银行不代任何单位或者个人冻结、扣款，不得停止单位、个人存款的正常支付。"},{"i":20,"n":"第二十条","txt":"支付结算实行集中统一和分级管理相结合的管理体制。 中国人民银行总行负责制定统一的支付结算制度，组织、协调、管理、监督全国的支付结算工作，调解、处理银行之间的支付结算纠纷。 中国人民银行省、自治区、直辖市分行根据统一的支付结算制度制定实施细则，报总行备案；根据需要可以制定单项支付结算办法，报经中国人民银行总行批准后执行。中国人民银行分、支行负责组织、协调、管理、监督本辖区的支付结算工作，调解、处理本辖区银行之间的支付结算纠纷。 政策性银行、商业银行总行可以根据统一的支付结算制度，结合本行情况，制定具体管理实施办法，报经中国人民银行总行批准后执行。政策性银行、商业银行负责组织、管理、协调本行内的支付结算工作，调解、处理本行内分支机构之间的支付结算纠纷。"},{"i":21,"n":"第二十一条","txt":"本办法所称票据，是指银行汇票、商业汇票、银行本票和支票。"},{"i":22,"n":"第二十二条","txt":"票据的签发、取得和转让，必须具有真实的交易关系和债权债务关系。 票据的取得，必须给付对价。但因税收、继承、赠与可以依法无偿取得票据的，不受给付对价的限制。"},{"i":23,"n":"第二十三条","txt":"银行汇票的出票人在票据上的签章，应为经中国人民银行批准使用的该银行汇票专用章加其法定代表人或其授权经办人的签名或者盖章。银行承兑商业汇票、办理商业汇票转贴现、再贴现时的签章，应为经中国人民银行批准使用的该银行汇票专用章加其法定代表人或其授权经办人的签名或者盖章。银行本票的出票人在票据上的签章，应为经中国人民银行批准使用的该银行本票专用章加其法定代表人或其授权经办人的签名或者盖章。 单位在票据上的签章，应为该单位的财务专用章或者公章加其法定代表人或其授权的代理人的签名或者盖章。个人在票据上的签章，应为该个人的签名或者盖章。 支票的出票人和商业承兑汇票的承兑人在票据上的签章，应为其预留银行的签章。"},{"i":24,"n":"第二十四条","txt":"出票人在票据上的签章不符合《票据法》、《票据管理实施办法》和本办法规定的，票据无效；承兑人、保证人在票据上的签章不符合《票据法》、《票据管理实施办法》和本办法规定的，其签章无效，但不影响其他符合规定签章的效力；背书人在票据上的签章不符合《票据法》、《票据管理实施办法》和本办法规定的，其签章无效，但不影响其前手符合规定签章的效力。"},{"i":25,"n":"第二十五条","txt":"出票人在票据上的记载事项必须符合《票据法》、《票据管理实施办法》和本办法的规定。票据上可以记载《票据法》和本办法规定事项以外的其他出票事项，但是该记载事项不具有票据上的效力，银行不负审查责任。"},{"i":26,"n":"第二十六条","txt":"区域性银行汇票仅限于出票人向本区域内的收款人出票，银行本票和支票仅限于出票人向其票据交换区域内的收款人出票。"},{"i":27,"n":"第二十七条","txt":"票据可以背书转让，但填明“现金”字样的银行汇票、银行本票和用于支取现金的支票不得背书转让。 区域性银行汇票仅限于在本区域内背书转让。银行本票、支票仅限于在其票据交换区域内背书转让。"},{"i":28,"n":"第二十八条","txt":"区域性银行汇票和银行本票、支票出票人向规定区域以外的收款人出票的，背书人向规定区域以外的被背书人转让票据的，区域外的银行不予受理，但出票人、背书人仍应承担票据责任。"},{"i":29,"n":"第二十九条","txt":"票据背书转让时，由背书人在票据背面签章、记载被背书人名称和背书日期。背书未记载日期的，视为在票据到期日前背书。 持票人委托银行收款或以票据质押的，除按上款规定记载背书外，还应在背书人栏记载“委托收款”或“质押”字样。"},{"i":30,"n":"第三十条","txt":"票据出票人在票据正面记载“不得转让”字样的，票据不得转让；其直接后手再背书转让的，出票人对其直接后手的被背书人不承担保证责任，对被背书人提示付款或委托收款的票据，银行不予受理。 票据背书人在票据背面背书人栏记载“不得转让”字样的，其后手再背书转让的，记载“不得转让”字样的背书人对其后手的被背书人不承担保证责任。"},{"i":31,"n":"第三十一条","txt":"票据被拒绝承兑、拒绝付款或者超过付款提示期限的，不得背书转让。背书转让的，背书人应当承担票据责任。"},{"i":32,"n":"第三十二条","txt":"背书不得附有条件。背书附有条件的，所附条件不具有票据上的效力。"},{"i":33,"n":"第三十三条","txt":"以背书转让的票据，背书应当连续。持票人以背书的连续，证明其票据权利。非经背书转让，而以其他合法方式取得票据的，依法举证，证明其票据权利。 背书连续，是指票据第一次背书转让的背书人是票据上记载的收款人，前次背书转让的被背书人是后一次背书转让的背书人，依次前后衔接，最后一次背书转让的被背书人是票据的最后持票人。"},{"i":34,"n":"第三十四条","txt":"票据的背书人应当在票据背面的背书栏依次背书。背书栏不敷背书的，可以使用统一格式的粘单，粘附于票据凭证上规定的粘接处。粘单上的第一记载人，应当在票据和粘单的粘接处签章。"},{"i":35,"n":"第三十五条","txt":"银行汇票、商业汇票和银行本票的债务可以依法由保证人承担保证责任。 保证人必须按照《票据法》的规定在票据上记载保证事项。保证人为出票人、承兑人保证的，应将保证事项记载在票据的正面；保证人为背书人保证的，应将保证事项记载在票据的背面或粘单上。"},{"i":36,"n":"第三十六条","txt":"商业汇票的持票人超过规定期限提示付款的，丧失对其前手的追索权，持票人在作出说明后，仍可以向承兑人请求付款。 银行汇票、银行本票的持票人超过规定期限提示付款的，丧失对出票人以外的前手的追索权，持票人在作出说明后，仍可以向出票人请求付款。 支票的持票人超过规定的期限提示付款的，丧失对出票人以外的前手的追索权。"},{"i":37,"n":"第三十七条","txt":"通过委托收款银行或者通过票据交换系统向付款人或代理付款人提示付款的，视同持票人提示付款；其提示付款日期以持票人向开户银行提交票据日为准。 付款人或代理付款人应于见票当日足额付款。 本条所称“代理付款人”是指根据付款人的委托，代理其支付票据金额的银行。"},{"i":38,"n":"第三十八条","txt":"票据债务人对下列情况的持票人可以拒绝付款： （一）对不履行约定义务的与自己有直接债权债务关系的持票人； （二）以欺诈、偷盗或者胁迫等手段取得票据的持票人； （三）对明知有欺诈、偷盗或者胁迫等情形，出于恶意取得票据的持票人； （四）明知债务人与出票人或者持票人的前手之间存在抗辩事由而取得票据的持票人； （五）因重大过失取得不符合《票据法》规定的票据的持票人； （六）对取得背书不连续票据的持票人； （七）符合《票据法》规定的其他抗辩事由。"},{"i":39,"n":"第三十九条","txt":"票据债务人对下列情况不得拒绝付款： （一）与出票人之间有抗辩事由； （二）与持票人的前手之间有抗辩事由。"},{"i":40,"n":"第四十条","txt":"票据到期被拒绝付款或者在到期前被拒绝承兑，承兑人或付款人死亡、逃匿的，承兑人或付款人被依法宣告破产的或者因违法被责令终止业务活动的，持票人可以对背书人、出票人以及票据的其他债务人行使追索权。 持票人行使追索权，应当提供被拒绝承兑或者被拒绝付款的拒绝证明或者退票理由书以及其他有关证明。"},{"i":41,"n":"第四十一条","txt":"本办法所称“拒绝证明”应当包括下列事项： （一）被拒绝承兑、付款的票据种类及其主要记载事项； （二）拒绝承兑、付款的事实依据和法律依据； （三）拒绝承兑、付款的时间； （四）拒绝承兑人、拒绝付款人的签章。"},{"i":42,"n":"第四十二条","txt":"本办法所称退票理由书应当包括下列事项： （一）所退票据的种类； （二）退票的事实依据和法律依据； （三）退票时间； （四）退票人签章。"},{"i":43,"n":"第四十三条","txt":"本办法所称的其他证明是指： （一）医院或者有关单位出具的承兑人、付款人死亡证明； （二）司法机关出具的承兑人、付款人逃匿的证明； （三）公证机关出具的具有拒绝证明效力的文书。"},{"i":44,"n":"第四十四条","txt":"持票人应当自收到被拒绝承兑或者被拒绝付款的有关证明之日起３日内，将被拒绝事由书面通知其前手；其前手应当自收到通知之日起３日内书面通知其再前手。持票人也可以同时向各票据债务人发出书面通知。 未按照前款规定期限通知的，持票人仍可以行使追索权。"},{"i":45,"n":"第四十五条","txt":"持票人可以不按照票据债务人的先后顺序，对其中任何一人、数人或者全体行使追索权。 持票人对票据债务人中的一人或者数人已经进行追索的，对其他票据债务人仍可以行使追索权。被追索人清偿债务后，与持票人享有同一权利。"},{"i":46,"n":"第四十六条","txt":"持票人行使追索权，可以请求被追索人支付下列金额和费用： （一）被拒绝付款的票据金额； （二）票据金额自到期日或者提示付款日起至清偿日止按照中国人民银行规定的同档次流动资金贷款利率计算的利息。 （三）取得有关拒绝证明和发出通知书的费用。 被追索人清偿债务时，持票人应当交出票据和有关拒绝证明，并出具所收到利息和费用的收据。"},{"i":47,"n":"第四十七条","txt":"被追索人依照前条规定清偿后，可以向其他票据债务人行使再追索权，请求其他票据债务人支付下列金额和费用： （一）已清偿的全部金额； （二）前项金额自清偿日起至再追索清偿日止，按照中国人民银行规定的同档次流动资金贷款利率计算的利息； （三）发出通知书的费用。 行使再追索权的被追索人获得清偿时，应当交出票据和有关拒绝证明，并出具所收到利息和费用的收据。"},{"i":48,"n":"第四十八条","txt":"已承兑的商业汇票、支票、填明“现金”字样和代理付款人的银行汇票以及填明“现金”字样的银行本票丧失，可以由失票人通知付款人或者代理付款人挂失止付。 未填明“现金”字样和代理付款人的银行汇票以及未填明“现金”字样的银行本票丧失，不得挂失止付。"},{"i":49,"n":"第四十九条","txt":"允许挂失止付的票据丧失，失票人需要挂失止付的，应填写挂失止付通知书并签章。挂失止付通知书应当记载下列事项： （一）票据丧失的时间、地点、原因； （二）票据的种类、号码、金额、出票日期、付款日期、付款人名称、收款人名称； （三）挂失止付人的姓名、营业场所或者住所以及联系方法。 欠缺上述记载事项之一的，银行不予受理。"},{"i":50,"n":"第五十条","txt":"付款人或者代理付款人收到挂失止付通知书后，查明挂失票据确未付款时，应立即暂停支付。付款人或者代理付款人自收到挂失止付通知书之日起１２日内没有收到人民法院的止付通知书的，自第１３日起，持票人提示付款并依法向持票人付款的，不再承担责任。"},{"i":51,"n":"第五十一条","txt":"付款人或者代理付款人在收到挂失止付通知书之前，已经向持票人付款的，不再承担责任。但是，付款人或者代理付款人以恶意或者重大过失付款的除外。"},{"i":52,"n":"第五十二条","txt":"银行汇票的付款地为代理付款人或出票人所在地，银行本票的付款地为出票人所在地，商业汇票的付款地为承兑人所在地，支票的付款地为付款人所在地。"},{"i":53,"n":"第五十三条","txt":"银行汇票是出票银行签发的，由其在见票时按照实际结算金额无条件支付给收款人或者持票人的票据。 银行汇票的出票银行为银行汇票的付款人。"},{"i":54,"n":"第五十四条","txt":"单位和个人各种款项结算，均可使用银行汇票。 银行汇票可以用于转帐，填明“现金”字样的银行汇票也可以用于支取现金。"},{"i":55,"n":"第五十五条","txt":"银行汇票的出票和付款，全国范围限于中国人民银行和各商业银行参加“全国联行往来”的银行机构办理。跨系统银行签发的转帐银行汇票的付款，应通过同城票据交换将银行汇票和解讫通知提交给同城的有关银行审核支付后抵用。代理付款人不得受理未在本行开立存款帐户的持票人为单位直接提交的银行汇票。省、自治区、直辖市内和跨省、市的经济区域内银行汇票的出票和付款，按照有关规定办理。 银行汇票的代理付款人是代理本系统出票银行或跨系统签约银行审核支付汇票款项的银行。"},{"i":56,"n":"第五十六条","txt":"签发银行汇票必须记载下列事项： （一）表明“银行汇票”的字样； （二）无条件支付的承诺； （三）出票金额； （四）付款人名称； （五）收款人名称； （六）出票日期； （七）出票人签章。 欠缺记载上列事项之一的，银行汇票无效。"},{"i":57,"n":"第五十七条","txt":"银行汇票的提示付款期限自出票日起１个月。 持票人超过付款期限提示付款的，代理付款人不予受理。"},{"i":58,"n":"第五十八条","txt":"申请人使用银行汇票，应向出票银行填写“银行汇票申请书”，填明收款人名称、汇票金额、申请人名称、申请日期等事项并签章，签章为其预留银行的签章。 申请人和收款人均为个人，需要使用银行汇票向代理付款人支取现金的，申请人须在“银行汇票申请书”上填明代理付款人名称，在“汇票金额”栏先填写“现金”字样，后填写汇票金额。 申请人或者收款人为单位的，不得在“银行汇票申请书”上填明“现金”字样。"},{"i":59,"n":"第五十九条","txt":"出票银行受理银行汇票申请书，收妥款项后签发银行汇票，并用压数机压印出票金额，将银行汇票和解讫通知一并交给申请人。 签发转帐银行汇票，不得填写代理付款人名称，但由人民银行代理兑付银行汇票的商业银行，向设有分支机构地区签发转帐银行汇票的除外。 签发现金银行汇票，申请人和收款人必须均为个人，收妥申请人交存的现金后，在银行汇票“出票金额”栏先填写“现金”字样，后填写出票金额，并填写代理付款人名称。申请人或者收款人为单位的，银行不得为其签发现金银行汇票。"},{"i":60,"n":"第六十条","txt":"申请人应将银行汇票和解讫通知一并交付给汇票上记明的收款人。 收款人受理银行汇票时，应审查下列事项： （一）银行汇票和解讫通知是否齐全、汇票号码和记载的内容是否一致； （二）收款人是否确为本单位或本人； （三）银行汇票是否在提示付款期限内； （四）必须记载的事项是否齐全； （五）出票人签章是否符合规定，是否有压数机压印的出票金额，并与大写出票金额一致； （六）出票金额、出票日期、收款人名称是否更改，更改的其他记载事项是否由原记载人签章证明。"},{"i":61,"n":"第六十一条","txt":"收款人受理申请人交付的银行汇票时，应在出票金额以内，根据实际需要的款项办理结算，并将实际结算金额和多余金额准确、清晰地填入银行汇票和解讫通知的有关栏内。未填明实际结算金额和多余金额或实际结算金额超过出票金额的，银行不予受理。"},{"i":62,"n":"第六十二条","txt":"银行汇票的实际结算金额不得更改，更改实际结算金额的银行汇票无效。"},{"i":63,"n":"第六十三条","txt":"收款人可以将银行汇票背书转让给被背书人。 银行汇票的背书转让以不超过出票金额的实际结算金额为准。未填写实际结算金额或实际结算金额超过出票金额的银行汇票不得背书转让。"},{"i":64,"n":"第六十四条","txt":"被背书人受理银行汇票时，除按照第六十条的规定审查外，还应审查下列事项： （一）银行汇票是否记载实际结算金额，有无更改，其金额是否超过出票金额； （二）背书是否连续，背书人签章是否符合规定，背书使用粘单的是否按规定签章； （三）背书人为个人的身份证件。"},{"i":65,"n":"第六十五条","txt":"持票人向银行提示付款时，必须同时提交银行汇票和解讫通知，缺少任何一联，银行不予受理。"},{"i":66,"n":"第六十六条","txt":"在银行开立存款帐户的持票人向开户银行提示付款时，应在汇票背面“持票人向银行提示付款签章”处签章，签章须与预留银行签章相同，并将银行汇票和解讫通知、进帐单送交开户银行。银行审查无误后办理转帐。"},{"i":67,"n":"第六十七条","txt":"未在银行开立存款帐户的个人持票人，可以向选择的任何一家银行机构提示付款。提示付款时，应在汇票背面“持票人向银行提示付款签章”处签章，并填明本人身份证件名称、号码及发证机关，由其本人向银行提交身份证件及其复印件。银行审核无误后，将其身份证件复印件留存备查，并以持票人的姓名开立应解汇款及临时存款帐户，该帐户只付不收，付完清户，不计付利息。 转帐支付的，应由原持票人向银行填制支款凭证，并由本人交验其身份证件办理支付款项。该帐户的款项只能转入单位或个体工商户的存款帐户，严禁转入储蓄和信用卡帐户。 支取现金的，银行汇票上必须有出票银行按规定填明的“现金”字样，才能办理。未填明“现金”字样，需要支取现金的，由银行按照国家现金管理规定审查支付。 持票人对填明“现金”字样的银行汇票，需要委托他人向银行提示付款的，应在银行汇票背面背书栏签章，记载“委托收款”字样、被委托人姓名和背书日期以及委托人身份证件"},{"i":68,"n":"第六十八条","txt":"银行汇票的实际结算金额低于出票金额的，其多余金额由出票银行退交申请人。"},{"i":69,"n":"第六十九条","txt":"持票人超过期限向代理付款银行提示付款不获付款的，须在票据权利时效内向出票银行作出说明，并提供本人身份证件或单位证明，持银行汇票和解讫通知向出票银行请求付款。"},{"i":70,"n":"第七十条","txt":"申请人因银行汇票超过付款提示期限或其他原因要求退款时，应将银行汇票和解讫通知同时提交到出票银行。申请人为单位的，应出具该单位的证明；申请人为个人的，应出具该本人的身份证件。对于代理付款银行查询的该张银行汇票，应在汇票提示付款期满后方能办理退款。出票银行对于转帐银行汇票的退款，只能转入原申请人帐户；对于符合规定填明“现金”字样银行汇票的退款，才能退付现金。 申请人缺少解讫通知要求退款的，出票银行应于银行汇票提示付款期满一个月后办理。"},{"i":71,"n":"第七十一条","txt":"银行汇票丧失，失票人可以凭人民法院出具的其享有票据权利的证明，向出票银行请求付款或退款。"},{"i":72,"n":"第七十二条","txt":"商业汇票是出票人签发的，委托付款人在指定日期无条件支付确定的金额给收款人或者持票人的票据。"},{"i":73,"n":"第七十三条","txt":"商业汇票分为商业承兑汇票和银行承兑汇票。 商业承兑汇票由银行以外的付款人承兑。 银行承兑汇票由银行承兑。 商业汇票的付款人为承兑人。"},{"i":74,"n":"第七十四条","txt":"在银行开立存款帐户的法人以及其他组织之间，必须具有真实的交易关系或债权债务关系，才能使用商业汇票。"},{"i":75,"n":"第七十五条","txt":"商业承兑汇票的出票人，为在银行开立存款帐户的法人以及其他组织，与付款人具有真实的委托付款关系，具有支付汇票金额的可靠资金来源。"},{"i":76,"n":"第七十六条","txt":"银行承兑汇票的出票人必须具备下列条件： （一）在承兑银行开立存款帐户的法人以及其他组织； （二）与承兑银行具有真实的委托付款关系； （三）资信状况良好，具有支付汇票金额的可靠资金来源。"},{"i":77,"n":"第七十七条","txt":"出票人不得签发无对价的商业汇票用以骗取银行或者其他票据当事人的资金。"},{"i":78,"n":"第七十八条","txt":"签发商业汇票必须记载下列事项： （一）表明“商业承兑汇票”或“银行承兑汇票”的字样； （二）无条件支付的委托； （三）确定的金额； （四）付款人名称； （五）收款人名称； （六）出票日期； （七）出票人签章。 欠缺记载上列事项之一的，商业汇票无效。"},{"i":79,"n":"第七十九条","txt":"商业承兑汇票可以由付款人签发并承兑，也可以由收款人签发交由付款人承兑。 银行承兑汇票应由在承兑银行开立存款帐户的存款人签发。"},{"i":80,"n":"第八十条","txt":"商业汇票可以在出票时向付款人提示承兑后使用，也可以在出票后先使用再向付款人提示承兑。 定日付款或者出票后定期付款的商业汇票，持票人应当在汇票到期日前向付款人提示承兑。见票后定期付款的汇票，持票人应当自出票日起１个月内向付款人提示承兑。 汇票未按照规定期限提示承兑的，持票人丧失对其前手的追索权。"},{"i":81,"n":"第八十一条","txt":"商业汇票的付款人接到出票人或持票人向其提示承兑的汇票时，应当向出票人或持票人签发收到汇票的回单，记明汇票提示承兑日期并签章。付款人应当在自收到提示承兑的汇票之日起３日内承兑或者拒绝承兑。 付款人拒绝承兑的，必须出具拒绝承兑的证明。"},{"i":82,"n":"第八十二条","txt":"商业汇票的承兑银行，必须具备下列条件： （一）与出票人具有真实的委托付款关系； （二）具有支付汇票金额的可靠资金； （三）内部管理完善，经其法人授权的银行审定。"},{"i":83,"n":"第八十三条","txt":"银行承兑汇票的出票人或持票人向银行提示承兑时，银行的信贷部门负责 （三）内部管理完善，经其法人授权的银行审定。"},{"i":84,"n":"第八十三条","txt":"银行承兑汇票的出票人或持票人向银行提示承兑时，银行的信贷部门负责按照有关规定和审批程序，对出票人的资格、资信、购销合同和汇票记载的内容进行认真审查，必要时可由出票人提供担保。符合规定和承兑条件的，与出票人签订承兑协议。"},{"i":85,"n":"第八十四条","txt":"付款人承兑商业汇票，应当在汇票正面记载“承兑”字样和承兑日期并签章。"},{"i":86,"n":"第八十五条","txt":"付款人承兑商业汇票，不得附有条件；承兑附有条件的，视为拒绝承兑。"},{"i":87,"n":"第八十六条","txt":"银行承兑汇票的承兑银行，应按票面金额向出票人收取万分之五的手续费。"},{"i":88,"n":"第八十七条","txt":"商业汇票的付款期限，最长不得超过６个月。 定日付款的汇票付款期限自出票日起计算，并在汇票上记载具体的到期日。 出票后定期付款的汇票付款期限自出票日起按月计算，并在汇票上记载。 见票后定期付款的汇票付款期限自承兑或拒绝承兑日起按月计算，并在汇票上记载。"},{"i":89,"n":"第八十八条","txt":"商业汇票的提示付款期限，自汇票到期日起１０日。 持票人应在提示付款期限内通过开户银行委托收款或直接向付款人提示付款。对异地委托收款的，持票人可匡算邮程，提前通过开户银行委托收款。持票人超过提示付款期限提示付款的，持票人开户银行不予受理。"},{"i":90,"n":"第八十九条","txt":"商业承兑汇票的付款人开户银行收到通过委托收款寄来的商业承兑汇票，将商业承兑汇票留存，并及时通知付款人。 （一）付款人收到开户银行的付款通知，应在当日通知银行付款。付款人在接到通知日的次日起３日内（遇法定休假日顺延，下同）未通知银行付款的，视同付款人承诺付款，银行应于付款人接到通知日的次日起第４日（法定休假日顺延，下同）上午开始营业时，将票款划给持票人。 付款人提前收到由其承兑的商业汇票，应通知银行于汇票到期日付款。付款人在接到通知日的次日起３日内未通知银行付款，付款人接到通知日的次日起第４日在汇票到期日之前的，银行应于汇票到期日将票款划给持票人。 （二）银行在办理划款时，付款人存款帐户不足支付的，应填制付款人未付票款通知书，连同商业承兑汇票邮寄持票人开户银行转交持票人。 （三）付款人存在合法抗辩事由拒绝支付的，应自接到通知日的次日起３日内，作成拒绝付款证明送交开户银行，银行将拒绝付款证"},{"i":91,"n":"第九十条","txt":"银行承兑汇票的出票人应于汇票到期前将票款足额交存其开户银行。承兑银行应在汇票到期日或到期日后的见票当日支付票款。 承兑银行存在合法抗辩事由拒绝支付的，应自接到商业汇票的次日起３日内，作成拒绝付款证明，连同商业银行承兑汇票邮寄持票人开户银行转交持票人。"},{"i":92,"n":"第九十一条","txt":"银行承兑汇票的出票人于汇票到期日未能足额交存票款时，承兑银行除凭票向持票人无条件付款外，对出票人尚未支付的汇票金额按照每天万分之五计收利息。"},{"i":93,"n":"第九十二条","txt":"商业汇票的持票人向银行办理贴现必须具备下列条件： （一）在银行开立存款帐户的企业法人以及其他组织； （二）与出票人或者直接前手之间具有真实的商品交易关系； （三）提供与其直接前手之间的增值税发票和商品发运单据复印件。"},{"i":94,"n":"第九十三条","txt":"符合条件的商业汇票的持票人可持未到期的商业汇票连同贴现凭证向银行申请贴现。贴现银行可持未到期的商业汇票向其他银行转贴现，也可向中国人民银行申请再贴现。贴现、转贴现、再贴现时，应作成转让背书，并提供贴现申请人与其直接前手之间的增值税发票和商品发运单据复印件。"},{"i":95,"n":"第九十四条","txt":"贴现、转贴现和再贴现的期限从其贴现之日起至汇票到期日止。实付贴现金额按票面金额扣除贴现日至汇票到期前１日的利息计算。 承兑人在异地的，贴现、转贴现和再贴现的期限以及贴现利息的计算应另加３天的划款日期。"},{"i":96,"n":"第九十五条","txt":"贴现、转贴现、再贴现到期，贴现、转贴现、再贴现银行应向付款人收取票款。不获付款的，贴现、转贴现、再贴现银行应向其前手追索票款。贴现、再贴现银行追索票款时可从申请人的存款帐户收取票款。"},{"i":97,"n":"第九十六条","txt":"存款人领购商业汇票，必须填写“票据和结算凭证领用单”并签章，签章应与预留银行的签章相符。存款帐户结清时，必须将全部剩余空白商业汇票交回银行注销。"},{"i":98,"n":"第九十七条","txt":"银行本票是银行签发的，承诺自己在见票时无条件支付确定的金额给收款人或者持票人的票据。"},{"i":99,"n":"第九十八条","txt":"单位和个人在同一票据交换区域需要支付各种款项，均可以使用银行本票。 银行本票可以用于转帐，注明“现金”字样的银行本票可以用于支取现金。"},{"i":100,"n":"第九十九条","txt":"银行本票分为不定额本票和定额本票两种。"},{"i":101,"n":"第一百条","txt":"银行本票的出票人，为经中国人民银行当地分支行批准办理银行本票业务的银行机构。"},{"i":102,"n":"第一百零一条","txt":"签发银行本票必须记载下列事项： （一）表明“银行本票”的字样； （二）无条件支付的承诺； （三）确定的金额； （四）收款人名称； （五）出票日期； （六）出票人签章。 欠缺记载上列事项之一的，银行本票无效。"},{"i":103,"n":"第一百零二条","txt":"定额银行本票面额为１千元、５千元、１万元和５万元。"},{"i":104,"n":"第一百零三条","txt":"银行本票的提示付款期限自出票日起最长不得超过２个月。 持票人超过付款期限提示付款的，代理付款人不予受理。 银行本票的代理付款人是代理出票银行审核支付银行本票款项的银行。"},{"i":105,"n":"第一百零四条","txt":"申请人使用银行本票，应向银行填写“银行本票申请书”，填明收款人名称、申请人名称、支付金额、申请日期等事项并签章。申请人和收款人均为个人需要支取现金的，应在“支付金额”栏先填写“现金”字样，后填写支付金额。 申请人或收款人为单位的，不得申请签发现金银行本票。"},{"i":106,"n":"第一百零五条","txt":"出票银行受理银行本票申请书，收妥款项签发银行本票。用于转帐的，在银行本票上划去“现金”字样；申请人和收款人均为个人需要支取现金的，在银行本票上划去“转帐”字样。不定额银行本票用压数机压印出票金额。出票银行在银行本票上签章后交给申请人。 申请人或收款人为单位的，银行不得为其签发现金银行本票。"},{"i":107,"n":"第一百零六条","txt":"申请人应将银行本票交付给本票上记明的收款人。 收款人受理银行本票时，应审查下列事项： （一）收款人是否确为本单位或本人； （二）银行本票是否在提示付款期限内； （三）必须记载的事项是否齐全； （四）出票人签章是否符合规定，不定额银行本票是否有压数机压印的出票金额，并与大写出票金额一致； （五）出票金额、出票日期、收款人名称是否更改，更改的其他记载事项是否由原记载人签章证明。"},{"i":108,"n":"第一百零七条","txt":"收款人可以将银行本票背书转让给被背书人。 被背书人受理银行本票时，除按照第一百零六条的规定审查外，还应审查下列事项： （一）背书是否连续，背书人签章是否符合规定，背书使用粘单的是否按规定签章； （二）背书人为个人的身份证件。"},{"i":109,"n":"第一百零八条","txt":"银行本票见票即付。跨系统银行本票的兑付，持票人开户银行可根据中国人民银行规定的金融机构同业往来利率向出票银行收取利息。"},{"i":110,"n":"第一百零九条","txt":"在银行开立存款帐户的持票人向开户银行提示付款时，应在银行本票背面“持票人向银行提示付款签章”处签章，签章须与预留银行签章相同，并将银行本票、进帐单送交开户银行。银行审查无误后办理转帐。"},{"i":111,"n":"第一百一十条","txt":"未在银行开立存款帐户的个人持票人，凭注明“现金”字样的银行本票向出票银行支取现金的，应在银行本票背面签章，记载本人身份证件名称、号码及发证机关，并交验本人身份证件及其复印件。 持票人对注明“现金”字样的银行本票需要委托他人向出票银行提示付款的，应在银行本票背面“持票人向银行提示付款签章”处签章，记载“委托收款”字样、被委托人姓名和背书日期以及委托人身份证件名称、号码、发证机关。被委托人向出票银行提示付款时，也应在银行本票背面“持票人向银行提示付款签章”处签章，记载证件名称、号码及发证机关，并同时交验委托人和被委托人的身份证件及其复印件。"},{"i":112,"n":"第一百一十一条","txt":"持票人超过提示付款期限不获付款的，在票据权利时效内向出票银行作出说明，并提供本人身份证件或单位证明，可持银行本票向出票银行请求付款。"},{"i":113,"n":"第一百一十二条","txt":"申请人因银行本票超过提示付款期限或其他原因要求退款时，应将银行本票提交到出票银行，申请人为单位的，应出具该单位的证明；申请人为个人的，应出具该本人的身份证件。出票银行对于在本行开立存款帐户的申请人，只能将款项转入原申请人帐户；对于现金银行本票和未在本行开立存款帐户的申请人，才能退付现金。"},{"i":114,"n":"第一百一十三条","txt":"银行本票丧失，失票人可以凭人民法院出具的其享有票据权利的证明，向出票银行请求付款或退款。"},{"i":115,"n":"第一百一十四条","txt":"支票是出票人签发的，委托办理支票存款业务的银行在见票时无条件支付确定的金额给收款人或者持票人的票据。"},{"i":116,"n":"第一百一十五条","txt":"支票上印有“现金”字样的为现金支票，现金支票只能用于支取现金。 支票上印有“转帐”字样的为转帐支票，转帐支票只能用于转帐。 支票上未印有“现金”或“转帐”字样的为普通支票，普通支票可以用于支取现金，也可以用于转帐。在普通支票左上角划两条平行线的，为划线支票，划线支票只能用于转帐，不得支取现金。"},{"i":117,"n":"第一百一十六条","txt":"单位和个人在同一票据交换区域的各种款项结算，均可以使用支票。"},{"i":118,"n":"第一百一十七条","txt":"支票的出票人，为在经中国人民银行当地分支行批准办理支票业务的银行机构开立可以使用支票的存款帐户的单位和个人。"},{"i":119,"n":"第一百一十八条","txt":"签发支票必须记载下列事项： （一）表明“支票”的字样； （二）无条件支付的委托； （三）确定的金额； （四）付款人名称； （五）出票日期； （六）出票人签章。 欠缺记载上列事项之一的，支票无效。 支票的付款人为支票上记载的出票人开户银行。"},{"i":120,"n":"第一百一十九条","txt":"支票的金额、收款人名称，可以由出票人授权补记。未补记前不得背书转让和提示付款。"},{"i":121,"n":"第一百二十条","txt":"签发支票应使用炭素墨水或墨汁填写，中国人民银行另有规定的除外。"},{"i":122,"n":"第一百二十一条","txt":"签发现金支票和用于支取现金的普通支票，必须符合国家现金管理的规定。"},{"i":123,"n":"第一百二十二条","txt":"支票的出票人签发支票的金额不得超过付款时在付款人处实有的存款金额。禁止签发空头支票。"},{"i":124,"n":"第一百二十三条","txt":"支票的出票人预留银行签章是银行审核支票付款的依据。银行也可以与出票人约定使用支付密码，作为银行审核支付支票金额的条件。"},{"i":125,"n":"第一百二十四条","txt":"出票人不得签发与其预留银行签章不符的支票；使用支付密码的，出票人不得签发支付密码错误的支票。"},{"i":126,"n":"第一百二十五条","txt":"出票人签发空头支票、签章与预留银行签章不符的支票、使用支付密码地区，支付密码错误的支票，银行应予以退票，并按票面金额处以百分之五但不低于１千元的罚款；持票人有权要求出票人赔偿支票金额２％的赔偿金。对屡次签发的，银行应停止其签发支票。"},{"i":127,"n":"第一百二十六条","txt":"支票的提示付款期限自出票日起１０日，但中国人民银行另有规定的除外。超过提示付款期限提示付款的，持票人开户银行不予受理，付款人不予付款。"},{"i":128,"n":"第一百二十七条","txt":"持票人可以委托开户银行收款或直接向付款人提示付款。用于支取现金的支票仅限于收款人向付款人提示付款。 持票人委托开户银行收款的支票，银行应通过票据交换系统收妥后入帐。 持票人委托开户银行收款时，应作委托收款背书，在支票背面背书人签章栏签章、记载“委托收款”字样、背书日期，在被背书人栏记载开户银行名称，并将支票和填制的进帐单送交开户银行。持票人持用于转帐的支票向付款人提示付款时，应在支票背面背书人签章栏签章，并将支票和填制的进帐单交送出票人开户银行。收款人持用于支取现金的支票向付款人提示付款时，应在支票背面“收款人签章”处签章，持票人为个人的，还需交验本人身份证件，并在支票背面注明证件名称、号码及发证机关。"},{"i":129,"n":"第一百二十八条","txt":"出票人在付款人处的存款足以支付支票金额时，付款人应当在见票当日足额付款。"},{"i":130,"n":"第一百二十九条","txt":"存款人领购支票，必须填写“票据和结算凭证领用单”并签章，签章应与预留银行的签章相符。存款帐户结清时，必须将全部剩余空白支票交回银行注销。"},{"i":131,"n":"第一百三十条","txt":"信用卡是指商业银行向个人和单位发行的，凭以向特约单位购物、消费和向银行存取现金，且具有消费信用的特制载体卡片。"},{"i":132,"n":"第一百三十一条","txt":"信用卡按使用对象分为单位卡和个人卡；按信誉等级分为金卡和普通卡。"},{"i":133,"n":"第一百三十二条","txt":"商业银行（包括外资银行、合资银行）、非银行金融机构未经中国人民银行批准不得发行信用卡。 非金融机构、境外金融机构的驻华代表机构不得发行信用卡和代理收单结算业务。"},{"i":134,"n":"第一百三十三条","txt":"申请发行信用卡的银行、非银行金融机构，必须具备下列条件： （一）符合中国人民银行颁布的商业银行资产负债比例监控指标； （二）相应的管理机构； （三）合格的管理人员和技术人员； （四）健全的管理制度和安全制度； （五）必要的电信设备和营业场所； （六）中国人民银行规定的其它条件。"},{"i":135,"n":"第一百三十四条","txt":"商业银行、非银行金融机构开办信用卡业务须报经中国人民银行总行批准；其所属分、支机构开办信用卡业务，须报经辖区内中国人民银行分、支行备案。"},{"i":136,"n":"第一百三十五条","txt":"凡在中国境内金融机构开立基本存款帐户的单位可申领单位卡。单位卡可申领若干张，持卡人资格由申领单位法定代表人或其委托的代理人书面指定和注销。 凡具有完全民事行为能力的公民可申领个人卡。个人卡的主卡持卡人可为其配偶及年满１８周岁的亲属申领附属卡，申领的附属卡最多不得超过两张，也有权要求注销其附属卡。"},{"i":137,"n":"第一百三十六条","txt":"单位或个人申领信用卡，应按规定填制申请表，连同有关资料一并送交发卡银行。符合条件并按银行要求交存一定金额的备用金后，银行为申领人开立信用卡存款帐户，并发给信用卡。"},{"i":138,"n":"第一百三十七条","txt":"单位卡帐户的资金一律从其基本存款帐户转帐存入，不得交存现金，不得将销货收入的款项存入其帐户。 个人卡帐户的资金以其持有的现金存入或以其工资性款项及属于个人的劳务报酬收入转帐存入。严禁将单位的款项存入个人卡帐户。"},{"i":139,"n":"第一百三十八条","txt":"发卡银行可根据申请人的资信程度，要求其提供担保。担保的方式可采用保证、抵押或质押。"},{"i":140,"n":"第一百三十九条","txt":"信用卡备用金存款利息，按照中国人民银行规定的活期存款利率及计息办法计算。"},{"i":141,"n":"第一百四十条","txt":"信用卡仅限于合法持卡人本人使用，持卡人不得出租或转借信用卡。"},{"i":142,"n":"第一百四十一条","txt":"发卡银行应建立授权审批制度；信用卡结算超过规定限额的必须取得发卡银行的授权。"},{"i":143,"n":"第一百四十二条","txt":"持卡人可持信用卡在特约单位购物、消费。单位卡不得用于１０万元以上的商品交易、劳务供应款项的结算。"},{"i":144,"n":"第一百四十三条","txt":"持卡人凭卡购物、消费时，需将信用卡和身份证件一并交特约单位。智能卡（下称ＩＣ卡）、照片卡可免验身份证件。 特约单位不得拒绝受理持卡人合法持有的、签约银行发行的有效信用卡，不得因持卡人使用信用卡而向其收取附加费用。"},{"i":145,"n":"第一百四十四条","txt":"特约单位受理信用卡时，应审查下列事项： （一）确为本单位可受理的信用卡； （二）信用卡在有效期内，未列入“止付名单”； （三）签名条上没有“样卡”或“专用卡”等非正常签名的字样； （四）信用卡无打孔、剪角、毁坏或涂改的痕迹； （五）持卡人身份证件或卡片上的照片与持卡人相符，但使用ＩＣ卡、照片卡或持卡人凭密码在销售点终端上消费、购物，可免验身份证件（下同）； （六）卡片正面的拼音姓名与卡片背面的签名和身份证件上的姓名一致。"},{"i":146,"n":"第一百四十五条","txt":"特约单位受理信用卡审查无误的，在签购单上压卡，填写实际结算金额、用途、持卡人身份证件号码、特约单位名称和编号。如超过支付限额的，应向发卡银行索权并填写授权号码，交持卡人签名确认，同时核对其签名与卡片背面签名是否一致。无误后，对同意按经办人填写的金额和用途付款的，由持卡人在签购单上签名确认，并将信用卡、身份证件和第一联签购单交还给持卡人。 审查发现问题的，应及时与签约银行联系，征求处理意见。对止付的信用卡，应收回并交还发卡银行。"},{"i":147,"n":"第一百四十六条","txt":"特约单位不得通过压卡、签单和退货等方式支付持卡人现金。"},{"i":148,"n":"第一百四十七条","txt":"特约单位在每日营业终了，应将当日受理的信用卡签购单汇总，计算手续费和净计金额，并填写汇（总）计单和进帐单，连同签购单一并送交收单银行办理进帐。"},{"i":149,"n":"第一百四十八条","txt":"收单银行接到特约单位送交的各种单据，经审查无误后，为特约单位办理进帐。"},{"i":150,"n":"第一百四十九条","txt":"持卡人要求退货的，特约单位应使用退货单办理压（刷）卡，并将退货单金额从当日签购单累计金额中抵减，退货单随签购单一并送交收单银行。"},{"i":151,"n":"第一百五十条","txt":"单位卡一律不得支取现金。"},{"i":152,"n":"第一百五十一条","txt":"个人卡持卡人在银行支取现金时，应将信用卡和身份证件一并交发卡银行或代理银行。ＩＣ卡、照片卡以及凭密码在ＰＯＳ上支取现金的可免验身份证件。 发卡银行或代理银行压（刷）卡后，填写取现单，经审查无误，交持卡人签名确认。超过支付限额的，代理银行应向发卡银行索权，并在取现单上填写授权号码。办理付款手续后，将现金、信用卡、身份证件和取现单回单联交给持卡人。"},{"i":153,"n":"第一百五十二条","txt":"发卡银行收到代理银行通过同城票据交换或本系统联行划转的各种单据审核无误后办理付款。"},{"i":154,"n":"第一百五十三条","txt":"信用卡透支额，金卡最高不得超过１万元，普通卡最高不得超过５千元。 信用卡透支期限最长为６０天。"},{"i":155,"n":"第一百五十四条","txt":"信用卡透支利息，自签单日或银行记帐日起１５日内按日息万分之五计算，超过１５日按日息万分之十计算，超过３０日或透支金额超过规定限额的，按日息万分之十五计算。透支计息不分段，按最后期限或者最高透支额的最高利率档次计息。"},{"i":156,"n":"第一百五十五条","txt":"持卡人使用信用卡不得发生恶意透支。 恶意透支是指持卡人超过规定限额或规定期限，并且经发卡银行催收无效的透支行为。"},{"i":157,"n":"第一百五十六条","txt":"单位卡在使用过程中，需要向其帐户续存资金的，一律从其基本存款帐户转帐存入。 个人卡在使用过程中，需要向其帐户续存资金的，只限于其持有的现金存入和工资性款项以及属于个人的劳务报酬收入转帐存入。"},{"i":158,"n":"第一百五十七条","txt":"个人卡持卡人或其代理人交存现金，应在发卡银行或其代理银行办理。 持卡人凭信用卡在发卡银行或代理银行交存现金的，银行经审查并收妥现金后，在存款单上压卡，将存款单回单联及信用卡交给持卡人。 持卡人委托他人在不压卡的情况下代为办理交存现金的，代理人应在信用卡存款单上填写持卡人的卡号、姓名、存款金额等内容，并将现金送交银行办理交存手续。"},{"i":159,"n":"第一百五十八条","txt":"发卡银行收到代理银行通过同城票据交换或本系统联行划转的各种单据审核无误后，为持卡人办理收款。"},{"i":160,"n":"第一百五十九条","txt":"持卡人不需要继续使用信用卡的，应持信用卡主动到发卡银行办理销户。 销户时，单位卡帐户余额转入其基本存款帐户，不得提取现金；个人卡帐户可以转帐结清，也可以提取现金。"},{"i":161,"n":"第一百六十条","txt":"持卡人还清透支本息后，属于下列情况之一的，可以办理销户： （一）信用卡有效期满４５天后，持卡人不更换新卡的； （二）信用卡挂失满４５天后，没有附属卡又不更换新卡的； （三）信用卡被列入止付名单，发卡银行已收回其信用卡４５天的； （四）持卡人死亡，发卡银行已收回其信用卡４５天的； （五）持卡人要求销户或担保人撤销担保，并已交回全部信用卡４５天的； （六）信用卡帐户两年（含）以上未发生交易的； （七）持卡人违反其他规定，发卡银行认为应该取消资格的。 发卡银行办理销户，应当收回信用卡。有效信用卡无法收回的，应当将其止付。"},{"i":162,"n":"第一百六十一条","txt":"信用卡丧失，持卡人应立即持本人身份证件或其它有效证明，并按规定提供有关情况，向发卡银行或代办银行申请挂失。发卡银行或代办银行审核后办理挂失手续。"},{"i":163,"n":"第一百六十二条","txt":"本办法所称结算方式，是指汇兑、托收承付和委托收款。"},{"i":164,"n":"第一百六十三条","txt":"单位在结算凭证上的签章，应为该单位的财务专用章或者公章加其法定代表人或者其授权的代理人的签名或者盖章。"},{"i":165,"n":"第一百六十四条","txt":"银行办理结算，给单位或个人的收、付款通知和汇兑回单，应加盖该银行的转讫章；银行给单位或个人的托收承付、委托收款的回单和向付款人发出的承付通知，应加盖该银行的业务公章。"},{"i":166,"n":"第一百六十五条","txt":"结算凭证上的记载事项，必须符合本办法的规定。结算凭证上可以记载本办法规定以外的其他记载事项，除国家和中国人民银行另有规定外，该记载事项不具有支付结算的效力。"},{"i":167,"n":"第一百六十六条","txt":"按照本办法的规定必须在结算凭证上记载汇款人、付款人和收款人帐号的，帐号与户名必须一致。"},{"i":168,"n":"第一百六十七条","txt":"银行办理结算向外发出的结算凭证，必须于当日至迟次日寄发；收到的结算凭证，必须及时将款项支付给结算凭证上记载的收款人。"},{"i":169,"n":"第一百六十八条","txt":"汇兑是汇款人委托银行将其款项支付给收款人的结算方式。"},{"i":170,"n":"第一百六十九条","txt":"单位和个人的各种款项的结算，均可使用汇兑结算方式。"},{"i":171,"n":"第一百七十条","txt":"汇兑分为信汇、电汇两种，由汇款人选择使用。"},{"i":172,"n":"第一百七十一条","txt":"签发汇兑凭证必须记载下列事项： （一）表明“信汇”或“电汇”的字样； （二）无条件支付的委托； （三）确定的金额； （四）收款人名称； （五）汇款人名称； （六）汇入地点、汇入行名称； （七）汇出地点、汇出行名称； （八）委托日期； （九）汇款人签章。 汇兑凭证上欠缺上列记载事项之一的，银行不予受理。 汇兑凭证记载的汇款人名称、收款人名称，其在银行开立存款帐户的，必须记载其帐号。欠缺记载的，银行不予受理。 委托日期是指汇款人向汇出银行提交汇兑凭证的当日。"},{"i":173,"n":"第一百七十二条","txt":"汇兑凭证上记载收款人为个人的，收款人需要到汇入银行领取汇款，汇款人应在汇兑凭证上注明“留行待取”字样；留行待取的汇款，需要指定单位的收款人领取汇款的，应注明收款人的单位名称；信汇凭收款人签章支取的，应在信汇凭证上预留其签章。 汇款人确定不得转汇的，应在汇兑凭证备注栏注明“不得转汇”字样。"},{"i":174,"n":"第一百七十三条","txt":"汇款人和收款人均为个人，需要在汇入银行支取现金的，应在信、电汇凭证的“汇款金额”大写栏，先填写“现金”字样，后填写汇款金额。"},{"i":175,"n":"第一百七十四条","txt":"汇出银行受理汇款人签发的汇兑凭证，经审查无误后，应及时向汇入银行办理汇款，并向汇款人签发汇款回单。 汇款回单只能作为汇出银行受理汇款的依据，不能作为该笔汇款已转入收款人帐户的证明。"},{"i":176,"n":"第一百七十五条","txt":"汇入银行对开立存款帐户的收款人，应将汇给其的款项直接转入收款人帐户，并向其发出收帐通知。 收帐通知是银行将款项确已收入收款人帐户的凭据。"},{"i":177,"n":"第一百七十六条","txt":"未在银行开立存款帐户的收款人，凭信、电汇的取款通知或“留行待取”的，向汇入银行支取款项，必须交验本人的身份证件，在信、电汇凭证上注明证件名称、号码及发证机关，并在“收款人签盖章”处签章；信汇凭签章支取的，收款人的签章必须与预留信汇凭证上的签章相符。银行审查无误后，以收款人的姓名开立应解汇款及临时存款帐户，该帐户只付不收，付完清户，不计付利息。 支取现金的，信、电汇凭证上必须有按规定填明的“现金”字样，才能办理。未填明“现金”字样，需要支取现金的，由汇入银行按照国家现金管理规定审查支付。 收款人需要委托他人向汇入银行支取款项的，应在取款通知上签章，注明本人身份证件名称、号码、发证机关和“代理”字样以及代理人姓名。代理人代理取款时，也应在取款通知上签章，注明其身份证件名称、号码及发证机关，并同时交验代理人和被代理人的身份证件。 转帐支付的，应由原收款人向银行填制支款凭证，并由本人交验其身份"},{"i":178,"n":"第一百七十七条","txt":"汇款人对汇出银行尚未汇出的款项可以申请撤销。申请撤销时，应出具正式函件或本人身份证件及原信、电汇回单。汇出银行查明确未汇出款项的，收回原信、电汇回单，方可办理撤销。"},{"i":179,"n":"第一百七十八条","txt":"汇款人对汇出银行已经汇出的款项可以申请退汇。对在汇入银行开立存款帐户的收款人，由汇款人与收款人自行联系退汇；对未在汇入银行开立存款帐户的收款人，汇款人应出具正式函件或本人身份证件以及原信、电汇回单，由汇出银行通知汇入银行，经汇入银行核实汇款确未支付，并将款项汇回汇出银行，方可办理退汇。"},{"i":180,"n":"第一百七十九条","txt":"转汇银行不得受理汇款人或汇出银行对汇款的撤销或退汇。"},{"i":181,"n":"第一百八十条","txt":"汇入银行对于收款人拒绝接受的汇款，应即办理退汇。汇入银行对于向收款人发出取款通知，经过２个月无法交付的汇款，应主动办理退汇。"},{"i":182,"n":"第一百八十一条","txt":"托收承付是根据购销合同由收款人发货后委托银行向异地付款人收取款项，由付款人向银行承认付款的结算方式。"},{"i":183,"n":"第一百八十二条","txt":"使用托收承付结算方式的收款单位和付款单位，必须是国有企业、供销合作社以及经营管理较好，并经开户银行审查同意的城乡集体所有制工业企业。"},{"i":184,"n":"第一百八十三条","txt":"办理托收承付结算的款项，必须是商品交易，以及因商品交易而产生的劳务供应的款项。代销、寄销、赊销商品的款项，不得办理托收承付结算。"},{"i":185,"n":"第一百八十四条","txt":"收付双方使用托收承付结算必须签有符合《经济合同法》的购销合同，并在合同上订明使用托收承付结算方式。"},{"i":186,"n":"第一百八十五条","txt":"收付双方办理托收承付结算，必须重合同、守信用。收款人对同一付款人发货托收累计３次收不回货款的，收款人开户银行应暂停收款人向该付款人办理托收；付款人累计３次提出无理拒付的，付款人开户银行应暂停其向外办理托收。"},{"i":187,"n":"第一百八十六条","txt":"收款人办理托收，必须具有商品确已发运的证件（包括铁路、航运、公路等运输部门签发运单、运单副本和邮局包裹回执）。 没有发运证件，属于下列情况的，可凭其他有关证件办理托收： （一）内贸、外贸部门系统内商品调拨，自备运输工具发送或自提的；易燃、易爆、剧毒、腐蚀性强的商品，以及电、石油、天然气等必须使用专用工具或线路、管道运输的，可凭付款人确已收到商品的证明（粮食部门凭提货单及发货明细表）。 （二）铁道部门的材料厂向铁道系统供应专用器材，可凭其签发注明车辆号码和发运日期的证明。 （三）军队使用军列整车装运物资，可凭注明车辆号码、发运日期的单据；军用仑库对军内发货，可凭总后勤部签发的提货单副本，各大军区、省军区也可比照办理。 （四）收款人承造或大修理船舶、锅炉和大型机器等，生产周期长，合同规定按工程进度分次结算的，可凭工程进度完工证明书。 （五）付款人购进的商品，在收款人所在地转厂加工、配套的，"},{"i":188,"n":"第一百八十七条","txt":"托收承付结算每笔的金额起点为１万元。新华书店系统每笔的金额起点为１千元。"},{"i":189,"n":"第一百八十八条","txt":"托收承付结算款项的划回方法，分邮寄和电报两种，由收款人选用。"},{"i":190,"n":"第一百八十九条","txt":"签发托收承付凭证必须记载下列事项： （一）表明“托收承付”的字样； （二）确定的金额； （三）付款人名称及帐号； （四）收款人名称及帐号； （五）付款人开户银行名称； （六）收款人开户银行名称； （七）托收附寄单证张数或册数； （八）合同名称、号码； （九）委托日期； （十）收款人签章； 托收承付凭证上欠缺记载上列事项之一的，银行不予受理。"},{"i":191,"n":"第一百九十条","txt":"托收。收款人按照签订的购销合同发货后，委托银行办理托收。 （一）收款人应将托收凭证并附发运证件或其他符合托收承付结算的有关证明和交易单证送交银行。收款人如需取回发运证件，银行应在托收凭证上加盖“已验发运证件”戳记。 对于军品托收，有驻厂军代表检验产品或有指定专人负责财务监督的，收款人还应当填制盖有驻厂军代表或指定人员印章（要在银行预留印模）的结算通知单，将交易单证和发运证件装入密封袋，并在密封袋上填明托收号码；同时，在托收凭证上填明结算通知单和密封袋的号码。然后，将托收凭证和结算通知单送交银行办理托收。 没有驻厂军代表使用代号明件办理托收的，不填结算通知单，但应在交易单证上填写保密代号，按照正常托收办法处理。 （二）收款人开户银行接到托收凭证及其附件后，应当按照托收的范围、条件和托收凭证记载的要求认真进行审查，必要时，还应查验收付款人签订的购销合同。凡不符合要求或违反购销合同发货的，不"},{"i":192,"n":"第一百九十一条","txt":"承付。付款人开户银行收到托收凭证及其附件后，应当及时通知付款人。通知的方法，可以根据具体情况与付款人签订协议，采取付款人来行自取、派人送达、对距离较远的付款人邮寄等。付款人应在承付期内审查核对，安排资金。 承付货款分为验单付款和验货付款两种，由收付双方商量选用，并在合同中明确规定。 （一）验单付款。验单付款的承付期为３天，从付款人开户银行发出承付通知的次日算起（承付期内遇法定休假日顺延）。 付款人在承付期内，未向银行表示拒绝付款，银行即视作承付，并在承付期满的次日（法定休假日顺延）上午银行开始营业时，将款项主动从付款人的帐户内付出，按照收款人指定的划款方式，划给收款人。 （二）验货付款。验货付款的承付期为１０天，从运输部门向付款人发出提货通知的次日算起。对收付双方在合同中明确规定，并在托收凭证上注明验货付款期限的，银行从其规定。 付款人收到提货通知后，应即向银行交验提货通知。付款人在银"},{"i":193,"n":"第一百九十二条","txt":"逾期付款。付款人在承付期满日银行营业终了时，如无足够资金支付，其不足部分，即为逾期未付款项，按逾期付款处理。 （一）付款人开户银行对付款人逾期支付的款项，应当根据逾期付款金额和逾期天数，按每天万分之五计算逾期付款赔偿金。 逾期付款天数从承付期满日算起。承付期满日银行营业终了时，付款人如无足够资金支付，其不足部分，应当算作逾期１天，计算１天的赔偿金。在承付期满的次日（遇法定休假日，逾期付款赔偿金的天数计算相应顺延，但在以后遇法定休假日应当照算逾期天数）银行营业终了时，仍无足够资金支付，其不足部分，应当算作逾期２天，计算２天的赔偿金。余类推。 银行审查拒绝付款期间，不能算作付款人逾期付款，但对无理的拒绝付款，而增加银行审查时间的，应从承付期满日起计算逾期付款赔偿金。 （二）赔偿金实行定期扣付，每月计算一次，于次月３日内单独划给收款人。在月内有部分付款的，其赔偿金随同部分支付的款项划给收款人"},{"i":194,"n":"第一百九十三条","txt":"拒绝付款。对下列情况，付款人在承付期内，可向银行提出全部或部分拒绝付款： （一）没有签订购销合同或购销合同未订明托收承付结算方式的款项。 （二）未经双方事先达成协议，收款人提前交货或因逾期交货付款人不再需要该项货物的款项。 （三）未按合同规定的到货地址发货的款项。 （四）代销、寄销、赊销商品的款项。 （五）验单付款，发现所列货物的品种、规格、数量、价格与合同规定不符，或货物已到，经查验货物与合同规定或发货清单不符的款项。 （六）验货付款，经查验货物与合同规定或与发货清单不符的款项。 （七）货款已经支付或计算有错误的款项。 不属于上述情况的，付款人不得向银行提出拒绝付款。 外贸部门托收进口商品的款项，在承付期内，订货部门除因商品的质量问题不能提出拒绝付款，应当另行向外贸部门提出索赔外，属于上述其他情况，可以向银行提出全部或部分拒绝付款。 付款人对以上情况提出拒绝付款时，必须填写“拒绝付款"},{"i":195,"n":"第一百九十四条","txt":"重办托收。收款人对被无理拒绝付款的托收款项，在收到退回的结算凭证及其所附单证后，需要委托银行重办托收，应当填写四联“重办托收理由书”，将其中三联连同购销合同、有关证据和退回的原托收凭证及交易单证，一并送交银行。经开户银行审查，确属无理拒绝付款，可以重办托收。"},{"i":196,"n":"第一百九十五条","txt":"收款人开户银行对逾期尚未划回，又未收到付款人开户银行寄来逾期付款通知或拒绝付款理由书的托收款项，应当及时发出查询。付款人开户银行要积极查明，及时答复。"},{"i":197,"n":"第一百九十六条","txt":"付款人提出的拒绝付款，银行按照本办法规定审查无法判明是非的，应由收付双方自行协商处理，或向仲裁机关，人民法院申请调解或裁决。"},{"i":198,"n":"第一百九十七条","txt":"未经开户银行批准使用托收承付结算方式的城乡集体所有制工业企业，收款人开户银行不得受理其办理托收；付款人开户银行对其承付的款项应按规定支付款项外，还要对该付款人按结算金额处以百分之五罚款。"},{"i":199,"n":"第一百九十八条","txt":"委托收款是收款人委托银行向付款人收取款项的结算方式。"},{"i":200,"n":"第一百九十九条","txt":"单位和个人凭已承兑商业汇票、债券、存单等付款人债务证明办理款项的结算，均可以使用委托收款结算方式。"},{"i":201,"n":"第二百条","txt":"委托收款在同城、异地均可以使用。"},{"i":202,"n":"第二百零一条","txt":"委托收款结算款项的划回方式，分邮寄和电报两种，由收款人选用。"},{"i":203,"n":"第二百零二条","txt":"签发委托收款凭证必须记载下列事项： （一）表明“委托收款”的字样； （二）确定的金额； （三）付款人名称； （四）收款人名称； （五）委托收款凭据名称及附寄单证张数； （六）委托日期； （七）收款人签章。 欠缺记载上列事项之一的，银行不予受理。 委托收款以银行以外的单位为付款人的，委托收款凭证必须记载付款人开户银行名称；以银行以外的单位或在银行开立存款帐户的个人为收款人的，委托收款凭证必须记载收款人开户银行名称；未在银行开立存款帐户的个人为收款人的，委托收款凭证必须记载被委托银行名称。欠缺记载的，银行不予受理。"},{"i":204,"n":"第二百零三条","txt":"委托。收款人办理委托收款应向银行提交委托收款凭证和有关的债务证明。"},{"i":205,"n":"第二百零四条","txt":"付款。银行接到寄来的委托收款凭证及债务证明，审查无误办理付款。 （一）以银行为付款人的，银行应在当日将款项主动支付给收款人。 （二）以单位为付款人的，银行应及时通知付款人，按照有关办法规定，需要将有关债务证明交给付款人的应交给付款人，并签收。 付款人应于接到通知的当日书面通知银行付款。 按照有关办法规定，付款人未在接到通知日的次日起３日内通知银行付款的，视同付款人同意付款，银行应于付款人接到通知日的次日起第４日上午开始营业时，将款项划给收款人。 付款人提前收到由其付款的债务证明，应通知银行于债务证明的到期日付款。付款人未于接到通知日的次日起３日内通知银行付款，付款人接到通知日的次日起第４日在债务证明到期日之前的，银行应于债务证明到期日将款项划给收款人。 银行在办理划款时，付款人存款帐户不足支付的，应通过被委托银行向收款人发出未付款项通知书。按照有关办法规定，债务证明留存付款人开户银行的"},{"i":206,"n":"第二百零五条","txt":"拒绝付款。付款人审查有关债务证明后，对收款人委托收取的款项需要拒绝付款的，可以办理拒绝付款。 （一）以银行为付款人的，应自收到委托收款及债务证明的次日起３日内出具拒绝证明连同有关债务证明、凭证寄给被委托银行，转交收款人。 （二）以单位为付款人的，应在付款人接到通知日的次日起３日内出具拒绝证明，持有债务证明的，应将其送交开户银行。银行将拒绝证明、债务证明和有关凭证一并寄给被委托银行，转交收款人。"},{"i":207,"n":"第二百零六条","txt":"在同城范围内，收款人收取公用事业费或根据国务院的规定，可以使用同城特约委托收款。 收取公用事业费，必须具有收付双方事先签订的经济合同，由付款人向开户银行授权，并经开户银行同意，报经中国人民银行当地分支行批准。"},{"i":208,"n":"第二百零七条","txt":"单位和个人办理支付结算，不准签发没有资金保证的票据或远期支票，套取银行信用；不准签发、取得和转让没有真实交易和债权债务的票据，套取银行和他人资金；不准无理拒绝付款，任意占用他人资金；不准违反规定开立和使用帐户。"},{"i":209,"n":"第二百零八条","txt":"银行办理支付结算，不准以任何理由压票、任意退票、截留挪用客户和他行资金；不准无理拒绝支付应由银行支付的票据款项；不准受理无理拒付、不扣少扣滞纳金；不准违章签发、承兑、贴现票据，套取银行资金；不准签发空头银行汇票、银行本票和办理空头汇款；不准在支付结算制度之外规定附加条件，影响汇路畅通；不准违反规定为单位和个人开立帐户；不准拒绝受理、代理他行正常结算业务；不准放弃对企事业单位和个人违反结算纪律的制裁；不准逃避向人民银行转汇大额汇划款项。"},{"i":210,"n":"第二百零九条","txt":"单位、个人和银行按照法定条件在票据上签章的，必须按照所记载的事项承担票据责任。"},{"i":211,"n":"第二百一十条","txt":"单位签发商业汇票后，必须承担保证该汇票承兑和付款的责任。 单位和个人签发支票后，必须承担保证该支票付款的责任。 银行签发银行汇票、银行本票后，即承担该票据付款的责任。"},{"i":212,"n":"第二百一十一条","txt":"商业汇票的背书人背书转让票据后，即承担保证其后手所持票据承兑和付款责任。 银行汇票、银行本票或支票的背书人背书转让票据后，即承担保证其后手所持票据付款的责任。 单位或银行承兑商业汇票后，必须承担该票据付款的责任。"},{"i":213,"n":"第二百一十二条","txt":"票据的保证人应当与被保证人对持票人承担连带责任。"},{"i":214,"n":"第二百一十三条","txt":"变造票据除签章以外的记载事项的，在变造之前签章的人，对原记载事项负责、在变造之后签章的人，对变造之后的记载事项负责；不能辨别在票据被变造之前或者之后签章的，视同在变造之前签章。"},{"i":215,"n":"第二百一十四条","txt":"持票人超过规定期限提示付款的，银行汇票、银行本票的出票人、商业汇票的承兑人，在持票人作出说明后，仍应当继续对持票人承担付款责任；支票的出票人对持票人的追索，仍应当承担清偿责任。"},{"i":216,"n":"第二百一十五条","txt":"付款人及其代理付款人以恶意或者重大过失付款的，应当自行承担责任。"},{"i":217,"n":"第二百一十六条","txt":"商业汇票的付款人在到期前付款的，由付款人自行承担所产生的责任。"},{"i":218,"n":"第二百一十七条","txt":"承兑人或者付款人拒绝承兑或拒绝付款，未按规定出具拒绝证明、或者出具退票理由书的，应当承担由此产生的民事责任。"},{"i":219,"n":"第二百一十八条","txt":"持票人不能出示拒绝证明、退票理由书或者未按规定期限提供其他合法证明丧失对其前手追索权的，承兑人或者付款人应对持票人承担责任。"},{"i":220,"n":"第二百一十九条","txt":"持票人因不获承兑或不获付款，对其前手行使追索权时，票据的出票人、背书人和保证人对持票人承担连带责任。"},{"i":221,"n":"第二百二十条","txt":"持票人行使追索权时，持票人及其前手未按《票据法》规定期限将被拒绝事由书面通知其前手的，因延期通知给其前手或者出票人造成损失的，由没有按照规定期限通知的票据当事人，在票据金额内承担对该损失的赔偿责任。"},{"i":222,"n":"第二百二十一条","txt":"票据债务人在持票人不获付款或不获承兑时，应向持票人清偿《票据法》规定的金额和费用。"},{"i":223,"n":"第二百二十二条","txt":"单位和个人签发空头支票、签章与预留银行签章不符或者支付密码错误的支票，应按照《票据管理实施办法》和本办法的规定承担行政责任。"},{"i":224,"n":"第二百二十三条","txt":"单位为票据的付款人，对见票即付或者到期的票据，故意压票、拖延支付的，应按照《票据管理实施办法》的规定承担行政责任。"},{"i":225,"n":"第二百二十四条","txt":"持卡人必须妥善保管和正确使用其信用卡，否则，应按规定承担因此造成的资金损失。"},{"i":226,"n":"第二百二十五条","txt":"持卡人使用单位卡发生透支的，由其单位承担透支金额的偿还和支付透支利息的责任。持卡人使用个人卡附属卡发生透支的，由其主卡持卡人承担透支金额的偿还和支付透支利息的责任；主卡持卡人丧失偿还能力的，由其附属卡持卡人承担透支金额的偿还和支付透支利息的责任。"},{"i":227,"n":"第二百二十六条","txt":"持卡人办理挂失后，被冒用造成的损失，有关责任人按照信用卡章程的规定承担责任。"},{"i":228,"n":"第二百二十七条","txt":"持卡人违反本办法规定使用信用卡进行商品交易、套取现金以及出租或转借信用卡的，应按规定承担行政责任。"},{"i":229,"n":"第二百二十八条","txt":"单位卡持卡人违反本办法规定，将基本存款帐户以外的存款和销货款收入的款项转入其信用卡帐户的；个人卡持卡人违反本办法规定，将单位的款项转入其信用卡帐户的，应按规定承担行政责任。"},{"i":230,"n":"第二百二十九条","txt":"特约单位受理信用卡时，应当按照规定的操作程序办理，否则，由其承担因此造成的资金损失。"},{"i":231,"n":"第二百三十条","txt":"发卡银行未按规定时间将止付名单发至特约单位的，应由其承担因此造成的资金损失。"},{"i":232,"n":"第二百三十一条","txt":"银行违反本办法规定，未经批准发行信用卡的；帮助持卡人将其基本存款帐户以外的存款或其他款项转入单位卡帐户，将单位的款项转入个人卡帐户的；违反规定帮助持卡人提取现金的，应按规定承担行政责任。"},{"i":233,"n":"第二百三十二条","txt":"非金融机构、非银行金融机构、境外金融机构驻华代表机构违反规定，经营信用卡业务的，应按规定承担行政责任。"},{"i":234,"n":"第二百三十三条","txt":"付款单位对收款单位托收的款项逾期付款，应按照规定承担赔偿责任；付款单位变更开户银行、帐户名称和帐号，未能及时通知收款单位，影响收取款项的，应由付款单位承担逾期付款赔偿责任；付款单位提出的无理拒绝付款，对收款单位重办的托收，应承担自第一次托收承付期满日起逾期付款赔偿责任。"},{"i":235,"n":"第二百三十四条","txt":"单位和个人办理支付结算，未按照本办法的规定填写票据或结算凭证或者填写有误，影响资金使用或造成资金损失；票据或印章丢失，造成资金损失的，由其自行负责。"},{"i":236,"n":"第二百三十五条","txt":"单位和个人违反本办法的规定，银行停止其使用有关支付结算工具，因此造成的后果，由单位和个人自行负责。"},{"i":237,"n":"第二百三十六条","txt":"付款单位到期无款支付，逾期不退回托收承付有关单证的，应按规定承担行政责任。"},{"i":238,"n":"第二百三十七条","txt":"城乡集体所有制工业企业未经银行批准，擅自办理托收承付结算的，应按规定承担行政责任。"},{"i":239,"n":"第二百三十八条","txt":"单位和个人违反《银行帐户管理办法》开立和使用帐户的，应按规定承担行政责任。"},{"i":240,"n":"第二百三十九条","txt":"对单位和个人承担行政责任的处罚，由中国人民银行委托商业银行执行。"},{"i":241,"n":"第二百四十条","txt":"收款人或持票人委托的收款银行的责任，限于收到付款人支付的款项后按照票据和结算凭证上记载的事项将票据或结算凭证记载的金额转入收款人或持票人帐户。 付款人委托的付款银行的责任，限于按照票据和结算凭证上记载事项从付款人帐户支付金额。但托收承付结算中的付款人开户银行，应按照托收承付结算方式有关规定承担责任。"},{"i":242,"n":"第二百四十一条","txt":"银行办理支付结算，因工作差错发生延误，影响客户和他行资金使用的，按中国人民银行规定的同档次流动资金贷款利率计付赔偿金。"},{"i":243,"n":"第二百四十二条","txt":"银行违反规定故意压票、退票、拖延支付，受理无理拒付、擅自拒付退票、有款不扣以及不扣、少扣赔偿金，截留挪用结算资金，影响客户和他行资金使用的，要按规定承担赔偿责任。因重大过失错付或被冒领的，要负责资金赔偿。"},{"i":244,"n":"第二百四十三条","txt":"银行违反本办法规定将支付结算的款项转入储蓄和信用卡帐户的，应按规定承担行政责任。"},{"i":245,"n":"第二百四十四条","txt":"银行违反规定签发空头银行汇票、银行本票和办理空头汇款的，应按照规定承担行政责任。"},{"i":246,"n":"第二百四十五条","txt":"银行违反规定故意压票、退票、拖延支付，受理无理拒付、擅自拒付退票、有款不扣以及不扣、少扣赔偿金，截留、挪用结算资金的，应按规定承担行政责任。"},{"i":247,"n":"第二百四十六条","txt":"银行未按规定通过人民银行办理大额转汇的，应按规定承担行政责任。"},{"i":248,"n":"第二百四十七条","txt":"银行在结算制度之外规定附加条件，影响汇路畅通的，应按规定承担行政责任。"},{"i":249,"n":"第二百四十八条","txt":"银行违反《银行帐户管理办法》开立和管理帐户的，应按规定承担行政责任。"},{"i":250,"n":"第二百四十九条","txt":"违反国家法律、法规和未经中国人民银行批准，作为中介机构经营结算业务的；未经中国人民银行批准，开办银行汇票、银行本票、支票、信用卡业务的，应按规定承担行政责任。"},{"i":251,"n":"第二百五十条","txt":"金融机构的工作人员在票据业务中玩忽职守，对违反规定的票据予以承兑、付款、保证或者贴现的，应按照《票据管理实施办法》的规定承担行政责任或刑事责任。"},{"i":252,"n":"第二百五十一条","txt":"违反本办法规定擅自印制票据的，应按照《票据管理实施办法》的规定承担行政责任。"},{"i":253,"n":"第二百五十二条","txt":"邮电部门在传递票据、结算凭证和拍发电报中，因工作差错而发生积压、丢失、错投、错拍、漏拍、重拍等，造成结算延误，影响单位、个人和银行资金使用或造成资金损失的，由邮电部门负责。"},{"i":254,"n":"第二百五十三条","txt":"伪造、变造票据和结算凭证上的签章或其他记载事项的，应当承担民事责任或刑事责任。"},{"i":255,"n":"第二百五十四条","txt":"有利用票据、信用卡、结算凭证欺诈的行为，构成犯罪的，应依法承担刑事责任。情节轻微，不构成犯罪的，应按照规定承担行政责任。"},{"i":256,"n":"第二百五十五条","txt":"本办法规定的各项期限的计算，适用民法通则关于计算期间的规定。期限最后一日是法定休假日的，以休假日的次日为最后一日。 按月计算期限的，按到期月的对日计算；无对日的，月末日为到期日。 本办法所规定的各项期限，可以因不可抗力的原因而中止。不可抗力的原因消失时，期限可以顺延。"},{"i":257,"n":"第二百五十六条","txt":"银行汇票、商业汇票由中国人民银行总行统一格式、联次、颜色、规格，并在中国人民银行总行批准的印制厂印制。由各家银行总行组织定货和管理。 银行本票、支票由中国人民银行总行统一格式、联次、颜色、规格，并在中国人民银行总行批准的印制厂印制，由中国人民银行各省、自治区、直辖市、计划单列市分行负责组织各商业银行定货和管理。 信用卡按中国人民银行的有关规定印制，信用卡结算凭证的格式、联次、颜色、规格由中国人民银行总行统一规定，各发卡银行总行负责印制。 汇兑凭证、托收承付凭证、委托收款凭证由中国人民银行总行统一格式、联次、颜色、规格，由各行负责印制和管理。"},{"i":258,"n":"第二百五十七条","txt":"银行办理各项支付结算业务，根据承担的责任和业务成本以及应付给有关部门的费用，分别收取邮费、电报费、手续费、凭证工本费（信用卡卡片费）、挂失手续费，以及信用卡年费、特约手续费、异地存取款手续费。收费范围，除财政金库全部免收、存款不计息帐户免收邮费、手续费外，对其他单位和个人都要按照规定收取费用。 邮费，单程的每笔按邮局挂号信每件收费标准收费；双程的每笔按邮局挂号信二件收费标准收费；客户要求使用特快专递的，按邮局规定的收费标准收取；超重部分按邮局规定的标准加收。 电报费，每笔按四十五个字照电报费标准收取，超过的字数按每字收费的标准加收。急电均加倍收取电报费。 手续费，按银行规定的标准收取。 银行办理支付结算业务按照附二《支付结算业务收费表》收取手续费和邮电费。 信用卡统一的收费标准，中国人民银行将另行规定。 支票的手续费由经办银行向购买人收取，其他结算的手续费、邮电费一律由经办银行向委托人"},{"i":259,"n":"第二百五十八条","txt":"各部门、各单位制定的有关规定，涉及支付结算而与本办法有抵触的，一律按照本办法的规定执行。 中国人民银行过去有关支付结算的规定与本办法有抵触的，以本办法为准。"},{"i":260,"n":"第二百五十九条","txt":"本办法由中国人民银行总行负责解释、修改。"},{"i":261,"n":"第二百六十条","txt":"本办法自１９９７年１２月１日起施行。"}],"qichedaikuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范汽车贷款业务管理，防范汽车贷款风险，促进汽车贷款业务健康发展，根据《中华人民共和国中国人民银行法》、《中华人民共和国银行业监督管理法》、《中华人民共和国商业银行法》等法律规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称汽车贷款是指贷款人向借款人发放的用于购买汽车（含二手车）的贷款，包括个人汽车贷款、经销商汽车贷款和机构汽车贷款。"},{"i":3,"n":"第三条","txt":"本办法所称贷款人是指在中华人民共和国境内依法设立的、经中国银行业监督管理委员会及其派出机构批准经营人民币贷款业务的商业银行、农村合作银行、农村信用社及获准经营汽车贷款业务的非银行金融机构。"},{"i":4,"n":"第四条","txt":"本办法所称自用车是指借款人通过汽车贷款购买的、不以营利为目的的汽车；商用车是指借款人通过汽车贷款购买的、以营利为目的的汽车；二手车是指从办理完注册登记手续到达到国家强制报废标准之前进行所有权变更并依法办理过户手续的汽车；新能源汽车是指采用新型动力系统，完全或者主要依靠新型能源驱动的汽车，包括插电式混合动力（含增程式）汽车、纯电动汽车和燃料电池汽车等。"},{"i":5,"n":"第五条","txt":"汽车贷款利率按照中国人民银行公布的贷款利率规定执行，计、结息办法由借款人和贷款人协商确定。"},{"i":6,"n":"第六条","txt":"汽车贷款的贷款期限（含展期）不得超过5年，其中，二手车贷款的贷款期限（含展期）不得超过3年，经销商汽车贷款的贷款期限不得超过1年。"},{"i":7,"n":"第七条","txt":"借贷双方应当遵循平等、自愿、诚实、守信的原则。"},{"i":8,"n":"第八条","txt":"本办法所称个人汽车贷款，是指贷款人向个人借款人发放的用于购买汽车的贷款。"},{"i":9,"n":"第九条","txt":"借款人申请个人汽车贷款，应当同时符合以下条件： （一）是中华人民共和国公民，或在中华人民共和国境内连续居住一年（含一年）以上的港、澳、台居民及外国人； （二）具有有效身份证明、固定和详细住址且具有完全民事行为能力； （三）具有稳定的合法收入或足够偿还贷款本息的个人合法资产； （四）个人信用良好； （五）能够支付规定的首期付款； （六）贷款人要求的其他条件。"},{"i":10,"n":"第十条","txt":"贷款人发放个人汽车贷款，应综合考虑以下因素，确定贷款金额、期限、利率和还本付息方式等贷款条件： （一）贷款人对借款人的信用评级情况； （二）贷款担保情况； （三）所购汽车的性能及用途； （四）汽车行业发展和汽车市场供求情况。"},{"i":11,"n":"第十一条","txt":"贷款人应当建立借款人信贷档案。借款人信贷档案应载明以下内容： （一）借款人姓名、住址、有效身份证明及有效联系方式； （二）借款人的收入水平及信用状况证明； （三）所购汽车的购车协议、汽车型号、发动机号、车架号、价格与购车用途； （四）贷款的金额、期限、利率、还款方式和担保情况； （五）贷款催收记录； （六）防范贷款风险所需的其他资料。"},{"i":12,"n":"第十二条","txt":"贷款人发放个人商用车贷款，除本办法第十一条规定的内容外，应在借款人信贷档案中增加商用车运营资格证年检情况、商用车折旧、保险情况等内容。"},{"i":13,"n":"第十三条","txt":"本办法所称经销商汽车贷款，是指贷款人向汽车经销商发放的用于采购车辆、零配件的贷款。"},{"i":14,"n":"第十四条","txt":"借款人申请经销商汽车贷款，应当同时符合以下条件： （一）具有工商行政主管部门核发的企业法人营业执照； （二）具有汽车生产商出具的代理销售汽车证明； （三）资产负债率不超过80%； （四）具有稳定的合法收入或足够偿还贷款本息的合法资产； （五）经销商、经销商高级管理人员及经销商代为受理贷款申请的客户无重大违约行为或信用不良记录； （六）贷款人要求的其他条件。"},{"i":15,"n":"第十五条","txt":"贷款人应为每个经销商借款人建立独立的信贷档案，并及时更新。经销商信贷档案应载明以下内容： （一）经销商的名称、法定代表人及营业地址； （二）各类营业证照复印件； （三）经销商购买保险、商业信用及财务状况； （四）所购汽车及零部件的型号、价格及用途； （五）贷款担保状况； （六）防范贷款风险所需的其他资料。"},{"i":16,"n":"第十六条","txt":"贷款人对经销商采购车辆、零配件贷款的贷款金额应以经销商一段期间的平均存货为依据，具体期间应视经销商存货周转情况而定。"},{"i":17,"n":"第十七条","txt":"贷款人应通过定期清点经销商采购车辆、零配件存货，以及分析经销商财务报表等方式，定期对经销商进行信用审查，并视审查结果调整经销商信用级别和清点存货的频率。"},{"i":18,"n":"第十八条","txt":"本办法所称机构汽车贷款，是指贷款人对除经销商以外的法人、其他经济组织（以下简称机构借款人）发放的用于购买汽车的贷款。"},{"i":19,"n":"第十九条","txt":"借款人申请机构汽车贷款，必须同时符合以下条件： （一）具有企业或事业单位登记管理机关核发的企业法人营业执照或事业单位法人证书及法人分支机构营业执照、个体工商户营业执照等证明借款人主体资格的法定文件； （二）具有合法、稳定的收入或足够偿还贷款本息的合法资产； （三）能够支付规定的首期付款； （四）无重大违约行为或信用不良记录； （五）贷款人要求的其他条件。"},{"i":20,"n":"第二十条","txt":"贷款人应参照本办法第十五条的规定为每个机构借款人建立独立的信贷档案，加强信贷风险跟踪监测。"},{"i":21,"n":"第二十一条","txt":"贷款人对从事汽车租赁业务的机构发放机构商用车贷款，应监测借款人对残值的估算方式，防范残值估计过高给贷款人带来的风险。"},{"i":22,"n":"第二十二条","txt":"汽车贷款发放实施贷款最高发放比例要求制度，贷款人发放的汽车贷款金额占借款人所购汽车价格的比例，不得超过贷款最高发放比例要求；贷款最高发放比例要求由中国人民银行、中国银行业监督管理委员会根据宏观经济、行业发展等实际情况另行规定。 前款所称汽车价格，对新车是指汽车实际成交价格（扣除政府补贴，且不含各类附加税、费及保费等）与汽车生产商公布的价格的较低者，对二手车是指汽车实际成交价格（扣除政府补贴，且不含各类附加税、费及保费等）与贷款人评估价格的较低者。"},{"i":23,"n":"第二十三条","txt":"贷款人应建立借款人信用评级系统，审慎使用外部信用评级，通过内外评级结合，确定借款人的信用级别。对个人借款人，应根据其职业、收入状况、还款能力、信用记录等因素确定信用级别；对经销商及机构借款人，应根据其信贷档案所反映的情况、高级管理人员的信用情况、财务状况、信用记录等因素确定信用级别。"},{"i":24,"n":"第二十四条","txt":"贷款人发放汽车贷款，应要求借款人提供所购汽车抵押或其他有效担保。经贷款人审查、评估，确认借款人信用良好，确能偿还贷款的，可以不提供担保。"},{"i":25,"n":"第二十五条","txt":"贷款人应直接或委托指定经销商受理汽车贷款申请，完善审贷分离制度，加强贷前审查和贷后跟踪催收工作。"},{"i":26,"n":"第二十六条","txt":"贷款人应建立二手车市场信息数据库和二手车残值估算体系。"},{"i":27,"n":"第二十七条","txt":"贷款人应根据贷款金额、贷款地区分布、借款人财务状况、汽车品牌、抵押担保等因素建立汽车贷款分类监控系统，对不同类别的汽车贷款风险进行定期检查、评估。根据检查评估结果，及时调整各类汽车贷款的风险级别。"},{"i":28,"n":"第二十八条","txt":"贷款人应建立汽车贷款预警监测分析系统，制定预警标准；超过预警标准后应采取重新评价贷款审批制度等措施。"},{"i":29,"n":"第二十九条","txt":"贷款人应建立不良贷款分类处理制度和审慎的贷款损失准备制度，计提相应的风险准备。"},{"i":30,"n":"第三十条","txt":"贷款人发放抵押贷款，应审慎评估抵押物价值，充分考虑抵押物减值风险，设定抵押率上限。"},{"i":31,"n":"第三十一条","txt":"贷款人应将汽车贷款的有关信息及时录入金融信用信息基础数据库。"},{"i":32,"n":"第三十二条","txt":"贷款人在从事汽车贷款业务时有违反本办法规定之行为的，中国银行业监督管理委员会及其派出机构有权依据《中华人民共和国银行业监督管理法》等法律规定对该贷款人及其相关人员进行处罚。中国人民银行及其分支机构可以建议中国银行业监督管理委员会及其派出机构对从事汽车贷款业务的贷款人违规行为进行监督检查。"},{"i":33,"n":"第三十三条","txt":"贷款人对借款人发放的用于购买推土机、挖掘机、搅拌机、泵机等工程车辆的贷款，比照本办法执行。"},{"i":34,"n":"第三十四条","txt":"本办法由中国人民银行和中国银行业监督管理委员会共同负责解释。"},{"i":35,"n":"第三十五条","txt":"本办法自2018年1月1日起施行。原《汽车贷款管理办法》（中国人民银行 中国银行业监督管理委员会令〔2004〕第2号发布）同时废止。"}],"dianzishangyehuipiaoyewuguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范电子商业汇票业务，保障电子商业汇票活动中当事人的合法权益，促进电子商业汇票业务发展，依据《中华人民共和国中国人民银行法》、《中华人民共和国票据法》、《中华人民共和国电子签名法》、《中华人民共和国物权法》、《票据管理实施办法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"电子商业汇票是指出票人依托电子商业汇票系统，以数据电文形式制作的，委托付款人在指定日期无条件支付确定金额给收款人或者持票人的票据。 电子商业汇票分为电子银行承兑汇票和电子商业承兑汇票。 电子银行承兑汇票由银行业金融机构、财务公司（以下统称金融机构）承兑；电子商业承兑汇票由金融机构以外的法人或其他组织承兑。 电子商业汇票的付款人为承兑人。"},{"i":3,"n":"第三条","txt":"电子商业汇票系统是经中国人民银行批准建立，依托网络和计算机技术，接收、存储、发送电子商业汇票数据电文，提供与电子商业汇票货币给付、资金清算行为相关服务的业务处理平台。"},{"i":4,"n":"第四条","txt":"电子商业汇票各当事人应本着诚实信用原则，按照本办法的规定作出票据行为。"},{"i":5,"n":"第五条","txt":"电子商业汇票的出票、承兑、背书、保证、提示付款和追索等业务，必须通过电子商业汇票系统办理。"},{"i":6,"n":"第六条","txt":"电子商业汇票业务主体的类别分为： （一）直接接入电子商业汇票系统的金融机构（以下简称接入机构）； （二）通过接入机构办理电子商业汇票业务的金融机构（以下简称被代理机构）； （三）金融机构以外的法人及其他组织。 电子商业汇票系统对不同业务主体分配不同的类别代码。"},{"i":7,"n":"第七条","txt":"票据当事人办理电子商业汇票业务应具备中华人民共和国组织机构代码。 被代理机构、金融机构以外的法人及其他组织办理电子商业汇票业务,应在接入机构开立账户。"},{"i":8,"n":"第八条","txt":"接入机构提供电子商业汇票业务服务，应对客户基本信息的真实性负审核责任，并依据本办法及相关规定，与客户签订电子商业汇票业务服务协议，明确双方的权利和义务。 客户基本信息包括客户名称、账号、组织机构代码和业务主体类别等信息。"},{"i":9,"n":"第九条","txt":"电子商业汇票系统运营者由中国人民银行指定和监管。"},{"i":10,"n":"第十条","txt":"接入机构应按规定向客户和电子商业汇票系统转发电子商业汇票信息，并保证内部系统存储的电子商业汇票信息与电子商业汇票系统存储的相关信息相符。"},{"i":11,"n":"第十一条","txt":"电子商业汇票信息以电子商业汇票系统的记录为准。"},{"i":12,"n":"第十二条","txt":"电子商业汇票以人民币为计价单位。"},{"i":13,"n":"第十三条","txt":"电子商业汇票为定日付款票据。 电子商业汇票的付款期限自出票日起至到期日止，最长不得超过1年。"},{"i":14,"n":"第十四条","txt":"票据当事人在电子商业汇票上的签章，为该当事人可靠的电子签名。 电子签名所需的认证服务应由合法的电子认证服务提供者提供。 可靠的电子签名必须符合《中华人民共和国电子签名法》第十三条第一款的规定。"},{"i":15,"n":"第十五条","txt":"电子商业汇票业务活动中，票据当事人所使用的数据电文和电子签名应符合《中华人民共和国电子签名法》的有关规定。"},{"i":16,"n":"第十六条","txt":"客户开展电子商业汇票活动时，其签章所依赖的电子签名制作数据和电子签名认证证书，应向接入机构指定的电子认证服务提供者的注册审批机构申请。 接入机构为客户提供电子商业汇票业务服务或作为电子商业汇票当事人时，其签章所依赖的电子签名制作数据和电子签名认证证书，应向电子商业汇票系统运营者指定的电子认证服务提供者的注册审批机构申请。"},{"i":17,"n":"第十七条","txt":"接入机构、电子商业汇票系统运营者指定的电子认证服务机构提供者，应对电子签名认证证书申请者的身份真实性负审核责任。 电子认证服务提供者依据《中华人民共和国电子签名法》承担相应责任。"},{"i":18,"n":"第十八条","txt":"接入机构应对通过其办理电子商业汇票业务客户的电子签名真实性负审核责任。 电子商业汇票系统运营者应对接入机构的身份真实性和电子签名真实性负审核责任。"},{"i":19,"n":"第十九条","txt":"电子商业汇票系统应实时接收、处理电子商业汇票信息，并向相关票据当事人的接入机构实时发送该信息；接入机构应实时接收、处理电子商业汇票信息，并向相关票据当事人实时发送该信息。"},{"i":20,"n":"第二十条","txt":"出票人签发电子商业汇票时，应将其交付收款人。 电子商业汇票背书，背书人应将电子商业汇票交付被背书人。 电子商业汇票质押解除，质权人应将电子商业汇票交付出质人。 交付是指票据当事人将电子商业汇票发送给受让人，且受让人签收的行为。"},{"i":21,"n":"第二十一条","txt":"签收是指票据当事人同意接受其他票据当事人的行为申请，签章并发送电子指令予以确认的行为。 驳回是指票据当事人拒绝接受其他票据当事人的行为申请，签章并发送电子指令予以确认的行为。 收款人、被背书人可与接入机构签订协议，委托接入机构代为签收或驳回行为申请，并代理签章。 商业承兑汇票的承兑人应与接入机构签订协议，在符合本办法规定的情况下，由接入机构代为签收或驳回提示付款指令，并代理签章。"},{"i":22,"n":"第二十二条","txt":"出票人或背书人在电子商业汇票上记载了“不得转让”事项的，电子商业汇票不得继续背书。"},{"i":23,"n":"第二十三条","txt":"票据当事人通过电子商业汇票系统作出行为申请，行为接收方未签收且未驳回的，票据当事人可撤销该行为申请。电子商业汇票系统为行为接收方的，票据当事人不得撤销。"},{"i":24,"n":"第二十四条","txt":"电子商业汇票的出票日是指出票人记载在电子商业汇票上的出票日期。 电子商业汇票的提示付款日是指提示付款申请的指令进入电子商业汇票系统的日期。 电子商业汇票的拒绝付款日是指驳回提示付款申请的指令进入电子商业汇票系统的日期。 电子商业汇票追索行为的发生日是指追索通知的指令进入电子商业汇票系统的日期。 承兑、背书、保证、质押解除、付款和追索清偿等行为的发生日是指相应的签收指令进入电子商业汇票系统的日期。"},{"i":25,"n":"第二十五条","txt":"电子商业汇票责任解除前，电子商业汇票的承兑人不得撤销原办理电子商业汇票业务的账户，接入机构不得为其办理销户手续。"},{"i":26,"n":"第二十六条","txt":"接入机构终止提供电子商业汇票业务服务的，应按规定由其他接入机构承接其电子商业汇票业务服务。"},{"i":27,"n":"第二十七条","txt":"电子商业汇票的出票，是指出票人签发电子商业汇票并交付收款人的票据行为。 出票人在电子商业汇票交付收款人前，可办理票据的未用退回。 出票人不得在提示付款期后将票据交付收款人。"},{"i":28,"n":"第二十八条","txt":"电子商业汇票的出票人必须为银行业金融机构以外的法人或其他组织。 电子银行承兑汇票的出票人应在承兑金融机构开立账户。"},{"i":29,"n":"第二十九条","txt":"电子商业汇票出票必须记载下列事项： （一）表明“电子银行承兑汇票”或“电子商业承兑汇票”的字样； （二）无条件支付的委托； （三）确定的金额； （四）出票人名称； （五）付款人名称； （六）收款人名称； （七）出票日期； （八）票据到期日； （九）出票人签章。"},{"i":30,"n":"第三十条","txt":"出票人可在电子商业汇票上记载自身的评级信息，并对记载信息的真实性负责，但该记载事项不具有票据上的效力。 评级信息包括评级机构、信用等级和评级到期日。"},{"i":31,"n":"第三十一条","txt":"电子商业汇票的承兑，是指付款人承诺在票据到期日支付电子商业汇票金额的票据行为。"},{"i":32,"n":"第三十二条","txt":"电子商业汇票交付收款人前，应由付款人承兑。"},{"i":33,"n":"第三十三条","txt":"电子银行承兑汇票由真实交易关系或债权债务关系中的债务人签发，并交由金融机构承兑。 电子银行承兑汇票的出票人与收款人不得为同一人。"},{"i":34,"n":"第三十四条","txt":"电子商业承兑汇票的承兑有以下几种方式： （一）真实交易关系或债权债务关系中的债务人签发并承兑； （二）真实交易关系或债权债务关系中的债务人签发，交由第三人承兑； （三）第三人签发，交由真实交易关系或债权债务关系中的债务人承兑； （四）收款人签发，交由真实交易关系或债权债务关系中的债务人承兑。"},{"i":35,"n":"第三十五条","txt":"电子银行承兑汇票的出票人应向承兑金融机构提交真实、有效、用以证实真实交易关系或债权债务关系的交易合同或其他证明材料，并在电子商业汇票上作相应记录，承兑金融机构应负责审核。"},{"i":36,"n":"第三十六条","txt":"承兑人应在票据到期日前，承兑电子商业汇票。"},{"i":37,"n":"第三十七条","txt":"承兑人承兑电子商业汇票，必须记载下列事项： （一）表明“承兑”的字样； （二）承兑日期； （三）承兑人签章。"},{"i":38,"n":"第三十八条","txt":"承兑人可在电子商业汇票上记载自身的评级信息，并对记载信息的真实性负责，但该记载事项不具有票据上的效力。 评级信息包括评级机构、信用等级和评级到期日。"},{"i":39,"n":"第三十九条","txt":"转让背书是指持票人将电子商业汇票权利依法转让给他人的票据行为。 票据在提示付款期后，不得进行转让背书。"},{"i":40,"n":"第四十条","txt":"转让背书应当基于真实、合法的交易关系和债权债务关系，或以税收、继承、捐赠、股利分配等合法行为为基础。"},{"i":41,"n":"第四十一条","txt":"转让背书必须记载下列事项： （一）背书人名称； （二）被背书人名称； （三）背书日期； （四）背书人签章。"},{"i":42,"n":"第四十二条","txt":"贴现是指持票人在票据到期日前，将票据权利背书转让给金融机构，由其扣除一定利息后，将约定金额支付给持票人的票据行为。 转贴现是指持有票据的金融机构在票据到期日前，将票据权利背书转让给其他金融机构，由其扣除一定利息后，将约定金额支付给持票人的票据行为。 再贴现是指持有票据的金融机构在票据到期日前，将票据权利背书转让给中国人民银行，由其扣除一定利息后，将约定金额支付给持票人的票据行为。"},{"i":43,"n":"第四十三条","txt":"贴现、转贴现和再贴现按照交易方式，分为买断式和回购式。 买断式是指贴出人将票据权利转让给贴入人，不约定日后赎回的交易方式。 回购式是指贴出人将票据权利转让给贴入人，约定日后赎回的交易方式。 电子商业汇票贴现、转贴现和再贴现业务中转让票据权利的票据当事人为贴出人，受让票据权利的票据当事人为贴入人。"},{"i":44,"n":"第四十四条","txt":"电子商业汇票当事人在办理回购式贴现、回购式转贴现和回购式再贴现业务时，应明确赎回开放日、赎回截止日。 赎回开放日是指办理回购式贴现赎回、回购式转贴现赎回和回购式再贴现赎回业务的起始日期。 赎回截止日是指办理回购式贴现赎回、回购式转贴现赎回和回购式再贴现赎回业务的截止日期，该日期应早于票据到期日。 自赎回开放日起至赎回截止日止，为赎回开放期。"},{"i":45,"n":"第四十五条","txt":"在赎回开放日前，原贴出人、原贴入人不得作出除追索行为外的其他票据行为。 回购式贴现、回购式转贴现和回购式再贴现业务的原贴出人、原贴入人应按照协议约定，在赎回开放期赎回票据。 在赎回开放期未赎回票据的，原贴入人在赎回截止日后只可将票据背书给他人或行使票据权利，除票据关系以外的其他权利义务关系由双方协议约定。"},{"i":46,"n":"第四十六条","txt":"持票人申请贴现时，应向贴入人提供用以证明其与直接前手间真实交易关系或债权债务关系的合同、发票等其他材料，并在电子商业汇票上作相应记录，贴入人应负责审查。"},{"i":47,"n":"第四十七条","txt":"电子商业汇票贴现、转贴现和再贴现必须记载下列事项： （一）贴出人名称； （二）贴入人名称； （三）贴现、转贴现或再贴现日期； （四）贴现、转贴现或再贴现类型； （五）贴现、转贴现或再贴现利率； （六）实付金额； （七）贴出人签章。 实付金额为贴入人实际支付给贴出人的金额。 回购式贴现、回购式转贴现和回购式再贴现还应记载赎回开放日和赎回截止日。 贴现还应记载贴出人贴现资金入账信息。"},{"i":48,"n":"第四十八条","txt":"电子商业汇票回购式贴现、回购式转贴现和回购式再贴现赎回应作成背书，并记载下列事项： （一）原贴出人名称； （二）原贴入人名称； （三）赎回日期； （四）赎回利率； （五）赎回金额； （六）原贴入人签章。"},{"i":49,"n":"第四十九条","txt":"贴现和转贴现利率、期限等由贴出人与贴入人协商确定。 再贴现利率由中国人民银行规定。"},{"i":50,"n":"第五十条","txt":"电子商业汇票贴现、转贴现和再贴现可选择票款对付方式或其他方式清算资金。 本办法所称票款对付，是指票据交付和资金交割同时完成，并互为条件的一种交易方式。"},{"i":51,"n":"第五十一条","txt":"电子商业汇票的质押，是指电子商业汇票持票人为了给债权提供担保，在票据到期日前在电子商业汇票系统中进行登记，以该票据为债权人设立质权的票据行为。"},{"i":52,"n":"第五十二条","txt":"主债务到期日先于票据到期日，且主债务已经履行完毕的，质权人应按约定解除质押。 主债务到期日先于票据到期日，且主债务到期未履行的，质权人可行使票据权利，但不得继续背书。 票据到期日先于主债务到期日的，质权人可在票据到期后行使票据权利，并与出质人协议将兑现的票款用于提前清偿所担保的债权或继续作为债权的担保。"},{"i":53,"n":"第五十三条","txt":"电子商业汇票质押，必须记载下列事项： （一）出质人名称； （二）质权人名称； （三）质押日期； （四）表明“质押”的字样； （五）出质人签章。"},{"i":54,"n":"第五十四条","txt":"电子商业汇票质押解除，必须记载下列事项： （一）表明“质押解除”的字样； （二）质押解除日期。"},{"i":55,"n":"第五十五条","txt":"电子商业汇票的保证，是指电子商业汇票上记载的债务人以外的第三人保证该票据获得付款的票据行为。"},{"i":56,"n":"第五十六条","txt":"电子商业汇票获得承兑前，保证人作出保证行为的，被保证人为出票人。 电子商业汇票获得承兑后、出票人将电子商业汇票交付收款人前，保证人作出保证行为的，被保证人为承兑人。 出票人将电子商业汇票交付收款人后，保证人作出保证行为的，被保证人为背书人。"},{"i":57,"n":"第五十七条","txt":"电子商业汇票保证，必须记载下列事项： （一）表明“保证”的字样； （二）保证人名称； （三）保证人住所； （四）被保证人名称； （五）保证日期； （六）保证人签章。"},{"i":58,"n":"第五十八条","txt":"提示付款是指持票人通过电子商业汇票系统向承兑人请求付款的行为。 持票人应在提示付款期内向承兑人提示付款。 提示付款期自票据到期日起10日，最后一日遇法定休假日、大额支付系统非营业日、电子商业汇票系统非营业日顺延。"},{"i":59,"n":"第五十九条","txt":"持票人在票据到期日前提示付款的，承兑人可付款或拒绝付款，或于到期日付款。承兑人拒绝付款或未予应答的，持票人可待票据到期后再次提示付款。"},{"i":60,"n":"第六十条","txt":"持票人在提示付款期内提示付款的，承兑人应在收到提示付款请求的当日至迟次日（遇法定休假日、大额支付系统非营业日、电子商业汇票系统非营业日顺延）付款或拒绝付款。 持票人超过提示付款期提示付款的，接入机构不得拒绝受理。持票人在作出合理说明后，承兑人仍应当承担付款责任，并在上款规定的期限内付款或拒绝付款。 电子商业承兑汇票承兑人在票据到期后收到提示付款请求，且在收到该请求次日起第3日（遇法定休假日、大额支付系统非营业日、电子商业汇票系统非营业日顺延）仍未应答的，接入机构应按其与承兑人签订的《电子商业汇票业务服务协议》，进行如下处理： （一）承兑人账户余额在该日电子商业汇票系统营业截止时足够支付票款的，则视同承兑人同意付款，接入机构应扣划承兑人账户资金支付票款，并在下一日（遇法定休假日、大额支付系统非营业日、电子商业汇票系统非营业日顺延）电子商业汇票系统营业开始时，代承兑人作出付款应答，并代理签"},{"i":61,"n":"第六十一条","txt":"接入机构应及时将持票人的提示付款请求通知电子商业承兑汇票的承兑人。通知方式由接入机构与承兑人自行约定。"},{"i":62,"n":"第六十二条","txt":"持票人可选择票款对付方式或其他方式向承兑人提示付款。"},{"i":63,"n":"第六十三条","txt":"电子商业汇票提示付款，必须记载下列事项： （一）提示付款日期； （二）提示付款人签章。 持票人可与接入机构签订协议，委托接入机构代为提示付款并代理签章。"},{"i":64,"n":"第六十四条","txt":"承兑人付款或拒绝付款，必须记载下列事项： （一）承兑人名称； （二）付款日期或拒绝付款日期； （三）承兑人签章。 承兑人拒绝付款的，还应注明拒绝付款的理由。"},{"i":65,"n":"第六十五条","txt":"追索分为拒付追索和非拒付追索。 拒付追索是指电子商业汇票到期后被拒绝付款，持票人请求前手付款的行为。 非拒付追索是指存在下列情形之一，持票人请求前手付款的行为： （一）承兑人被依法宣告破产的； （二）承兑人因违法被责令终止业务活动的。"},{"i":66,"n":"第六十六条","txt":"持票人在票据到期日前被拒付的，不得拒付追索。 持票人在提示付款期内被拒付的，可向所有前手拒付追索。 持票人超过提示付款期提示付款被拒付的，若持票人在提示付款期内曾发出过提示付款，则可向所有前手拒付追索；若未在提示付款期内发出过提示付款，则只可向出票人、承兑人拒付追索。"},{"i":67,"n":"第六十七条","txt":"追索时，追索人应当提供拒付证明。 拒付追索时，拒付证明为票据信息和拒付理由。 非拒付追索时，拒付证明为票据信息和相关法律文件。"},{"i":68,"n":"第六十八条","txt":"持票人因电子商业汇票到期后被拒绝付款或法律法规规定其他原因，拥有的向票据债务人追索的权利时效规定如下： （一）持票人对出票人、承兑人追索和再追索权利时效，自票据到期日起2年，且不短于持票人对其他前手的追索和再追索权利时效。 （二）持票人对其他前手的追索权利时效，自被拒绝付款之日起6个月；持票人对其他前手的再追索权利时效，自清偿日或被提起诉讼之日起3个月。"},{"i":69,"n":"第六十九条","txt":"持票人发出追索通知，必须记载下列事项： （一）追索人名称； （二）被追索人名称； （三）追索通知日期； （四）追索类型； （五）追索金额； （六）追索人签章。"},{"i":70,"n":"第七十条","txt":"电子商业汇票清偿，必须记载下列事项： （一）追索人名称； （二）清偿人名称； （三）同意清偿金额； （四）清偿日期； （五）清偿人签章。"},{"i":71,"n":"第七十一条","txt":"票据当事人可通过接入机构查询与其相关的电子商业汇票票据信息。"},{"i":72,"n":"第七十二条","txt":"接入机构应记录其与电子商业汇票系统之间发送和接收的电子商业汇票票据信息，并按规定将该信息向客户展示。 票据信息包括票面信息和行为信息。 票面信息是指出票人将票据交付收款人后、其他行为发生前，记载在票据上的所有信息。 行为信息是指票据行为的必须记载事项。"},{"i":73,"n":"第七十三条","txt":"出票人可查询电子商业汇票票面信息。 承兑人在收到提示付款申请前，可查询电子商业汇票票面信息。收到提示付款申请后，可查询该票据的所有票据信息。 收款人、被背书人和保证人可查询自身作出的行为信息及之前的票据信息。 持票人可查询所有票据信息。 在追索阶段，被追索人可查询所有票据信息。"},{"i":74,"n":"第七十四条","txt":"票据当事人对票据信息有异议的，应通过接入机构向电子商业汇票系统运营者提出书面申请，电子商业汇票系统运营者应在10个工作日内按照查询权限办理相关查询业务。"},{"i":75,"n":"第七十五条","txt":"电子商业汇票所有票据行为中，处于待签收状态的接收方可向电子商业汇票系统查询该票据承兑人和行为发起方的电子商业汇票支付信用信息。"},{"i":76,"n":"第七十六条","txt":"电子商业汇票系统仅提供票据当事人的电子商业汇票支付信用信息，不对其进行信用评价或评级。"},{"i":77,"n":"第七十七条","txt":"电子商业汇票发生法律纠纷时，电子商业汇票系统运营者负有出具电子商业汇票系统相关记录的义务。"},{"i":78,"n":"第七十八条","txt":"承兑人应及时足额支付电子商业汇票票款。承兑人故意压票、拖延支付，影响持票人资金使用的，按中国人民银行规定的同档次流动资金贷款利率计付赔偿金。"},{"i":79,"n":"第七十九条","txt":"电子银行承兑汇票的出票人于票据到期日未能足额交存票款时，承兑人除向持票人无条件付款外，对出票人尚未支付的汇票金额转入逾期贷款处理，并按照每天万分之五计收罚息。"},{"i":80,"n":"第八十条","txt":"电子商业汇票相关各方存在下列情形之一，影响电子商业汇票业务处理或造成其他票据当事人资金损失的，应承担相应赔偿责任。中国人民银行有权视情节轻重对其处以警告或3万元以下罚款： （一）作为电子银行承兑汇票承兑人的财务公司、电子商业承兑汇票的承兑人违反《中华人民共和国票据法》、《票据管理实施办法》和本办法规定无理拒付或拖延支付的； （二）接入机构为客户提供电子商业汇票业务服务，未对客户基本信息尽审核义务的； （三）为电子商业汇票业务活动提供电子认证服务的电子认证服务提供者，未依据《中华人民共和国电子签名法》承担相应责任的； （四）接入机构为客户提供电子商业汇票业务服务，未对客户电子签名真实性进行认真审核，造成资金损失的； （五）电子商业汇票系统运营者未对接入机构身份真实性和电子签名真实性进行认真审核，造成资金损失的； （六）接入机构因清算资金不足导致电子商业汇票资金清算失败，给票据当事人造成损"},{"i":81,"n":"第八十一条","txt":"电子商业汇票当事人应当妥善保管电子签名制作数据，严防泄露。因保管不善造成资金损失的，有关责任方应当依法承担赔偿责任。"},{"i":82,"n":"第八十二条","txt":"金融机构发现利用电子商业汇票从事违法犯罪活动的，应依法履行报告义务。"},{"i":83,"n":"第八十三条","txt":"电子商业汇票的数据电文格式和票据显示样式由中国人民银行统一规定。"},{"i":84,"n":"第八十四条","txt":"本办法未尽事宜，遵照《中华人民共和国票据法》、《票据管理实施办法》等法律法规执行。"},{"i":85,"n":"第八十五条","txt":"本办法由中国人民银行负责解释和修订。"},{"i":86,"n":"第八十六条","txt":"本办法自公布之日起施行。"}],"lianyinhangyewuguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范银行经营离岸银行业务的行为，根据《中华人民共和国外汇理条例》，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称“银行”是指经国家外汇管理局批准经营外汇业务的中资银行及其分支行。"},{"i":3,"n":"第三条","txt":"本办法所称“离岸银行业务”是指银行吸收非居民的资金，服务于非居民的金融活动。"},{"i":4,"n":"第四条","txt":"本办法所称“非居民”是指在境外(含港、澳、台地区)的自然人、法人(含在境外注册的中国境外投资企业)、政府机构、国际组织及其他经济组织，包括中资金融机构的海外支持机构，但不包括境内机构的境外代表机构和办事机构。"},{"i":5,"n":"第五条","txt":"离岸银行业务经营币种仅限于可自由兑换货币。"},{"i":6,"n":"第六条","txt":"国家外汇管理局及其分局(以下简称“外汇局”)是银行经营离岸银行业务的监管机关，负责离岸银行业务的审批、管理、监督和检查。"},{"i":7,"n":"第七条","txt":"银行应当按照本办法经营离岸银行业务，并参照国际惯例为客户提供服务。"},{"i":8,"n":"第八条","txt":"银行经营离岸银行业务，应当经国家外汇管理局批准，并在批准的业务范围内经营。未经批准，不得擅自经营或者超范围经营离岸银行业务。"},{"i":9,"n":"第九条","txt":"符合下列条件的银行可以申请经营离岸银行业务： (一)遵守国家金融法律法规，近3年内无重大违法违规行为； (二)具有规定的外汇资产规模，且外汇业务经营业绩良好； (三)具有相应素质的外汇从业人员，并在以往经营活动中无不良记录。其中主管人员应当具备5年以上经营外汇业务的资历，其他从业人员中至少应当有50%具备3年以上经营外汇业务的资历； (四)具有完善的内部管理规章制度和风险控制制度； (五)具有适合开展离岸业务的场所和设施； (六)国家外汇管理局要求的其他条件。"},{"i":10,"n":"第十条","txt":"银行申请经营离岸银行业务，应当向外汇局提交下列文件和资料： (一)经营离岸银行业务申请书； (二)经营离岸银行业务的可行性报告； (三)经营外汇业务许可证的正本复印件； (四)经营离岸银行业务的内部管理规章制度和风险控制制度； (五)近3年资产负债表和损益表(外币合并表、人民币和外币合并表)； (六)离岸银行业务主管人员和其他从业人员名单、履历，外汇局核发的外汇从业人员资格证书； (七)经营离岸银行业务的场所和设施情况简介； (八)国家外汇管理局要求的其他文件和资料。 银行分行申请开办离岸银行业务除提交上述文件和资料外，还应当提交其总行同意其开办离岸银行业务的文件、总行出具的经营离岸银行业务的授权书和筹备离岸银行业务的验收报告。"},{"i":11,"n":"第十一条","txt":"银行总行申请经营离岸银行业务，由国家外汇管理局审批；银行分行申请经营离岸银行业务，由当地外汇局初审后，报国家外汇管理局审批。"},{"i":12,"n":"第十二条","txt":"国家外汇管理局收到银行经营离岸银行业务的申请后，应当予审核，并自收到申请报告之日起4个月内予以批复。对于不符合开办离岸银行业务条件的银行，国家外汇管理局将其申请退回。自退回之日起，6个月内银行不得就同一内容再次提出申请。"},{"i":13,"n":"第十三条","txt":"经批准经营离岸的银行自批准之日起6个月内不开办业务的，视同自动终止离岸银行业务。国家外汇管理局有权取消其经营离岸银行业务的资格。"},{"i":14,"n":"第十四条","txt":"银行申请停办离岸银行业务，应当向外汇局提交下列文件和资料： (一)停办离岸银行业务的申请报告； (二)停办离岸银行业务的详细说明(包括停办离岸银行业务原因和停办离岸银行业务后债权债务清理措施、步骤)； (三)国家外汇管理局要求的其他文件和资料。 银行分行申请停办离岸银行业务除提交上述文件和资料外，还应当提交其总行同意其停办离岸银行业务的文件。"},{"i":15,"n":"第十五条","txt":"国家外汇管理局收到银行停办离岸银行业务的申请后，应当自收到申请之日起4个月内予以批复。银行经国家外汇管理局审查批准后方可停办离岸银行业务。"},{"i":16,"n":"第十六条","txt":"银行可以申请下列部分或者全部离岸银行业务： (一)外汇存款； (二)外汇贷款； (三)同业外汇拆借； (四)国际结算； (五)发行大额可转让存款证； (六)外汇担保； (七)咨询、见证业务； (八)国家外汇管理局批准的其他业务。"},{"i":17,"n":"第十七条","txt":"本办法所称“外汇存款”有以下限制： (一)非居民法人最低存款额为等值5万美元的可自由兑换货币，非居民自然人最低存款额为等值1万美元的可自由兑换货币。 (二)非现钞存款。 本办法所称“同业外汇拆借”是指银行与国际金融市场及境内其他银行离岸资金间的同业拆借。 本办法所称“发行大额可转让存款证”是指以总行名义发行的大额可转让存款证。"},{"i":18,"n":"第十八条","txt":"国家外汇管理局对申请开办离岸银行业务的银行实行审批前的面谈制度。"},{"i":19,"n":"第十九条","txt":"银行对离岸银行业务应当与在岸银行业务实行分离型管理，设立独立的离岸银行业务部门，配备专职业务人员，设立单独的离岸银行业务帐户，并使用离岸银行业务专用凭证和业务专用章。"},{"i":20,"n":"第二十条","txt":"经营离岸银行业务的银行应当建立、健全离岸银行业务财务、会计制度。离岸业务与在岸业务分帐管理，离岸业务的资产负债和损益年终与在岸外汇业务税后并表。"},{"i":21,"n":"第二十一条","txt":"银行应当对离岸银行业务风险单独监测。外汇局将银行离岸银行业务资产负债计入外汇资产负债表中进行总体考核。"},{"i":22,"n":"第二十二条","txt":"离岸银行业务的外汇存款、外汇贷款利率可以参照国际金融市场利率制定。"},{"i":23,"n":"第二十三条","txt":"银行吸收离岸存款免交存款准备金。"},{"i":24,"n":"第二十四条","txt":"银行发行大额可转让存款证应当报国家外汇管理局审批。由国家外汇管理局核定规模和入市条件。"},{"i":25,"n":"第二十五条","txt":"离岸帐户抬头应当注明“OSA”(OFFSHORE ACCOUNT)"},{"i":26,"n":"第二十六条","txt":"非居民资金汇往离岸帐户和离岸帐户资金汇往境外帐户以及离岸帐户之间的资金可以自由进出； 离岸帐户和在岸帐户间的资金往来，银行应当按照以下规定办理： (一)在岸帐户资金汇往离岸帐户的，汇出行应当按照结汇、售汇及付汇管理规定和贸易进口付汇核销监管规定，严格审查有效商业单据和有效凭证，并且按照《国际收支统计申报办法》进行申报。 (二)离岸帐户资金汇往在岸帐户的，汇入行应当按照结汇、售汇及付汇管理规定和出口收汇核销管理规定，严格审查有效商业单据和有效凭证，并且按照《国际收支统计申报办法》进行申报。"},{"i":27,"n":"第二十七条","txt":"银行离岸帐户头寸与在岸帐户头寸相互抵补的限额和期限由国家外汇管理局核定。未经批准，银行不得超过核定的限额和期限。"},{"i":28,"n":"第二十八条","txt":"经营离岸银行业务的银行应当按照规定向外汇局报送离岸银行业务财务报表和统计报表。"},{"i":29,"n":"第二十九条","txt":"经营离岸银行业务的银行发生下列情况，应当在1个工作日内主动向外汇局报告，并且及时予以纠正： (一)离岸帐户与在岸帐户的头寸抵补超过规定限额； (二)离岸银行业务的经营出现重大亏损； (三)离岸银行业务发生其他重大异常情况； (四)银行认为应当报告的其他情况。"},{"i":30,"n":"第三十条","txt":"外汇局定期对银行经营离岸银行业务的情况进行检查和考评，检查和考评的内容包括： (一)离岸银行资产质量情况； (二)离岸银行业务收益情况； (三)离岸银行业务内部管理规章制度和风险控制制度的执行情况； (四)国家外汇管理局规定的其他情况。"},{"i":31,"n":"第三十一条","txt":"未经国家外汇管理局批准，擅自经营和超范围经营离岸银行业务的，由外汇局根据《中华人民共和国外汇管理条例》第四十一条的规定进行处罚；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"银行违反本办法第二十二条规定的，由外汇局根据《中华人民共和国外汇管理条例》第四十三条的规定进行处罚。"},{"i":33,"n":"第三十三条","txt":"银行违反本办法第二十四条、第二十七条规定的，由外汇局根据《中华人民共和国外汇管理条例》第四十四条的规定进行处罚；构成犯罪的，依法追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"银行违反本办法第二十六条规定的，由外汇局根据《中华人民共和国外汇管理条例》第三十九、四十、四十八条的规定进行处罚；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"银行违反本办法第二十八、二十九条规定或者不配合外汇局检查和考评的，由外汇局根据《中华人民共和国外汇管理条例》第四十九条的规定进行处罚。"},{"i":36,"n":"第三十六条","txt":"外资金融机构经营离岸银行业务，另行规定。"},{"i":37,"n":"第三十七条","txt":"本办法由国家外汇管理局负责解释。"},{"i":38,"n":"第三十八条","txt":"本办法自1998年1月1日起施行。"}],"xitongzhongyaoxingyinhangfujiajianguanguiding":[{"i":1,"n":"第一条","txt":"为完善我国系统重要性金融机构监管框架，明确系统重要性银行附加监管要求，加强宏观审慎管理，根据《中华人民共和国中国人民银行法》《中华人民共和国银行业监督管理法》《中华人民共和国商业银行法》等法律法规和完善系统重要性金融机构监管的相关要求，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于依据《系统重要性银行评估办法》认定的系统重要性银行。"},{"i":3,"n":"第三条","txt":"人民银行负责系统重要性银行附加监管规则制定、监测分析，视情要求银保监会采取相应监管措施，并在必要时经国务院批准对系统重要性银行进行检查监督。人民银行会同银保监会提出附加监管要求，牵头银保监会等单位组建危机管理小组，组织审查系统重要性银行恢复计划和处置计划建议，开展可处置性评估。 银保监会依法对系统重要性银行实施微观审慎监管，本规定提出的附加监管要求不取代银保监会的日常监管职责。"},{"i":4,"n":"第四条","txt":"系统重要性银行在满足最低资本要求、储备资本和逆周期资本要求基础上，还应满足一定的附加资本要求，由核心一级资本满足。 系统重要性银行分为五组，第一组到第五组的银行分别适用0.25%、0.5%、0.75%、1%和1.5%的附加资本要求。若银行同时被认定为我国系统重要性银行和全球系统重要性银行，附加资本要求不叠加，采用二者孰高原则确定。 银行应在进入系统重要性银行名单或者系统重要性得分变化导致组别上升后，在经过一个完整自然年度后的1月1日满足附加资本要求。若银行退出系统重要性银行名单或者系统重要性得分变化导致组别下降，立即适用新的资本要求。 人民银行、银保监会可以根据宏观经济形势、金融风险变化和银行业发展实际对系统重要性银行附加资本要求进行调整，报国务院金融稳定发展委员会审议通过后实施。 系统重要性银行应拥有充足的资本和债务工具，增强总损失吸收能力，在经营困难时能够通过减记或转股的方式吸收损"},{"i":5,"n":"第五条","txt":"系统重要性银行应建立资本内在约束机制，提高资本内生积累能力，切实发挥资本对业务发展的指导和约束作用。人民银行、银保监会在整体资本管理框架下，根据系统重要性银行的业务经营状况和风险情况，结合压力测试结果，定期对系统重要性银行的资本状况进行全面评估，前瞻性、针对性地评估银行在压力情景下可能出现的资本缺口，并将评估结果作为提出资本监管要求的重要参考。"},{"i":6,"n":"第六条","txt":"系统重要性银行在满足杠杆率要求的基础上，应额外满足附加杠杆率要求。附加杠杆率要求为系统重要性银行附加资本要求的50%，由一级资本满足。 银行应在进入系统重要性银行名单或者系统重要性得分变化导致组别上升后，在经过一个完整自然年度后的1月1日满足附加杠杆率要求。若银行退出系统重要性银行名单或系统重要性得分变化导致组别下降，立即适用新的杠杆率要求。 人民银行、银保监会可以根据宏观经济形势、金融风险变化和银行业发展实际对系统重要性银行附加杠杆率要求进行调整，报国务院金融稳定发展委员会审议通过后实施。"},{"i":7,"n":"第七条","txt":"人民银行会同银保监会基于对实质性风险的判断，对高得分组别系统重要性银行的流动性和大额风险暴露进行评估，根据评估结果提出附加监管要求，报国务院金融稳定发展委员会审议通过后实施。"},{"i":8,"n":"第八条","txt":"恢复计划应详细说明银行在持续经营能力出现问题等压力情景下，如何通过实施该恢复计划恢复持续经营能力。处置计划应详细说明银行在无法持续经营时，如何通过实施该处置计划实现安全、快速、有效处置，保障关键业务和服务不中断，避免引发系统性金融风险。 首次进入系统重要性银行名单的银行，应当根据自身经营特点、风险和管理状况，按照人民银行、银保监会的要求，制定集团层面的恢复计划和处置计划建议，并于下一年度8月31日前提交危机管理小组审查。系统重要性银行每年更新恢复计划、每两年更新处置计划建议并于更新年度8月31日前报送危机管理小组，并且在内外部经营环境、风险状况发生重大变化时，按照人民银行、银保监会要求进行更新。危机管理小组应自收到恢复计划和处置计划建议之日起2个月内提出书面意见。恢复计划和处置计划建议未获认可的，系统重要性银行应按照要求在危机管理小组规定的时限内完成整改并重新报送。危机管理小组应根据处"},{"i":9,"n":"第九条","txt":"在系统重要性银行持续经营能力可能或者已经出现问题等压力情景下，满足预先设定的触发条件，系统重要性银行启动并执行恢复计划，快速补充资本和流动性，以度过危机并恢复持续经营能力。恢复计划包括但不限于： （一）机构概览，恢复计划治理架构与职责划分。 （二）关键功能与核心业务、关键共享服务和重要实体识别，风险领域和薄弱环节。 （三）恢复措施的触发机制，包括触发指标定义及设置等。 （四）压力情景设计、分析及各压力情景下的措施有效性检验。 （五）银行在面临资本不足或流动性困难时可以采取的措施及具体执行方案，包括补充流动性、资产出售、补充资本、暂停或限制分红、压缩经营成本等。 （六）银行向人民银行、银保监会等部门报告和沟通策略等安排。 （七）银行实施恢复计划的障碍及解决障碍的措施。"},{"i":10,"n":"第十条","txt":"处置计划建议应立足于机构自救，落实自救资金来源和制度安排，采取内部纾困模式，落实股东和债权人的风险化解与损失承担责任，具体内容包括但不限于： （一）机构概览，处置计划治理架构与职责划分。 （二）关键功能与核心业务、关键共享服务和重要实体识别。 （三）处置策略分析，处置权力分析（例如更换负有责任的管理层等相关人员），处置工具分析（例如收购与承接、过桥银行、经营中救助）等。 （四）处置措施的触发机制。 （五）处置措施和方案，包括对实现快速稳定、提升长期生存能力的分析，以及采取的主要措施，例如内部财务纾困、业务转让、部分或全部资产及负债转让等。 （六）保障有效处置的支持性分析，包括处置资金计划和来源、估值能力、关键服务持续运营安排、金融市场基础设施及持续接入安排、消费者权益保护方案等。 （七）与境内外相关部门的协调和信息共享、沟通策略等。 （八）处置实施障碍分析及解决障碍的计划措施。 （九）"},{"i":11,"n":"第十一条","txt":"危机管理小组定期开展可处置性评估，确保处置计划具有可行性和可靠性，并根据评估情况完善处置框架。当系统重要性银行发生兼并、收购、重组等重大变化时，危机管理小组应当及时评估其可处置性的变化情况。若银行退出系统重要性银行名单，危机管理小组不再对其开展可处置性评估。可处置性评估应至少包含以下内容： （一）处置计划中涉及的处置权力和处置工具是否合法可行。 （二）处置资金来源及资金安排是否充足、明确。 （三）关键功能的识别方法是否合理。 （四）关键功能和关键共享服务是否有合理的安排，以保证处置中的持续运行。 （五）金融市场基础设施能否持续接入，以保证关键功能不中断。 （六）组织架构及管理信息系统能否支持处置。 （七）处置中的跨部门合作和信息共享安排是否可行。 （八）处置影响分析，包括对金融市场的影响、对金融基础设施的影响、对其他金融机构融资行为的影响、对其他金融机构资本充足率的影响、对实体经济的影"},{"i":12,"n":"第十二条","txt":"危机管理小组的职责包括但不限于： （一）定期审查恢复计划和处置计划建议，确保恢复计划和处置计划与银行的系统重要性相匹配，并且有效、可操作。 （二）定期开展可处置性评估，确保系统重要性银行的组织架构、管理水平、基础设施建设和能力能够有效支持处置。"},{"i":13,"n":"第十三条","txt":"系统重要性银行应执行人民银行牵头制定的系统重要性金融机构统计制度，按要求向人民银行、银保监会报送统计报表。按要求报送财务会计报告、年度业务发展计划、信贷计划和利润计划、压力测试报告和其他资料。每年应当向人民银行、银保监会报送全面风险管理报告，包括对银行风险状况的全面分析、风险防控体系有效性的评估、资产质量报告、改进风险管理水平的具体措施以及人民银行、银保监会要求报送的其他信息。及时向危机管理小组报送审查恢复计划和处置计划建议、开展可处置性评估所需要的相关信息，确保自身管理信息系统能够迅速、全面满足相关信息报送要求。发生兼并、收购、重组等重大变化时，及时向危机管理小组报送相关重大变化对恢复计划和处置计划等的影响分析报告。 系统重要性银行应每年通过官方网站或年度报告披露资本充足率、杠杆率、流动性、大额风险暴露等监管指标情况，并说明附加监管要求满足情况。披露时间不得晚于每年4月30日。因特殊"},{"i":14,"n":"第十四条","txt":"系统重要性银行应当全面梳理经营管理中的风险领域和薄弱环节，建立覆盖所有实质性风险领域的风险数据加总和风险报告体系。风险数据加总应确保风险数据的定义、收集和处理能够真实反映银行的风险容忍度和风险偏好，客观衡量风险调整后的经营表现，满足风险报告的需要。系统重要性银行基于规范的汇报路径和程序，按要求将风险信息及时、准确、清晰、完整地报告给人民银行、银保监会等部门。风险数据加总和风险报告体系包括但不限于： （一）在集团层面建立风险数据加总和风险报告体系的治理架构，明确董事会、高级管理层和各相关部门职责，确保与集团整体治理架构相适应，并保证相应的资源安排。 （二）在集团层面加强信息技术基础设施建设，统一数据结构，建立精细化的数据分类体系和数据字典，健全各业务条线、法人机构、各类资产、各个行业和地区风险敞口及潜在风险的数据库。 （三）提高数据加总和分类的自动化程度，确保在整个集团范围内全部风险数据"},{"i":15,"n":"第十五条","txt":"银行进入系统重要性银行名单后，由董事会承担相关工作的最终责任。董事会的职责包括但不限于： （一）负责推动系统重要性银行达到附加监管要求，并承担最终责任。 （二）制定有效的资本规划，建立资本内在约束机制，定期审查评估资本规划的实施情况，确保资本水平持续满足监管要求。 （三）负责审批恢复计划和处置计划建议，对恢复计划和处置计划建议的制定与更新承担最终责任。 （四）审批集团风险数据加总和风险报告框架，确保充足的资源支持，定期听取专题汇报，充分了解和掌握风险数据加总和风险报告工作的进展情况。 （五）负责推动落实人民银行、银保监会作出的风险提示和整改要求，并承担最终责任。 高级管理层成立以行长为组长的专门领导工作组，承担相关工作的统筹协调与组织实施职责。"},{"i":16,"n":"第十六条","txt":"人民银行在并表基础上加强对系统重要性银行监测分析和风险评估，包括但不限于： （一）在并表基础上收集和分析系统重要性银行的财务数据、资本充足情况、流动性、大额风险暴露、关联交易和内部交易等定量信息。 （二）收集系统重要性银行集团层面的公司治理、内部控制、防火墙建设和风险管理等定性信息。 （三）定期评估系统重要性银行集团层面的风险及风险管理状况、跨境经营情况、跨业经营情况以及内部风险交叉传染途径。 银保监会依法对系统重要性银行实行并表监督管理，实施强化性监管要求。"},{"i":17,"n":"第十七条","txt":"人民银行、银保监会及时共享系统重要性银行的统计报表、监管报告以及其他重大风险报告。在对系统重要性银行发生的兼并、收购、重组等重大变化进行审批时，银保监会应及时将相关信息告知人民银行。"},{"i":18,"n":"第十八条","txt":"人民银行、银保监会从防范系统性金融风险的角度，设定不同的压力测试情景，指定压力测试模型和方法，定期对系统重要性银行开展压力测试，评估银行的资本规划及资本充足状况、流动性、大额风险暴露等风险状况，检验恢复计划和处置计划的可行性，并根据压力测试结果对系统重要性银行提出相应的监管要求。"},{"i":19,"n":"第十九条","txt":"人民银行、银保监会可基于监测分析和压力测试结果，评估系统重要性银行的信贷集中度、复杂性、业务扩张速度等关键指标情况，强化事前风险预警，引导银行降低系统性金融风险。 系统重要性银行存在违反审慎经营规则或威胁金融稳定情形的，人民银行可向该银行直接作出风险提示，并抄送银保监会。必要时，人民银行商银保监会按照法定程序对系统重要性银行的业务结构、经营策略和组织架构提出调整建议，并推进有效实施。系统重要性银行应按要求限期整改，并在规定期限内向人民银行和银保监会提交整改报告。"},{"i":20,"n":"第二十条","txt":"系统重要性银行违反附加监管规定的，人民银行、银保监会应当要求其限期整改。对于逾期未完成整改的，人民银行、银保监会可以与银行的董事、高级管理人员进行监督管理谈话，人民银行可以建议银保监会采取审慎监管措施，银保监会积极采纳建议并及时作出回复。"},{"i":21,"n":"第二十一条","txt":"本规定由人民银行和银保监会负责解释。"},{"i":22,"n":"第二十二条","txt":"本规定自2021年12月1日起施行。自本规定施行之日起，系统重要性银行附加资本要求不再适用《商业银行资本管理办法（试行）》（中国银行业监督管理委员会令2012年第1号发布）第二十五条的规定。"}],"tongzhicunkuanguanlibanfa":[{"i":1,"n":"第一条","txt":"为进一步规范通知存款业务，维护存款人的利益，根据《中华人民共和国中国人民银行法》及其他相关法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称通知存款，是指存款人在存入款项时不约定存期，支取时需提前通知金融机构，约定支取存款日期和金额方能支取的存款。"},{"i":3,"n":"第三条","txt":"凡在中华人民共和国境内的个人、法人和其他组织，均可到经中国人民银行批准开办通知存款业务的金融机构办理该项存款。"},{"i":4,"n":"第四条","txt":"通知存款不论实际存期多长，按存款人提前通知的期限长短划分为一天通知存款和七天通知存款两个品种。一天通知存款必须提前一天通知约定支取存款，七天通知存款必须提前七天通知约定支取存款。"},{"i":5,"n":"第五条","txt":"通知存款的最低起存金额：个人为5万元，单位为50万元；最低支取金额：个人为5万元；单位为10万元。存款人需一次性存入，可以一次或分次支取。"},{"i":6,"n":"第六条","txt":"通知存款为记名式存款。个人通知存款采用记名存单形式，单位通知存款采用记名存款凭证形式。存单或存款凭证须注明“通知存款”字样。"},{"i":7,"n":"第七条","txt":"存款人提前通知金融机构约定支取通知存款的方式由金融机构与存款人自行约定。"},{"i":8,"n":"第八条","txt":"通知存款存入时，存款人自由选择通知存款品种（一天通知存款或七天通知存款），但存单或存款凭证上不注明存期和利率，金融机构按支取日挂牌公告的相应利率水平和实际存期计息，利随本清。"},{"i":9,"n":"第九条","txt":"通知存款如遇以下情况，按活期存款利率计息： （一）实际存期不足通知期限的，按活期存款利率计息； （二）未提前通知而支取的，支取部分按活期存款利率计息； （三）已办理通知手续而提前支取或逾期支取的，支取部分按活期存款利率计息； （四）支取金额不足或超过约定金额的，不足或超过部分按活期存款利率计息； （五）支取金额不足最低支取金额的，按活期存款利率计息。"},{"i":10,"n":"第十条","txt":"通知存款如已办理通知手续而不支取或在通知期限内取消通知的，通知期限内不计息。"},{"i":11,"n":"第十一条","txt":"通知存款部分支取，留存部分高于最低起存金额的，需重新填写通知存款单或凭证，从原开户日计算存期；留存部分低于起存金额的予以清户，按清户日挂牌公告的活期存款利率计息，或根据存款人意愿转为其他存款。"},{"i":12,"n":"第十二条","txt":"邮政储蓄部门办理通知存款业务，按本办法执行。"},{"i":13,"n":"第十三条","txt":"金融机构或邮政储蓄部门违反本办法办理通知存款业务的，由中国人民银行按照有关规定进行相应的处罚。"},{"i":14,"n":"第十四条","txt":"本办法仅适用于人民币业务，自颁布之日起执行。凡与本办法内容不一致的，以本办法为准。"},{"i":15,"n":"第十五条","txt":"本办法由中国人民银行总行解释和修改。"}],"jinrongjichusheshijianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强金融基础设施统筹监管与建设规划，保障金融体系安全高效运行，根据《中华人民共和国中国人民银行法》、《中华人民共和国证券法》、《中华人民共和国期货和衍生品法》、《中华人民共和国公司法》、《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《中华人民共和国个人信息保护法》、《期货交易管理条例》、《征信业管理条例》、《关键信息基础设施安全保护条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"经国务院或金融基础设施管理部门批准设立的金融基础设施，其建设、运营、维护和监督管理，适用本办法。法律、行政法规、国务院及金融基础设施管理部门另有规定的，从其规定。"},{"i":3,"n":"第三条","txt":"本办法所称金融基础设施，是指金融资产登记存管系统、清算结算系统（含开展集中清算业务的中央对手方）、交易设施、交易报告库，重要支付系统，基础征信系统。 本办法所称金融基础设施管理部门，是指中国人民银行、中国证券监督管理委员会。"},{"i":4,"n":"第四条","txt":"以习近平新时代中国特色社会主义思想为指导，坚持党中央对金融工作的集中统一领导。金融基础设施运营机构应当按照党章、党规要求设立党组织，加强党的建设，确保党的路线方针和国家重大战略部署在金融基础设施运营机构得到贯彻执行。 本办法所称金融基础设施运营机构，是指根据法律、行政法规、国务院相关决定及本办法规定，经批准负责建设、运营和维护金融基础设施的企业法人或事业单位法人。"},{"i":5,"n":"第五条","txt":"金融基础设施管理部门要加强规划引领，按照构建现代化基础设施体系的统一部署，促进金融基础设施之间有序互联互通，按照安全、高效原则，不断优化金融基础设施布局，增强整体性，加强金融基础设施治理体系建设，促使金融基础设施运营机构服从大局、优先维护公共利益，进一步完善治理，提高运行效率与服务水平，防止过度追求利润和承担风险，促进服务市场与支持监管并重。根据统一大市场建设要求，审慎开展新设金融基础设施工作，对于涉及国家金融安全、外溢性强的金融基础设施，保持国家绝对控制力。"},{"i":6,"n":"第六条","txt":"金融基础设施的准入和监督管理，应当遵循“谁审批、谁监管、谁负责”的原则，符合国家战略和规划，符合国家经济社会发展需要，维护国家金融安全。"},{"i":7,"n":"第七条","txt":"金融基础设施的建设、运营、维护和监管，应当立足我国实际情况，与《金融市场基础设施原则（PFMI）》等国际准则相接轨。"},{"i":8,"n":"第八条","txt":"在中华人民共和国境内设立金融基础设施，依照《中华人民共和国中国人民银行法》、《中华人民共和国证券法》、《中华人民共和国期货和衍生品法》、《期货交易管理条例》、《征信业管理条例》等法律、行政法规，以及国务院相关规定进行管理，并与市场准入负面清单制度做好衔接。 中国证券监督管理委员会负责涉及证券、期货及其相关活动的新设金融基础设施的准入管理；中国人民银行负责新设支付系统、基础征信系统以及银行间市场金融基础设施的准入管理；其他新设金融基础设施由中国人民银行会同其他相关部门负责准入管理。涉及或可能涉及对金融体系产生重大影响或相关部门认为确有必要的金融基础设施，应当报经国务院同意后批准。对于其中影响或可能影响中华人民共和国国家安全的外商投资，依法进行外商投资安全审查。 任何单位或个人不得非法设立运营金融基础设施，不得非法提供或变相提供金融基础设施相关服务，不得非法使用“交易所”、“交易中心”、“"},{"i":9,"n":"第九条","txt":"金融基础设施的运营机构应当具备下列条件： （一）具有在中华人民共和国境内合法成立的法人实体； （二）具有清晰、透明的组织结构和治理安排，不违反中华人民共和国国家利益及社会公共利益； （三）具有符合规定的注册资本和实缴资本； （四）具有必要的营业场所和支持业务开展的、安全且合规的系统与设施； （五）具有与拟开展业务相适应的风险管理制度、内控制度、业务规则等制度安排； （六）拟任董事（理事）、监事和高级管理人员符合本办法规定的任职条件； （七）股东与实际控制人具有必要的运营经验，信用记录良好，无故意或重大过失犯罪记录，且3年内无重大违法违规事项或受到重大监管处罚。 事业单位法人运营的金融基础设施原则上参照执行。"},{"i":10,"n":"第十条","txt":"金融基础设施运营机构的董事（理事）、监事和高级管理人员，应当具有大学本科及以上学历，信用记录良好，熟悉与本领域金融基础设施相关的法律法规与国际监管准则，具有5年以上金融领域相关从业经验和履行职责所需的管理能力，最近5年无重大违法违规记录。金融基础设施运营机构采取公司制组织形式的，其董事、监事、高级管理人员应当同时符合《中华人民共和国公司法》第一百七十八条的规定。"},{"i":11,"n":"第十一条","txt":"金融基础设施运营机构有以下事项之一的，应当根据各部门职责分工报相关金融基础设施管理部门批准： （一）变更自身或所运营金融基础设施的名称； （二）变更注册资本； （三）变更住所或营业场所； （四）调整自身或所运营金融基础设施的业务范围； （五）变更持有资本总额或股份总额百分之五以上的主要股东、实际控制人、受益所有人； （六）变更法定代表人、董事长（理事长）、总经理； （七）修改法人章程； （八）所运营的金融基础设施与境内外其他金融基础设施建立系统连接，或与境内外其他金融基础设施运营机构开展重大业务合作。"},{"i":12,"n":"第十二条","txt":"金融基础设施管理部门依法公布金融基础设施及运营机构名单。"},{"i":13,"n":"第十三条","txt":"金融基础设施运营机构应当建立健全清晰、透明的治理结构和有效的问责机制，并及时对外披露。"},{"i":14,"n":"第十四条","txt":"金融基础设施运营机构应当参考《金融市场基础设施原则（PFMI）》等相关要求设立风险管理委员会，建立健全稳健的风险管理框架，确保能够识别、度量、监测和管理所涉及的相关风险，包括但不限于： （一）有效度量、监测和管理来自参与者的信用风险和来自在支付、清算和结算过程中产生的信用风险，并通过高信用等级、低流动性风险和低市场风险的担保品管理自身的信用风险敞口； （二）有效度量、监测和管理流动性风险。金融基础设施运营机构应当持有足够的流动性资源，包括但不限于现金、存款、商业银行授信额度等； （三）有效度量、监测和管理整体市场运行风险； （四）保持不低于六个月当前运营成本的优质流动性资产，以弥补可能发生的经营性亏损，保障持续运营。优质流动性资产范围由相关部门另行规定； （五）将用于满足六个月经营需要的自有资产和参与者资产保存在经金融基础设施管理部门认可的金融机构或专业机构； （六）定期监测和评估参与"},{"i":15,"n":"第十五条","txt":"金融基础设施运营机构应当建立完善的技术系统及管理机制，包括： （一）符合必要的技术规范、通信程序与标准； （二）系统故障应急处理机制和灾难备份机制，具备完善的数据安全保护和数据备份措施，灾难备份中心应当位于中华人民共和国境内； （三）有效的网络安全管理制度，系统重要性金融基础设施还应当落实关键信息基础设施安全保护相关法律、行政法规要求； （四）完备的数据存储管理机制，在中华人民共和国境内运营过程中收集和产生的个人信息和重要数据应当在境内存储。因业务需要，确需向境外提供的，应当符合国家有关规定。"},{"i":16,"n":"第十六条","txt":"金融基础设施运营机构应当建立完善的内控制度，采取有效措施，防范自身与金融基础设施的参与者之间，以及金融基础设施的不同参与者之间的利益冲突。"},{"i":17,"n":"第十七条","txt":"金融基础设施运营机构应当妥善保存金融基础设施服务的原始凭证和重要数据，以及与内部管理、业务经营有关的重要信息，保存期限应当不少于20年，法律、行政法规另有规定的除外。"},{"i":18,"n":"第十八条","txt":"金融基础设施运营机构应当加强数据安全管理，承担数据安全管理主体责任，建立和完善有效的内部数据安全管理制度和问责办法，对金融基础设施参与者的业务数据、相关资料，以及提供服务过程中产生的其他数据进行保护，确保数据不被损毁、非法窃取及非法使用，不得侵害个人信息权益。法律、行政法规或相关金融基础设施管理部门对数据处理有明确规定的，从其规定。 金融基础设施运营机构应当为参与者及时获得与其相关的数据及资料提供便利。 金融基础设施运营机构应当建立完备的差错争议和客户投诉处理机制，及时、妥善解决差错争议和客户投诉，切实维护客户合法权益。"},{"i":19,"n":"第十九条","txt":"金融基础设施运营机构相关服务涉及外包的，应当明确服务外包不得转移责任，金融基础设施运营机构与金融基础设施参与者之间的法律关系不发生改变，且不得妨碍金融基础设施管理部门履行相关监管职能。"},{"i":20,"n":"第二十条","txt":"金融基础设施运营机构应当承担参与者管理主体责任，切实采取措施强化参与者的监督和管理。金融基础设施运营机构与金融基础设施参与者之间应当通过签订协议、公约或制定业务规则等方式，明确各方权利、义务和责任。"},{"i":21,"n":"第二十一条","txt":"金融基础设施之间通过相关系统连接开展业务合作，其运营机构之间应当通过签订协议或公约等形式，明确各方权利、义务和责任，确保法律关系清晰，并应当有效识别与管理相关风险，包括但不限于： （一）准确识别所连接金融基础设施的运营机构相关资质，确保对方具备良好的公司治理结构； （二）有效管理运行、信用、流动性、技术和法律等各类风险，包括建立有效的风险识别和隔离机制，避免与所连接金融基础设施之间的风险传染。"},{"i":22,"n":"第二十二条","txt":"金融基础设施运营机构应当建立健全应急预案，涵盖重大疫情、自然灾害、金融市场异常波动、外部冲击、网络安全事件、数据安全事件等可能影响持续稳健经营的极端情形，以及相应情形下拟采取的应急处置措施，并与建立系统连接的其他金融基础设施应急处置预案有效衔接，维护金融市场安全平稳运行。"},{"i":23,"n":"第二十三条","txt":"金融基础设施运营机构发生下列情形，应当按照部门职责分工及时向相关金融基础设施管理部门备案： （一）制定并实施恢复计划； （二）变更其他董事（理事）、监事及高级管理人员。"},{"i":24,"n":"第二十四条","txt":"金融基础设施运营机构应当按照部门职责分工定期向相关金融基础设施管理部门报告自身经营、金融基础设施业务开展及展业合规等相关情况。 金融基础设施及其运营机构发生下列重大事项的，金融基础设施运营机构应当及时向相关金融基础设施管理部门报告： （一）发生系统故障、人为操作失误、数据泄露等事故，或因自然灾害等其他情形引发核心业务异常并造成实质性影响； （二）发生对其正常经营有重大影响的诉讼、仲裁，或存在重大或有负债、或有损失的事项； （三）重要业务系统上线、发生重大变更、下线等。"},{"i":25,"n":"第二十五条","txt":"为境内居民或机构提供跨境交付服务的境外金融基础设施及其运营机构，应当遵守本办法相关管理要求，开展金融基础设施服务3年以上，受到其所在国家或地区相应政府机构的具有可比性且全面的监管与规制，未出现重大风险事故、重大违法违规事项或受到相关监管机构处罚且情节严重的情形。跨境交付服务指境外金融基础设施向境内居民或机构提供金融基础设施服务。 为境内居民或机构提供跨境交付服务的境外金融基础设施所在国家或地区的有关监管机构应当与相关金融基础设施管理部门签署谅解备忘录。我国另有规定的，从其规定。 按照监管对等原则，为境内居民或机构提供跨境交付服务的境外金融基础设施及其运营机构，应当就下列事项，定期向相关金融基础设施管理部门报告： （一）境外展业合规情况； （二）在境外取得监管授权与豁免、业务牌照和许可的情况； （三）基于《金融市场基础设施原则（PFMI）》开展的自评估报告（如适用）。 金融基础设施管理部"},{"i":26,"n":"第二十六条","txt":"金融基础设施运营机构应当按照相关金融基础设施管理部门有关规定，向国家金融基础数据库报送金融业综合统计相关数据。国家金融基础数据库应当按照相关规定，加强制度化信息共享。"},{"i":27,"n":"第二十七条","txt":"金融基础设施运营机构应当于每年四月底前向相关金融基础设施管理部门报告前一年财务情况。"},{"i":28,"n":"第二十八条","txt":"中国人民银行依照法律、行政法规负责对支付系统、基础征信系统以及银行间市场金融基础设施和相关运营机构进行检查；中国证券监督管理委员会依照法律、行政法规负责对涉及证券、期货及其相关活动的金融基础设施和相关运营机构进行检查。"},{"i":29,"n":"第二十九条","txt":"金融基础设施运营机构及其工作人员应当配合检查与评估，并及时提供有关文件材料，保证材料真实、准确、完整，不得拒绝、阻碍和隐瞒。"},{"i":30,"n":"第三十条","txt":"金融基础设施运营机构应当制定发生风险时的恢复计划并定期更新。 金融基础设施管理部门作为金融基础设施风险处置的牵头部门，按职责分工负责对恢复计划失效且难以保证关键性业务连续性的金融基础设施实施处置措施。 金融基础设施及其运营机构难以持续经营，或严重危害金融秩序、损害公众利益的，应当依法实施市场退出。"},{"i":31,"n":"第三十一条","txt":"经认定符合以下部分或全部标准的，属于系统重要性金融基础设施，由金融基础设施管理部门按职责分工负责提出认定意见并监管： （一）参与者数量大、分布广； （二）市场占有率较高； （三）业务复杂，与金融机构关联性强，或与其他系统重要性金融基础设施相互连接； （四）在金融市场中提供难以替代的关键服务，一旦发生重大风险事件等导致无法持续经营，可能对金融体系和实体经济产生重大不利影响。"},{"i":32,"n":"第三十二条","txt":"系统重要性金融基础设施及其运营机构，在维持由国务院金融管理部门负责监管的现行监管体制不变基础上，由中国人民银行负责宏观审慎管理。其中，涉及证券、期货及其相关活动的金融基础设施及其运营机构，由中国证券监督管理委员会依法进行监管；支付系统、基础征信系统、银行间市场金融基础设施及其运营机构，由中国人民银行负责监管；其他金融基础设施及其运营机构，由中国人民银行会同其他相关部门进行功能监管。"},{"i":33,"n":"第三十三条","txt":"有下列情形之一的，金融基础设施管理部门可以责令限期改正，依照《中华人民共和国中国人民银行法》、《中华人民共和国证券法》、《中华人民共和国期货和衍生品法》、《征信业管理条例》等相关法律、行政法规，对金融基础设施运营机构、直接负责的董事（理事）、监事和高级管理人员或直接责任人员予以处罚；涉嫌构成犯罪的，依法移送司法机关追究刑事责任： （一）未按照本办法规定报金融基础设施管理部门批准的； （二）未按照本办法规定向金融基础设施管理部门备案的； （三）未按照本办法规定向金融基础设施管理部门报告的； （四）违反本办法规定，拒绝、阻碍金融基础设施管理部门的询问、检查、调查或不如实提供有关文件、资料的； （五）违反本办法规定，聘任不符合任职条件的董事（理事）、监事和高级管理人员的； （六）无正当理由限制或拒绝为参与者提供金融基础设施服务，或中断、终止金融基础设施业务的； （七）存在危害自身或其他金融基"},{"i":34,"n":"第三十四条","txt":"擅自运营金融基础设施、实质性开办金融基础设施业务的，由相关部门或县级以上人民政府根据职责分工依照《中华人民共和国中国人民银行法》、《中华人民共和国证券法》、《中华人民共和国期货和衍生品法》、《征信业管理条例》等相关法律、行政法规予以取缔、没收违法所得、罚款等；涉嫌构成犯罪的，依法移送司法机关追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"金融基础设施运营机构超出原业务范围开办金融基础设施业务，由金融基础设施管理部门根据职责分工责令限期改正，依照《中华人民共和国中国人民银行法》、《中华人民共和国证券法》、《中华人民共和国期货和衍生品法》、《征信业管理条例》等相关法律、行政法规予以处罚；涉嫌构成犯罪的，依法移送司法机关追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"对破坏、危害金融基础设施，影响金融基础设施及其运营机构安全稳定运行的单位与个人，由金融基础设施管理部门依照《中华人民共和国中国人民银行法》、《中华人民共和国证券法》、《中华人民共和国期货和衍生品法》、《征信业管理条例》等相关法律、行政法规予以处罚；构成违反治安管理规定行为的，由有关部门依照《中华人民共和国治安管理处罚法》予以处罚；涉嫌构成犯罪的，依法移送司法机关追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"本办法自2025年10月1日起施行。"}],"jinrongkonggugongsiguanlianjiaoyiguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范金融控股公司关联交易行为，防止不当利益输送、风险集中、风险传染和监管套利，促进金融控股公司稳健经营，根据《中华人民共和国公司法》、《国务院关于实施金融控股公司准入管理的决定》（国发〔2020〕12号）以及《金融控股公司监督管理试行办法》（中国人民银行令〔2020〕第4号发布）等法律法规和部门规章，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于经中国人民银行批准设立的金融控股公司，以及金融控股公司及其附属机构共同构成的金融控股集团。 本办法所称金融控股公司附属机构是指纳入金融控股公司并表管理范围的所有机构。金融控股公司应当遵循实质重于形式原则，综合考虑实质控制和风险相关性，根据《金融控股公司监督管理试行办法》等规定，审慎确定并表管理范围。"},{"i":3,"n":"第三条","txt":"金融控股公司开展关联交易应当遵守法律、行政法规、企业财务制度和中国人民银行、国务院金融监督管理机构的有关规定，并按照企业会计准则进行会计处理，遵循诚实信用、穿透识别、合理公允、公开透明和治理独立的原则，强化金融控股集团不同法人主体之间的风险隔离。"},{"i":4,"n":"第四条","txt":"金融控股公司应当建立健全关联交易管理、报告和披露制度，强化金融控股公司和附属机构关联交易、金融控股集团内部交易和金融控股集团对外关联交易管理，提升集团风险管理和内部控制水平。 金融控股公司承担对金融控股集团关联交易管理的主体责任，按照实质重于形式和穿透原则，准确、全面、及时识别关联方和关联交易，推动金融控股集团规范开展关联交易。附属机构积极配合金融控股公司对金融控股集团开展关联交易管理。 金融控股公司或其附属机构是上市公司的，关联方的认定和关联交易的管理、报告和披露应当符合国务院证券监督管理机构和证券交易所的有关规定。附属机构是金融机构的，关联方的认定和关联交易的管理、报告和披露应当符合国务院金融监督管理机构的有关规定。"},{"i":5,"n":"第五条","txt":"中国人民银行依法对金融控股公司的关联交易实施监督管理。中国人民银行副省级城市中心支行以上分支机构（以下简称中国人民银行分支机构）可以依照本办法开展相关工作。"},{"i":6,"n":"第六条","txt":"金融控股公司的关联方，是指与金融控股公司存在一方控制另一方，或对另一方施加重大影响，以及与金融控股公司同受一方控制或重大影响的自然人、法人、非法人组织或中国人民银行认定的其他主体等。金融控股公司的关联方包括股东类关联方、内部人关联方以及所有附属机构。"},{"i":7,"n":"第七条","txt":"金融控股公司的股东类关联方包括： （一）金融控股公司的控股股东、实际控制人，及其一致行动人、受益所有人。 （二）金融控股公司的主要股东及其控股股东、实际控制人、一致行动人、受益所有人。 （三）本条第一项、第二项所列关联自然人的配偶、父母、成年子女及兄弟姐妹，以及所列关联法人或非法人组织的董事、监事、高级管理人员。 （四）本条第一项所列关联方控制或施加重大影响的法人或非法人组织，本条第二项所列关联方控制的法人或非法人组织，以及本条第一项、第二项所列关联自然人的配偶、父母、成年子女及兄弟姐妹控制的法人或非法人组织。"},{"i":8,"n":"第八条","txt":"金融控股公司的内部人关联方包括： （一）金融控股公司的董事、监事、高级管理人员以及具有投融资等核心业务审批或决策权的人员。 （二）本条第一项所列关联方的配偶、父母、成年子女及兄弟姐妹。 （三）本条第一项、第二项所列关联方控制的法人或非法人组织。"},{"i":9,"n":"第九条","txt":"金融控股公司按照实质重于形式和穿透原则，可以认定以下自然人、法人或非法人组织为金融控股公司的关联方： （一）在过去十二个月内或者根据相关协议安排在未来十二个月内存在本办法第七条、第八条规定情形之一的。 （二）本办法第七条第一项、第二项以及第八条第一项所列关联方的其他关系密切的家庭成员。 （三）本办法第七条第二项，以及第八条第一项所列关联方可以施加重大影响的法人或非法人组织。 （四）金融控股公司附属机构的重要关联方，即可能对金融控股集团经营产生重大影响的附属机构股东、董事、监事、高级管理人员、合营企业、联营企业以及其他可能导致利益不当转移的自然人、法人或非法人组织。 （五）对金融控股公司有影响，与金融控股公司或其附属机构发生或可能发生未遵守商业合理原则、有失公允的交易行为，并可以从交易中获得利益的自然人、法人或非法人组织。"},{"i":10,"n":"第十条","txt":"中国人民银行及其分支机构可以根据实质重于形式和穿透原则，认定可能导致金融控股公司或其附属机构利益不当转移的自然人、法人或非法人组织为金融控股公司的关联方。"},{"i":11,"n":"第十一条","txt":"金融控股公司及其附属机构应当按照实质重于形式和穿透原则，识别、认定、管理关联交易并计算关联交易金额。 计算关联自然人与金融控股公司的关联交易金额时，其配偶、父母、成年子女、兄弟姐妹等与该金融控股公司的关联交易应当合并计算；计算关联法人或非法人组织与金融控股公司的关联交易金额时，与其存在控制关系的法人或非法人组织与该金融控股公司的关联交易应当合并计算。 中国人民银行及其分支机构可以按照实质重于形式和穿透原则，识别、认定金融控股公司的关联交易。"},{"i":12,"n":"第十二条","txt":"按照交易主体的不同，金融控股集团的关联交易包括： （一）金融控股公司的关联交易，指金融控股公司与其关联方之间发生的转移资源、劳务或义务的行为。 （二）金融控股公司附属机构的关联交易，指金融控股公司附属机构与其关联方之间发生的转移资源、劳务或义务的行为。"},{"i":13,"n":"第十三条","txt":"按照管理目标的不同，金融控股集团的关联交易至少包括： （一）集团内部交易，指金融控股公司与其附属机构之间以及金融控股公司各附属机构之间发生的转移资源、劳务或义务的行为，或者联合提供服务的行为。 （二）集团对外关联交易，指金融控股公司及其附属机构与金融控股公司的关联方（除附属机构外）之间发生的转移资源、劳务或义务的行为。"},{"i":14,"n":"第十四条","txt":"按照交易类型的不同，金融控股集团的关联交易包括： （一）投融资类：包括贷款（含贸易融资）、融资租赁、融资融券、买入返售、票据承兑和贴现、透支、债券投资、金融衍生品交易、特定目的载体投资、投资于关联方发行的金融产品且基础资产涉及其他关联方的交易、证券回购、拆借、开立信用证、保理、担保、保函、贷款承诺以及其他实质上由金融控股公司或其附属机构承担信用风险的业务，投资股权、不动产及其他资产，与关联方共同投资等。 （二）资产转移类：包括自用动产与不动产买卖，信贷资产及其收（受）益权买卖，抵债资产的接收和处置，其他出售资产交易等。 （三）提供服务类：包括征信、信用评级、资产评估、法律、审计、精算、咨询等服务；软件和信息技术服务、互联网数据服务；非金融机构支付服务；金融信息服务，包括但不限于客户信息共享、金融交易风险控制、金融决策分析；信息展示、销售推介、委托或受托销售；有价证券交易经纪服务和承销服"},{"i":15,"n":"第十五条","txt":"金融控股集团的关联交易金额以交易对价或转移的利益计算，计算方式如下： （一）投融资类关联交易以投融资金额计算交易金额。其中，投资于关联方发行的金融产品且基础资产涉及其他关联方的，以投资金额计算交易金额；投资于关联方发行的金融产品且基础资产不涉及其他关联方的，以管理费或服务费计算交易金额。 （二）资产转移类关联交易以交易价格或公允价值计算交易金额。 （三）提供服务类关联交易以业务收入或支出金额计算交易金额。 （四）中国人民银行确定的其他计算口径。"},{"i":16,"n":"第十六条","txt":"按照交易金额的不同，金融控股公司的关联交易包括： （一）金融控股公司的重大关联交易是指金融控股公司与其关联方之间单笔交易金额达到金融控股公司上一年度末经审计的法人口径净资产1%以上或超过10亿元，或一个会计年度内对单个关联方交易金额累计达到金融控股公司上一年度末经审计的法人口径净资产5%以上或超过50亿元的交易。 一个会计年度内金融控股公司与单个关联方的累计交易金额达到上述标准后，其后发生的关联交易每累计达到金融控股公司上一年度末经审计的法人口径净资产1%以上，应当重新认定为重大关联交易。 （二）金融控股公司的一般关联交易是指除重大关联交易以外的其他关联交易。 金融控股公司附属机构的重大关联交易和一般关联交易由附属机构依据或参照有关规定进行认定。"},{"i":17,"n":"第十七条","txt":"金融控股公司应当建立有效的关联交易管理制度，明确事前、事中、事后的全流程管控措施，降低关联交易的复杂程度，提升金融控股集团整体关联交易管理水平，确保金融控股集团各层面关联交易管理制度有效衔接。金融控股公司的关联交易管理制度包括但不限于： （一）管理架构和相应职责分工。 （二）金融控股公司关联交易的管理流程、定价指引、限额管理、禁止行为、内部审计和责任追究等。 （三）金融控股公司关联方的识别、报告、核验、信息收集与管理。 （四）金融控股公司关联交易的发起、定价、审查、回避、报告和披露等。 （五）指导和督促金融控股公司附属机构完善关联交易管理。 （六）金融控股集团内部交易及其风险敞口的识别、评估和报告。 （七）金融控股集团对外关联交易及其风险敞口的识别、评估和报告。 （八）金融控股公司关联交易、金融控股公司附属机构关联交易、金融控股集团内部交易和对外关联交易可能产生的风险传染以及对金融控股"},{"i":18,"n":"第十八条","txt":"金融控股公司应当建立完善的关联交易管理架构，包括： （一）董事会对金融控股公司的关联交易管理承担最终责任。 （二）董事会下设关联交易管理委员会，负责制订关联交易管理的总体目标、基本原则和管理制度，并提交董事会审议决策；统筹关联交易管理、审议、批准和风险控制以及董事会授权的其他事宜。关联交易管理委员会由三名以上董事组成，由具备相关专业经验的独立董事担任负责人，确保关联交易管理委员会的客观性和独立性。 （三）金融控股公司应当设立跨部门的关联交易管理办公室，负责金融控股公司关联交易管理体系的建立和完善以及日常关联交易管理的协调工作，审查关联方清单、关联交易以及关联交易相关报告。关联交易管理办公室成员包括合规、业务、风控、财务等相关部门负责人。 （四）金融控股公司应当明确关联交易管理的牵头部门，并设置专岗，负责维护关联方清单、拟定关联交易管理制度、开展日常关联交易管理等工作。 金融控股公司关联"},{"i":19,"n":"第十九条","txt":"金融控股公司应当建立关联方信息档案，至少每半年更新一次，并向中国人民银行及其住所地分支机构报送。关联交易管理办公室负责关联方信息档案的更新、维护、分类和汇总等工作，通过多种方式对有关信息进行必要的核实验证，并及时在集团内进行信息共享，确保金融控股公司附属机构能够及时识别集团内部交易和集团对外关联交易。 金融控股公司应当在董事、监事和高级管理人员任职资格备案时，向中国人民银行及其住所地分支机构报告其关联方情况。金融控股公司应当明确具有投融资等核心业务审批或决策权的人员范围，并且自相关人员任职之日起十五个工作日内，向中国人民银行及其住所地分支机构报告其关联方情况。 自然人、法人或其他非法人组织应当在持有或控制金融控股公司5%以上股权之日起十五个工作日内，向金融控股公司、中国人民银行及其住所地分支机构报告其关联方情况，并提交不与金融控股公司或其附属机构进行不当关联交易的承诺函。相关报告人应如"},{"i":20,"n":"第二十条","txt":"金融控股公司应当建立关联交易管理信息系统，提高关联方和关联交易管理的信息化和智能化水平，按照交易金额、交易频率、交易时间等因素对关联方的重要性进行排序，并及时向中国人民银行及其住所地分支机构报送关联方、重大关联交易、季度关联交易情况等信息，保证数据的真实性、准确性和完整性。"},{"i":21,"n":"第二十一条","txt":"金融控股公司及其附属机构开展关联交易应当按照商业合理原则，具有真实的业务背景、条件合理、定价公允，明确交易对价的确定原则及定价方法。关联交易定价应当以明确、公允的市场价格为基础；无法获取市场价格的，可以参考与独立第三方交易的条件和价格；因交易特殊性而无法按照前述方法进行定价的，应当对该定价的公允性和条件设定的合理性作出说明。必要时关联交易管理委员会可以聘请财务顾问等独立第三方出具报告，作为判断的依据。"},{"i":22,"n":"第二十二条","txt":"金融控股公司应当根据金融控股集团实际业务和风险状况，控制关联交易的数量和规模，按照交易类型、单一关联方、全部关联方等不同分类，审慎设置关键业务领域关联交易量化限制指标，每年对交易限额的有效性和合理性进行评估，经充分论证后可以适度调整，避免风险过度集中。包括： （一）金融控股公司的关联交易限额。 （二）金融控股公司附属机构的关联交易限额，国务院金融监督管理机构另有规定的，从其规定。 （三）金融控股集团内部交易的限额。 （四）金融控股集团对外关联交易的限额。 金融控股公司的上述限额应当在经由董事会批准后十五个工作日内向中国人民银行及其住所地分支机构报告，并详细说明限额设置的有效性和合理性。"},{"i":23,"n":"第二十三条","txt":"金融控股公司及其附属机构不得进行以下关联交易： （一）通过金融控股集团内部交易虚构交易、转移收入与风险或进行监管套利，或者通过第三方间接进行内部交易，损害金融控股公司及其附属机构的稳健性。 （二）通过金融控股集团对外关联交易进行不当利益输送，损害金融控股公司及其附属机构的稳健性。 （三）通过隐匿关联关系、拆分交易、设计复杂交易结构等各种隐蔽方式规避内部审查、外部监管以及报告披露义务，为关联方违规提供融资、隐藏风险等。 （四）关联交易协议条件显著偏离与非关联方进行的同类交易，以及采用明显偏离市场价格或缺乏合理依据的定价基准。 （五）金融控股公司附属金融机构（财务公司除外）向金融控股公司提供融资。 （六）金融控股公司附属机构（财务公司除外）接受金融控股公司的股权作为质押标的。 （七）通过互联网数据服务、金融信息服务等交易规避有关规定，或利用规则、数据、算法等各种手段实施价格控制、利益输送或"},{"i":24,"n":"第二十四条","txt":"金融控股公司每年至少对金融控股集团的关联交易进行一次专项审计，并将审计结果报董事会和监事会。金融控股公司不得聘用关联方控制的会计师事务所、专业评估机构、律师事务所为其提供审计、评估等服务。"},{"i":25,"n":"第二十五条","txt":"对于未按规定报告关联方、金融控股集团内部交易和对外关联交易，以及违规开展关联交易等情形，金融控股公司应当按照内部问责制度对相关人员进行问责。"},{"i":26,"n":"第二十六条","txt":"金融控股公司关联交易应当订立书面交易协议，按照商业合理原则，以不优于对非关联方同类交易的条件进行。关联交易协议安排应具有真实商业背景，结构清晰，避免多层嵌套。 金融控股公司与同一关联方之间长期持续发生的、需要反复签订交易协议的关联交易，可以签订统一交易协议，协议期限一般不超过三年。统一交易协议的签订、续签、实质性变更，应按照重大关联交易进行内部审查、报告和信息披露。统一关联交易协议下发生的关联交易无需逐笔进行审查、报告和披露，但应当在季度报告中说明执行情况。统一交易协议应当明确或预估关联交易金额。"},{"i":27,"n":"第二十七条","txt":"金融控股公司应当完善关联交易内控机制和管理流程，关键环节的审查意见以及关联交易管理委员会、董事会等会议决议、记录应当清晰可查。 金融控股公司的一般关联交易按照金融控股公司内部管理制度和授权程序审查，报关联交易管理委员会备案。金融控股公司的重大关联交易经由关联交易管理委员会审查后，提交董事会批准。关联交易管理委员会应重点关注关联交易的合规性和公允性。 董事会关于关联交易的会议所作决议须经非关联董事三分之二以上通过。出席董事会的非关联董事人数不足三人的，应当提交股东（大）会审议。金融控股公司关联交易管理委员会、董事会及股东（大）会对关联交易进行表决或决策时，与该关联交易有利害关系的人员应当回避。金融控股公司未设立股东（大）会，或者因回避原则而无法召开股东（大）会的，仍由董事会审议且不适用本条关于回避的规定，但关联董事应出具不存在利益输送的声明。 金融控股公司独立董事应当逐笔对重大关联交易的"},{"i":28,"n":"第二十八条","txt":"金融控股公司进行的下列关联交易，可以免予按照关联交易的方式进行审议和披露，但在统计关联交易金额与比例时应当合并计算： （一）与关联自然人单笔交易额在50万元以下或与关联法人单笔交易额在500万元以下的关联交易，且交易后累计未达到重大关联交易标准的。 （二）一方以现金认购另一方公开发行的股票、公司债券或企业债券、可转换债券或其他衍生品种。 （三）活期存款业务。 （四）同一自然人同时担任金融控股公司和其他法人的独立董事且不存在其他构成关联方情形的，该法人与金融控股公司进行的交易。 （五）交易的定价为国家规定的。 （六）法律、行政法规及国务院金融管理部门认可的其他情形。"},{"i":29,"n":"第二十九条","txt":"为统筹管理金融控股集团的关联交易，金融控股公司应当充分了解附属机构所在行业以及上市公司的关联交易管理要求，督促附属机构满足有关规定。金融控股公司应当指导和督促未上市且未受行业监管的附属机构，建立有效的关联交易管理体系。 金融控股公司应当维护附属机构尤其是上市公司和受监管实体的独立运作，通过公司治理程序参与附属机构关联交易管理，指导和督促附属机构指定或设置专门的组织，履行该机构关联交易内部控制和管理职责，并承担相应的责任。"},{"i":30,"n":"第三十条","txt":"金融控股公司应当及时收集附属机构的关联方、重大关联交易、季度关联交易情况等信息，按照交易金额、交易频率、交易时间等因素对附属机构以及附属机构关联方的重要性进行排序，按季对附属机构关联交易及其风险敞口进行汇总分析和监测预警，每年对附属机构关联交易管理情况进行评估检查，形成综合评价报告并提交董事会批准。附属机构应当配合向金融控股公司提供所需的相关信息。"},{"i":31,"n":"第三十一条","txt":"金融控股公司应当统筹管理集团内部交易，及时对金融控股集团内部交易及其风险敞口进行收集汇总、监测分析和评估预警，重点关注金融控股集团内部交易的合理性和公允性，提高金融控股集团内部交易的透明度，及时充分、结构清晰地披露金融控股集团内部交易的定性与定量信息，有效促进利益相关方对金融控股集团业务运作和风险状况的分析与评估。"},{"i":32,"n":"第三十二条","txt":"金融控股公司每季度应当对金融控股集团内部交易进行分析评估，包括但不限于： （一）金融控股集团内部交易的总体情况、重点机构和集中程度等。 （二）交易背景的真实性和必要性，是否存在虚构交易问题。 （三）是否存在转移收入或隐藏风险，以及是否存在监管套利问题。 （四）金融控股公司和其附属机构之间以及不同附属机构之间的交易依赖关系，以及各附属机构经营的独立性。 （五）金融控股集团内部交易可能产生的风险传染以及对集团和附属机构经营稳健性的影响。 （六）有助于理解金融控股集团业务运作和风险状况的其他信息。"},{"i":33,"n":"第三十三条","txt":"金融控股公司应当统筹管理集团对外关联交易，及时对金融控股集团对外关联交易及其风险敞口进行收集汇总、监测分析和评估预警，重点关注金融控股集团对外关联交易的合规性和公允性，提高金融控股集团对外关联交易的透明度，及时充分、结构清晰地披露金融控股集团对外关联交易的定性与定量信息。"},{"i":34,"n":"第三十四条","txt":"金融控股公司应当重点防范金融控股公司及其附属机构向金融控股公司的控股股东、实际控制人及其关联方进行利益输送的风险。 金融控股公司应当加强对金融控股公司及其附属机构与金融控股公司所属企业集团内其他机构之间关联交易的监测分析和风险管理，防止金融风险和实业风险之间的交叉传染。"},{"i":35,"n":"第三十五条","txt":"金融控股公司每季度应当对金融控股集团对外关联交易进行分析评估，包括但不限于： （一）金融控股集团对外关联交易的总体情况、重点机构和集中程度等。 （二）交易架构、交易目的、交易条件或对价、定价政策与依据等要素。 （三）是否存在大股东控制、内部人控制以及不当利益输送等问题。 （四）金融控股集团对外关联交易可能产生的风险集中、风险传染和风险外溢。 （五）有助于理解金融控股集团业务运作和风险状况的其他信息。"},{"i":36,"n":"第三十六条","txt":"金融控股公司应当按照本办法规定，真实、准确、完整、及时地报告并披露金融控股公司关联交易、金融控股集团内部交易和对外关联交易信息，不得存在任何虚假记载、误导性陈述或重大遗漏。 关联交易管理委员会应当统筹管理关联交易信息报告和披露工作，提高金融控股公司关联交易、金融控股集团内部交易和对外关联交易的透明度。 金融控股公司附属机构的关联交易由附属机构依据或参照有关规定进行报告和披露。"},{"i":37,"n":"第三十七条","txt":"金融控股公司应当在签订重大关联交易协议后十五个工作日内逐笔向中国人民银行及其住所地分支机构报送有关情况，内容至少包括： （一）关联交易概述。 （二）交易对手情况，包括关联自然人基本情况，关联法人或非法人组织的名称、经济性质或类型、主营业务或经营范围、法定代表人、住所地、注册资本及其变化，与金融控股公司存在的关联关系。 （三）关联交易的具体情况，包括关联交易类型、穿透的交易架构图、交易目的、交易条件或对价、定价政策与依据、关联交易金额及相应比例等。 （四）关联交易的风险提示，以及对财务状况、经营成果的影响。 （五）交易协议，交易涉及的有关法律文件和审批文件，以及中介服务机构出具的专业报告（如有）。 （六）股东（大）会、董事会决议，关联交易管理委员会的意见或决议情况，独立董事发表意见情况。"},{"i":38,"n":"第三十八条","txt":"金融控股公司应当按本办法规定，在每季度结束后四十日内向中国人民银行及其住所地分支机构报送关联交易整体情况，包括金融控股公司关联交易、金融控股集团内部交易和对外关联交易的交易类型、交易金额、限额管理情况、交易评估、分析评估报告等。 金融控股公司关联交易、金融控股集团内部交易和对外关联交易的年度评估报告应当提交董事会批准。金融控股公司董事会应当每年向股东（大）会就金融控股公司关联交易、金融控股集团内部交易和对外关联交易整体情况作出专项报告，并向中国人民银行及其住所地分支机构报送。"},{"i":39,"n":"第三十九条","txt":"金融控股公司应当在公司年报中披露当年金融控股公司关联交易的总体情况。金融控股公司应当在签订关联交易协议后十五个工作日内在公司网站逐笔披露本办法第三十七条规定须逐笔报告的重大关联交易。一般关联交易应当在每季度结束后四十日内按照关联方和交易类型在公司网站合并披露。 金融控股公司应当在每季度结束后四十日内在公司网站披露本季度金融控股集团内部交易和对外关联交易的定性与定量信息，并在公司年报中作出专项说明，提高金融控股集团运作的透明度。 金融控股公司的关联交易、金融控股集团内部交易和对外关联交易信息涉及国家秘密、商业秘密或者国务院金融管理部门认可的其他情形，金融控股公司可以向中国人民银行申请豁免按照本办法披露或履行相关义务。 国务院金融监督管理机构另有规定的，从其规定。"},{"i":40,"n":"第四十条","txt":"中国人民银行与相关部门之间建立监管合作与信息共享机制，加强金融控股公司及其附属机构的关联交易监管，及时共享相关关联方及关联交易信息，在必要时依据职责分工采取相应的监管措施。"},{"i":41,"n":"第四十一条","txt":"金融控股公司违反本办法规定，未按要求管理、报告、披露关联交易相关信息，或者违规开展关联交易的，中国人民银行应当要求其限期改正。 逾期未改正的，中国人民银行可以对金融控股公司的董事、监事、高级管理人员进行监督管理谈话，并要求金融控股公司采取限制经营活动等措施。 金融控股公司违反本办法规定，违规开展关联交易的，中国人民银行可以依据《金融控股公司监督管理试行办法》第五十二条实施处罚。 附属金融机构违反本办法规定的，中国人民银行应当将发现的线索、证据移交国务院金融监督管理机构依法采取措施。"},{"i":42,"n":"第四十二条","txt":"金融控股公司董事、监事、高级管理人员或其他相关人员违反本办法规定的，中国人民银行可以要求其限期改正；逾期未改正的，中国人民银行可以采取记入履职记录、要求金融控股公司进行问责等措施；情节严重的，中国人民银行可以要求金融控股公司调整董事、监事、高级管理人员或者限制其权利。"},{"i":43,"n":"第四十三条","txt":"金融控股公司股东、实际控制人利用关联交易损害金融控股公司利益的，中国人民银行可以要求其限期改正；对逾期未改正的，可以要求金融控股公司采取限制该股东的权利或者要求其转让股权等措施。 金融控股公司的其他关联方违反本办法规定的，中国人民银行可以采取通报批评等措施。"},{"i":44,"n":"第四十四条","txt":"会计师事务所、专业评估机构、律师事务所、税务师事务所等服务机构违反诚信及勤勉尽责原则，出具文件存在虚假记载、误导性陈述或重大遗漏的，中国人民银行可以将发现的线索、证据移交有关主管部门依法处理。"},{"i":45,"n":"第四十五条","txt":"本办法所称控股股东，是指其出资额占金融控股公司资本总额50%以上或其持有的股份占金融控股公司股本总额50%以上的股东；出资额或持有股份的比例虽不足50%，但依其出资额或持有的股份所享有的表决权已足以对股东（大）会的决议产生控制性影响或能够实际支配公司行为的股东。 实际控制人，是指通过投资关系、协议或其他安排，能够实际支配公司行为的人。 一致行动人，是指通过协议、合作或其他途径，在行使表决权或参与其他经济活动时采取相同意思表示的自然人、法人或非法人组织。 受益所有人，是指最终拥有或实际控制市场主体，或者享有市场主体最终收益的自然人。 主要股东，是指持有或控制金融控股公司股份总额5%以上股份或表决权，或持有股份总额不足5%但对金融控股公司经营管理有重大影响的股东。 其他关系密切的家庭成员，是指除配偶、父母、成年子女及兄弟姐妹以外的包括配偶的父母、子女的配偶、兄弟姐妹的配偶、配偶的兄弟姐妹以"},{"i":46,"n":"第四十六条","txt":"本办法实施后，金融控股公司应当在中国人民银行认可的期限内完善各项制度和治理架构，稳妥有序落实本办法有关要求，确保过渡期满关联交易管理合规。"},{"i":47,"n":"第四十七条","txt":"本办法由中国人民银行负责解释。"},{"i":48,"n":"第四十八条","txt":"本办法自2023年3月1日起施行。"}],"jinrongkonggugongsijianduguanlishixingbanfa":[{"i":1,"n":"第一条","txt":"为规范金融控股公司行为，加强对非金融企业等设立金融控股公司的监督管理，防范系统性金融风险，根据《中华人民共和国中国人民银行法》、《中华人民共和国公司法》、《中华人民共和国商业银行法》、《中华人民共和国证券法》、《中华人民共和国证券投资基金法》、《中华人民共和国保险法》、《中华人民共和国银行业监督管理法》、《中华人民共和国信托法》等法律、行政法规以及《国务院关于实施金融控股公司准入管理的决定》（国发〔2020〕12号），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称金融控股公司是指依法设立，控股或实际控制两个或两个以上不同类型金融机构，自身仅开展股权投资管理、不直接从事商业性经营活动的有限责任公司或股份有限公司。 本办法适用于控股股东或实际控制人为境内非金融企业、自然人以及经认可的法人的金融控股公司。金融机构跨业投资控股形成的金融集团参照本办法确定监管政策标准，具体规则另行制定。 本办法所称金融机构包括以下类型： （一）商业银行（不含村镇银行）、金融租赁公司。 （二）信托公司。 （三）金融资产管理公司。 （四）证券公司、公募基金管理公司、期货公司。 （五）人身保险公司、财产保险公司、再保险公司、保险资产管理公司。 （六）国务院金融管理部门认定的其他机构。 本办法所称金融控股公司所控股金融机构是指金融控股公司控股或实际控制的境内外金融机构。本办法将控股或实际控制统称为实质控制。金融控股集团是指金融控股公司及其所控股机构共同构成的企业法人联"},{"i":3,"n":"第三条","txt":"投资方直接或间接取得被投资方过半数有表决权股份的，即对被投资方形成实质控制。计算表决权时应当综合考虑投资方直接或间接持有的可转换工具、可执行认股权证、可执行期权等潜在表决权。 投资方未直接或间接取得被投资方过半数有表决权的股份，有以下情形之一的，视同投资方对被投资方形成实质控制： （一）投资方通过与其他投资方签订协议或其他安排，实质拥有被投资方过半数表决权。 （二）按照法律规定或协议约定，投资方具有实际支配被投资方公司行为的权力。 （三）投资方有权任免被投资方董事会或其他类似权力机构的过半数成员。 （四）投资方在被投资方董事会或其他类似权力机构具有过半数表决权。 （五）其他属于实质控制的情形，包括按照《企业会计准则第33号——合并财务报表》构成控制的情形。 两个或两个以上投资方均有资格单独主导被投资方不同方面的决策、经营和管理等活动时，能够主导对被投资方回报产生最重大影响的活动的一方，"},{"i":4,"n":"第四条","txt":"中国人民银行依法对金融控股公司实施监管，审查批准金融控股公司的设立、变更、终止以及业务范围。 国务院金融管理部门依法按照金融监管职责分工对金融控股公司所控股金融机构实施监管。 财政部负责制定金融控股公司财务制度并组织实施。 建立金融控股公司监管跨部门联合机制。中国人民银行与国务院银行保险监督管理机构、国务院证券监督管理机构、国家外汇管理部门加强对金融控股公司及其所控股金融机构的监管合作和信息共享。中国人民银行、国务院银行保险监督管理机构、国务院证券监督管理机构、国家外汇管理部门与发展改革部门、财政部门、国有资产管理部门等加强金融控股公司的信息数据共享。"},{"i":5,"n":"第五条","txt":"中国人民银行会同相关部门按照实质重于形式原则，对金融控股集团的资本、行为及风险进行全面、持续、穿透监管，防范金融风险跨行业、跨市场传递。"},{"i":6,"n":"第六条","txt":"非金融企业、自然人及经认可的法人实质控制两个或两个以上不同类型金融机构，并具有以下情形之一的，应当设立金融控股公司： （一）实质控制的金融机构中含商业银行，金融机构的总资产规模不少于5000亿元的，或金融机构总资产规模少于5000亿元，但商业银行以外其他类型的金融机构总资产规模不少于1000亿元或受托管理资产的总规模不少于5000亿元。 （二）实质控制的金融机构不含商业银行，金融机构的总资产规模不少于1000亿元或受托管理资产的总规模不少于5000亿元。 （三）实质控制的金融机构总资产规模或受托管理资产的总规模未达到第一项、第二项规定的标准，但中国人民银行按照宏观审慎监管要求，认为需要设立金融控股公司的。 符合前款规定条件的企业集团，如果企业集团内的金融资产占集团并表总资产的比重达到或超过85%的，可申请专门设立金融控股公司，由金融控股公司及其所控股机构共同构成金融控股集团；也可按照本"},{"i":7,"n":"第七条","txt":"申请设立金融控股公司的，除应当具备《中华人民共和国公司法》规定的条件外，还应当具备以下条件： （一）实缴注册资本额不低于50亿元人民币，且不低于直接所控股金融机构注册资本总和的50%。 （二）拟设金融控股公司的股东、实际控制人符合相关法律、行政法规、国务院决定和本办法规定。 （三）有符合任职条件的董事、监事和高级管理人员。 （四）有健全的组织机构和有效的风险管理、内部控制制度。 （五）有能力为所控股金融机构持续补充资本。 设立金融控股公司，还应当符合其他审慎性条件。"},{"i":8,"n":"第八条","txt":"非金融企业、自然人持有金融控股公司股权不足5%且对金融控股公司经营管理无重大影响的，应当符合以下条件： （一）非金融企业应当依法设立，股权结构清晰，公司治理完善。 （二）非金融企业和自然人最近三年无重大违法违规记录或重大不良信用记录；没有因涉嫌重大违法违规正在被调查或处于整改期间；不存在对所投资企业经营失败负有重大责任未逾三年的情形；不存在因故意犯罪被判处刑罚、刑罚执行完毕未逾五年的情形。 （三）非金融企业不存在长期未实际开展业务、停业、破产清算、治理结构缺失、内部控制失效等影响履行股东权利和义务的情形；不存在可能严重影响持续经营的担保、诉讼、仲裁或其他重大事项。 通过证券交易所、全国中小企业股份转让系统交易取得金融控股公司5%以下股份的股东，不适用本条前述规定。 金融产品可以持有上市金融控股公司股份，但单一投资人、发行人或管理人及其实际控制人、关联方、一致行动人控制的金融产品持有同一"},{"i":9,"n":"第九条","txt":"非金融企业、自然人申请设立或投资入股成为金融控股公司主要股东、控股股东或实际控制人的，应当在符合本办法第八条规定的同时，还符合以下条件： （一）非金融企业和自然人应当具有良好的信用记录和社会声誉。 （二）非金融企业应当核心主业突出，资本实力雄厚，投资金融机构动机纯正，已制定合理的投资金融业的商业计划，不盲目向金融业扩张，不影响主营业务发展。 （三）非金融企业应当公司治理规范，股权结构和组织架构清晰，股东、受益所有人结构透明，管理能力达标，具有有效的风险管理和内部控制机制。 （四）非金融企业应当财务状况良好。成为主要股东的，应当最近两个会计年度连续盈利。成为控股股东或实际控制人的，应当最近三个会计年度连续盈利，年终分配后净资产达到总资产的40%（母公司财务报表口径），权益性投资余额不超过净资产的40%（合并财务报表口径）。 （五）持有金融控股公司5%以上股份的自然人，应当具有履行金融机构"},{"i":10,"n":"第十条","txt":"非金融企业、自然人及经认可的法人存在下列情形之一的，不得成为金融控股公司的主要股东、控股股东或实际控制人： （一）股权存在权属纠纷。 （二）曾经委托他人或接受他人委托持有金融控股公司或金融机构股权。 （三）曾经虚假投资、循环注资金融机构，或在投资金融控股公司或金融机构时，有提供虚假承诺或虚假材料行为。 （四）曾经投资金融控股公司或金融机构，对金融控股公司或金融机构经营失败或重大违规行为负有重大责任。 （五）曾经投资金融控股公司或金融机构，拒不配合中国人民银行或国务院银行保险监督管理机构、国务院证券监督管理机构、国家外汇管理部门监管。"},{"i":11,"n":"第十一条","txt":"金融控股公司的控股股东或实际控制人不得存在以下情形： （一）通过特定目的载体或委托他人持股等方式规避金融控股公司监管。 （二）关联方众多，股权关系复杂、不透明或存在权属纠纷，恶意开展关联交易，恶意使用关联关系。 （三）滥用市场垄断地位或技术优势开展不正当竞争。 （四）操纵市场、扰乱金融秩序。 （五）五年内转让所持有的金融控股公司股份。 （六）其他可能对金融控股公司经营管理产生重大不利影响的情形。"},{"i":12,"n":"第十二条","txt":"金融控股公司股东应当以合法自有资金投资金融控股公司，确保投资控股金融控股公司资金来源真实、可靠。 金融控股公司股东不得以委托资金、债务资金等非自有资金以及投资基金等方式投资金融控股公司，不得委托他人或接受他人委托持有金融控股公司的股权，法律、行政法规另有规定的除外。 金融控股公司应当以合法自有资金投资控股金融机构，不得对金融机构进行虚假注资、循环注资，不得抽逃金融机构资金。 中国人民银行对金融控股公司的资本合规性实施穿透管理，向上核查投资控股金融控股公司的资金来源，向下会同其他国务院金融管理部门核查金融控股公司投资控股金融机构的资金来源。"},{"i":13,"n":"第十三条","txt":"设立金融控股公司，应当经中国人民银行批准，依照金融机构管理。 本办法实施前已具备第六条情形的机构，拟申请成为金融控股公司的，应当在本办法实施之日起12个月内向中国人民银行提出申请。 本办法实施后，拟控股或实际控制两个或两个以上不同类型金融机构，并具有本办法第六条规定设立金融控股公司情形的，应当向中国人民银行申请。 申请设立金融控股公司应当提交以下文件、资料： （一）章程草案。 （二）拟任职的董事、高级管理人员的资格证明。 （三）法定验资机构出具的验资证明。 （四）股东名册及其出资额、股份。 （五）持有注册资本5%以上的股东的资信证明和有关资料。 （六）经营方针和计划。 （七）经营场所、安全防范措施和与业务有关的其他设施的资料。 （八）其他需专门说明的事项及申请材料真实性声明。 中国人民银行应当自受理申请之日起六个月内作出批准或不予批准的书面决定；决定不批准的，应当说明理由。 设立许可的"},{"i":14,"n":"第十四条","txt":"申请设立金融控股公司或企业集团母公司申请作为金融控股公司时，发起人或控股股东应当就以下内容出具说明或承诺函： （一）投资设立金融控股公司的目的。 （二）金融控股公司的真实资本来源，金融控股公司投资控股金融机构的真实资金来源。 （三）金融控股公司的组织架构和管理模式。 （四）金融控股公司的控股股东、实际控制人、受益所有人、一致行动人以及关联方。 （五）在金融控股公司设立之时，金融控股公司的股东之间无关联关系。 （六）金融控股公司与关联方之间、关联方相互之间不进行不当关联交易。 （七）必要时向金融控股公司补充资本。 （八）必要时金融控股公司向所控股金融机构及时补充资本金。 （九）承诺遵守本办法规定。 以上事项发生变化的，应当重新出具说明或承诺函。"},{"i":15,"n":"第十五条","txt":"金融控股公司有下列事项之一的，应当经中国人民银行批准： （一）变更名称、住所、注册资本。 （二）修改公司章程。 （三）变更持有5%以上股权的主要股东、实际控制人。 （四）投资控股其他金融机构。 （五）增加或减少对所控股金融机构持股或出资比例，导致金融控股公司实际控制权益变更或丧失的。 （六）金融控股公司分立、合并、终止或解散。 中国人民银行自受理上述事项申请之日起三个月内作出批准或不予批准的决定。 金融控股公司依法终止其业务活动，应当注销其金融控股公司许可证。"},{"i":16,"n":"第十六条","txt":"金融控股公司除对所控股的金融机构进行股权管理外，还可以经中国人民银行批准，对所控股的金融机构进行流动性支持。金融控股公司应当严格规范该资金使用，并不得为其主要股东、控股股东和实际控制人提供融资支持。 金融控股公司开展跨境投融资活动，应当遵守国家有关跨境投融资及外汇管理规定。"},{"i":17,"n":"第十七条","txt":"金融控股公司可以投资经国务院金融管理部门认定与金融业务相关的机构，但投资总额账面价值原则上不得超过金融控股公司净资产的15%。国家另有规定的除外。"},{"i":18,"n":"第十八条","txt":"金融控股公司应当具有简明、清晰、可穿透的股权结构，实际控制人和最终受益人可识别，法人层级合理，与自身资本规模、经营管理能力和风险管控水平相适应。本办法实施前，已经存在的、股权结构不符合本条要求的企业集团，应当在国务院金融管理部门认可的期限内，降低组织架构复杂程度，简化法人层级。本办法实施后，新增的金融控股公司，金融控股公司和所控股金融机构法人层级原则上不得超过三级。金融控股公司股权结构或法人层级发生变化时，应当向中国人民银行说明情况，对属于应当申请批准的事项，应当依法履行审批程序。 金融控股公司所控股金融机构不得反向持有母公司股权。金融控股公司所控股金融机构之间不得交叉持股。金融控股公司所控股金融机构不得再成为其他类型金融机构的主要股东，但金融机构控股与其自身相同类型的或属业务延伸的金融机构，并经国务院金融管理部门认可的除外。本办法实施前，金融控股公司所控股金融机构已经成为其他类型金融"},{"i":19,"n":"第十九条","txt":"同一投资人及其关联方、一致行动人，作为主要股东参股金融控股公司的数量不得超过两家，作为控股股东和实际控制人控股金融控股公司的数量不得超过一家。 根据国务院授权持有金融控股公司股权的投资主体，以及经中国人民银行认可参与金融控股公司风险处置的投资主体，不受本条前款规定限制。"},{"i":20,"n":"第二十条","txt":"金融控股公司应当完善公司治理结构，依法参与所控股机构的法人治理，促进所控股机构安全稳健运行。 金融控股公司不得滥用实质控制权，干预所控股机构的正常独立自主经营，损害所控股机构以及其相关利益人的合法权益。金融控股公司滥用实质控制权或采取不正当干预行为导致所控股机构发生损失的，应当对该损失承担责任。"},{"i":21,"n":"第二十一条","txt":"金融控股公司的董事、监事和高级管理人员的任职条件由中国人民银行规定。金融控股公司变更董事、监事和高级管理人员，应当符合任职条件，并向中国人民银行备案。 金融控股公司的高级管理人员原则上可以兼任所控股机构的董事或监事，但不能兼任所控股机构的高级管理人员。所控股机构的高级管理人员不得相互兼任。"},{"i":22,"n":"第二十二条","txt":"金融控股公司与其所控股机构之间、其所控股机构之间在开展业务协同，共享客户信息、销售团队、信息技术系统、运营后台、营业场所等资源时，不得损害客户权益，应当依法明确风险承担主体，防止风险责任不清、交叉传染及利益冲突。"},{"i":23,"n":"第二十三条","txt":"金融控股公司及其所控股机构在集团内部共享客户信息时，应当确保依法合规、风险可控并经客户书面授权或同意，防止客户信息被不当使用。 金融控股公司所控股机构在提供综合化金融服务时，应当尊重客户知情权和选择权。"},{"i":24,"n":"第二十四条","txt":"金融控股公司应当对纳入并表管理范围内所控股机构的公司治理、资本和杠杆率等进行全面持续管控，有效识别、计量、监测和控制金融控股集团的总体风险状况。企业集团整体被认定为金融控股集团的，应当对集团内从事金融活动的机构实行并表管理。"},{"i":25,"n":"第二十五条","txt":"不属于金融控股公司所控股机构，但具有以下情形的，应当纳入并表管理范围： （一）具有业务同质性的各类被投资机构，其资产规模占金融控股公司并表资产规模的比例较小，但加总的业务和风险足以对金融控股公司的财务状况及风险水平造成重大影响的。 （二）被投资机构所产生的风险和损失足以对金融控股公司造成重大影响的，包括但不限于流动性风险、法律合规风险、声誉风险等。 （三）通过境内外所控股机构、空壳公司及其他复杂股权设计成立的、有证据表明金融控股公司实质控制或对该机构的经营管理存在重大影响的其他被投资机构。 属于金融控股公司所控股机构，但其股权被金融控股公司短期持有，不会对金融控股公司产生重大风险影响的，包括准备在一个会计年度之内出售或清盘、权益性资本在50%以上的，经中国人民银行认可后，可以不纳入金融控股公司并表管理范围。 以企业会计准则和资本监管规定等为基础进行并表管理，具体规则由中国人民银行会同相"},{"i":26,"n":"第二十六条","txt":"金融控股公司、所控股金融机构以及集团整体的资本应当与资产规模和风险水平相适应，资本充足水平应当以并表管理为基础计算，持续符合中国人民银行和国务院银行保险监督管理机构、国务院证券监督管理机构规定。具体办法由中国人民银行另行制定。"},{"i":27,"n":"第二十七条","txt":"金融控股公司应当建立资本补充机制，当所控股金融机构资本不足时，金融控股公司应当及时补充资本。 金融控股公司可以依法发行合格资本工具，保持金融控股集团整体资本充足。"},{"i":28,"n":"第二十八条","txt":"金融控股公司应当严格控制债务风险，保持债务规模和期限结构合理适当。 金融控股公司应当加强资产负债管理，严格管理资产抵押、质押等行为，定期对资产进行评估，逐步实现动态评价，并按照企业会计准则相关规定计提减值准备。"},{"i":29,"n":"第二十九条","txt":"金融控股公司应当建立与金融控股集团组织架构、业务规模、复杂程度和声誉影响相适应的全面风险管理体系。 全面风险管理体系应当覆盖金融控股公司所控股的、由地方政府依法批设或监管的从事金融活动的机构。 金融控股公司应当建立健全声誉风险监测、评估和应急处置机制，加强品牌等方面的管理，降低声誉风险事件对集团整体稳健性的负面影响。"},{"i":30,"n":"第三十条","txt":"金融控股公司应当要求所控股金融机构限期建立全面风险管理体系，督促所控股金融机构采取定性和定量相结合的方法，识别、计量、评估、监测、报告、控制或缓释所控股金融机构所承担的各类风险。 各类风险包括信用风险、市场风险、流动性风险、操作风险、声誉风险、战略风险、信息科技风险以及其他风险。"},{"i":31,"n":"第三十一条","txt":"金融控股公司应当建立与服务实体经济相适应的金融控股集团风险偏好体系，明确集团在实现其战略目标过程中愿意并能够承担的风险水平，确定风险管理目标，确定集团对各类风险的风险容忍度和风险限额。 金融控股公司应当将风险管理要求嵌入集团经营管理流程和信息科技系统中，依据所控股金融机构发展战略和风险偏好，将各类风险指标和风险限额分配到所控股金融机构，建立超限额处置机制，及时监控风险管理制度执行情况。"},{"i":32,"n":"第三十二条","txt":"金融控股公司应当在并表基础上管理集团风险集中与大额风险暴露。金融控股公司应当建立大额风险暴露的管理政策和内控制度，实时监控大额风险暴露，建立大额风险暴露的预警报告制度，以及与风险限额相匹配的风险分散措施等。 集团风险集中与大额风险暴露是指集团并表后的资产组合对单个交易对手或一组有关联的交易对手、行业或地理区域、特定类别的产品等超过集团资本一定比例的风险集中暴露。"},{"i":33,"n":"第三十三条","txt":"金融控股公司应当统筹协调集团对同一企业（含企业集团）授信工作，提升集团信用风险防控水平。 金融控股公司应当主动掌握集团对同一企业融资情况，对融资余额较大的企业，金融控股公司应当牵头建立集团内信息共享和联合授信机制，主要包括协调所控股机构共同收集汇总企业信息，识别隐性关联企业和实际控制人，联合设置企业融资风险预警线等。 金融控股公司应当要求所控股金融机构定期上报从其他金融机构获得的授信额度和使用情况。"},{"i":34,"n":"第三十四条","txt":"金融控股公司应当建立健全集团整体的风险隔离机制，包括金融控股公司与其所控股机构之间、其所控股机构之间的风险隔离制度，强化法人、人事、信息、财务和关联交易等“防火墙”，对集团内部的交叉任职、业务往来、信息共享，以及共用销售团队、信息技术系统、运营后台、营业设施和营业场所等行为进行合理隔离，有效防控风险，保护客户合法权益。"},{"i":35,"n":"第三十五条","txt":"金融控股公司与其所控股金融机构之间、所控股金融机构之间以及所控股金融机构与集团内其他机构之间的集团内部交易，应当遵守法律、行政法规和中国人民银行、国务院银行保险监督管理机构、国务院证券监督管理机构的相关规定，并按照企业会计准则进行会计处理。其中的“关联方”、“关联方交易”等概念，以法律、行政法规和财政部有关财务、会计规定为准。 金融控股公司与其所控股金融机构之外的其他关联方之间发生的关联交易应当遵循市场原则，不得违背公平竞争和反垄断规则。 金融控股公司应当加强关联交易管理。金融控股公司与其所控股金融机构、其他关联方不得通过各种手段隐匿关联交易和资金真实去向，不得通过关联交易开展不正当利益输送、损害投资者或客户的消费权益、规避监管规定或违规操作。 金融控股公司股东应当遵守法律、行政法规和中国人民银行的相关规定，不得与金融控股公司进行不当的关联交易，不得利用其对金融控股公司经营管理的影响力"},{"i":36,"n":"第三十六条","txt":"金融控股公司及其所控股机构不得进行以下关联交易： （一）利用其实质控制权损害其他股东和客户的合法权益。 （二）通过内部交易进行监管套利。 （三）通过第三方间接进行内部交易，损害金融控股公司稳健性。 （四）金融控股公司所控股金融机构（财务公司除外）向金融控股公司提供融资，或向金融控股公司的股东、其他非金融机构关联方提供无担保融资等。 （五）金融控股公司所控股金融机构（财务公司除外）向金融控股公司其他关联方提供的融资或担保，超过提供融资或担保的所控股金融机构资本净额的10%，或超过接受融资或担保的金融控股公司关联方资本净额的20%，国务院银行保险监督管理机构、国务院证券监督管理机构另有规定的除外。 （六）金融控股公司所控股金融机构（财务公司除外）和所控股非金融机构接受金融控股公司的股权作为质押标的。 （七）金融控股公司对金融控股集团外的担保余额超过金融控股公司净资产的10%。 （八）中国人"},{"i":37,"n":"第三十七条","txt":"金融控股公司应当按照法律、行政法规和中国人民银行要求，遵循真实、准确、完整的原则，及时进行信息披露。对信息披露中的虚假记载、误导性陈述及重大遗漏等依法承担责任。"},{"i":38,"n":"第三十八条","txt":"中国人民银行会同相关部门依照法律、行政法规、国务院决定及本办法，制定对金融控股公司及其业务活动实施监督管理的实施细则。"},{"i":39,"n":"第三十九条","txt":"中国人民银行依照法律、行政法规、国务院决定及本办法，对金融控股公司实施并表监管，在并表基础上，通过报告制度、现场检查、监管谈话、风险评估和预警等方式，监控、评估、防范和化解金融控股公司整体层面的资本充足、关联交易、流动性、声誉等风险，维护金融体系整体稳定。金融控股公司符合系统重要性金融机构认定标准的，应当遵守关于系统重要性金融机构的监管规定。"},{"i":40,"n":"第四十条","txt":"中国人民银行对金融控股公司主要股东和控股股东进行审查，对其真实股权结构和实际控制人实施穿透监管。"},{"i":41,"n":"第四十一条","txt":"中国人民银行对金融控股公司主要股东和控股股东的入股资金进行穿透监管，严格审查入股资金来源、性质与流向。"},{"i":42,"n":"第四十二条","txt":"中国人民银行根据履行职责的需要，建立统一的金融控股公司监管信息平台和统计制度，有权要求金融控股公司按照规定报送资产负债表、利润表和其他财务会计、统计报表、经营管理资料以及注册会计师出具的审计报告。具体报送要求由中国人民银行另行规定。 中国人民银行与相关部门之间建立信息共享机制，中国人民银行提供金融控股公司相关监管信息，其他部门提供本领域内的关于金融控股公司的信息。各方应确保信息用于履职需要，遵循保密要求。中国人民银行可以请国务院银行保险监督管理机构、国务院证券监督管理机构提供金融控股公司所控股机构的风险状况、检查报告和监管评级等监督管理信息，所获信息不能满足对金融控股公司监管需要的，中国人民银行可以要求金融控股公司所控股机构直接报送相关信息。"},{"i":43,"n":"第四十三条","txt":"中国人民银行根据履行职责的需要，可以对金融控股公司进行现场检查，询问工作人员，查阅、复制相关文件、资料，检查电子数据系统等。 为促进金融控股公司稳健经营，中国人民银行可以建议国务院银行保险监督管理机构、国务院证券监督管理机构、国家外汇管理部门对金融控股公司所控股金融机构进行现场检查，必要时经国务院批准，可以会同国务院银行保险监督管理机构、国务院证券监督管理机构、国家外汇管理部门对所控股金融机构进行现场检查。国务院银行保险监督管理机构、国务院证券监督管理机构、国家外汇管理部门根据监管需要，可以建议中国人民银行对金融控股公司进行现场检查。"},{"i":44,"n":"第四十四条","txt":"中国人民银行根据履行职责的需要，可以与金融控股公司董事、监事、高级管理人员进行监督管理谈话，要求金融控股公司董事、监事、高级管理人员就金融控股公司业务活动和风险管理的重大事项作出说明。"},{"i":45,"n":"第四十五条","txt":"中国人民银行会同相关部门建立和完善金融控股集团的风险评估体系，综合运用宏观审慎政策、金融机构评级、反洗钱、反恐怖融资监测等政策工具，评估金融控股集团的经营管理与风险状况。中国人民银行可以根据风险评估结果动态调整对金融控股公司的监管要求，区别情形采取风险警示、早期纠正、风险处置措施。"},{"i":46,"n":"第四十六条","txt":"金融控股公司所控股金融机构违反审慎经营规则，财务状况显著恶化，严重危及自身稳健运行、损害客户合法权益，金融控股公司有义务帮助其所控股金融机构恢复正常营运。金融控股公司未主动履行上述义务的，中国人民银行有权会同国务院银行保险监督管理机构、国务院证券监督管理机构要求金融控股公司采取注资、转让股权等适当措施进行自救。金融控股公司在开展救助时，应当做好风险隔离，防范风险传染和蔓延。"},{"i":47,"n":"第四十七条","txt":"金融控股公司应当事前对风险处置作出合格的计划并报告中国人民银行。 金融控股公司违反本办法及相关规定，或自身经营不善，对所控股金融机构、金融控股集团造成重大风险，中国人民银行可以要求其限期整改。所造成的风险状况可能影响金融稳定、严重扰乱金融秩序、损害公众利益的，中国人民银行可以要求金融控股公司采取下列措施： （一）限制经营活动。 （二）限制向股东分红，限制董事、监事、高级管理人员的薪酬和其他收入。 （三）限期补充资本。 （四）调整负有责任的董事、监事、高级管理人员或限制其权利。 （五）转让所控股金融机构的股权。 金融控股公司有本条第二款规定情形的，中国人民银行可以要求其股东转让股权或限制股东权利；必要时，中国人民银行可以提请国务院反垄断部门启动反垄断调查，依法作出处理决定。"},{"i":48,"n":"第四十八条","txt":"金融控股公司难以持续经营，若不市场退出将严重危害金融秩序、损害公众利益的，应当依法实施市场退出。"},{"i":49,"n":"第四十九条","txt":"为维护金融稳定，中国人民银行有权要求金融控股公司制定金融控股集团整体恢复和处置计划，并报中国人民银行备案。"},{"i":50,"n":"第五十条","txt":"按照本办法第六条规定应当设立金融控股公司，但未获得金融控股公司许可的，由中国人民银行会同国务院银行保险监督管理机构、国务院证券监督管理机构责令改正，逾期不改正的，中国人民银行可以会同国务院银行保险监督管理机构、国务院证券监督管理机构对其采取以下措施： （一）要求其部分转让对金融机构的股权至丧失实质控制权。 （二）要求其全部转让对金融机构的股权。 （三）其他纠正措施。 经批准设立的金融控股公司在存续期内，不再符合金融控股公司设立条件的，中国人民银行可以对金融控股公司采取本条前款规定的纠正措施。"},{"i":51,"n":"第五十一条","txt":"金融控股公司的发起人、控股股东、实际控制人违反本办法规定，有下列行为之一的，由中国人民银行责令限期改正，没收违法所得，并处违法所得1倍以上5倍以下罚款。没有违法所得或违法所得不足50万元的，处50万元以上500万元以下罚款。情节严重的，依据《中华人民共和国行政许可法》的规定，撤销行政许可；涉嫌构成犯罪的，移送有关机关依法追究刑事责任： （一）提供虚假的承诺函。 （二）虚假出资、循环注资，利用委托资金、债务资金等非自有资金出资。 （三）通过委托他人或接受他人委托等方式违规持有金融控股公司股权。 （四）提供虚假的或隐瞒重要事实的资料。 （五）违反本办法规定的其他情形。"},{"i":52,"n":"第五十二条","txt":"金融控股公司违反本办法规定，有下列行为之一的，由中国人民银行责令限期改正，没收违法所得，对单位处违法所得1倍以上10倍以下罚款，没有违法所得或违法所得不足100万元的，处100万元以上1000万元以下罚款；对直接负责的董事、高级管理人员和其他直接责任人员，处违法所得1倍以上10倍以下罚款，没有违法所得或违法所得不足10万元的，处10万元以上100万元以下罚款；涉嫌构成犯罪的，移送有关机关依法追究刑事责任： （一）对金融机构虚假出资、循环注资，利用委托资金、债务资金等非自有资金出资。 （二）违规开展关联交易。 （三）干预所控股金融机构经营造成重大风险或重大风险隐患。 （四）提供虚假的或隐瞒重要事实的财务会计报告、报表、统计报表及经营资料。 （五）拒绝或阻碍中国人民银行现场检查。 （六）违反本办法的其他情形。"},{"i":53,"n":"第五十三条","txt":"本办法所称金融控股公司主要股东是指持有或控制金融控股公司股份总额5%以上股份或表决权，或持有股份总额不足5%但对金融控股公司经营管理有重大影响的股东。 本办法所称金融控股公司控股股东是指其出资额占金融控股公司资本总额50%以上或其持有的股份占金融控股公司股本总额50%以上的股东；出资额或持有股份的比例虽不足50%，但依其出资额或持有的股份所享有的表决权已足以对股东会、股东大会的决议产生重大影响或能够实际支配公司行为的股东。 本办法所称实际控制人是指通过投资关系、协议或其他安排，能够实际支配公司行为的人。"},{"i":54,"n":"第五十四条","txt":"本办法实施前已经存在的、具备金融控股公司设立情形的机构，如果未达到本办法规定的监管要求，经国务院金融管理部门同意，可以在一定期限内进行整改，并由国务院金融管理部门进行验收。"},{"i":55,"n":"第五十五条","txt":"本办法由中国人民银行负责解释。"},{"i":56,"n":"第五十六条","txt":"本办法自2020年11月1日起施行。"}],"jinrongkonggugongsidongshijianshigaojiguanlirenyua63dd31":[{"i":1,"n":"第一条","txt":"为了加强对金融控股公司董事、监事、高级管理人员的任职管理，规范金融控股公司运作，防范经营风险，根据《国务院关于实施金融控股公司准入管理的决定》（国发〔2020〕12号）、《金融控股公司监督管理试行办法》（中国人民银行令〔2020〕第4号发布）及有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"对金融控股公司董事、监事、高级管理人员的任职管理，适用本规定。 本规定所称高级管理人员，是指对金融控股公司经营管理、风险控制具有决策权或者重大影响的人员，包括：总经理、副总经理、总经理助理、董事会秘书、风险管理负责人、合规负责人、财务负责人、审计负责人、同职级的其他高级管理人员，以及实际履行上述职务职责的人员。"},{"i":3,"n":"第三条","txt":"中国人民银行负责对金融控股公司董事、监事、高级管理人员的任职进行备案和监督管理。 中国人民银行副省级城市中心支行以上分支机构（以下简称中国人民银行分支机构）依照本规定开展相关工作。"},{"i":4,"n":"第四条","txt":"金融控股公司董事、监事、高级管理人员应当符合法律、行政法规的相关规定以及中国人民银行规定的任职条件。 金融控股公司不得任用不符合任职条件的人员担任董事、监事、高级管理人员，不得授权不符合任职条件的人员实际行使董事、监事、高级管理人员的相关职权。"},{"i":5,"n":"第五条","txt":"金融控股公司董事、监事、高级管理人员应当遵守法律、行政法规和中国人民银行有关规定，遵守金融控股公司章程，遵循诚信原则，切实履行职责，不得利用职务之便牟取非法利益。"},{"i":6,"n":"第六条","txt":"担任金融控股公司董事、监事、高级管理人员的，应当具备下列条件： （一）具有完全民事行为能力； （二）具有良好的守法合规记录； （三）具有良好的品行、声誉； （四）具有大学本科以上学历或者学士以上学位； （五）从事金融工作5年以上，或者从事相关经济工作等与其履行职责相适应的工作8年以上，并具有良好的从业记录； （六）具有与职务相适应的知识、经验和能力。"},{"i":7,"n":"第七条","txt":"担任金融控股公司董事长、副董事长、监事会主席、总经理、副总经理或者实际履行上述职务职责的人员，应当从事金融工作8年以上，或者从事相关经济工作10年以上，并具有良好的从业记录。 金融控股公司董事长、监事会主席、总经理或者实际履行上述职务职责的人员，原则上在同一家金融控股公司任同一职务时间累计不得超过10年。"},{"i":8,"n":"第八条","txt":"金融控股公司高级管理人员还应当具有下列任职经历之一： （一）担任金融控股公司等金融机构部门负责人同等及以上职务不少于2年，其中担任总经理或者实际履行其职务职责的人员，该任职经历应当不少于5年； （二）担任金融管理部门相当管理职务不少于2年，其中担任总经理或者实际履行其职务职责的人员，该任职经历应当不少于5年； （三）其他证明其具有该职务所需知识、能力、经验的任职经历。"},{"i":9,"n":"第九条","txt":"担任金融控股公司财务负责人的，还应当取得高级会计师以上职称或者注册会计师资格，并从事财务、会计或者审计相关工作2年以上。没有取得高级会计师以上职称或者注册会计师资格的，应当从事财务、会计或者审计相关工作10年以上。 担任金融控股公司风险管理负责人的，还应当从事风险管理相关工作2年以上。 担任金融控股公司合规负责人的，还应当从事法律合规相关工作2年以上。 担任金融控股公司审计负责人的，还应当从事财务、会计或者审计相关工作2年以上。"},{"i":10,"n":"第十条","txt":"金融控股公司所实质控制金融机构中包含商业银行（不含村镇银行）的，其董事、高级管理人员中应当分别至少有1人在商业银行（不含村镇银行）担任部门负责人同等及以上职务不少于3年，或者在相应金融管理部门担任相当管理职务不少于3年。 金融控股公司所实质控制金融机构中包含证券公司的，其董事、高级管理人员中应当分别至少有1人在证券公司担任部门负责人同等及以上职务不少于3年，或者在相应金融管理部门担任相当管理职务不少于3年。 金融控股公司所实质控制金融机构中包含保险公司的，其董事、高级管理人员中应当分别至少有1人在保险公司担任部门负责人同等及以上职务不少于3年，或者在相应金融管理部门担任相当管理职务不少于3年。"},{"i":11,"n":"第十一条","txt":"有下列情形之一的，不得担任金融控股公司董事、监事、高级管理人员： （一）因犯有危害国家安全、恐怖主义、贪污、贿赂、侵占财产、挪用财产、黑社会性质犯罪或者破坏社会主义经济秩序罪，被判处刑罚，自执行期满之日起未逾5年；或者因犯罪被剥夺政治权利，自执行期满之日起未逾5年；或者涉嫌从事重大违法活动、被相关部门调查尚未作出处理结论。 （二）对曾任职机构违法违规行为、重大损失负有个人责任或者直接领导责任，情节严重的，或者对曾任职机构被接管、撤销、宣告破产或者吊销营业执照负有个人责任，自该机构被接管、撤销、宣告破产或者吊销营业执照之日起未逾3年。 （三）不配合或者指使他人不配合依法监管或者案件查处而受到处罚未逾3年。 （四）被金融管理部门取消、撤销任职资格未逾3年，或者被金融管理部门禁止进入市场期满未逾3年，或者被金融管理部门处罚未逾3年。 （五）被国家机关开除公职，自作出处分决定之日起未逾3年。"},{"i":12,"n":"第十二条","txt":"金融控股公司独立董事除不得存在第十一条所列情形外，还不得存在下列情形： （一）本人及其近亲属合并持有该金融控股公司或者其所控股单个机构1%以上股份或者股权； （二）本人或者其近亲属在持有该金融控股公司1%以上股份或者股权的股东单位任职； （三）本人或者其近亲属在该金融控股公司或者其所控股机构任职，其中不包括本人在该金融控股公司担任独立董事； （四）本人或者其近亲属任职的机构与该金融控股公司之间存在因法律、会计、审计、管理咨询、担保合作等方面的业务联系或者债权债务等方面的利益关系，以致于妨碍其履职独立性的情形； （五）本人或者其近亲属可能被该金融控股公司主要股东、高级管理层控制或者施加重大影响，以致于妨碍其履职独立性的其他情形。"},{"i":13,"n":"第十三条","txt":"独立董事在同一家金融控股公司任职时间累计不得超过6年，且同时最多只能在两家金融控股公司兼任独立董事。"},{"i":14,"n":"第十四条","txt":"金融控股公司董事、监事、高级管理人员的兼任行为不得违反法律、行政法规及金融管理部门有关规定，不得存在利益冲突，或者明显分散其在该金融控股公司履职的时间和精力。 金融控股公司董事长和总经理应当分设。金融控股公司高级管理人员除在本公司参股或者在其控股的机构担任董事、监事之外，不得在其他营利性机构兼任职务。法律法规和中国人民银行另有规定的除外。"},{"i":15,"n":"第十五条","txt":"金融控股公司任命董事、监事、高级管理人员或者授权相关人员履行董事、监事、高级管理人员职责，应当确认其符合相应的任职条件，并自决定作出之日起5个工作日内向中国人民银行提交下列备案材料，同时抄送住所地中国人民银行分支机构： （一）备案报告书，内容至少包含所任职务、职责范围、权限及该职务在本金融控股公司组织架构中的位置，并对照本规定的任职条件逐项进行说明； （二）中国人民银行统一制作的任职备案表； （三）身份、学历、学位和相关专业技术资格等材料的复印件； （四）关于任职人员品行、专业知识、业务能力、工作业绩等方面的综合鉴定； （五）股东（大）会、董事会关于董事、监事、高级管理人员的任职决议； （六）金融控股公司董事、监事、高级管理人员的个人信用报告； （七）最近3年内曾担任金融机构董事长或者高级管理人员的，还应当提交最近职务的离任审计报告或者经济责任审计报告； （八）不存在任何不符合任职条件"},{"i":16,"n":"第十六条","txt":"本规定第十五条所规定的备案材料应当分别加盖单位公章，纸质材料提交一式两份。备案材料正本的电子扫描光盘一张（PDF格式文件），随纸质材料一同报送。"},{"i":17,"n":"第十七条","txt":"金融控股公司董事、监事、高级管理人员改任的，高级管理人员兼任其他高级管理职务的，以及董事与高级管理人员相互兼任的，除本条第二款所述情形外，应当按规定备案。 金融控股公司应当在作出下列改任、兼任决定之日起5个工作日内向中国人民银行及其分支机构书面报告： （一）已备案的金融控股公司董事长、副董事长、监事会主席，在同一金融控股公司内改任除独立董事之外其他董事、监事；除董事长、副董事长、监事会主席、独立董事之外的已备案的董事、监事，在同一金融控股公司内由董事改任监事或者由监事改任董事。 （二）已备案的金融控股公司总经理、副总经理，在同一金融控股公司内改任除独立董事之外其他董事、监事，以及兼任除独立董事之外其他董事；除总经理、副总经理之外的已备案的金融控股公司高级管理人员，在同一金融控股公司内改任除董事长、副董事长、监事会主席、独立董事之外其他董事、监事，以及兼任除董事长、副董事长、独立董事之外"},{"i":18,"n":"第十八条","txt":"金融控股公司董事长、总经理职务存在人员空缺时，金融控股公司应当按照公司章程等有关规定，确定符合任职条件的人员代为履职，并在确定之日起5个工作日内向中国人民银行及其分支机构书面报告。 代为履职时间不得超过6个月，金融控股公司应当在6个月内选聘符合任职条件的人员，并向中国人民银行备案。"},{"i":19,"n":"第十九条","txt":"金融控股公司聘任或者解聘董事、监事、高级管理人员的，应当自作出决定之日起20个工作日内通过公司官方网站和其他媒体向社会公告有关情况。"},{"i":20,"n":"第二十条","txt":"中国人民银行及其分支机构通过审核备案材料、考察谈话、调查从业经历等方式对相关人员的任职条件进行核查。 材料不齐全、不符合规定形式或者存在错误的，金融控股公司应当在收到补充或者完善材料的通知之日起10个工作日内向中国人民银行提交符合要求的材料，同时抄送住所地中国人民银行分支机构。 未达到中国人民银行规定的任职条件的，以及隐瞒有关情况或者提供虚假材料的，中国人民银行应当要求金融控股公司进行限期调整，并自完成调整之日起3个工作日内向中国人民银行及其分支机构书面报告。"},{"i":21,"n":"第二十一条","txt":"金融控股公司应当制定符合本规定的董事、监事、高级管理人员任职管理制度，并及时向中国人民银行及其分支机构书面报告。 中国人民银行及其分支机构对金融控股公司制定的董事、监事、高级管理人员任职管理制度进行评估和指导，并对其任职管理制度执行情况进行检查。"},{"i":22,"n":"第二十二条","txt":"中国人民银行及其分支机构通过现场检查及非现场监管等方式对金融控股公司及其董事、监事、高级管理人员执行本规定的情况进行监督检查。 中国人民银行建立和完善金融控股公司董事、监事、高级管理人员管理信息系统。中国人民银行及其分支机构在该系统中记录关于金融控股公司董事、监事、高级管理人员的有关信息，包括但不限于下列内容： （一）任职备案材料的基本内容及职务变更情况； （二）受到的刑事处罚、主管部门的行政处罚、行政处分或者纪律处分； （三）与其相关的风险提示函和监管谈话记录； （四）被金融管理部门书面认定为不适合担任董事、监事、高级管理人员职务，或者被金融管理部门撤销、取消任职资格的情况； （五）审计发现的重大问题。 中国人民银行向有关董事、监事、高级管理人员的任免机构或者组织告知上述相关情况。"},{"i":23,"n":"第二十三条","txt":"出现下列情形时，金融控股公司应当自发生之日起5个工作日内向中国人民银行及其分支机构书面报告： （一）停止担任金融控股公司董事、监事、高级管理人员职务的，其书面报告包括免职决定文件、相关会议的决议等材料； （二）金融控股公司调整高级管理人员职责分工； （三）董事、监事、高级管理人员在金融控股公司之外的机构兼任职务； （四）董事、监事、高级管理人员受到刑事处罚、主管部门的行政处罚、行政处分或者纪律处分； （五）董事、监事、高级管理人员出现不符合任职条件情形。"},{"i":24,"n":"第二十四条","txt":"金融控股公司董事长、高级管理人员离任或者改任的，金融控股公司应当于该人员离任或者改任之日起3个月内向中国人民银行及其分支机构提交离任审计报告。 金融控股公司董事长的离任审计报告应当至少包括对下列情况及其所负领导责任和直接责任的评估结论： （一）贯彻执行国家法律法规、各项规章制度的情况。 （二）董事会运作是否合法有效。 （三）金融控股公司的风险管理与内部控制是否有效。 （四）金融控股公司是否发生重大案件、重大损失或者重大风险。 （五）被审计对象是否涉及所在金融控股集团的重大关联交易，以及重大关联交易是否依法披露；是否存在受到刑事处罚、主管部门的行政处罚、行政处分或者纪律处分等情形。 金融控股公司高级管理人员的离任审计报告应当至少包括对下列情况及其所负领导责任和直接责任的评估结论： （一）贯彻执行国家法律法规、各项规章制度的情况； （二）金融控股公司或者分管部门的经营是否合法合规； （三）"},{"i":25,"n":"第二十五条","txt":"金融控股公司出现下列情形之一的，中国人民银行应当要求其改正，并对直接负责的董事、监事、高级管理人员出具风险提示函，进行监管谈话，并要求其就相关事项作出说明： （一）在股权投资管理、公司治理结构或者内控制度等方面存在重大隐患； （二）董事、监事、高级管理人员不符合中国人民银行规定的任职条件，未按规定进行任职备案，未按规定履行报告义务，未按规定进行离任审计，违反规定授权其他人员实际行使董事、监事、高级管理人员相关职权，以及未按照中国人民银行的要求调整董事、监事、高级管理人员的； （三）违反本规定的其他情形。"},{"i":26,"n":"第二十六条","txt":"金融控股公司所控股金融机构出现重大违法违规问题或者重大风险隐患，金融监管部门可以建议中国人民银行对金融控股公司负有直接责任的董事、监事、高级管理人员进行监管谈话；认为其不适宜继续履职的，可以建议中国人民银行要求金融控股公司限期调整。"},{"i":27,"n":"第二十七条","txt":"本规定所称近亲属包括配偶、父母、子女、兄弟姐妹、祖父母、外祖父母、孙子女、外孙子女。"},{"i":28,"n":"第二十八条","txt":"本规定由中国人民银行负责解释。"},{"i":29,"n":"第二十九条","txt":"本规定自2021年5月1日起施行。"}],"jinrongjigoufanxiqianhefankongburongzijianduguanli43f89a":[{"i":1,"n":"第一条","txt":"为了督促金融机构有效履行反洗钱和反恐怖融资义务，规范反洗钱和反恐怖融资监督管理行为，根据《中华人民共和国反洗钱法》《中华人民共和国中国人民银行法》《中华人民共和国反恐怖主义法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内依法设立的下列金融机构： （一）开发性金融机构、政策性银行、商业银行、农村合作银行、农村信用合作社、村镇银行； （二）证券公司、期货公司、证券投资基金管理公司； （三）保险公司、保险资产管理公司； （四）信托公司、金融资产管理公司、企业集团财务公司、金融租赁公司、汽车金融公司、消费金融公司、货币经纪公司、贷款公司、银行理财子公司； （五）中国人民银行确定并公布应当履行反洗钱和反恐怖融资义务的其他金融机构。 非银行支付机构、银行卡清算机构、资金清算中心、网络小额贷款公司以及从事汇兑业务、基金销售业务、保险专业代理和保险经纪业务的机构，适用本办法关于金融机构的监督管理规定。"},{"i":3,"n":"第三条","txt":"中国人民银行及其分支机构依法对金融机构反洗钱和反恐怖融资工作进行监督管理。"},{"i":4,"n":"第四条","txt":"金融机构应当按照规定建立健全反洗钱和反恐怖融资内部控制制度，评估洗钱和恐怖融资风险，建立与风险状况和经营规模相适应的风险管理机制，搭建反洗钱信息系统，设立或者指定部门并配备相应人员，有效履行反洗钱和反恐怖融资义务。"},{"i":5,"n":"第五条","txt":"对依法履行反洗钱和反恐怖融资职责或者义务获得的客户身份资料和交易信息，应当予以保密，非依法律规定不得对外提供。"},{"i":6,"n":"第六条","txt":"金融机构应当按照规定，结合本机构经营规模以及洗钱和恐怖融资风险状况，建立健全反洗钱和反恐怖融资内部控制制度。"},{"i":7,"n":"第七条","txt":"金融机构应当在总部层面建立洗钱和恐怖融资风险自评估制度，定期或不定期评估洗钱和恐怖融资风险，经董事会或者高级管理层审定之日起10个工作日内，将自评估情况报送中国人民银行或者所在地中国人民银行分支机构。 金融机构洗钱和恐怖融资风险自评估应当与本机构经营规模和业务特征相适应，充分考虑客户、地域、业务、交易渠道等方面的风险要素类型及其变化情况，并吸收运用国家洗钱和恐怖融资风险评估报告、监管部门及自律组织的指引等。金融机构在采用新技术、开办新业务或者提供新产品、新服务前，或者其面临的洗钱或者恐怖融资风险发生显著变化时，应当进行洗钱和恐怖融资风险评估。 金融机构应当定期审查和不断优化洗钱和恐怖融资风险评估工作流程和指标体系。"},{"i":8,"n":"第八条","txt":"金融机构应当根据本机构经营规模和已识别出的洗钱和恐怖融资风险状况，经董事会或者高级管理层批准，制定相应的风险管理政策，并根据风险状况变化和控制措施执行情况及时调整。 金融机构应当将洗钱和恐怖融资风险管理纳入本机构全面风险管理体系，覆盖各项业务活动和管理流程；针对识别的较高风险情形，应当采取强化措施，管理和降低风险；针对识别的较低风险情形，可以采取简化措施；超出金融机构风险控制能力的，不得与客户建立业务关系或者进行交易，已经建立业务关系的，应当中止交易并考虑提交可疑交易报告，必要时终止业务关系。"},{"i":9,"n":"第九条","txt":"金融机构应当设立专门部门或者指定内设部门牵头开展反洗钱和反恐怖融资管理工作。 金融机构应当明确董事会、监事会、高级管理层和相关部门的反洗钱和反恐怖融资职责，建立相应的绩效考核和奖惩机制。 金融机构应当任命或者授权一名高级管理人员牵头负责反洗钱和反恐怖融资管理工作，并采取合理措施确保其独立开展工作以及充分获取履职所需权限和资源。 金融机构应当根据本机构经营规模、洗钱和恐怖融资风险状况和业务发展趋势配备充足的反洗钱岗位人员，采取适当措施确保反洗钱岗位人员的资质、经验、专业素质及职业道德符合要求，制定持续的反洗钱和反恐怖融资培训计划。"},{"i":10,"n":"第十条","txt":"金融机构应当根据反洗钱和反恐怖融资工作需要，建立和完善相关信息系统，并根据风险状况、反洗钱和反恐怖融资工作需求变化及时优化升级。"},{"i":11,"n":"第十一条","txt":"金融机构应当建立反洗钱和反恐怖融资审计机制，通过内部审计或者独立审计等方式，审查反洗钱和反恐怖融资内部控制制度制定和执行情况。审计应当遵循独立性原则，全面覆盖境内外分支机构、控股附属机构，审计的范围、方法和频率应当与本机构经营规模及洗钱和恐怖融资风险状况相适应，审计报告应当向董事会或者其授权的专门委员会提交。"},{"i":12,"n":"第十二条","txt":"金融机构应当在总部层面制定统一的反洗钱和反恐怖融资机制安排，包括为开展客户尽职调查、洗钱和恐怖融资风险管理，共享反洗钱和反恐怖融资信息的制度和程序，并确保其所有分支机构和控股附属机构结合自身业务特点有效执行。 金融机构在共享和使用反洗钱和反恐怖融资信息方面应当依法提供信息并防止信息泄露。"},{"i":13,"n":"第十三条","txt":"金融机构应当要求其境外分支机构和控股附属机构在驻在国家（地区）法律规定允许的范围内，执行本办法；驻在国家（地区）有更严格要求的，遵守其规定。 如果本办法的要求比驻在国家（地区）的相关规定更为严格，但驻在国家（地区）法律禁止或者限制境外分支机构和控股附属机构实施本办法的，金融机构应当采取适当的补充措施应对洗钱和恐怖融资风险，并向中国人民银行报告。"},{"i":14,"n":"第十四条","txt":"金融机构应当按照规定，结合内部控制制度和风险管理机制的相关要求，履行客户尽职调查、客户身份资料和交易记录保存、大额交易和可疑交易报告等义务。"},{"i":15,"n":"第十五条","txt":"金融机构应当按照中国人民银行的规定报送反洗钱和反恐怖融资工作信息。金融机构应当对相关信息的真实性、完整性、有效性负责。"},{"i":16,"n":"第十六条","txt":"在境外设有分支机构或控股附属机构的，境内金融机构总部应当按年度向中国人民银行或者所在地中国人民银行分支机构报告境外分支机构或控股附属机构接受驻在国家（地区）反洗钱和反恐怖融资监管情况。"},{"i":17,"n":"第十七条","txt":"发生下列情况的，金融机构应当按照规定及时向中国人民银行或者所在地中国人民银行分支机构报告： （一）制定或者修订主要反洗钱和反恐怖融资内部控制制度的； （二）牵头负责反洗钱和反恐怖融资工作的高级管理人员、牵头管理部门或者部门主要负责人调整的； （三）发生涉及反洗钱和反恐怖融资工作的重大风险事项的； （四）境外分支机构和控股附属机构受到当地监管当局或者司法部门开展的与反洗钱和反恐怖融资相关的执法检查、行政处罚、刑事调查或者发生其他重大风险事件的； （五）中国人民银行要求报告的其他事项。"},{"i":18,"n":"第十八条","txt":"中国人民银行及其分支机构应当遵循风险为本和法人监管原则，合理运用各类监管方法，实现对不同类型金融机构的有效监管。 中国人民银行及其分支机构可以向国务院金融监督管理机构或者其派出机构通报对金融机构反洗钱和反恐怖融资监管情况。"},{"i":19,"n":"第十九条","txt":"根据履行反洗钱和反恐怖融资职责的需要，中国人民银行及其分支机构可以按照规定程序，对金融机构履行反洗钱和反恐怖融资义务的情况开展执法检查。 中国人民银行及其分支机构可以对其下级机构负责监督管理的金融机构进行反洗钱和反恐怖融资执法检查，可以授权下级机构检查由上级机构负责监督管理的金融机构。"},{"i":20,"n":"第二十条","txt":"中国人民银行及其分支机构开展反洗钱和反恐怖融资执法检查，应当依据现行反洗钱和反恐怖融资规定，按照中国人民银行执法检查有关程序规定组织实施。"},{"i":21,"n":"第二十一条","txt":"中国人民银行及其分支机构应当根据执法检查有关程序规定，规范有效地开展执法检查工作，重点加强对以下机构的监督管理： （一）涉及洗钱和恐怖融资案件的机构； （二）洗钱和恐怖融资风险较高的机构； （三）通过日常监管、受理举报投诉等方式，发现存在重大违法违规线索的机构； （四）其他应当重点监管的机构。"},{"i":22,"n":"第二十二条","txt":"中国人民银行及其分支机构进入金融机构现场开展反洗钱和反恐怖融资检查的，按照规定可以询问金融机构工作人员，要求其对监管事项作出说明；查阅、复制文件、资料，对可能被转移、隐匿或者销毁的文件、资料予以封存；查验金融机构运用信息化、数字化管理业务数据和进行洗钱和恐怖融资风险管理的系统。"},{"i":23,"n":"第二十三条","txt":"中国人民银行及其分支机构应当根据金融机构报送的反洗钱和反恐怖融资工作信息，结合日常监管中获得的其他信息，对金融机构反洗钱和反恐怖融资制度的建立健全情况和执行情况进行评价。"},{"i":24,"n":"第二十四条","txt":"为了有效实施风险为本监管，中国人民银行及其分支机构应当结合国家、地区、行业的洗钱和恐怖融资风险评估情况，在采集金融机构反洗钱和反恐怖融资信息的基础上，对金融机构开展风险评估，及时、准确掌握金融机构洗钱和恐怖融资风险状况。"},{"i":25,"n":"第二十五条","txt":"为了解金融机构洗钱和恐怖融资风险状况，中国人民银行及其分支机构可以对金融机构开展洗钱和恐怖融资风险现场评估。 中国人民银行及其分支机构开展现场风险评估应当填制《反洗钱监管审批表》（附1）及《反洗钱监管通知书》（附2），经本行（营业管理部）行长（主任）或者分管副行长（副主任）批准后，至少提前5个工作日将《反洗钱监管通知书》送达被评估的金融机构。 中国人民银行及其分支机构可以要求被评估的金融机构提供必要的资料数据，也可以现场采集评估需要的信息。 在开展现场风险评估时，中国人民银行及其分支机构的反洗钱工作人员不得少于2人，并出示合法证件。 现场风险评估结束后，中国人民银行及其分支机构应当制发《反洗钱监管意见书》（附3），将风险评估结论和发现的问题反馈被评估的金融机构。"},{"i":26,"n":"第二十六条","txt":"根据金融机构合规情况和风险状况，中国人民银行及其分支机构可以采取监管提示、约见谈话、监管走访等措施。在监管过程中，发现金融机构存在较高洗钱和恐怖融资风险或者涉嫌违反反洗钱和反恐怖融资规定的，中国人民银行及其分支机构应当及时开展执法检查。"},{"i":27,"n":"第二十七条","txt":"金融机构存在洗钱和恐怖融资风险隐患，或者反洗钱和反恐怖融资工作存在明显漏洞，需要提示金融机构关注的，经中国人民银行或其分支机构反洗钱部门负责人批准，可以向该金融机构发出《反洗钱监管提示函》（附4），要求其采取必要的管控措施，督促其整改。 金融机构应当自收到《反洗钱监管提示函》之日起20个工作日内，经本机构分管反洗钱和反恐怖融资工作负责人签批后作出书面答复；不能及时作出答复的，经中国人民银行或者其所在地中国人民银行分支机构同意后，在延长时限内作出答复。"},{"i":28,"n":"第二十八条","txt":"根据履行反洗钱和反恐怖融资职责的需要，针对金融机构反洗钱和反恐怖融资义务履行不到位、突出风险事件等重要问题，中国人民银行及其分支机构可以约见金融机构董事、监事、高级管理人员或者部门负责人进行谈话。"},{"i":29,"n":"第二十九条","txt":"中国人民银行及其分支机构进行约见谈话前，应当填制《反洗钱监管审批表》及《反洗钱监管通知书》。约见金融机构董事、监事、高级管理人员，应当经本行（营业管理部）行长（主任）或者分管副行长（副主任）批准；约见金融机构部门负责人的，应当经本行（营业管理部）反洗钱部门负责人批准。 《反洗钱监管通知书》应当至少提前2个工作日送达被谈话机构。情况特殊需要立即进行约见谈话的，应当在约见谈话现场送达《反洗钱监管通知书》。 约见谈话时，中国人民银行及其分支机构反洗钱工作人员不得少于2人。谈话结束后，应当填写《反洗钱约谈记录》（附5）并经被谈话人签字确认。"},{"i":30,"n":"第三十条","txt":"为了解、核实金融机构反洗钱和反恐怖融资政策执行情况以及监管意见整改情况，中国人民银行及其分支机构可以对金融机构开展监管走访。"},{"i":31,"n":"第三十一条","txt":"中国人民银行及其分支机构进行监管走访前，应当填制《反洗钱监管审批表》及《反洗钱监管通知书》，由本行（营业管理部）行长（主任）或者分管副行长（副主任）批准。 《反洗钱监管通知书》应当至少提前5个工作日送达金融机构。情况特殊需要立即实施监管走访的，应当在进入金融机构现场时送达《反洗钱监管通知书》。 监管走访时，中国人民银行及其分支机构反洗钱工作人员不得少于2人，并出示合法证件。 中国人民银行及其分支机构应当做好监管走访记录，必要时，可以制发《反洗钱监管意见书》。"},{"i":32,"n":"第三十二条","txt":"中国人民银行及其分支机构应当持续跟踪金融机构对监管发现问题的整改情况，对于未合理制定整改计划或者未有效实施整改的，可以启动执法检查或者进一步采取其他监管措施。"},{"i":33,"n":"第三十三条","txt":"中国人民银行分支机构对金融机构分支机构依法实施行政处罚，或者在监管过程中发现涉及金融机构总部的重大问题、系统性缺陷的，应当及时将处罚决定或者监管意见抄送中国人民银行或者金融机构总部所在地中国人民银行分支机构。"},{"i":34,"n":"第三十四条","txt":"中国人民银行及其分支机构监管人员违反规定程序或者超越职权规定实施监管的，金融机构有权拒绝或者提出异议。金融机构对中国人民银行及其分支机构提出的违法违规问题有权提出申辩，有合理理由的，中国人民银行及其分支机构应当采纳。"},{"i":35,"n":"第三十五条","txt":"中国人民银行及其分支机构从事反洗钱工作的人员，违反本办法有关规定的，按照《中华人民共和国反洗钱法》第三十条的规定予以处分。"},{"i":36,"n":"第三十六条","txt":"金融机构违反本办法有关规定的，由中国人民银行或者其地市中心支行以上分支机构按照《中华人民共和国反洗钱法》第三十一条、第三十二条的规定进行处理；区别不同情形，建议国务院金融监督管理机构依法予以处理。 中国人民银行县（市）支行发现金融机构违反本规定的，应报告其上一级分支机构，由该分支机构按照前款规定进行处理或提出建议。"},{"i":37,"n":"第三十七条","txt":"金融集团适用本办法第九条第四款、第十一条至第十三条的规定。"},{"i":38,"n":"第三十八条","txt":"本办法由中国人民银行负责解释。"},{"i":39,"n":"第三十九条","txt":"本办法自2021年8月1日起施行。本办法施行前有关反洗钱和反恐怖融资规定与本办法不一致的，按照本办法执行。《金融机构反洗钱监督管理办法（试行）》（银发〔2014〕344号文印发）同时废止。 附： 1.反洗钱监管审批表 2.反洗钱监管通知书 3.反洗钱监管意见书 4.反洗钱监管提示函 5.反洗钱约谈记录 附1 附2 附3 附4 附5"}],"jinrongjigoufanxiqianguiding":[{"i":1,"n":"第一条","txt":"为了预防洗钱活动，规范反洗钱监督管理行为和金融机构的反洗钱工作，维护金融秩序，根据《中华人民共和国反洗钱法》、《中华人民共和国中国人民银行法》等有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在中华人民共和国境内依法设立的下列金融机构： （一）商业银行、城市信用合作社、农村信用合作社、邮政储汇机构、政策性银行； （二）证券公司、期货经纪公司、基金管理公司； （三）保险公司、保险资产管理公司； （四）信托投资公司、金融资产管理公司、财务公司、金融租赁公司、汽车金融公司、货币经纪公司； （五）中国人民银行确定并公布的其他金融机构。 从事汇兑业务、支付清算业务和基金销售业务的机构适用本规定对金融机构反洗钱监督管理的规定。"},{"i":3,"n":"第三条","txt":"中国人民银行是国务院反洗钱行政主管部门，依法对金融机构的反洗钱工作进行监督管理。中国银行业监督管理委员会、中国证券监督管理委员会、中国保险监督管理委员会在各自的职责范围内履行反洗钱监督管理职责。 中国人民银行在履行反洗钱职责过程中，应当与国务院有关部门、机构和司法机关相互配合。"},{"i":4,"n":"第四条","txt":"中国人民银行根据国务院授权代表中国政府开展反洗钱国际合作。中国人民银行可以和其他国家或者地区的反洗钱机构建立合作机制，实施跨境反洗钱监督管理。"},{"i":5,"n":"第五条","txt":"中国人民银行依法履行下列反洗钱监督管理职责： （一）制定或者会同中国银行业监督管理委员会、中国证券监督管理委员会和中国保险监督管理委员会制定金融机构反洗钱规章； （二）负责人民币和外币反洗钱的资金监测； （三）监督、检查金融机构履行反洗钱义务的情况； （四）在职责范围内调查可疑交易活动； （五）向侦查机关报告涉嫌洗钱犯罪的交易活动； （六）按照有关法律、行政法规的规定，与境外反洗钱机构交换与反洗钱有关的信息和资料； （七）国务院规定的其他有关职责。"},{"i":6,"n":"第六条","txt":"中国人民银行设立中国反洗钱监测分析中心，依法履行下列职责： （一）接收并分析人民币、外币大额交易和可疑交易报告； （二）建立国家反洗钱数据库,妥善保存金融机构提交的大额交易和可疑交易报告信息； （三）按照规定向中国人民银行报告分析结果； （四）要求金融机构及时补正人民币、外币大额交易和可疑交易报告； （五）经中国人民银行批准，与境外有关机构交换信息、资料； （六）中国人民银行规定的其他职责。"},{"i":7,"n":"第七条","txt":"中国人民银行及其工作人员应当对依法履行反洗钱职责获得的信息予以保密，不得违反规定对外提供。 中国反洗钱监测分析中心及其工作人员应当对依法履行反洗钱职责获得的客户身份资料、大额交易和可疑交易信息予以保密；非依法律规定，不得向任何单位和个人提供。"},{"i":8,"n":"第八条","txt":"金融机构及其分支机构应当依法建立健全反洗钱内部控制制度，设立反洗钱专门机构或者指定内设机构负责反洗钱工作，制定反洗钱内部操作规程和控制措施，对工作人员进行反洗钱培训，增强反洗钱工作能力。 金融机构及其分支机构的负责人应当对反洗钱内部控制制度的有效实施负责。"},{"i":9,"n":"第九条","txt":"金融机构应当按照规定建立和实施客户身份识别制度。 （一）对要求建立业务关系或者办理规定金额以上的一次性金融业务的客户身份进行识别，要求客户出示真实有效的身份证件或者其他身份证明文件，进行核对并登记，客户身份信息发生变化时，应当及时予以更新； （二）按照规定了解客户的交易目的和交易性质，有效识别交易的受益人； （三）在办理业务中发现异常迹象或者对先前获得的客户身份资料的真实性、有效性、完整性有疑问的，应当重新识别客户身份； （四）保证与其有代理关系或者类似业务关系的境外金融机构进行有效的客户身份识别，并可从该境外金融机构获得所需的客户身份信息。 前款规定的具体实施办法由中国人民银行会同中国银行业监督管理委员会、中国证券监督管理委员会和中国保险监督管理委员会制定。"},{"i":10,"n":"第十条","txt":"金融机构应当在规定的期限内，妥善保存客户身份资料和能够反映每笔交易的数据信息、业务凭证、账簿等相关资料。 前款规定的具体实施办法由中国人民银行会同中国银行业监督管理委员会、中国证券监督管理委员会、中国保险监督管理委员会制定。"},{"i":11,"n":"第十一条","txt":"金融机构应当按照规定向中国反洗钱监测分析中心报告人民币、外币大额交易和可疑交易。 前款规定的具体实施办法由中国人民银行另行制定。"},{"i":12,"n":"第十二条","txt":"中国人民银行会同中国银行业监督管理委员会、中国证券监督管理委员会、中国保险监督管理委员会指导金融行业自律组织制定本行业的反洗钱工作指引。"},{"i":13,"n":"第十三条","txt":"金融机构在履行反洗钱义务过程中，发现涉嫌犯罪的，应当及时以书面形式向中国人民银行当地分支机构和当地公安机关报告。"},{"i":14,"n":"第十四条","txt":"金融机构及其工作人员应当依法协助、配合司法机关和行政执法机关打击洗钱活动。 金融机构的境外分支机构应当遵循驻在国家或者地区反洗钱方面的法律规定，协助配合驻在国家或者地区反洗钱机构的工作。"},{"i":15,"n":"第十五条","txt":"金融机构及其工作人员对依法履行反洗钱义务获得的客户身份资料和交易信息应当予以保密；非依法律规定，不得向任何单位和个人提供。 金融机构及其工作人员应当对报告可疑交易、配合中国人民银行调查可疑交易活动等有关反洗钱工作信息予以保密，不得违反规定向客户和其他人员提供。"},{"i":16,"n":"第十六条","txt":"金融机构及其工作人员依法提交大额交易和可疑交易报告，受法律保护。"},{"i":17,"n":"第十七条","txt":"金融机构应当按照中国人民银行的规定，报送反洗钱统计报表、信息资料以及稽核审计报告中与反洗钱工作有关的内容。"},{"i":18,"n":"第十八条","txt":"中国人民银行及其分支机构根据履行反洗钱职责的需要，可以采取下列措施进行反洗钱现场检查： （一）进入金融机构进行检查； （二）询问金融机构的工作人员，要求其对有关检查事项作出说明； （三）查阅、复制金融机构与检查事项有关的文件、资料，并对可能被转移、销毁、隐匿或者篡改的文件资料予以封存； （四）检查金融机构运用电子计算机管理业务数据的系统。 中国人民银行或者其分支机构实施现场检查前，应填写现场检查立项审批表，列明检查对象、检查内容、时间安排等内容，经中国人民银行或者其分支机构负责人批准后实施。 现场检查时，检查人员不得少于2人，并应出示执法证和检查通知书；检查人员少于2人或者未出示执法证和检查通知书的，金融机构有权拒绝检查。 现场检查后，中国人民银行或者其分支机构应当制作现场检查意见书，加盖公章，送达被检查机构。现场检查意见书的内容包括检查情况、检查评价、改进意见与措施。"},{"i":19,"n":"第十九条","txt":"中国人民银行及其分支机构根据履行反洗钱职责的需要，可以与金融机构董事、高级管理人员谈话，要求其就金融机构履行反洗钱义务的重大事项作出说明。"},{"i":20,"n":"第二十条","txt":"中国人民银行对金融机构实施现场检查，必要时将检查情况通报中国银行业监督管理委员会、中国证券监督管理委员会或者中国保险监督管理委员会。"},{"i":21,"n":"第二十一条","txt":"中国人民银行或者其省一级分支机构发现可疑交易活动需要调查核实的，可以向金融机构调查可疑交易活动涉及的客户账户信息、交易记录和其他有关资料，金融机构及其工作人员应当予以配合。 前款所称中国人民银行或者其省一级分支机构包括中国人民银行总行、上海总部、分行、营业管理部、省会（首府）城市中心支行、副省级城市中心支行。"},{"i":22,"n":"第二十二条","txt":"中国人民银行或者其省一级分支机构调查可疑交易活动，可以询问金融 机构的工作人员，要求其说明情况；查阅、复制被调查的金融机构客户的账户信息、交易记录和其他有关资料；对可能被转移、隐藏、篡改或者毁损的文件、资料，可以封存。 调查可疑交易活动时，调查人员不得少于2人，并出示执法证和中国人民银行或者其省一级分支机构出具的调查通知书。查阅、复制、封存被调查的金融机构客户的账户信息、交易记录和其他有关资料，应当经中国人民银行或者其省一级分支机构负责人批准。调查人员违反规定程序的，金融机构有权拒绝调查。 询问应当制作询问笔录。询问笔录应当交被询问人核对。记载有遗漏或者差错的，被询问人可以要求补充或者更正。被询问人确认笔录无误后，应当签名或者盖章；调查人员也应当在笔录上签名。 调查人员封存文件、资料，应当会同在场的金融机构工作人员查点清楚，当场开列清单一式二份，由调查人员和在场的金融机构工作人员签名或"},{"i":23,"n":"第二十三条","txt":"经调查仍不能排除洗钱嫌疑的，应当立即向有管辖权的侦查机关报案。对客户要求将调查所涉及的账户资金转往境外的，金融机构应当立即向中国人民银行当地分支机构报告。经中国人民银行负责人批准，中国人民银行可以采取临时冻结措施，并以书面形式通知金融机构，金融机构接到通知后应当立即予以执行。 侦查机关接到报案后，认为需要继续冻结的，金融机构在接到侦查机关继续冻结的通知后，应当予以配合。侦查机关认为不需要继续冻结的，中国人民银行在接到侦查机关不需要继续冻结的通知后，应当立即以书面形式通知金融机构解除临时冻结。 临时冻结不得超过48小时。金融机构在按照中国人民银行的要求采取临时冻结措施后48小时内，未接到侦查机关继续冻结通知的，应当立即解除临时冻结。"},{"i":24,"n":"第二十四条","txt":"中国人民银行及其分支机构从事反洗钱工作的人员有下列行为之一的，依法给予行政处分： （一）违反规定进行检查、调查或者采取临时冻结措施的； （二）泄露因反洗钱知悉的国家秘密、商业秘密或者个人隐私的； （三）违反规定对有关机构和人员实施行政处罚的； （四）其他不依法履行职责的行为。"},{"i":25,"n":"第二十五条","txt":"金融机构违反本规定的，由中国人民银行或者其地市中心支行以上分支机构按照《中华人民共和国反洗钱法》第三十一条、第三十二条的规定进行处罚；区别不同情形，建议中国银行业监督管理委员会、中国证券监督管理委员会或者中国保险监督管理委员会采取下列措施： （一）责令金融机构停业整顿或者吊销其经营许可证； （二）取消金融机构直接负责的董事、高级管理人员和其他直接责任人员的任职资格、禁止其从事有关金融行业工作； （三）责令金融机构对直接负责的董事、高级管理人员和其他直接责任人员给予纪律处分。 中国人民银行县（市）支行发现金融机构违反本规定的，应报告其上一级分支机构，由该分支机构按照前款规定进行处罚或者提出建议。"},{"i":26,"n":"第二十六条","txt":"中国人民银行和其地市中心支行以上分支机构对金融机构违反本规定的行为给予行政处罚的，应当遵守《中国人民银行行政处罚程序规定》的有关规定。"},{"i":27,"n":"第二十七条","txt":"本规定自2007年1月1日起施行。2003年1月3日中国人民银行发布的《金融机构反洗钱规定》同时废止。"}],"jinrongjigoudaejiaoyihekeyijiaoyibaogaoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范金融机构大额交易和可疑交易报告行为，根据《中华人民共和国反洗钱法》、《中华人民共和国中国人民银行法》、《中华人民共和国反恐怖主义法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内依法设立的下列金融机构： （一）政策性银行、商业银行、农村合作银行、农村信用社、村镇银行。 （二）证券公司、期货公司、基金管理公司。 （三）保险公司、保险资产管理公司、保险专业代理公司、保险经纪公司。 （四）信托公司、金融资产管理公司、企业集团财务公司、金融租赁公司、汽车金融公司、消费金融公司、货币经纪公司、贷款公司。 （五）中国人民银行确定并公布的应当履行反洗钱义务的从事金融业务的其他机构。"},{"i":3,"n":"第三条","txt":"金融机构应当履行大额交易和可疑交易报告义务，向中国反洗钱监测分析中心报送大额交易和可疑交易报告，接受中国人民银行及其分支机构的监督、检查。"},{"i":4,"n":"第四条","txt":"金融机构应当通过其总部或者总部指定的一个机构，按本办法规定的路径和方式提交大额交易和可疑交易报告。"},{"i":5,"n":"第五条","txt":"金融机构应当报告下列大额交易： （一）当日单笔或者累计交易人民币5万元以上（含5万元）、外币等值1万美元以上（含1万美元）的现金缴存、现金支取、现金结售汇、现钞兑换、现金汇款、现金票据解付及其他形式的现金收支。 （二）非自然人客户银行账户与其他的银行账户发生当日单笔或者累计交易人民币200万元以上（含200万元）、外币等值20万美元以上（含20万美元）的款项划转。 （三）自然人客户银行账户与其他的银行账户发生当日单笔或者累计交易人民币50万元以上（含50万元）、外币等值10万美元以上（含10万美元）的境内款项划转。 （四）自然人客户银行账户与其他的银行账户发生当日单笔或者累计交易人民币20万元以上（含20万元）、外币等值1万美元以上（含1万美元）的跨境款项划转。 累计交易金额以客户为单位，按资金收入或者支出单边累计计算并报告。中国人民银行另有规定的除外。 中国人民银行根据需要可以调整本"},{"i":6,"n":"第六条","txt":"对同时符合两项以上大额交易标准的交易，金融机构应当分别提交大额交易报告。"},{"i":7,"n":"第七条","txt":"对符合下列条件之一的大额交易，如未发现交易或行为可疑的，金融机构可以不报告： （一）定期存款到期后，不直接提取或者划转，而是本金或者本金加全部或者部分利息续存入在同一金融机构开立的同一户名下的另一账户。 活期存款的本金或者本金加全部或者部分利息转为在同一金融机构开立的同一户名下的另一账户内的定期存款。 定期存款的本金或者本金加全部或者部分利息转为在同一金融机构开立的同一户名下的另一账户内的活期存款。 （二）自然人实盘外汇买卖交易过程中不同外币币种间的转换。 （三）交易一方为各级党的机关、国家权力机关、行政机关、司法机关、军事机关、人民政协机关和人民解放军、武警部队，但不包含其下属的各类企事业单位。 （四）金融机构同业拆借、在银行间债券市场进行的债券交易。 （五）金融机构在黄金交易所进行的黄金交易。 （六）金融机构内部调拨资金。 （七）国际金融组织和外国政府贷款转贷业务项下的交易。 （八"},{"i":8,"n":"第八条","txt":"金融机构应当在大额交易发生之日起5个工作日内以电子方式提交大额交易报告。"},{"i":9,"n":"第九条","txt":"下列金融机构与客户进行金融交易并通过银行账户划转款项的，由银行机构按照本办法规定提交大额交易报告： （一）证券公司、期货公司、基金管理公司。 （二）保险公司、保险资产管理公司、保险专业代理公司、保险经纪公司。 （三）信托公司、金融资产管理公司、企业集团财务公司、金融租赁公司、汽车金融公司、消费金融公司、货币经纪公司、贷款公司。"},{"i":10,"n":"第十条","txt":"客户通过在境内金融机构开立的账户或者境内银行卡所发生的大额交易，由开立账户的金融机构或者发卡银行报告；客户通过境外银行卡所发生的大额交易，由收单机构报告；客户不通过账户或者银行卡发生的大额交易，由办理业务的金融机构报告。"},{"i":11,"n":"第十一条","txt":"金融机构发现或者有合理理由怀疑客户、客户的资金或者其他资产、客户的交易或者试图进行的交易与洗钱、恐怖融资等犯罪活动相关的，不论所涉资金金额或者资产价值大小，应当提交可疑交易报告。"},{"i":12,"n":"第十二条","txt":"金融机构应当制定本机构的交易监测标准，并对其有效性负责。交易监测标准包括并不限于客户的身份、行为，交易的资金来源、金额、频率、流向、性质等存在异常的情形，并应当参考以下因素： （一）中国人民银行及其分支机构发布的反洗钱、反恐怖融资规定及指引、风险提示、洗钱类型分析报告和风险评估报告。 （二）公安机关、司法机关发布的犯罪形势分析、风险提示、犯罪类型报告和工作报告。 （三）本机构的资产规模、地域分布、业务特点、客户群体、交易特征，洗钱和恐怖融资风险评估结论。 （四）中国人民银行及其分支机构出具的反洗钱监管意见。 （五）中国人民银行要求关注的其他因素。"},{"i":13,"n":"第十三条","txt":"金融机构应当定期对交易监测标准进行评估，并根据评估结果完善交易监测标准。如发生突发情况或者应当关注的情况的，金融机构应当及时评估和完善交易监测标准。"},{"i":14,"n":"第十四条","txt":"金融机构应当对通过交易监测标准筛选出的交易进行人工分析、识别，并记录分析过程；不作为可疑交易报告的，应当记录分析排除的合理理由；确认为可疑交易的，应当在可疑交易报告理由中完整记录对客户身份特征、交易特征或行为特征的分析过程。"},{"i":15,"n":"第十五条","txt":"金融机构应当在按本机构可疑交易报告内部操作规程确认为可疑交易后，及时以电子方式提交可疑交易报告，最迟不超过5个工作日。"},{"i":16,"n":"第十六条","txt":"既属于大额交易又属于可疑交易的交易，金融机构应当分别提交大额交易报告和可疑交易报告。"},{"i":17,"n":"第十七条","txt":"可疑交易符合下列情形之一的，金融机构应当在向中国反洗钱监测分析中心提交可疑交易报告的同时，以电子形式或书面形式向所在地中国人民银行或者其分支机构报告，并配合反洗钱调查： （一）明显涉嫌洗钱、恐怖融资等犯罪活动的。 （二）严重危害国家安全或者影响社会稳定的。 （三）其他情节严重或者情况紧急的情形。"},{"i":18,"n":"第十八条","txt":"金融机构应当对下列恐怖活动组织及恐怖活动人员名单开展实时监测，有合理理由怀疑客户或者其交易对手、资金或者其他资产与名单相关的，应当在立即向中国反洗钱监测分析中心提交可疑交易报告的同时，以电子形式或书面形式向所在地中国人民银行或者其分支机构报告，并按照相关主管部门的要求依法采取措施。 （一）中国政府发布的或者要求执行的恐怖活动组织及恐怖活动人员名单。 （二）联合国安理会决议中所列的恐怖活动组织及恐怖活动人员名单。 （三）中国人民银行要求关注的其他涉嫌恐怖活动的组织及人员名单。 恐怖活动组织及恐怖活动人员名单调整的，金融机构应当立即开展回溯性调查，并按前款规定提交可疑交易报告。 法律、行政法规、规章对上述名单的监控另有规定的，从其规定。"},{"i":19,"n":"第十九条","txt":"金融机构应当根据本办法制定大额交易和可疑交易报告内部管理制度和操作规程，对本机构的大额交易和可疑交易报告工作做出统一要求，并对分支机构、附属机构大额交易和可疑交易报告制度的执行情况进行监督管理。 金融机构应当将大额交易和可疑交易报告制度向中国人民银行或其总部所在地的中国人民银行分支机构报备。"},{"i":20,"n":"第二十条","txt":"金融机构应当设立专职的反洗钱岗位，配备专职人员负责大额交易和可疑交易报告工作，并提供必要的资源保障和信息支持。"},{"i":21,"n":"第二十一条","txt":"金融机构应当建立健全大额交易和可疑交易监测系统，以客户为基本单位开展资金交易的监测分析，全面、完整、准确地采集各业务系统的客户身份信息和交易信息，保障大额交易和可疑交易监测分析的数据需求。"},{"i":22,"n":"第二十二条","txt":"金融机构应当按照完整准确、安全保密的原则，将大额交易和可疑交易报告、反映交易分析和内部处理情况的工作记录等资料自生成之日起至少保存5年。 保存的信息资料涉及正在被反洗钱调查的可疑交易活动，且反洗钱调查工作在前款规定的最低保存期届满时仍未结束的，金融机构应将其保存至反洗钱调查工作结束。"},{"i":23,"n":"第二十三条","txt":"金融机构及其工作人员应当对依法履行大额交易和可疑交易报告义务获得的客户身份资料和交易信息，对依法监测、分析、报告可疑交易的有关情况予以保密，不得违反规定向任何单位和个人提供。"},{"i":24,"n":"第二十四条","txt":"金融机构违反本办法的，由中国人民银行或者其地市中心支行以上分支机构按照《中华人民共和国反洗钱法》第三十一条、第三十二条的规定予以处罚。"},{"i":25,"n":"第二十五条","txt":"非银行支付机构、从事汇兑业务和基金销售业务的机构报告大额交易和可疑交易适用本办法。银行卡清算机构、资金清算中心等从事清算业务的机构应当按照中国人民银行有关规定开展交易监测分析、报告工作。 本办法所称非银行支付机构，是指根据《非金融机构支付服务管理办法》（中国人民银行令〔2010〕第2号发布）规定取得《支付业务许可证》的支付机构。 本办法所称资金清算中心，包括城市商业银行资金清算中心、农信银资金清算中心有限责任公司及中国人民银行确定的其他资金清算中心。"},{"i":26,"n":"第二十六条","txt":"本办法所称非自然人，包括法人、其他组织和个体工商户。"},{"i":27,"n":"第二十七条","txt":"金融机构应当按照本办法所附的大额交易和可疑交易报告要素要求（要素内容见附件），制作大额交易报告和可疑交易报告的电子文件。具体的报告格式和填报要求由中国人民银行另行规定。"},{"i":28,"n":"第二十八条","txt":"中国反洗钱监测分析中心发现金融机构报送的大额交易报告或者可疑交易报告内容要素不全或者存在错误的，可以向提交报告的金融机构发出补正通知，金融机构应当在接到补正通知之日起5个工作日内补正。"},{"i":29,"n":"第二十九条","txt":"本办法由中国人民银行负责解释。"},{"i":30,"n":"第三十条","txt":"本办法自2017年7月1日起施行。中国人民银行2006年11月14日发布的《金融机构大额交易和可疑交易报告管理办法》（中国人民银行令〔2006〕第2号）和2007年6月11日发布的《金融机构报告涉嫌恐怖融资的可疑交易管理办法》（中国人民银行令〔2007〕第1号）同时废止。中国人民银行此前发布的大额交易和可疑交易报告的其他规定，与本办法不一致的，以本办法为准。"}],"jinrongjigoukehushouyisuoyourenshibieguanlibanfa":[{"i":1,"n":"第一条","txt":"为了预防和遏制洗钱和恐怖融资活动，落实金融机构客户尽职调查要求，规范受益所有人识别核实工作，根据《中华人民共和国反洗钱法》、《中华人民共和国反恐怖主义法》等法律规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于《金融机构客户尽职调查和客户身份资料及交易记录保存管理办法》（中国人民银行 国家金融监督管理总局 中国证券监督管理委员会令〔2025〕第11号发布）所规定的应当履行客户尽职调查义务的机构。"},{"i":3,"n":"第三条","txt":"金融机构在开展客户尽职调查时，应当根据客户的组织形式和风险状况，识别并采取合理措施核实非自然人客户的受益所有人，以增强对客户及其风险状况的了解，并将识别核实结果充分运用于洗钱风险管理。"},{"i":4,"n":"第四条","txt":"金融机构应当按照以下原则开展受益所有人识别核实工作： （一）基于风险原则。金融机构应当按照基于风险的原则，采取与风险程度相匹配的差异化措施识别核实客户的受益所有人。 （二）合理性原则。金融机构应当勤勉尽责，通过合理的手段了解客户的所有权和控制权结构，识别并采取合理措施核实受益所有人，从而确信其了解客户的受益所有人身份信息和权利状况信息。 （三）可靠性原则。金融机构应当通过来源可靠的佐证材料、数据或信息识别核实受益所有人，并综合考虑这些不同来源的佐证材料、数据或信息相互印证以后的整体可靠性。 金融机构不得仅通过查询中国人民银行受益所有人信息查询管理系统（以下简称受益所有人信息查询管理系统）的方式获取受益所有人信息，或者直接通过批量化、自动化等辅助手段代替必要的风险判断和受益所有人识别核实。"},{"i":5,"n":"第五条","txt":"金融机构开展受益所有人识别核实工作，应当平衡好管理洗钱风险与优化金融服务的关系，应当采取与风险状况相匹配的措施，不得采取明显超过必要限度的或者“一刀切”式的措施。"},{"i":6,"n":"第六条","txt":"中国人民银行可以通过发布监管指引、指南、案例等方式，指导金融机构开展受益所有人识别核实工作。"},{"i":7,"n":"第七条","txt":"金融机构对开展受益所有人识别核实工作过程中获取的有关信息，应当依法予以保密。"},{"i":8,"n":"第八条","txt":"符合下列条件之一的自然人，为法人、非法人组织的受益所有人：  （一）通过直接方式或者间接方式最终拥有法人、非法人组织25%以上股权、股份或者合伙权益； （二）虽未满足第一项标准，但最终享有法人、非法人组织25%以上收益权、表决权； （三）虽未满足第一项标准，但单独或者联合对法人、非法人组织进行实际控制。 前款第三项所称实际控制包括但不限于通过协议约定、关系密切的人等方式实施控制，例如决定法定代表人、董事、监事、高级管理人员或者执行事务合伙人的任免，决定重大经营、管理决策的制定或者执行，决定财务收支，长期实际支配使用重要资产或者主要资金等。 如不存在第一款规定的三种情形的，法人、非法人组织中负责日常经营管理的人员应被认定为受益所有人。"},{"i":9,"n":"第九条","txt":"对于国内法人、非法人组织的分支机构，金融机构一般应当将该法人、非法人组织的受益所有人认定为该分支机构的受益所有人。如果法人、非法人组织已经是金融机构的客户，且金融机构已按照规定对其开展客户尽职调查的，金融机构可以重复利用已有的受益所有人信息。 对于外国公司分支机构，金融机构除应当按照本办法第八条识别该分支机构所属外国公司的受益所有人外，还应当将该分支机构的至少一名高级管理人员认定为受益所有人。"},{"i":10,"n":"第十条","txt":"对于下列法人、非法人组织，金融机构可以免于识别其受益所有人： （一）机关法人及代表其行使职权的派出机构、临时性机构，包括政党机关、人大机关、政协机关、行政机关、监察机关、司法机关、军事机关等及代表其行使职权的派出机构、临时性机构； （二）事业单位； （三）基层群众性自治组织法人，包括居民委员会和村民委员会； （四）农村集体经济组织法人； （五）政府间国际组织、外国政府、外国政府驻华使领馆及办事处等组织及机构； （六）中国人民银行规定的其他法人、非法人组织。"},{"i":11,"n":"第十一条","txt":"对于下列法人、非法人组织，金融机构在充分评估其洗钱和恐怖融资风险的基础上，可以采取与风险状况相匹配的简化识别措施： （一）对于不具有法人资格的专业服务机构，如律师事务所、会计师事务所、资产评估机构、合伙专利代理机构等，无较高风险情形的，可以将机构负责人认定为受益所有人； （二）对于城镇农村的合作经济组织法人，包括农民专业合作社和农民专业合作社联合社，参照本办法第八条识别受益所有人，无较高风险情形的，可以将法定代表人认定为受益所有人； （三）对于个人独资企业，无较高风险情形的，可以将投资人认定为受益所有人； （四）对于合格境外投资者，无较高风险情形的，可以将法定代表人、授权代表或者合格境外投资者业务负责人认定为受益所有人； （五）对于外国企业常驻代表机构，参照本办法第九条第二款识别受益所有人，无较高风险情形的，可以根据风险状况采取简化的识别措施； （六）对于社会团体、基金会、社会服务机构"},{"i":12,"n":"第十二条","txt":"信托的受益所有人包括： （一）信托当事人，即委托人、受托人、受益人、监察人（如有）； （二）对信托行使最终有效控制的其他自然人。 前款第一项所列信托当事人为非自然人时，金融机构应当逐一、逐层深入，追溯到对信托行使最终有效控制的自然人，并将其认定为受益所有人。前款第二项所称最终有效控制包括但不限于处分信托财产、决定信托财产的投资、决定信托分配方案、变更或者终止信托、变更受益人（或者受益人的条件）、任命或者变更受托人。 对于信托设立时或者信托存续期间未列出明确具体受益人的，金融机构应当识别并记录受益人的范围（如受益人的类别，或者指定权范围内的潜在受益人）。"},{"i":13,"n":"第十三条","txt":"金融机构为财富管理服务信托和公益慈善信托提供服务时，应当按照本办法第十二条的规定识别受益所有人。对于财富管理服务信托以外的其他资产服务信托，金融机构为其提供服务时，如果其所有权和控制权结构简单且洗钱和恐怖融资风险较低，可以采取简化措施识别受益所有人。 金融机构为民事信托和外国信托提供服务时，应当按照本办法第十二条的规定识别受益所有人。 信托公司在开展信托业务过程中聘请投资顾问、法律顾问、会计师等专业服务人员或者机构的，还应当获取并留存专业服务人员或者机构的基本信息。"},{"i":14,"n":"第十四条","txt":"对于资产管理信托等资产管理产品，金融机构应当按照基于风险原则，根据资产管理产品的具体情况，参照本办法第八条识别其受益所有人。 对于以金融机构为管理人或者受托人的资产管理产品，如果资产管理产品为公开募集或者发行，且按照有关规定进行备案或者登记的，如银行公募理财产品、公开发行的基金产品等，金融机构在提供资金托管等金融服务时，可以采取简化措施，将管理资产管理产品的自然人认定为受益所有人。 对前款规定以外的以金融机构为管理人或者受托人的其他资产管理产品，金融机构在提供资金托管等金融服务时，可在充分评估其洗钱和恐怖融资风险的基础上，根据风险状况确定受益所有人识别核实措施的程度和具体方式。对于低风险的资产管理产品，如针对企业年金、机关事业单位职业年金等设立的资产管理产品，金融机构可以采取简化措施，将管理资产管理产品的自然人认定为受益所有人。"},{"i":15,"n":"第十五条","txt":"信托公司作为信托受托人的，在其与银行、证券公司、期货公司等非信托金融机构建立业务关系时和业务存续期间，应当提供信托受益所有人相关的信息和材料。 对于财富管理服务信托以外的其他营业信托，银行、证券公司、期货公司等非信托金融机构为信托提供资金托管、证券经纪等金融服务时，能够确信信托公司反洗钱和反恐怖融资体系健全并能有效履行反洗钱和反恐怖融资义务的，可以采信信托公司提供的受益所有人信息。信托公司提供的受益所有人信息存在明显疑点，或者信托公司的受益所有人识别核实措施存在明显瑕疵的，银行、证券公司、期货公司等非信托金融机构可以要求信托公司重新识别核实受益所有人并提供相关信息和材料。 信托公司未配合提供必要信息和材料，或者出现严重违法、重大风险，或者暴露出明显的反洗钱和反恐怖融资体系性缺陷的，银行、证券公司、期货公司等非信托金融机构应当根据情形采取必要的洗钱风险管理措施。 信托公司之间开展信托业务"},{"i":16,"n":"第十六条","txt":"金融机构应当通过来源可靠的佐证材料、数据或信息了解非自然人客户的所有权和控制权结构，识别出客户的受益所有人，并根据风险状况采取合理措施核实其受益所有人信息。 上述佐证材料、数据或信息可以来源于政府部门，也可以来源于其他渠道，如公开信息、金融机构发现的信息、客户自己提供的信息等。"},{"i":17,"n":"第十七条","txt":"金融机构应当结合客户所提供的受益所有人信息，以及以下佐证材料、数据或信息，了解客户的所有权和控制权结构，进而识别出客户的受益所有人： （一）法人的相关佐证材料、数据或信息，包括但不限于营业执照（登记证书）或者其他可以验证法人身份的文件，章程，董事、高级管理人员和股东名单、股东持股数量以及持股类型（包括相关的投票权类型）； （二）合伙企业的相关佐证材料、数据或信息，包括但不限于营业执照或者其他可以验证合伙企业身份的文件，合伙协议，合伙人名单、各合伙人承担责任的方式以及合伙人持有的合伙权益比例； （三）外国公司分支机构的相关佐证材料、数据或信息，包括本款第一项所规定的外国公司的信息和资料，以及外国公司分支机构的营业执照和高级管理人员信息等； （四）信托的相关佐证材料、数据或信息，包括但不限于信托合同、成立公告（如有）、信托登记证明文书（如有）或者类似书面文件，信托受益权在受托人处的登记记录"},{"i":18,"n":"第十八条","txt":"金融机构应当识别、留存的客户受益所有人信息包括以下信息： （一）受益所有人的身份信息，包括姓名、性别、国籍、出生日期以及身份证件或者身份证明文件的种类、号码、有效期限； （二）受益所有人的权利状况信息，包括受益所有权关系类型以及形成时间、终止时间（如有）。 对于透明度较高、信息披露充分的客户，如上市公司和经官方信息验证并确认属于国有独资公司、国有控股公司、全民所有制企业的，金融机构识别、留存的受益所有人身份信息应当至少包括姓名、性别、国籍、出生年月以及可以用于身份识别的照片。 存在本办法第八条第一款第一项规定情形的，受益所有人的权利状况信息还应包括受益所有人持有股权、股份或者合伙权益的比例；存在本办法第八条第一款第二项规定情形的，受益所有人的权利状况信息还应当包括受益所有人拥有收益权、表决权的比例；存在本办法第八条第一款第三项规定情形的，受益所有人的权利状况信息还应当包括受益所有人实际"},{"i":19,"n":"第十九条","txt":"金融机构应当按照基于风险原则，采取合理措施核实所识别出的受益所有人信息。 对于受益所有人身份信息的真实性，应当通过我国政府公开渠道核实，或者通过外国政府机构、国际组织等官方认证的信息核实；无法通过上述渠道核实的，可以通过受益所有人有效身份证件或者其他身份证明文件的原件或者复印件、影印件，并辅以客户补充提供的其他资料进行核实。对于市场透明度较高的客户，如上市公司和经官方信息验证并确认属于国有独资公司、国有控股公司、全民所有制企业的，金融机构可以通过官方公开信息核实受益所有人的姓名、性别、国籍、出生年月和照片。 对于受益所有人的权利状况，应当以客户提供的佐证材料、数据或信息为基础，必要时结合政府部门信息、公开信息以及金融机构发现的信息等多渠道信息进行核实，综合判断其权利状况与客户的所有权和控制权结构、风险状况是否相符合，以提升受益所有人信息的准确性。客户及其行为确属低风险情形的，金融机构可"},{"i":20,"n":"第二十条","txt":"金融机构识别、核实客户的受益所有人时，存在下列特定情形的，应当根据情形采取相应加强措施： （一）存在特定风险，如客户或者交易来自高风险国家或者地区； （二）客户所有权或者控制权结构复杂，如所有权结构涉及境外持股且无法核实登记注册信息，存在循环嵌套、交叉持股，存在协议控制、代持； （三）客户所有权或者控制权出现异常变化，如客户频繁更换法定代表人、高级管理人员、受益所有人，且无合理理由； （四）金融机构先前获得的受益所有人信息真实性、可靠性存疑的，如金融机构发现存在本办法第二十八条规定的重大差异情形； （五）有合理理由怀疑客户及其交易涉嫌洗钱或恐怖融资的。"},{"i":21,"n":"第二十一条","txt":"存在第二十条规定的特定情形时，金融机构应当根据情形采取相匹配的以下一种或者多种加强措施： （一）进一步获取受益所有人更为全面的身份信息，包括姓名、性别、国籍、出生日期、经常居住地或者工作单位地址、联系方式以及身份证件或者身份证明文件的种类、号码、有效期限; （二）通过额外的独立、可靠信息进一步验证客户的所有权和控制权情况； （三）要求客户补充提供相关证明资料，如代持协议及类似具有法律效力的文件； （四）回访客户，必要时对客户进行实地走访，进一步了解客户的所有权和控制权情况、财产与资金来源、建立业务关系的目的和性质等； （五）加强客户交易监测，关注与非股东、企业员工及业务伙伴等其他人的资金往来，进一步了解业务关系的目的和性质； （六）采取比本办法第八条更严格的识别标准，如将股权、股份、合伙权益识别标准的阈值设为10%； （七）提高对客户及其受益所有人信息审核和更新的频率； （八）与客户建"},{"i":22,"n":"第二十二条","txt":"金融机构发现自然人客户行为或者交易出现较高洗钱或者恐怖融资风险情形时，应当视情形筛查该自然人作为受益所有人在本机构的全部非自然人客户，并进行关联分析，同时采取必要的客户尽职调查或者洗钱风险管理措施。"},{"i":23,"n":"第二十三条","txt":"金融机构在核实受益所有人过程中，对于符合《受益所有人信息管理办法》（中国人民银行 国家市场监督管理总局令〔2024〕第3号发布）第二条规定的客户，应当将识别出的受益所有人信息与受益所有人信息查询管理系统中保存的受益所有人备案信息进行查询核对。"},{"i":24,"n":"第二十四条","txt":"金融机构与客户业务关系存续期间，应当持续关注并评估客户整体状况及交易情况，当出现以下情形时，金融机构应当审核并在必要时更新受益所有人信息： （一）非自然人客户的股权（合伙权益）、收益权、表决权、控制权发生重大变化可能影响受益所有权的； （二）非自然人客户的法定代表人、董事、高级管理人员发生重大变化可能影响受益所有权的； （三）信托的当事人发生变化的，如受益人的范围发生变化、受益人的资格丧失或者被确定；   （四）对非自然人客户采取持续尽职调查措施且确需对受益所有人再次进行识别或核实的；   （五）出现可能影响受益所有权的其他情形。"},{"i":25,"n":"第二十五条","txt":"金融机构应当根据本办法准确判断非自然人客户是否符合采取简化或者豁免措施的条件。无法作出准确判断的，金融机构不得采取简化或者豁免措施；非自然人客户出现第二十条规定情形的，不得采取简化或者豁免措施。"},{"i":26,"n":"第二十六条","txt":"金融机构将识别出的受益所有人信息与受益所有人信息查询管理系统保存的备案信息进行查询核对时，发现受益所有人信息错误、不一致或者不完整的，应当按照规定对差异情况进行反馈，以准确核实受益所有人。 金融机构应当建立健全差异反馈制度，明确差异分析、判断和报告工作流程以及相关工作要求，有效处理并反馈受益所有人信息查询核对结果。"},{"i":27,"n":"第二十七条","txt":"金融机构查询核对后发现差异的，应当与客户进行必要的沟通、核实。金融机构有合理理由认为由于自身识别不准确而导致差异的，应当更正其识别的受益所有人信息。金融机构有合理理由认为由于备案信息不准确而导致差异且差异重大的，应当在发现差异之日起30个工作日内通过受益所有人信息查询管理系统提交差异报告，记录并留存报告的理由、差异确认的过程，并提供相关佐证材料。 金融机构查询核对受益所有人信息发现重大差异的，在确保洗钱和恐怖融资风险可控的情况下，金融机构可以先与客户建立或者维持业务关系。 差异报告要素内容、报告格式和填报要求由中国人民银行另行规定。"},{"i":28,"n":"第二十八条","txt":"金融机构查询核对后，存在以下情形之一的，属于重大差异： （一）受益所有人不匹配，例如发现受益所有人信息查询管理系统保存的受益所有人多出、遗漏或者存在其他不一致且影响识别受益所有人的； （二）受益所有人身份的关键信息要素不一致，如对于同一受益所有人，发现受益所有人信息查询管理系统保存的人员姓名、性别、国籍、出生日期以及身份证件或者身份证明文件种类、同一身份证件或者身份证明文件的号码存在不一致； （三）受益所有人的权利状况信息存在重大不一致，例如对于同一受益所有人，发现受益所有人信息查询管理系统保存的股权（合伙权益）比例、收益权比例或者表决权比例，实际控制的方式和内容，担任的职务等存在不一致且影响受益所有权关系类型的最终认定，或者受益所有权形成、终止时间出现年月差异的； （四）影响识别受益所有人的其他实质性差异。"},{"i":29,"n":"第二十九条","txt":"金融机构查询核对后，存在以下情形之一的，属于非重大差异，金融机构无需提交差异报告： （一）对于同一受益所有人，因拼写、缩写等原因导致非汉字姓名书写不一致； （二）受益所有人的权利状况信息存在非重大不一致，例如对于同一受益所有人，发现受益所有人信息查询管理系统保存的股权（合伙权益）比例、收益权比例或者表决权比例，实际控制的方式和内容，担任的职务等存在不一致，但不影响受益所有权关系类型的最终认定的； （三）金融机构采用比本办法第八条更严格的受益所有人识别标准，导致信息不一致，例如将持有法人或非法人组织股权、股份、合伙权益、表决权或者收益权比例小于25%的自然人识别为客户的受益所有人； （四）不影响识别受益所有人的其他差异。 金融机构判断为非重大差异的，应当自发现差异之日起30个工作日内记录信息比对和分析核实的情况、不报告的原因以及采取的措施，同时应当向客户提示相关差异情况。"},{"i":30,"n":"第三十条","txt":"当金融机构将识别出的受益所有人信息与受益所有人信息查询管理系统保存的备案信息进行查询核对时，如果发现客户应当备案但未备案受益所有人信息，应当采取适当形式与客户进行沟通，提示其备案受益所有人信息，客户仍未备案的，应当报送差异报告。"},{"i":31,"n":"第三十一条","txt":"金融机构开展差异分析时，发现与洗钱或者恐怖融资等犯罪活动相关的，应当按照规定报送可疑交易报告。 既属于应提交差异报告又属于应提交可疑交易报告情形的，金融机构应当分别提交差异报告和可疑交易报告，提交的差异报告不得提及可疑交易报告报送情况。"},{"i":32,"n":"第三十二条","txt":"金融机构有下列情形之一的，由中国人民银行或者其设区的市级以上派出机构依照《中华人民共和国反洗钱法》第五十三条的规定责令限期改正，可以给予警告或者处二十万元以下罚款： （一）识别核实受益所有人所依据的佐证材料、数据或者信息可靠性或者充分性明显不足的； （二）识别核实出受益所有人的理由明显不合理的； （三）未按规定在客户业务关系存续期间审核或者更新受益所有人信息的； （四）发现或者应当发现本办法第二十条所规定情形，但未采取本办法第二十一条第一款所规定相应措施的，或者所采取措施明显不合理的； （五）未按规定将识别出的受益所有人信息与受益所有人信息查询管理系统中保存的受益所有人备案信息进行查询核对的； （六）未在规定时限内完成客户受益所有人识别核实工作的； （七）其他违反受益所有人识别核实要求的。"},{"i":33,"n":"第三十三条","txt":"金融机构有下列情形之一的，属于《中华人民共和国反洗钱法》第五十三条所规定的情节严重情形，由中国人民银行或者其设区的市级以上派出机构依照《中华人民共和国反洗钱法》第五十三条的规定处二十万元以上两百万元以下罚款：  （一）未开展或者未实质开展受益所有人识别核实工作的； （二）采取的受益所有人识别简化措施、豁免措施与其风险明显不匹配的; （三）存在本办法第三十二条所规定的违法行为，综合考虑金融机构的经营规模、勤勉尽责程度、危害程度及整改情况等因素，认定为情节严重的；  （四）其他情节严重的情形。"},{"i":34,"n":"第三十四条","txt":"金融机构违反本办法第二十一条第二款或者第二十二条的规定，应当采取但未采取相应的洗钱风险管理措施，或者洗钱风险管理措施明显不当的，依照《中华人民共和国反洗钱法》第五十四条的规定予以处罚。"},{"i":35,"n":"第三十五条","txt":"金融机构有下列情形之一的，由中国人民银行或者其设区的市级以上派出机构依照《中华人民共和国反洗钱法》第五十三条的规定责令限期改正，可以给予警告或者处五万元以下罚款： （一）查询核对后，应发现但未发现明显的重大差异的； （二）发现重大差异，但未按规定时限提交差异报告的； （三）提交的差异报告分析理由明显不完整、不充分、缺乏说服力，或者佐证材料明显不足以支持分析结论，经督促后，仍然反复出现同类问题的；  （四）对于非重大差异提交差异报告，经督促后，仍然反复出现同类问题的； （五）未记录非重大差异信息比对和分析核实的情况、不报告的理由的； （六）未按规定留存反映差异分析和内部处理情况的工作记录等资料的； （七）未有效履行本办法规定的其他差异反馈义务的。"},{"i":36,"n":"第三十六条","txt":"金融机构存在本办法第三十二条至第三十五条规定的违法情形是由于相应的内部控制制度缺陷造成的，应当对内部控制制度的缺陷依照《中华人民共和国反洗钱法》第五十二条的规定予以处罚。"},{"i":37,"n":"第三十七条","txt":"有下列情形之一的，可以根据情况从轻或者减轻本办法所规定的处罚： （一）持续提交高质量差异报告，对受益所有人备案信息核实有直接帮助； （二）协助客户准确备案或者更新受益所有人备案信息，取得显著成效； （三）持续准确识别复杂情形下的受益所有人，并对提升行业受益所有人识别水平具有重大借鉴价值； （四）其他对国家提高受益所有人信息准确性作出重大贡献的情形。"},{"i":38,"n":"第三十八条","txt":"本办法要求金融机构识别并采取合理措施核实非自然人客户的受益所有人，其中涉及的非自然人客户不包括个体工商户。"},{"i":39,"n":"第三十九条","txt":"金融机构对本办法实施前已经建立业务关系或者进行交易的存量非自然人客户，未满足本办法有关受益所有人识别标准或者识别核实要求的，应当自本办法施行之日起6个月内完成较高风险以上存量客户受益所有人识别核实工作，自本办法施行之日起2年内完成全部存量客户的受益所有人识别核实工作。对于存量长期不动户（如银行机构久悬户、睡眠户），或者已被采取暂停非柜面交易等严格限制措施的客户，可将受益所有人识别核实工作延长至客户申请激活账户或者办理业务时再开展。"},{"i":40,"n":"第四十条","txt":"本办法由中国人民银行负责解释。"},{"i":41,"n":"第四十一条","txt":"本办法自2026年1月20日起施行。《中国人民银行关于加强反洗钱客户身份识别有关工作的通知》（银发〔2017〕235号）、《中国人民银行关于进一步做好受益所有人身份识别工作有关问题的通知》（银发〔2018〕164号）同时废止。本办法施行前有关受益所有人识别核实规定与本办法不一致的，按照本办法执行。"}],"jinrongjigoukehujinzhidiaochahekehushenfenziliaoji9cca63":[{"i":1,"n":"第一条","txt":"为了预防和遏制洗钱和恐怖融资活动，规范金融机构客户尽职调查、客户身份资料及交易记录保存行为，维护国家安全和金融秩序，根据《中华人民共和国反洗钱法》、《中华人民共和国反恐怖主义法》等法律规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在境内设立的下列机构，履行本办法规定的金融机构反洗钱义务： （一）政策性银行、商业银行、农村合作银行、农村信用合作社、村镇银行； （二）证券公司、期货公司、证券投资基金管理公司； （三）保险公司、保险资产管理公司； （四）信托公司、金融资产管理公司、企业集团财务公司、金融租赁公司、汽车金融公司、消费金融公司、货币经纪公司、理财公司； （五）非银行支付机构； （六）中国人民银行确定并公布的从事金融业务的其他机构。"},{"i":3,"n":"第三条","txt":"金融机构应当勤勉尽责，遵循“了解你的客户”的原则，识别并采取合理措施核实客户及其受益所有人身份，根据客户特征和交易活动的性质、风险状况，采取相应的尽职调查措施。在业务关系存续期间，应当持续关注并评估客户整体状况及交易情况，了解客户的洗钱、恐怖融资风险。涉及较高洗钱、恐怖融资风险的，应当采取相应的强化尽职调查措施，必要时可以采取与风险相匹配的洗钱风险管理措施。涉及较低洗钱、恐怖融资风险的，根据情形采取简化尽职调查措施。"},{"i":4,"n":"第四条","txt":"金融机构应当按照安全、准确、完整、保密的原则，妥善保存客户身份资料及交易记录，确保足以重现每笔交易，以提供客户尽职调查、监测分析交易、调查可疑交易活动以及查处洗钱、恐怖融资案件所需的信息。"},{"i":5,"n":"第五条","txt":"金融机构应当根据反洗钱和反恐怖融资相关法律及本办法规定，结合面临的洗钱和恐怖融资风险状况，建立健全客户尽职调查、客户身份资料及交易记录保存等方面的内部控制制度，定期审计、评估内部控制制度是否健全、有效，及时修改和完善相关制度。 金融机构应当合理设计业务流程和操作规范，以保证客户尽职调查、客户身份资料及交易记录保存制度有效执行。"},{"i":6,"n":"第六条","txt":"金融机构应当在总部层面对客户尽职调查、客户身份资料及交易记录保存工作作出统一部署或者安排，制定反洗钱和反恐怖融资信息共享制度和程序，以保证客户尽职调查、洗钱和恐怖融资风险管理工作有效开展。 金融机构应当对其分支机构执行客户尽职调查制度、客户身份资料及交易记录保存制度的情况进行管理。 金融机构应当要求其境外分支机构和附属机构在驻在国家或者地区法律规定允许的范围内，执行本办法的有关要求，驻在国家或者地区有更严格要求的，遵守其规定。如果本办法的要求比驻在国家或者地区的相关规定更为严格，但驻在国家或者地区法律禁止或者限制境外分支机构和附属机构实施本办法的，金融机构应当采取适当措施应对洗钱、恐怖融资风险，并向中国人民银行报告。"},{"i":7,"n":"第七条","txt":"有下列情形之一的，金融机构应当开展客户尽职调查： （一）与客户建立业务关系、为客户提供规定金额以上的一次性金融服务，包括单笔或者明显关联的累计交易； （二）有合理理由怀疑客户及其交易涉嫌洗钱或者恐怖融资； （三）对先前获得的客户身份资料的真实性、有效性、完整性存在疑问。 开展客户尽职调查应当采取下列尽职调查措施： （一）识别客户身份，并通过来源可靠、独立的相关材料、数据或者信息核实客户身份； （二）了解客户建立业务关系和交易的目的和性质，并根据风险状况获取相关信息； （三）对于洗钱、恐怖融资风险较高的情形，了解客户的资金来源和用途，并根据风险状况采取强化的尽职调查措施；对于涉及较低洗钱、恐怖融资风险的，根据情形采取简化客户尽职调查措施； （四）在业务关系存续期间，对客户采取持续的尽职调查措施，审查客户状况及其交易情况，以确认为客户提供的各类服务和交易符合金融机构对客户身份背景、业务需求"},{"i":8,"n":"第八条","txt":"金融机构不得为身份不明的客户提供服务或者与其进行交易，不得为客户开立匿名账户或者假名账户，不得为冒用他人身份的客户开立账户。"},{"i":9,"n":"第九条","txt":"政策性银行、商业银行、农村合作银行、农村信用合作社、村镇银行等金融机构和从事汇兑业务的机构在办理下列业务时，应当开展客户尽职调查，并登记客户身份基本信息，留存客户有效身份证件或者其他身份证明文件的复印件或者影印件： （一）以开立账户或者通过其他协议约定等方式与客户建立业务关系的； （二）为客户提供现金汇款、现钞兑换、票据兑付、实物贵金属买卖、销售各类金融产品等一次性金融服务且交易金额人民币5万元以上或者外币等值1万美元以上的。"},{"i":10,"n":"第十条","txt":"金融机构提供保管箱服务时，应当了解保管箱的实际使用人，登记实际使用人的姓名、联系方式、有效身份证件或者其他身份证明文件的种类、号码和有效期限，并留存实际使用人有效身份证件或者其他身份证明文件的复印件或者影印件。"},{"i":11,"n":"第十一条","txt":"证券公司、期货公司、证券投资基金管理公司以及其他从事基金销售业务的机构在为客户办理下列业务时，应当开展客户尽职调查，并登记客户身份基本信息，留存客户有效身份证件或者其他身份证明文件的复印件或者影印件： （一）经纪业务； （二）资产管理业务； （三）向客户销售各类金融产品且交易金额人民币5万元以上或者外币等值1万美元以上的； （四）融资融券、股票质押、约定购回等信用交易类业务； （五）场外衍生品交易等柜台业务； （六）承销与保荐、上市公司并购重组财务顾问、公司债券受托管理、非上市公众公司推荐、资产证券化等业务； （七）中国人民银行和中国证券监督管理委员会规定的应当开展客户尽职调查的其他证券业务。"},{"i":12,"n":"第十二条","txt":"保险公司在与客户订立人寿保险合同和其他具有投资性质的保险合同时，应当开展客户尽职调查，确认投保人和被保险人之间的关系，以及被保险人和受益人之间的关系，登记投保人身份基本信息，并留存投保人有效身份证件或者其他身份证明文件的复印件或者影印件；识别并核实被保险人、受益人的身份，登记被保险人、受益人的姓名或者名称、联系方式、有效身份证件或者其他身份证明文件的种类、号码和有效期限，并留存被保险人、受益人有效身份证件或者其他身份证明文件的复印件或者影印件。上述保险合同未明确指定受益人，而是通过特征描述、法定继承或者其他方式指定受益人时，保险公司应当在明确受益人身份或者赔偿、给付保险金时识别、核实受益人身份。 对于保险费金额人民币5万元以上或者外币等值1万美元以上的财产保险合同和健康保险、意外伤害保险等不具有投资性质的人身保险合同，保险公司在与客户订立保险合同时，应当识别并核实投保人、被保险人身份，"},{"i":13,"n":"第十三条","txt":"在客户申请解除保险合同、减保或者办理保单贷款时，退还的保险费、现金价值或者提供的贷款金额为人民币1万元以上或者外币等值1000美元以上的，保险公司应当核实申请人身份，登记退保、减保或者办理保单贷款原因，将保险费、现金价值退还或者发放至投保人本人账户，遇特殊情况无法将保险费、现金价值退还或者发放至投保人本人账户的，需登记原因并经高级管理层批准。"},{"i":14,"n":"第十四条","txt":"对于人寿保险合同和其他具有投资性质的保险合同，保险公司在赔偿或者给付保险金时，应当核实被保险人、受益人身份，并留存受益人有效身份证件或者其他身份证明文件的复印件或者影印件。 对于财产保险合同和健康保险、意外伤害保险等不具有投资性质的人身保险合同，当被保险人或者受益人请求保险公司赔偿时，金额为人民币5万元以上或者外币等值1万美元以上的，保险公司应当识别并核实被保险人或者受益人身份，登记被保险人或者受益人的姓名或者名称、联系方式、有效身份证件或者其他身份证明文件的种类、号码和有效期限，并留存被保险人或者受益人有效身份证件或者其他身份证明文件的复印件或者影印件。 保险公司应当将保险金支付给保单受益人、被保险人或者指定收款人的账户。对于被保险人或者受益人请求将保险金支付给被保险人、受益人、指定收款人以外第三人的，保险公司应当确认被保险人和实际收款人之间的关系，或者受益人和实际收款人之间的关系，"},{"i":15,"n":"第十五条","txt":"保险公司在与客户订立养老保障管理合同时，应当识别并核实委托人身份，登记委托人身份基本信息，并留存委托人有效身份证件或者其他身份证明文件的复印件或者影印件；在办理资金领取时，金额为人民币5万元以上或者外币等值1万美元以上的，保险公司应当识别并核实受益人身份。"},{"i":16,"n":"第十六条","txt":"非银行支付机构在办理下列业务时，应当开展客户尽职调查，并登记客户身份基本信息，留存客户有效身份证件或者其他身份证明文件的复印件或者影印件： （一）以开立支付账户等方式与客户建立业务关系，以及向客户出售记名预付卡或者一次性出售不记名预付卡人民币1万元以上的； （二）中国人民银行规定的其他情形。"},{"i":17,"n":"第十七条","txt":"银行、非银行支付机构为特约商户提供收单服务，应当对特约商户开展客户尽职调查，并登记特约商户及其法定代表人或者负责人身份基本信息，留存特约商户及其法定代表人或者负责人有效身份证件或者其他身份证明文件的复印件或者影印件。"},{"i":18,"n":"第十八条","txt":"信托公司在设立信托或者为客户办理信托受益权转让时，应当识别并核实委托人身份，了解信托财产的来源，登记委托人的身份基本信息，并留存委托人有效身份证件或者其他身份证明文件的复印件或者影印件。受益人不是委托人本人的，信托公司应当识别并核实受益人身份。"},{"i":19,"n":"第十九条","txt":"保险资产管理公司、金融资产管理公司、企业集团财务公司、金融租赁公司、汽车金融公司、消费金融公司、货币经纪公司、理财公司以及中国人民银行确定并公布的从事金融业务的其他机构，在与客户建立业务关系时，应当识别并核实客户身份，登记客户身份基本信息，并留存客户有效身份证件或者其他身份证明文件的复印件或者影印件。 金融机构依托其他机构开展上述业务时，应当符合本办法第三十七条的规定。"},{"i":20,"n":"第二十条","txt":"为信托办理业务或者客户的财产属于信托财产的，金融机构应当了解信托的业务性质、所有权和控制权结构，通过获取其名称、成立的协议文件以及受托人或者管理人的名称、登记的住所或者主要经营场所等信息，识别并核实其身份，依照有关规定识别并采取合理措施核实信托的受益所有人。当受托人或者管理人的住所和主要经营场所不一致时，以主要经营场所为准；对于在境外注册或者经营的，至少识别和登记国家或者地区信息。 对于客户为法人或者非法人组织的，金融机构应当了解客户的业务性质、所有权和控制权结构，依照有关规定通过来源可靠的相关信息识别并采取合理措施核实客户的受益所有人。"},{"i":21,"n":"第二十一条","txt":"保险公司应当将人寿保险保单受益人纳入相关的风险因素来决定是否采取强化的客户尽职调查措施。 对于人寿保险保单受益人为法人或者非法人组织并且具有较高风险情形的，保险公司应当在赔偿或者给付保险金时采取强化尽职调查措施，识别并采取合理措施核实保单受益人的受益所有人。"},{"i":22,"n":"第二十二条","txt":"金融机构应当通过来源可靠、独立的相关材料、数据或者信息核实客户身份，包括下列一种或者多种方式： （一）通过公安、市场监督管理、民政、税务、移民管理、电信管理等部门或者其他政府公开渠道获取的信息核实客户身份； （二）通过外国政府机构、国际组织等官方认证的信息核实客户身份； （三）要求客户补充其他身份资料或者相关材料； （四）其他来源可靠、独立的信息。 银行业金融机构履行客户尽职调查义务时，依照法律、行政法规、部门规章的规定需核实相关自然人的居民身份证的，可以通过中国人民银行建立的联网核查公民身份信息系统进行核查。"},{"i":23,"n":"第二十三条","txt":"金融机构应当在建立业务关系或者办理规定金额以上的一次性金融服务时核实客户及其受益所有人身份。对于难以中断的正常交易，在有效管理洗钱、恐怖融资风险的情况下，金融机构可以在建立业务关系后尽快完成客户及其受益所有人身份核实工作。金融机构在未完成客户及其受益所有人身份核实工作前为客户办理业务的，应当采取适当的措施管理风险。"},{"i":24,"n":"第二十四条","txt":"客户由他人代理办理业务的，金融机构应当采取合理方式确认代理关系存在，在依照本办法的有关要求对被代理人采取客户尽职调查措施时，应当识别并核实代理人身份，登记代理人的姓名或者名称、联系方式、有效身份证件或者其他身份证明文件的种类、号码，并留存代理人有效身份证件或者其他身份证明文件的复印件或者影印件。"},{"i":25,"n":"第二十五条","txt":"金融机构在与客户建立业务关系时，应当根据客户尽职调查所获得的信息，及时评估客户风险，划分风险等级，确定不同风险等级客户的定期审核频次和方式。对洗钱、恐怖融资风险等级最高的客户，金融机构应当至少每年进行1次审核。 金融机构应当持续关注客户的风险状况、交易情况和身份信息变化，及时、合理调整客户洗钱、恐怖融资风险等级。"},{"i":26,"n":"第二十六条","txt":"业务关系存续期间，金融机构应当持续关注并评估客户整体状况及交易情况，了解客户的洗钱、恐怖融资风险。有下列情形之一的，应当通过向客户了解或者其他渠道获取信息，进一步核实客户及其交易有关情况，以确认为客户提供的各类服务和交易符合金融机构对客户身份背景、业务需求、风险状况以及对客户资金来源和用途等方面的认识，以及客户尽职调查收集的相关材料、数据和信息的时效性及相关性： （一）客户有关行为或者交易出现异常，客户进行的交易与金融机构所掌握的客户身份、风险状况等不符，或者其他因素导致客户风险状况发生变化的； （二）对先前获得的客户身份资料的真实性、有效性、完整性存在疑问的； （三）客户要求变更姓名或者名称、身份证件或者其他身份证明文件种类、身份证件号码、经营范围、法定代表人、受益人或者受益所有人的； （四）其他需要关注并评估客户整体状况及交易情况的。 客户先前提交的身份证件或者其他身份证明文件已过"},{"i":27,"n":"第二十七条","txt":"金融机构与客户建立业务关系时或者业务关系存续期间，综合考虑客户特征、业务关系、交易目的、交易性质、资金来源和用途等因素，对于存在较高洗钱、恐怖融资风险情形的，或者客户为国家有关机关调查、发布的涉嫌洗钱、恐怖融资及相关犯罪人员的，应当根据风险状况采取强化尽职调查措施。"},{"i":28,"n":"第二十八条","txt":"对于洗钱、恐怖融资风险较高的情形以及高风险客户，金融机构根据情形采取相匹配的下列一种或者多种强化尽职调查措施： （一）获取业务关系、交易目的和性质、资金来源和用途的相关信息，必要时，要求客户提供相关材料并予以核实； （二）通过实地查访等方式了解客户的经济状况或者经营状况； （三）加强对客户及其交易的监测分析； （四）加强对客户及其受益所有人信息审查； （五）与客户建立、维持业务关系，或者为客户办理业务，需要获得高级管理层的批准。 金融机构采取强化尽职调查措施后，确需对客户的洗钱、恐怖融资风险进行风险管理的，可以对客户的交易方式、交易规模、交易频率、办理业务类型等实施合理限制，认为客户的洗钱、恐怖融资风险超出金融机构风险管理能力的，应当拒绝办理业务或者终止已经建立的业务关系。 金融机构采取洗钱风险管理措施，应当依照有关管理规定的要求和程序进行，不得违法冻结客户资金，不得采取与洗钱风险状况"},{"i":29,"n":"第二十九条","txt":"金融机构结合客户特征、业务关系或者交易目的和性质，经过风险评估且具有充足理由判断其洗钱、恐怖融资风险为低风险时，根据情形采取适当的简化客户尽职调查措施。当怀疑客户或者交易涉嫌洗钱、恐怖融资等高风险情形的，金融机构不得采取简化尽职调查措施。 金融机构采取的简化尽职调查措施可以包括在建立业务关系后的合理期限内完成客户及其受益所有人身份核实、延长客户定期审查的周期，降低尽职调查措施的频率和强度、降低交易监测的频率和强度等。对于采取简化尽职调查措施的客户或者交易，金融机构应当定期审查其风险状况。当客户或者交易风险状况发生变化时，金融机构应当及时调整简化措施范围和相关要求。 简化尽职调查不等于豁免金融机构对客户的尽职调查，应当至少识别并核实客户身份，登记客户姓名、联系方式、身份证件或者其他身份证明文件的号码、种类、有效期限等身份信息，留存客户尽职调查过程中必要的身份资料。 金融机构根据本条第一款"},{"i":30,"n":"第三十条","txt":"金融机构无法按本办法规定开展客户尽职调查的，不得与客户建立业务关系、提供规定金额以上的一次性金融服务；已经建立业务关系的，应当根据情形终止已建立的业务关系，并提交可疑交易报告。 金融机构与客户建立业务关系时或者与客户业务关系存续期间，有合理理由怀疑客户存在组织批量或者分批开立账户，出租出借或者买卖账户，或者其他涉嫌洗钱等违法犯罪活动情形的，金融机构有权拒绝开户，或者根据客户及其申请办理业务的风险状况，采取延长审查期限、强化尽职调查等措施，必要时采取适当的洗钱风险管理措施。"},{"i":31,"n":"第三十一条","txt":"有合理理由怀疑客户涉嫌洗钱或者恐怖融资，并且开展客户尽职调查会导致发生泄密事件的，金融机构可以不开展客户尽职调查，但应当提交可疑交易报告。"},{"i":32,"n":"第三十二条","txt":"金融机构与境外金融机构建立代理行或者类似业务关系，或者接受委托为境外经纪机构或其客户提供境内证券期货交易时，应当了解境外机构所在国家或者地区洗钱、恐怖融资风险状况，充分收集境外机构代理业务性质、声誉、内部控制、接受监管和调查等方面的信息，评估境外机构接受反洗钱和反恐怖融资监管和调查的情况，以及反洗钱和反恐怖融资措施的健全性和有效性，明确本机构与境外机构在客户尽职调查、客户身份资料及交易记录保存方面的职责。 金融机构与境外金融机构建立代理行或者类似业务关系，或者接受委托为境外经纪机构或其客户提供境内证券期货交易时，应当获得董事会或者向董事会负责的高级管理层的批准。金融机构应当确保委托机构对直接使用代理行账户的客户开展尽职调查，并能够应金融机构要求提供相关客户尽职调查信息。金融机构不得与空壳银行建立代理行或者类似业务关系，同时应当确保委托机构不提供账户供空壳银行使用。 金融机构应当持续关注"},{"i":33,"n":"第三十三条","txt":"金融机构应当采取合理措施确定客户及其受益所有人是否为外国政要、国际组织高级管理人员、外国政要或者国际组织高级管理人员的特定关系人。客户或者其受益所有人为外国政要或者其特定关系人的，金融机构应当采取措施了解客户及其受益所有人资金或者财产的来源和用途，与客户建立、维持业务关系还应当获得高级管理层批准，并对客户及业务关系采取强化的持续监测措施。客户或者其受益所有人为国际组织高级管理人员或者其特定关系人的，在具有较高风险情形时，金融机构应当采取前述规定的措施。 人寿保险保单受益人或者其受益所有人为外国政要、国际组织高级管理人员、外国政要或者国际组织高级管理人员的特定关系人的，保险公司应当在赔偿或者给付保险金时获得高级管理层批准，并对投保人及业务关系采取强化尽职调查措施。 前两款规定的外国政要，包括外国现任的或者离任的履行重要公共职能的人员，如国家元首、政府首脑、高层政要，重要的政府、司法或者军"},{"i":34,"n":"第三十四条","txt":"金融机构和从事汇兑业务的机构为客户向境外汇出资金时，应当登记汇款人的姓名或者名称、账号、住所和收款人的姓名或者名称、账号等信息，在汇兑凭证或者相关信息系统中留存上述信息，并向接收汇款的境外机构提供汇款人的姓名或者名称、账号、住所等信息。汇款人未在本机构开户，金融机构无法登记汇款人账号的，可以登记并向接收汇款的境外机构提供其他相关信息，确保该笔交易可跟踪稽核。 金融机构和从事汇兑业务的机构为客户向境外汇出资金金额为单笔人民币5000元或者外币等值1000美元以上的，应当核实汇款人信息的准确性。有合理理由怀疑客户涉嫌洗钱或者恐怖融资的，无论汇出资金金额大小，金融机构都应当采取合理措施核实汇款人信息。 金融机构作为跨境汇款业务的中间机构时，应当完整传递汇款业务所附的汇款人和收款人信息，采取合理措施识别是否缺少汇款人和收款人必要信息，并根据风险状况，明确执行、拒绝或者暂停上述汇款业务的适用情形"},{"i":35,"n":"第三十五条","txt":"金融机构和从事汇兑业务的机构为客户办理境内汇款的，应当参照执行本办法第三十四条第一款和第二款的要求。汇款机构无法及时将汇款人信息提供给接收汇款的机构的，应当至少提供汇款人账号或者其他能够确保该笔交易可跟踪稽核的信息，并在接收汇款的机构或者相关主管部门需要时向其提供汇款人信息。 不符合本办法第三十四条和第三十五条第一款有关汇款业务要求的，金融机构和从事汇兑业务的机构不得为客户办理汇款业务。金融机构和从事汇兑业务的机构通过其境内外分支机构、附属机构或者代理机构开展汇款业务的，应当确保其境内外分支机构、附属机构或者代理机构遵守汇款业务相关规定。"},{"i":36,"n":"第三十六条","txt":"金融机构运用互联网和移动通信等信息通信技术，依法以非面对面形式与客户建立业务关系或者为客户提供金融服务时，应当建立有效的客户身份认证机制，通过有效措施识别并核实客户身份，以确认客户身份的真实性和交易的合理性。"},{"i":37,"n":"第三十七条","txt":"金融机构依托第三方开展本办法第七条第二款第一项、第二项、第五项尽职调查措施的，应当符合下列要求，并承担未履行客户尽职调查义务的责任： （一）第三方接受反洗钱和反恐怖融资监管或者监测； （二）评估第三方的风险状况及其履行反洗钱和反恐怖融资义务的能力，并确保第三方根据反洗钱和反恐怖融资法律法规和本办法的有关要求采取客户尽职调查、客户身份资料及交易记录保存措施；第三方具有较高风险情形或者不具备履行反洗钱和反恐怖融资义务能力的，不得依托第三方开展客户尽职调查； （三）金融机构能够立即从第三方获取客户尽职调查的必要信息； （四）金融机构在需要时能够立即获得第三方开展客户尽职调查获取的身份证件或者其他身份证明文件以及其他资料的复印件或者影印件； （五）金融机构依托境外第三方开展客户尽职调查的，应当充分考虑第三方所在国家或者地区的风险状况，不得依托来自高风险国家或者地区的第三方开展客户尽职调查。 金"},{"i":38,"n":"第三十八条","txt":"金融机构应当在开展客户尽职调查中相互配合。"},{"i":39,"n":"第三十九条","txt":"金融机构应当建立健全工作机制，及时获取依法应当采取反洗钱特别预防措施的组织和人员名单，对客户及其交易对象开展核查，客户或者其交易对象的资金或者其他资产与名单相关的，应当立即依照有关规定采取反洗钱特别预防措施。"},{"i":40,"n":"第四十条","txt":"金融机构应当建立健全工作机制，及时获取国际反洗钱组织和我国有关部门发布的高风险国家或者地区以及强化监控国家或者地区名单。对于来自高风险国家或者地区的客户或交易，金融机构应当结合业务关系和交易的风险状况采取强化尽职调查措施和必要的风险管理措施。对于来自强化监控国家或者地区的客户，金融机构在开展客户尽职调查及划分客户风险等级时，应当关注客户所在国家或者地区的风险状况。 国际反洗钱组织或者我国有关部门要求对高风险国家或者地区采取其他行动的，金融机构应当基于风险采取下列应对措施，免受其洗钱、恐怖融资风险的影响： （一）对来自高风险国家或者地区的客户和交易采取强化的交易监测措施，发现可疑情形应及时提交可疑交易报告，必要时拒绝提供金融服务或者终止业务关系； （二）审慎考虑在高风险国家或者地区开立分支机构、控股附属机构或者设立代表处；在高风险国家或者地区有分支机构、控股附属机构、代表处的金融机构，应"},{"i":41,"n":"第四十一条","txt":"金融机构在开展客户尽职调查时，应当根据风险情形向中国反洗钱监测分析中心报告下列可疑行为： （一）客户拒绝提供有效身份证件或者其他身份证明文件的； （二）有合理理由怀疑客户建立业务关系的目的和性质与洗钱或者恐怖融资等违法犯罪活动相关的； （三）对向境内汇入资金的境外机构提出要求后，仍无法完整获得汇款人姓名或者名称、账号和住所的； （四）采取必要措施后，对先前获得的客户身份资料的真实性、有效性、完整性仍存在疑问的； （五）履行客户尽职调查义务时发现其他可疑行为的。 金融机构报告上述可疑行为依照中国人民银行关于金融机构大额交易和可疑交易报告的相关规定执行。"},{"i":42,"n":"第四十二条","txt":"金融机构应当保存的客户身份资料包括记载客户身份信息、受益所有人信息以及反映金融机构开展客户尽职调查工作情况的各种记录和资料。 金融机构应当保存的交易记录包括关于每笔交易的数据信息、业务凭证、账簿以及有关规定要求的反映交易真实情况的合同、业务凭证、单据、业务函件和其他资料。"},{"i":43,"n":"第四十三条","txt":"金融机构应当采取必要的管理措施和技术措施，逐步实现以电子化方式完整、准确保存客户身份资料及交易信息，依法保护商业秘密和个人信息，防止客户身份资料及交易记录缺失、损毁，防止泄漏客户身份资料及交易信息。 金融机构客户身份资料及交易记录的保存方式和管理机制，应当确保足以重现和追溯每笔交易，并经过适当的授权后能够将所有的客户尽职调查信息和交易记录依法提供给监管部门和执法机关，便于金融机构反洗钱工作开展，以及反洗钱调查和监督管理。"},{"i":44,"n":"第四十四条","txt":"金融机构应当按照下列期限保存客户身份资料及交易记录： （一）客户身份资料自业务关系结束后或者一次性金融服务结束后至少保存10年； （二）交易记录自交易结束后至少保存10年。 如客户身份资料及交易记录涉及正在被反洗钱调查的可疑交易活动，且反洗钱调查工作在前款规定的最低保存期限届满时仍未结束的，金融机构应当将相关客户身份资料及交易记录保存至反洗钱调查工作结束。 同一介质上存有不同保存期限客户身份资料或者交易记录的，应当按最长保存期限保存。同一客户身份资料或者交易记录采用不同介质保存的，应当按照上述期限要求至少保存一种介质的客户身份资料或者交易记录。 法律、行政法规对客户身份资料及交易记录有更长保存期限要求的，从其规定。"},{"i":45,"n":"第四十五条","txt":"金融机构解散或者被宣告破产时，应当按规定移交客户身份资料、交易记录以及包含客户身份资料、交易记录的介质。"},{"i":46,"n":"第四十六条","txt":"金融机构违反本办法的，中国人民银行或者其设区的市级以上分支机构依照《中华人民共和国反洗钱法》第五十二条至第五十六条的规定进行处罚；区别不同情形，建议有关金融管理部门依法予以处理。"},{"i":47,"n":"第四十七条","txt":"银行卡清算机构、网络支付清算机构、网络小额贷款公司以及从事汇兑业务、基金销售业务、保险专业代理和保险经纪业务的机构履行客户尽职调查和客户身份资料及交易记录保存义务适用本办法有关规定。"},{"i":48,"n":"第四十八条","txt":"保险公司根据本办法第十二条、第十四条开展客户尽职调查，确认投保人和被保险人，被保险人和受益人，被保险人和保险金实际收款人，以及受益人和保险金实际收款人之间的关系时，应至少通过核对能证实双方关系的文件，走访、查验，或者获取投保人、被保险人、受益人或保险金实际收款人的书面声明等一种方式进行确认，并保存相关工作记录或者材料。 保险公司在办理团险业务时可以按照单个被保险人的保险费金额或者分摊到每个被保险人的保险费金额计算保险业务客户尽职调查起点金额。 保险公司在办理再保险业务时，履行客户尽职调查义务不适用本办法。"},{"i":49,"n":"第四十九条","txt":"本办法有关用语的含义如下： （一）自然人客户的身份基本信息指姓名、性别、国籍、职业、住所地或者工作单位地址、联系方式，身份证件或者其他身份证明文件的种类、号码和有效期限，客户的住所地与经常居住地不一致的，以客户的经常居住地为准。 （二）法人、非法人组织和个体工商户客户的身份基本信息指名称、住所、经营范围、客户依法设立或者可依法开展经营、社会活动的执照、证件或者文件的名称、号码和有效期限；法定代表人或负责人和授权办理业务人员的姓名、联系方式、身份证件或者其他身份证明文件的种类、号码和有效期限。其中，客户住所信息指客户登记的住所或者主要经营场所，当住所和主要经营场所不一致时，以主要经营场所为准，对于在境外注册或者经营的，至少登记国家或者地区信息。 （三）客户有效身份证件或者其他身份证明文件是指国家有关机关、外国（地区）政府颁发能够证明其身份的书面或者电子证件，或者法律、行政法规规定的其他身"},{"i":50,"n":"第五十条","txt":"本办法由中国人民银行会同国家金融监督管理总局、中国证券监督管理委员会解释。"},{"i":51,"n":"第五十一条","txt":"对本办法施行前已经建立业务关系的存量客户，未满足本办法有关客户尽职调查要求的，金融机构应当自本办法施行之日起半年内完成较高风险以上存量客户的尽职调查，自本办法施行之日起2年内完成全部存量客户的尽职调查。"},{"i":52,"n":"第五十二条","txt":"本办法自2026年1月1日起施行。《金融机构客户身份识别和客户身份资料及交易记录保存管理办法》（中国人民银行 中国银行业监督管理委员会 中国证券监督管理委员会 中国保险监督管理委员会令〔2007〕第2号发布）和《金融机构客户尽职调查和客户身份资料及交易记录保存管理办法》（中国人民银行 中国银行保险监督管理委员会 中国证券监督管理委员会令〔2022〕第1号发布）同时废止。本办法施行前发布的客户尽职调查和客户身份资料及交易记录保存的其他规定与本办法不一致的，以本办法为准。数字人民币客户尽职调查和客户身份资料及交易记录保存工作依照有关规定执行。"}],"jinrongjigoukehushenfenshibiehekehushenfenziliaoji989f94":[{"i":1,"n":"第一条","txt":"为了预防洗钱和恐怖融资活动，规范金融机构客户身份识别、客户身份资料和交易记录保存行为，维护金融秩序，根据《中华人民共和国反洗钱法》等法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内依法设立的下列金融机构： （一）政策性银行、商业银行、农村合作银行、城市信用合作社、农村信用合作社。 （二）证券公司、期货公司、基金管理公司。 （三）保险公司、保险资产管理公司。 （四）信托公司、金融资产管理公司、财务公司、金融租赁公司、汽车金融公司、货币经纪公司。 （五）中国人民银行确定并公布的其他金融机构。 从事汇兑业务、支付清算业务和基金销售业务的机构履行客户身份识别、客户身份资料和交易记录保存义务适用本办法。"},{"i":3,"n":"第三条","txt":"金融机构应当勤勉尽责，建立健全和执行客户身份识别制度，遵循“了解你的客户”的原则，针对具有不同洗钱或者恐怖融资风险特征的客户、业务关系或者交易，采取相应的措施，了解客户及其交易目的和交易性质，了解实际控制客户的自然人和交易的实际受益人。 金融机构应当按照安全、准确、完整、保密的原则，妥善保存客户身份资料和交易记录，确保能足以重现每项交易，以提供识别客户身份、监测分析交易情况、调查可疑交易活动和查处洗钱案件所需的信息。"},{"i":4,"n":"第四条","txt":"金融机构应当根据反洗钱和反恐怖融资方面的法律规定，建立和健全客户身份识别、客户身份资料和交易记录保存等方面的内部操作规程,指定专人负责反洗钱和反恐融资合规管理工作，合理设计业务流程和操作规范，并定期进行内部审计，评估内部操作规程是否健全、有效，及时修改和完善相关制度。"},{"i":5,"n":"第五条","txt":"金融机构应当对其分支机构执行客户身份识别制度、客户身份资料和交易记录保存制度的情况进行监督管理。 金融机构总部、集团总部应对客户身份识别、客户身份资料和交易记录保存工作作出统一要求。 金融机构应要求其境外分支机构和附属机构在驻在国家（地区）法律规定允许的范围内，执行本办法的有关要求，驻在国家（地区）有更严格要求的，遵守其规定。如果本办法的要求比驻在国家（地区）的相关规定更为严格，但驻在国家（地区）法律禁止或者限制境外分支机构和附属机构实施本办法，金融机构应向中国人民银行报告。"},{"i":6,"n":"第六条","txt":"金融机构与境外金融机构建立代理行或者类似业务关系时，应当充分收集有关境外金融机构业务、声誉、内部控制、接受监管等方面的信息，评估境外金融机构接受反洗钱监管的情况和反洗钱、反恐怖融资措施的健全性和有效性，以书面方式明确本金融机构与境外金融机构在客户身份识别、客户身份资料和交易记录保存方面的职责。 金融机构与境外金融机构建立代理行或者类似业务关系应当经董事会或者其他高级管理层的批准。"},{"i":7,"n":"第七条","txt":"政策性银行、商业银行、农村合作银行、城市信用合作社、农村信用合作社等金融机构和从事汇兑业务的机构，在以开立账户等方式与客户建立业务关系，为不在本机构开立账户的客户提供现金汇款、现钞兑换、票据兑付等一次性金融服务且交易金额单笔人民币1万元以上或者外币等值1000美元以上的，应当识别客户身份，了解实际控制客户的自然人和交易的实际受益人，核对客户的有效身份证件或者其他身份证明文件，登记客户身份基本信息，并留存有效身份证件或者其他身份证明文件的复印件或者影印件。 如客户为外国政要，金融机构为其开立账户应当经高级管理层的批准。"},{"i":8,"n":"第八条","txt":"商业银行、农村合作银行、城市信用合作社、农村信用合作社等金融机构为自然人客户办理人民币单笔5 万元以上或者外币等值1 万美元以上现金存取业务的，应当核对客户的有效身份证件或者其他身份证明文件。"},{"i":9,"n":"第九条","txt":"金融机构提供保管箱服务时，应了解保管箱的实际使用人。"},{"i":10,"n":"第十条","txt":"政策性银行、商业银行、农村合作银行、城市信用合作社、农村信用合作社等金融机构和从事汇兑业务的机构为客户向境外汇出资金时，应当登记汇款人的姓名或者名称、账号、住所和收款人的姓名、住所等信息，在汇兑凭证或者相关信息系统中留存上述信息，并向接收汇款的境外机构提供汇款人的姓名或者名称、账号、住所等信息。汇款人没有在本金融机构开户，金融机构无法登记汇款人账号的，可登记并向接收汇款的境外机构提供其他相关信息，确保该笔交易的可跟踪稽核。境外收款人住所不明确的，金融机构可登记接收汇款的境外机构所在地名称。 接收境外汇入款的金融机构，发现汇款人姓名或者名称、汇款人账号和汇款人住所三项信息中任何一项缺失的，应要求境外机构补充。如汇款人没有在办理汇出业务的境外机构开立账户，接收汇款的境内金融机构无法登记汇款人账号的，可登记其他相关信息，确保该笔交易的可跟踪稽核。境外汇款人住所不明确的，境内金融机构可登记资金"},{"i":11,"n":"第十一条","txt":"证券公司、期货公司、基金管理公司以及其他从事基金销售业务的机构在办理以下业务时，应当识别客户身份，了解实际控制客户的自然人和交易的实际受益人，核对客户的有效身份证件或者其他身份证明文件，登记客户身份基本信息，并留存有效身份证件或者其他身份证明文件的复印件或者影印件： （一）资金账户开户、销户、变更，资金存取等。 （二）开立基金账户。 （三）代办证券账户的开户、挂失、销户或者期货客户交易编码的申请、挂失、销户。 （四）与客户签订期货经纪合同。 （五）为客户办理代理授权或者取消代理授权。 （六）转托管，指定交易、撤销指定交易。 （七）代办股份确认。 （八）交易密码挂失。 （九）修改客户身份基本信息等资料。 （十）开通网上交易、电话交易等非柜面交易方式。 （十一）与客户签订融资融券等信用交易合同。 （十二）办理中国人民银行和中国证券监督管理委员会确定的其他业务。"},{"i":12,"n":"第十二条","txt":"对于保险费金额人民币1 万元以上或者外币等值1000美元以上且以现金形式缴纳的财产保险合同，单个被保险人保险费金额人民币2万元以上或者外币等值2000 美元以上且以现金形式缴纳的人身保险合同，保险费金额人民币20万元以上或者外币等值2万美元以上且以转账形式缴纳的保险合同，保险公司在订立保险合同时，应确认投保人与被保险人的关系，核对投保人和人身保险被保险人、法定继承人以外的指定受益人的有效身份证件或者其他身份证明文件，登记投保人、被保险人、法定继承人以外的指定受益人的身份基本信息，并留存有效身份证件或者其他身份证明文件的复印件或者影印件。"},{"i":13,"n":"第十三条","txt":"在客户申请解除保险合同时，如退还的保险费或者退还的保险单的现金价值金额为人民币1万元以上或者外币等值1000美元以上的，保险公司应当要求退保申请人出示保险合同原件或者保险凭证原件，核对退保申请人的有效身份证件或者其他身份证明文件，确认申请人的身份。"},{"i":14,"n":"第十四条","txt":"在被保险人或者受益人请求保险公司赔偿或者给付保险金时，如金额为人民币1万元以上或者外币等值1000美元以上，保险公司应当核对被保险人或者受益人的有效身份证件或者其他身份证明文件，确认被保险人、受益人与投保人之间的关系，登记被保险人、受益人身份基本信息，并留存有效身份证件或者其他身份证明文件的复印件或者影印件。"},{"i":15,"n":"第十五条","txt":"信托公司在设立信托时，应当核对委托人的有效身份证件或者其他身份证明文件，了解信托财产的来源，登记委托人、受益人的身份基本信息，并留存委托人的有效身份证件或者其他身份证明文件的复印件或者影印件。"},{"i":16,"n":"第十六条","txt":"金融资产管理公司、财务公司、金融租赁公司、汽车金融公司、货币经纪公司、保险资产管理公司以及中国人民银行确定的其他金融机构在与客户签订金融业务合同时，应当核对客户的有效身份证件或者其他身份证明文件，登记客户身份基本信息，并留存有效身份证件或者其他身份证明文件的复印件或者影印件。"},{"i":17,"n":"第十七条","txt":"金融机构利用电话、网络、自动柜员机以及其他方式为客户提供非柜台方式的服务时，应实行严格的身份认证措施，采取相应的技术保障手段，强化内部管理程序，识别客户身份。"},{"i":18,"n":"第十八条","txt":"金融机构应按照客户的特点或者账户的属性，并考虑地域、业务、行业、客户是否为外国政要等因素，划分风险等级，并在持续关注的基础上，适时调整风险等级。在同等条件下，来自于反洗钱、反恐怖融资监管薄弱国家（地区）客户的风险等级应高于来自于其他国家（地区）的客户。 金融机构应当根据客户或者账户的风险等级，定期审核本金融机构保存的客户基本信息，对风险等级较高客户或者账户的审核应严于对风险等级较低客户或者账户的审核。对本金融机构风险等级最高的客户或者账户，至少每半年进行一次审核。 金融机构的风险划分标准应报送中国人民银行。"},{"i":19,"n":"第十九条","txt":"在与客户的业务关系存续期间，金融机构应当采取持续的客户身份识别措施，关注客户及其日常经营活动、金融交易情况，及时提示客户更新资料信息。 对于高风险客户或者高风险账户持有人，金融机构应当了解其资金来源、资金用途、经济状况或者经营状况等信息，加强对其金融交易活动的监测分析。客户为外国政要的，金融机构应采取合理措施了解其资金来源和用途。 客户先前提交的身份证件或者身份证明文件已过有效期的，客户没有在合理期限内更新且没有提出合理理由的，金融机构应中止为客户办理业务。"},{"i":20,"n":"第二十条","txt":"金融机构应采取合理方式确认代理关系的存在，在按照本办法的有关要求对被代理人采取客户身份识别措施时，应当核对代理人的有效身份证件或者身份证明文件，登记代理人的姓名或者名称、联系方式、身份证件或者身份证明文件的种类、号码。"},{"i":21,"n":"第二十一条","txt":"除信托公司以外的金融机构了解或者应当了解客户的资金或者财产属于信托财产的，应当识别信托关系当事人的身份，登记信托委托人、受益人的姓名或者名称、联系方式。"},{"i":22,"n":"第二十二条","txt":"出现以下情况时，金融机构应当重新识别客户： （一）客户要求变更姓名或者名称、身份证件或者身份证明文件种类、身份证件号码、注册资本、经营范围、法定代表人或者负责人的。 （二）客户行为或者交易情况出现异常的。 （三）客户姓名或者名称与国务院有关部门、机构和司法机关依法要求金融机构协查或者关注的犯罪嫌疑人、洗钱和恐怖融资分子的姓名或者名称相同的。 （四）客户有洗钱、恐怖融资活动嫌疑的。 （五）金融机构获得的客户信息与先前已经掌握的相关信息存在不一致或者相互矛盾的。 （六）先前获得的客户身份资料的真实性、有效性、完整性存在疑点的。 （七）金融机构认为应重新识别客户身份的其他情形。"},{"i":23,"n":"第二十三条","txt":"金融机构除核对有效身份证件或者其他身份证明文件外，可以采取以下的一种或者几种措施，识别或者重新识别客户身份： （一）要求客户补充其他身份资料或者身份证明文件。 （二）回访客户。 （三）实地查访。 （四）向公安、工商行政管理等部门核实。 （五）其他可依法采取的措施。 银行业金融机构履行客户身份识别义务时，按照法律、行政法规或部门规章的规定需核对相关自然人的居民身份证的，应通过中国人民银行建立的联网核查公民身份信息系统进行核查。其他金融机构核实自然人的公民身份信息时，可以通过中国人民银行建立的联网核查公民身份信息系统进行核查。"},{"i":24,"n":"第二十四条","txt":"金融机构委托其他金融机构向客户销售金融产品时，应在委托协议中明确双方在识别客户身份方面的职责，相互间提供必要的协助，相应采取有效的客户身份识别措施。 符合下列条件时，金融机构可信赖销售金融产品的金融机构所提供的客户身份识别结果，不再重复进行已完成的客户身份识别程序，但仍应承担未履行客户身份识别义务的责任： （一）销售金融产品的金融机构采取的客户身份识别措施符合反洗钱法律、行政法规和本办法的要求。 （二）金融机构能够有效获得并保存客户身份资料信息。"},{"i":25,"n":"第二十五条","txt":"金融机构委托金融机构以外的第三方识别客户身份的，应当符合下列要求： （一）能够证明第三方按反洗钱法律、行政法规和本办法的要求，采取了客户身份识别和身份资料保存的必要措施。 （二）第三方为本金融机构提供客户信息，不存在法律制度、技术等方面的障碍。 （三）本金融机构在办理业务时，能立即获得第三方提供的客户信息，还可在必要时从第三方获得客户的有效身份证件、身份证明文件的原件、复印件或者影印件。 委托第三方代为履行识别客户身份的，金融机构应当承担未履行客户身份识别义务的责任。"},{"i":26,"n":"第二十六条","txt":"金融机构在履行客户身份识别义务时，应当向中国反洗钱监测分析中心和中国人民银行当地分支机构报告以下可疑行为： （一）客户拒绝提供有效身份证件或者其他身份证明文件的。 （二）对向境内汇入资金的境外机构提出要求后，仍无法完整获得汇款人姓名或者名称、汇款人账号和汇款人住所及其他相关替代性信息的。 （三）客户无正当理由拒绝更新客户基本信息的。 （四）采取必要措施后，仍怀疑先前获得的客户身份资料的真实性、有效性、完整性的。 （五）履行客户身份识别义务时发现的其他可疑行为。 金融机构报告上述可疑行为参照《金融机构大额交易和可疑交易报告管理办法》（中国人民银行令〔2006〕第2 号发布）及相关规定执行。"},{"i":27,"n":"第二十七条","txt":"金融机构应当保存的客户身份资料包括记载客户身份信息、资料以及反映金融机构开展客户身份识别工作情况的各种记录和资料。 金融机构应当保存的交易记录包括关于每笔交易的数据信息、业务凭证、账簿以及有关规定要求的反映交易真实情况的合同、业务凭证、单据、业务函件和其他资料。"},{"i":28,"n":"第二十八条","txt":"金融机构应采取必要管理措施和技术措施，防止客户身份资料和交易记录的缺失、损毁，防止泄漏客户身份信息和交易信息。 金融机构应采取切实可行的措施保存客户身份资料和交易记录，便于反洗钱调查和监督管理。"},{"i":29,"n":"第二十九条","txt":"金融机构应当按照下列期限保存客户身份资料和交易记录： （一）客户身份资料，自业务关系结束当年或者一次性交易记账当年计起至少保存5 年。 （二）交易记录，自交易记账当年计起至少保存5 年。 如客户身份资料和交易记录涉及正在被反洗钱调查的可疑交易活动，且反洗钱调查工作在前款规定的最低保存期届满时仍未结束的，金融机构应将其保存至反洗钱调查工作结束。 同一介质上存有不同保存期限客户身份资料或者交易记录的，应当按最长期限保存。同一客户身份资料或者交易记录采用不同介质保存的，至少应当按照上述期限要求保存一种介质的客户身份资料或者交易记录。 法律、行政法规和其他规章对客户身份资料和交易记录有更长保存期限要求的，遵守其规定。"},{"i":30,"n":"第三十条","txt":"金融机构破产或者解散时，应当将客户身份资料和交易记录移交中国银行业监督管理委员会、中国证券监督管理委员会或者中国保险监督管理委员会指定的机构。"},{"i":31,"n":"第三十一条","txt":"金融机构违反本办法的，由中国人民银行按照《中华人民共和国反洗钱法》第三十一条、第三十二条的规定予以处罚；区别不同情形，向中国银行业监督管理委员会、中国证券监督管理委员会或者中国保险监督管理委员会建议采取下列措施： （一）责令金融机构停业整顿或者吊销其经营许可证。 （二）取消金融机构直接负责的董事、高级管理人员和其他直接责任人员的任职资格、禁止其从事有关金融行业的工作。 （三）责令金融机构对直接负责的董事、高级管理人员和其他直接责任人员给予纪律处分。 中国人民银行县（市）支行发现金融机构违反本办法的，应当报告上一级中国人民银行分支机构，由上一级分支机构按照前款规定进行处罚或者提出建议。"},{"i":32,"n":"第三十二条","txt":"保险公司在办理再保险业务时，履行客户身份识别义务不适用本办法。"},{"i":33,"n":"第三十三条","txt":"本办法下列用语的含义如下： 自然人客户的“身份基本信息”包括客户的姓名、性别、国籍、职业、住所地或者工作单位地址、联系方式，身份证件或者身份证明文件的种类、号码和有效期限。客户的住所地与经常居住地不一致的，登记客户的经常居住地。 法人、其他组织和个体工商户客户的“身份基本信息”包括客户的名称、住所、经营范围、组织机构代码、税务登记证号码；可证明该客户依法设立或者可依法开展经营、社会活动的执照、证件或者文件的名称、号码和有效期限；控股股东或者实际控制人、法定代表人、负责人和授权办理业务人员的姓名、身份证件或者身份证明文件的种类、号码、有效期限。"},{"i":34,"n":"第三十四条","txt":"本办法由中国人民银行会同中国银行业监督管理委员会、中国证券监督管理委员会、中国保险监督管理委员会解释。"},{"i":35,"n":"第三十五条","txt":"本办法自2007年8 月1日起施行。"}],"jinrongtongjiguanliguiding":[{"i":1,"n":"第一条","txt":"为适应金融管理体制改革和金融业务的发展，依法强化金融统计管理，规范金融统计行为，提高金融统计质量，根据《中华人民共和国统计法》、《中华人民共和国统计法实施细则》、《中华人民共和国中国人民银行法》、《中华人民共和国商业银行法》、《金融违法行为处罚办法》等法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中国人民银行，以及经中国人民银行批准从事金融业务的中、外资金融机构，包括政策性银行、商业银行、城市信用合作社、农村信用合作社、信托投资公司、企业集团财务公司、金融租赁公司、金融资产管理公司、邮政储汇局等。"},{"i":3,"n":"第三条","txt":"本规定所称金融统计，系指中国人民银行和各金融机构统计部门对各项金融业务活动的情况和资料进行调查收集、整理和分析，提供统计信息和统计咨询意见，实行信息交流与共享，进行金融统计管理和监督等活动的总称。它包括货币统计、本外币信贷收支统计、现金收支统计、贷款累放累收统计、金融监管统计、资金流量统计、金融市场统计、银行中间业务及各种专项统计等金融业务统计。 本规定所称统计部门，系指中国人民银行和各金融机构内部从事金融统计业务的工作部门。"},{"i":4,"n":"第四条","txt":"金融统计工作的基本任务是：及时、准确、全面地完成各项金融业务统计；收集、整理、积累金融和有关国民经济的统计资料；开展统计调查、统计分析和统计预测，依法进行统计管理和统计检查，为国家和金融部门进行宏观经济决策、监测经济与金融运行情况、金融监管和经营管理提供统计信息和统计咨询意见；为社会公众提供统计信息；进行国际交流和为有关国际金融组织提供信息资料。"},{"i":5,"n":"第五条","txt":"金融统计工作遵循客观性、科学性、统一性、及时性的原则。"},{"i":6,"n":"第六条","txt":"金融统计实行统一领导、分级负责的管理体制。中国人民银行是组织、领导、监督、管理和协调全国金融统计工作的主管机关。"},{"i":7,"n":"第七条","txt":"金融统计要以计算机网络为依托逐步实现自动化、规范化、标准化管理。"},{"i":8,"n":"第八条","txt":"加快金融统计与国际接轨的进程，逐步实现按国际准则加工和披露金融统计数据。"},{"i":9,"n":"第九条","txt":"金融统计是以会计科目和各类账户信息为基础的全面统计，在此基础上形成各类统计报表。"},{"i":10,"n":"第十条","txt":"中国人民银行总行统一管理金融系统全国性统计报表，并负责金融系统全国性统计报表的制定、颁发与撤销。中国人民银行各分支行负责监督、检查辖区内金融机构执行统计报表、统计数据管理制度的情况。"},{"i":11,"n":"第十一条","txt":"金融机构总行（总公司、总局）管理本系统金融统计报表，并负责系统内全国性定期统计报表的制定、撤销，但须报中国人民银行总行备案。"},{"i":12,"n":"第十二条","txt":"中国人民银行各分行、营业管理部、省会（首府）城市中心支行可以制定地区性统计报表，但须报中国人民银行总行备案；金融机构省分行（分公司、分局）可以制定本系统地区性统计报表，但须报中国人民银行分行、省会（首府）城市中心支行备案。中国人民银行省会（首府）城市中心支行以下分支机构和金融机构省分行（分公司、分局）以下分支机构不得制定地区固定性统计报表。但在征得上级部门同意后，可根据实际需要制定地区临时性统计报表。临时性报表的期限一般不超过一年。"},{"i":13,"n":"第十三条","txt":"中国人民银行分行、营业管理部、省会（首府）城市中心支行，金融机构总行（总公司、总局）、省分行（分公司、分局），在遵循中国人民银行总行统一规定的统计项目、统计指标下，可增设必要的统计项目、统计指标。中国人民银行各分行、营业管理部、省会（首府）城市中心支行根据金融管理的需要，可要求辖区内金融机构增设必要的统计项目、统计指标和附表、统计台账和原始统计记录。"},{"i":14,"n":"第十四条","txt":"中国人民银行和各金融机构及其分支机构应严格控制临时性统计报表的制定和印发，减少临时性统计报表的数量。"},{"i":15,"n":"第十五条","txt":"中国人民银行制定统一的金融统计标准，以保障统计调查中采用的指标含义、计算方法、分类目录、调查表式和统计编码等方面的标准化。"},{"i":16,"n":"第十六条","txt":"中国人民银行向各金融机构收集统计数据由中国人民银行统计部门归口管理，各金融机构内设部门向中国人民银行报送的与中国人民银行统一金融统计指标（全科目统计指标）相关的统计数据由各金融机构统计部门归口管理，以保证统计数据的准确和一致。"},{"i":17,"n":"第十七条","txt":"中国人民银行和各金融机构统计部门要加强对金融统计资料和统计电子化资料的管理，建立健全金融统计资料的审核、整理、交接和存档等管理制度。"},{"i":18,"n":"第十八条","txt":"对违反国家统计法律、法规和本规定制定印发的统计报表和统计调查表，中国人民银行和各金融机构统计部门有权拒绝填报。"},{"i":19,"n":"第十九条","txt":"全国范围或地区性统计调查，由中国人民银行组织各金融机构共同进行；各金融机构本系统的统计调查，由各金融机构负责组织。"},{"i":20,"n":"第二十条","txt":"金融统计资料公布的主要内容要逐步实现与国际接轨，加快透明度进程。"},{"i":21,"n":"第二十一条","txt":"中国人民银行总行定期公布全国性金融统计资料（月后20日内通过新闻媒体和中国人民银行网站向全社会公布月度金融机构货币供应量、信贷收支及资产负债主要指标等金融统计资料）；中国人民银行分行、营业管理部、省会（首府）城市中心支行根据中国人民银行总行规定，定期公布辖区内金融统计资料，并报总行备案，对外公布个别项目的统计数字，须报经行长批准。 金融机构总行（总公司、总局）对外公布金融统计资料，须经本行（公司、局）行长（总经理、局长）批准。金融机构分支机构公布金融统计资料，按照其上级主管部门的规定执行。"},{"i":22,"n":"第二十二条","txt":"对外公布有密级的金融统计资料的审批，实行分级负责制度。 绝密、机密、秘密级的金融统计资料，未经批准，任何单位或个人不得擅自对外公布。 绝密、机密、秘密级金融统计资料的划分，按《金融工作中国家秘密及密级具体范围的规定》执行。 对外公布绝密级金融统计资料，必须报经国务院审批后，由中国人民银行总行公布；对外公布机密级金融统计资料，须经中国人民银行总行批准；对外公布秘密级金融统计资料，全国性数字由中国人民银行总行批准，金融机构本系统的数字由其总行（总公司、总局）批准。"},{"i":23,"n":"第二十三条","txt":"中国人民银行总行设立专职统计部门，负责组织、领导和协调全国金融统计工作；中国人民银行各分行、营业管理部、省会（首府）城市中心支行、地（市）级中心支行设专职统计部门，负责领导、协调辖区内金融机构的统计工作；中国人民银行县级支行设置统计岗位。"},{"i":24,"n":"第二十四条","txt":"各金融机构总行（总公司、总局）设立专职统计部门，管理本系统的统计工作；各金融机构分支机构的统计部门设置，由其总行（总公司、总局）自行决定。"},{"i":25,"n":"第二十五条","txt":"中国人民银行统计部门履行下列职责： （一）中国人民银行总行统计部门起草金融统计制度和有关管理规定；各分行、营业管理部、省会（首府）城市中心支行统计部门可根据总行下发的制度和有关规定，结合当地情况起草本行制度和实施细则，并报中国人民银行总行备案。 （二）组织、领导、管理、监督、检查金融机构的统计工作。 （三）收集、审核、汇总、编制金融统计数据和统计报表。 （四）收集、整理、积累金融统计资料和有关国民经济统计资料。 （五）按规定向有关部门提供金融统计资料，对外公布综合性金融统计资料。 （六）组织金融机构开展统计调查、统计分析和统计预测。 （七）组织和促进金融统计标准化、现代化建设，建立统一的金融统计管理信息系统和有效安全的网络传输设施，在金融系统内实行信息共享。 （八）组织开展统计执法和统计质量检查，培训统计人员。 （九）经授权代表金融系统参加国内、国际金融统计活动。"},{"i":26,"n":"第二十六条","txt":"金融机构统计部门履行下列职责： （一）贯彻执行中国人民银行制定的金融统计制度及有关管理办法，并接受中国人民银行的监督、检查。 （二）制定本系统金融统计制度、办法，领导和管理本系统金融统计工作。 （三）收集、汇总、编制、管理本系统金融统计数据和报表。 （四）收集、整理、积累本系统金融统计资料和有关国民经济统计资料。 （五）依法向中国人民银行报送统计数据、报表、统计制度和统计资料，向有关部门提供统计数据，对外公布本系统金融统计信息。 （六）完成中国人民银行布置的各项统计调查工作，在本系统组织开展统计调查、统计分析和统计预测。 （七）执行中国人民银行规定的统一的统计指标编码和电子文件接口规则。 （八）领导、组织本系统开展统计法规和统计质量检查，培训统计人员。"},{"i":27,"n":"第二十七条","txt":"统计人员的配备应符合以下要求： （一）统计人员要具备良好的职业道德，具有必要的统计专业基础知识和一定的计算机操作技能。 （二）统计人员必须实行岗位培训，未经岗前培训或培训不合格者不得上岗。经考核不适宜担任统计工作的人员，应及时进行调整。"},{"i":28,"n":"第二十八条","txt":"中国人民银行分支行统计部门主要负责人的调动，要征得上一级中国人民银行主管部门的同意；各金融机构分支行（公司、局）统计负责人的调动，应当征得其上级主管部门同意并向中国人民银行当地统计部门备案；统计人员调动工作或者离职，应当有符合规定条件的人接管，并须办理交接手续。"},{"i":29,"n":"第二十九条","txt":"中国人民银行分支行、各金融机构及其分支机构，应当根据国家有关规定和工作需要，设置和聘任统计专业技术职务。"},{"i":30,"n":"第三十条","txt":"凡设置统计部门的机构，其统计部门主要负责人为统计责任人；不设统计部门的，其法定代表人或主要负责人为统计责任人。统计责任人要对本机构统计数据的真实性负责。"},{"i":31,"n":"第三十一条","txt":"统计人员履行以下职责： （一）执行统计法律、规定、制度，按规定及时、准确、完整地填报统计数字，编制统计报表，不得虚报、瞒报、伪造、篡改统计数据； （二）严格遵守保密制度； （三）收集、整理、提供统计资料； （四）进行统计调查、统计分析和统计预测; （五）规范使用统计计算机程序系统，保证统计资料和统计数据安全; （六）依照规定的审批程序，有权要求有关部门和人员提供金融业务资料，询问情况和查阅原始资料； （七）检查统计资料的准确性，有权要求改正不确实的统计资料； （八）拒报不符合规定的统计报表，检举和揭发违反统计法律、规定、制度的行为。 中国人民银行和各金融机构的统计部门及统计人员依照国家颁布的统计法律、法规和本规定行使上述职权，任何单位和个人不得非法干预。"},{"i":32,"n":"第三十二条","txt":"中国人民银行统计部门依法对各金融机构的统计工作以及统计法律、规定、制度的执行情况，统计质量、统计真实性情况和统计工作情况，定期或不定期进行监督检查。检查的内容和重点应根据统计法律、规定和统计制度实施的情况具体确定。 金融机构统计部门在中国人民银行同级统计部门的组织指导下，监督检查本系统统计工作，以及统计法律、规定、制度的执行情况。 任何人不得干扰和妨碍统计人员执法检查和做出检查结论。"},{"i":33,"n":"第三十三条","txt":"中国人民银行统计部门应配备熟悉相关法律、规定、制度和统计业务的专职或兼职统计检查员。"},{"i":34,"n":"第三十四条","txt":"统计检查员在规定的职责范围内行使统计检查权。"},{"i":35,"n":"第三十五条","txt":"统计检查部门和统计检查员有权对被检查机构使用的统计资料及其数据来源进行检查和监督。统计检查员按规定有权向被检查金融机构发出《统计检查查询书》。被检查金融机构在接到《统计检查查询书》15日内应据实答复。"},{"i":36,"n":"第三十六条","txt":"统计检查可以对会计报表、与统计有关的其他业务报表及有关台账和原始凭证等进行核对。"},{"i":37,"n":"第三十七条","txt":"中国人民银行和各金融机构定期分别对本系统金融统计工作进行评比，中国人民银行定期对金融系统统计工作进行评比。中国人民银行和各金融机构根据有关规定对有下列表现之一的金融统计人员或者集体，分别给予嘉奖、记功、记大功、晋级、升职，授予荣誉称号，并可给予一定的奖励，奖励费用按照有关规定在有关经费中开支。 （一）在改革和完善金融统计制度、统计方法等方面，有突出贡献的； （二）在完成金融统计调查任务，保障统计资料的及时性、准确性方面，做出显著成绩的； （三）在进行金融统计分析、统计监督方面有创新，取得重要成果的； （四）在运用和推广现代化统计信息技术方面，有显著成绩的； （五）在强化统计教育和统计专业培训、进行统计科学研究，提高统计科学水平方面， 做出重要贡献的； （六）坚持实事求是，依法办事，同违反统计法律、规定、制度的行为作斗争，表现突出的； （七）揭发、检举统计违法行为有功的。"},{"i":38,"n":"第三十八条","txt":"金融机构统计及相关部门和人员，有下列行为之一者，由中国人民银行地（市）级（含地、市）以上机构和有关部门对该金融机构给予警告并处以3万元以下罚款；对金融机构直接负责的高级管理人员、其他直接负责的主管人员和直接责任人员，由所在金融机构或者上级金融机构给予警告、严重警告、记过、记大过、降级的纪律处分。中国人民银行统计及相关部门的工作人员有下列行为之一者，由所在单位或上级单位给予警告、严重警告、记过、记大过、降级的纪律处分。 （一）虚报、瞒报金融统计资料的； （二）伪造、篡改金融统计资料的； （三）拒报或者屡次迟报金融统计资料的； （四）违反本规定，未经批准，自行编制发布金融统计调查表，造成恶劣影响的； （五）违反本规定有关保密条款和《金融工作中国家秘密及其密级具体范围规定》，超越权限，自行公布金融统计资料造成严重后果的； （六）强迫和授意统计部门和统计人员在统计数据上弄虚作假的； （七）对坚"},{"i":39,"n":"第三十九条","txt":"严重违反本规定的各金融机构统计及相关部门和人员，有下列行为之一者，由中国人民银行地（市）级（不含地、市）以上机构依据《金融违法行为处罚办法》第十二条对该金融机构给予警告，并处以10万元以上50万元以下罚款，情节严重的，责令该金融机构停业整顿或者吊销经营金融业务许可证；对金融机构直接负责的高级管理人员、其他直接负责的主管人员和直接责任人员，由所在金融机构或者上级金融机构给予记大过直至开除的纪律处分。中国人民银行统计及相关部门人员有下列行为之一者，由所在单位或上级单位给予记大过直至开除的纪律处分。 （一）虚报、瞒报、伪造、篡改金融统计资料数额较大或者占应报数额的份额较多的； （二）虚报、瞒报、伪造、篡改金融统计资料，一年内再次发生的； （三）虚报、瞒报、伪造、篡改金融统计资料，被责令改正而拒不改正的； （四）虚报、瞒报、伪造、篡改金融统计资料，造成严重后果的； （五）中国人民银行总行、分行"},{"i":40,"n":"第四十条","txt":"对于违反本规定，篡改金融统计资料、编造虚假数字骗取荣誉称号、物质奖励或晋升职务的，由作出有关决定的机关或其上级机关、监察机关取消其荣誉称号、追缴物质奖励和撤销晋升的职务。"},{"i":41,"n":"第四十一条","txt":"当事人对本规定第三十八条、三十九所受处罚不服的，可依据有关法律、法规申请行政复议。当事人对行政复议决定不服的，可在接到行政复议决定书之日起15日之内向当地人民法院起诉。"},{"i":42,"n":"第四十二条","txt":"对违反本规定构成犯罪的，提交司法机关依法追究刑事责任。"},{"i":43,"n":"第四十三条","txt":"中国人民银行分行、营业管理部、省会（首府）城市中心支行和各金融机构，可根据本规定制定本辖区、本系统的实施细则，并报中国人民银行总行备案。"},{"i":44,"n":"第四十四条","txt":"本规定由中国人民银行总行负责解释。"},{"i":45,"n":"第四十五条","txt":"本规定自2002年12月15日起施行。1995年12月3日发布的《金融统计管理规定》同时废止。"}],"yinhangbanlijieshouhuiyewuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范银行办理结售汇业务，保障外汇市场平稳运行，根据《中华人民共和国中国人民银行法》、《中华人民共和国外汇管理条例》（以下简称《外汇管理条例》），制定本办法。"},{"i":2,"n":"第二条","txt":"中国人民银行及其分支机构、国家外汇管理局及其分支局（以下简称外汇局）是银行结售汇业务的监督管理机关。"},{"i":3,"n":"第三条","txt":"本办法下列用语的含义： （一）银行是指在中华人民共和国境内依法设立的商业银行、城市信用合作社、农村信用合作社等吸收公众存款的金融机构以及政策性银行； （二）结售汇业务是指银行为客户或因自身经营活动需求办理的人民币与外汇之间兑换的业务，包括即期结售汇业务和人民币与外汇衍生产品业务； （三）即期结售汇业务是指在交易订立日之后两个工作日内完成清算，且清算价格为交易订立日当日汇价的结售汇交易； （四）人民币与外汇衍生产品业务是指远期结售汇、人民币与外汇期货、人民币与外汇掉期、人民币与外汇期权等业务及其组合； （五）结售汇综合头寸是指银行持有的，因银行办理对客和自身结售汇业务、参与银行间外汇市场交易等人民币与外汇间交易而形成的外汇头寸。"},{"i":4,"n":"第四条","txt":"银行办理结售汇业务，应当经外汇局批准。"},{"i":5,"n":"第五条","txt":"银行办理结售汇业务，应当遵守本办法和其他有关结售汇业务的管理规定。"},{"i":6,"n":"第六条","txt":"银行申请办理即期结售汇业务，应当具备下列条件： （一）具有金融业务资格； （二）具备完善的业务管理制度； （三）具备办理业务所必需的软硬件设备； （四）拥有具备相应业务工作经验的高级管理人员和业务人员。"},{"i":7,"n":"第七条","txt":"银行申请办理人民币与外汇衍生产品业务，应当具备下列条件： （一）具有即期结售汇业务资格； （二）具备完善的业务管理制度； （三）拥有具备相应业务工作经验的高级管理人员和业务人员； （四）符合银行业监督管理机构对从事金融衍生产品交易的有关规定。"},{"i":8,"n":"第八条","txt":"银行可以根据经营需要一并申请即期结售汇业务和人民币与外汇衍生产品业务资格。"},{"i":9,"n":"第九条","txt":"银行申请即期结售汇业务或人民币与外汇衍生产品业务资格，应当由其总行统一提出申请，外国银行分行除外。 政策性银行、全国性商业银行申请即期结售汇业务或人民币与外汇衍生产品业务资格，由国家外汇管理局审批；其他银行由所在地国家外汇管理局分局、外汇管理部审批。"},{"i":10,"n":"第十条","txt":"银行分支机构办理即期结售汇业务或人民币与外汇衍生产品业务，应当取得已具备相应业务资格的上级机构授权，并报所在地国家外汇管理局分支局备案。"},{"i":11,"n":"第十一条","txt":"银行办理结售汇业务期间，发生合并或者分立的，新设立的银行应当向外汇局重新申请结售汇业务资格；发生变更名称、变更营业地址、经营结售汇业务的分支机构合并或者分立等情况的，应当自变更之日起30日内报外汇局备案。"},{"i":12,"n":"第十二条","txt":"银行停止办理即期结售汇业务或人民币与外汇衍生产品业务的，应当自停办业务之日起30日内报外汇局备案。"},{"i":13,"n":"第十三条","txt":"银行被依法撤销或者宣告破产的，其结售汇业务资格自动丧失。"},{"i":14,"n":"第十四条","txt":"银行应当建立、健全本行结售汇业务风险管理制度，并建立结售汇业务经营和风险管理定期评估机制。 外汇局对银行办理结售汇业务中执行外汇管理规定的情况实行定期评估。"},{"i":15,"n":"第十五条","txt":"银行应当指定专门部门作为结售汇业务的牵头管理部门，负责督导、协调本行及其分支机构的外汇管理规定执行工作。"},{"i":16,"n":"第十六条","txt":"银行应当加强对结售汇业务管理人员、经办人员、销售人员、交易员以及其他相关业务人员的外汇管理政策培训，确保其具备必要的政策法规知识。"},{"i":17,"n":"第十七条","txt":"银行应当建立结售汇会计科目，区分即期结售汇和人民币与外汇衍生产品，分别核算对客结售汇、自身结售汇和银行间市场交易业务。"},{"i":18,"n":"第十八条","txt":"银行办理结售汇业务时，应当按照“了解业务、了解客户、尽职审查”的原则对相关凭证或商业单据进行审核。国家外汇管理局有明确规定的，从其规定。"},{"i":19,"n":"第十九条","txt":"银行办理人民币与外汇衍生产品业务时，应当与有真实需求背景的客户进行与其风险能力相适应的衍生产品交易，并遵守国家外汇管理局关于客户、产品、交易头寸等方面的规定。"},{"i":20,"n":"第二十条","txt":"银行应当遵守结售汇综合头寸管理规定，在规定时限内将结售汇综合头寸保持在核定限额以内。 银行结售汇综合头寸限额根据国际收支状况、银行外汇业务经营情况以及宏观审慎管理等因素，按照法人监管原则统一核定，外国银行分行视同法人管理。"},{"i":21,"n":"第二十一条","txt":"尚未取得人民币业务资格的外资银行，在取得即期结售汇业务资格以后，应当向中国人民银行当地分支机构申请开立结售汇人民币专用账户，专门用于结售汇业务的人民币往来，不适用本办法第二十条结售汇综合头寸管理规定。"},{"i":22,"n":"第二十二条","txt":"银行办理结售汇业务时，可以根据经营需要自行决定挂牌货币，并应当执行中国人民银行和国家外汇管理局关于银行汇价管理的相关规定。"},{"i":23,"n":"第二十三条","txt":"银行应当及时、准确、完整地向外汇局报送结售汇、综合头寸等数据以及国家外汇管理局规定的其他相关报表和资料，并按要求定期核对和及时纠错。"},{"i":24,"n":"第二十四条","txt":"银行应当建立结售汇单证保存制度，区分业务类型分别保存有关单证，保存期限不得少于5年。"},{"i":25,"n":"第二十五条","txt":"银行应当配合外汇局的监督检查，如实说明有关情况，提供有关文件、资料，不得拒绝、阻碍和隐瞒。"},{"i":26,"n":"第二十六条","txt":"外汇局通过非现场监管和现场检查等方式，加强对银行结售汇业务的监督管理，建立健全银行结售汇业务监管信息档案。"},{"i":27,"n":"第二十七条","txt":"银行未经批准擅自办理结售汇业务的，由外汇局或者有关主管部门依照《外汇管理条例》第四十六条第一款予以处罚。"},{"i":28,"n":"第二十八条","txt":"银行有下列情形之一的，由外汇局依照《外汇管理条例》第四十七条予以处罚： （一）办理结售汇业务，未按规定审核相关凭证或商业单据的； （二）未按规定将结售汇综合头寸保持在核定限额内的； （三）未按规定执行中国人民银行和国家外汇管理局汇价管理规定的。"},{"i":29,"n":"第二十九条","txt":"银行未按规定向外汇局报送结售汇、综合头寸等数据以及国家外汇管理局规定的其他相关报表和资料的，由外汇局依照《外汇管理条例》第四十八条予以处罚。"},{"i":30,"n":"第三十条","txt":"未取得结售汇业务资格的银行因自身需要进行结售汇的，应当通过具有结售汇业务资格的银行办理。"},{"i":31,"n":"第三十一条","txt":"非银行金融机构办理结售汇业务，参照本办法执行，国家外汇管理局另有规定的除外。"},{"i":32,"n":"第三十二条","txt":"本办法由中国人民银行负责解释。"},{"i":33,"n":"第三十三条","txt":"本办法自2014年8月1日起施行。此前规定与本办法不一致的，以本办法为准。《外汇指定银行办理结汇、售汇业务管理暂行办法》（中国人民银行令〔2002〕4号发布）、《中国人民银行关于结售汇业务管理工作的通知》（银发〔2004〕62号）同时废止。"}],"yinhangkaqingsuanjigouguanlibanfa":[{"i":1,"n":"第一条","txt":"为促进我国银行卡清算市场健康发展，规范银行卡清算机构管理，保护当事人合法权益，根据《中华人民共和国中国人民银行法》、《国务院关于实施银行卡清算机构准入管理的决定》（国发〔2015〕22号），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称银行卡清算机构是指经批准，依法取得银行卡清算业务许可证，专门从事银行卡清算业务的企业法人。"},{"i":3,"n":"第三条","txt":"仅为跨境交易提供外币的银行卡清算服务的境外机构（以下简称境外机构），原则上可以不在中华人民共和国境内设立银行卡清算机构，但对境内银行卡清算体系稳健运行或公众支付信心具有重要影响的，应当在中华人民共和国境内设立法人，依法取得银行卡清算业务许可证。"},{"i":4,"n":"第四条","txt":"银行卡清算机构应当遵守国家安全、国家网络安全相关法律法规，确保银行卡清算业务基础设施的安全、稳定和高效运行。银行卡清算业务基础设施应满足国家信息安全等级保护要求，使用经国家密码管理机构认可的商用密码产品，符合国家及行业相关金融标准，且其核心业务系统不得外包。"},{"i":5,"n":"第五条","txt":"为保障金融信息安全，境内发行的银行卡在境内使用时，其相关交易处理应当通过境内银行卡清算业务基础设施完成。"},{"i":6,"n":"第六条","txt":"银行卡清算机构与境内入网发卡机构或收单机构（以下简称入网机构）的银行卡交易资金清算应当通过境内银行以人民币完成资金结算，为跨境交易提供外币的银行卡清算服务的情形除外。"},{"i":7,"n":"第七条","txt":"银行卡清算机构和境外机构应当对从银行卡清算服务中获取的身份信息、账户信息、交易信息以及其他相关敏感信息等当事人金融信息予以保密；除法律法规另有规定外，未经当事人授权不得对外提供。 银行卡清算机构和境外机构为处理银行卡跨境交易且经当事人授权，向境外发卡机构或收单机构传输境内收集的相关个人金融信息的，应当通过业务规则及协议等有效措施，要求境外发卡机构或收单机构为所获得的个人金融信息保密。"},{"i":8,"n":"第八条","txt":"银行卡清算机构和境外机构应当遵守法律法规的有关规定，遵循诚信和公平竞争的原则，不得损害国家利益和社会公共利益。"},{"i":9,"n":"第九条","txt":"银行卡清算机构和境外机构应当遵守反洗钱和反恐怖融资法律法规和相关规定，履行反洗钱和反恐怖融资义务。 银行卡清算机构办理银行卡跨境交易，应当遵守国家外汇及跨境人民币管理的有关规定。"},{"i":10,"n":"第十条","txt":"中国人民银行、中国银行业监督管理委员会按照分工，依法对银行卡清算机构和境外机构实施监督管理，并加强沟通协调，共同防范银行卡清算业务系统性风险。"},{"i":11,"n":"第十一条","txt":"银行卡清算机构的注册资本不低于10亿元人民币，出资人应当以自有资金出资，不得以委托资金、债务资金等非自有资金出资。"},{"i":12,"n":"第十二条","txt":"银行卡清算机构50%以上的董事（含董事长、副董事长）和全部高级管理人员应当具备相应的任职专业知识，5年以上银行、支付或者清算的从业经验和良好的品行、声誉，以及担任职务所需的独立性。 除《中华人民共和国公司法》规定的情形外，有以下情形之一的，不得担任银行卡清算机构的董事、高级管理人员： （一）有重大过失或犯罪记录的。 （二）因违法行为或者违纪行为被金融监管机构取消任职资格的董事、监事、高级管理人员，自被取消任职资格之日起未逾5年的。 （三）曾经担任被金融监管机构行政处罚单位的董事、监事或者高级管理人员，并对被行政处罚负有个人责任或者直接领导责任，自执行期满未逾2年的。"},{"i":13,"n":"第十三条","txt":"申请人向中国人民银行提出银行卡清算机构筹备申请的，应当提交下列申请材料： （一）筹备申请书，载明公司的名称、住所、注册资本等。 （二）企业法人营业执照复印件和公司章程，申请人为外商投资企业的，还应当提交外商投资企业批准证书复印件。 （三）证明其资本实力符合要求的材料及相关证明。 （四）真实、完整、公允的最近一年财务会计报告，设立时间不足一年的除外。 （五）出资人出资决议，出资金额、方式及资金来源，以及出资人之间关联关系的说明。 （六）主要出资人和其他单一持股比例超过10%的出资人的资质证明材料，包括但不限于营业执照、最近三年财务会计报告、无重大违法违规记录证明和从业经历证明等。 出资人为境内银行业金融机构的，应当提供金融业务许可证复印件和中国银行业监督管理委员会允许其投资银行卡清算机构的批准文件。 （七）关于公司实际控制人情况的说明。 （八）公司组织架构设置、财务独立性、风控体系构建及"},{"i":14,"n":"第十四条","txt":"中国人民银行收到银行卡清算机构筹备申请的，应当自受理之日起10日内，将申请材料送交中国银行业监督管理委员会。中国银行业监督管理委员会应当自收到申请材料之日起30日内出具书面意见，送交中国人民银行。"},{"i":15,"n":"第十五条","txt":"中国人民银行根据有利于银行卡清算市场公平竞争和健康发展的审慎性原则，以及中国银行业监督管理委员会的意见，自受理之日起90日内作出批准或不批准筹备的决定，并书面通知申请人。决定不批准的，应当说明理由。"},{"i":16,"n":"第十六条","txt":"银行卡清算机构筹备期为获准筹备之日起1年。申请人在规定筹备期内未完成筹备工作的，应当说明理由，经中国人民银行批准，可以延长3个月。"},{"i":17,"n":"第十七条","txt":"申请人应当在筹备期届满前向中国人民银行提出开业申请，提交下列申请材料： （一）开业申请书，载明公司的名称、住所、注册资本及营运资金等。 （二）银行卡清算业务标准体系和业务规则的具体内容及详细说明。 （三）银行卡清算业务基础设施架构报告、建设报告、业务连续性计划及应急预案。 （四）银行卡清算业务基础设施标准符合和技术安全证明材料。 （五）拟任董事和高级管理人员的任职资格申请材料，包括但不限于履历说明及学历、技术职称、具备担任职务所需的独立性说明，无犯罪记录和未受处罚等相关证明材料。 （六）内部控制、风险防范和合规机制材料。 （七）信息安全保障机制材料，包括但不限于银行卡支付网络信息安全标准、入网安全管理机制、个人信息安全保护机制、核心业务系统信息安全等级保护定级和测评报告、独立的信息安全风险评估报告、信息安全管理体系等。 （八）反洗钱和反恐怖融资措施验收材料。 （九）筹备工作完成情况总结"},{"i":18,"n":"第十八条","txt":"中国人民银行和中国银行业监督管理委员会可以采取查询有关国家机关、国家信用信息共享交换平台、征信机构、拟任职人员曾任职机构，开展专业知识能力测试等方式对拟任职董事、高级管理人员是否符合任职资格条件进行审查。"},{"i":19,"n":"第十九条","txt":"中国人民银行收到银行卡清算机构开业申请的，参照本办法第十四条和第十五条　的规定，作出批准或不批准开业的决定，并书面通知申请人。决定批准的，颁发开业核准文件和银行卡清算业务许可证，并予以公告；决定不批准的，说明理由。"},{"i":20,"n":"第二十条","txt":"银行卡清算机构未在规定期限内开业的，开业批准文件失效，由中国人民银行办理开业批准注销手续，收回其《银行卡清算业务许可证》，并予以公告。"},{"i":21,"n":"第二十一条","txt":"境外机构为跨境交易提供外币的银行卡清算服务是指： （一）授权境内收单机构或与境内银行卡清算机构合作，实现境外发行的银行卡在境内的使用。 （二）授权境内发卡机构发行仅限于境外使用的外币银行卡。"},{"i":22,"n":"第二十二条","txt":"境外机构与境内银行卡清算机构合作授权发行银行卡的，应当采用境内银行卡清算机构的发卡行标识代码。境外机构不得通过合作方式变相从事人民币的银行卡清算业务。"},{"i":23,"n":"第二十三条","txt":"境外机构为跨境交易提供外币的银行卡清算服务的，应当在提供服务前30日向中国人民银行和中国银行业监督管理委员会报告，并提交下列材料： （一）机构基本信息。 （二）在母国接受监管的情况。 （三）参与国家或国际支付系统的说明。 （四）本机构内部控制、风险防范和信息安全保障机制。 （五）本机构反洗钱和反恐怖融资内部控制制度、组织架构以及开展相关工作的情况说明。 （六）银行卡清算业务基础设施运行情况。 （七）银行卡清算业务规则。 （八）业务发展规划、与境内机构合作的情况说明。 （九）持卡人和商户权益保护策略及机制。 （十）其他需专门说明的事项及材料真实性声明。 上述材料为外国文字的，应当同时提供中文译本，并以中文译本为准。境外机构基本信息发生变更的，应当自变更之日起30日内向中国人民银行和中国银行业监督管理委员会报告。"},{"i":24,"n":"第二十四条","txt":"中国人民银行在收到境外机构报告之日起30日内在网站上公示境外机构基本信息。"},{"i":25,"n":"第二十五条","txt":"银行卡清算机构有下列变更事项之一的，应当按规定向中国人民银行提交变更申请材料： （一）设立分支机构。 （二）分立或者合并。 （三）变更公司名称或者公司章程。 （四）变更注册资本。 （五）变更主要出资人或其他单一持股比例超过10%的出资人。 （六）变更银行卡清算品牌。 （七）更换董事和高级管理人员。 中国人民银行收到上述申请材料的，应当参照本办法第十四条和第十五条的规定，作出批准或不批准的决定，并书面通知申请人。 银行卡清算机构变更单一持股比例超过5%以上的出资人，且不属于上述第五项所规定情形的，应当提前向中国人民银行和中国银行业监督管理委员会提交变更情况书面报告。"},{"i":26,"n":"第二十六条","txt":"外国投资者并购银行卡清算机构，应当执行外资并购境内基础设施安全审查的管理规定。"},{"i":27,"n":"第二十七条","txt":"银行卡清算机构终止部分或全部银行卡清算业务及解散的，应当向中国人民银行提交下列申请材料： （一）终止业务申请表，载明机构的名称和住所等。 （二）股东大会（股东会）或董事会终止业务的决议。 （三）终止业务的评估报告。 （四）与入网机构达成的业务终止处置方案。 （五）终止业务的应急预案。 （六）涉及持卡人和商户权益保护的处理措施。 （七）其他需专门说明的事项及申请材料真实性声明。 中国人民银行收到上述申请材料的，应当参照本办法第十四条和第十五条的规定，作出批准或不批准的决定。中国人民银行批准银行卡清算机构终止全部银行卡清算业务及解散的，应当收回银行卡清算业务许可证。"},{"i":28,"n":"第二十八条","txt":"境外机构终止为跨境交易提供外币的银行卡清算服务的，应当至少提前30日向中国人民银行和中国银行业监督管理委员会报告，提交下列材料： （一）终止业务的评估报告。 （二）与入网机构达成的业务终止处置方案。 （三）终止业务的应急预案。 （四）涉及持卡人和商户权益保护的处理措施。 （五）其他需专门说明的事项及材料真实性声明。"},{"i":29,"n":"第二十九条","txt":"中国人民银行、中国银行业监督管理委员会的工作人员有下列情形之一的，依法给予行政处分。涉嫌犯罪的，依法移送司法机关追究刑事责任： （一）违反规定审查批准银行卡清算业务的申请、变更、终止等事项的。 （二）泄露知悉的国家秘密或商业秘密的。 （三）滥用职权、玩忽职守等其他违反法律法规的行为。"},{"i":30,"n":"第三十条","txt":"银行卡清算机构有以下情形的，由中国人民银行会同中国银行业监督管理委员会，责令限期改正，并给予警告或者处1万元以上3万元以下的罚款；情节严重的，根据《中华人民共和国中国人民银行法》第四十六条　的规定进行处罚： （一）未按规定建立银行卡清算业务标准体系、业务规则、内部控制、风险防范和信息安全保障机制的。 （二）未按规定报告相关事项的。 （三）转让、出租、出借银行卡清算业务许可证的。 （四）超出规定范围经营业务的。 （五）任命不符合规定的董事、高级管理人员的。 （六）未按规定申请变更事项或擅自设立分支机构的。 （七）拒绝或者阻碍相关检查、监督管理的。 （八）限制发卡机构或收单机构与其他银行卡清算机构合作的。 （九）银行卡清算业务基础设施出现重大风险的。 （十）无正当理由限制、拒绝银行卡交易，或中断、终止银行卡清算业务的。 （十一）提供虚假的或者隐瞒重要事实的信息或资料的。 （十二）违反有关信"},{"i":31,"n":"第三十一条","txt":"银行卡清算机构和境外机构违反反洗钱和反恐怖融资规定的，按照有关法律法规进行处理。"},{"i":32,"n":"第三十二条","txt":"申请人隐瞒有关情况或者提供虚假材料申请银行卡清算业务许可的，中国人民银行不予受理或者不予行政许可，并给予警告，申请人在1年内不得再次申请银行卡清算业务许可。 被许可人以欺骗、贿赂等不正当手段取得银行卡清算业务许可的，中国人民银行依法收回银行卡清算业务许可证，并给予行政处罚，申请人在3年内不得再次申请银行卡清算业务许可；涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"未经中国人民银行批准，擅自从事银行卡清算业务，伪造、变造银行卡清算业务许可证，由中国人民银行责令其终止银行卡清算业务，并依据《中华人民共和国中国人民银行法》第四十六条的规定进行处罚；涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"本办法所称银行卡清算业务标准体系包括卡片标准、受理标准、信息交换标准、业务处理标准和信息安全标准等内容。"},{"i":35,"n":"第三十五条","txt":"本办法所称银行卡清算核心业务系统是指业务处理系统、风险管理系统、差错处理系统、信息服务系统及其灾备系统等。 业务处理系统是指银行卡清算机构提供的银行卡清算交易转接系统和清算系统。 风险管理系统是指银行卡清算机构提供的对银行卡清算业务参与主体和服务内容进行风险识别、评估及管控的系统。 差错处理系统是指银行卡清算机构提供的用于入网机构间提交差错交易、争议案件以解决交易差错、争议及疑问的电子处理系统。 信息服务系统是指银行卡清算机构为入网机构提供当日交易查询、历史交易查询、交易统计分析、清算文件上送与下载、发卡行标识代码信息下发、汇率信息查询与下发等信息服务的辅助系统。 灾备系统是指银行卡清算机构为应对异常灾难的发生提前建立的相关系统的备份系统。"},{"i":36,"n":"第三十六条","txt":"《国务院关于实施银行卡清算机构准入管理的决定》施行前已经依法在中华人民共和国境内从事银行卡清算业务的境内机构，应当凭原批准从事银行卡清算业务的文件，参照本办法第十七条申请银行卡清算业务许可证。 《国务院关于实施银行卡清算机构准入管理的决定》施行前仅为跨境交易提供外币的银行卡清算服务的境外机构，应当参照本办法第二十三条进行报告。"},{"i":37,"n":"第三十七条","txt":"本办法由中国人民银行会同中国银行业监督管理委员会解释。"},{"i":38,"n":"第三十八条","txt":"本办法自发布之日起施行。"}],"yinhangjianzhaiquanshichangzhaiquandengjituoguanji1efd98":[{"i":1,"n":"第一条","txt":"为规范债券登记、托管和结算行为，保护投资者合法权益，维护债券登记、托管和结算秩序，促进债券市场健康发展，依据《中华人民共和国中国人民银行法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"固定收益类有价证券（以下简称债券）在银行间债券市场的登记、托管和结算适用本办法。 商业银行柜台记账式国债的登记、托管和结算适用《商业银行柜台记账式国债交易管理办法》。"},{"i":3,"n":"第三条","txt":"债券登记、托管和结算业务遵循安全、高效的原则，采取全国统一的运营管理模式。"},{"i":4,"n":"第四条","txt":"中国人民银行依法对银行间债券市场债券登记托管结算机构和债券登记、托管和结算业务进行监督管理。"},{"i":5,"n":"第五条","txt":"本办法所称债券登记托管结算机构是指在银行间债券市场专门办理债券登记、托管和结算业务的法人。 中央国债登记结算有限责任公司是中国人民银行指定的债券登记托管结算机构。"},{"i":6,"n":"第六条","txt":"债券登记托管结算机构承担债券中央登记、一级托管及结算职能；经中国人民银行批准的柜台交易承办银行承担商业银行柜台记账式国债的二级托管职能。"},{"i":7,"n":"第七条","txt":"债券登记托管结算机构在债券登记、托管和结算业务中履行下列职能： （一）设立和管理债券账户； （二）债券登记； （三）债券托管； （四）债券结算； （五）代理拨付债券兑付本息和相关收益资金； （六）跨市场交易流通债券的总托管； （七）提供债券等质押物的管理服务; （八）代理债券持有人向债券发行人依法行使债券权利； （九）依法提供与债券登记、托管和结算相关的信息、查询、咨询、培训服务； （十）监督柜台交易承办银行的二级托管业务； （十一）中国人民银行规定的其他职能。"},{"i":8,"n":"第八条","txt":"债券登记托管结算机构应当采取下列措施保证业务的正常开展： （一）具有专用的债券登记、托管、结算系统和设备，强化技术手段以保障数据安全； （二）建立系统故障应急处理机制和灾难备份机制； （三）完善公司治理，建立健全内部控制机制和风险管理制度，定期对登记、托管和结算情况进行内部稽核和检查； （四）制定债券登记、托管和结算相关业务规则与操作规程，加强对关键岗位的管理。"},{"i":9,"n":"第九条","txt":"下列事项，债券登记托管结算机构应当报中国人民银行批准： （一）章程的制定和修改，并购、合并、重组、分立等重大事项； （二）内部控制制度、风险管理制度、业务规则以及应急预案的制定和修改； （三）开展新业务，变更登记、托管和结算业务模式； （四）与境内外其他市场中介机构有关债券登记、托管和结算的业务合作； （五）中国人民银行要求的其他事项。"},{"i":10,"n":"第十条","txt":"下列事项，债券登记托管结算机构应当报中国人民银行备案： （一）制定和修改中长期业务发展规划； （二）高级管理人员变动； （三）中国人民银行要求的其他事项。"},{"i":11,"n":"第十一条","txt":"债券登记托管结算机构应当妥善保存债券登记、托管和结算的原始凭证及债券账务数据等有关文件和资料，其保存时间至少为债券到期后20年。"},{"i":12,"n":"第十二条","txt":"债券登记托管结算机构根据业务发展需要，可以编制并定期发布债券登记、托管和结算业务相关信息。债券登记托管结算机构向其他组织和个人提供上述信息须符合中国人民银行有关规定。"},{"i":13,"n":"第十三条","txt":"债券登记托管结算机构对债券持有人有关债券登记、托管和结算的数据和资料负有保密义务，但有下列情形的，应当依法予以办理： （一）债券持有人查询本人的债券账务资料； （二）受托人持债券持有人的书面委托查询有关债券账务资料； （三）人民法院、人民检察院、公安机关等依照法定的程序和条件进行查询和取证； （四）法律法规规定的其他情形。 债券登记托管结算机构应当方便债券持有人及时获得其债券账户记录。"},{"i":14,"n":"第十四条","txt":"债券登记托管结算机构应当公开与债券登记、托管和结算业务相关的收费项目和标准。 债券登记托管结算机构制定或者调整收费项目和标准时，应当充分征求中国银行间市场交易商协会（以下简称交易商协会）、债券发行人和债券持有人的意见，并将征求意见的情况向中国人民银行报告。"},{"i":15,"n":"第十五条","txt":"债券登记托管结算机构应当与债券发行人和债券持有人分别签订相关服务协议，明确双方的权利义务。 债券登记托管结算机构应当在充分征求交易商协会、债券发行人和债券持有人意见的基础上制定相关服务协议的文本，并将征求意见的情况向中国人民银行报告。"},{"i":16,"n":"第十六条","txt":"债券登记托管结算机构应当对债券登记、托管和结算活动进行日常监测，发现异常情况、重大业务风险和技术风险以及重大违法违规行为的，应当及时向中国人民银行报告并进行相应处理，同时抄送交易商协会。 债券登记托管结算机构应当与全国银行间同业拆借中心相互配合，建立债券市场一线监控制度。"},{"i":17,"n":"第十七条","txt":"债券登记托管结算机构应当于每月前5个工作日内向中国人民银行报送上月债券发行、登记、托管、结算等有关数据和统计信息，并于每年度结束后20个工作日内向中国人民银行报送债券登记、托管和结算业务的年度工作报告。 交易商协会、债券登记托管结算机构和全国银行间同业拆借中心应当按照中国人民银行有关规定建立信息和数据交流机制。"},{"i":18,"n":"第十八条","txt":"债券登记托管结算机构应当按有关规定及时公布债券登记、托管和结算业务有关统计信息，但不得泄露非公开信息。"},{"i":19,"n":"第十九条","txt":"债券账户是指在债券登记托管结算机构开立的用以记载债券持有人所持有债券的品种、数量及其变动等情况的电子簿记账户。"},{"i":20,"n":"第二十条","txt":"债券持有人通过债券账户持有债券。债券持有人持有债券以其债券账户内记载的债券托管余额为准。债券持有人对债券账户记载内容有异议的，债券登记托管结算机构应当及时复查并予以答复；因债券登记托管结算机构工作失误造成数据差错并给债券持有人带来损失的，债券登记托管结算机构应当承担相应法律责任。"},{"i":21,"n":"第二十一条","txt":"债券登记托管结算机构应当根据分类设置、集中管理的原则制定债券账户管理制度。"},{"i":22,"n":"第二十二条","txt":"债券持有人开立债券账户应当按照中国人民银行的规定向债券登记托管结算机构提出申请，且应当保证所提交的开户资料真实、准确、完整。 债券账户采用实名制，不得出租、出借或转让。"},{"i":23,"n":"第二十三条","txt":"债券账户分为自营账户和代理总账户。"},{"i":24,"n":"第二十四条","txt":"一个投资者只能开立一个自营账户，中国人民银行另有规定的除外。 具有法人资格的投资者应当以法人名义开立自营账户；经法人授权的商业银行分支机构可以分支机构的名义开立自营账户；证券投资基金等非法人机构投资者可按中国人民银行规定单独开立自营账户。"},{"i":25,"n":"第二十五条","txt":"柜台交易承办银行和其他交易场所证券登记托管结算机构等可以在债券登记托管结算机构开立代理总账户，用于记载其二级托管的全部债券余额。 柜台交易承办银行和其他交易场所证券登记托管结算机构等为二级托管账户持有人确认的托管债券总额应当与其代理总账户记载的债券余额相等，且代理总账户内的债券应当与其自营的债券严格分开。"},{"i":26,"n":"第二十六条","txt":"债券持有人可申请注销其账户。申请注销时，债券登记托管结算机构应当在确定该账户已无债券托管，且无未到期的回购等未了结的债权债务、质押以及冻结等情形时方可予以办理。"},{"i":27,"n":"第二十七条","txt":"债券登记是指债券登记托管结算机构以簿记方式依法确认债券持有人持有债券事实的行为。"},{"i":28,"n":"第二十八条","txt":"债券发行结束后，债券发行人应当向债券登记托管结算机构提供相关机构和组织出具的债券发行审批、核准、注册等文件复印件、有关发行文件及相关资料。债券登记托管结算机构应当根据债券发行募集资金收讫确认及时办理债券登记。涉及二级托管账户的，柜台交易承办银行和其他交易场所证券登记托管结算机构等为二级托管账户持有人办理债券登记。"},{"i":29,"n":"第二十九条","txt":"债券存续期内，因债券发行人预先约定或债券持有人合法要求而派生的债券，债券登记托管结算机构应当根据发行文件和债券持有人的委托，办理派生债券的登记。"},{"i":30,"n":"第三十条","txt":"债券因交易结算、非交易过户、选择权行使等原因引起债券账户余额变化的，债券登记托管结算机构应当办理变更登记。涉及二级托管账户的，柜台交易承办银行和其他交易场所证券登记托管结算机构等应当为二级托管账户持有人办理变更登记。 因分立、合并或解散等原因导致债券发行人变更的，债务承继人应当及时向债券登记托管结算机构提交相关证明材料，债券登记托管结算机构应当依法及时办理变更登记。"},{"i":31,"n":"第三十一条","txt":"债券登记托管结算机构可依法为债券持有人提供债券质押登记服务，对相应债券进行冻结；或依照法律法规对债券进行冻结。债券被冻结时，债券登记托管结算机构应当在相应债券账户内加以明确标记，以表明债券权利受到限制。"},{"i":32,"n":"第三十二条","txt":"因到期兑付、提前兑付、选择权行使等原因导致债权债务终止的，债券登记托管结算机构应当办理债券注销登记；涉及二级托管账户的，柜台交易承办银行和其他交易场所证券登记托管结算机构等应当及时办理托管债券余额注销。 仍处于冻结状态的债券到期兑付时，债券登记托管结算机构应当提存其本息，待相关当事人出具有效法律文件后，按有关规定办理。"},{"i":33,"n":"第三十三条","txt":"债券托管是指债券登记托管结算机构对债券持有人持有的债券进行集中保管，并对其持有债券的相关权益进行管理和维护的行为。"},{"i":34,"n":"第三十四条","txt":"债券持有人应当委托债券登记托管结算机构托管其持有的债券。 债券托管关系自债券登记托管结算机构为债券持有人开立债券账户后成立，至债券账户注销终止。"},{"i":35,"n":"第三十五条","txt":"债券登记托管结算机构应当对债券持有人托管的债券采取安全有效的管理措施，保证其托管账务的真实、准确、完整和安全。债券登记托管结算机构对所托管的债券不享有任何性质的所有权，不得挪用所托管的债券。 债券登记托管结算机构出现破产、解散、分立、合并及撤销等情况时，债券持有人在该机构所托管的债券和其他资产不参与资产清算。"},{"i":36,"n":"第三十六条","txt":"跨市场交易的债券持有人可将其持有的跨市场交易流通债券进行转托管。债券登记托管结算机构应当及时为其提供转托管服务。"},{"i":37,"n":"第三十七条","txt":"债券发行人委托债券登记托管结算机构办理债券兑付本息或相关收益资金分配时，债券发行人应当及时、足额向债券登记托管结算机构支付相关款项，债券登记托管结算机构收到相关款项后应当及时办理；债券发行人未履行上述支付义务的，债券登记托管结算机构有权推迟办理，债券发行人应当及时向市场说明有关情况。"},{"i":38,"n":"第三十八条","txt":"债券结算是指在确认结算指令的基础上进行的债券过户。"},{"i":39,"n":"第三十九条","txt":"投资者或其代理人应当根据债券交易合同的约定及时发送债券结算指令，其相应的债券账户应当有足够余额用于结算。"},{"i":40,"n":"第四十条","txt":"债券登记托管结算机构应当明确结算指令的形式和传递方式，并对其采取有效的识别措施。 债券登记托管结算机构应当根据有效结算指令及时为投资者或其代理人办理债券结算，债券结算一旦完成不可撤销。"},{"i":41,"n":"第四十一条","txt":"银行间债券市场债券结算机制包括全额和净额两种。净额业务有关规定由中国人民银行另行规定。"},{"i":42,"n":"第四十二条","txt":"债券结算和资金结算可采用券款对付、见券付款、见款付券和纯券过户等结算方式。 券款对付是指结算双方同步办理债券过户和资金支付并互为条件的结算方式。 见券付款是指收券方以付券方应付债券足额为资金支付条件的结算方式。 见款付券是指付券方以收到收券方支付的足额资金为债券过户条件的结算方式。 纯券过户是指结算双方的债券过户与资金支付相互独立的结算方式。 债券结算和资金结算的风险由结算双方自行承担。"},{"i":43,"n":"第四十三条","txt":"已进入债券结算过程处于待付状态的资金和债券，以及该笔结算涉及的担保物只能用于该笔结算，不能被强制执行。"},{"i":44,"n":"第四十四条","txt":"债券登记托管结算机构可为投资者的债券借贷提供便利，以保证债券结算的顺利进行，有关办法由中国人民银行另行规定。"},{"i":45,"n":"第四十五条","txt":"交易流通受到限制的债券办理转让过户，应当符合相关法律、法规和有关主管部门的规定。"},{"i":46,"n":"第四十六条","txt":"办理扣划、继承、抵债、赠与等非交易过户的，债券登记托管结算机构应当要求当事人提交合法有效的法律文件。"},{"i":47,"n":"第四十七条","txt":"债券登记托管结算机构及相关工作人员有下列情形之一的，由中国人民银行按照《中华人民共和国中国人民银行法》第四十六条的规定进行处罚： （一）工作失职，给债券发行人和债券持有人造成严重损失； （二）挪用债券持有人托管债券和资金； （三）篡改债券账户有关账务数据； （四）泄露债券持有人账户信息； （五）其他违反本办法的行为。 违反本办法，构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"债券发行人和债券持有人违反本办法，由中国人民银行按照《中华人民共和国中国人民银行法》第四十六条的规定进行处罚，构成犯罪的，依法追究刑事责任。"},{"i":49,"n":"第四十九条","txt":"本办法由中国人民银行负责解释。"},{"i":50,"n":"第五十条","txt":"本办法自2009年5月4日起施行。"}],"yinhangjianzhaiquanshichangfeijinrongqiyezhaiwuron6465f4":[{"i":1,"n":"第一条","txt":"为进一步完善银行间债券市场管理，促进非金融企业直接债务融资发展，根据《中华人民共和国中国人民银行法》及相关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称非金融企业债务融资工具（以下简称债务融资工具），是指具有法人资格的非金融企业（以下简称企业）在银行间债券市场发行的，约定在一定期限内还本付息的有价证券。"},{"i":3,"n":"第三条","txt":"债务融资工具发行与交易应遵循诚信、自律原则。"},{"i":4,"n":"第四条","txt":"企业发行债务融资工具应在中国银行间市场交易商协会（以下简称交易商协会）注册。"},{"i":5,"n":"第五条","txt":"债务融资工具在中央国债登记结算有限责任公司（以下简称中央结算公司）登记、托管、结算。"},{"i":6,"n":"第六条","txt":"全国银行间同业拆借中心（以下简称同业拆借中心）为债务融资工具在银行间债券市场的交易提供服务。"},{"i":7,"n":"第七条","txt":"企业发行债务融资工具应在银行间债券市场披露信息。信息披露应遵循诚实信用原则，不得有虚假记载、误导性陈述或重大遗漏。"},{"i":8,"n":"第八条","txt":"企业发行债务融资工具应由金融机构承销。企业可自主选择主承销商。需要组织承销团的，由主承销商组织承销团。"},{"i":9,"n":"第九条","txt":"企业发行债务融资工具应由在中国境内注册且具备债券评级资质的评级机构进行信用评级。"},{"i":10,"n":"第十条","txt":"为债务融资工具提供服务的承销机构、信用评级机构、注册会计师、律师等专业机构和人员应勤勉尽责，严格遵守执业规范和职业道德，按规定和约定履行义务。 上述专业机构和人员所出具的文件含有虚假记载、误导性陈述和重大遗漏的，应当就其负有责任的部分承担相应的法律责任。"},{"i":11,"n":"第十一条","txt":"债务融资工具发行利率、发行价格和所涉费率以市场化方式确定，任何商业机构不得以欺诈、操纵市场等行为获取不正当利益。"},{"i":12,"n":"第十二条","txt":"债务融资工具投资者应自行判断和承担投资风险。"},{"i":13,"n":"第十三条","txt":"交易商协会依据本办法及中国人民银行相关规定对债务融资工具的发行与交易实施自律管理。交易商协会应根据本办法制定相关自律管理规则，并报中国人民银行备案。"},{"i":14,"n":"第十四条","txt":"同业拆借中心负责债务融资工具交易的日常监测，每月汇总债务融资工具交易情况向交易商协会报送。"},{"i":15,"n":"第十五条","txt":"中央结算公司负责债务融资工具登记、托管、结算的日常监测，每月汇总债务融资工具发行、登记、托管、结算、兑付等情况向交易商协会报送。"},{"i":16,"n":"第十六条","txt":"交易商协会应每月向中国人民银行报告债务融资工具注册汇总情况、自律管理工作情况、市场运行情况及自律管理规则执行情况。"},{"i":17,"n":"第十七条","txt":"交易商协会对违反自律管理规则的机构和人员，可采取警告、诫勉谈话、公开谴责等措施进行处理。"},{"i":18,"n":"第十八条","txt":"中国人民银行依法对交易商协会、同业拆借中心和中央结算公司进行监督管理。 交易商协会、同业拆借中心和中央结算公司应按照中国人民银行的要求，及时向中国人民银行报送与债务融资工具发行和交易等有关的信息。"},{"i":19,"n":"第十九条","txt":"对违反本办法规定的机构和人员，中国人民银行可依照《中华人民共和国中国人民银行法》第四十六条规定进行处罚，构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"短期融资券适用本办法。"},{"i":21,"n":"第二十一条","txt":"本办法自2008年4月15日起施行。《短期融资券管理办法》（中国人民银行令〔2005〕第2号）、《短期融资券承销规程》和《短期融资券信息披露规程》（中国人民银行公告〔2005〕第10号）同时终止执行。"}],"yinhangjianwaihuishichangguanliguiding":[{"i":1,"n":"第一条","txt":"为规范和发展外汇市场，保障各方合法权益，维护外汇市场秩序和社会公共利益，促进外汇市场服务实体经济，扩大高水平对外开放，根据《中华人民共和国中国人民银行法》《中华人民共和国外汇管理条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称银行间外汇市场是指通过中国外汇交易中心（以下简称外汇交易中心）进行人民币与外币交易的市场。"},{"i":3,"n":"第三条","txt":"具有结汇、售汇业务经营资格的境内金融机构之间开展人民币与外币交易应通过外汇交易中心进行。 境外金融机构参与银行间外汇市场应遵守中国人民银行和国家外汇管理局有关规定。"},{"i":4,"n":"第四条","txt":"境内金融机构可选择双边清算或通过银行间市场清算所股份有限公司（以下简称上海清算所）进行集中清算。"},{"i":5,"n":"第五条","txt":"中国人民银行和国家外汇管理局负责监督管理银行间外汇市场。"},{"i":6,"n":"第六条","txt":"银行间外汇市场交易应遵循公开、公平、公正和诚实信用的原则，禁止欺诈、操纵市场、内幕交易等影响银行间外汇市场秩序和损害市场参与者合法权益的行为。"},{"i":7,"n":"第七条","txt":"外汇交易中心和上海清算所在中国人民银行、国家外汇管理局监管下，在规定范围内分别组织银行间外汇市场交易和清算，制定业务规则，提供设施和服务。"},{"i":8,"n":"第八条","txt":"外汇交易中心和上海清算所应当加强业务协作，开展数据交互，保障业务和系统安全高效运行，不断提升设施服务水平。"},{"i":9,"n":"第九条","txt":"银行间外汇市场如发生重大异常、系统故障等，对外汇市场正常秩序和市场公平可能造成重大影响的，外汇交易中心和上海清算所应当立即采取应急措施并及时向中国人民银行、国家外汇管理局报告。"},{"i":10,"n":"第十条","txt":"境内金融机构以法人身份参与银行间外汇市场，并应先取得结汇、售汇业务经营资格。中国人民银行、国家外汇管理局另有规定的除外。"},{"i":11,"n":"第十一条","txt":"外汇交易中心和上海清算所分别负责金融机构参与银行间外汇市场交易资格、清算资格管理，并履行相应的市场管理职责。"},{"i":12,"n":"第十二条","txt":"金融机构应建立健全内部管理制度和风险控制机制，实行前中后台分离机制。"},{"i":13,"n":"第十三条","txt":"金融机构应指派具备必要能力的交易员代表其开展银行间外汇市场报价、交易，加强对交易行为的规范和管理。"},{"i":14,"n":"第十四条","txt":"金融机构应在交易达成后以安全高效的方式尽快完成交易确认，自主决定参与交易冲销、同步交收等风险缓释服务，提升结算效率，缓释交易风险。"},{"i":15,"n":"第十五条","txt":"金融机构开展银行间人民币外汇衍生品交易，应当与交易对手签署衍生产品交易主协议。"},{"i":16,"n":"第十六条","txt":"境内货币经纪公司可为银行间人民币外汇衍生品等提供经纪服务。 金融机构通过境内货币经纪公司协商达成人民币外汇衍生品交易意向后，应即时通过外汇交易中心确认后方可达成交易。"},{"i":17,"n":"第十七条","txt":"经中国人民银行授权，外汇交易中心可根据符合条件的金融机构报价计算、形成并公布人民币汇率中间价，按照相关规则计算并发布人民币汇率收盘价、参考汇率等重要数据指标。 参与中间价报价的金融机构不得向其他机构和个人提供中间价报价信息。"},{"i":18,"n":"第十八条","txt":"银行间外汇市场即期交易价格实行日最大浮动幅度管理机制，报价与成交不得超过相应货币对中间价的上下波动幅度。上下波动幅度由中国人民银行确定并公布。"},{"i":19,"n":"第十九条","txt":"外汇交易中心应根据服务实体经济的需求丰富人民币与外币交易品种、币种、方式，完善交易时间安排。 （一）交易品种包括即期、远期、外汇掉期、货币掉期、期权等。 （二）交易方式包括询价、竞价、撮合，以及经批准的其他交易方式。"},{"i":20,"n":"第二十条","txt":"上海清算所应根据服务实体经济的需求拓展清算品种、币种，合理计量风险资源，计算保证金和清算基金规模。"},{"i":21,"n":"第二十一条","txt":"金融机构参与银行间外汇市场，应采取有效措施管理金融机构与客户之间、不同客户之间的利益冲突，不得损害客户的合法权益。"},{"i":22,"n":"第二十二条","txt":"银行间外汇市场交易实行做市商或报价行制度。银行间外汇市场做市商或报价行应承担持续提供人民币与外币交易买、卖价格义务。"},{"i":23,"n":"第二十三条","txt":"境内金融机构可通过银行间外汇市场平盘结售汇业务敞口，并合理开展做市或自营交易，积极向市场提供流动性，调剂外汇市场供求余缺。 境外金融机构参与银行间外汇市场，应坚持审慎原则，符合管理跨境交易人民币汇率敞口等实际需要。中国人民银行和国家外汇管理局对境外央行类机构另有规定的，从其规定。"},{"i":24,"n":"第二十四条","txt":"金融机构、外汇交易中心、上海清算所、境内货币经纪公司应妥善保护交易相关信息。 （一）采用符合相关规定的方式交流交易信息，遵循可追溯、可审核、有记录、有访问控制的原则。 （二）按照规定妥善、完整地保存交易、清算的相关记录。"},{"i":25,"n":"第二十五条","txt":"外汇交易中心和上海清算所应当履行外汇市场交易和清算的信息披露义务，定期公布基础行情、清算信息等。"},{"i":26,"n":"第二十六条","txt":"外汇交易中心和上海清算所应当根据国家外汇管理局的要求，履行数据统计和信息报送义务。"},{"i":27,"n":"第二十七条","txt":"外汇交易中心和上海清算所可按照商业化原则向金融机构、金融信息服务商等提供银行间外汇市场数据服务。 （一）数据服务应当遵循公平、合理、无歧视的原则，遵守数据安全、网络安全等相关规定，履行数据安全保护义务，进行数据加工脱敏处理，不得损害参与机构利益。 （二）数据服务涉及数据出境的，应遵守数据出境安全等相关规定。"},{"i":28,"n":"第二十八条","txt":"金融信息服务商等机构向市场分发银行间外汇市场相关数据，应保证相关信息的及时性和一致性。"},{"i":29,"n":"第二十九条","txt":"外汇交易中心和上海清算所向金融机构收取交易、清算相关费用，应当遵循公开、合理原则。"},{"i":30,"n":"第三十条","txt":"外汇市场自律机制履行自律管理职能，负责制定外汇市场准则和实施自律管理。中国人民银行和国家外汇管理局依法对自律管理活动进行指导和监督，参与银行间外汇市场的境内金融机构、境内货币经纪公司应当加入外汇市场自律机制。"},{"i":31,"n":"第三十一条","txt":"金融机构、外汇交易中心、上海清算所、境内货币经纪公司、其他机构及相关人员违反本规定的，国家外汇管理局有权根据《中华人民共和国外汇管理条例》责令其限期改正，没收违法所得，视情节严重程度给予警告、罚款或责令停止经营相关业务等处罚；不属于本部门管辖的，应当移送其他有管辖权的行政机关；涉嫌犯罪的，依法移送司法机关。"},{"i":32,"n":"第三十二条","txt":"境内金融机构经允许参与具有离岸性质的人民币与外币交易，不适用于本规定。"},{"i":33,"n":"第三十三条","txt":"本规定下列用语的含义： （一）境内金融机构，是指经国务院金融管理部门批准，在中华人民共和国境内设立的从事金融业务的机构。 （二）境外金融机构，是指境外央行类机构、境外清算行、境外参加行，以及其他符合规定的各类境外机构投资者。 （三）境内货币经纪公司，是指经国家金融监督管理总局批准在境内设立的，专门为金融机构之间的金融交易活动提供经纪服务的非银行金融机构。 （四）金融信息服务商，是指向从事金融分析、金融交易、金融决策及其他金融活动的用户提供市场信息或数据服务的机构。"},{"i":34,"n":"第三十四条","txt":"本规定由中国人民银行负责解释。"},{"i":35,"n":"第三十五条","txt":"本规定自2026年2月1日起实施。《银行间外汇市场管理暂行规定》（银发〔1996〕423号文印发）、《中国人民银行关于加快发展外汇市场有关问题的通知》（银发〔2005〕202号）同时废止。"}],"feijinrongjigouzhifufuwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为促进支付服务市场健康发展，规范非金融机构支付服务行为，防范支付风险，保护当事人的合法权益，根据《中华人民共和国中国人民银行法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称非金融机构支付服务，是指非金融机构在收付款人之间作为中介机构提供下列部分或全部货币资金转移服务： （一）网络支付； （二）预付卡的发行与受理； （三）银行卡收单； （四）中国人民银行确定的其他支付服务。 本办法所称网络支付，是指依托公共网络或专用网络在收付款人之间转移货币资金的行为，包括货币汇兑、互联网支付、移动电话支付、固定电话支付、数字电视支付等。 本办法所称预付卡，是指以营利为目的发行的、在发行机构之外购买商品或服务的预付价值，包括采取磁条、芯片等技术以卡片、密码等形式发行的预付卡。 本办法所称银行卡收单，是指通过销售点（POS）终端等为银行卡特约商户代收货币资金的行为。"},{"i":3,"n":"第三条","txt":"非金融机构提供支付服务，应当依据本办法规定取得《支付业务许可证》，成为支付机构。 支付机构依法接受中国人民银行的监督管理。 未经中国人民银行批准，任何非金融机构和个人不得从事或变相从事支付业务。"},{"i":4,"n":"第四条","txt":"支付机构之间的货币资金转移应当委托银行业金融机构办理，不得通过支付机构相互存放货币资金或委托其他支付机构等形式办理。 支付机构不得办理银行业金融机构之间的货币资金转移，经特别许可的除外。"},{"i":5,"n":"第五条","txt":"支付机构应当遵循安全、效率、诚信和公平竞争的原则，不得损害国家利益、社会公共利益和客户合法权益。"},{"i":6,"n":"第六条","txt":"支付机构应当遵守反洗钱的有关规定，履行反洗钱义务。"},{"i":7,"n":"第七条","txt":"中国人民银行负责《支付业务许可证》的颁发和管理。 申请《支付业务许可证》的，需经所在地中国人民银行分支机构审查后，报中国人民银行批准。 本办法所称中国人民银行分支机构，是指中国人民银行副省级城市中心支行以上的分支机构。"},{"i":8,"n":"第八条","txt":"《支付业务许可证》的申请人应当具备下列条件： （一）在中华人民共和国境内依法设立的有限责任公司或股份有限公司，且为非金融机构法人； （二）有符合本办法规定的注册资本最低限额； （三）有符合本办法规定的出资人； （四）有5名以上熟悉支付业务的高级管理人员； （五）有符合要求的反洗钱措施； （六）有符合要求的支付业务设施； （七）有健全的组织机构、内部控制制度和风险管理措施； （八）有符合要求的营业场所和安全保障措施； （九）申请人及其高级管理人员最近3年内未因利用支付业务实施违法犯罪活动或为违法犯罪活动办理支付业务等受过处罚。"},{"i":9,"n":"第九条","txt":"申请人拟在全国范围内从事支付业务的，其注册资本最低限额为1亿元人民币；拟在省（自治区、直辖市）范围内从事支付业务的，其注册资本最低限额为3千万元人民币。注册资本最低限额为实缴货币资本。 本办法所称在全国范围内从事支付业务，包括申请人跨省（自治区、直辖市）设立分支机构从事支付业务，或客户可跨省（自治区、直辖市）办理支付业务的情形。 中国人民银行根据国家有关法律法规和政策规定，调整申请人的注册资本最低限额。 外商投资支付机构的业务范围、境外出资人的资格条件和出资比例等，由中国人民银行另行规定，报国务院批准。"},{"i":10,"n":"第十条","txt":"申请人的主要出资人应当符合以下条件： （一）为依法设立的有限责任公司或股份有限公司； （二）截至申请日，连续为金融机构提供信息处理支持服务2年以上，或连续为电子商务活动提供信息处理支持服务2年以上； （三）截至申请日，连续盈利2年以上； （四）最近3年内未因利用支付业务实施违法犯罪活动或为违法犯罪活动办理支付业务等受过处罚。 本办法所称主要出资人，包括拥有申请人实际控制权的出资人和持有申请人10%以上股权的出资人。"},{"i":11,"n":"第十一条","txt":"申请人应当向所在地中国人民银行分支机构提交下列文件、资料： （一）书面申请，载明申请人的名称、住所、注册资本、组织机构设置、拟申请支付业务等； （二）公司营业执照（副本）复印件； （三）公司章程； （四）验资证明； （五）经会计师事务所审计的财务会计报告； （六）支付业务可行性研究报告； （七）反洗钱措施验收材料； （八）技术安全检测认证证明； （九）高级管理人员的履历材料； （十）申请人及其高级管理人员的无犯罪记录证明材料； （十一）主要出资人的相关材料； （十二）申请资料真实性声明。"},{"i":12,"n":"第十二条","txt":"申请人应当在收到受理通知后按规定公告下列事项： （一）申请人的注册资本及股权结构； （二）主要出资人的名单、持股比例及其财务状况； （三）拟申请的支付业务； （四）申请人的营业场所； （五）支付业务设施的技术安全检测认证证明。"},{"i":13,"n":"第十三条","txt":"中国人民银行分支机构依法受理符合要求的各项申请，并将初审意见和申请资料报送中国人民银行。中国人民银行审查批准的，依法颁发《支付业务许可证》，并予以公告。 《支付业务许可证》自颁发之日起，有效期5年。支付机构拟于《支付业务许可证》期满后继续从事支付业务的，应当在期满前6个月内向所在地中国人民银行分支机构提出续展申请。中国人民银行准予续展的，每次续展的有效期为5年。"},{"i":14,"n":"第十四条","txt":"支付机构变更下列事项之一的，应当在向公司登记机关申请变更登记前报中国人民银行同意： （一）变更公司名称、注册资本或组织形式； （二）变更主要出资人； （三）合并或分立； （四）调整业务类型或改变业务覆盖范围。"},{"i":15,"n":"第十五条","txt":"支付机构申请终止支付业务的，应当向所在地中国人民银行分支机构提交下列文件、资料： （一）公司法定代表人签署的书面申请，载明公司名称、支付业务开展情况、拟终止支付业务及终止原因等； （二）公司营业执照（副本）复印件； （三）《支付业务许可证》复印件； （四）客户合法权益保障方案； （五）支付业务信息处理方案。 准予终止的，支付机构应当按照中国人民银行的批复完成终止工作，交回《支付业务许可证》。"},{"i":16,"n":"第十六条","txt":"本章对许可程序未作规定的事项，适用《中国人民银行行政许可实施办法》（中国人民银行令〔2004〕第3号）。"},{"i":17,"n":"第十七条","txt":"支付机构应当按照《支付业务许可证》核准的业务范围从事经营活动，不得从事核准范围之外的业务，不得将业务外包。 支付机构不得转让、出租、出借《支付业务许可证》。"},{"i":18,"n":"第十八条","txt":"支付机构应当按照审慎经营的要求，制订支付业务办法及客户权益保障措施，建立健全风险管理和内部控制制度，并报所在地中国人民银行分支机构备案。"},{"i":19,"n":"第十九条","txt":"支付机构应当确定支付业务的收费项目和收费标准，并报所在地中国人民银行分支机构备案。 支付机构应当公开披露其支付业务的收费项目和收费标准。"},{"i":20,"n":"第二十条","txt":"支付机构应当按规定向所在地中国人民银行分支机构报送支付业务统计报表和财务会计报告等资料。"},{"i":21,"n":"第二十一条","txt":"支付机构应当制定支付服务协议，明确其与客户的权利和义务、纠纷处理原则、违约责任等事项。 支付机构应当公开披露支付服务协议的格式条款，并报所在地中国人民银行分支机构备案。"},{"i":22,"n":"第二十二条","txt":"支付机构的分公司从事支付业务的，支付机构及其分公司应当分别到所在地中国人民银行分支机构备案。 支付机构的分公司终止支付业务的，比照前款办理。"},{"i":23,"n":"第二十三条","txt":"支付机构接受客户备付金时，只能按收取的支付服务费向客户开具发票，不得按接受的客户备付金金额开具发票。"},{"i":24,"n":"第二十四条","txt":"支付机构接受的客户备付金不属于支付机构的自有财产。 支付机构只能根据客户发起的支付指令转移备付金。禁止支付机构以任何形式挪用客户备付金。"},{"i":25,"n":"第二十五条","txt":"支付机构应当在客户发起的支付指令中记载下列事项： （一）付款人名称； （二）确定的金额； （三）收款人名称； （四）付款人的开户银行名称或支付机构名称； （五）收款人的开户银行名称或支付机构名称； （六）支付指令的发起日期。 客户通过银行结算账户进行支付的，支付机构还应当记载相应的银行结算账号。客户通过非银行结算账户进行支付的，支付机构还应当记载客户有效身份证件上的名称和号码。"},{"i":26,"n":"第二十六条","txt":"支付机构接受客户备付金的，应当在商业银行开立备付金专用存款账户存放备付金。中国人民银行另有规定的除外。 支付机构只能选择一家商业银行作为备付金存管银行，且在该商业银行的一个分支机构只能开立一个备付金专用存款账户。 支付机构应当与商业银行的法人机构或授权的分支机构签订备付金存管协议，明确双方的权利、义务和责任。 支付机构应当向所在地中国人民银行分支机构报送备付金存管协议和备付金专用存款账户的信息资料。"},{"i":27,"n":"第二十七条","txt":"支付机构的分公司不得以自己的名义开立备付金专用存款账户，只能将接受的备付金存放在支付机构开立的备付金专用存款账户。"},{"i":28,"n":"第二十八条","txt":"支付机构调整不同备付金专用存款账户头寸的，由备付金存管银行的法人机构对支付机构拟调整的备付金专用存款账户的余额情况进行复核，并将复核意见告知支付机构及有关备付金存管银行。 支付机构应当持备付金存管银行的法人机构出具的复核意见办理有关备付金专用存款账户的头寸调拨。"},{"i":29,"n":"第二十九条","txt":"备付金存管银行应当对存放在本机构的客户备付金的使用情况进行监督，并按规定向备付金存管银行所在地中国人民银行分支机构及备付金存管银行的法人机构报送客户备付金的存管或使用情况等信息资料。 对支付机构违反第二十五条至第二十八条相关规定使用客户备付金的申请或指令，备付金存管银行应当予以拒绝；发现客户备付金被违法使用或有其他异常情况的，应当立即向备付金存管银行所在地中国人民银行分支机构及备付金存管银行的法人机构报告。"},{"i":30,"n":"第三十条","txt":"支付机构的实缴货币资本与客户备付金日均余额的比例，不得低于10%。 本办法所称客户备付金日均余额，是指备付金存管银行的法人机构根据最近90日内支付机构每日日终的客户备付金总量计算的平均值。"},{"i":31,"n":"第三十一条","txt":"支付机构应当按规定核对客户的有效身份证件或其他有效身份证明文件，并登记客户身份基本信息。 支付机构明知或应知客户利用其支付业务实施违法犯罪活动的，应当停止为其办理支付业务。"},{"i":32,"n":"第三十二条","txt":"支付机构应当具备必要的技术手段，确保支付指令的完整性、一致性和不可抵赖性，支付业务处理的及时性、准确性和支付业务的安全性；具备灾难恢复处理能力和应急处理能力，确保支付业务的连续性。"},{"i":33,"n":"第三十三条","txt":"支付机构应当依法保守客户的商业秘密，不得对外泄露。法律法规另有规定的除外。"},{"i":34,"n":"第三十四条","txt":"支付机构应当按规定妥善保管客户身份基本信息、支付业务信息、会计档案等资料。"},{"i":35,"n":"第三十五条","txt":"支付机构应当接受中国人民银行及其分支机构定期或不定期的现场检查和非现场检查，如实提供有关资料，不得拒绝、阻挠、逃避检查，不得谎报、隐匿、销毁相关证据材料。"},{"i":36,"n":"第三十六条","txt":"中国人民银行及其分支机构依据法律、行政法规、中国人民银行的有关规定对支付机构的公司治理、业务活动、内部控制、风险状况、反洗钱工作等进行定期或不定期现场检查和非现场检查。 中国人民银行及其分支机构依法对支付机构进行现场检查，适用《中国人民银行执法检查程序规定》（中国人民银行令〔2010〕第1号发布）。"},{"i":37,"n":"第三十七条","txt":"中国人民银行及其分支机构可以采取下列措施对支付机构进行现场检查： （一）询问支付机构的工作人员，要求其对被检查事项作出解释、说明； （二）查阅、复制与被检查事项有关的文件、资料，对可能被转移、藏匿或毁损的文件、资料予以封存； （三）检查支付机构的客户备付金专用存款账户及相关账户； （四）检查支付业务设施及相关设施。"},{"i":38,"n":"第三十八条","txt":"支付机构有下列情形之一的，中国人民银行及其分支机构有权责令其停止办理部分或全部支付业务： （一）累计亏损超过其实缴货币资本的50%； （二）有重大经营风险； （三）有重大违法违规行为。"},{"i":39,"n":"第三十九条","txt":"支付机构因解散、依法被撤销或被宣告破产而终止的，其清算事宜按照国家有关法律规定办理。"},{"i":40,"n":"第四十条","txt":"中国人民银行及其分支机构的工作人员有下列情形之一的，依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）违反规定审查批准《支付业务许可证》的申请、变更、终止等事项的； （二）违反规定对支付机构进行检查的； （三）泄露知悉的国家秘密或商业秘密的； （四）滥用职权、玩忽职守的其他行为。"},{"i":41,"n":"第四十一条","txt":"商业银行有下列情形之一的，中国人民银行及其分支机构责令其限期改正，并给予警告或处1万元以上3万元以下罚款；情节严重的，中国人民银行责令其暂停或终止客户备付金存管业务： （一）未按规定报送客户备付金的存管或使用情况等信息资料的； （二）未按规定对支付机构调整备付金专用存款账户头寸的行为进行复核的； （三）未对支付机构违反规定使用客户备付金的申请或指令予以拒绝的。"},{"i":42,"n":"第四十二条","txt":"支付机构有下列情形之一的，中国人民银行分支机构责令其限期改正，并给予警告或处1万元以上3万元以下罚款： （一）未按规定建立有关制度办法或风险管理措施的； （二） 未按规定办理相关备案手续的； （三）未按规定公开披露相关事项的； （四）未按规定报送或保管相关资料的； （五）未按规定办理相关变更事项的； （六）未按规定向客户开具发票的； （七）未按规定保守客户商业秘密的。"},{"i":43,"n":"第四十三条","txt":"支付机构有下列情形之一的，中国人民银行分支机构责令其限期改正，并处3万元罚款；情节严重的，中国人民银行注销其《支付业务许可证》；涉嫌犯罪的，依法移送公安机关立案侦查；构成犯罪的，依法追究刑事责任： （一）转让、出租、出借《支付业务许可证》的； （二）超出核准业务范围或将业务外包的； （三）未按规定存放或使用客户备付金的； （四）未遵守实缴货币资本与客户备付金比例管理规定的； （五）无正当理由中断或终止支付业务的； （六）拒绝或阻碍相关检查监督的； （七）其他危及支付机构稳健运行、损害客户合法权益或危害支付服务市场的违法违规行为。"},{"i":44,"n":"第四十四条","txt":"支付机构未按规定履行反洗钱义务的，中国人民银行及其分支机构依据国家有关反洗钱法律法规等进行处罚；情节严重的，中国人民银行注销其《支付业务许可证》。"},{"i":45,"n":"第四十五条","txt":"支付机构超出《支付业务许可证》有效期限继续从事支付业务的，中国人民银行及其分支机构责令其终止支付业务；涉嫌犯罪的，依法移送公安机关立案侦查；构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"以欺骗等不正当手段申请《支付业务许可证》但未获批准的，申请人及持有其5%以上股权的出资人3年内不得再次申请或参与申请《支付业务许可证》。 以欺骗等不正当手段申请《支付业务许可证》且已获批准的，由中国人民银行及其分支机构责令其终止支付业务，注销其《支付业务许可证》；涉嫌犯罪的，依法移送公安机关立案侦查；构成犯罪的，依法追究刑事责任；申请人及持有其5%以上股权的出资人不得再次申请或参与申请《支付业务许可证》。"},{"i":47,"n":"第四十七条","txt":"任何非金融机构和个人未经中国人民银行批准擅自从事或变相从事支付业务的，中国人民银行及其分支机构责令其终止支付业务；涉嫌犯罪的，依法移送公安机关立案侦查；构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"本办法实施前已经从事支付业务的非金融机构，应当在本办法实施之日起1年内申请取得《支付业务许可证》。逾期未取得的，不得继续从事支付业务。"},{"i":49,"n":"第四十九条","txt":"本办法由中国人民银行负责解释。"},{"i":50,"n":"第五十条","txt":"本办法自2010年9月1日起施行。"}],"feiyinhangzhifujigoukehubeifujincunguanbanfa":[{"i":1,"n":"第一条","txt":"为规范非银行支付机构客户备付金管理，保障当事人合法权益，促进支付行业健康有序发展，根据《中华人民共和国中国人民银行法》《中华人民共和国电子商务法》《中华人民共和国网络安全法》《非金融机构支付服务管理办法》（中国人民银行令〔2010〕第2号发布）等法律法规规章，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于客户备付金的存放、归集、使用、划转等存管活动。"},{"i":3,"n":"第三条","txt":"本办法下列用语的含义： 客户备付金，是指非银行支付机构为办理客户委托的支付业务而实际收到的预收待付货币资金。 备付金集中存管账户，是指非银行支付机构在中国人民银行开立的专门存放客户备付金的账户。 特定业务待结算资金，是指非银行支付机构为客户办理跨境人民币支付、基金销售支付、跨境外汇支付等特定业务时，已从备付金集中存管账户付出或者尚未向备付金集中存管账户归集的待付资金。 特定业务银行，是指满足本办法第二十三条的规定,具备相关业务资质，为非银行支付机构提供特定业务待结算资金存管等服务的商业银行。 特定业务待结算资金专用存款账户，是指非银行支付机构在特定业务银行开立的专门存放特定业务待结算资金的账户。 备付金银行，是指符合本办法要求，与非银行支付机构签订协议，为非银行支付机构开立预付卡备付金专用存款账户，并提供客户备付金存管服务的商业银行。 预付卡备付金专用存款账户，是指非银行支付机构因开展"},{"i":4,"n":"第四条","txt":"非银行支付机构接收的客户备付金应当直接全额交存至中国人民银行或者符合要求的商业银行。 非银行支付机构因发行预付卡或者为预付卡充值所直接接收的客户备付金应当通过预付卡备付金专用存款账户统一交存至备付金集中存管账户。"},{"i":5,"n":"第五条","txt":"客户备付金只能用于办理客户委托的支付业务和本办法规定的其他情形。 任何单位和个人不得挪用、占用、借用客户备付金，不得以客户备付金提供担保。"},{"i":6,"n":"第六条","txt":"客户备付金的划转应当通过符合本办法第二十一条规定的清算机构办理。"},{"i":7,"n":"第七条","txt":"非银行支付机构、清算机构和备付金银行应当按照法律法规、本办法以及双方协议约定，开展客户备付金存管业务，保障客户备付金安全完整，维护客户合法权益。 清算机构、备付金银行依照本办法对客户备付金业务实行监督的，非银行支付机构应当配合。"},{"i":8,"n":"第八条","txt":"中国人民银行及其分支机构对客户备付金存管业务活动进行监督管理。"},{"i":9,"n":"第九条","txt":"非银行支付机构应当在中国人民银行开立一个备付金集中存管账户。 非银行支付机构携备付金集中存管账户开立申请书、营业执照、《支付业务许可证》（副本）、法定代表人或者负责人身份证件原件和复印件及其他开户所需材料到住所地中国人民银行分支机构开立备付金集中存管账户。 备付金集中存管账户的管理应当遵守中国人民银行会计核算相关规定。"},{"i":10,"n":"第十条","txt":"开展跨境人民币支付业务的非银行支付机构，可以选择一家特定业务银行开立一个特定业务待结算资金专用存款账户，仅用于办理跨境人民币支付结算业务。非银行支付机构确有特殊需要的，可以再选择一家特定业务银行开立一个特定业务待结算资金专用存款账户作为备用账户。"},{"i":11,"n":"第十一条","txt":"开展基金销售支付业务的非银行支付机构，可以选择一家特定业务银行开立一个特定业务待结算资金专用存款账户，仅用于办理基金销售支付结算业务。"},{"i":12,"n":"第十二条","txt":"开展跨境外汇支付业务的非银行支付机构，原则上可以选择不超过两家特定业务银行，每家特定业务银行可以开立一个特定业务待结算资金专用存款账户（一家特定业务银行的多个币种跨境外汇待结算资金专用存款账户视作一个特定业务待结算资金专用存款账户），仅用于办理跨境外汇支付结算业务。"},{"i":13,"n":"第十三条","txt":"非银行支付机构特定业务待结算资金专用存款账户与其中华人民共和国境内客户、商户银行结算账户之间的资金划转应当由清算机构通过备付金集中存管账户办理。 特定业务待结算资金专用存款账户的管理，以及境内和跨境资金划转应当遵守中国人民银行和相关监管部门的规定。"},{"i":14,"n":"第十四条","txt":"开展预付卡发行与受理业务的非银行支付机构，可以选择一家备付金银行开立一个预付卡备付金专用存款账户，该账户性质为专用存款账户，仅用于收取客户的购卡、充值资金，不可以办理现金支取或者向备付金集中存管账户以外的账户转账。预付卡备付金专用存款账户资金交存备付金集中存管账户前发起、经由备付金银行审核确认的当日误入款的原路退回交易除外。 非银行支付机构开立预付卡备付金专用存款账户，应当遵守中国人民银行关于开立专用存款账户的相关规定，并出具《支付业务许可证》（副本）和备付金协议。 预付卡备付金专用存款账户的名称应当标明非银行支付机构名称和“客户备付金”字样。非银行支付机构其他银行账户不得使用“备付金”字样。 预付卡备付金专用存款账户内资金应当于每个工作日大额支付系统业务截止前全部交存至备付金集中存管账户。"},{"i":15,"n":"第十五条","txt":"非银行支付机构的分支机构应当将接收的客户备付金存放在以非银行支付机构名义开立的备付金账户，不得以该分支机构名义开立备付金账户。"},{"i":16,"n":"第十六条","txt":"非银行支付机构名称发生变更的，应当在名称变更手续完成之日起2个工作日内，到住所地中国人民银行分支机构办理备付金集中存管账户名称变更。 非银行支付机构因迁址等原因需变更备付金集中存管账户的，应当在非银行支付机构住所变更等手续完成后，按照本办法第九条的规定，到迁址后住所地中国人民银行分支机构开立新备付金集中存管账户，并于新备付金集中存管账户开立之日起2个工作日内将原备付金集中存管账户资金全部划转至新备付金集中存管账户，并办理原备付金集中存管账户销户手续。"},{"i":17,"n":"第十七条","txt":"非银行支付机构名称发生变更的，应当在名称变更手续完成之日起2个工作日内，到备付金银行办理预付卡备付金专用存款账户名称变更。 非银行支付机构拟撤销预付卡备付金专用存款账户的，应当书面告知备付金银行或者其授权分支机构，并于拟撤销账户内的资金全部划转至备付金集中存管账户之日起2个工作日内，办理销户手续。"},{"i":18,"n":"第十八条","txt":"非银行支付机构终止支付业务的，应当在按照规定提交的客户权益保障方案中说明备付金账户及特定业务待结算资金专用存款账户撤销事项，并在中国人民银行决定终止相关业务后办理销户手续。"},{"i":19,"n":"第十九条","txt":"非银行支付机构应当提前2个工作日将开立、变更和撤销备付金账户和特定业务待结算资金专用存款账户原因及后续安排报告住所地中国人民银行分支机构。 非银行支付机构、备付金银行和特定业务银行应当在备付金账户和特定业务待结算资金专用存款账户开立、变更或者撤销当日分别向非银行支付机构住所地中国人民银行分支机构备案，同时书面告知清算机构。"},{"i":20,"n":"第二十条","txt":"非银行支付机构应当确定一个自有资金账户，向住所地中国人民银行分支机构备案，并将账户信息书面告知清算机构。非银行支付机构应当将备案自有资金账户与其预付卡备付金专用存款账户、特定业务待结算资金专用存款账户分户管理。 非银行支付机构拟变更备案自有资金账户的，应当提前2个工作日向住所地中国人民银行分支机构报告变更原因、变更后的自有资金账户、变更时间等事项，并书面告知清算机构。"},{"i":21,"n":"第二十一条","txt":"非银行支付机构应当选择符合以下要求的清算机构： （一）依法成立的清算机构； （二）具备监督客户备付金的能力和条件，包括但不限于有健全的客户备付金业务操作办法和规程，熟悉客户备付金存管业务的管理人员，监测、核对客户备付金信息的技术能力，能够按规定建立客户备付金监测系统； （三）具有满足国家和金融领域相关技术标准要求的业务设施，具备与非银行支付机构业务规模相匹配的系统处理能力，以及保障清算服务安全稳定运行所需的应急处置、灾难恢复和网络安全保障能力； （四）满足中国人民银行基于保护客户备付金安全、维护消费者合法权益所规定的其他要求。"},{"i":22,"n":"第二十二条","txt":"非银行支付机构拟变更清算机构的，应当提前10个工作日向住所地中国人民银行分支机构报告变更方案。变更方案应当包括变更理由、时间安排、变更后的清算机构、业务合作情况、系统对接方式、应急处置预案等内容。"},{"i":23,"n":"第二十三条","txt":"非银行支付机构开展预付卡发行与受理业务时，应当选择符合以下要求的商业银行作为备付金银行： （一）总资产不得低于1000亿元，有关资本充足率、杠杆率、流动性等风险控制指标符合监管规定； （二）具备监督客户备付金的能力和条件，包括健全的客户备付金业务操作办法和规程，熟悉客户备付金存管业务的管理人员，监测、核对客户备付金信息的技术能力，能够按规定建立客户备付金存管系统； （三）境内分支机构数量和网点分布能够满足非银行支付机构的支付业务需要，并具有与非银行支付机构业务规模相匹配的系统处理能力； （四）具备必要的灾难恢复处理能力和应急处理能力，能够确保业务的连续性； （五）满足中国人民银行基于保护客户备付金安全、维护消费者合法权益所规定的其他要求。"},{"i":24,"n":"第二十四条","txt":"开展预付卡发行与受理业务的非银行支付机构拟变更备付金银行（包括同一备付金银行的不同分支机构）的，应当提前10个工作日向住所地中国人民银行分支机构报告变更方案，变更方案应当包括变更理由、时间安排、变更后的备付金银行等内容，并按照本办法第十四条、第十七条第二款的规定，开立新预付卡备付金专用存款账户，撤销原预付卡备付金专用存款账户。"},{"i":25,"n":"第二十五条","txt":"非银行支付机构应当分别与清算机构、备付金银行或者其授权的一个境内分支机构签订备付金协议，约定双方的权利、义务和责任，保障客户备付金安全。 备付金协议应当约定非银行支付机构划转客户备付金的支付指令，以及客户备付金发生损失时双方应当承担的偿付责任和相关偿付方式。 备付金协议对客户备付金安全保障责任约定不明的，非银行支付机构、备付金银行和清算机构应当优先保证客户备付金的安全及支付业务的连续性，不得因争议影响客户合法权益。"},{"i":26,"n":"第二十六条","txt":"非银行支付机构与清算机构、备付金银行或者其授权的分支机构应当自备付金协议签订之日起2个工作日内，分别向非银行支付机构住所地中国人民银行分支机构备案。"},{"i":27,"n":"第二十七条","txt":"非银行支付机构、清算机构和备付金银行应当妥善保管备付金账户信息及交易信息，保障客户信息安全和交易安全。"},{"i":28,"n":"第二十八条","txt":"非银行支付机构应当在收到客户备付金或者客户划转客户备付金不可撤销的支付指令后，办理客户委托的支付业务。"},{"i":29,"n":"第二十九条","txt":"非银行支付机构应当基于真实交易信息发送划转客户备付金的支付指令，确保支付指令的完整性、一致性、可跟踪稽核和不可篡改，并确保相关资金划转事项的真实性、合规性。 清算机构应当及时对支付指令进行审核，审核无误后及时办理资金划转，必要时可以要求非银行支付机构提交与交易相关的材料。 清算机构有权拒绝执行非银行支付机构未按约定或者违反本办法发送的支付指令。"},{"i":30,"n":"第三十条","txt":"非银行支付机构之间的合作应当符合中国人民银行有关规定。 非银行支付机构之间因合作产生的、基于真实交易的客户备付金划转应当通过清算机构在备付金集中存管账户之间进行，发起支付业务的非银行支付机构应当提供交易流水、收付款人信息等表明交易实际发生的材料。 非银行支付机构之间不得相互直接开放支付业务接口，不得相互开立支付账户。"},{"i":31,"n":"第三十一条","txt":"开展预付卡发行与受理业务的非银行支付机构应当在预付卡章程、协议、售卡网点、公司网站等以显著方式向客户告知用于接收购卡、充值资金的预付卡备付金专用存款账户的开户银行、户名和账号。"},{"i":32,"n":"第三十二条","txt":"非银行支付机构通过非现金方式接收的预付卡业务客户备付金应当直接交存至预付卡备付金专用存款账户；按规定可以通过现金形式接收的预付卡业务客户备付金，应当在收讫日起2个工作日内全额交存至预付卡备付金专用存款账户。"},{"i":33,"n":"第三十三条","txt":"在符合相关业务规定的情形下，非银行支付机构备付金集中存管账户中的资金仅能向其商户和客户指定的银行结算账户、备案自有资金账户和特定业务待结算资金专用存款账户、存在合规业务合作关系的其他非银行支付机构备付金集中存管账户，以及中国人民银行基于保障消费者合法权益而认可的其他账户划转。 非银行支付机构开展合规业务，需要向备付金集中存管账户划转自有资金的，应当通过清算机构从备案自有资金账户办理。"},{"i":34,"n":"第三十四条","txt":"非银行支付机构按规定通过非现金方式为客户办理备付金赎回的，应当通过清算机构从备付金集中存管账户划转资金；按规定通过现金形式为客户办理备付金赎回的，应当先通过备案自有资金账户办理，再通过备付金主监督机构从备付金集中存管账户将相应额度的客户备付金划转至备案自有资金账户。"},{"i":35,"n":"第三十五条","txt":"非银行支付机构应当缴纳行业保障基金，用于弥补客户备付金特定损失以及中国人民银行规定的其他用途。 行业保障基金管理办法由中国人民银行另行制定。"},{"i":36,"n":"第三十六条","txt":"非银行支付机构提取划转至备付金集中存管账户的手续费收入、因办理合规业务转入的自有资金等资金的，应当向备付金主监督机构提交表明相关资金真实性、合理性的材料，经备付金主监督机构审查通过后划转至备案自有资金账户。"},{"i":37,"n":"第三十七条","txt":"非银行支付机构因办理客户备付金划转产生的手续费费用，不得使用客户备付金支付。"},{"i":38,"n":"第三十八条","txt":"中国人民银行及其分支机构依法对非银行支付机构、清算机构以及备付金银行的客户备付金存管业务活动实施非现场监管以及现场检查。 中国人民银行及其分支机构有权根据监管需要，调阅非银行支付机构、清算机构、备付金银行和特定业务银行的相关交易、会计处理和档案等资料，要求非银行支付机构对其客户备付金等相关项目进行外部专项审计。 中国人民银行分支机构应当设置风险监测专岗，持续监测辖区内非银行支付机构客户备付金风险情况，建立备付金风险处置机制，及时发现、处置、化解非银行支付机构客户备付金风险。 中国人民银行负责组织建设客户备付金管理系统，组织建立中国人民银行分支机构与清算机构之间、各清算机构之间、清算机构与备付金银行和特定业务银行之间的信息共享机制，指导清算机构建立非银行支付机构客户备付金信息核对校验机制和风险监测体系。"},{"i":39,"n":"第三十九条","txt":"清算机构和备付金银行应当分别对备付金集中存管账户、预付卡备付金专用存款账户中客户备付金的存放、使用、划转实行监督，建立和完善客户备付金相关交易的事前、事中、事后监测及监督机制，指定专人实时监测备付金风险，及时核实异常交易。"},{"i":40,"n":"第四十条","txt":"非银行支付机构、清算机构、备付金银行和特定业务银行应当建立自查机制，定期按照要求对自身业务合规性、流程可靠性、系统连续性、客户信息安全性等进行自查。 非银行支付机构应当聘请独立的、具有专业资质的审计机构，按年对备付金业务进行审计。"},{"i":41,"n":"第四十一条","txt":"非银行支付机构应当与清算机构、备付金银行建立客户备付金信息核对校验机制，逐日核对客户备付金的存放、使用、划转等信息，并至少保存核对记录5年。非银行支付机构应当与特定业务银行定期核对特定业务待结算资金的存放、使用、划转等信息，并至少保存核对记录5年。"},{"i":42,"n":"第四十二条","txt":"非银行支付机构应当选择一家清算机构作为备付金主监督机构，并在备付金协议中予以明确；其他清算机构、备付金银行应当配合备付金主监督机构进行备付金监督，定期向备付金主监督机构报送客户备付金业务及风险信息，备付金主监督机构收集汇总后与非银行支付机构进行核对，并向非银行支付机构住所地中国人民银行分支机构报送核对校验结果。 非银行支付机构拟变更备付金主监督机构的，按照本办法第二十二条的规定办理，同时向住所地中国人民银行分支机构报告变更后的备付金主监督机构及客户备付金核对校验安排等事项。"},{"i":43,"n":"第四十三条","txt":"中国支付清算协会对非银行支付机构客户备付金存管业务活动进行自律管理。"},{"i":44,"n":"第四十四条","txt":"清算机构、备付金银行、特定业务银行应当加强客户备付金和特定业务待结算资金管理，发现客户备付金或者特定业务待结算资金异常的，应当立即督促非银行支付机构纠正，并向非银行支付机构住所地中国人民银行分支机构报告，由其进行核查。经核查确实存在风险的，中国人民银行分支机构应当立即启动风险处置机制，并上报中国人民银行。"},{"i":45,"n":"第四十五条","txt":"备付金银行、特定业务银行与非银行支付机构不在同一省、自治区、直辖市、计划单列市的，备付金银行、特定业务银行向非银行支付机构住所地中国人民银行分支机构报送各类信息、材料时，还应当抄送其住所地中国人民银行分支机构。"},{"i":46,"n":"第四十六条","txt":"非银行支付机构、清算机构、备付金银行、特定业务银行应当于每月前5个工作日内，向中国人民银行分支机构提交上一月其辖区内各非银行支付机构客户备付金业务以及跨境人民币支付、基金销售支付和跨境外汇支付业务报告，包括客户备付金和特定业务待结算资金的存放、使用、余额、风险和处置情况等内容。 中国人民银行分支机构、清算机构应当于每月前10个工作日内，向中国人民银行提交非银行支付机构客户备付金业务以及跨境人民币支付、基金销售支付和跨境外汇支付业务报告，包括客户备付金和特定业务待结算资金的存放、使用、余额、风险和处置情况，以及对非银行支付机构业务合规性评价等内容。"},{"i":47,"n":"第四十七条","txt":"非银行支付机构、备付金银行、清算机构、特定业务银行有下列情形之一，情节轻微的，由中国人民银行及其分支机构进行约谈，责令限期改正；情节严重或者逾期未改正的，依据《中华人民共和国中国人民银行法》第四十六条的规定进行处罚： （一）未按本办法规定存放、使用或者划转客户备付金的； （二）未按本办法规定发送客户备付金支付指令的； （三）未按本办法规定签订备付金协议的； （四）未按本办法规定选择备付金银行、清算机构开展备付金业务的； （五）未按本办法规定开立、变更、撤销备付金账户、特定业务待结算资金专用存款账户和备案自有资金账户的； （六）未按本办法规定缴纳行业保障基金的； （七）未按本办法规定划转手续费收入的； （八）未按本办法规定办理备付金银行、清算机构、备付金主监督机构变更事项的； （九）未按本办法规定办理备案事项或者报送、告知相关信息的； （十）未按本办法规定建立客户备付金信息核对校验机制、"},{"i":48,"n":"第四十八条","txt":"商业银行、清算机构违反本办法，擅自从事或者变相从事客户备付金相关业务活动的，中国人民银行及其分支机构责令终止相关业务，并依据《中华人民共和国中国人民银行法》第四十六条的规定进行处罚。"},{"i":49,"n":"第四十九条","txt":"任何单位和个人挪用、占用、借用客户备付金的，中国人民银行及其分支机构依据《中华人民共和国中国人民银行法》第四十六条的规定进行处罚。"},{"i":50,"n":"第五十条","txt":"拒绝、阻挠、逃避中国人民银行及其分支机构检查监督，或者谎报、隐匿、销毁相关证据材料的，有关法律、行政法规有处罚规定的，依照其规定给予处罚；有关法律、行政法规未作处罚规定的，中国人民银行及其分支机构给予警告，并处3万元以下罚款。"},{"i":51,"n":"第五十一条","txt":"中国人民银行及其分支机构的工作人员滥用职权、玩忽职守、徇私舞弊，不依法履行客户备付金监督管理职责，或者泄露工作秘密、商业秘密的，依法给予处分；涉嫌构成犯罪的，移送司法机关依法追究刑事责任。"},{"i":52,"n":"第五十二条","txt":"本办法由中国人民银行负责解释。"},{"i":53,"n":"第五十三条","txt":"自本办法施行之日起的6个月为过渡期。过渡期内，非银行支付机构应当按照本办法规定，理顺相关账户体系，选定备付金主监督机构，完成业务流程及系统改造、备付金信息核对校验机制建立等工作。"},{"i":54,"n":"第五十四条","txt":"本办法自2021年3月1日起施行，《支付机构客户备付金存管办法》（中国人民银行公告〔2013〕第6号公布）同时废止。本办法施行之前的客户备付金相关管理规定与本办法不一致的，以本办法为准。"}],"feiyinhangzhifujigoujianduguanlitiaolishishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国中国人民银行法》、《中华人民共和国电子商务法》、《中华人民共和国行政许可法》、《非银行支付机构监督管理条例》（以下简称《条例》）等法律、行政法规，制定本细则。"},{"i":2,"n":"第二条","txt":"非银行支付机构应当遵循诚实信用、合法合规、安全高效原则开展业务，采取切实有效措施保障业务连续性、备付金安全和用户合法权益，不得以欺骗、隐瞒、非自有资金出资等不正当手段办理行政许可事项，严禁倒卖、出租、出借支付业务许可证。"},{"i":3,"n":"第三条","txt":"《条例》所称中国人民银行的分支机构是指中国人民银行各省、自治区、直辖市以及计划单列市分行。中国人民银行的分支机构根据中国人民银行的授权和分工，依法对辖区内非银行支付机构及非银行支付机构分支机构实施监督管理，对本辖区非银行支付机构监管工作作出统一部署。 中国人民银行的分支机构之间应当加强监管协同和信息共享。"},{"i":4,"n":"第四条","txt":"《条例》所称非银行支付机构的董事、监事和高级管理人员，应当符合下列条件： （一）熟悉与支付业务相关的制度文件。 （二）具有履行职责所需的经营管理能力，包括具有担任拟任职务所需的独立性、良好的从业记录等。高级管理人员还应当具有大学本科以上学历，从事支付结算、金融、信息处理业务2年以上或者从事会计、经济、信息科技、法律工作3年以上。 （三）最近3年诚信记录良好且无重大违法违规记录。 （四）不存在《中华人民共和国公司法》规定的不得担任公司董事、监事和高级管理人员的情形。 前款所称高级管理人员，包括总经理、副总经理、财务负责人、技术负责人、合规风控负责人或者实际履行上述职责的人员。非银行支付机构应当具有5名以上高级管理人员。 中国人民银行及其分支机构可以对非银行支付机构拟任的董事、监事和高级管理人员进行任职考察，考察方式包括但不限于向其原任职单位核实工作情况、通过谈话了解拟任人员的基本情况和业"},{"i":5,"n":"第五条","txt":"非银行支付机构的董事、监事和高级管理人员就任时和在任期间应当始终符合本细则第四条要求。 非银行支付机构董事、监事和高级管理人员在任期间出现不符合本细则第四条情形的，非银行支付机构应当停止其任职，并于10日内将相关情况报告住所所在地中国人民银行的分支机构。"},{"i":6,"n":"第六条","txt":"《条例》所称其他审慎性条件是指具有良好的资本实力、风险管理能力、业务合规能力等符合审慎经营规则的条件。 《条例》施行前已按照有关规定设立的非银行支付机构还应当满足经营状况良好、支付业务许可证有效期内无重大违法违规记录、不存在无正当理由连续2年以上未开展支付业务的情况等条件。 中国人民银行及其分支机构为核实本条规定的审慎性条件，可以要求申请人提供有关说明材料。"},{"i":7,"n":"第七条","txt":"本细则第六条所称重大违法违规记录是指从事犯罪活动，影响恶劣；或者存在《条例》第五十一条第一项、第五项情形;或者存在《条例》第五十条任一情形和第五十一条除第一项、第五项之外的情形，并且具有下列情节之一的： （一）司法机关认定主动为非法活动提供支付服务，拒不整改或者性质恶劣。 （二）伪造系统数据或者提供虚假材料等，导致监管工作无法正常开展。 （三）情节恶劣，造成严重后果或者社会影响。 对非银行支付机构在《条例》施行前存在的重大违法违规记录的认定，参照上述规定执行。"},{"i":8,"n":"第八条","txt":"根据《条例》第八条，非银行支付机构注册资本最低限额在人民币1亿元基础上，按下列规则附加提高： （一）仅从事本细则第五十五条规定的储值账户运营Ⅰ类业务的，注册资本最低限额附加值为人民币1亿元。 （二）仅在住所所在省、自治区、直辖市从事本细则第五十五条规定的储值账户运营Ⅱ类业务的，注册资本最低限额无需附加。经营地域范围在其住所所在地以外每增加1个省、自治区、直辖市的，注册资本最低限额附加值增加人民币500万元。经营地域范围超过20个省、自治区、直辖市的，注册资本最低限额附加值为人民币1亿元。但是，仅从事储值账户运营Ⅱ类（仅限于线上实名支付账户充值）或者储值账户运营Ⅱ类（仅限于经营地域范围预付卡受理）的，注册资本最低限额无需附加。 （三）仅在住所所在省、自治区、直辖市从事本细则第五十五条规定的支付交易处理Ⅰ类业务的，注册资本最低限额无需附加。经营地域范围在其住所所在地以外每增加1个省、自治区"},{"i":9,"n":"第九条","txt":"申请设立非银行支付机构的，申请人应当向住所所在地中国人民银行的分支机构申请，并提交下列材料： （一）书面申请，载明申请人拟设立非银行支付机构的名称、住所、注册资本、拟申请支付业务类型、经营地域范围等。 （二）公司章程草案。 （三）验资证明或者公司资本情况材料。 （四）主要股东、实际控制人材料。 （五）拟任董事、监事和高级管理人员材料。 （六）拟设立非银行支付机构的组织机构设置方案、内部控制制度、风险管理制度、退出预案以及用户合法权益保障机制材料。 （七）支付业务发展规划和可行性研究报告。 （八）反洗钱和反恐怖融资措施材料。 （九）支付业务设施材料。 （十）有符合规定的经营场所材料。 （十一）申请材料真实性声明。"},{"i":10,"n":"第十条","txt":"本细则第九条所称主要股东材料包括： （一）申请人股东关联关系说明材料，以及股权结构和控制框架图。 （二）营业执照（副本）复印件，或者有效身份证件复印件、个人履历。 （三）财务状况和出资情况说明材料，含出资方资金来源说明，以及最近2年经会计师事务所审计的财务会计报告或者个人财务状况说明。 （四）无重大违法违规材料，含最近3年无重大违法违规记录承诺，以及其他能够说明没有因涉嫌重大违法违规正在被调查或者处于整改期间的相关材料。 （五）诚信记录良好材料，含企业或者个人征信报告，以及其他能够说明诚信记录良好的相关材料。 （六）股权稳定性和补充资本承诺书，含主要股东3年内不再变更的承诺，以及非银行支付机构发生风险事件影响其正常运营、损害用户合法权益时，主要股东补充资本的承诺。 主要股东为金融机构的，还应当提供金融业务许可证复印件、准予投资申请人的批复文件或者其他相关材料。"},{"i":11,"n":"第十一条","txt":"本细则第九条所称实际控制人材料包括： （一）申请人实际控制权和控制关系说明材料。 （二）营业执照（副本）复印件，或者有效身份证件复印件、个人履历。 （三）财务状况和出资情况说明材料，含出资方资金来源说明，以及最近2年经会计师事务所审计的财务会计报告或者个人财务状况说明。 （四）无重大违法违规材料，含最近3年无重大违法违规记录承诺，以及其他能够说明没有因涉嫌重大违法违规正在被调查或者处于整改期间的相关材料。 （五）诚信记录良好材料，含企业或者个人征信报告，以及其他能够说明诚信记录良好的相关材料。 （六）股权稳定性承诺书，含实际控制人3年内不再变更的承诺。 实际控制人为自然人的，还应当提交其实际控制的公司最近2年经营情况说明材料、最近2年经会计师事务所审计的财务会计报告或者其他相关材料。 前款所称实际控制的公司，指本条第一款第一项规定的申请人实际控制权和控制关系说明材料中，实际控制人控制的"},{"i":12,"n":"第十二条","txt":"本细则第九条所称董事、监事和高级管理人员材料包括： （一）有效身份证件复印件。 （二）个人履历和相关说明材料。 （三）高级管理人员学历证书复印件。 （四）无重大违法违规材料，含最近3年无重大违法违规记录承诺，以及其他能够说明没有因涉嫌重大违法违规正在被调查或者处于整改期间的相关材料。 （五）诚信记录良好材料，含个人征信报告，以及其他能够说明诚信记录良好的相关材料。 （六）个人承诺书，含对本人（及配偶）是否有大额负债进行说明，并就本人诚信和公正履职、履行反洗钱和反恐怖融资义务等进行承诺。如涉及兼职的，还需提交兼职情况说明和“确保有足够时间和精力有效履行相应职责”的承诺。"},{"i":13,"n":"第十三条","txt":"本细则第九条所称拟设立非银行支付机构的组织机构设置方案应当包含公司治理结构，董事、监事、管理层、各职能部门设置，岗位设置和职责等情况。 内部控制制度是指为合理保证拟设立非银行支付机构经营管理合法合规、资产安全、财务报告和相关信息真实完整而制定的相关制度。 风险管理制度应当包含拟设立非银行支付机构经营过程中的风险分析、风险识别、风险处置等内容。"},{"i":14,"n":"第十四条","txt":"本细则第九条所称支付业务发展规划和可行性研究报告应当包括下列内容： （一）拟从事支付业务的市场前景分析。 （二）拟从事支付业务的处理流程，载明从用户发起支付业务到完成用户委托支付业务各环节的业务内容以及相关资金流转情况。 （三）拟从事支付业务的风险分析和管理措施，并对支付业务各环节分别进行说明。 （四）拟从事支付业务的成本和经济效益分析。 拟申请不同类型支付业务的，应当按照支付业务类型分别提供前款规定内容。"},{"i":15,"n":"第十五条","txt":"本细则第九条所称反洗钱和反恐怖融资措施材料应当包括下列内容： （一）反洗钱内部控制制度文件，载明反洗钱合规管理框架、客户尽职调查和客户身份资料及交易记录保存措施、大额和可疑交易报告措施、反洗钱审计和培训措施、协助反洗钱调查的内部程序、反洗钱工作保密措施。 （二）反洗钱岗位设置和职责说明，载明负责反洗钱工作的内设机构、反洗钱高级管理人员和专职反洗钱工作人员及其联系方式。 （三）开展大额和可疑交易监测的技术条件说明。 （四）洗钱风险自评估制度，《条例》施行前已按照有关规定设立的非银行支付机构还应当提交已完成的洗钱风险自评估报告。"},{"i":16,"n":"第十六条","txt":"本细则第九条所称支付业务设施材料应当包括下列内容： （一）支付业务设施机房部署情况。非银行支付机构生产中心机房原则上应当与非银行支付机构主要经营场所所在地位于同一省、自治区、直辖市。 （二）支付业务设施符合中国人民银行规定的业务规范、技术标准和安全要求说明材料。 未按照中国人民银行规定的业务规范、技术标准和安全要求提供说明材料的，或者说明材料的程序、方法存在重大缺陷的，中国人民银行及其分支机构可以要求申请人重新提交说明材料。"},{"i":17,"n":"第十七条","txt":"本细则第九条所称有符合规定的经营场所材料应当包括住所所有权或者使用权的说明材料，以及经营场所安全的相关材料。"},{"i":18,"n":"第十八条","txt":"申请人申请设立非银行支付机构，应当向住所所在地中国人民银行的分支机构提交申请材料。中国人民银行的分支机构依法受理符合要求的申请，自受理申请之日起初步审查，并将申请材料和初步审查意见报送中国人民银行。中国人民银行自中国人民银行的分支机构受理申请之日起6个月内作出批准或者不予批准的决定。"},{"i":19,"n":"第十九条","txt":"申请人应当自收到受理通知之日起10日内，向住所所在地中国人民银行的分支机构提交公告材料，由中国人民银行的分支机构在其网站上连续公告下列事项20日： （一）拟设立非银行支付机构的注册资本和股权结构。 （二）主要股东名单和持股比例。 （三）实际控制人名单。 （四）拟申请的支付业务类型。 （五）拟设立非银行支付机构的经营场所。 （六）支付业务设施符合中国人民银行规定的业务规范、技术标准和安全要求说明材料。 公告期间，对于社会公众反映的申请人涉嫌提供虚假材料，申请人、主要股东和实际控制人涉嫌违法违规等情形，中国人民银行的分支机构应当进行核查，核查时间不计入审查时限。"},{"i":20,"n":"第二十条","txt":"申请人应当自领取营业执照之日起6个月内开业，并向住所所在地中国人民银行的分支机构报告。申请人自领取营业执照之日起超过6个月未开业的，应当向住所所在地中国人民银行的分支机构报告，说明正当理由和有关情况。"},{"i":21,"n":"第二十一条","txt":"《条例》规定的非银行支付机构变更事项包括： （一）变更主要股东或者实际控制人。 （二）合并或者分立。 （三）跨省、自治区、直辖市变更住所。 （四）变更业务类型或者经营地域范围。 （五）变更董事、监事或者高级管理人员。 （六）变更名称或者注册资本。 非银行支付机构因办理上述变更事项涉及全部支付业务终止的，应当按照本章第三节有关规定办理。"},{"i":22,"n":"第二十二条","txt":"非银行支付机构拟变更本细则第二十一条第一款第一项至第四项事项，以及系统重要性非银行支付机构拟变更本细则第二十一条第一款第五项事项的，应当向中国人民银行的分支机构提交申请，由中国人民银行的分支机构受理、初步审查后报中国人民银行审查、决定。 非银行支付机构拟变更本细则第二十一条第一款第六项事项，以及非系统重要性非银行支付机构拟变更本细则第二十一条第一款第五项事项的，应当向中国人民银行的分支机构提交申请，由中国人民银行的分支机构受理、审查、决定。 非银行支付机构办理本细则第二十一条第一款第一项至第六项事项的，经中国人民银行及其分支机构批准后，依法向市场监督管理部门办理登记手续。"},{"i":23,"n":"第二十三条","txt":"非银行支付机构经查实存在违规经营、规避监管、未按要求落实整改意见，或者因涉嫌违法违规被调查、侦查且尚未结案等其他影响非银行支付机构稳健运行情形的，非银行支付机构应当审慎提交变更申请，依法做好整改，配合调查、侦查直至有关情形消失。 非银行支付机构如需改变中国人民银行的分支机构已受理的变更申请，应当撤回原申请后按本细则要求重新提交变更申请。"},{"i":24,"n":"第二十四条","txt":"非银行支付机构变更主要股东包括下列情形： （一）新增主要股东。 （二）现有主要股东增加或者减少股权比例。"},{"i":25,"n":"第二十五条","txt":"非银行支付机构申请变更主要股东或者实际控制人的，应当符合下列条件： （一）现有主要股东或者实际控制人持股或者实际控制已满3年。现有主要股东改变股权比例且未导致主要股东身份和实际控制人变更，现有主要股东或者实际控制人死亡、丧失完全民事行为能力、执行法院判决、风险处置或者中国人民银行基于审慎监管原则同意再次变更等情形除外。 （二）拟变更后的主要股东或者实际控制人应当符合《条例》及本细则有关规定。拟变更后的主要股东或者实际控制人为公司的，还应当具有稳定的盈利来源或者较好的可持续发展能力。 （三）最近3年无重大违法违规记录。 （四）诚信记录良好。 （五）备付金管理机制健全有效。"},{"i":26,"n":"第二十六条","txt":"非银行支付机构申请变更主要股东或者实际控制人的，应当向住所所在地中国人民银行的分支机构提交下列材料： （一）书面申请，载明申请人基本情况、变更原因、变更方案、变更前后主要股东或者实际控制人情况等。 （二）申请人材料，包括： 1.营业执照（副本）复印件和支付业务许可证复印件。 2.无重大违法违规材料，含最近3年无重大违法违规记录承诺，以及其他能够说明没有因涉嫌重大违法违规正在被调查或者处于整改期间的相关材料。 3.诚信记录良好材料，含企业征信报告，以及其他能够说明诚信记录良好的相关材料。 4.备付金安全承诺。 5.公司合规经营情况说明，含最近3年经营情况、被投诉举报情况、受到行政处罚或者被采取监管措施情况，以及上述相关问题的整改情况。 6.申请人为国有企业、国有控股企业或者上市企业，变更涉及国有资产转让或者上市公司资产交易依法应当取得相关监管部门批准或者备案的，应当提供批准或者备案文件。"},{"i":27,"n":"第二十七条","txt":"《条例》所称合并是指一家非银行支付机构吸收其他非银行支付机构，合并后只有一家非银行支付机构持有支付业务许可证，其他非银行支付机构解散的行为。合并主体可以获取多家被合并主体全部或者部分业务类型和经营地域范围。 非银行支付机构申请合并的，应当由拟合并主体向其住所所在地中国人民银行的分支机构提交合并申请。 非银行支付机构拟跨省、自治区、直辖市进行合并的，拟合并主体住所所在地中国人民银行的分支机构应当征求拟被合并主体住所所在地中国人民银行的分支机构意见，拟被合并主体住所所在地中国人民银行的分支机构应当自收到征求意见函起10日内，向拟合并主体住所所在地中国人民银行的分支机构出具审查意见，审查意见包括但不限于拟被合并主体备付金安全情况和合规经营情况等。"},{"i":28,"n":"第二十八条","txt":"《条例》所称分立是指一家非银行支付机构将部分资产和负债分离转让给其他一家或者多家企业，分立后仅有一家法人主体持有支付业务许可证的行为。 非银行支付机构申请分立的，应当由原非银行支付机构向拟持证主体住所所在地中国人民银行的分支机构提交分立申请。 非银行支付机构拟跨省、自治区、直辖市进行分立的，拟持证主体住所所在地中国人民银行的分支机构应当征求原非银行支付机构住所所在地中国人民银行的分支机构意见，原非银行支付机构住所所在地中国人民银行的分支机构应当自收到征求意见函起10日内，向拟持证主体住所所在地中国人民银行的分支机构出具审查意见，审查意见包括但不限于原非银行支付机构备付金安全情况和合规经营情况等。"},{"i":29,"n":"第二十九条","txt":"非银行支付机构申请合并或者分立的，应当符合下列条件： （一）拟合并主体或者拟持证主体符合《条例》及本细则有关规定。 （二）合并或者分立后股权结构稳定，承诺3年内不再变更主要股东或者实际控制人。主要股东改变股权比例且未导致主要股东身份和实际控制人变更，主要股东或者实际控制人死亡、丧失完全民事行为能力或者存在其他无法继续履行职责，执行法院判决、风险处置或者中国人民银行基于审慎监管原则同意再次变更等情形除外。 （三）具有保障用户合法权益、支付业务连续性的方案和措施。 （四）最近3年无重大违法违规记录。 （五）诚信记录良好。 （六）备付金管理机制健全有效。"},{"i":30,"n":"第三十条","txt":"非银行支付机构申请合并的，应当由拟合并主体向住所所在地中国人民银行的分支机构提交下列材料： （一）书面申请，载明拟合并主体和拟被合并主体的基本情况、变更原因、变更方案等。 （二）拟合并主体和拟被合并主体材料，包括： 1.营业执照（副本）复印件和支付业务许可证复印件。 2.无重大违法违规材料，含最近3年无重大违法违规记录承诺，以及其他能够说明没有因涉嫌重大违法违规正在被调查或者处于整改期间的相关材料。 3.诚信记录良好材料，含企业征信报告，以及其他能够说明诚信记录良好的材料。 4.备付金安全承诺。 5.公司合规经营情况说明，含最近3年经营情况、被投诉举报情况、受到行政处罚或者被采取监管措施情况，以及上述相关问题的整改情况。 6.拟合并主体或者拟被合并主体为国有企业、国有控股企业或者上市企业，变更涉及国有资产转让或者上市公司资产交易依法应当取得相关监管部门批准或者备案的，应当提供批准或者备"},{"i":31,"n":"第三十一条","txt":"非银行支付机构申请分立的，应当向拟持证主体住所所在地中国人民银行的分支机构提交下列材料： （一）书面申请，载明申请人基本情况、变更原因、变更方案等。 （二）申请人相关材料，包括： 1.营业执照（副本）复印件和支付业务许可证复印件。 2.无重大违法违规材料，含最近3年无重大违法违规记录承诺，以及其他能够说明没有因涉嫌重大违法违规正在被调查或者处于整改期间的相关材料。 3.诚信记录良好材料，含企业征信报告，以及其他能够说明诚信记录良好的相关材料。 4.备付金安全承诺。 5.公司合规经营情况说明，含最近3年经营情况、被投诉举报情况、受到行政处罚或者被采取监管措施情况，以及上述相关问题的整改情况。 6.申请人为国有企业、国有控股企业或者上市企业，变更涉及国有资产转让或者上市公司资产交易依法应当取得相关监管部门批准或者备案的，应当提供批准或者备案文件。 （三）股东会或者其他有权决定机构同意申请人"},{"i":32,"n":"第三十二条","txt":"非银行支付机构申请跨省、自治区、直辖市变更住所的，应当向拟变更后住所所在地中国人民银行的分支机构提交申请。拟变更后住所所在地中国人民银行的分支机构应当征求原住所所在地中国人民银行的分支机构意见，原住所所在地中国人民银行的分支机构应当自收到征求意见函起10日内，向拟变更后住所所在地中国人民银行的分支机构出具审查意见，审查意见包括但不限于非银行支付机构备付金安全情况和合规经营情况等。"},{"i":33,"n":"第三十三条","txt":"非银行支付机构申请跨省、自治区、直辖市变更住所的，应当符合下列条件： （一）拟变更后的支付业务设施和住所符合《条例》及本细则有关规定。 （二）非银行支付机构经核准的经营地域范围覆盖变更后的住所所在地。 （三）最近3年无重大违法违规记录。 （四）诚信记录良好。 （五）备付金管理机制健全有效。"},{"i":34,"n":"第三十四条","txt":"非银行支付机构申请跨省、自治区、直辖市变更住所的，应当向拟变更后住所所在地中国人民银行的分支机构提交下列材料： （一）书面申请，载明申请人基本情况、主要股东和实际控制人情况、变更原因、变更方案等。 （二）申请人相关材料，包括： 1.营业执照（副本）复印件和支付业务许可证复印件。 2.无重大违法违规材料，含最近3年无重大违法违规记录承诺，以及其他能够说明没有因涉嫌重大违法违规正在被调查或者处于整改期间的相关材料。 3.诚信记录良好材料，含企业征信报告，以及其他能够说明诚信记录良好的相关材料。 4.备付金安全承诺。 5.公司合规经营情况说明，含最近3年经营情况、被投诉举报情况、受到行政处罚或者被采取监管措施情况，以及上述相关问题的整改情况。 （三）股东会或者其他有权决定机构同意申请人拟变更的决议文件。 （四）拟变更后的支付业务设施和住所合规情况材料，参照本细则第十六条、第十七条规定提供。"},{"i":35,"n":"第三十五条","txt":"非银行支付机构申请变更业务类型或者经营地域范围的，应当向住所所在地中国人民银行的分支机构提交申请。 非银行支付机构拟新增业务类型或者扩大经营地域范围的，应当参照本章第一节有关规定办理。 非银行支付机构拟缩小经营地域范围的，其住所所在地中国人民银行的分支机构应当征求拟不再展业地中国人民银行的分支机构意见，拟不再展业地中国人民银行的分支机构应当自收到征求意见函起10日内，向非银行支付机构住所所在地中国人民银行的分支机构出具审查意见，审查意见包括但不限于非银行支付机构备付金安全和合规经营情况等。"},{"i":36,"n":"第三十六条","txt":"非银行支付机构申请缩减业务类型或者缩小经营地域范围的，应当符合下列条件： （一）具有保障用户合法权益、支付业务连续性的方案和措施。 （二）最近3年无重大违法违规记录。 （三）诚信记录良好。 （四）备付金管理机制健全有效。"},{"i":37,"n":"第三十七条","txt":"非银行支付机构申请缩减业务类型或者缩小经营地域范围的，应当向住所所在地中国人民银行的分支机构提交下列材料： （一）书面申请，载明申请人基本情况、变更原因、变更方案等。 （二）申请人相关材料，包括： 1.营业执照（副本）复印件和支付业务许可证复印件。 2.无重大违法违规材料，含最近3年无重大违法违规记录承诺，以及其他能够说明没有因涉嫌重大违法违规正在被调查或者处于整改期间的相关材料。 3.诚信记录良好材料，含企业征信报告，以及其他能够说明诚信记录良好的相关材料。 4.备付金安全承诺。 5.公司合规经营情况说明，含最近3年经营情况、被投诉举报情况、受到行政处罚或者被采取监管措施情况，以及上述相关问题的整改情况。 （三）股东会或者其他有权决定机构同意申请人拟变更的决议文件。 （四）调整方案和公告，包括业务调整方案和时间安排、用户权益保障、风险控制和舆情应对方案、支付业务信息处理方案、调整公告"},{"i":38,"n":"第三十八条","txt":"非银行支付机构申请变更董事、监事或者高级管理人员的，应当符合下列条件： （一）拟变更后的董事、监事或者高级管理人员符合《条例》及本细则有关规定。 （二）最近3年无重大违法违规记录，中国人民银行及其分支机构根据审慎监管原则，责令非银行支付机构调整董事、监事或者高级管理人员的除外。 （三）诚信记录良好。 （四）备付金管理机制健全有效。 已经中国人民银行及其分支机构批准的非银行支付机构董事、监事在同一非银行支付机构内调任其他董事、监事职位的，或者高级管理人员在同一非银行支付机构内调任其他高级管理人员职位的，非银行支付机构无需提交变更申请，但应当于变更完成后10日内向住所所在地中国人民银行的分支机构报告调任情况。"},{"i":39,"n":"第三十九条","txt":"非银行支付机构申请变更董事、监事或者高级管理人员的，应当向住所所在地中国人民银行的分支机构提交下列材料： （一）书面申请，载明申请人基本情况、变更原因、变更前后人员情况等。 （二）申请人相关材料，包括： 1.营业执照（副本）复印件和支付业务许可证复印件。 2.无重大违法违规材料，含最近3年无重大违法违规记录承诺，以及其他能够说明没有因涉嫌重大违法违规正在被调查或者处于整改期间的相关材料。 3.诚信记录良好材料，含企业征信报告，以及其他能够说明诚信记录良好的相关材料。 4.备付金安全承诺。 5.公司合规经营情况说明，含最近3年经营情况、被投诉举报情况、受到行政处罚或者被采取监管措施情况，以及上述相关问题的整改情况。 （三）股东会或者其他有权决定机构同意申请人拟变更的决议文件。 （四）拟变更后的董事、监事或者高级管理人员资质合规情况材料，参照本细则第十二条规定提供。 （五）申请材料真实性声"},{"i":40,"n":"第四十条","txt":"非银行支付机构申请变更名称的，应当符合下列条件： （一）拟变更后的名称符合《条例》有关规定。 （二）最近3年无重大违法违规记录。 （三）诚信记录良好。 （四）备付金管理机制健全有效。"},{"i":41,"n":"第四十一条","txt":"非银行支付机构申请变更名称的，应当向住所所在地中国人民银行的分支机构提交下列材料： （一）书面申请，载明申请人基本情况、变更原因、拟变更的名称等。 （二）申请人相关材料，包括： 1.营业执照（副本）复印件和支付业务许可证复印件。 2.无重大违法违规材料，含最近3年无重大违法违规记录承诺，以及其他能够说明没有因涉嫌重大违法违规正在被调查或者处于整改期间的相关材料。 3.诚信记录良好材料，含企业征信报告，以及其他能够说明诚信记录良好的相关材料。 4.备付金安全承诺。 5.公司合规经营情况说明，含最近3年经营情况、被投诉举报情况、受到行政处罚或者被采取监管措施情况，以及上述相关问题的整改情况。 （三）股东会或者其他有权决定机构同意申请人拟变更的决议文件。 （四）申请材料真实性声明。"},{"i":42,"n":"第四十二条","txt":"非银行支付机构申请变更注册资本的，应当符合下列条件： （一）拟变更后的注册资本符合《条例》及本细则有关规定。 （二）因注册资本变更导致非银行支付机构主要股东和实际控制人变更的，拟变更后的主要股东和实际控制人符合《条例》及本细则有关规定。 （三）最近3年无重大违法违规记录。 （四）诚信记录良好。 （五）备付金管理机制健全有效。"},{"i":43,"n":"第四十三条","txt":"非银行支付机构申请变更注册资本的，应当向住所所在地中国人民银行的分支机构提交下列材料： （一）书面申请，载明申请人基本情况、变更原因、变更方案、变更前后注册资本和股权结构情况等。 （二）申请人相关材料，包括： 1.营业执照（副本）复印件和支付业务许可证复印件。 2.无重大违法违规材料，含最近3年无重大违法违规记录承诺，以及其他能够说明没有因涉嫌重大违法违规正在被调查或者处于整改期间的相关材料。 3.诚信记录良好材料，含企业征信报告，以及其他能够说明诚信记录良好的相关材料。 4.备付金安全承诺。 5.公司合规经营情况说明，含最近3年经营情况、被投诉举报情况、受到行政处罚或者被采取监管措施情况，以及上述相关问题的整改情况。 （三）股东会或者其他有权决定机构同意申请人拟变更的决议文件。 （四）拟增加注册资本的，应当提供资金来源说明。 （五）申请材料真实性声明。"},{"i":44,"n":"第四十四条","txt":"非银行支付机构同时涉及多项变更事项的，应当按照《条例》及本细则有关规定一次性提出申请。多项变更事项涉及相同申请材料的，非银行支付机构无需重复提交。 多项变更事项同时涉及由中国人民银行和中国人民银行的分支机构决定的，由中国人民银行的分支机构受理、初步审查后报中国人民银行审查、决定。"},{"i":45,"n":"第四十五条","txt":"非银行支付机构申请变更本细则第二十一条第一款第一项至第四项事项，系统重要性非银行支付机构申请变更本细则第二十一条第一款第五项事项的，中国人民银行的分支机构应当自受理申请之日起初步审查，并将非银行支付机构变更申请材料、行政许可受理通知书和初步审查意见报送中国人民银行。中国人民银行自中国人民银行的分支机构受理申请之日起3个月内作出批准或者不予批准的决定。 非系统重要性非银行支付机构申请变更本细则第二十一条第一款第五项事项的，中国人民银行的分支机构应当自受理申请之日起3个月内作出批准或者不予批准的决定，并及时将决定抄报中国人民银行。 非银行支付机构申请变更本细则第二十一条第一款第六项事项的，中国人民银行的分支机构应当自受理申请之日起1个月内作出批准或者不予批准的决定，并及时将决定抄报中国人民银行。 非银行支付机构同时涉及多项变更事项的，适用较长审查期限。"},{"i":46,"n":"第四十六条","txt":"非银行支付机构应当根据准予行政许可决定及时办理变更事项，于变更完成后10日内向中国人民银行的分支机构书面报告完成情况。 非银行支付机构未能根据准予行政许可决定在90日内办理变更事项的，应当将未变更原因、后续工作安排等情况书面报告中国人民银行的分支机构。未书面报告或者报告理由不充分的，中国人民银行的分支机构可以区别不同情形采取约谈、责令整改等措施。"},{"i":47,"n":"第四十七条","txt":"非银行支付机构申请终止支付业务的，应当向住所所在地中国人民银行的分支机构提交下列材料： （一）书面申请，载明公司基本情况、支付业务开展情况、拟终止支付业务类型和终止原因等。 （二）营业执照（副本）复印件和支付业务许可证复印件。 （三）股东会或者其他有权决定机构同意申请人拟终止支付业务的决议文件。 （四）支付业务终止方案。 中国人民银行的分支机构依法受理符合要求的申请，自受理申请之日起20日内初步审查完毕，并将申请材料和初步审查意见报送中国人民银行。中国人民银行自收到中国人民银行的分支机构报送的申请材料和初步审查意见之日起20日内，作出批准或者不予批准的决定。准予终止的，非银行支付机构应当按相关规定完成支付业务终止工作，交回支付业务许可证。"},{"i":48,"n":"第四十八条","txt":"本细则第四十七条所称支付业务终止方案应当包括下列内容： （一）支付业务终止整体安排。 （二）支付业务的资金和信息承接方情况，以及申请人与承接方关联关系说明。 （三）支付业务终止公告内容和公告方式。 （四）用户合法权益保障方案。 （五）支付业务信息处理方案。 （六）重大和突发事件应急预案。 （七）与承接方签订的支付业务信息、用户身份资料和交易记录移交协议，备付金承接协议。 用户合法权益保障方案应当包含对用户知情权、隐私权和选择权的保护措施，明确告知用户终止支付业务的原因、停止受理用户委托支付业务的时间、拟终止支付业务的后续安排；明确用户身份资料和交易记录的接收机构、移交安排、销毁方式和监督安排；明确备付金处理方案。 支付业务信息处理方案，应当明确支付业务信息的接收机构、移交安排、销毁方式和监督安排。"},{"i":49,"n":"第四十九条","txt":"非银行支付机构应当在经营场所显著位置公示支付业务许可证原件。非银行支付机构有官方网站的，还应当在官方网站主页显著位置公示其支付业务许可证的影像信息。 非银行支付机构分支机构应当在经营场所显著位置公示加盖法人公章的支付业务许可证复印件。"},{"i":50,"n":"第五十条","txt":"支付业务许可证因不可抗力灭失、损毁的，非银行支付机构应当自其确认支付业务许可证灭失、损毁之日起10日内，采取下列一种或者多种方式连续公告3日： （一）在住所所在地省级有影响力的报刊上公告。 （二）在非银行支付机构官方网站上公告。 （三）其他有效便捷的公告方式。 公告发出日期以最后张贴或者刊登日期为准。公告的具体内容应当包括公告事由、机构名称、住所、联系电话、声明原支付业务许可证作废等。公告的知晓范围应当至少覆盖非银行支付机构的经营地域范围。"},{"i":51,"n":"第五十一条","txt":"非银行支付机构应当自公告支付业务许可证灭失、损毁结束之日起10日内持已公告材料向住所所在地中国人民银行的分支机构重新申领支付业务许可证。 中国人民银行的分支机构自收到申请材料之日起10日内完成初步审核，并将申请材料和初步审核意见报送中国人民银行。中国人民银行自收到中国人民银行的分支机构报送的相关材料之日起20日内为非银行支付机构补发支付业务许可证。"},{"i":52,"n":"第五十二条","txt":"非银行支付机构支付业务许可证要素发生变化的，应当向住所所在地中国人民银行的分支机构申请换发支付业务许可证。 中国人民银行的分支机构自收到申请材料之日起10日内完成初步审核，并将申请材料和初步审核意见报送中国人民银行。中国人民银行自收到中国人民银行的分支机构报送的相关材料之日起20日内为非银行支付机构换发支付业务许可证。"},{"i":53,"n":"第五十三条","txt":"非银行支付机构根据《条例》第十二条设立分支机构的，应当分别向非银行支付机构法人及其分支机构住所所在地中国人民银行的分支机构备案，并提交下列材料： （一）非银行支付机构法人的法定代表人签署的书面报告，包括分支机构名称、公司治理架构、拟从事的支付业务类型等。 （二）加盖法人公章的支付业务许可证复印件。 （三）分支机构营业执照（副本）复印件。 （四）分支机构住所和管理人员相关材料。 非银行支付机构分支机构备案材料发生变更的，应当在变更完成后10日内向法人及其分支机构住所所在地中国人民银行的分支机构更换备案材料。 非银行支付机构分支机构拟在其备案地终止已备案的所有或者部分支付业务的，应当于终止支付业务前向法人和分支机构住所所在地中国人民银行的分支机构报告。"},{"i":54,"n":"第五十四条","txt":"本细则对行政许可程序未作规定的事项，适用法律、行政法规和中国人民银行关于行政许可的相关规定。"},{"i":55,"n":"第五十五条","txt":"《条例》所称储值账户运营分为储值账户运营Ⅰ类和储值账户运营Ⅱ类；支付交易处理分为支付交易处理Ⅰ类和支付交易处理Ⅱ类。 （一）原《非金融机构支付服务管理办法》规定的互联网支付，或者同时开展原《非金融机构支付服务管理办法》规定的互联网支付和移动电话支付（固定电话支付、数字电视支付）的，归入储值账户运营Ⅰ类。支付业务许可证登记的业务类型对应调整为储值账户运营Ⅰ类。 （二）原《非金融机构支付服务管理办法》规定的预付卡发行与受理、预付卡受理归入储值账户运营Ⅱ类，经营地域范围不变。支付业务许可证登记的业务类型对应调整为储值账户运营Ⅱ类（经营地域范围）、储值账户运营Ⅱ类（仅限于线上实名支付账户充值）、储值账户运营Ⅱ类（仅限于经营地域范围预付卡受理）。 （三）原《非金融机构支付服务管理办法》规定的银行卡收单归入支付交易处理Ⅰ类，经营地域范围不变。支付业务许可证登记的业务类型对应调整为支付交易处理Ⅰ类（"},{"i":56,"n":"第五十六条","txt":"《条例》所称合规管理制度、内部控制制度、业务管理制度、风险管理制度应当全面、完整反映法律、行政法规、中国人民银行规章和规范性文件的监管规定。"},{"i":57,"n":"第五十七条","txt":"《条例》所称突发事件应急预案应当包括下列内容： （一）支付业务系统连续性保障应急预案。 （二）备付金风险应急预案。 （三）用户信息泄露风险应急预案。 （四）其他可能危及非银行支付机构正常经营，损害用户合法权益的风险事件应急预案。"},{"i":58,"n":"第五十八条","txt":"《条例》所称用户权益保障机制，是指保障用户财产安全权、知情权、自主选择权、公平交易权、受尊重权、信息安全权等基本权利的内控制度和工作机制。 用户权益保障机制包括用户信息安全保护机制、重要信息披露机制、投诉处理机制、损失赔付机制、支付业务终止过程中用户权益保障方案等。 中国人民银行及其分支机构按照法定职责和监管权限依法接收转办或者办理非银行支付机构用户投诉、信访、举报事项。"},{"i":59,"n":"第五十九条","txt":"根据《条例》第二十八条，非银行支付机构净资产最低限额以备付金日均余额为计算依据，采取超额累退方式按照下列标准确定： （一）备付金日均余额不超过500亿元人民币的部分，按照5%计算。 （二）备付金日均余额超过500亿元人民币至2000亿元人民币的部分，按照4%计算。 （三）备付金日均余额超过2000亿元人民币至5000亿元人民币的部分，按照3%计算。 （四）备付金日均余额超过5000亿元人民币至10000亿元人民币的部分，按照2%计算。 （五）备付金日均余额超过10000亿元人民币的部分，按照1%计算。 非银行支付机构净资产最低限额应当不低于按照本条第一款第一项至第五项规定计算的加总值。 中国人民银行可以根据支付市场发展实际，动态调整前款比例的具体数值。"},{"i":60,"n":"第六十条","txt":"系统重要性非银行支付机构应当根据中国人民银行有关规定，结合业务规模等因素，满足附加要求。 系统重要性非银行支付机构管理办法由中国人民银行另行制定。"},{"i":61,"n":"第六十一条","txt":"非银行支付机构应当对用户身份资料自业务关系结束后或者一次性交易结束后至少保存5年，对交易记录自交易结束后至少保存5年。 司法机关正在调查的可疑交易或者违法犯罪活动涉及用户身份资料和交易记录，且相关调查工作在前款规定的最低保存期届满时仍未结束的，非银行支付机构应当将其保存至调查工作结束。 法律、行政法规对用户身份资料和交易记录有更长保存期限要求的，从其规定。"},{"i":62,"n":"第六十二条","txt":"非银行支付机构调整支付业务的收费项目或者收费标准的，原则上应当至少于调整施行前30个自然日，在经营场所、官方网站、公众号等醒目位置，业务办理途径的关键节点，对新的支付业务收费项目或者收费标准进行持续公示，在办理相关业务前确认用户知悉、接受调整后的收费项目或者收费标准，做好协议换签或者补签等相关工作，并保留用户同意的记录。"},{"i":63,"n":"第六十三条","txt":"《条例》第四十一条、第四十三条所列事项报告程序和要求适用中国人民银行关于非银行支付机构重大事项报告、网络安全风险和事件报告管理的有关规定。"},{"i":64,"n":"第六十四条","txt":"非银行支付机构变更法定代表人、住所（同省、自治区、直辖市）、公司章程的，应当在变更完成后10日内向住所所在地中国人民银行的分支机构报告。报告材料包括变更报告、变更后的公司章程和营业执照（副本）复印件等。 非银行支付机构变更受益所有人的，应当在变更完成后10日内向住所所在地中国人民银行的分支机构报告。 上市非银行支付机构变更非主要股东的，应当于每季度初10日内向住所所在地中国人民银行的分支机构报告。其他非银行支付机构变更非主要股东的，应当在变更完成后10日内向住所所在地中国人民银行的分支机构报告。 非银行支付机构应当对变更事项的合法性、真实性、有效性负责，积极配合中国人民银行的分支机构开展股权穿透式监管，不得瞒报、虚报、漏报。中国人民银行的分支机构对非银行支付机构变更事项存在疑问的，可以要求非银行支付机构补充说明。"},{"i":65,"n":"第六十五条","txt":"中国人民银行的分支机构应当加强属地管理，对非银行支付机构股权实施持续监管和穿透式监管，及时掌握对非银行支付机构经营管理可能产生重大影响的非主要股东或者受益所有人变化情况，防范非主要股东或者受益所有人通过一致行动安排等方式规避监管。"},{"i":66,"n":"第六十六条","txt":"中国人民银行及其分支机构应当加强非银行支付机构行政许可事项办理过程记录，完善非银行支付机构行政许可事项案卷管理制度，妥善保存非银行支付机构行政许可材料、审查记录、核实记录和相关证据材料等。"},{"i":67,"n":"第六十七条","txt":"中国人民银行及其分支机构按照中国人民银行关于执法检查的相关规定，依法对非银行支付机构实施现场检查和非现场检查。"},{"i":68,"n":"第六十八条","txt":"《条例》所称擅自设立非银行支付机构、从事或者变相从事支付业务，是指未经中国人民银行批准，根据用户提交的电子支付指令转移货币资金等情形，以及中国人民银行在有关业务规则中认定的其他情形。"},{"i":69,"n":"第六十九条","txt":"非银行支付机构违反《条例》有关规定的，中国人民银行及其分支机构可以依据《条例》进行处罚。"},{"i":70,"n":"第七十条","txt":"未经依法批准，擅自设立非银行支付机构、从事或者变相从事支付业务的，中国人民银行指导中国人民银行的分支机构依法予以取缔。中国人民银行及其分支机构可以依据《条例》进行处罚。涉嫌构成犯罪的，依法移送司法机关追究刑事责任。"},{"i":71,"n":"第七十一条","txt":"非银行支付机构主要股东、控股股东、实际控制人违反《条例》有关规定的，中国人民银行及其分支机构可以依据《条例》进行处罚。"},{"i":72,"n":"第七十二条","txt":"非银行支付机构违反本细则第五十九条规定的，中国人民银行及其分支机构可以依据《条例》第四十九条第二项规定进行处罚。"},{"i":73,"n":"第七十三条","txt":"《条例》施行前已按照有关规定设立的非银行支付机构，应当在过渡期结束前达到《条例》及本细则关于非银行支付机构设立条件以及净资产与备付金日均余额比例的规定。其他规定自本细则施行之日起执行。 各非银行支付机构的过渡期为本细则施行之日至其支付业务许可证有效期截止日，过渡期不满12个月的，按12个月计。"},{"i":74,"n":"第七十四条","txt":"《条例》施行之日起，各类支付业务规则暂沿用预付卡、网络支付、条码支付、银行卡收单等现行制度规定。中国人民银行现行制度文件中涉及非银行支付机构支付业务类型的有关规定，按本细则第五十五条规定的对应关系调整后执行。"},{"i":75,"n":"第七十五条","txt":"《条例》所称主要股东，是指出资额占非银行支付机构资本总额10%以上或者其持有的股份占非银行支付机构股本总额10%以上的股东；以及出资额或者持有股份的比例虽然不足10%，但对非银行支付机构经营管理有重大影响的股东。 前款所称重大影响，包括通过协议，向非银行支付机构派驻董事、监事或者高级管理人员，或者以其他方式影响非银行支付机构的财务和经营管理决策，以及中国人民银行认定的其他情形。 本细则中的“日”均为工作日，“月”均为自然月，“以上”均含本数或者本级。 本细则所称合并主体，是指整体承接其他一家或者多家非银行支付机构支付业务并继续持有支付业务许可证的非银行支付机构。 本细则所称被合并主体，是指合并后注销支付业务许可证并解散的非银行支付机构。 本细则所称持证主体，是指分立后持有支付业务许可证并继续开展支付业务的非银行支付机构。 本细则所称净资产，是指非银行支付机构经会计师事务所审计的财务会计"},{"i":76,"n":"第七十六条","txt":"本细则由中国人民银行解释。"},{"i":77,"n":"第七十七条","txt":"本细则自发布之日起施行。《非金融机构支付服务管理办法》（中国人民银行令〔2010〕第2号发布）、《非金融机构支付服务管理办法实施细则》（中国人民银行公告〔2010〕第17号公布）同时废止。"}],"huangjinjihuangjinzhipinjinchukouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范黄金及黄金制品进出口行为，加强黄金及黄金制品进出口管理，根据《中华人民共和国中国人民银行法》、《中华人民共和国海关法》和《国务院对确需保留的行政审批项目设定行政许可的决定》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称黄金是指未锻造金，黄金制品是指半制成金和金制成品等。"},{"i":3,"n":"第三条","txt":"中国人民银行是黄金及黄金制品进出口主管部门，对黄金及黄金制品进出口实行准许证制度。 中国人民银行根据国家宏观经济调控需求，可以对黄金及黄金制品进出口的数量进行限制性审批。 列入《黄金及黄金制品进出口管理目录》的黄金及黄金制品进口或出口通关时，应当向海关提交中国人民银行及其分支机构签发的《中国人民银行黄金及黄金制品进出口准许证》（附１）。 中国人民银行会同海关总署制定、调整并公布《黄金及黄金制品进出口管理商品目录》。"},{"i":4,"n":"第四条","txt":"法人、其他组织以下列贸易方式进出口黄金及黄金制品的，应当按照本办法办理《中国人民银行黄金及黄金制品进出口准许证》： （一）一般贸易； （二）加工贸易转内销及境内购置黄金原料以加工贸易方式出口黄金制品的； （三）海关特殊监管区域、保税监管场所与境内区外之间进出口的。 个人、法人或者其他组织因公益事业捐赠进口黄金及黄金制品的，应当按照本办法办理《中国人民银行黄金及黄金制品进出口准许证》。 个人携带黄金及黄金制品进出境的管理规定，由中国人民银行会同海关总署制定。"},{"i":5,"n":"第五条","txt":"国家黄金储备进出口由中国人民银行办理。 金质铸币（包括金质贵金属纪念币）进出口由中国人民银行指定机构办理。"},{"i":6,"n":"第六条","txt":"获得黄金进出口资格的市场主体应当承担平衡国内黄金市场实物供求的责任，进出口黄金应当在国务院批准的黄金现货交易所内登记，并完成初次交易。"},{"i":7,"n":"第七条","txt":"黄金进出口和公益事业捐赠黄金制品进口申请由中国人民银行受理和审批。 黄金制品进出口申请由中国人民银行地市级以上分支机构受理，中国人民银行上海总部，各分行、营业管理部、省会（首府）城市中心支行，深圳市中心支行审批。"},{"i":8,"n":"第八条","txt":"申请黄金进出口（除因公益事业捐赠进口黄金）的，应当具备法人资格，近２年内无相关违法违规行为，并且具备下列条件之一： （一）是国务院批准的黄金交易所的金融机构会员或做市商，具备黄金业务专业人员、完善的黄金业务风险控制制度和稳定的黄金进出口渠道，所开展的黄金市场业务符合相关政策或管理规定，并且申请前两个年度黄金现货交易活跃、自营交易量排名前列； （二）是国务院批准的黄金交易所的综合类会员，年矿产金10吨以上、其生产过程中的污染物排放达到国家环保标准，在境外黄金矿产投资规模达5000万美元以上，取得境外金矿或者共生、伴生金矿开采权，已形成矿产金生产能力，所开展的业务符合国内外相关政策或管理规定，申请前两个年度黄金现货交易活跃，自营交易量排名前列的矿产企业； （三）在国内有连续３年且每年不少于２亿元人民币的纳税记录，在境外有色金属投资１亿美元以上，取得境外金矿或共生、伴生金矿开采权，已形成矿产"},{"i":9,"n":"第九条","txt":"申请黄金制品进出口（除因公益事业捐赠进口黄金制品）的，应当具备法人或其他组织资格，近２年内无相关违法违规行为，并且具备下列条件之一： （一）生产、加工或者使用相关黄金制品的企业，有必要的生产场所、设备和设施，生产过程中的污染物排放达到国家环保标准，有连续３年且年均不少于100万元人民币的纳税记录； （二）适用海关认证企业管理的外贸经营企业，有连续３年且年均不少于300万元人民币的纳税记录； （三）因国家科研项目、重点课题需要使用黄金制品的教育机构、科学研究机构等。"},{"i":10,"n":"第十条","txt":"申请黄金进出口的，应当向中国人民银行提交下列材料： （一）书面申请，应当载明申请人的名称、住所（办公场所）、企业概况、进出口黄金的用途和计划数量等业务情况说明； （二）《黄金及黄金制品进出口申请表》（附２）； （三）加盖公章的企业法人营业执照复印件； （四）黄金进出口合同及其复印件； （五）加盖公章的《中华人民共和国组织机构代码证》复印件； （六）申请人近２年有无违法行为的说明材料； （七）银行业金融机构还应当提供内部黄金业务风险控制制度有关材料；申请出口黄金的还应当提交在国务院批准的黄金现货交易所实物黄金库存量证明； （八）黄金矿产的生产企业还应当提交省级环保部门出具的污染物排放许可证件和年度达标检测报告复印件、商务部门有关境外投资批复文件复印件、银行汇出汇款证明书复印件，境外国家或者地区开釆黄金有关证明，企业近３年的纳税记录，申请出口黄金的还应当提交由行业主管部门或自律组织出具的黄"},{"i":11,"n":"第十一条","txt":"申请黄金制品进出口的，应当向申请人住所地的中国人民银行地市级以上分支机构提交下列材料： （一）书面申请，应当载明申请人的名称、住所（办公场所）、企业概况、进出口黄金制品的用途和计划数量等业务情况说明； （二）《黄金及黄金制品进出口申请表》； （三）加盖公章的企业法人营业执照、事业单位法人证书等法定登记证书复印件； （四）黄金制品进出口合同复印件； （五）加盖备案登记章的《对外贸易经营者备案表》或《外商投资企业批准证书》； （六）申请人近２年有无违法行为的说明材料； （七）生产、加工或者使用黄金制品的企业还应当提交近３年的企业纳税记录，地市级环保部门出具的污染物排放许可证件和年度达标检测报告及其复印件； （八）从事外贸经营的企业还应当提交适用海关认证企业管理的有关证明材料、近３年的企业纳税记录； （九）教育机构、科学研究机构还应当提交承担国家科研项目、重点课题的证明材料； （十）出口黄金"},{"i":12,"n":"第十二条","txt":"加工贸易因故转内销的黄金制品、转内销商品中进口料件是《黄金及黄金制品进出口管理目录》范围内商品的、在境内购置黄金原料以加工贸易方式出口黄金制品的，适用本办法第九条第一项规定的申请条件。 因加工贸易转内销的，应当按照本办法第十一条规定报送申请材料，同时，还应当提交有正当理由需要转内销的说明材料、加工贸易业务批准证复印件、加工贸易合同等材料及其复印件。 境内购置黄金原料以加工贸易方式出口黄金制品的，企业应当在加工贸易手册设立（变更）时向海关申报境内购置黄金情况，并提交《中国人民银行黄金及黄金制品进出口准许证》。"},{"i":13,"n":"第十三条","txt":"个人、法人或者其他组织因公益事业捐赠进口黄金及黄金制品的，应当由受赠人向中国人民银行提交下列材料： （一）符合《中华人民共和国公益事业捐赠法》规定的捐赠协议； （二）事业单位法人证书或社会团体法人登记证书等法定登记证书及其复印件； （三）《黄金及黄金制品进出口申请表》。"},{"i":14,"n":"第十四条","txt":"中国人民银行应当自受理黄金及黄金制品进出口申请之日起20个工作日内做出行政许可决定。"},{"i":15,"n":"第十五条","txt":"中国人民银行地市级分支机构应当自受理黄金制品进出口申请之日起20个工作日内将初步审查意见和全部申请材料直接报送上一级机构。上一级机构应当在收到初步审查意见和全部申请材料后20个工作日内做出行政许可决定。 中国人民银行上海总部，各分行、营业管理部、省会（首府）城市中心支行，深圳市中心支行直接受理黄金制品进出口申请的，应当自受理之日起20个工作日内做出行政许可决定。"},{"i":16,"n":"第十六条","txt":"需要对申请材料的实质内容进行核实的，中国人民银行及其分支机构可以对申请人进行核查，核查应当由两名以上工作人员进行。"},{"i":17,"n":"第十七条","txt":"被许可人在办理黄金及黄金制品货物进出口时，凭《中国人民银行黄金及黄金制品进出口准许证》向海关办理有关手续。 《中国人民银行黄金及黄金制品进出口准许证》实行一批一证，自签发日起40个工作日内使用。被许可人有正当理由需要延期的，可以在凭证有效期届满５个工作曰前持原证向发证机构申请办理一次延期手续。"},{"i":18,"n":"第十八条","txt":"中国人民银行及其分支机构有权对被许可人从事行政许可事项的活动进行监督检查，被许可人应当予以配合。"},{"i":19,"n":"第十九条","txt":"被许可人应当按照中国人民银行及其分支机构的规定，及时上报黄金及黄金制品进出口许可的执行情况并且提供有关材料。"},{"i":20,"n":"第二十条","txt":"除本办法第四条规定外，以下方式进出的黄金及黄金制品免予办理《中国人民银行黄金及黄金制品进出口准许证》，由海关实施监管： （一）通过加工贸易方式进出的； （二）海关特殊监管区域、保税监管场所与境外之间进出的； （三）海关特殊监管区域、保税监管场所之间进出的； （四）以维修、退运、暂时进出境方式进出境的。"},{"i":21,"n":"第二十一条","txt":"除本办法第四条、第五条和第二十条规定之外，个人、法人和其他组织不得以其他任何方式进出口黄金及黄金制品。国家另有规定的除外。"},{"i":22,"n":"第二十二条","txt":"个人、法人和其他组织进出口黄金及黄金制品应当遵守国家反洗钱和反恐怖融资有关规定。"},{"i":23,"n":"第二十三条","txt":"黄金及黄金制品进出口发生的外汇收支，应当按照外汇管理规定办理。"},{"i":24,"n":"第二十四条","txt":"被许可人不得有下列行为： （一）转让、出借黄金及黄金制品进出口证件； （二）使用伪造、变造的黄金及黄金制品进出口证件； （三）骗取或者釆用其他不正当手段获取黄金及黄金制品进出口证件； （四）超越进出口行政许可品种、规格、数量范围； （五）虚假捐赠进口黄金及黄金制品； （六）进口黄金未按照规定在黄金现货交易所登记、交易； （七）以囤积居奇等方式恶意操纵黄金交易价格，或有欺诈等其他侵犯投资者权益行为； （八）违反黄金市场及黄金衍生品交易相关政策或管理规定； （九）拒绝中国人民银行及其分支机构监督检查，或者在监督检查过程中隐瞒有关情况、提供虚假材料。 被许可人有前款所列行为之一的，中国人民银行及其分支机构可以暂停受理其进出口申请；情节严重的，按照《中华人民共和国中国人民银行法》第四十六条规定予以处罚。"},{"i":25,"n":"第二十五条","txt":"中国人民银行及其分支机构可以依法撤销被许可人的黄金及黄金制品进出口证件。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定进出口黄金及黄金制品，构成走私行为或者违反海关监管规定等违法行为的，由海关依照《中华人民共和国海关法》、《中华人民共和国海关行政处罚实施条例》等法律法规处理；构成犯罪的，依法移交司法机关追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"本办法由中国人民银行、海关总署负责解释。"},{"i":28,"n":"第二十八条","txt":"本办法自2015年4月1日起施行。"}]};
